from __future__ import annotations
import math
import random
import itertools
from typing import List, Tuple
import numpy as np
try:
    from scipy.optimize import minimize
except ImportError:
    minimize = None

SQRT3 = math.sqrt(3.0)
_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    best = float("inf")
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best < 1e-6:  # Early exit for degenerate cases
                        return best
    return best

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        s = u + v
        u /= s
        v /= s
    return (1 - u - v) * _A + u * _B + v * _C

def _initial_configuration(n_pts: int) -> np.ndarray:
    pts = []
    layers = int(math.sqrt(n_pts)) + 1
    for i in range(layers):
        for j in range(layers - i):
            u = (i + 0.5) / layers
            v = (j + 0.5) / layers
            if len(pts) < n_pts and u + v <= 1.0:
                pts.append((1 - u - v) * _A + u * _B + v * _C)
    while len(pts) < n_pts:
        pts.append(_random_point())
    return np.array(pts)

def _anneal(n_pts: int = 11, iters: int = 5000, restarts: int = 3, seed: int = 0) -> np.ndarray:
    rng = random.Random(seed)
    best_pts = None
    best_val = 0.0

    for _ in range(restarts):
        pts = _initial_configuration(n_pts)
        current_val = _min_triangle_area(pts)

        for t in range(iters):
            T = max(0.01, 0.1 * (1 - t/iters))
            step_size = 0.05 * T

            idx = rng.randrange(n_pts)
            trial = pts.copy()
            trial[idx] += rng.uniform(-step_size, step_size), rng.uniform(-step_size, step_size)
            trial[idx] = _project_to_simplex(trial[idx])

            trial_val = _min_triangle_area(trial)
            delta = trial_val - current_val

            if delta > 0 or rng.random() < math.exp(delta / max(T, 1e-12)):
                pts = trial
                current_val = trial_val

                if current_val > best_val:
                    best_val = current_val
                    best_pts = pts.copy()

    return best_pts

def _local_polish(pts: np.ndarray) -> np.ndarray:
    if minimize is None:
        return pts
    n_pts = len(pts)
    x0 = pts.ravel()

    def f(x: np.ndarray) -> float:
        P = x.reshape((-1, 2))
        return -_min_triangle_area(P)

    res = minimize(f, x0, method='Nelder-Mead', options={'maxiter': 1000})
    if res.success:
        out = res.x.reshape((n_pts, 2))
        for i in range(n_pts):
            out[i] = _project_to_simplex(out[i])
        return out
    return pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=5000, restarts=3, seed=seed)
    pts = _local_polish(pts)
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

from __future__ import annotations

import math
import random
import itertools
from typing import List, Tuple
import numpy as np
try:
    from scipy.optimize import minimize
except ImportError:
    minimize = None

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    best = float("inf")
    for i, j, k in itertools.combinations(range(len(pts)), 3):
        a = _area(pts[i], pts[j], pts[k])
        if a < best:
            best = a
            if best < 1e-6:
                return best
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    w = 1.0 - u - v
    if u >= 0 and v >= 0 and w >= 0:
        return p
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _initial_configuration(n_pts: int) -> np.ndarray:
    pts = []
    for i in range(n_pts):
        u = (i + 0.5) / n_pts
        for j in range(int(math.sqrt(n_pts)) + 1):
            v = (j + 0.5) / (int(math.sqrt(n_pts)) + 1)
            if u + v <= 1.0 and len(pts) < n_pts:
                pts.append((1 - u - v) * _A + u * _B + v * _C)
    while len(pts) < n_pts:
        pts.append(_random_point())
    return np.array(pts)

def _anneal(n_pts: int = 11, iters: int = 50000, seed: int = 0) -> np.ndarray:
    rng = random.Random(seed)
    pts = _initial_configuration(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        T = max(0.001, 0.1 * (1 - t/iters))
        idx = rng.randrange(n_pts)
        trial = pts.copy()
        step = 0.05 * (1 - t/iters)
        angle = rng.uniform(0, 2*math.pi)
        dx = step * math.cos(angle)
        dy = step * math.sin(angle)
        trial[idx] += dx, dy
        trial[idx] = _project_to_simplex(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or rng.random() < math.exp(delta / max(T, 1e-12)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

        if t % 1000 == 0:
            pts = best_pts.copy()

    return best_pts

def _local_polish(pts: np.ndarray) -> np.ndarray:
    if minimize is None:
        return pts
    n_pts = len(pts)
    x0 = pts.ravel()
    def f(x: np.ndarray) -> float:
        P = x.reshape((-1, 2))
        return -_min_triangle_area(P)
    res = minimize(f, x0, method='Nelder-Mead', 
                  options={'maxiter': 2000, 'fatol': 1e-8, 'xatol': 1e-8})
    if res.success:
        out = res.x.reshape((n_pts, 2))
        for i in range(n_pts):
            out[i] = _project_to_simplex(out[i])
        return out
    return pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=30000, seed=seed)
    pts = _local_polish(pts)
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

import math
import random
import itertools
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    best = float("inf")
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _hexagonal_grid(n: int) -> List[np.ndarray]:
    points = []
    size = int(math.ceil(math.sqrt(n * 2 / SQRT3)))
    for i in range(size):
        for j in range(size):
            if len(points) >= n:
                break
            x = (i + 0.5 * (j % 2)) / size
            y = j * SQRT3 / (2 * size)
            if y <= SQRT3 * (1 - x) and y <= SQRT3 * x:
                points.append(np.array([x, y]))
    while len(points) < n:
        points.append(_random_point())
    return points[:n]

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    w = 1.0 - u - v
    if u >= 0 and v >= 0 and w >= 0:
        return p
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _optimize(pts: np.ndarray, iterations: int = 1000) -> np.ndarray:
    n = len(pts)
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)

    for _ in range(iterations):
        temp = 1.0 - (_ / iterations)
        step = 0.1 * temp

        new_pts = best_pts.copy()
        for i in range(n):
            if random.random() < 0.7:
                new_pts[i] += np.random.uniform(-step, step, 2)
                new_pts[i] = _project_to_simplex(new_pts[i])

        new_area = _min_triangle_area(new_pts)
        if new_area > best_area or (temp > 0 and 
           random.random() < math.exp((new_area - best_area)/temp)):
            best_pts = new_pts.copy()
            best_area = new_area

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _hexagonal_grid(11)
    pts = _optimize(np.array(pts), 2000)

    return [(float(x), float(y)) for x, y in pts]

