                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

def _hexagonal_grid(n: int) -> np.ndarray:
    pts = []
    size = int(math.ceil(math.sqrt(n * 2)))
    for i in range(size):
        for j in range(size):
            if len(pts) >= n:
                break
            x = 0.5 + (i - j) * 0.5 / (size-1)
            y = j * SQRT3 / 2 / (size-1)
            if _is_inside_triangle(x, y):
                pts.append([x, y])
    while len(pts) < n:
        x = random.uniform(0.1, 0.9)
        y = random.uniform(0.1, 0.8)
        if _is_inside_triangle(x, y):
