from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> Tuple[float, List[int]]:
    n = len(pts)
    best = float("inf")
    best_indices = [0, 1, 2]
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    best_indices = [i, j, k]
                    if best == 0:
                        return (0, best_indices)
    return (best, best_indices)

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    w = 1.0 - u - v
    if u >= 0 and v >= 0 and w >= 0:
        return p
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        s = u + v
        u /= s
        v /= s
    return (1 - u - v) * _A + u * _B + v * _C

def _hexagonal_configuration(n_pts: int = 11) -> np.ndarray:
    pts = []
    layers = math.ceil((math.sqrt(8 * n_pts + 1) - 1) / 4) + 1
    for i in range(layers):
        for j in range(layers - i):
            u = (i + 0.5 * j + 0.5) / layers
            v = (j * SQRT3 / 2 + 0.5) / layers
            if u + v <= 1.0:
                pts.append((1 - u - v) * _A + u * _B + v * _C)
    pts.append(np.array([0.5, SQRT3/6]))  # Center point
    while len(pts) < n_pts:
        pts.append(_random_point())
    return np.array(pts[:n_pts])

def _optimize(pts: np.ndarray, max_steps: int, init_step: float) -> np.ndarray:
    best_pts = pts.copy()
    best_val, critical_indices = _min_triangle_area(best_pts)
    step_size = init_step
    no_improve = 0

    for step in range(max_steps):
        trial = best_pts.copy()
        idx = random.choice(critical_indices)

        angle = random.uniform(0, 2*math.pi)
        dx = step_size * math.cos(angle)
        dy = step_size * math.sin(angle)
        trial[idx] += dx, dy
        trial[idx] = _project_to_simplex(trial[idx])

        trial_val, new_indices = _min_triangle_area(trial)

        if trial_val > best_val:
            best_val = trial_val
            best_pts = trial.copy()
            critical_indices = new_indices
            no_improve = 0
        else:
            no_improve += 1

        if no_improve > 100:
            step_size *= 0.8
            no_improve = 0
            if step_size < 1e-4:
                break

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    pts = _hexagonal_configuration(11)
    pts = _optimize(pts, max_steps=5000, init_step=0.05)
    pts = _optimize(pts, max_steps=3000, init_step=0.02)
    pts = _optimize(pts, max_steps=2000, init_step=0.01)

    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

