        for j in range(size):
            x = (i + 0.5 * (j % 2)) / size
            y = j * SQRT3 / (2 * size)
            if x <= 1 and y <= SQRT3/2 and (1 - x) * SQRT3 >= y:
                points.append([x, y])
                if len(points) == n:
                    return np.array(points)
    return np.array(points[:n])

