    for _ in range(max_iter):
        improved = False
        for i in range(n):
            for dx, dy in [(0.01, 0), (-0.01, 0), (0, 0.01), (0, -0.01)]:
                trial = best_pts.copy()
                trial[i] += np.array([dx, dy])
                # Project back to triangle if needed
                x, y = trial[i]
                if y < 0 or y > SQRT3/2 or x < 0 or x > 1 or (1 - x) * SQRT3 < y:
