import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    w = 1.0 - u - v
    if u >= 0 and v >= 0 and w >= 0:
        return p
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        s = u + v
        u /= s
        v /= s
    return (1 - u - v) * _A + u * _B + v * _C

def _min_triangle_area_fast(pts: np.ndarray) -> float:
    n = len(pts)
    best = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            p1 = pts[j] - pts[i]
            for k in range(j+1, n):
                p2 = pts[k] - pts[i]
                area = abs(p1[0]*p2[1] - p1[1]*p2[0]) * 0.5
                if area < best:
                    best = area
                    if best == 0:
                        return 0
    return best

def _grid_initialization(n: int) -> np.ndarray:
    pts = []
    k = math.ceil(math.sqrt(n * 2))
    for i in range(k):
        for j in range(k - i):
            u = (i + 0.5) / k
            v = (j + 0.5) / k
            if u + v <= 1.0:
                pts.append((1 - u - v) * _A + u * _B + v * _C)
                if len(pts) == n:
                    return np.array(pts)
    while len(pts) < n:
        pts.append(_random_point())
    return np.array(pts)

def _optimize(pts: np.ndarray, steps: int = 200) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area_fast(best_pts)
    step_size = 0.05

    for _ in range(steps):
        improved = False
        for i in range(len(pts)):
            for _ in range(5):
                trial = best_pts.copy()
                trial[i] += np.random.uniform(-step_size, step_size, 2)
                trial[i] = _project_to_simplex(trial[i])
                trial_val = _min_triangle_area_fast(trial)
                if trial_val > best_val:
                    best_val = trial_val
                    best_pts = trial.copy()
                    improved = True
                    break
        if not improved:
            step_size *= 0.8
    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)
    pts = _grid_initialization(11)
    pts = _optimize(pts)
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

import math
import random
import numpy as np
from itertools import combinations

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / 2.0

def _min_triangle_area(pts):
    min_area = float('inf')
    for trio in combinations(pts, 3):
        a = _area(*trio)
        if a < min_area:
            min_area = a
            if min_area < 1e-8:
                return min_area
    return min_area

def _is_in_triangle(p):
    x, y = p
    if x < 0 or x > 1 or y < 0 or y > SQRT3/2:
        return False
    if y > SQRT3 * x:
        return False
    if y > SQRT3 * (1 - x):
        return False
    return True

def _generate_initial_points(n):
    points = []
    # Start with hexagonal grid points
    for i in range(4):
        for j in range(4):
            if i + j <= 3:
                x = 0.2 + i * 0.2 + j * 0.1
                y = SQRT3/2 * 0.2 + j * 0.2 * SQRT3/2
                if _is_in_triangle((x, y)):
                    points.append([x, y])

    # Fill remaining points randomly
    while len(points) < n:
        x = random.uniform(0, 1)
        y = random.uniform(0, SQRT3/2)
        if _is_in_triangle((x, y)):
            points.append([x, y])
    return np.array(points)

def _optimize_points(points, iterations):
    best_points = points.copy()
    best_score = _min_triangle_area(best_points)

    for i in range(iterations):
        new_points = best_points.copy()

        # Occasionally make a larger random jump
        if i % 100 == 0:
            idx = random.randint(0, len(points)-1)
            new_points[idx] = np.random.uniform(0, 1, 2)
            if not _is_in_triangle(new_points[idx]):
                continue

        # Normal optimization step
        idx = random.randint(0, len(points)-1)
        step = 0.02 * (1 - (i/iterations)**0.5)  # Slower step size reduction
        new_points[idx] += np.random.uniform(-step, step, 2)

        if not _is_in_triangle(new_points[idx]):
            continue

        new_score = _min_triangle_area(new_points)

        if new_score > best_score:
            best_score = new_score
            best_points = new_points.copy()

    return best_points

def find_points(seed=None):
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    points = _generate_initial_points(11)
    points = _optimize_points(points, 3000)  # More iterations

    return [(float(p[0]), float(p[1])) for p in points]

