                          F: float = 0.8,
                          CR: float = 0.9,
                          seed: int | None = 0) -> np.ndarray:

    random.seed(seed)
    np.random.seed(seed)

    def generate_individual():
        return np.array([_random_point() for _ in range(n_pts)])

    population = [generate_individual() for _ in range(pop_size)]
    fitness = [_min_triangle_area(ind) for ind in population]
    best_idx = np.argmax(fitness)
    best_individual = population[best_idx].copy()
    best_fitness = fitness[best_idx]

    for _ in range(max_iter):
        for i in range(pop_size):
            target = population[i]
            a, b, c = random.sample(range(pop_size), 3)
            while a == i or b == i or c == i:
                a, b, c = random.sample(range(pop_size), 3)

            mutant = population[a] + F * (population[b] - population[c])

            trial = np.empty_like(target)
            for j in range(n_pts):
                if random.random() < CR:
                    trial[j] = mutant[j]
                else:
                    trial[j] = target[j]

                u, v = random.random(), random.random()
                if u + v > 1.0:
                    u, v = 1 - u, 1 - v
                trial[j] = (1 - u - v) * _A + u * _B + v * _C

            trial_fitness = _min_triangle_area(trial)
            if trial_fitness > fitness[i]:
                population[i] = trial
                fitness[i] = trial_fitness
                if trial_fitness > best_fitness:
                    best_fitness = trial_fitness
                    best_individual = trial.copy()

        if best_fitness == 0:
            break

    return best_individual

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _differential_evolution(n_pts=11, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

from __future__ import annotations

import math
import random
import itertools
from typing import List, Tuple
import time

import numpy as np
try:
    from scipy.optimize import minimize
except ImportError:
    minimize = None

SQRT3 = math.sqrt(3.0)
_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])
_TRIANGLE_AREA = SQRT3 / 4.0

def _is_inside(p: np.ndarray) -> bool:
    v0 = _C - _A
    v1 = _B - _A
    v2 = p - _A
    dot00 = np.dot(v0, v0)
    dot01 = np.dot(v0, v1)
    dot02 = np.dot(v0, v2)
    dot11 = np.dot(v1, v1)
    dot12 = np.dot(v1, v2)
    inv_denom = 1.0 / (dot00 * dot11 - dot01 * dot01)
    u = (dot11 * dot02 - dot01 * dot12) * inv_denom
    v = (dot00 * dot12 - dot01 * dot02) * inv_denom
    return (u >= 0) and (v >= 0) and (u + v <= 1)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5 / _TRIANGLE_AREA

def _min_triangle_area(pts: np.ndarray) -> float:
    min_area = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = np.clip(uv, 0.0, 1.0)
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    projected = (1 - u - v) * _A + u * _B + v * _C
    if not _is_inside(projected):
        return _random_point()
    return projected

def _initial_configuration(n_pts: int = 11) -> np.ndarray:
    pts = []
    layers = 3
    for layer in range(layers):
        for i in range(layer+1):
            u = 0.5 + (i - layer/2) * 0.3
            v = (layer * 0.3 * SQRT3/2)
            if u + v > 1.0:
                u, v = 1 - u, 1 - v
            pts.append((1 - u - v) * _A + u * _B + v * _C)
    while len(pts) < n_pts:
        pts.append(_random_point())
    return np.array(pts[:n_pts])

def _anneal(n_pts: int = 11, iters: int = 5000, seed: int | None = 0) -> np.ndarray:
    rng = random.Random(seed)
    pts = _initial_configuration(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    start_time = time.time()

    for t in range(iters):
        if time.time() - start_time > 25:
            break

        T = 0.2 * (1e-5 / 0.2) ** (t / (iters - 1))
        idx = rng.randrange(n_pts)
        trial = pts.copy()
        step = 0.03 * (1 - t/iters)
        trial[idx] += rng.uniform(-step, step), rng.uniform(-step, step)
        trial[idx] = _project_to_simplex(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or rng.random() < math.exp(delta / max(T, 1e-12)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

        if t % 100 == 0 and best_val < 0.02:
            for _ in range(5):
                idx = rng.randrange(n_pts)
                trial = best_pts.copy()
                trial[idx] += rng.uniform(-0.05, 0.05), rng.uniform(-0.05, 0.05)
                trial[idx] = _project_to_simplex(trial[idx])
                trial_val = _min_triangle_area(trial)
                if trial_val > best_val:
                    best_val = trial_val
                    best_pts = trial.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    start_time = time.time()
    pts = _anneal(n_pts=11, iters=5000, seed=seed)

    if minimize is not None and time.time() - start_time < 25:
        n_pts = len(pts)
        x0 = pts.ravel()
        def f(x: np.ndarray) -> float:
            P = x.reshape((-1, 2))
            return -_min_triangle_area(P)
        res = minimize(f, x0, method="Nelder-Mead", options=dict(maxiter=200))
        if res is not None and res.success:
            pts = res.x.reshape((n_pts, 2))
            for i in range(n_pts):
                pts[i] = _project_to_simplex(pts[i])

    # Final validation
    valid_pts = []
    for p in pts:
        if _is_inside(p):
            valid_pts.append(p)
        else:
            valid_pts.append(_random_point())

    return [(float(x), float(y)) for x, y in valid_pts]

import math
import random
import numpy as np
from itertools import combinations

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / 2.0

def _min_triangle_area(pts):
    min_area = float('inf')
    for trio in combinations(pts, 3):
        a = _area(*trio)
        if a < min_area:
            min_area = a
            if min_area < 1e-8:
                return min_area
    return min_area

def _is_in_triangle(p):
    x, y = p
    if x < 0 or x > 1 or y < 0 or y > SQRT3/2:
        return False
    if y > SQRT3 * x:
        return False
    if y > SQRT3 * (1 - x):
        return False
    return True

def _generate_initial_points(n):
    # Start with hexagonal grid points
    points = []
    size = int(np.ceil(np.sqrt(n)))
    for i in range(size):
        for j in range(size):
            if len(points) >= n:
                break
            x = 0.1 + 0.8 * i/(size-1)
            y = (SQRT3/2 * 0.8) * j/(size-1)
            if j % 2 == 1:
                x += 0.4/(size-1)
            # Add small random perturbation
            x += random.uniform(-0.01, 0.01)
            y += random.uniform(-0.01, 0.01)
            if _is_in_triangle((x, y)):
                points.append([x, y])

    # Fill any remaining points randomly
    while len(points) < n:
        x = random.uniform(0, 1)
        y = random.uniform(0, SQRT3/2)
        if _is_in_triangle((x, y)):
            points.append([x, y])
    return np.array(points)

def _optimize_points(points, iterations):
    best_points = points.copy()
    best_score = _min_triangle_area(best_points)

    for i in range(iterations):
        new_points = best_points.copy()

        # Alternate between single and multiple point updates
        if i % 5 == 0:
            # Update multiple points
            for _ in range(3):
                idx = random.randint(0, len(points)-1)
                step = 0.015 * (1 - i/iterations)
                new_points[idx] += np.random.uniform(-step, step, 2)
                if not _is_in_triangle(new_points[idx]):
                    new_points[idx] = best_points[idx].copy()
        else:
            # Update single point
            idx = i % len(points)  # Cycle through points
            step = 0.02 * (1 - i/iterations)
            new_points[idx] += np.random.uniform(-step, step, 2)
            if not _is_in_triangle(new_points[idx]):
                new_points[idx] = best_points[idx].copy()

        new_score = _min_triangle_area(new_points)

        if new_score > best_score:
            best_score = new_score
            best_points = new_points.copy()

    return best_points

def find_points(seed=None):
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    points = _generate_initial_points(11)
    points = _optimize_points(points, 3000)

    return [(float(p[0]), float(p[1])) for p in points]

