import math
import random
import itertools
from typing import List, Tuple

import numpy as np

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    best = float("inf")
    # Use itertools to avoid numpy memory overhead for small n=11
    for i, j, k in itertools.combinations(range(n), 3):
        a = _area(pts[i], pts[j], pts[k])
        if a < best:
            best = a
            if best == 0:  # Early exit if degenerate triangle found
                return 0
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    # Faster rejection sampling
    while True:
        x = random.random()
        y = random.random() * SQRT3 / 2
        if y <= SQRT3 * min(x, 1 - x):
            return np.array([x, y])

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    x, y = p
    # Fast boundary projection
    if y < 0:
        return np.array([x, 0])
    if y > SQRT3 / 2:
        return np.array([0.5, SQRT3 / 2])
    if x < 0:
        return np.array([0, 0])
    if x > 1:
        return np.array([1, 0])
    # Check if inside triangle
    if y <= SQRT3 * min(x, 1 - x):
        return p
    # Project to nearest edge
    edge_x = 0.5 - y / SQRT3
    if x < 0.5:
        dist = math.hypot(x - edge_x, y - SQRT3 * x)
        if dist < 1e-8:
            return np.array([edge_x, SQRT3 * x])
        return np.array([edge_x, SQRT3 * x])
    else:
        dist = math.hypot(x - (1 - edge_x), y - SQRT3 * (1 - x))
        if dist < 1e-8:
            return np.array([1 - edge_x, SQRT3 * (1 - x)])
        return np.array([1 - edge_x, SQRT3 * (1 - x)])

def _anneal(n_pts: int = 11,
            iters: int = 5_000,
            start_temp: float = 0.1,
            end_temp: float = 1e-5,
            step_size: float = 0.01,
            seed: int | None = 0) -> np.ndarray:
    rng = random.Random(seed)
    pts = np.array([_random_point() for _ in range(n_pts)])
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        T = start_temp * (end_temp / start_temp) ** (t / max(iters - 1, 1))
        idx = rng.randrange(n_pts)
        trial = pts.copy()
        trial[idx] += rng.uniform(-step_size, step_size), rng.uniform(-step_size, step_size)
        trial[idx] = _project_to_simplex(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or rng.random() < math.exp(delta / max(T, 1e-12)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=5_000, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

from __future__ import annotations

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area_fast(pts: np.ndarray, cutoff: float = 0) -> float:
    n = len(pts)
    best = float('inf')
    for i in range(n-2):
        for j in range(i+1, n-1):
            p = pts[i]
            q = pts[j]
            for k in range(j+1, n):
                a = abs(np.cross(q - p, pts[k] - p)) * 0.5
                if a <= cutoff:
                    return a
                if a < best:
                    best = a
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    u, v = random.random(), random.random()
    if u + v > 1.0:
        u, v = 1-u, 1-v
    return (1 - u - v) * _A + u * _B + v * _C

def _is_in_triangle(p: np.ndarray) -> bool:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    return u >= 0 and v >= 0 and (u + v) <= 1.0

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        s = u + v
        u /= s
        v /= s
    return (1 - u - v) * _A + u * _B + v * _C

def _initial_configuration(n_pts: int = 11) -> np.ndarray:
    pts = []
    layers = 3
    for i in range(layers):
        for j in range(layers - i):
            u = (i + 0.5 * (j % 2 + 1)) / (layers + 1)
            v = (j + 0.5 * (i % 2 + 1)) / (layers + 1)
            if u + v <= 1.0:
                pts.append((1 - u - v) * _A + u * _B + v * _C)
    while len(pts) < n_pts:
        pts.append(_random_point())
    return np.array(pts[:n_pts])

def _optimize(n_pts: int = 11, iters: int = 5000, seed: int | None = 0) -> np.ndarray:
    rng = random.Random(seed)
    pts = _initial_configuration(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area_fast(best_pts)
    accept_count = 0

    for t in range(iters):
        T = max(0.05 * (1 - t/iters)**2, 1e-6)
        step = 0.03 * (1 - t/iters)**0.5

        trial = pts.copy()
        if rng.random() < 0.7 or t < 1000:
            idx = rng.randrange(n_pts)
            trial[idx] += rng.uniform(-step, step), rng.uniform(-step, step)
            trial[idx] = _project_to_simplex(trial[idx])
        else:
            for _ in range(2 + int(t/iters * 3)):
                idx = rng.randrange(n_pts)
                trial[idx] += rng.uniform(-step*3, step*3), rng.uniform(-step*3, step*3)
                trial[idx] = _project_to_simplex(trial[idx])

        if not all(_is_in_triangle(p) for p in trial):
            continue

        trial_val = _min_triangle_area_fast(trial, best_val)
        if trial_val > best_val or rng.random() < math.exp((trial_val - best_val)/T):
            pts = trial
            accept_count += 1
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

        if t % 100 == 0 and accept_count < 30:
            step *= 1.2
        elif t % 100 == 0 and accept_count > 70:
            step *= 0.8
        accept_count = 0

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _optimize(n_pts=11, iters=6000, seed=seed)
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

