import math
import random
import itertools
from typing import List, Tuple
import numpy as np

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5

def _min_triangle_area_fast(pts: np.ndarray) -> float:
    min_area = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, min(i+7, n)):
            for k in range(j+1, min(j+7, n)):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _hex_grid_points(n: int) -> np.ndarray:
    points = []
    size = math.ceil(math.sqrt(n * 2 / SQRT3))
    for i in range(size):
        for j in range(size):
            x = (i + 0.5 * (j % 2)) / size
            y = (j * SQRT3 / 2) / size
            if x + y/SQRT3 <= 1.0 and x - y/SQRT3 <= 1.0 and y <= SQRT3/2:
                points.append([x, y])
    if len(points) < n:
        return _hex_grid_points(size+1)
    return np.array(random.sample(points, n))

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    w = 1.0 - u - v
    if u >= 0 and v >= 0 and w >= 0:
        return p
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _optimize(pts: np.ndarray, max_iter: int = 1000) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area_fast(best_pts)
    n = len(pts)

    for _ in range(max_iter):
        improved = False
        for i in range(n):
            for dx, dy in [(0.01,0), (-0.01,0), (0,0.01), (0,-0.01)]:
                trial = best_pts.copy()
                trial[i] += dx, dy
