import math
import random
import numpy as np

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    best = float("inf")
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _is_in_triangle(p: np.ndarray) -> bool:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    return u >= 0 and v >= 0 and (u + v) <= 1.0

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _initial_configuration() -> np.ndarray:
    pts = []
    # Add vertices with small margin
    margin = 0.02
    pts.extend([_A + margin*(_B+_C-_A), _B + margin*(_A+_C-_B), _C + margin*(_A+_B-_C)])

    # Add points along edges
    for i in range(1, 4):
        t = i/4.0
        pts.append((1-t)*_A + t*_B + margin*_C)
        pts.append((1-t)*_A + t*_C + margin*_B)
        pts.append((1-t)*_B + t*_C + margin*_A)

    # Add interior points in a grid pattern
    grid = [0.2, 0.4, 0.6, 0.8]
    for u in grid:
        for v in grid:
            if u + v < 1.0:
                pts.append((1-u-v)*_A + u*_B + v*_C)

    return np.array(pts[:11])

def _optimize(pts: np.ndarray, steps: int, step_size: float) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    n_pts = len(pts)

    for _ in range(steps):
        trial = best_pts.copy()
        idx = random.randrange(n_pts)
        direction = np.random.normal(0, 1, 2)
        direction /= np.linalg.norm(direction)
        trial[idx] += step_size * direction
        trial[idx] = _project_to_simplex(trial[idx])
        if not _is_in_triangle(trial[idx]):
            continue
        trial_val = _min_triangle_area(trial)
        if trial_val > best_val:
            best_val = trial_val
            best_pts = trial.copy()

    return best_pts

def _push_apart(pts: np.ndarray, steps: int) -> np.ndarray:
    n = len(pts)
    for _ in range(steps):
        min_area = _min_triangle_area(pts)
        for i in range(n):
            for j in range(i+1, n):
                for k in range(j+1, n):
                    a = _area(pts[i], pts[j], pts[k])
                    if abs(a - min_area) < 1e-6:
                        vec_ij = pts[j] - pts[i]
                        vec_ik = pts[k] - pts[i]
                        normal = np.array([-vec_ij[1], vec_ij[0]])
                        if np.dot(normal, vec_ik) < 0:
                            normal = -normal
                        pts[i] -= 0.01 * normal
                        pts[j] += 0.01 * normal
                        pts[k] += 0.01 * normal
                        pts[i] = _project_to_simplex(pts[i])
                        pts[j] = _project_to_simplex(pts[j])
                        pts[k] = _project_to_simplex(pts[k])
    return pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    pts = _initial_configuration()

    for _ in range(3):
        step_size = 0.1
        for _ in range(10):
            pts = _optimize(pts, steps=100, step_size=step_size)
            step_size *= 0.7

    pts = _push_apart(pts, steps=20)

    # Final local optimization
    for _ in range(2):
        step_size = 0.01
        for _ in range(5):
            pts = _optimize(pts, steps=50, step_size=step_size)
            step_size *= 0.5

    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

