                          (0.0035, 0.0035), (-0.0035, 0.0035),
                          (0.0035, -0.0035), (-0.0035, -0.0035)]:
                trial = best_pts.copy()
                trial[i] += np.array([dx, dy])
                x, y = trial[i]
                x, y = _project_to_triangle(x, y)
                trial[i] = np.array([x, y])

                area = _min_triangle_area_fast(trial)
                if area > best_area:
                    best_area = area
                    best_pts = trial.copy()
                    improved = True
        if not improved:
            break
    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
