def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / 2.0

def _min_triangle_area(pts):
    min_area = float('inf')
    for trio in combinations(pts, 3):
        a = _area(*trio)
        if a < min_area:
            min_area = a
            if min_area < 1e-8:
                return min_area
    return min_area

