    x, y = p
    if x < 0 or x > 1 or y < 0 or y > SQRT3/2:
        return False
    if y > SQRT3 * x:
        return False
    if y > SQRT3 * (1 - x):
        return False
    return True

def _generate_initial_points(n):
    # Optimized initial positions for n=11
    base_points = [
        [0.1, 0.05],
        [0.9, 0.05],
        [0.2, 0.15],
        [0.8, 0.15],
        [0.3, 0.3],
        [0.7, 0.3],
        [0.4, 0.45],
        [0.6, 0.45],
        [0.5, 0.6],
        [0.35, 0.2],
        [0.65, 0.2]
    ]

    points = []
    for p in base_points:
        x = p[0] + random.uniform(-0.02, 0.02)
        y = p[1] + random.uniform(-0.02, 0.02)
        if _is_in_triangle((x, y)):
            points.append([x, y])

    while len(points) < n:
        x = random.uniform(0, 1)
        y = random.uniform(0, SQRT3/2)
        if _is_in_triangle((x, y)):
