    best_points = points.copy()
    best_score = _min_triangle_area(best_points)
    no_improve = 0

    for i in range(iterations):
        new_points = best_points.copy()
        step = 0.03 * (1 - i/iterations)**2

        # Identify worst point (in smallest triangles)
        if i % 10 == 0:
            min_areas = [float('inf')] * len(points)
            for trio in combinations(range(len(points)), 3):
                a = _area(points[trio[0]], points[trio[1]], points[trio[2]])
                for idx in trio:
                    if a < min_areas[idx]:
                        min_areas[idx] = a
            worst_idx = np.argmin(min_areas)
        else:
            worst_idx = random.randint(0, len(points)-1)

        # Update selected point
        new_points[worst_idx] += np.random.uniform(-step, step, 2)
        if not _is_in_triangle(new_points[worst_idx]):
            new_points[worst_idx] = best_points[worst_idx].copy()

        new_score = _min_triangle_area(new_points)

        if new_score > best_score:
            best_score = new_score
            best_points = new_points.copy()
            no_improve = 0
        else:
            no_improve += 1
            if no_improve > 50:
                step *= 0.9
                no_improve = 0

    return best_points

