from scipy.spatial import Delaunay

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5 / TRIANGLE_AREA

def _min_triangle_area(pts: np.ndarray) -> float:
    tri = Delaunay(pts)
    simplices = tri.simplices
    min_area = float('inf')
    for simplex in simplices:
        a = _area(pts[simplex[0]], pts[simplex[1]], pts[simplex[2]])
        if a < min_area:
            min_area = a
            if min_area < 1e-8:
                return 0.0
    return min_area

def _barycentric_to_cartesian(u: float, v: float) -> np.ndarray:
    w = 1.0 - u - v
    x = 0.5 * v + u
    y = SQRT3 / 2 * v
    return np.array([x, y])

def _cartesian_to_barycentric(p: np.ndarray) -> Tuple[float, float]:
    x, y = p
    v = (2 * y) / SQRT3
    u = x - 0.5 * v
    return u, v

def _generate_initial_points(n: int) -> np.ndarray:
    points = []
    k = int(math.ceil(math.sqrt(n * 2 / SQRT3)))

    for i in range(k):
        for j in range(k):
            u = (i + 0.5 * (j % 2)) / k
            v = j / k
            if u >= 0 and v >= 0 and u + v <= 1.0:
                points.append(_barycentric_to_cartesian(u, v))
                if len(points) == n:
                    return np.array(points)

    while len(points) < n:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            points.append(_barycentric_to_cartesian(u, v))

    return np.array(points)

def _optimize_points(points: np.ndarray, iterations: int = 5000) -> np.ndarray:
    n = len(points)
    best_points = points.copy()
    best_score = _min_triangle_area(best_points)

    for iter in range(iterations):
        temp = 0.1 * (1.0 - iter/iterations)
        step = 0.05 * (1.0 - iter/iterations)

        idx = random.randint(0, n-1)
        new_points = points.copy()

        u, v = _cartesian_to_barycentric(points[idx])
        du = random.uniform(-step, step)
        dv = random.uniform(-step, step)

        new_u = max(0.0, min(1.0, u + du))
        new_v = max(0.0, min(1.0, v + dv))

        if new_u + new_v > 1.0:
            s = new_u + new_v
            new_u /= s
            new_v /= s

        new_points[idx] = _barycentric_to_cartesian(new_u, new_v)

        new_score = _min_triangle_area(new_points)

        if new_score > best_score or (temp > 0 and random.random() < math.exp((new_score - best_score)/temp)):
            points = new_points
            if new_score > best_score:
                best_score = new_score
                best_points = new_points.copy()

        if iter % 100 == 0 and best_score < 0.02:
            points = best_points.copy()
            for i in range(n):
                if random.random() < 0.2:
                    u, v = random.random(), random.random()
                    if u + v <= 1.0:
                        points[i] = _barycentric_to_cartesian(u, v)

    return best_points

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    initial_points = _generate_initial_points(11)
    optimized_points = _optimize_points(initial_points, 8000)

    return [(float(x), float(y)) for x, y in optimized_points]

