_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _hexagonal_grid(n: int) -> np.ndarray:
    pts = []
    k = int(math.sqrt(n)) + 1
    for i in range(k):
        for j in range(k):
            if len(pts) >= n:
                break
            x = (i + 0.5 * (j % 2)) / (k - 0.5)
            y = j * SQRT3 / (2 * k)
            if x <= 1.0 and y <= SQRT3/2 and (1-x)*SQRT3 >= y:
                pts.append([x, y])
    return np.array(pts[:n])

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    w = 1.0 - u - v
    if u >= 0 and v >= 0 and w >= 0:
        return p
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    # Start with hexagonal grid
    pts = _hexagonal_grid(11)

    # Optimize using Nelder-Mead
    def objective(x):
        P = x.reshape((-1, 2))
        for i in range(len(P)):
            P[i] = _project_to_simplex(P[i])
        return -_min_triangle_area_fast(P)

    res = minimize(
        objective,
        pts.ravel(),
        method='Nelder-Mead',
        options={'maxiter': 500, 'xatol': 1e-6, 'fatol': 1e-6}
    )

    pts = res.x.reshape((11, 2))
    for i in range(11):
        pts[i] = _project_to_simplex(pts[i])

    return [(float(x), float(y)) for x, y in pts]

