import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])
TRI_AREA = SQRT3 / 4.0

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n-2):
        for j in range(i+1, n-1):
            p0 = pts[i]
            p1 = pts[j]
            dx1 = p1[0] - p0[0]
            dy1 = p1[1] - p0[1]
            for k in range(j+1, n):
                dx2 = pts[k][0] - p0[0]
                dy2 = pts[k][1] - p0[1]
                area = abs(dx1*dy2 - dx2*dy1) * 0.5
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0
    return min_area

def _is_inside(p: np.ndarray) -> bool:
    try:
        u, v = np.linalg.solve(np.column_stack((_B-_A, _C-_A)), p-_A)
    except:
        return False
    return u >= -1e-8 and v >= -1e-8 and (1-u-v) >= -1e-8

def _generate_initial_points(n: int) -> np.ndarray:
    while True:
        pts = np.random.uniform(0, 1, (n, 2))
        pts[:, 1] *= SQRT3/2
        mask = np.array([_is_inside(p) for p in pts])
        if np.all(mask):
            return pts

def _differential_evolution(n_pts: int, max_iter: int) -> np.ndarray:
    pop_size = 10
    F = 0.8
    CR = 0.9

    pop = [_generate_initial_points(n_pts).flatten() for _ in range(pop_size)]
    best_sol = pop[0]
    best_val = -_min_triangle_area(best_sol.reshape(n_pts, 2))

    for _ in range(max_iter):
        for i in range(pop_size):
            idxs = [idx for idx in range(pop_size) if idx != i]
            a, b, c = [pop[idx] for idx in np.random.choice(idxs, 3, replace=False)]
            mutant = a + F * (b - c)

            cross_points = np.random.rand(n_pts*2) < CR
            trial = np.where(cross_points, mutant, pop[i])

            trial_pts = trial.reshape(n_pts, 2)
            for j in range(n_pts):
                if not _is_inside(trial_pts[j]):
                    trial_pts[j] = np.clip(trial_pts[j], [0, 0], [1, SQRT3/2])

            trial_val = -_min_triangle_area(trial_pts)
            if trial_val < best_val:
                best_val = trial_val
                best_sol = trial.copy()
            if trial_val < -_min_triangle_area(pop[i].reshape(n_pts, 2)):
                pop[i] = trial

    return best_sol.reshape(n_pts, 2)

def _refine(pts: np.ndarray, steps: int) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    n_pts = len(pts)

    for step in range(steps):
        step_size = 0.01 * (1 - step/steps)
        for idx in range(n_pts):
            for _ in range(5):
                trial = best_pts.copy()
                delta = np.random.uniform(-step_size, step_size, 2)
                trial[idx] += delta
                if _is_inside(trial[idx]):
                    trial_val = _min_triangle_area(trial)
                    if trial_val > best_val:
                        best_val = trial_val
                        best_pts = trial.copy()
    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    pts = _differential_evolution(n_pts=11, max_iter=20)
    pts = _refine(pts, steps=50)

    return [(float(x), float(y)) for x, y in pts]

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4  # Area of unit equilateral triangle

def _is_in_triangle(x: float, y: float) -> bool:
    return (y >= 0) and (y <= SQRT3*(1 - abs(2*x - 1)))

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5 / TRIANGLE_AREA

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n-2):
        for j in range(i+1, n-1):
            p1 = pts[i]
            p2 = pts[j]
            for k in range(j+1, n):
                p3 = pts[k]
                a = abs((p2[0]-p1[0])*(p3[1]-p1[1]) - (p2[1]-p1[1])*(p3[0]-p1[0])) / (2 * TRIANGLE_AREA)
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

def _initialize_points(n: int) -> np.ndarray:
    # Initialize with hexagonal grid plus some random perturbations
    pts = []
    size = int(math.ceil(math.sqrt(n * 2 / SQRT3)))

    for i in range(size):
        for j in range(size):
            if len(pts) >= n:
                break
            x = 0.5 + (i - j) * 0.5 / size
            y = j * SQRT3 / 2 / size
            if _is_in_triangle(x, y):
                pts.append([x, y])

    # Fill remaining points with random positions
    while len(pts) < n:
        x = random.uniform(0, 1)
        y_max = SQRT3 * (1 - abs(2*x - 1))
        y = random.uniform(0, y_max)
        pts.append([x, y])

    return np.array(pts)

def _optimize_points(pts: np.ndarray, iterations: int = 1000) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)
    n = len(pts)

    for step_num in range(iterations):
        temp = 1.0 - step_num / iterations  # Cooling factor
        step_size = 0.1 * temp

        for _ in range(n):  # Try moving each point once per iteration
            idx = random.randint(0, n-1)
            new_pts = best_pts.copy()

            # Generate new position within bounds
            while True:
                dx = random.uniform(-step_size, step_size)
                dy = random.uniform(-step_size, step_size)
                new_x = best_pts[idx][0] + dx
                new_y = best_pts[idx][1] + dy
                if _is_in_triangle(new_x, new_y):
                    break

            new_pts[idx] = [new_x, new_y]
            new_area = _min_triangle_area(new_pts)

            if new_area > best_area:
                best_area = new_area
                best_pts = new_pts.copy()

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _initialize_points(11)
    pts = _optimize_points(pts, 1500)

    # Final verification and adjustment
    for p in pts:
        x, y = p
        if not _is_in_triangle(x, y):
            y = min(y, SQRT3*(1 - abs(2*x - 1)))
            p[1] = max(y, 0)

    return [(float(x), float(y)) for x, y in pts]

