from typing import List, Tuple
import numpy as np

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray, changed_idx: int = -1) -> float:
    min_area = float('inf')
    n = len(pts)

    if changed_idx == -1:
        # Full calculation
        for i in range(n):
            for j in range(i+1, n):
                for k in range(j+1, n):
                    a = _area(pts[i], pts[j], pts[k])
                    if a < min_area:
                        min_area = a
                        if min_area == 0:
                            return 0
    else:
        # Only check triangles involving the changed point
        i = changed_idx
        for j in range(n):
            if j == i:
                continue
            for k in range(j+1, n):
                if k == i:
                    continue
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    while True:
        u, v = np.random.random(2)
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    w = 1.0 - u - v
    if u >= 0 and v >= 0 and w >= 0:
        return p
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _anneal(n_pts: int = 11,
            iters: int = 5000,
            start_temp: float = 0.2,
            end_temp: float = 1e-6,
            initial_step: float = 0.05,
            final_step: float = 0.005,
            seed: int | None = 0) -> np.ndarray:
    np.random.seed(seed)
    pts = np.array([_random_point() for _ in range(n_pts)])
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        T = start_temp * (end_temp / start_temp) ** (t / max(iters-1, 1))
        step = initial_step * (final_step / initial_step) ** (t / max(iters-1, 1))

        idx = np.random.randint(n_pts)
        trial = pts.copy()
        trial[idx] += np.random.uniform(-step, step, size=2)
        trial[idx] = _project_to_simplex(trial[idx])

        trial_val = _min_triangle_area(trial, idx)
        delta = trial_val - best_val

        if delta > 0 or np.random.random() < math.exp(delta / max(T, 1e-12)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = pts.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=5000, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

from __future__ import annotations

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / (2 * TRIANGLE_AREA)

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n-2):
        for j in range(i+1, n-1):
            p0 = pts[j] - pts[i]
            for k in range(j+1, n):
                p1 = pts[k] - pts[i]
                area = abs(p0[0]*p1[1] - p0[1]*p1[0]) / (2 * TRIANGLE_AREA)
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0
    return min_area

def _random_point_in_triangle() -> np.ndarray:
    r1 = random.random()
    r2 = random.random()
    if r1 + r2 > 1:
        r1 = 1 - r1
        r2 = 1 - r2
    x = r1 * 1.0 + r2 * 0.5
    y = r2 * SQRT3 / 2.0
    return np.array([x, y])

def _initialize_points(n_pts: int) -> np.ndarray:
    pts = []
    for i in range(n_pts):
        r = math.sqrt(random.random()) * 0.9
        angle = 2 * math.pi * i / n_pts
        x = 0.5 + r * 0.5 * math.cos(angle)
        y = SQRT3/3 + r * SQRT3/3 * math.sin(angle)
        pts.append(np.array([x, y]))
    return np.array(pts)

def _is_in_triangle(p: np.ndarray) -> bool:
    x, y = p
    if y < 0 or y > SQRT3/2:
        return False
    if x < 0 or x > 1:
        return False
    if y > SQRT3 * x or y > SQRT3 * (1 - x):
        return False
    return True

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    x, y = p
    if _is_in_triangle(p):
        return p

    # Project to closest edge
    edge1 = lambda x: SQRT3 * x
    edge2 = lambda x: SQRT3 * (1 - x)

    # Project to bottom edge
    if y < 0:
        x = max(0, min(1, x))
        return np.array([x, 0])

    # Project to left edge
    d1 = abs(y - edge1(x))
    # Project to right edge
    d2 = abs(y - edge2(x))

    if d1 < d2:
        y_proj = edge1(x)
        if y_proj < 0:
            return np.array([0, 0])
        return np.array([x, y_proj])
    else:
        y_proj = edge2(x)
        if y_proj < 0:
            return np.array([1, 0])
        return np.array([x, y_proj])

def _anneal(n_pts: int = 11,
            iters: int = 50000,
            start_temp: float = 0.1,
            end_temp: float = 1e-8,
            step_size: float = 0.05,
            seed: int | None = None) -> np.ndarray:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _initialize_points(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        T = start_temp * (end_temp / start_temp) ** (t / iters)
        current_step = step_size * (1 - t/iters)

        idx = random.randrange(n_pts)
        trial = pts.copy()

        if t % 100 == 0:
            trial[idx] = _random_point_in_triangle()
        else:
            delta = np.random.uniform(-current_step, current_step, size=2)
            trial[idx] += delta
            trial[idx] = _project_to_triangle(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta_val = trial_val - best_val

        if delta_val > 0 or math.exp(delta_val / max(T, 1e-12)) > random.random():
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
