import numpy as np

SQRT3 = math.sqrt(3.0)
TRI_AREA = SQRT3 / 4.0

def _is_inside(p: np.ndarray) -> bool:
    x, y = p
    if x < 0 or x > 1 or y < 0 or y > SQRT3/2:
        return False
    if y > SQRT3 * x or y > SQRT3 * (1 - x):
        return False
    return True

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / (2 * TRI_AREA)

def _min_triangle_area(pts: np.ndarray) -> float:
    min_area = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                area = _area(pts[i], pts[j], pts[k])
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0
    return min_area

def _random_point() -> np.ndarray:
    while True:
        x = random.uniform(0, 1)
        y = random.uniform(0, SQRT3/2)
        if _is_inside(np.array([x, y])):
            return np.array([x, y])

def _initial_configuration() -> np.ndarray:
    pts = []
    layers = 4
    for layer in range(layers):
        y = (layer + 0.5) * SQRT3 / (2 * layers)
        count = layer + 1
        for i in range(count):
            x = 0.5 + (i - layer/2) * (1.0/layers)
            pts.append(np.array([x, y]))

    while len(pts) < 11:
        pt = _random_point()
        pts.append(pt)

    return np.array(pts[:11])

def _optimize(pts: np.ndarray, iterations: int) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)
    n = len(pts)

    for t in range(iterations):
        temp = 0.1 * (1 - t/iterations)
        step = 0.05 * (1 - t/iterations)

        idx = random.randrange(n)
        trial = pts.copy()
        trial[idx] += np.random.uniform(-step, step, 2)

        if not _is_inside(trial[idx]):
            continue

        trial_area = _min_triangle_area(trial)

        if trial_area > best_area or (temp > 0 and random.random() < math.exp((trial_area - best_area)/temp)):
            pts = trial
            if trial_area > best_area:
                best_area = trial_area
                best_pts = trial.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    pts = _initial_configuration()
    pts = _optimize(pts, 5000)

    for _ in range(3):
        pts = _optimize(pts, 1000)

    return [(float(x), float(y)) for x, y in pts]

import math
import random
import numpy as np
from itertools import combinations

SQRT3 = math.sqrt(3.0)
TRI_AREA = SQRT3 / 4.0

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / 2.0

def _min_triangle_area(pts):
    min_area = float('inf')
    for trio in combinations(pts, 3):
        area = _area(*trio)
        if area < min_area:
            min_area = area
            if min_area == 0:
                return 0
    return min_area / TRI_AREA

def _is_in_triangle(pt):
    x, y = pt
    return y >= 0 and y <= SQRT3 * min(x, 1-x)

def _random_point():
    while True:
        x, y = random.random(), random.random()
        if _is_in_triangle((x, y)):
            return np.array([x, y])

def _hexagonal_grid(n):
    k = math.ceil(math.sqrt(n / (2/SQRT3)))
    pts = []
    for i in range(k):
        for j in range(k):
            x = (i + 0.5*(j%2)) / (k-0.5)
            y = (j * SQRT3/2) / (k-0.5)
            if _is_in_triangle((x, y)):
                pts.append([x, y])
                if len(pts) == n:
                    return pts
    while len(pts) < n:
        pts.append(_random_point())
    return pts[:n]

def _simulated_annealing(pts, iterations=5000):
    current = np.array(pts)
    current_energy = -_min_triangle_area(current)
    best = current.copy()
    best_energy = current_energy

    temp = 1.0
    cooling_rate = 0.9995

    for _ in range(iterations):
        temp *= cooling_rate
        idx = random.randrange(len(current))
        new_pt = current[idx] + np.random.normal(0, temp, 2)

        if not _is_in_triangle(new_pt):
            continue

        trial = current.copy()
        trial[idx] = new_pt
        trial_energy = -_min_triangle_area(trial)

        if trial_energy < best_energy:
            best = trial.copy()
            best_energy = trial_energy

        if trial_energy < current_energy or math.exp((current_energy - trial_energy)/temp) > random.random():
            current = trial.copy()
            current_energy = trial_energy

    return best

def find_points(seed=None):
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _hexagonal_grid(11)
    pts = _simulated_annealing(pts, 5000)

    best_pts = pts.copy()
    best_score = _min_triangle_area(best_pts)

    for _ in range(1000):
        idx = random.randrange(len(pts))
        new_pt = pts[idx] + np.random.normal(0, 0.01, 2)

        if not _is_in_triangle(new_pt):
            continue

        trial = pts.copy()
        trial[idx] = new_pt
        trial_score = _min_triangle_area(trial)

        if trial_score > best_score:
            best_pts = trial.copy()
            best_score = trial_score

    return [(float(x), float(y)) for x, y in best_pts]

