import math
import random
import time
import numpy as np
from scipy.optimize import minimize

SQRT3 = math.sqrt(3.0)
_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])
_TRIANGLE_AREA = SQRT3 / 4.0

def _is_inside_triangle(p: np.ndarray) -> bool:
    v0 = _C - _A
    v1 = _B - _A
    v2 = p - _A
    dot00 = np.dot(v0, v0)
    dot01 = np.dot(v0, v1)
    dot02 = np.dot(v0, v2)
    dot11 = np.dot(v1, v1)
    dot12 = np.dot(v1, v2)
    inv_denom = 1.0 / (dot00 * dot11 - dot01 * dot01)
    u = (dot11 * dot02 - dot01 * dot12) * inv_denom
    v = (dot00 * dot12 - dot01 * dot02) * inv_denom
    return (u >= 0) and (v >= 0) and (u + v <= 1)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5 / _TRIANGLE_AREA

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n-2):
        for j in range(i+1, n-1):
            p = pts[i]
            q = pts[j]
            for k in range(j+1, n):
                r = pts[k]
                a = abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / (2 * _TRIANGLE_AREA)
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

def _random_point_inside() -> np.ndarray:
    while True:
        x = random.uniform(0, 1)
        y = random.uniform(0, SQRT3/2)
        if y <= SQRT3 * min(x, 1 - x):
            return np.array([x, y])

def _initial_configuration(n_pts: int = 11) -> np.ndarray:
    pts = []
    # Hexagonal pattern
    for i in range(4):
        for j in range(4):
            if i + j <= 3:
                x = 0.2 + 0.2 * i - 0.1 * j
                y = 0.1 * SQRT3 * j
                pts.append(np.array([x, y]))
    while len(pts) < n_pts:
        pts.append(_random_point_inside())
    return np.array(pts[:n_pts])

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    x, y = p
    if y < 0:
        y = 0
    if y > SQRT3/2:
        y = SQRT3/2
    if x < 0:
        x = 0
    if x > 1:
        x = 1
    if y > SQRT3 * x:
        y = SQRT3 * x
    if y > SQRT3 * (1 - x):
        y = SQRT3 * (1 - x)
    return np.array([x, y])

def _anneal(n_pts: int = 11, iters: int = 3000, seed: int | None = None) -> np.ndarray:
    rng = random.Random(seed)
    pts = _initial_configuration(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        T = 0.1 * (1e-5 / 0.1) ** (t / (iters - 1))
        idx = rng.randrange(n_pts)
        trial = pts.copy()
        step = 0.05 * (1 - t/iters)
        trial[idx] += rng.uniform(-step, step), rng.uniform(-step, step)
        trial[idx] = _project_to_triangle(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or rng.random() < math.exp(delta / max(T, 1e-12)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

        if t % 100 == 0 and t > 0:
            for _ in range(3):
                idx = rng.randrange(n_pts)
                trial = best_pts.copy()
                trial[idx] += rng.uniform(-0.05, 0.05), rng.uniform(-0.05, 0.05)
                trial[idx] = _project_to_triangle(trial[idx])
                trial_val = _min_triangle_area(trial)
                if trial_val > best_val:
                    best_val = trial_val
                    best_pts = trial.copy()

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    start_time = time.time()
    pts = _anneal(n_pts=11, iters=3000, seed=seed)

    if time.time() - start_time < 25:
        n_pts = len(pts)
        x0 = pts.ravel()
        def f(x: np.ndarray) -> float:
            P = x.reshape((-1, 2))
            return -_min_triangle_area(P)
        res = minimize(f, x0, method="Nelder-Mead", options=dict(maxiter=200))
        if res is not None and res.success:
            pts = res.x.reshape((n_pts, 2))
            for i in range(n_pts):
                pts[i] = _project_to_triangle(pts[i])

    return [(float(x), float(y)) for x, y in pts]

