import math
import random
import itertools
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    best = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

def _barycentric_random() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            w = 1 - u - v
            if min(u, v, w) > 0.01:  # Keep points away from edges
                return u * _B + v * _C + w * _A

def _grid_configuration(n: int = 11) -> np.ndarray:
    pts = []
    layers = 4
    for layer in range(1, layers+1):
        for i in range(layer+1):
            u = (i + 0.5) / (layers + 1)
            v = (layer - i + 0.5) / (layers + 1)
            if u + v < 1.0:
                pts.append((1-u-v)*_A + u*_B + v*_C)
    while len(pts) < n:
        pts.append(_barycentric_random())
    return np.array(pts[:n])

def _verify_points(pts: np.ndarray) -> bool:
    for p in pts:
        M = np.column_stack((_B-_A, _C-_A))
        uv = np.linalg.lstsq(M, p-_A, rcond=None)[0]
        u, v = uv
        if u < 0 or v < 0 or (1-u-v) < 0:
            return False
    return True

def _anneal(n_pts: int = 11, iters: int = 5000, seed: int | None = None) -> np.ndarray:
    if seed is not None:
        random.seed(seed)
    pts = _grid_configuration(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        T = 0.1 * (0.9 ** (t // 100))
        idx = random.randrange(n_pts)
        trial = pts.copy()

        step = 0.05 * (1 - t/iters)
        u, v = random.uniform(-step, step), random.uniform(-step, step)
        trial[idx] += u, v

        if not _verify_points(trial):
            continue

        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or random.random() < math.exp(delta / max(T, 1e-12)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

    return best_pts

def _optimize_local(pts: np.ndarray, steps: int = 500) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    n = len(pts)

    for _ in range(steps):
        improved = False
        for idx in range(n):
            for _ in range(5):
                trial = best_pts.copy()
                step = 0.01 * (1 - _/steps)
                trial[idx] += random.uniform(-step, step), random.uniform(-step, step)

                if not _verify_points(trial):
                    continue

                trial_val = _min_triangle_area(trial)
                if trial_val > best_val:
                    best_val = trial_val
                    best_pts = trial.copy()
                    improved = True
                    break
            if improved:
                break
    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=5000, seed=seed)
    pts = _optimize_local(pts, steps=500)
    assert _verify_points(pts), "Invalid points found"
    return [(float(x), float(y)) for x, y in pts]

import math
import random
import itertools
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    min_area = float('inf')
    # Only check nearby points to save time
    for i in range(len(pts)):
        for j in range(i+1, min(i+6, len(pts))):
            for k in range(j+1, min(j+6, len(pts))):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _hexagonal_grid(n: int) -> np.ndarray:
    pts = []
    layers = math.ceil(math.sqrt(n))
    spacing = 1.0 / (layers + 1)

    for i in range(layers):
        for j in range(layers - i):
            u = (i + 0.5 * j + 1) * spacing
            v = (j * SQRT3/2 + 1) * spacing
            if u + v/SQRT3 <= 1.0:
                pts.append((1 - u - v/SQRT3) * _A + u * _B + v * _C)

    while len(pts) < n:
        u = random.random()
        v = random.random() * SQRT3/2
        if u + v/SQRT3 <= 1.0:
            pts.append((1 - u - v/SQRT3) * _A + u * _B + v * _C)

    return np.array(pts[:n])

def _optimize(pts: np.ndarray, steps: int = 500) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)
    n = len(pts)

    for step in range(steps):
        temp = 1.0 - step/steps
        step_size = 0.01 * temp

        for i in range(n):
            trial = best_pts.copy()
            dx = random.uniform(-step_size, step_size)
            dy = random.uniform(-step_size, step_size)
            trial[i] += np.array([dx, dy])

            # Project back to triangle
            M = np.column_stack((_B - _A, _C - _A))
            uv = np.linalg.lstsq(M, trial[i] - _A, rcond=None)[0]
            u, v = uv
            w = 1.0 - u - v
            if u < 0 or v < 0 or w < 0:
                u = max(0.0, min(1.0, u))
                v = max(0.0, min(1.0, v))
                if u + v > 1.0:
                    u, v = u/(u+v), v/(u+v)
                trial[i] = (1 - u - v) * _A + u * _B + v * _C

            current_area = _min_triangle_area(trial)
            if current_area > best_area or (temp > 0 and random.random() < temp/10):
                best_area = current_area
                best_pts = trial.copy()

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
    pts = _hexagonal_grid(11)
    pts = _optimize(pts, 500)
    return [(float(x), float(y)) for x, y in pts]

