def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    best = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best < 1e-8:
                        return best
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    u, v = random.random(), random.random()
    if u + v > 1.0:
        u, v = 1 - u, 1 - v
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = 1 - v, 1 - u
    return (1 - u - v) * _A + u * _B + v * _C

def _initialize_points(n_pts: int = 11) -> np.ndarray:
    pts = []
    for i in range(n_pts):
        u = (i + 0.5) / n_pts
        for j in range(n_pts):
            v = (j + 0.5) / n_pts
            if u + v <= 1.0:
                pts.append((1 - u - v) * _A + u * _B + v * _C)
    if len(pts) < n_pts:
        pts.extend([_random_point() for _ in range(n_pts - len(pts))])
    return np.array(pts[:n_pts])

def _optimize_points(pts: np.ndarray, iters: int = 1000, step_size: float = 0.01) -> np.ndarray:
    n = len(pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for _ in range(iters):
        improved = False
        for i in range(n):
            for _ in range(10):
                trial = pts.copy()
                trial[i] += np.random.uniform(-step_size, step_size, 2)
                trial[i] = _project_to_simplex(trial[i])
                trial_val = _min_triangle_area(trial)
                if trial_val > best_val:
                    best_val = trial_val
                    best_pts = trial.copy()
                    pts = trial.copy()
                    improved = True
                    break
        if not improved:
            step_size *= 0.9
    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)
    pts = _initialize_points(11)
    pts = _optimize_points(pts, iters=1000, step_size=0.01)
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

