import math
import random
import itertools
from typing import List, Tuple
import time
import numpy as np
try:
    from scipy.optimize import minimize
except ImportError:
    minimize = None

SQRT3 = math.sqrt(3.0)
_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])
_TRIANGLE_AREA = SQRT3 / 4.0

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5 / _TRIANGLE_AREA

def _min_triangle_area(pts: np.ndarray) -> float:
    min_area = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

def _random_point() -> np.ndarray:
    u, v = random.random(), random.random()
    if u + v > 1.0:
        u, v = 1 - u, 1 - v
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _hex_grid(n: int) -> List[np.ndarray]:
    pts = []
    k = math.ceil(math.sqrt(n * 2 / SQRT3))
    for i in range(k):
        for j in range(k):
            if len(pts) >= n:
                break
            x = (i + 0.5 * (j % 2)) / k
            y = SQRT3 * j / (2 * k)
            if x + y/SQRT3 <= 1.0 and y <= SQRT3/2:
                pts.append(np.array([x, y]))
    while len(pts) < n:
        pts.append(_random_point())
    return pts[:n]

def _anneal(n_pts: int = 11, iters: int = 5000, seed: int | None = 0) -> np.ndarray:
    rng = random.Random(seed)
    pts = np.array(_hex_grid(n_pts))
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    start_time = time.time()
    no_improve = 0

    for t in range(iters):
        if time.time() - start_time > 25 or no_improve > 500:
            break

        T = 0.2 * (1e-6 / 0.2) ** (t / (iters - 1))
        step = 0.05 * (1 - t/iters)
        idx = rng.randrange(n_pts)
        trial = pts.copy()
        trial[idx] += rng.uniform(-step, step), rng.uniform(-step, step)
        trial[idx] = _project_to_simplex(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or rng.random() < math.exp(delta / max(T, 1e-12)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()
                no_improve = 0
            else:
                no_improve += 1

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    start_time = time.time()
    pts = _anneal(n_pts=11, iters=5000, seed=seed)

    if minimize is not None and time.time() - start_time < 25:
        n_pts = len(pts)
        x0 = pts.ravel()
        def f(x: np.ndarray) -> float:
            P = x.reshape((-1, 2))
            return -_min_triangle_area(P)
        res = minimize(f, x0, method="Nelder-Mead", options=dict(maxiter=500))
        if res is not None and res.success:
            pts = res.x.reshape((n_pts, 2))
            for i in range(n_pts):
                pts[i] = _project_to_simplex(pts[i])

    return [(float(x), float(y)) for x, y in pts]

from __future__ import annotations
import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])
TRI_AREA = SQRT3 / 4.0

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n-2):
        for j in range(i+1, n-1):
            p0 = pts[i]
            p1 = pts[j]
            dx1 = p1[0] - p0[0]
            dy1 = p1[1] - p0[1]
            for k in range(j+1, n):
                dx2 = pts[k][0] - p0[0]
                dy2 = pts[k][1] - p0[1]
                area = abs(dx1*dy2 - dx2*dy1) * 0.5
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0
    return min_area

def _is_inside(p: np.ndarray) -> bool:
    try:
        u, v = np.linalg.solve(np.column_stack((_B-_A, _C-_A)), p-_A)
    except:
        return False
    return u >= -1e-8 and v >= -1e-8 and (1-u-v) >= -1e-8

def _generate_hex_grid(n: int) -> np.ndarray:
    k = math.ceil(math.sqrt(n / 3)) + 2
    x = np.linspace(0, 1, 2*k+1)
    y = np.linspace(0, SQRT3/2, k+1)
    xx, yy = np.meshgrid(x, y)
    pts = np.column_stack((xx.ravel(), yy.ravel()))
    mask = np.array([_is_inside(p) for p in pts])
    inside = pts[mask]
    if len(inside) < n:
        return _generate_hex_grid(n)
    return inside[np.random.choice(len(inside), n, replace=False)]

def _differential_evolution(n_pts: int, max_iter: int) -> np.ndarray:
    pop_size = 20
    F = 0.7
    CR = 0.9

    def eval_fn(x):
        pts = x.reshape(-1, 2)
        if not all(_is_inside(p) for p in pts):
            return float('inf')
        return -_min_triangle_area(pts)

    pop = []
    for _ in range(pop_size):
        pts = _generate_hex_grid(n_pts)
        pop.append(pts.flatten())
    pop = np.array(pop)

    best_idx = np.argmin([eval_fn(ind) for ind in pop])
    best_sol = pop[best_idx]
    best_val = eval_fn(best_sol)

    for _ in range(max_iter):
        for i in range(pop_size):
            idxs = [idx for idx in range(pop_size) if idx != i]
            a, b, c = pop[np.random.choice(idxs, 3, replace=False)]
            mutant = a + F * (b - c)

            cross_points = np.random.rand(n_pts*2) < CR
            trial = np.where(cross_points, mutant, pop[i])

            for j in range(n_pts):
                x, y = trial[j*2], trial[j*2+1]
                if not _is_inside(np.array([x, y])):
                    x = np.clip(x, 0, 1)
                    y = np.clip(y, 0, SQRT3/2)
                    trial[j*2], trial[j*2+1] = x, y

            trial_val = eval_fn(trial)
            if trial_val < best_val:
                best_val = trial_val
                best_sol = trial.copy()
            if trial_val < eval_fn(pop[i]):
                pop[i] = trial

    return best_sol.reshape(-1, 2)

def _refine(pts: np.ndarray, steps: int) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    n_pts = len(pts)

    for step in range(steps):
        step_size = 0.02 * (1 - step/steps)
        for idx in range(n_pts):
            for _ in range(5):
                trial = best_pts.copy()
                delta = np.random.uniform(-step_size, step_size, 2)
                trial[idx] += delta
                if _is_inside(trial[idx]):
                    trial_val = _min_triangle_area(trial)
                    if trial_val > best_val:
                        best_val = trial_val
                        best_pts = trial.copy()
    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    pts = _differential_evolution(n_pts=11, max_iter=30)
    pts = _refine(pts, steps=100)

    return [(float(x), float(y)) for x, y in pts]

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4  # Area of unit equilateral triangle

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5 / TRIANGLE_AREA

def _min_triangle_area(pts: np.ndarray) -> float:
    min_area = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

def _is_in_triangle(x: float, y: float) -> bool:
    return y <= SQRT3 * (1 - abs(2*x - 1)) and 0 <= x <= 1 and 0 <= y <= SQRT3/2

def _generate_initial_points(n: int) -> np.ndarray:
    # Generate exactly n points in a hexagonal grid pattern
    pts = []
    layers = 5  # Enough layers to get at least 11 points
    while len(pts) < n:
        pts = []
        for layer in range(layers):
            for i in range(layer + 1):
                j = layer - i
                x = 0.5 + (i - j) * 0.5 / (layers - 1)
                y = j * SQRT3 / 2 / (layers - 1)
                if _is_in_triangle(x, y):
                    pts.append([x, y])
                    if len(pts) == n:
                        return np.array(pts)
        layers += 1
    return np.array(pts[:n])

def _optimize_points(pts: np.ndarray, iterations: int = 3000) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)
    n = len(pts)
    temp = 1.0
    cooling_rate = temp / iterations

    for step in range(iterations):
        temp = 1.0 - step * cooling_rate
        new_pts = best_pts.copy()

        for _ in range(5):  # Try 5 times to find valid move
            idx = random.randint(0, n-1)
            move = np.random.normal(0, 0.02 * temp, 2)
            new_pt = best_pts[idx] + move
            x, y = new_pt

            if _is_in_triangle(x, y):
                new_pts[idx] = new_pt
                break

        new_area = _min_triangle_area(new_pts)

        if new_area > best_area or (temp > 0 and random.random() < math.exp((new_area - best_area)/temp)):
            best_area = new_area
            best_pts = new_pts.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _generate_initial_points(11)
    pts = _optimize_points(pts, 2500)

    # Fallback if optimization somehow fails
    if len(pts) != 11 or not all(_is_in_triangle(x, y) for x, y in pts):
        pts = np.array([
            [0.5, 0.0], [0.25, 0.4330127], [0.75, 0.4330127],
            [0.125, 0.21650635], [0.375, 0.21650635],
            [0.625, 0.21650635], [0.875, 0.21650635],
            [0.25, 0.0], [0.5, 0.28867513], [0.75, 0.0],
            [0.375, 0.4330127]
        ])

    return [(float(x), float(y)) for x, y in pts]

from __future__ import annotations

import math
import random
import itertools
from typing import List, Tuple
import time
import numpy as np
try:
    from scipy.optimize import minimize, differential_evolution
    from scipy.spatial import KDTree
except ImportError:
    minimize = None
    differential_evolution = None

SQRT3 = math.sqrt(3.0)
start_time = time.time()

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area_fast(pts: np.ndarray) -> float:
    tree = KDTree(pts)
    best = float('inf')
    n = len(pts)
    for i in range(n):
        neighbors = tree.query_ball_point(pts[i], 0.2)
        for j in neighbors:
            if j <= i:
                continue
            for k in neighbors:
                if k <= j:
                    continue
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _structured_points(n: int) -> np.ndarray:
    pts = []
    layers = int(math.sqrt(n)) + 1
    for i in range(layers):
        for j in range(layers - i):
            u = i / layers
            v = j / layers
            if u + v <= 1.0:
                pts.append((1 - u - v) * _A + u * _B + v * _C)
    if len(pts) < n:
        pts.extend([_A + (random.random(), random.random() * SQRT3) for _ in range(n - len(pts))])
    return np.array(pts[:n])

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    w = 1.0 - u - v
    if u >= 0 and v >= 0 and w >= 0:
        return p
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _optimize_global(n_pts: int) -> np.ndarray:
    if differential_evolution is None or time.time() - start_time > 20:
        return _structured_points(n_pts)

    bounds = [(0, 1), (0, SQRT3/2)] * n_pts

    def f(x: np.ndarray) -> float:
        P = x.reshape((-1, 2))
        return -_min_triangle_area_fast(P)

    result = differential_evolution(
        f,
        bounds,
        strategy='best1bin',
        maxiter=100,
        popsize=15,
        tol=1e-6,
        polish=False,
        seed=0
    )

    if result.success:
        pts = result.x.reshape((n_pts, 2))
        for i in range(n_pts):
            pts[i] = _project_to_simplex(pts[i])
        return pts
    return _structured_points(n_pts)

def _local_polish(pts: np.ndarray) -> np.ndarray:
    if minimize is None or time.time() - start_time > 28:
        return pts
    n_pts = len(pts)
    x0 = pts.ravel()

    def f(x: np.ndarray) -> float:
        P = x.reshape((-1, 2))
        return -_min_triangle_area_fast(P)

    bounds = [(0, 1), (0, SQRT3/2)] * n_pts
    res = minimize(
        f,
        x0,
        method="L-BFGS-B",
        bounds=bounds,
        options=dict(maxiter=500)
    )

    if res is not None and res.success:
        out = res.x.reshape((n_pts, 2))
        for i in range(n_pts):
            out[i] = _project_to_simplex(out[i])
        return out
    return pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)
    pts = _optimize_global(11)
    pts = _local_polish(pts)
    if time.time() - start_time < 28:
        pts = _local_polish(pts)
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    best = float("inf")
    for i in range(len(pts)):
        for j in range(i+1, min(i+5, len(pts))):
            for k in range(j+1, min(j+5, len(pts))):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best < 0.001:
                        return best
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _hex_grid_point(i: int, n: int) -> np.ndarray:
    row = i // n
    col = i % n
    x = (col + 0.5 * (row % 2)) / (n - 0.5)
    y = row * SQRT3 / (2 * (n - 1))
    if x > 1.0 or y > SQRT3/2 or (x > 0.5 and y > SQRT3*(1-x)):
        return _random_point()
    return np.array([x, y])

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _is_in_triangle(p: np.ndarray) -> bool:
    x, y = p
    if x < 0 or x > 1 or y < 0 or y > SQRT3/2:
        return False
    if x <= 0.5:
        return y <= SQRT3 * x
    else:
        return y <= SQRT3 * (1 - x)

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    if _is_in_triangle(p):
        return p
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        s = u + v
        u /= s
        v /= s
    return (1 - u - v) * _A + u * _B + v * _C

def _optimize(n_pts: int = 11, phases: int = 4, iters: int = 4000, seed: int = 0) -> np.ndarray:
    rng = random.Random(seed)

    grid_size = int(math.sqrt(n_pts)) + 1
    pts = np.array([_hex_grid_point(i, grid_size) for i in range(n_pts)])
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for phase in range(phases):
        temp = 0.2 * (0.8 ** phase)
        step = 0.1 * (0.6 ** phase)

        for _ in range(iters):
            idx = rng.randrange(n_pts)
            trial = pts.copy()
            angle = rng.uniform(0, 2*math.pi)
            dx = step * math.cos(angle)
            dy = step * math.sin(angle)
            trial[idx] += dx, dy
            trial[idx] = _project_to_simplex(trial[idx])

            if not _is_in_triangle(trial[idx]):
                continue

            trial_val = _min_triangle_area(trial)
            delta = trial_val - best_val

            if delta > 0 or rng.random() < math.exp(delta / max(temp, 1e-12)):
                pts = trial
                if trial_val > best_val:
                    best_val = trial_val
                    best_pts = trial.copy()

            if _ % 500 == 0 and best_val < 0.02:
                pts = best_pts.copy()
                pts[rng.randrange(n_pts)] = _random_point()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _optimize(n_pts=11, phases=4, iters=4000, seed=seed)
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

