import math
import random
import itertools
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4  # Area of unit equilateral triangle

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5 / TRIANGLE_AREA

def _min_triangle_area_fast(pts: np.ndarray) -> float:
    min_area = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

def _is_in_triangle(x: float, y: float) -> bool:
    if y < 0 or y > SQRT3/2:
        return False
    if x < 0 or x > 1:
        return False
    if y > SQRT3 * (1 - x):
        return False
    return True

def _generate_initial_points(n: int) -> np.ndarray:
    # Generate points in a hexagonal pattern with proper boundary handling
    k = math.ceil(math.sqrt(n * 2 / SQRT3))
    points = []
    for i in range(k):
        for j in range(k):
            x = (i + 0.5 * (j % 2)) / (k - 0.5)
            y = j * SQRT3 / (2 * (k - 0.5))
            if _is_in_triangle(x, y):
                points.append([x, y])
                if len(points) == n:
                    return np.array(points)
    # If we didn't get enough points, fill with random valid points
    while len(points) < n:
        x = random.uniform(0, 1)
        y = random.uniform(0, min(SQRT3/2, SQRT3 * (1 - x)))
        points.append([x, y])
    return np.array(points)

def _optimize_points(pts: np.ndarray, max_iter: int = 1000) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area_fast(best_pts)
    n = len(pts)
    step_sizes = [0.01, 0.005, 0.001]

    for step in step_sizes:
        improved = True
        while improved:
            improved = False
            for i in range(n):
                for dx, dy in itertools.product([-step, 0, step], [-step, 0, step]):
                    if dx == 0 and dy == 0:
                        continue
                    trial = best_pts.copy()
                    trial[i] += np.array([dx, dy])
                    x, y = trial[i]
                    if not _is_in_triangle(x, y):
                        continue

                    area = _min_triangle_area_fast(trial)
                    if area > best_area:
                        best_area = area
                        best_pts = trial.copy()
                        improved = True
    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    pts = _generate_initial_points(11)

    # Small perturbations with boundary checks
    for i in range(len(pts)):
        for _ in range(20):
            dx, dy = np.random.uniform(-0.002, 0.002, 2)
            x, y = pts[i][0] + dx, pts[i][1] + dy
            if _is_in_triangle(x, y):
                pts[i] = np.array([x, y])
                break

    pts = _optimize_points(pts)

    # Final verification and fallback
    valid = all(_is_in_triangle(x, y) for x, y in pts)
    if not valid:
        pts = _generate_initial_points(11)

    return [(float(x), float(y)) for x, y in pts]

from __future__ import annotations
import math
import random
import itertools
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(points: np.ndarray, triplets: np.ndarray) -> np.ndarray:
    p = points[triplets[:, 0]]
    q = points[triplets[:, 1]]
    r = points[triplets[:, 2]]
    return np.abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(points: np.ndarray) -> float:
    n = len(points)
    if n < 3:
        return 0.0
    triplets = np.array(list(itertools.combinations(range(n), 3)))
    areas = _area(points, triplets)
    return np.min(areas) / TRIANGLE_AREA

def _generate_hexagonal(n: int) -> np.ndarray:
    points = []
    k = math.ceil(math.sqrt(n / 3))
    for i in range(k):
        for j in range(k):
            x = (i + 0.5 * j) / k
            y = (SQRT3 / 2) * j / k
            if x <= 1.0 and y <= SQRT3/2 and (1 - x) * SQRT3 >= y:
                points.append([x, y])
    return np.array(points[:n])

def _is_inside(p: np.ndarray) -> bool:
    x, y = p
    if y < 0 or y > SQRT3/2:
        return False
    if x < 0 or x > 1:
        return False
    if y > SQRT3 * x or y > SQRT3 * (1 - x):
        return False
    return True

def _project(p: np.ndarray) -> np.ndarray:
    x, y = p
    if _is_inside(p):
        return p

    # Project to closest edge
    if y <= 0:
        return np.clip(x, 0, 1), 0.0
    if y >= SQRT3 * x and y >= SQRT3 * (1 - x):
        return 0.5, SQRT3/2

    # Project to left or right edge
    if x <= 0.5:
        edge_y = SQRT3 * x
        if y > edge_y:
            return (y / SQRT3, y)
        else:
            return (x, 0.0 if y < 0 else y)
    else:
        edge_y = SQRT3 * (1 - x)
        if y > edge_y:
            return (1 - y / SQRT3, y)
        else:
            return (x, 0.0 if y < 0 else y)

def _optimize(points: np.ndarray, iterations: int) -> np.ndarray:
    n = len(points)
    best_points = points.copy()
    best_score = _min_triangle_area(best_points)

    for i in range(iterations):
        temp = 0.1 * (0.001 / 0.1) ** (i / iterations)

        # Perturb each point
        new_points = best_points.copy()
        for j in range(n):
            step = 0.01 * (1 - i/iterations)
            dx, dy = np.random.uniform(-step, step, 2)
            new_p = new_points[j] + [dx, dy]
            new_points[j] = _project(new_p)

        new_score = _min_triangle_area(new_points)
        if new_score > best_score or (temp > 0 and np.random.random() < math.exp((new_score - best_score)/temp)):
            best_points = new_points
            best_score = new_score

    return best_points

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    np.random.seed(seed)
    random.seed(seed)

    # Start with hexagonal pattern
    points = _generate_hexagonal(11)

    # Optimize
