import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    best = float("inf")
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = 1 - v, 1 - u
    return (1 - u - v) * _A + u * _B + v * _C

def _hexagonal_lattice(n_pts: int) -> np.ndarray:
    pts = []
    k = int(math.sqrt(n_pts)) + 1
    for i in range(k):
        for j in range(k):
            if len(pts) >= n_pts:
                break
            x = (i + 0.5 * (j % 2)) / k
            y = (j * SQRT3 / 2) / k
            if x + y / SQRT3 <= 1.0 and y <= SQRT3 / 2:
                pts.append(np.array([x, y]))
    return np.array(pts[:n_pts])

def _adaptive_anneal(n_pts: int = 11, iters: int = 3000, seed: int | None = 0) -> np.ndarray:
    rng = random.Random(seed)
    pts = _hexagonal_lattice(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    no_improve = 0

    for t in range(iters):
        T = 0.1 * (0.001 / 0.1) ** (t / max(iters - 1, 1))
        idx = rng.randrange(n_pts)
        trial = pts.copy()
        step = 0.01 * (1 - t/iters)
        trial[idx] += rng.uniform(-step, step), rng.uniform(-step, step)
        trial[idx] = _project_to_simplex(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or rng.random() < math.exp(delta / max(T, 1e-12)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()
                no_improve = 0
            else:
                no_improve += 1

        if no_improve > 100:
            break

    return best_pts

def _gradient_perturb(pts: np.ndarray, steps: int = 200) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    n_pts = len(pts)

    for _ in range(steps):
        idx = random.randrange(n_pts)
        trial = best_pts.copy()
        grad = np.zeros(2)
        for j in range(n_pts):
            if j == idx:
                continue
            for k in range(j+1, n_pts):
                if k == idx:
                    continue
                p, q, r = best_pts[idx], best_pts[j], best_pts[k]
                area = _area(p, q, r)
                if area == best_val:
                    normal = np.array([q[1] - r[1], r[0] - q[0]])
                    grad += normal / np.linalg.norm(normal)
        if np.linalg.norm(grad) > 0:
            grad = grad / np.linalg.norm(grad)
        trial[idx] += 0.001 * grad
        trial[idx] = _project_to_simplex(trial[idx])

        trial_val = _min_triangle_area(trial)
        if trial_val > best_val:
            best_val = trial_val
            best_pts = trial.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _adaptive_anneal(n_pts=11, iters=3000, seed=seed)
    pts = _gradient_perturb(pts, steps=200)
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

