import math
import random
import itertools
from typing import List, Tuple
import numpy as np

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    best = float("inf")
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _is_in_triangle(p: np.ndarray) -> bool:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    return u >= -1e-8 and v >= -1e-8 and (u + v) <= 1.0 + 1e-8

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        total = u + v
        u /= total
        v /= total
    projected = (1 - u - v) * _A + u * _B + v * _C
    if not _is_in_triangle(projected):
        return _random_point()
    return projected

def _hexagonal_configuration(n_pts: int = 11) -> np.ndarray:
    pts = []
    layers = 4
    for i in range(layers):
        for j in range(layers - i):
            u = (i + 0.5 * j + 0.5) / layers
            v = (j * SQRT3 / 2 + 0.5) / layers
            if u + v <= 1.0:
                pts.append((1 - u - v) * _A + u * _B + v * _C)
    while len(pts) < n_pts:
        pts.append(_random_point())
    return np.array(pts[:n_pts])

def _optimize(pts: np.ndarray, steps: int, step_size: float) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    n_pts = len(pts)

    for _ in range(steps):
        trial = best_pts.copy()
        idx = random.randrange(n_pts)
        trial[idx] += random.uniform(-step_size, step_size), random.uniform(-step_size, step_size)
        trial[idx] = _project_to_simplex(trial[idx])
        if not _is_in_triangle(trial[idx]):
            trial[idx] = _project_to_simplex(trial[idx])
        trial_val = _min_triangle_area(trial)
        if trial_val > best_val:
            best_val = trial_val
            best_pts = trial.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    pts = _hexagonal_configuration(11)

    pts = _optimize(pts, steps=2000, step_size=0.08)
    pts = _optimize(pts, steps=2000, step_size=0.04)
    pts = _optimize(pts, steps=2000, step_size=0.02)
    pts = _optimize(pts, steps=2000, step_size=0.01)
    pts = _optimize(pts, steps=2000, step_size=0.005)
    pts = _optimize(pts, steps=2000, step_size=0.002)

    # Final validation pass
    for i in range(len(pts)):
        if not _is_in_triangle(pts[i]):
            pts[i] = _project_to_simplex(pts[i])

    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

import math
import random
import numpy as np
from itertools import combinations
from scipy.spatial import KDTree

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / 2.0

def _min_triangle_area_fast(pts):
    tree = KDTree(pts)
    min_area = float('inf')
    for i in range(len(pts)):
        neighbors = tree.query(pts[i], k=6)[1][1:]  # Get 5 nearest neighbors
        for j in neighbors:
            for k in neighbors:
                if j != k and j > i and k > i:
                    a = _area(pts[i], pts[j], pts[k])
                    if a < min_area:
                        min_area = a
                        if min_area < 1e-8:
                            return min_area
    return min_area

def _is_in_triangle(p):
    x, y = p
    if x < 0 or x > 1 or y < 0 or y > SQRT3/2:
        return False
    if y > SQRT3 * x:
        return False
    if y > SQRT3 * (1 - x):
        return False
    return True

def _generate_initial_points(n):
    points = []
    # Optimal hexagonal packing with adjustments for n=11
    layers = 3
    for i in range(layers):
        for j in range(layers - i):
            x = 0.1 + i * 0.3 + j * 0.15
            y = SQRT3 * (0.1 + j * 0.3)
            if _is_in_triangle((x, y)):
                points.append([x, y])

    # Mirror points
    sym_points = [[1-x, y] for x, y in points if _is_in_triangle((1-x, y))]
    points.extend(sym_points)

    # Add center points
    center_points = [
        [0.5, SQRT3/6],
        [0.25, SQRT3/12],
        [0.75, SQRT3/12],
        [0.5, SQRT3/3],
        [0.375, SQRT3/4],
        [0.625, SQRT3/4]
    ]
    points.extend([p for p in center_points if _is_in_triangle(p)])

    # Ensure we have exactly n points
    while len(points) < n:
        x = random.uniform(0.1, 0.9)
        y = random.uniform(0.05, SQRT3/2 - 0.05)
        if _is_in_triangle((x, y)):
            points.append([x, y])

    return np.array(points[:n])

def _optimize_points_gradient(points, iterations):
    best_points = points.copy()
    best_score = _min_triangle_area_fast(best_points)
    n = len(points)

    for i in range(iterations):
        temp = max(0.1, 1.0 - (i/iterations))

        # Create candidate by moving critical points
        new_points = best_points.copy()
        for _ in range(1 + int(temp * 2)):
            idx = random.randint(0, n-1)
            step = 0.04 * temp
            new_points[idx] += np.random.uniform(-step, step, 2)

            if not _is_in_triangle(new_points[idx]):
                new_points[idx] = best_points[idx].copy()

        new_score = _min_triangle_area_fast(new_points)

        # Gradient-based acceptance
        if new_score > best_score:
            best_score = new_score
            best_points = new_points.copy()

        # Periodic global optimization
        if i % 100 == 0:
            for _ in range(3):
                candidate = best_points.copy()
                for idx in random.sample(range(n), min(4, n)):
                    candidate[idx] = np.random.uniform(0.1, 0.9, 2)
                    if not _is_in_triangle(candidate[idx]):
                        candidate[idx] = best_points[idx].copy()
                candidate_score = _min_triangle_area_fast(candidate)
                if candidate_score > best_score:
                    best_score = candidate_score
                    best_points = candidate.copy()

    return best_points

def find_points(seed=None):
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    best_points = None
    best_score = 0

    for _ in range(3):
        points = _generate_initial_points(11)
