import math
import random
import numpy as np
from itertools import combinations

SQRT3 = math.sqrt(3.0)
_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5

def _min_triangle_area(pts, exclude_idx=None):
    min_area = float('inf')
    n = len(pts)
    for i in range(n-2):
        if exclude_idx is not None and i == exclude_idx:
            continue
        for j in range(i+1, n-1):
            if exclude_idx is not None and j == exclude_idx:
                continue
            for k in range(j+1, n):
                if exclude_idx is not None and k == exclude_idx:
                    continue
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

def _random_point():
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p):
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv[0], uv[1]
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    # Better initial points using hexagonal pattern
    pts = []
    for i in range(11):
        if i == 0:
            pts.append(_random_point())
        else:
            best_p = None
            best_min_dist = 0
            for _ in range(10):
                p = _random_point()
                min_dist = min(np.linalg.norm(p - q) for q in pts)
                if min_dist > best_min_dist:
                    best_min_dist = min_dist
                    best_p = p
            pts.append(best_p)
    pts = np.array(pts)

    best_pts = pts.copy()
    best_area = _min_triangle_area(pts)

    for t in range(5000):
        T = 0.2 * (0.0001/0.2) ** (t/4999)
        idx = random.randrange(11)
        step = 0.1 * (0.01/0.1) ** (t/4999)

        new_pts = pts.copy()
        new_pts[idx] += random.uniform(-step, step), random.uniform(-step, step)
        new_pts[idx] = _project_to_simplex(new_pts[idx])

        # Only compute affected triangles
        new_area = _min_triangle_area(new_pts, idx)
        if new_area == 0:
            continue
        new_area = min(new_area, _min_triangle_area([p for i,p in enumerate(new_pts) if i != idx]))

        if new_area > best_area or (T > 0 and random.random() < math.exp((new_area - best_area)/T)):
            pts = new_pts
            if new_area > best_area:
                best_area = new_area
                best_pts = new_pts.copy()

    return [(float(x), float(y)) for x, y in best_pts]

