import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / (2 * TRIANGLE_AREA)

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n-2):
        for j in range(i+1, n-1):
            p0 = pts[j] - pts[i]
            for k in range(j+1, n):
                p1 = pts[k] - pts[i]
                area = abs(p0[0]*p1[1] - p0[1]*p1[0]) / (2 * TRIANGLE_AREA)
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0
    return min_area

def _random_point_in_triangle() -> np.ndarray:
    r1 = random.random()
    r2 = random.random()
    if r1 + r2 > 1:
        r1 = 1 - r1
        r2 = 1 - r2
    x = r1 * 1.0 + r2 * 0.5
    y = r2 * SQRT3 / 2.0
    return np.array([x, y])

def _initialize_points(n_pts: int) -> np.ndarray:
    pts = []
    for i in range(n_pts):
        r = math.sqrt(random.random()) * 0.8
        angle = 2 * math.pi * i / n_pts
        x = 0.5 + r * 0.4 * math.cos(angle)
        y = SQRT3/3 + r * SQRT3/3 * math.sin(angle)
        pts.append(np.array([x, y]))
    return np.array(pts)

def _is_in_triangle(p: np.ndarray) -> bool:
    x, y = p
    if y < 0 or y > SQRT3/2:
        return False
    if x < 0 or x > 1:
        return False
    if y > SQRT3 * x or y > SQRT3 * (1 - x):
        return False
    return True

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    x, y = p
    if _is_in_triangle(p):
        return p

    # Project to closest point inside triangle
    edge1 = lambda x: SQRT3 * x
    edge2 = lambda x: SQRT3 * (1 - x)

    # Project to bottom edge
    if y < 0:
        x = max(0.01, min(0.99, x))
        return np.array([x, 0.01])

    # Project to left edge
    d1 = abs(y - edge1(x))
    # Project to right edge
    d2 = abs(y - edge2(x))

    if d1 < d2:
        y_proj = edge1(x)
        if y_proj < 0:
            return np.array([0.01, 0.01])
        return np.array([max(0.01, min(0.99, x)), max(0.01, min(y_proj, SQRT3/2 - 0.01))])
    else:
        y_proj = edge2(x)
        if y_proj < 0:
            return np.array([0.99, 0.01])
        return np.array([max(0.01, min(0.99, x)), max(0.01, min(y_proj, SQRT3/2 - 0.01))])

def _anneal(n_pts: int = 11,
            iters: int = 30000,
            start_temp: float = 0.1,
            end_temp: float = 1e-8,
            step_size: float = 0.03,
            seed: int | None = None) -> np.ndarray:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _initialize_points(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        T = start_temp * (end_temp / start_temp) ** (t / iters)
        current_step = step_size * (1 - t/iters)

        idx = random.randrange(n_pts)
        trial = pts.copy()

        if t % 100 == 0:
            trial[idx] = _random_point_in_triangle()
        else:
            delta = np.random.uniform(-current_step, current_step, size=2)
            trial[idx] += delta
            trial[idx] = _project_to_triangle(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta_val = trial_val - best_val

        if delta_val > 0 or math.exp(delta_val / max(T, 1e-12)) > random.random():
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

import math
import random
import numpy as np
from itertools import combinations
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRI_AREA = 0.5 * SQRT3 / 2.0

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5 / TRI_AREA

def _min_triangle_area(pts):
    min_area = float('inf')
    n = len(pts)
    for i in range(n-2):
        for j in range(i+1, n-1):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

def _is_in_triangle(p):
    x, y = p
    return (x + y/SQRT3 <= 1.0) and (x - y/SQRT3 <= 0.0) and (y <= SQRT3/2)

def _project_to_triangle(p):
    x, y = p
    # Project to y boundary first
    if y > SQRT3/2:
        y = SQRT3/2
    # Project to left boundary
    if x - y/SQRT3 > 0:
        x = y/SQRT3
    # Project to right boundary
    if x + y/SQRT3 > 1:
        x = 1 - y/SQRT3
    return np.array([x, y])

def _initialize_points(n):
    points = []
    # Use a triangular number pattern to get close to 11 points
    layers = 4
    for i in range(layers + 1):
        for j in range(layers + 1 - i):
            x = (i + 0.5 * j) / layers
            y = (SQRT3/2) * j / layers
            points.append([x, y])
    # Select 11 points closest to center
    center = np.array([0.5, SQRT3/4])
    points = sorted(points, key=lambda p: np.linalg.norm(np.array(p)-center))[:11]
    return np.array(points)

def _get_worst_triangle_indices(pts, k=1):
    min_area = float('inf')
    worst_indices = None
    n = len(pts)
    for i in range(n-2):
        for j in range(i+1, n-1):
            for m in range(j+1, n):
                a = _area(pts[i], pts[j], pts[m])
                if a < min_area:
                    min_area = a
                    worst_indices = (i, j, m)
                    if min_area == 0:
                        return [worst_indices]
    return [worst_indices] if worst_indices else []

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    pts = _initialize_points(11)
    best_pts = pts.copy()
    best_area = _min_triangle_area(pts)

    # Simulated annealing phase
    for t in range(3000):
        T = max(0.001, 0.1 * (0.001/0.1) ** (t/2999))
        step = 0.05 * (1 - t/3000)

        # Perturb points in worst triangles
        worst_tris = _get_worst_triangle_indices(pts)
        if not worst_tris:
            continue
        idx = random.choice(worst_tris[0])

        new_pts = pts.copy()
        perturbation = np.random.uniform(-step, step, size=2)
        new_pts[idx] += perturbation
        new_pts[idx] = _project_to_triangle(new_pts[idx])

        new_area = _min_triangle_area(new_pts)
        if new_area > best_area or (T > 0 and random.random() < math.exp((new_area - best_area)/T)):
            pts = new_pts
            if new_area > best_area:
                best_area = new_area
                best_pts = new_pts.copy()

    # Local optimization phase
    for _ in range(500):
        worst_tris = _get_worst_triangle_indices(best_pts)
        if not worst_tris:
            break
        i, j, k = worst_tris[0]
        centroid = (best_pts[i] + best_pts[j] + best_pts[k]) / 3
        for idx in [i, j, k]:
            new_pts = best_pts.copy()
            new_pts[idx] = 0.8 * new_pts[idx] + 0.2 * centroid
            new_pts[idx] = _project_to_triangle(new_pts[idx])
            new_area = _min_triangle_area(new_pts)
            if new_area > best_area:
                best_area = new_area
                best_pts = new_pts.copy()

    return [(float(x), float(y)) for x, y in best_pts]

