import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    u, v = random.random(), random.random()
    if u + v > 1.0:
        u, v = 1 - u, 1 - v
    return (1 - u - v) * _A + u * _B + v * _C

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            v1 = pts[j] - pts[i]
            for k in range(j+1, n):
                v2 = pts[k] - pts[i]
                area = 0.5 * abs(v1[0]*v2[1] - v1[1]*v2[0])
                if area < min_area:
                    min_area = area
                    if min_area < 1e-8:
                        return 0
    return min_area

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    if u >= 0 and v >= 0 and (u + v) <= 1:
        return p
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _initial_configuration(n_pts: int = 11) -> np.ndarray:
    pts = []
    layers = math.ceil(math.sqrt(n_pts))
    for i in range(layers):
        for j in range(layers):
            if len(pts) >= n_pts:
                break
            u = (i + 0.5 * (j % 2)) / layers
            v = j * 0.866 / layers
            if u + v > 1.0:
                u, v = 1 - u, 1 - v
            pts.append((1 - u - v) * _A + u * _B + v * _C)
    return np.array(pts[:n_pts])

def _anneal(n_pts: int = 11,
            max_iter: int = 15000,
            start_temp: float = 0.2,
            end_temp: float = 1e-10,
            seed: int | None = None) -> np.ndarray:

    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _initial_configuration(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    no_improve = 0
    max_no_improve = 500

    for t in range(max_iter):
        T = start_temp * math.exp(math.log(end_temp/start_temp) * t/max_iter)
        step_size = 0.1 * (1 - 0.9 * t/max_iter)

        idx = random.randrange(n_pts)
        trial = pts.copy()

        if t % 200 == 0:
            trial = _initial_configuration(n_pts)
        elif t % 50 == 0:
            trial[idx] = _random_point()
        else:
            perturbation = np.random.normal(0, step_size, 2)
            trial[idx] += perturbation
            trial[idx] = _project_to_simplex(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or random.random() < math.exp(delta / max(T, 1e-12)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()
                no_improve = 0
            else:
                no_improve += 1
        else:
            no_improve += 1

        if no_improve >= max_no_improve:
            break

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, max_iter=15000, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

