import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5 / TRIANGLE_AREA

def _min_triangle_area(pts: np.ndarray) -> float:
    min_area = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

def _is_in_triangle(x: float, y: float) -> bool:
    return y >= 0 and y <= SQRT3 * min(x, 1 - x) and x >= 0 and x <= 1

def _generate_initial_points(n: int) -> np.ndarray:
    pts = []
    layers = 6
    for layer in range(layers):
        for i in range(layer + 1):
            j = layer - i
            x = 0.5 + (i - j) * 0.5 / (layers - 1)
            y = j * SQRT3 / 2 / (layers - 1)
            if _is_in_triangle(x, y):
                pts.append([x, y])

    if len(pts) < n:
        for _ in range(n - len(pts)):
            x = random.uniform(0, 1)
            y_max = SQRT3 * min(x, 1 - x)
            y = random.uniform(0, y_max)
            pts.append([x, y])

    return np.array(pts[:n])

def _optimize_points(pts: np.ndarray, iterations: int = 2000) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)
    n = len(pts)
    temp = 1.0
    cooling_rate = temp / iterations

    for step in range(iterations):
        temp = 1.0 - step * cooling_rate
        new_pts = best_pts.copy()

        for _ in range(10):
            idx = random.randint(0, n-1)
            move = np.random.normal(0, 0.015 * temp, 2)
            new_pt = best_pts[idx] + move
            x, y = new_pt

            if _is_in_triangle(x, y):
                new_pts[idx] = new_pt
                break

        new_area = _min_triangle_area(new_pts)

        if new_area > best_area or (temp > 0 and random.random() < math.exp((new_area - best_area)/temp)):
            best_area = new_area
            best_pts = new_pts.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _generate_initial_points(11)
    pts = _optimize_points(pts)

    # Final validation and fallback
    valid = True
    for x, y in pts:
        if not _is_in_triangle(x, y):
            valid = False
            break

    if not valid:
        pts = np.array([
