def _area_matrix(pts: np.ndarray) -> np.ndarray:
    n = len(pts)
    areas = np.zeros((n, n, n))
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                areas[i,j,k] = abs(np.cross(pts[j]-pts[i], pts[k]-pts[i])) * 0.5
    return areas

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                area = abs(np.cross(pts[j]-pts[i], pts[k]-pts[i])) * 0.5
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0
    return min_area

def _random_point() -> np.ndarray:
    u, v = random.random(), random.random()
    if u + v > 1.0:
        u, v = 1 - u, 1 - v
    return (1 - u - v) * _A + u * _B + v * _C

def _grid_points(n: int) -> np.ndarray:
    k = math.ceil(math.sqrt(n * 2 / SQRT3))
    points = []
    for i in range(k):
        y = (i + 0.5) * SQRT3 / (2 * k)
        x_start = 0.5 - (i + 0.5) / (2 * k)
        x_step = (1 + i / k) / k
        for j in range(k - i):
            x = x_start + j * x_step
            points.append(np.array([x, y]))
    return np.array(points[:n])

