    pts = _grid_points(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        T = max(0.01, 0.1 * (1 - t/iters))
        idx = random.randrange(n_pts)
        trial = pts.copy()
        step = 0.01 * (1 - t/iters)
        trial[idx] += random.uniform(-step, step), random.uniform(-step, step)

        u, v = trial[idx][0], trial[idx][1]
        if v < 0 or v > SQRT3/2 or u < v/SQRT3 or u > 1 - v/SQRT3:
