    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best < 1e-8:
                        return best
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _hexagonal_points(n: int) -> np.ndarray:
    points = []
    k = int(math.sqrt(n)) + 1
    for i in range(k):
        for j in range(k - i):
            u = (i + 0.5 * j) / k
            v = (j * SQRT3 / 2) / k
            points.append((1 - u - v) * _A + u * _B + v * _C)
    return np.array(points[:n])

def _is_in_triangle(p: np.ndarray) -> bool:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    return u >= -1e-10 and v >= -1e-10 and (u + v) <= 1.0 + 1e-10

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _optimize(pts: np.ndarray, max_iter: int = 1000, step_size: float = 0.02) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    n = len(pts)

    for _ in range(max_iter):
