    return (1 - u - v) * _A + u * _B + v * _C

def _hexagonal_configuration(n_pts: int = 11) -> np.ndarray:
    pts = []
    layers = math.ceil((n_pts / 3)**0.5)
    for i in range(layers):
        for j in range(layers):
            if len(pts) >= n_pts:
                break
            x = 0.1 + 0.8 * i / (layers - 1)
            y = 0.1 + 0.8 * j / (layers - 1)
            pts.append((x, y * SQRT3/2))
    while len(pts) < n_pts:
        pts.append(_random_point())
    return np.array(pts)

def _anneal(n_pts: int = 11, seed: int | None = None) -> np.ndarray:
    if seed is not None:
        random.seed(seed)
    pts = _hexagonal_configuration(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(10000):
        T = 0.1 * (0.999 ** t)
        step = 0.05 * (1 - t/10000) + 0.001
        idx = random.randrange(n_pts)
        trial = pts.copy()
        trial[idx] += random.uniform(-step, step), random.uniform(-step, step)
        trial[idx] = _project_to_simplex(trial[idx])

