import math
import random
import itertools
from typing import List, Tuple
import numpy as np

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p, q, r) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5 / TRIANGLE_AREA

comb = list(itertools.combinations(range(11), 3))

def _min_triangle_area(pts: np.ndarray) -> float:
    min_area = float('inf')
    for i, j, k in comb:
        a = _area(pts[i], pts[j], pts[k])
        if a < min_area:
            min_area = a
            if min_area == 0:
                break
    return min_area

def _random_barycentric() -> Tuple[float, float, float]:
    u, v = random.random(), random.random()
    if u + v > 1:
        u, v = 1 - u, 1 - v
    return (1 - u - v, u, v)

def _barycentric_to_cartesian(b) -> np.ndarray:
    return np.array([0.5 * b[1] + 0.5 * b[2], SQRT3 / 2 * b[2]])

def _cartesian_to_barycentric(p) -> Tuple[float, float, float]:
    y = p[1] * 2 / SQRT3
    x = p[0] - y * 0.5
    return (1 - x - y, x, y)

def _project_to_triangle(p) -> np.ndarray:
    b = _cartesian_to_barycentric(p)
    b = np.maximum(b, 0)
    b /= b.sum()
    return _barycentric_to_cartesian(b)

def _initial_configuration() -> np.ndarray:
    pts = []
    # Add vertices
    pts.append(np.array([0.0, 0.0]))
    pts.append(np.array([1.0, 0.0]))
    pts.append(np.array([0.5, SQRT3/2]))

    # Add symmetric points
    for _ in range(8):
        while True:
            b = _random_barycentric()
            pt = _barycentric_to_cartesian(b)
            if all(not np.allclose(pt, p) for p in pts):
                pts.append(pt)
                break
    return np.array(pts)

def _get_worst_point(pts: np.ndarray) -> int:
    min_areas = np.full(len(pts), float('inf'))
    for i, j, k in comb:
        a = _area(pts[i], pts[j], pts[k])
        if a < min_areas[i]:
            min_areas[i] = a
        if a < min_areas[j]:
            min_areas[j] = a
        if a < min_areas[k]:
            min_areas[k] = a
    return np.argmin(min_areas)

def _optimize(pts: np.ndarray, iters: int, temp: float, cooling_rate: float) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    current_temp = temp

    for t in range(iters):
        idx = _get_worst_point(pts) if t % 5 == 0 else random.randrange(len(pts))
        trial = pts.copy()

        b = _cartesian_to_barycentric(trial[idx])
        perturbation = np.random.normal(0, current_temp, 2)
        new_b = np.clip(b + [perturbation[0], perturbation[1], -perturbation[0]-perturbation[1]], 0, 1)
        new_b /= new_b.sum()
        trial[idx] = _barycentric_to_cartesian(new_b)

        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or math.exp(delta / max(current_temp, 1e-12)) > random.random():
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

        current_temp *= cooling_rate

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    pts = _initial_configuration()
    pts = _optimize(pts, iters=30000, temp=0.1, cooling_rate=0.9999)
    pts = _optimize(pts, iters=10000, temp=0.01, cooling_rate=0.9995)

    return [(float(x), float(y)) for x, y in pts]

import math
import numpy as np
from scipy.optimize import differential_evolution
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p, q, r):
    return abs(np.cross(q - p, r - p)) * 0.5 / TRIANGLE_AREA

def _min_triangle_area(pts):
    pts = pts.reshape(-1, 2)
    n = len(pts)
    min_area = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

def _constraint(x):
    pts = x.reshape(-1, 2)
    for pt in pts:
        x, y = pt
        if y < 0 or y > SQRT3/2:
            return -1
        if x < max(0, y/SQRT3 - 1e-8) or x > min(1, 1 - y/SQRT3 + 1e-8):
            return -1
    return 1

def objective(x):
    if _constraint(x) < 0:
        return 0
    return -_min_triangle_area(x)

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    bounds = [(0.0, 1.0), (0.0, SQRT3/2)] * 11
    result = differential_evolution(
        objective,
        bounds,
        strategy='best1bin',
        maxiter=100,
        popsize=15,
        tol=1e-8,
        mutation=(0.5, 1.0),
        recombination=0.7,
        seed=seed,
        polish=False,
        updating='immediate'
    )
    pts = result.x.reshape(-1, 2)
    return [(float(x), float(y)) for x, y in pts]

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area_fast(pts: np.ndarray) -> float:
    n = len(pts)
    best = float('inf')
    # Check triangles with nearby points first
    for i in range(n):
        for j in range(i+1, min(i+6, n)):
            for k in range(j+1, min(j+6, n)):
                a = _area(pts[i], pts[j], pts[k])
                if a < best and a > 1e-8:
                    best = a
                    if best < 0.01:  # Early exit if too small
                        return best
    return best

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    if u >= 0 and v >= 0 and (u + v) <= 1:
        return p
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _initialize_hexagonal(n: int = 11) -> np.ndarray:
    pts = []
    # Hexagonal grid points
    layers = 3
    for layer in range(layers):
        for i in range(layer + 1):
            j = layer - i
            if i <= layers and j <= layers:
                x = 0.5 * i + 0.5 * j / 2
                y = SQRT3 * j / 2
                if x <= 1 and y <= SQRT3/2 and (1 - x - y/SQRT3) >= 0:
                    pts.append(np.array([x, y]))

    # Add center points if needed
    if len(pts) < n:
        pts.append((_A + _B + _C) / 3)
    if len(pts) < n:
        pts.append((_A + _B) / 2)
    if len(pts) < n:
        pts.append((_A + _C) / 2)
    if len(pts) < n:
        pts.append((_B + _C) / 2)

    # Fill remaining with optimized positions
    while len(pts) < n:
        u = random.random()
        v = random.random() * (1 - u)
        pts.append((1 - u - v) * _A + u * _B + v * _C)

    return np.array(pts[:n])

def _optimize_points_fast(pts: np.ndarray, max_iter: int = 1000) -> np.ndarray:
    n = len(pts)
    best_pts = pts.copy()
    best_score = _min_triangle_area_fast(best_pts)
    no_improve = 0

    for iter in range(max_iter):
        if no_improve > 50 and iter > max_iter//2:
            break

        step = 0.05 * (1 - iter/max_iter)
        idx = random.randrange(n)

        for _ in range(5):
            trial = best_pts.copy()
            trial[idx] += random.uniform(-step, step), random.uniform(-step, step)
            trial[idx] = _project_to_simplex(trial[idx])

            current_score = _min_triangle_area_fast(trial)
            if current_score > best_score:
                best_score = current_score
                best_pts = trial.copy()
                no_improve = 0
            else:
                no_improve += 1

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    pts = _initialize_hexagonal(11)
    pts = _optimize_points_fast(pts, 800)

    return [(float(x), float(y)) for x, y in pts]

import math
import random
import numpy as np
from itertools import combinations
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRI_AREA = 0.5 * SQRT3 / 2.0

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5 / TRI_AREA

def _min_triangle_area(pts):
    min_area = float('inf')
    n = len(pts)
    for i in range(n-2):
        for j in range(i+1, n-1):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

def _is_in_triangle(p):
    x, y = p
    return (x >= 0) and (y >= 0) and (x + y/SQRT3 <= 1.0) and (x - y/SQRT3 <= 0.0) and (y <= SQRT3/2)

def _project_to_triangle(p):
    x, y = p
    # Ensure positive coordinates first
    x = max(0.0, x)
    y = max(0.0, y)
    # Project to y boundary
    y = min(y, SQRT3/2)
    # Project to left boundary
    if x - y/SQRT3 > 0:
        x = y/SQRT3
    # Project to right boundary
    if x + y/SQRT3 > 1:
        x = 1 - y/SQRT3
    return np.array([x, y])

def _initialize_points(n):
    points = []
    # Use hexagonal lattice pattern
    layers = 4
    for i in range(layers + 1):
        for j in range(layers + 1 - i):
            x = (i + 0.5 * j) / layers
            y = (SQRT3/2) * j / layers
            points.append([x, y])
    # Ensure we have at least n points
    while len(points) < n:
        x = random.uniform(0, 1)
        y = random.uniform(0, SQRT3/2)
        if _is_in_triangle((x, y)):
            points.append([x, y])
    # Select n points closest to center
    center = np.array([0.5, SQRT3/4])
    points = sorted(points, key=lambda p: np.linalg.norm(np.array(p)-center))[:n]
    return np.array(points)

def _get_worst_triangle_indices(pts, k=1):
    min_area = float('inf')
    worst_indices = None
    n = len(pts)
    for i in range(n-2):
        for j in range(i+1, n-1):
            for m in range(j+1, n):
                a = _area(pts[i], pts[j], pts[m])
                if a < min_area:
                    min_area = a
                    worst_indices = (i, j, m)
                    if min_area == 0:
                        return [worst_indices]
    return [worst_indices] if worst_indices else []

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    pts = _initialize_points(11)
    best_pts = pts.copy()
    best_area = _min_triangle_area(pts)

    # Simulated annealing phase
    for t in range(2000):
        T = max(0.001, 0.1 * (0.001/0.1) ** (t/1999))
        step = 0.03 * (1 - t/2000)

        # Perturb points in worst triangles
        worst_tris = _get_worst_triangle_indices(pts)
        if not worst_tris:
            continue
        idx = random.choice(worst_tris[0])

        new_pts = pts.copy()
        perturbation = np.random.uniform(-step, step, size=2)
        new_pts[idx] += perturbation
        new_pts[idx] = _project_to_triangle(new_pts[idx])

        new_area = _min_triangle_area(new_pts)
        if new_area > best_area or (T > 0 and random.random() < math.exp((new_area - best_area)/T)):
            pts = new_pts
            if new_area > best_area:
                best_area = new_area
                best_pts = new_pts.copy()

    # Local optimization phase
    for _ in range(300):
        worst_tris = _get_worst_triangle_indices(best_pts)
        if not worst_tris:
            break
        i, j, k = worst_tris[0]
        centroid = (best_pts[i] + best_pts[j] + best_pts[k]) / 3
        for idx in [i, j, k]:
            new_pts = best_pts.copy()
            new_pts[idx] = 0.9 * new_pts[idx] + 0.1 * centroid
            new_pts[idx] = _project_to_triangle(new_pts[idx])
            new_area = _min_triangle_area(new_pts)
            if new_area > best_area:
                best_area = new_area
                best_pts = new_pts.copy()

    return [(float(x), float(y)) for x, y in best_pts]

