import math
import random
import numpy as np
try:
    from scipy.optimize import minimize
except ImportError:
    minimize = None

SQRT3 = math.sqrt(3.0)
_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    best = float("inf")
    n = len(pts)
    for i in range(n):
        for j in range(i+1, min(i+10, n)):  # Limit j range
            for k in range(j+1, min(j+10, n)):  # Limit k range
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best < 1e-6:
                        return best
    return best

def _random_point() -> np.ndarray:
    u, v = random.random(), random.random()
    if u + v > 1.0:
        u, v = 1-u, 1-v
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _initial_configuration(n_pts: int) -> np.ndarray:
    pts = []
    layers = int(math.sqrt(n_pts)) + 1
    for i in range(layers):
        for j in range(layers - i):
            u = (i + 0.5) / layers
            v = (j + 0.5) / layers
            if len(pts) < n_pts:
                pts.append((1 - u - v) * _A + u * _B + v * _C)
    while len(pts) < n_pts:
        pts.append(_random_point())
    return np.array(pts)

def _anneal(n_pts: int = 11, iters: int = 1000, restarts: int = 2, seed: int = 0) -> np.ndarray:
    rng = random.Random(seed)
    best_pts = _initial_configuration(n_pts)
    best_val = _min_triangle_area(best_pts)

    for _ in range(restarts):
        pts = _initial_configuration(n_pts)
        current_val = _min_triangle_area(pts)

        for t in range(iters):
            T = max(0.01, 0.1 * (1 - t/iters))
            step_size = 0.05 * T

            idx = rng.randrange(n_pts)
            trial = pts.copy()
            trial[idx] += rng.uniform(-step_size, step_size), rng.uniform(-step_size, step_size)
            trial[idx] = _project_to_simplex(trial[idx])

            trial_val = _min_triangle_area(trial)
            delta = trial_val - current_val

            if delta > 0 or rng.random() < math.exp(delta / max(T, 1e-12)):
                pts = trial
                current_val = trial_val

                if current_val > best_val:
                    best_val = current_val
                    best_pts = pts.copy()

    return best_pts

def _local_polish(pts: np.ndarray) -> np.ndarray:
    if minimize is None or len(pts) == 0:
        return pts
    n_pts = len(pts)
    x0 = pts.ravel()

    def f(x: np.ndarray) -> float:
        P = x.reshape((-1, 2))
        return -_min_triangle_area(P)

    res = minimize(f, x0, method='Nelder-Mead', options={'maxiter': 200})
    if res.success:
        out = res.x.reshape((n_pts, 2))
        for i in range(n_pts):
            out[i] = _project_to_simplex(out[i])
        return out
    return pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=1000, restarts=2, seed=seed)
    pts = _local_polish(pts)
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4

def _is_in_triangle(x: float, y: float) -> bool:
    return (y >= 0) and (y <= SQRT3*(1 - abs(2*x - 1)))

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / (2 * TRIANGLE_AREA)

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n-2):
        for j in range(i+1, n-1):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

def _initialize_points(n: int) -> np.ndarray:
    pts = []
    size = int(math.ceil(math.sqrt(n * 2 / SQRT3)))

    for i in range(size):
        for j in range(size):
            if len(pts) >= n:
                break
            x = 0.5 + (i - j) * 0.5 / size
            y = j * SQRT3 / 2 / size
            if _is_in_triangle(x, y):
                pts.append([x, y])

    while len(pts) < n:
        x = random.uniform(0, 1)
        y_max = SQRT3 * (1 - abs(2*x - 1))
        y = random.uniform(0, y_max)
        pts.append([x, y])

    pts = np.array(pts)
    for i in range(len(pts)):
        x, y = pts[i]
        if not _is_in_triangle(x, y):
            y = min(y, SQRT3*(1 - abs(2*x - 1)))
            pts[i][1] = max(y, 0)
    return pts

def _optimize_points(pts: np.ndarray, iterations: int = 1000) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)
    n = len(pts)

    for step_num in range(iterations):
        temp = 1.0 - step_num / iterations
        step_size = 0.1 * temp

        for _ in range(n):
            idx = random.randint(0, n-1)
            new_pts = best_pts.copy()

            for _ in range(10):  # Try up to 10 times to find valid position
                dx = random.uniform(-step_size, step_size)
                dy = random.uniform(-step_size, step_size)
                new_x = best_pts[idx][0] + dx
                new_y = best_pts[idx][1] + dy
                if _is_in_triangle(new_x, new_y):
                    new_pts[idx] = [new_x, new_y]
                    break

            new_area = _min_triangle_area(new_pts)
            if new_area > best_area:
                best_area = new_area
                best_pts = new_pts.copy()

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _initialize_points(11)
    pts = _optimize_points(pts, 1000)

    # Final verification
    for i in range(len(pts)):
        x, y = pts[i]
        if not _is_in_triangle(x, y):
            y = min(y, SQRT3*(1 - abs(2*x - 1)))
            pts[i][1] = max(y, 0)

    return [(float(x), float(y)) for x, y in pts]

from __future__ import annotations

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    best = float("inf")
    n = len(pts)
    for i in range(n):
        for j in range(i+1, min(i+6, n)):
            for k in range(j+1, min(j+6, n)):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _initial_configuration(n_pts: int = 11) -> np.ndarray:
    pts = []
    # Hexagonal grid with more layers
    layers = 3
    for i in range(layers):
        for j in range(layers):
            if i + j < layers:
                u = (i + 0.5) / layers
                v = (j + 0.5) / layers
                pts.append((1 - u - v) * _A + u * _B + v * _C)
    # Add random points with minimum distance
    while len(pts) < n_pts:
        p = _random_point()
        if all(np.linalg.norm(p - q) > 0.1 for q in pts):
            pts.append(p)
    return np.array(pts[:n_pts])

def _parallel_tempering(n_pts: int = 11, 
                       n_chains: int = 4, 
                       iters: int = 2000,
                       seed: int | None = 0) -> np.ndarray:
    rng = random.Random(seed)
    chains = [_initial_configuration(n_pts) for _ in range(n_chains)]
    temps = [0.1 * (1.5 ** i) for i in range(n_chains)]
    best_pts = chains[0].copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        for i in range(n_chains):
            step_size = 0.05 * (1 - (t/iters)) + 0.01
            idx = rng.randrange(n_pts)
            trial = chains[i].copy()
            trial[idx] += rng.uniform(-step_size, step_size), rng.uniform(-step_size, step_size)
            trial[idx] = _project_to_simplex(trial[idx])
            trial_val = _min_triangle_area(trial)
            delta = (trial_val - _min_triangle_area(chains[i])) / temps[i]

            if delta > 0 or rng.random() < math.exp(delta):
                chains[i] = trial
                if trial_val > best_val:
                    best_val = trial_val
                    best_pts = trial.copy()

        if t % 100 == 0 and t > 0:
            i, j = rng.sample(range(n_chains), 2)
            val_i = _min_triangle_area(chains[i]))
            val_j = _min_triangle_area(chains[j]))
            delta = (val_j - val_i) * (1/temps[i] - 1/temps[j])
            if delta > 0 or rng.random() < math.exp(delta):
                chains[i], chains[j] = chains[j], chains[i]

    return best_pts

def _gradient_optimize(pts: np.ndarray, steps: int = 500) -> np.ndarray:
    n = len(pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for _ in range(steps):
        grad = np.zeros_like(pts)
        min_areas = np.full(n, float('inf'))

        for i in range(n):
            for j in range(i+1, n):
                for k in range(j+1, n):
                    a = _area(pts[i], pts[j], pts[k])
                    if a < min_areas[i]:
                        min_areas[i] = a
                        grad[i] += (pts[j] - pts[i]) + (pts[k] - pts[i])
                    if a < min_areas[j]:
                        min_areas[j] = a
                        grad[j] += (pts[i] - pts[j]) + (pts[k] - pts[j])
                    if a < min_areas[k]:
                        min_areas[k] = a
                        grad[k] += (pts[i] - pts[k]) + (pts[j] - pts[k])

        step = 0.01 / (1 + _min_triangle_area(pts))
        trial = pts + step * grad
        for i in range(n):
            trial[i] = _project_to_simplex(trial[i])

        trial_val = _min_triangle_area(trial)
        if trial_val > best_val:
            best_val = trial_val
