import math
import itertools
from typing import List, Tuple
import numpy as np

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray, changed_idx: int = -1) -> float:
    min_area = float('inf')
    n = len(pts)

    if changed_idx == -1:
        for i in range(n):
            for j in range(i+1, n):
                for k in range(j+1, n):
                    a = _area(pts[i], pts[j], pts[k])
                    if a < min_area:
                        min_area = a
                        if min_area == 0:
                            return 0
    else:
        i = changed_idx
        for j in range(n):
            if j == i:
                continue
            for k in range(j+1, n):
                if k == i:
                    continue
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _hexagonal_points(n: int) -> np.ndarray:
    if n == 0:
        return np.array([])

    layers = 1
    while True:
        max_points = layers * (layers + 1) // 2
        if max_points >= n:
            break
        layers += 1

    pts = []
    for i in range(layers):
        for j in range(layers - i):
            x = 0.5 * i + j
            y = SQRT3 / 2 * i
            pts.append([x, y])

    pts = np.array(pts[:n])
    if len(pts) > 0:
        max_x = np.max(pts[:, 0])
        max_y = np.max(pts[:, 1])
        pts[:, 0] /= max_x
        pts[:, 1] /= max_y
        pts += np.random.normal(0, 0.001, pts.shape)  # Small random perturbation

    return pts

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    w = 1.0 - u - v
    if u >= 0 and v >= 0 and w >= 0:
        return p
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _anneal(n_pts: int = 11,
            iters: int = 15000,
            start_temp: float = 0.2,
            end_temp: float = 1e-8,
            initial_step: float = 0.1,
            final_step: float = 0.001,
            seed: int | None = 0) -> np.ndarray:
    np.random.seed(seed)
    pts = _hexagonal_points(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        T = start_temp * (end_temp / start_temp) ** (t / max(iters-1, 1))
        step = initial_step * (final_step / initial_step) ** (t / max(iters-1, 1))

        idx = np.random.randint(n_pts)
        trial = pts.copy()
        perturbation = np.random.normal(0, step, size=2)
        trial[idx] += perturbation
        trial[idx] = _project_to_simplex(trial[idx])

        trial_val = _min_triangle_area(trial, idx)
        delta = trial_val - best_val

        if delta > 0 or np.random.random() < math.exp(delta / max(T, 1e-12)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = pts.copy()

        if t % 1000 == 0:
            current_val = _min_triangle_area(pts)
            if current_val > best_val:
                best_val = current_val
                best_pts = pts.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=15000, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

