    pts = []
    size = int(math.ceil(math.sqrt(n)))
    for i in range(size):
        for j in range(size):
            if len(pts) >= n:
                break
            x = 0.5 + (i - j) * 0.5 / (size + 1)
            y = j * SQRT3 / 2 / (size + 1)
            if _is_in_triangle(x, y):
