    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _initial_configuration(n_pts: int = 11) -> np.ndarray:
    pts = []
    for i in range(n_pts):
        u = (i * 0.381966) % 1.0
        v = ((i + 0.5) * 0.381966) % 1.0
        if u + v > 1.0:
            u, v = 1-u, 1-v
        pts.append((1 - u - v) * _A + u * _B + v * _C)
    return np.array(pts)

def _optimize(n_pts: int = 11, max_iters: int = 5000, seed: int | None = 0) -> np.ndarray:
    random.seed(seed)
    pts = _initial_configuration(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    no_improve = 0

    for t in range(max_iters):
        T = 0.1 * (0.999 ** t)
