def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area_fast(pts: np.ndarray) -> float:
    n = len(pts)
    best = float('inf')
    for i in range(n):
        for j in range(i+1, min(i+6, n)):
            for k in range(j+1, min(j+6, n)):
                a = _area(pts[i], pts[j], pts[k])
                if a < best and a > 1e-8:
                    best = a
                    if best < 0.01:
                        return best
    return best

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    if u >= 0 and v >= 0 and (u + v) <= 1:
        return p
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _initialize_hexagonal(n: int = 11) -> np.ndarray:
    pts = []
    layers = 3
    for layer in range(layers):
        for i in range(layer + 1):
            j = layer - i
            x = 0.5 * i + 0.5 * j / 2
            y = SQRT3 * j / 2
            # Check if point is inside the triangle
            if y <= SQRT3/2 and (1 - x - y/SQRT3) >= 0 and x >= 0:
                pts.append(np.array([x, y]))

    # Add center points if needed
    if len(pts) < n:
        pts.append((_A + _B + _C) / 3)
    if len(pts) < n:
        pts.append((_A + _B) / 2)
    if len(pts) < n:
        pts.append((_A + _C) / 2)
    if len(pts) < n:
        pts.append((_B + _C) / 2)

    # Fill remaining with random points inside triangle
    while len(pts) < n:
        u = random.random()
        v = random.random() * (1 - u)
        pts.append((1 - u - v) * _A + u * _B + v * _C)

    return np.array(pts[:n])

def _optimize_points_fast(pts: np.ndarray, max_iter: int = 1000) -> np.ndarray:
    n = len(pts)
    best_pts = pts.copy()
    best_score = _min_triangle_area_fast(best_pts)
    no_improve = 0

    for iter in range(max_iter):
        if no_improve > 50 and iter > max_iter//2:
            break

        step = 0.05 * (1 - iter/max_iter)
        idx = random.randrange(n)

        for _ in range(5):
            trial = best_pts.copy()
            trial[idx] += random.uniform(-step, step), random.uniform(-step, step)
            trial[idx] = _project_to_simplex(trial[idx])

            current_score = _min_triangle_area_fast(trial)
            if current_score > best_score:
                best_score = current_score
                best_pts = trial.copy()
                no_improve = 0
            else:
                no_improve += 1

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    pts = _initialize_hexagonal(11)
    pts = _optimize_points_fast(pts, 800)

    return [(float(x), float(y)) for x, y in pts]

import math
import random
import numpy as np
from itertools import combinations

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / 2.0

def _min_triangle_area(pts):
    min_area = float('inf')
    n = len(pts)
    # Check only nearby points to reduce computations
    for i in range(n):
        for j in range(i+1, min(i+5, n)):
            for k in range(j+1, min(j+5, n)):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area < 1e-8:
                        return min_area
    return min_area

def _is_in_triangle(p):
    x, y = p
    if x < 0 or x > 1 or y < 0 or y > SQRT3/2:
        return False
    if y > SQRT3 * x:
        return False
    if y > SQRT3 * (1 - x):
        return False
    return True

def _generate_initial_points(n):
    # Optimized initial configuration for n=11
    base_points = [
        [0.1, 0.05], [0.9, 0.05],  # Bottom corners
        [0.2, 0.15], [0.8, 0.15],   # Middle bottom
        [0.3, 0.3], [0.7, 0.3],     # Middle
        [0.4, 0.45], [0.6, 0.45],    # Middle top
        [0.5, 0.6],                  # Center top
        [0.2, 0.45], [0.8, 0.45]     # Side points
    ]
    points = []
    for p in base_points[:n]:
        x = p[0] + random.uniform(-0.02, 0.02)
        y = p[1] + random.uniform(-0.02, 0.02)
        if _is_in_triangle((x, y)):
            points.append([x, y])
        else:
            points.append(p.copy())
    return np.array(points)

def _optimize_points(points, iterations):
    best_points = points.copy()
    best_score = _min_triangle_area(best_points)

    for i in range(iterations):
        new_points = best_points.copy()
        idx = i % len(points)

        # Adaptive step size based on current best score
        step = max(0.01, 0.05 * (1 - i/iterations))

        # Try multiple perturbation directions
        for _ in range(3):
            temp_points = new_points.copy()
            temp_points[idx] += np.random.uniform(-step, step, 2)
            if _is_in_triangle(temp_points[idx]):
                temp_score = _min_triangle_area(temp_points)
                if temp_score > best_score:
                    best_score = temp_score
                    new_points = temp_points.copy()
                    break

    return best_points

def find_points(seed=None):
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    points = _generate_initial_points(11)
    points = _optimize_points(points, 4000)  # More iterations within time limit

    return [(float(p[0]), float(p[1])) for p in points]

