import math
import random
import itertools
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRI_AREA = SQRT3 / 4.0

def _area(p, q, r) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / (2 * TRI_AREA)

def _min_triangle_area(pts: np.ndarray) -> float:
    min_area = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

def _random_barycentric() -> Tuple[float, float, float]:
    u, v = random.random(), random.random()
    if u + v > 1:
        u, v = 1 - u, 1 - v
    return (1 - u - v, u, v)

def _barycentric_to_cartesian(b: Tuple[float, float, float]) -> Tuple[float, float]:
    x = 0.5 * b[1] + 0.5 * b[2]
    y = (SQRT3 / 2) * b[2]
    return (x, y)

def _initial_configuration() -> np.ndarray:
    # Based on known good configurations
    bary = [
        (1, 0, 0), (0, 1, 0), (0, 0, 1),
        (0.5, 0.5, 0), (0.5, 0, 0.5), (0, 0.5, 0.5),
        (1/3, 1/3, 1/3),
        (0.25, 0.5, 0.25), (0.5, 0.25, 0.25),
        (0.25, 0.25, 0.5), (0.2, 0.4, 0.4)
    ]
    return np.array([_barycentric_to_cartesian(b) for b in bary])

def _perturb_barycentric(b: Tuple[float, float, float], scale: float) -> Tuple[float, float, float]:
    u, v, w = b
    du = random.uniform(-scale, scale)
    dv = random.uniform(-scale, scale)
    u_new = max(0, min(1, u + du))
    v_new = max(0, min(1, v + dv))
    w_new = max(0, min(1, 1 - u_new - v_new))
    # Renormalize
    s = u_new + v_new + w_new
    return (u_new/s, v_new/s, w_new/s)

def _optimize(initial: np.ndarray, steps: int = 5000) -> np.ndarray:
    current = np.array([_random_barycentric() for _ in range(11)])
    best = current.copy()
    best_val = _min_triangle_area(np.array([_barycentric_to_cartesian(b) for b in best]))

    for step in range(steps):
        scale = 0.1 * (1 - step/steps)
        trial = current.copy()
        idx = random.randrange(11)
        trial[idx] = _perturb_barycentric(trial[idx], scale)

        cartesian = np.array([_barycentric_to_cartesian(b) for b in trial])
        trial_val = _min_triangle_area(cartesian)

        if trial_val > best_val:
            best_val = trial_val
            best = trial.copy()
            current = trial.copy()

    return np.array([_barycentric_to_cartesian(b) for b in best])

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
    initial = _initial_configuration()
    optimized = _optimize(initial, steps=10000)
    return [(float(x), float(y)) for x, y in optimized]

from __future__ import annotations

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0  # Area of unit equilateral triangle

def _is_inside_triangle(p: np.ndarray) -> bool:
    x, y = p
    if y < 0 or y > SQRT3/2:
        return False
    if x < 0 or x > 1:
        return False
    if y > SQRT3 * x or y > SQRT3 * (1 - x):
        return False
    return True

def _random_point() -> np.ndarray:
    while True:
        x = random.random()
        y = random.random() * SQRT3/2
        if _is_inside_triangle(np.array([x, y])):
            return np.array([x, y])

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    x, y = p
    # Check if already inside
    if _is_inside_triangle(p):
        return p

    # Project to closest point on triangle boundary
    if y < 0:
        y = 0
    elif y > SQRT3/2:
        y = SQRT3/2

    if x < 0:
        x = 0
    elif x > 1:
        x = 1

    # Check edges
    if y > SQRT3 * x:
        # Project to left edge
        y = SQRT3 * x
    elif y > SQRT3 * (1 - x):
        # Project to right edge
        y = SQRT3 * (1 - x)

    return np.array([x, y])

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')

    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                x1, y1 = pts[i]
                x2, y2 = pts[j]
                x3, y3 = pts[k]
                area = abs((x2-x1)*(y3-y1) - (x3-x1)*(y2-y1)) / 2.0
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0.0
    return min_area / TRIANGLE_AREA

def _initialize_points(n: int) -> np.ndarray:
    # Hexagonal grid initialization
    k = math.ceil(math.sqrt(n / (SQRT3/2)))
    pts = []
    for i in range(k):
        for j in range(k):
            x = (0.5 + j) / k
            y = (0.5 + i * SQRT3/2) / (k * SQRT3/2)
            if y <= SQRT3 * (1 - x):
                pts.append([x, y])
                if len(pts) == n:
                    return np.array(pts)

    # Fill remaining with random points
    while len(pts) < n:
        pts.append(_random_point())
    return np.array(pts)

def _optimize_points(pts: np.ndarray, iterations: int = 5000) -> np.ndarray:
    n = len(pts)
    best_pts = pts.copy()
    best_score = _min_triangle_area(best_pts)

    for _ in range(iterations):
        temp = 0.1 * (1 - _ / iterations)
        step = 0.05 * (1 - _ / iterations)

        # Perturb each point
        trial_pts = best_pts.copy()
        for i in range(n):
            angle = random.uniform(0, 2*math.pi)
            dx = step * math.cos(angle)
            dy = step * math.sin(angle)
            trial_pts[i] += np.array([dx, dy])
            trial_pts[i] = _project_to_triangle(trial_pts[i])

        trial_score = _min_triangle_area(trial_pts)

        if trial_score > best_score or random.random() < math.exp((trial_score - best_score)/temp):
            best_score = trial_score
            best_pts = trial_pts.copy()

    # Local refinement
    for _ in range(1000):
        improved = False
        for i in np.random.permutation(n):
            for angle in np.linspace(0, 2*math.pi, 12, endpoint=False):
                step = 0.01
                dx = step * math.cos(angle)
                dy = step * math.sin(angle)
                trial_pts = best_pts.copy()
                trial_pts[i] += np.array([dx, dy])
                trial_pts[i] = _project_to_triangle(trial_pts[i])
                trial_score = _min_triangle_area(trial_pts)
                if trial_score > best_score:
                    best_score = trial_score
                    best_pts = trial_pts.copy()
                    improved = True
                    break
            if improved:
                break
        if not improved:
            break

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _initialize_points(11)
    pts = _optimize_points(pts, 10000)

    # Final validation
    for p in pts:
        if not _is_inside_triangle(p):
            p = _project_to_triangle(p)

    return [(float(p[0]), float(p[1])) for p in pts]

