import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    best = float("inf")
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _initialize_points(n_pts: int) -> np.ndarray:
    pts = []
    for _ in range(n_pts):
        pts.append(_project_to_simplex(_random_point()))
    return np.array(pts)

def _anneal(n_pts: int = 11,
            iters: int = 10000,
            start_temp: float = 0.2,
            end_temp: float = 1e-6,
            step_size: float = 0.02,
            seed: int | None = None) -> np.ndarray:
    rng = random.Random(seed)
    pts = _initialize_points(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    no_improve = 0

    for t in range(iters):
        if no_improve > 500:
            break
        T = start_temp * (end_temp / start_temp) ** (t / (iters - 1))
        current_step = step_size * (1 - t/iters)
        idx = rng.randrange(n_pts)
        trial = pts.copy()
        if t % 100 == 0:
            trial[idx] = _project_to_simplex(_random_point())
        else:
            trial[idx] += rng.uniform(-current_step, current_step), rng.uniform(-current_step, current_step)
            trial[idx] = _project_to_simplex(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or rng.random() < math.exp(delta / max(T, 1e-12)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()
                no_improve = 0
            else:
                no_improve += 1

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=10000, seed=seed)
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

import math
import random
import numpy as np
from itertools import combinations

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / 2.0

def _min_triangle_area(pts):
    min_area = float('inf')
    for trio in combinations(pts, 3):
        a = _area(*trio)
        if a < min_area:
            min_area = a
            if min_area < 1e-8:
                return min_area
    return min_area

def _is_in_triangle(p):
    x, y = p
    if x < 0 or x > 1 or y < 0 or y > SQRT3/2:
        return False
    if y > SQRT3 * x:
        return False
    if y > SQRT3 * (1 - x):
        return False
    return True

def _generate_initial_points(n):
    points = []
    # Improved hexagonal grid with more coverage
    grid_size = 0.18
    for i in range(6):
        for j in range(6):
            if i + j <= 5:
                x = 0.1 + i * grid_size + j * grid_size/2
                y = SQRT3/2 * 0.1 + j * grid_size * SQRT3/2
                if _is_in_triangle((x, y)):
                    points.append([x, y])

    # Add some random points with better distribution
    while len(points) < n:
        if len(points) < n:
            x = random.uniform(0.1, 0.9)
            y = random.uniform(0.1, 0.8 * SQRT3/2)
            if _is_in_triangle((x, y)) and all(math.hypot(x-p[0], y-p[1]) > 0.1 for p in points):
                points.append([x, y])
        else:
            x = random.uniform(0, 1)
            y = random.uniform(0, SQRT3/2)
            if _is_in_triangle((x, y)):
                points.append([x, y])
    return np.array(points)

def _optimize_points(points, iterations):
    best_points = points.copy()
    best_score = _min_triangle_area(best_points)

    for i in range(iterations):
        new_points = best_points.copy()

        # More aggressive perturbation strategy
        if i % 50 == 0:
            # Try moving the point with smallest local area
            areas = []
            for j in range(len(points)):
                min_local = float('inf')
                for k, l in combinations([x for x in range(len(points)) if x != j], 2):
                    a = _area(points[j], points[k], points[l])
                    if a < min_local:
                        min_local = a
                areas.append(min_local)
            idx = np.argmin(areas)
            new_points[idx] = np.random.uniform(0, 1, 2)
            if not _is_in_triangle(new_points[idx]):
                continue

        # Normal optimization step with adaptive step size
        idx = random.randint(0, len(points)-1)
        step = 0.05 * (1 - (i/iterations)**2)  # Faster initial steps
        new_points[idx] += np.random.uniform(-step, step, 2)

        # Project back into triangle if needed
        if not _is_in_triangle(new_points[idx]):
            x, y = new_points[idx]
            x = max(0.01, min(0.99, x))
            y = max(0.01, min(SQRT3/2 - 0.01, y))
            if y > SQRT3 * x:
                y = SQRT3 * x - 0.01
            if y > SQRT3 * (1 - x):
                y = SQRT3 * (1 - x) - 0.01
            new_points[idx] = [x, y]

        new_score = _min_triangle_area(new_points)

        if new_score > best_score:
            best_score = new_score
            best_points = new_points.copy()

    return best_points

def find_points(seed=None):
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    points = _generate_initial_points(11)
    points = _optimize_points(points, 5000)  # More iterations

    return [(float(p[0]), float(p[1])) for p in points]

from __future__ import annotations
import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])
TRI_AREA = SQRT3 / 4.0

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n-2):
        for j in range(i+1, n-1):
            p0 = pts[i]
            p1 = pts[j]
            dx1 = p1[0] - p0[0]
            dy1 = p1[1] - p0[1]
            for k in range(j+1, n):
                dx2 = pts[k][0] - p0[0]
                dy2 = pts[k][1] - p0[1]
                area = abs(dx1*dy2 - dx2*dy1) * 0.5
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0
    return min_area

def _is_inside(p: np.ndarray) -> bool:
    try:
        u, v = np.linalg.solve(np.column_stack((_B-_A, _C-_A)), p-_A)
    except:
        return False
    return u >= -1e-8 and v >= -1e-8 and (1-u-v) >= -1e-8

def _generate_initial_points(n: int) -> np.ndarray:
    while True:
        pts = np.random.uniform(0, 1, (n, 2))
        pts[:, 1] *= SQRT3/2
        mask = np.array([_is_inside(p) for p in pts])
        if np.all(mask):
            return pts

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    u, v = np.linalg.solve(np.column_stack((_B-_A, _C-_A)), p-_A)
    u = max(0, min(1, u))
    v = max(0, min(1, v))
    if u + v > 1:
        u, v = u/(u+v), v/(u+v)
    return _A + u*(_B-_A) + v*(_C-_A)

def _differential_evolution(n_pts: int, max_iter: int) -> np.ndarray:
    pop_size = 10
    F = 0.8
    CR = 0.9

    pop = [_generate_initial_points(n_pts).flatten() for _ in range(pop_size)]
    best_sol = pop[0]
    best_val = -_min_triangle_area(best_sol.reshape(n_pts, 2))

    for _ in range(max_iter):
        for i in range(pop_size):
            idxs = [idx for idx in range(pop_size) if idx != i]
            a, b, c = [pop[idx] for idx in np.random.choice(idxs, 3, replace=False)]
            mutant = a + F * (b - c)

            cross_points = np.random.rand(n_pts*2) < CR
            trial = np.where(cross_points, mutant, pop[i])

            trial_pts = trial.reshape(n_pts, 2)
            for j in range(n_pts):
                if not _is_inside(trial_pts[j]):
                    trial_pts[j] = _project_to_triangle(trial_pts[j])

            trial_val = -_min_triangle_area(trial_pts)
            if trial_val < best_val:
                best_val = trial_val
                best_sol = trial.copy()
            if trial_val < -_min_triangle_area(pop[i].reshape(n_pts, 2)):
                pop[i] = trial

    return best_sol.reshape(n_pts, 2)

def _refine(pts: np.ndarray, steps: int) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    n_pts = len(pts)

    for step in range(steps):
        step_size = 0.01 * (1 - step/steps)
        for idx in range(n_pts):
            for _ in range(5):
                trial = best_pts.copy()
                delta = np.random.uniform(-step_size, step_size, 2)
                trial[idx] += delta
                if _is_inside(trial[idx]):
                    trial_val = _min_triangle_area(trial)
                    if trial_val > best_val:
                        best_val = trial_val
                        best_pts = trial.copy()
    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    pts = _differential_evolution(n_pts=11, max_iter=20)
    pts = _refine(pts, steps=50)

    return [(float(x), float(y)) for x, y in pts]

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5 / TRIANGLE_AREA

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    while True:
        u, v = np.random.random(2)
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _hex_grid_points(n: int) -> np.ndarray:
    pts = []
    k = 4  # Adjusted to generate at least 11 points
    for i in range(k):
        for j in range(k - i):
            x = i/k + j/(2*k)
            y = j * SQRT3/(2*k)
            pts.append([x, y])
            if len(pts) == n:
                return np.array(pts)
    return np.array(pts)

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    w = 1.0 - u - v
    if u >= 0 and v >= 0 and w >= 0:
        return p
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _optimize(pts: np.ndarray, n_iters: int = 500) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for _ in range(n_iters):
        improved = False
        for idx in range(len(pts)):
            for dx, dy in [(0.001,0), (-0.001,0), (0,0.001), (0,-0.001)]:
