TRIANGLE_AREA = SQRT3 / 4.0

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5 / TRIANGLE_AREA

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    best = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            p0 = pts[j] - pts[i]
            for k in range(j+1, n):
                p1 = pts[k] - pts[i]
                a = abs(p0[0]*p1[1] - p0[1]*p1[0]) * 0.5 / TRIANGLE_AREA
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _hex_grid_points(n: int) -> np.ndarray:
    pts = []
    k = int(math.sqrt(n)) + 2
    for i in range(k):
        for j in range(k):
            if i + j > k:
                continue
            u = (i + 0.5 * (j % 2)) / k
            v = j * SQRT3 / (2 * k)
            if u + v/SQRT3 <= 1.0 and v <= SQRT3/2:
                x = (1-u-v/SQRT3)*_A[0] + u*_B[0] + (v/(SQRT3/2))*_C[0]
                y = (1-u-v/SQRT3)*_A[1] + u*_B[1] + (v/(SQRT3/2))*_C[1]
                pts.append(np.array([x, y]))
                if len(pts) == n:
                    return np.array(pts)
    return np.array(pts[:n])

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    if u >= 0 and v >= 0 and (u + v) <= 1:
        return p
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _anneal(n_pts: int = 11, iters: int = 5000, seed: int | None = None) -> np.ndarray:
    rng = random.Random(seed)
    pts = _hex_grid_points(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        T = max(0.01, 1.0 - t/iters)
        trial = pts.copy()

        step_size = 0.05 * (1 - t/iters) + 0.01
        idx = rng.randint(0, n_pts-1)

