            trial[idx] = _hex_grid_points(1)[0]
        else:
            dx = rng.uniform(-step_size, step_size)
            dy = rng.uniform(-step_size, step_size)
            trial[idx] += np.array([dx, dy])
            trial[idx] = _project_to_simplex(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or rng.random() < math.exp(delta / T):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

        if t % 500 == 0 and t > 0:
            pts = best_pts.copy()
            for i in range(n_pts):
                if rng.random() < 0.3:
                    pts[i] += rng.uniform(-0.05, 0.05, 2)
                    pts[i] = _project_to_simplex(pts[i])

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=8000, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4

def _point_in_triangle(pt):
    x, y = pt
    return (0 <= x <= 1 and 0 <= y <= SQRT3/2 and 
            y <= SQRT3 * (1 - abs(2*x - 1)))

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / 2

def _min_triangle_area(pts):
    min_area = float('inf')
    n = len(pts)
    for i in range(n-2):
        for j in range(i+1, n-1):
            for k in range(j+1, n):
                area = _area(pts[i], pts[j], pts[k])
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0
    return min_area

def _generate_initial_points(n):
    points = []
    # Generate points in hexagonal pattern
    layers = int(math.ceil((n/3)**0.5)) + 1
    for layer in range(layers):
        y = layer * SQRT3 / (2*layers)
        x_start = 0.5 - layer/(2*layers)
        step = 1.0/layers if layer > 0 else 0
        for i in range(layer+1):
            x = x_start + i*step
            if _point_in_triangle((x, y)) and len(points) < n:
                points.append([x, y])

    # Fill remaining points with random valid points
    while len(points) < n:
        x = random.uniform(0, 1)
        y = random.uniform(0, SQRT3/2)
        if _point_in_triangle((x, y)):
            points.append([x, y])

    return np.array(points)

def _optimize_points(pts, max_iter=2000):
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)
    n = len(pts)

    for iteration in range(max_iter):
        improved = False
        step = 0.05 * (1 - iteration/max_iter)

        for idx in random.sample(range(n), n):
            original_pt = best_pts[idx].copy()

            for _ in range(10):
                new_pt = original_pt + np.random.uniform(-step, step, 2)
                if not _point_in_triangle(new_pt):
                    continue

                temp_pts = best_pts.copy()
                temp_pts[idx] = new_pt
                current_area = _min_triangle_area(temp_pts)

                if current_area > best_area:
                    best_area = current_area
                    best_pts = temp_pts.copy()
                    improved = True
                    break

        if not improved and iteration > max_iter//2:
            break

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _generate_initial_points(11)
    pts = _optimize_points(pts, 2000)

    # Ensure all points are valid
    for i in range(len(pts)):
        if not _point_in_triangle(pts[i]):
            x, y = pts[i]
            while not _point_in_triangle((x, y)):
                x = random.uniform(0, 1)
                y = random.uniform(0, SQRT3/2)
            pts[i] = [x, y]

    return [(float(x), float(y)) for x, y in pts]

from __future__ import annotations

import math
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5 / TRIANGLE_AREA

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

def _is_in_triangle(p: np.ndarray) -> bool:
    v0 = np.array([0.5, SQRT3/2])
    v1 = np.array([0.0, 0.0])
    v2 = np.array([1.0, 0.0])

    d1 = np.cross(p - v1, v0 - v1)
    d2 = np.cross(p - v0, v2 - v0)
    d3 = np.cross(p - v1, v2 - v1)

    has_neg = (d1 < 0) or (d2 < 0) or (d3 < 0)
    has_pos = (d1 > 0) or (d2 > 0) or (d3 > 0)
    return not (has_neg and has_pos)

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    v0 = np.array([0.5, SQRT3/2])
    v1 = np.array([0.0, 0.0])
    v2 = np.array([1.0, 0.0])

    if _is_in_triangle(p):
        return p

    def dist_to_segment(p, a, b):
        pa = p - a
        ba = b - a
        h = np.clip(np.dot(pa, ba) / np.dot(ba, ba), 0.0, 1.0)
        return np.linalg.norm(pa - h * ba)

    d0 = dist_to_segment(p, v1, v0)
    d1 = dist_to_segment(p, v0, v2)
    d2 = dist_to_segment(p, v1, v2)

    if d0 <= d1 and d0 <= d2:
        t = np.clip(np.dot(p - v1, v0 - v1) / np.dot(v0 - v1, v0 - v1), 0.0, 1.0)
        return v1 + t * (v0 - v1)
    elif d1 <= d2:
        t = np.clip(np.dot(p - v0, v2 - v0) / np.dot(v2 - v0, v2 - v0), 0.0, 1.0)
        return v0 + t * (v2 - v0)
    else:
        t = np.clip(np.dot(p - v1, v2 - v1) / np.dot(v2 - v1, v2 - v1), 0.0, 1.0)
        return v1 + t * (v2 - v1)

def _initialize_points(n: int) -> np.ndarray:
    # Combination of hexagonal and circular patterns
    pts = []
    layers = int(math.ceil(math.sqrt(n * 2 / SQRT3)))

    # Hexagonal grid
    for i in range(layers):
        for j in range(layers - i):
            x = 0.5 * i + j
            y = SQRT3 / 2 * i
            pts.append([x, y])

    # Circular pattern
    center = np.array([0.5, SQRT3/6])
    for k in range(len(pts), n):
        angle = 2 * math.pi * k / n
        r = 0.5 * (k / n) ** 0.5
        x = center[0] + r * math.cos(angle)
        y = center[1] + r * math.sin(angle)
        pts.append([x, y])

    pts = np.array(pts[:n])
    if len(pts) > 0:
        # Scale to fit triangle
        max_x = np.max(pts[:, 0])
        max_y = np.max(pts[:, 1])
        pts[:, 0] /= max_x
        pts[:, 1] /= max_y

        # Add small random perturbations
        pts += np.random.uniform(-0.01, 0.01, pts.shape)

        # Project any outliers back to triangle
        for i in range(len(pts)):
            if not _is_in_triangle(pts[i]):
                pts[i] = _project_to_triangle(pts[i])

    return pts

def _optimize_points(pts: np.ndarray, max_iter: int = 20000) -> np.ndarray:
    n = len(pts)
    best_pts = pts.copy()
    best_score = _min_triangle_area(best_pts)

    temp = 0.1
    cooling_rate = 0.9995
    step_size = 0.05
    no_improve = 0

    for iteration in range(max_iter):
        if no_improve > 1000 and iteration > max_iter // 2:
            break

        idx = np.random.randint(n)
        new_pts = pts.copy()
        perturbation = np.random.normal(0, step_size, size=2)
        new_pts[idx] += perturbation
        new_pts[idx] = _project_to_triangle(new_pts[idx])

        new_score = _min_triangle_area(new_pts)
        delta = new_score - best_score

        if delta > 0 or (temp > 0 and np.random.random() < math.exp(delta / temp)):
            pts = new_pts
            if new_score > best_score:
                best_score = new_score
                best_pts = pts.copy()
                no_improve = 0
            else:
                no_improve += 1
        else:
            no_improve += 1

        temp *= cooling_rate

        # Adaptive step size
        if iteration % 100 == 0:
            if no_improve < 50:
                step_size = min(0.1, step_size * 1.05)
            else:
                step_size = max(0.001, step_size * 0.95)

        # Periodic shake
        if iteration % 500 == 0 and no_improve > 500:
            pts = best_pts.copy()
            shake = np.random.normal(0, 0.02, pts.shape)
            pts = np.clip(pts + shake, 0, 1)
            for i in range(n):
                if not _is_in_triangle(pts[i]):
                    pts[i] = _project_to_triangle(pts[i])

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    if seed is not None:
        np.random.seed(seed)

    pts = _initialize_points(11)
    pts = _optimize_points(pts)

    return [(float(x), float(y)) for x, y in pts]

import math
import random
import itertools
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / 2.0

def _min_triangle_area(pts):
    n = len(pts)
    min_area = float('inf')
    for i in range(n-2):
        for j in range(i+1, n-1):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0.0
    return min_area

def _barycentric_to_cartesian(u, v):
    w = 1.0 - u - v
    x = w * 0.0 + u * 1.0 + v * 0.5
    y = w * 0.0 + u * 0.0 + v * SQRT3/2
    return (x, y)

def _generate_hexagonal_grid(n):
    pts = []
    layers = int(math.sqrt(n)) + 1
    for i in range(layers):
        for j in range(layers - i):
            u = (i + 0.5 * j) / (2 * layers)
            v = (j * SQRT3 / 2) / (2 * layers)
            if u + v <= 1.0:
                pts.append(_barycentric_to_cartesian(u, v))

    while len(pts) < n:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            pts.append(_barycentric_to_cartesian(u, v))

    return pts[:n]

def _project_to_triangle(x, y):
    v0 = (0.5, SQRT3/2)
    v1 = (1.0, 0.0)
    v2 = (0.0, 0.0)

    def sign(a, b, c):
        return (a[0]-c[0])*(b[1]-c[1])-(a[1]-c[1])*(b[0]-c[0])

    d1 = sign((x,y), v0, v1)
    d2 = sign((x,y), v1, v2)
    d3 = sign((x,y), v2, v0)

    has_neg = (d1 < 0) or (d2 < 0) or (d3 < 0)
    has_pos = (d1 > 0) or (d2 > 0) or (d3 > 0)

    if not (has_neg and has_pos):
        return (x, y)

    def closest_point_on_segment(a, b, p):
        ab = (b[0]-a[0], b[1]-a[1])
        ap = (p[0]-a[0], p[1]-a[1])
        t = max(0, min(1, (ap[0]*ab[0] + ap[1]*ab[1])/(ab[0]**2 + ab[1]**2))
        return (a[0] + t*ab[0], a[1] + t*ab[1])

    candidates = [
        closest_point_on_segment(v0, v1, (x,y)),
        closest_point_on_segment(v1, v2, (x,y)),
        closest_point_on_segment(v2, v0, (x,y))
    ]

    return min(candidates, key=lambda p: (p[0]-x)**2 + (p[1]-y)**2)

def _optimize_configuration(pts, max_iter=5000):
    best_pts = [p[:] for p in pts]
    best_area = _min_triangle_area(best_pts)
    n = len(pts)

    for iter in range(max_iter):
        T = 0.1 * (1 - iter/max_iter)**2
        step = 0.05 * (1 - iter/max_iter)

        idx = random.randint(0, n-1)
        new_pts = [p[:] for p in best_pts]
        dx, dy = random.uniform(-step, step), random.uniform(-step, step)
        new_pts[idx] = (new_pts[idx][0] + dx, new_pts[idx][1] + dy)
        new_pts[idx] = _project_to_triangle(*new_pts[idx])

        new_area = _min_triangle_area(new_pts)
        delta = new_area - best_area

        if delta > 0 or (T > 0 and random.random() < math.exp(delta/T)):
            best_pts = new_pts
            best_area = new_area

    return best_pts

def find_points(seed=None):
    if seed is not None:
        random.seed(seed)

    pts = _generate_hexagonal_grid(11)
    pts = _optimize_configuration(pts)

    return [(round(x, 8), round(y, 8)) for x, y in pts]

from __future__ import annotations

import math
import random
import itertools
from typing import List, Tuple, Optional
import numpy as np

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _is_inside_triangle(pt: np.ndarray) -> bool:
    x, y = pt
    return (y >= 0 and x >= 0 and (x + y/SQRT3) <= 1 and 
            (x - y/SQRT3) <= 0 and y <= SQRT3/2)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5 / TRIANGLE_AREA

class MinAreaTracker:
    def __init__(self, pts: np.ndarray):
        self.pts = pts.copy()
        self.n = len(pts)
        self.triplets = list(itertools.combinations(range(self.n), 3))
        self.point_to_triplets = [[] for _ in range(self.n)]
        for idx_triplet, triplet in enumerate(self.triplets):
            for i in triplet:
                self.point_to_triplets[i].append(idx_triplet)
        self.areas_arr = np.zeros(len(self.triplets))
        for idx_triplet, (i, j, k) in enumerate(self.triplets):
            self.areas_arr[idx_triplet] = _area(pts[i], pts[j], pts[k])
        self.min_area = np.min(self.areas_arr)

    def update_point(self, idx: int, new_pos: np.ndarray) -> bool:
        if not _is_inside_triangle(new_pos):
            return False
        self.pts[idx] = new_pos
        for idx_triplet in self.point_to_triplets[idx]:
            i, j, k = self.triplets[idx_triplet]
            self.areas_arr[idx_triplet] = _area(self.pts[i], self.pts[j], self.pts[k])
        self.min_area = np.min(self.areas_arr)
        return True

    def get_min_area(self) -> float:
        return self.min_area

def _random_barycentric(rng: np.random.Generator) -> Tuple[float, float, float]:
    u, v = rng.random(2)
    if u + v > 1:
        u, v = 1 - u, 1 - v
    return (1 - u - v, u, v)

def _barycentric_to_cartesian(bary: Tuple[float, float, float]) -> np.ndarray:
    a, b, c = bary
    return np.array([0.5 * (b - a) + c * 0.5, c * SQRT3 / 2])

def _initial_configuration(n_pts: int = 11, rng: np.random.Generator = None) -> np.ndarray:
    if rng is None:
        rng = np.random.default_rng()

    pts = []
    # Hexagonal lattice points
    k = math.ceil(math.sqrt(2 * n_pts / (SQRT3/2)))
    offset = 1/(2*k)
    for i in range(k):
        for j in range(k):
            if len(pts) >= n_pts:
                break
            x = (i + 0.5 * (j % 2)) / k + offset
            y = (j * SQRT3 / 2) / k + offset
            if _is_inside_triangle(np.array([x, y])):
                pts.append(np.array([x, y]))

    # Fill remaining points with random positions
    while len(pts) < n_pts:
        bary = _random_barycentric(rng)
        pt = _barycentric_to_cartesian(bary)
        if _is_inside_triangle(pt):
            pts.append(pt)

    return np.array(pts[:n_pts])

def _optimize(n_pts: int = 11, iters: int = 10000, seed: int | None = None) -> np.ndarray:
    rng = np.random.default_rng(seed)
    pts = _initial_configuration(n_pts, rng)
    tracker = MinAreaTracker(pts)
    best_pts = pts.copy()
    best_val = tracker.get_min_area()

    for t in range(iters):
        T = max(0.01 * (1 - t/iters), 1e-6)
        step_size = 0.02 * (1 - t/iters) + 0.001

        idx = rng.integers(0, n_pts)
        old_pos = pts[idx].copy()

        # Move in barycentric coordinates
        bary = _random_barycentric(rng)
        new_pos = _barycentric_to_cartesian(bary)

        if not tracker.update_point(idx, new_pos):
            continue

        trial_val = tracker.get_min_area()
        delta = trial_val - best_val

        if delta > 0 or rng.random() < math.exp(delta / T):
            pts = tracker.pts.copy()
            if trial_val > best_val:
                best_val = trial_val
                best_pts = pts.copy()
        else:
            tracker.update_point(idx, old_pos)

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    pts = _optimize(n_pts=11, iters=10000, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

from __future__ import annotations
import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    best = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

def _generate_hex_grid(n: int) -> np.ndarray:
    layers = math.ceil(math.sqrt(n / 3)) + 2
    pts = []
    for i in range(-layers, layers+1):
        for j in range(-layers, layers+1):
            x = 0.5 + 0.5 * i + 0.25 * j
            y = SQRT3/4 * j
            pts.append([x, y])
    pts = np.array(pts)
    inside = []
    for p in pts:
        try:
            u, v = np.linalg.solve(np.column_stack((_B-_A, _C-_A)), p-_A)[0]
            if u >= 0 and v >= 0 and (1-u-v) >= 0:
                inside.append(p)
        except:
            continue
    return np.array(inside)

def _simulated_annealing(n_pts: int, max_iter: int) -> np.ndarray:
    current = _generate_hex_grid(n_pts)
    if len(current) < n_pts:
        current = np.random.uniform(0, 1, (n_pts, 2))
    else:
        current = current[np.random.choice(len(current), n_pts, replace=False)]

    current_val = _min_triangle_area(current)
    best = current.copy()
    best_val = current_val

    temp = 1.0
    cooling_rate = 0.999

    for _ in range(max_iter):
        temp *= cooling_rate
        candidate = current.copy()

        for i in range(n_pts):
            if random.random() < 0.3:
                candidate[i] += np.random.normal(0, temp, 2)
                try:
                    u, v = np.linalg.solve(np.column_stack((_B-_A, _C-_A)), candidate[i]-_A)[0]
                    if u < 0 or v < 0 or (1-u-v) < 0:
                        candidate[i] = current[i]
                except:
                    candidate[i] = current[i]

        candidate_val = _min_triangle_area(candidate)
        if candidate_val > current_val:
            current = candidate
            current_val = candidate_val
            if candidate_val > best_val:
                best = candidate.copy()
                best_val = candidate_val
        elif temp > 0 and random.random() < math.exp((candidate_val - current_val)/temp):
            current = candidate
            current_val = candidate_val

    return best

def _local_search(pts: np.ndarray, steps: int) -> np.ndarray:
    best = pts.copy()
    best_val = _min_triangle_area(best)
    n = len(pts)

    for _ in range(steps):
        temp = best.copy()
        idx = random.randint(0, n-1)
        temp[idx] += np.random.uniform(-0.01, 0.01, 2)
        try:
            u, v = np.linalg.solve(np.column_stack((_B-_A, _C-_A)), temp[idx]-_A)[0]
            if u < 0 or v < 0 or (1-u-v) < 0:
                continue
        except:
            continue

        temp_val = _min_triangle_area(temp)
        if temp_val > best_val:
            best = temp.copy()
            best_val = temp_val

    return best

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    pts = _simulated_annealing(n_pts=11, max_iter=500)
    pts = _local_search(pts, steps=1000)

    return [(float(x), float(y)) for x, y in pts]

