import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    u, v = random.random(), random.random()
    if u + v > 1.0:
        u, v = 1 - u, 1 - v
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = 1 - u, 1 - v
    return (1 - u - v) * _A + u * _B + v * _C

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')

    # Check only nearby points using spatial hashing
    grid_size = int(math.sqrt(n))
    grid = {}
    for i, p in enumerate(pts):
        x, y = p
        cell = (int(x*grid_size), int(y*grid_size))
        if cell not in grid:
            grid[cell] = []
        grid[cell].append(i)

    for i in range(n):
        neighbors = []
        x, y = pts[i]
        cell_x, cell_y = int(x*grid_size), int(y*grid_size)
        for dx in [-1, 0, 1]:
            for dy in [-1, 0, 1]:
                neighbor_cell = (cell_x + dx, cell_y + dy)
                if neighbor_cell in grid:
                    neighbors.extend(grid[neighbor_cell])

        for j in neighbors:
            if j <= i:
                continue
            for k in neighbors:
                if k <= j:
                    continue
                area = 0.5 * abs((pts[j,0]-pts[i,0])*(pts[k,1]-pts[i,1]) - (pts[j,1]-pts[i,1])*(pts[k,0]-pts[i,0]))
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0.0
    return min_area

def _optimize_points(n_pts: int = 11, seed: int | None = 0) -> np.ndarray:
    random.seed(seed)

    # Initialize with hexagonal grid
    best_pts = []
    k = int(math.sqrt(n_pts)) + 1
    for i in range(k):
        for j in range(k):
            if len(best_pts) >= n_pts:
                break
            x = 0.5 + (i - k//2) * 0.2
            y = 0.5 + (j - k//2) * 0.2 * SQRT3
            if x >= 0 and y >= 0 and (1 - x - y) >= 0:
                best_pts.append(np.array([x, y]))

    while len(best_pts) < n_pts:
        best_pts.append(_random_point())

    best_pts = np.array(best_pts)
    best_val = _min_triangle_area(best_pts)

    # Pattern search optimization
    step_size = 0.1
    no_improve = 0

    while no_improve < 50 and step_size > 0.001:
        improved = False

        for idx in random.sample(range(n_pts), n_pts):
            for angle in np.linspace(0, 2*np.pi, 8):
                dx, dy = step_size*math.cos(angle), step_size*math.sin(angle)
                trial = best_pts.copy()
                trial[idx] += dx, dy
                trial[idx] = _project_to_simplex(trial[idx])
                trial_val = _min_triangle_area(trial)

                if trial_val > best_val:
                    best_val = trial_val
                    best_pts = trial.copy()
                    improved = True
                    no_improve = 0
                    break
            if improved:
                break

        if not improved:
            no_improve += 1
            step_size *= 0.8

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _optimize_points(n_pts=11, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

