                break
            u = (i + 0.5) / grid_size
            v = (j + 0.5) / grid_size
            if u + v <= 1.0:
                pts.append((1 - u - v) * _A + u * _B + v * _C)
    if len(pts) < n_pts:
        pts.extend([_random_point() for _ in range(n_pts - len(pts))])
    return np.array(pts[:n_pts])

def _optimize_points(pts: np.ndarray, iters: int = 100, step_size: float = 0.01) -> np.ndarray:
