    min_area = float('inf')

    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                p, q, r = pts[i], pts[j], pts[k]
                area = abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0.0
    return min_area

def _initialize_points(n: int) -> np.ndarray:
    pts = []
    k = int(math.sqrt(n)) + 1
    for i in range(k):
        for j in range(k):
            if len(pts) >= n:
                break
            x = 0.5 + (i/k - 0.5) * 0.9
            y = (j/k) * 0.9 * SQRT3/2
            if y <= SQRT3/2 * (1 - abs(2*x - 1)):
                pts.append(np.array([x, y]))
    while len(pts) < n:
        pts.append(_random_point())
    return np.array(pts[:n])

def _anneal(n_pts: int = 11,
            iters: int = 20000,
            start_temp: float = 0.5,
            end_temp: float = 1e-10,
            seed: int | None = None) -> np.ndarray:

    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _initialize_points(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    step_size = 0.05
    accept_rate = 0.0
    restart_counter = 0

    for t in range(iters):
        T = start_temp * math.exp(-4.0 * t / iters)

        if t % 100 == 0:
            step_size *= 0.8 if accept_rate < 0.3 else 1.2
            step_size = min(0.1, max(0.001, step_size))
            accept_rate = 0.0

        if t % 1000 == 0 and t > 0:
            if restart_counter < 3 and best_val < 0.03:
                pts = _initialize_points(n_pts)
                restart_counter += 1

        idx = random.randrange(n_pts)
        trial = pts.copy()

        if random.random() < 0.7:
            grad = np.zeros(2)
            best_dir = np.zeros(2)
            min_contrib = float('inf')

            for j in range(n_pts):
                if j == idx:
                    continue
                for k in range(j+1, n_pts):
                    if k == idx:
                        continue
                    p, q, r = pts[idx], pts[j], pts[k]
                    area = abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5
                    if area < best_val * 1.5:
                        dx = (q[1]-r[1]) * 0.5
                        dy = (r[0]-q[0]) * 0.5
                        weight = 1.0 / (area + 1e-8)
                        grad += np.array([dx, dy]) * weight
                        if area < min_contrib:
                            min_contrib = area
                            best_dir = np.array([dx, dy])

            if np.linalg.norm(grad) > 0:
                grad = grad / np.linalg.norm(grad)
                trial[idx] += grad * random.uniform(0, step_size)
            else:
                trial[idx] += best_dir * random.uniform(0, step_size)
        else:
            trial[idx] += np.random.uniform(-step_size, step_size, 2)

        trial[idx] = _project_to_simplex(trial[idx])
        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or random.random() < math.exp(delta / max(T, 1e-12)):
            pts = trial
            accept_rate += 1.0 / 100
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=20000, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

