    return (1 - u - v) * _A + u * _B + v * _C

def _grid_points(n: int) -> List[np.ndarray]:
    k = int(math.sqrt(n)) + 1
    points = []
    for i in range(k):
        for j in range(k):
            if i + j > k:
                continue
            u = i / k
            v = j / k
            points.append((1 - u - v) * _A + u * _B + v * _C)
            if len(points) >= n:
                return points
    return points

