    layers = math.ceil(math.sqrt(n))
    for i in range(layers):
        for j in range(layers):
            if len(pts) >= n:
                break
            x = (i + 0.5 * (j % 2)) / (layers - 0.5)
            y = (j * SQRT3 * 0.5) / (layers - 0.5)
            if _is_in_triangle(np.array([x, y])):
                pts.append(np.array([x, y]))
    while len(pts) < n:
        x = random.random()
        y = random.random() * SQRT3 / 2
        if _is_in_triangle(np.array([x, y])):
            pts.append(np.array([x, y]))
    return np.array(pts[:n])

def _optimize_points(pts: np.ndarray, max_iter: int = 5000) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)
    n = len(pts)

    for _ in range(max_iter):
        improved = False
        for idx in range(n):
            for _ in range(5):
                step = 0.02
                trial = best_pts.copy()
                trial[idx] += np.random.uniform(-step, step, 2)

                if not _is_in_triangle(trial[idx]):
                    continue

                new_area = _min_triangle_area(trial)
                if new_area > best_area:
                    best_area = new_area
                    best_pts = trial.copy()
                    improved = True
                    break

        if not improved:
            break

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _hexagonal_grid(11)
    pts = _optimize_points(pts)

    return [(float(x), float(y)) for x, y in pts]

