    points = []
    # Generate hexagonal grid points first
    grid_size = 0.2
    for i in range(4):
        for j in range(4):
            if i + j <= 3 and len(points) < n:
                x = 0.1 + i * grid_size + j * grid_size/2
                y = SQRT3/2 * 0.1 + j * grid_size * SQRT3/2
                if _is_in_triangle((x, y)):
                    points.append([x, y])

    # Fill remaining points with random positions
    while len(points) < n:
        x = random.uniform(0.1, 0.9)
        y = random.uniform(0.1, 0.8 * SQRT3/2)
        if _is_in_triangle((x, y)) and all(math.hypot(x-p[0], y-p[1]) > 0.1 for p in points):
            points.append([x, y])

    return np.array(points[:n])  # Ensure exactly n points

def _optimize_points(points, iterations):
