    best_score = _min_triangle_area(best_points)

    for i in range(iterations):
        new_points = best_points.copy()

        if i % 50 == 0:
            areas = []
            for j in range(len(points)):
                min_local = float('inf')
                for k, l in combinations([x for x in range(len(points)) if x != j], 2):
                    a = _area(points[j], points[k], points[l])
                    if a < min_local:
                        min_local = a
                areas.append(min_local)
            idx = np.argmin(areas)
            new_points[idx] = np.random.uniform(0.1, 0.9, 2)
