import math
import random
import itertools
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / 2.0

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    best = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best / TRIANGLE_AREA

def _random_barycentric() -> Tuple[float, float, float]:
    s = random.random()
    t = random.random()
    if s + t > 1:
        s, t = 1 - s, 1 - t
    return (s, t, 1 - s - t)

def _barycentric_to_cartesian(b: Tuple[float, float, float]) -> np.ndarray:
    return np.array([0.5*b[2] + b[1], SQRT3/2 * b[2]])

def _initial_configuration(n_pts: int = 11) -> np.ndarray:
    pts = []
    # Hexagonal lattice points
    k = math.ceil(math.sqrt(n_pts / (SQRT3/2)))
    for i in range(k):
        for j in range(k):
            x = (i + 0.5*(j%2)) / (k-0.5)
            y = j * SQRT3/2 / (k-0.5)
            if x <= 1 and y <= SQRT3/2 and (1-x)*SQRT3/2 >= y:
                pts.append(np.array([x, y]))
    # Fill remaining points with random barycentric
    while len(pts) < n_pts:
        s, t, u = _random_barycentric()
        pts.append(_barycentric_to_cartesian((s, t, u)))
    return np.array(pts[:n_pts])

def _optimize_points(pts: np.ndarray, iterations: int = 10000) -> np.ndarray:
    n = len(pts)
    best_pts = pts.copy()
    best_score = _min_triangle_area(best_pts)

    for iter in range(iterations):
        temp = 1.0 - iter/iterations
        idx = random.randrange(n)

        # Generate new point in barycentric coordinates
        s, t, u = _random_barycentric()
        new_pt = _barycentric_to_cartesian((s, t, u))

        trial = best_pts.copy()
        trial[idx] = new_pt
        trial_score = _min_triangle_area(trial)

        if trial_score > best_score or random.random() < temp:
            best_score = trial_score
            best_pts = trial.copy()

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
    pts = _initial_configuration(11)
    pts = _optimize_points(pts, 15000)
    return [(float(x), float(y)) for x, y in pts]

