import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _barycentric_to_cartesian(u: float, v: float) -> np.ndarray:
    return (1 - u - v) * _A + u * _B + v * _C

def _cartesian_to_barycentric(p: np.ndarray) -> Tuple[float, float]:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    return uv[0], uv[1]

def _generate_initial_points(n: int) -> np.ndarray:
    points = []
    k = int(math.sqrt(n)) + 1
    for i in range(k):
        for j in range(k):
            if len(points) >= n:
                break
            u = (i + 0.5 * (j % 2)) / k
            v = (j * math.sqrt(3)/2) / k
            if u + v <= 1.0:
                points.append(_barycentric_to_cartesian(u, v))
    while len(points) < n:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            points.append(_barycentric_to_cartesian(u, v))
    return np.array(points)

def _min_triangle_area_fast(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')

    for i in range(n):
        for j in range(i+1, min(i+7, n)):
            for k in range(j+1, min(j+7, n)):
                a = pts[j] - pts[i]
                b = pts[k] - pts[i]
                cross = abs(a[0]*b[1] - a[1]*b[0])
                if cross < min_area:
                    min_area = cross
                    if min_area == 0:
                        return 0.0
    return min_area * 0.5

def _optimize_points(pts: np.ndarray, iterations: int = 15000) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area_fast(best_pts)
    n = len(pts)
    step_size = 0.05

    for _ in range(iterations):
        idx = random.randrange(n)
        trial = best_pts.copy()

        angle = random.uniform(0, 2*math.pi)
        step = step_size * (0.9 + 0.2*random.random())
        dx, dy = step * math.cos(angle), step * math.sin(angle)

        trial[idx] += np.array([dx, dy])
        u, v = _cartesian_to_barycentric(trial[idx])
        if u < 0 or v < 0 or u + v > 1:
            trial[idx] = _barycentric_to_cartesian(
                max(0, min(1, u)), max(0, min(1, v))
            )

        current_area = _min_triangle_area_fast(trial)
        if current_area > best_area:
            best_area = current_area
            best_pts = trial.copy()
            step_size = min(0.1, step_size * 1.05)
        else:
            step_size = max(0.005, step_size * 0.99)

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    initial_points = _generate_initial_points(11)
    optimized_points = _optimize_points(initial_points, 20000)

    return [(float(x), float(y)) for x, y in optimized_points]

