import math
import random
import itertools
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p, q, r) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5 / TRIANGLE_AREA

class MinTriangleArea:
    def __init__(self, n_points):
        self.comb = list(itertools.combinations(range(n_points), 3))
        self.point_cache = {}

    def __call__(self, pts: np.ndarray) -> float:
        best = float("inf")
        for tri in self.comb:
            i, j, k = tri
            a = _area(pts[i], pts[j], pts[k])
            if a < best:
                best = a
                if best < 0.01:
                    return best
        return best

def _generate_initial_points(n: int) -> np.ndarray:
    pts = []
    # Hexagonal core
    layers = math.ceil((n / 3)**0.5) + 1
    for i in range(layers):
        for j in range(layers):
            x = 0.5 + (j - i) * 0.5 / layers
            y = SQRT3 * (i + j) / (3 * layers)
            if x >= 0 and y >= 0 and (1 - x - y/SQRT3) >= 0:
                pts.append([x, y])

    # Add random points with minimum distance
    while len(pts) < n:
        x = random.uniform(0.1, 0.9)
        y = random.uniform(0.1, 0.8)
        if y <= SQRT3 * x and y <= SQRT3 * (1 - x):
            valid = True
            for p in pts:
                if math.hypot(p[0]-x, p[1]-y) < 0.1:
                    valid = False
                    break
            if valid:
                pts.append([x, y])

    return np.array(pts[:n])

def _optimize_points(pts: np.ndarray, steps: int, min_area_func) -> np.ndarray:
    best_pts = pts.copy()
    best_val = min_area_func(best_pts)
    n = len(pts)

    for step in range(steps):
        temp = max(0.05, 1.0 - step / steps)
        step_size = 0.05 * temp

        for i in range(n):
            trial = best_pts.copy()
            angle = random.uniform(0, 2*math.pi)
            dx = step_size * math.cos(angle)
            dy = step_size * math.sin(angle)
            trial[i] += dx, dy

            x, y = trial[i]
            if y < 0 or y > SQRT3 * x or y > SQRT3 * (1 - x):
                continue

            val = min_area_func(trial)
            if val > best_val or (temp > 0.1 and random.random() < math.exp(10*(val - best_val)/temp)):
                best_val = val
                best_pts = trial.copy()

    return best_pts

def _global_perturbation(pts: np.ndarray, steps: int, min_area_func) -> np.ndarray:
    best_pts = pts.copy()
    best_val = min_area_func(best_pts)
    n = len(pts)

    for step in range(steps):
        step_size = 0.02 * (1 - step/steps)

        trial = best_pts.copy()
        for i in range(n):
            angle = random.uniform(0, 2*math.pi)
            dx = step_size * math.cos(angle)
            dy = step_size * math.sin(angle)
            trial[i] += dx, dy

            x, y = trial[i]
            if y < 0 or y > SQRT3 * x or y > SQRT3 * (1 - x):
                trial[i] = best_pts[i]

        val = min_area_func(trial)
        if val > best_val:
            best_val = val
            best_pts = trial.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    min_area_func = MinTriangleArea(11)
    pts = _generate_initial_points(11)
    pts = _optimize_points(pts, 30000, min_area_func)
    pts = _global_perturbation(pts, 5000, min_area_func)

    return [(float(x), float(y)) for x, y in pts]

