        if _is_inside(np.array([x, y])):
            pts.append([x, y])
    return np.array(pts)

def _simulated_annealing(n_pts: int, initial_temp: float, cooling_rate: float, steps: int) -> np.ndarray:
    current_solution = _generate_initial_points(n_pts)
    current_energy = -_min_triangle_area(current_solution)
    best_solution = current_solution.copy()
    best_energy = current_energy

    temp = initial_temp

    for step in range(steps):
        temp *= cooling_rate
        new_solution = current_solution.copy()

