from __future__ import annotations

import math
import itertools
from typing import List, Tuple
import numpy as np

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    min_area = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    while True:
        u, v = np.random.random(2)
        if u + v <= 1.0:
            w = 1 - u - v
            if u > 0 and v > 0 and w > 0:
                break
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(1e-9, min(1-1e-9, u))
    v = max(1e-9, min(1-1e-9, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    w = 1 - u - v
    if w < 1e-9:
        u, v = u*(1-1e-9), v*(1-1e-9)
    return (1 - u - v) * _A + u * _B + v * _C

def _local_optimize(pts: np.ndarray, steps: int = 100) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    n = len(pts)

    for _ in range(steps):
        improved = False
        for i in range(n):
            for dx, dy in [(0.01, 0), (-0.01, 0), (0, 0.01), (0, -0.01)]:
                trial = pts.copy()
                trial[i] += np.array([dx, dy])
                trial[i] = _project_to_simplex(trial[i])
                trial_val = _min_triangle_area(trial)
                if trial_val > best_val:
                    best_val = trial_val
                    best_pts = trial.copy()
                    improved = True
        if not improved:
            break
    return best_pts

def _anneal(n_pts: int = 11,
            iters: int = 3000,
            start_temp: float = 0.2,
            end_temp: float = 1e-6,
            seed: int | None = 0) -> np.ndarray:
    np.random.seed(seed)
    pts = np.array([_random_point() for _ in range(n_pts)])
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        T = start_temp * (end_temp / start_temp) ** (t / max(iters-1, 1))
        step_size = 0.05 * (1 - t/iters) + 0.005

        trial = pts.copy()
        if np.random.random() < 0.2:
            for _ in range(1 + int(np.random.random() * 3)):
                idx = np.random.randint(n_pts)
                trial[idx] += np.random.uniform(-step_size, step_size, size=2)
                trial[idx] = _project_to_simplex(trial[idx])
        else:
            idx = np.random.randint(n_pts)
            trial[idx] += np.random.uniform(-step_size, step_size, size=2)
            trial[idx] = _project_to_simplex(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or np.random.random() < math.exp(delta / max(T, 1e-12)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = pts.copy()

    return _local_optimize(best_pts)

