import math
import random
import numpy as np

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    min_area = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _initial_configuration(n_pts: int = 11) -> np.ndarray:
    # Hexagonal grid initialization
    pts = []
    layers = math.ceil((math.sqrt(8*n_pts/3 + 1) - 1)/2)
    for layer in range(layers):
        count = layer + 1
        for i in range(count):
            u = (i + 0.5 * (layer % 2)) / (2*layers)
            v = (layer * 0.866) / (2*layers)
            if u + v > 1.0:
                u, v = 1 - u, 1 - v
            pts.append((1 - u - v) * _A + u * _B + v * _C)
            if len(pts) == n_pts:
                return np.array(pts)
    return np.array(pts[:n_pts])

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    pts = _initial_configuration(11)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    accept_count = 0

    for t in range(5000):
        T = 0.1 * (0.998 ** t)
        step_size = 0.03 * (1 - t/5000)**2

        # Occasionally move multiple points
        if t % 10 == 0 and random.random() < 0.3:
            idx1, idx2 = random.sample(range(11), 2)
            trial = pts.copy()
            for idx in [idx1, idx2]:
                trial[idx] += random.uniform(-step_size, step_size), random.uniform(-step_size, step_size)
                trial[idx] = _project_to_simplex(trial[idx])
        else:
            idx = random.randrange(11)
            trial = pts.copy()
            trial[idx] += random.uniform(-step_size, step_size), random.uniform(-step_size, step_size)
            trial[idx] = _project_to_simplex(trial[idx])

        trial_val = _min_triangle_area(trial)

        if trial_val > best_val or random.random() < math.exp((trial_val - best_val)/max(T, 1e-12)):
            pts = trial
            accept_count += 1
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

        # Adaptive step size adjustment
        if t % 100 == 0 and t > 0:
            accept_rate = accept_count / 100
            if accept_rate < 0.2:
                step_size *= 0.9
            elif accept_rate > 0.5:
                step_size *= 1.1
            accept_count = 0

    return [(float(x), float(y)) for x, y in best_pts]

