def _constraint(x):
    pts = x.reshape(-1, 2)
    for pt in pts:
        x, y = pt
        if y < 0 or y > SQRT3/2:
            return -1
        if x < max(0, y/SQRT3 - 1e-8) or x > min(1, 1 - y/SQRT3 + 1e-8):
            return -1
    return 1

def objective(x):
    if _constraint(x) < 0:
        return 0
    return -_min_triangle_area(x)

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    bounds = [(0.0, 1.0), (0.0, SQRT3/2)] * 11
    result = differential_evolution(
        objective,
        bounds,
        strategy='randtobest1bin',
        maxiter=200,
        popsize=30,
        tol=1e-9,
        mutation=(0.5, 1.0),
        recombination=0.7,
        seed=seed,
        polish=True,
        updating='immediate'
    )
    pts = result.x.reshape(-1, 2)
    return [(float(x), float(y)) for x, y in pts]

