import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5 / TRIANGLE_AREA

def _min_triangle_area(pts: np.ndarray) -> float:
    best = float("inf")
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, min(j+10, n)):  # Limit k range for performance
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _generate_point_inside() -> np.ndarray:
    while True:
        r1, r2 = random.random(), random.random()
        if r1 + r2 <= 1.0:
            break
    x = (1 - r1 - r2) * _A[0] + r1 * _B[0] + r2 * _C[0]
    y = (1 - r1 - r2) * _A[1] + r1 * _B[1] + r2 * _C[1]
    return np.array([x, y])

def _hexagonal_grid(n_pts: int) -> List[np.ndarray]:
    pts = []
    layers = math.ceil(math.sqrt(n_pts / 3))
    for i in range(layers):
        for j in range(layers):
            for k in range(layers):
                if i + j + k == layers - 1:
                    u = (i + 0.5 * j + 0.5 * k) / layers
                    v = (SQRT3/2 * j + SQRT3/2 * k) / layers
                    if u >= 0 and v >= 0 and u + v/SQRT3 <= 1.0:
                        pts.append(np.array([u, v]))
                    if len(pts) >= n_pts:
                        return pts
    while len(pts) < n_pts:
        pts.append(_generate_point_inside())
    return pts[:n_pts]

def _anneal(n_pts: int = 11, seed: int | None = None) -> np.ndarray:
    if seed is not None:
        random.seed(seed)
    pts = np.array(_hexagonal_grid(n_pts))
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    iters = 5000

    for t in range(iters):
        T = 0.1 * math.exp(-5.0 * t / iters)
        step_size = 0.05 * (1 - t/iters)
        idx = random.randrange(n_pts)
        trial = pts.copy()
        trial[idx] += random.uniform(-step_size, step_size), random.uniform(-step_size, step_size)

        # Ensure point stays inside triangle
        r1 = trial[idx][0] - _A[0]
        r2 = trial[idx][1] - _A[1]
        M = np.column_stack((_B - _A, _C - _A))
        try:
            uv = np.linalg.solve(M, trial[idx] - _A)
            u, v = uv
            if u < 0 or v < 0 or u + v > 1.0:
                trial[idx] = _generate_point_inside()
        except:
            trial[idx] = _generate_point_inside()

        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or random.random() < math.exp(delta / max(T, 1e-12)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

    return best_pts

def _verify_points(pts: np.ndarray) -> bool:
    M = np.column_stack((_B - _A, _C - _A))
    for p in pts:
        uv = np.linalg.solve(M, p - _A)
        u, v = uv
        if u < 0 or v < 0 or u + v > 1.0:
            return False
    return True

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    for _ in range(3):  # Try up to 3 times to get valid points
        pts = _anneal(n_pts=11, seed=seed)
        if _verify_points(pts):
            break
    else:
        pts = np.array(_hexagonal_grid(11))

    return [(float(x), float(y)) for x, y in pts]

