    points = []
    # Hexagonal pattern with some randomness
    layers = 3
    for layer in range(layers):
        for i in range(layer+1):
            x = 0.2 + 0.3*i/(layer+1) + random.uniform(-0.05, 0.05)
            y = SQRT3/2 * (0.2 + 0.3*layer/layers) + random.uniform(-0.05, 0.05)
            if _is_in_triangle((x, y)):
                points.append([x, y])

    # Fill remaining points with more spread
    while len(points) < n:
        x = random.uniform(0.1, 0.9)
        y = random.uniform(0.1, 0.8*SQRT3/2)
        if _is_in_triangle((x, y)):
