import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray, threshold: float = 0) -> float:
    n = len(pts)
    best = float("inf")
    for i in range(n):
        for j in range(i+1, min(i+8, n)):  # Limit j range
            for k in range(j+1, min(j+8, n)):  # Limit k range
                a = _area(pts[i], pts[j], pts[k])
                if a < threshold:
                    return 0
                if a < best:
                    best = a
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _hex_grid_points(n: int) -> np.ndarray:
    k = math.ceil(math.sqrt(n * 2 / SQRT3))
    pts = []
    for i in range(k):
        for j in range(k):
            if i + j > k:
                continue
            u = (i + 0.5 * (j % 2)) / k
            v = j * SQRT3 / (2 * k)
            if u + v/SQRT3 <= 1.0 and v <= SQRT3/2:
                pts.append((1-u-v/SQRT3)*_A + u*_B + (v/(SQRT3/2))*_C)
                if len(pts) == n:
                    return np.array(pts)
    return np.array(pts[:n])

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    w = 1.0 - u - v
    if u >= 0 and v >= 0 and w >= 0:
        return p
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        s = u + v
        u /= s
        v /= s
    return (1 - u - v) * _A + u * _B + v * _C

def _optimize_points(pts: np.ndarray, max_iter: int = 5000) -> np.ndarray:
    n = len(pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for _ in range(max_iter):
        improved = False
        for i in range(n):
            for _ in range(2):  # Try 2 random moves per point
                step = 0.01
                trial = pts.copy()
                dx = random.uniform(-step, step)
                dy = random.uniform(-step, step)
                trial[i] += np.array([dx, dy])
                trial[i] = _project_to_simplex(trial[i])

                # Only check triangles involving the moved point
                local_min = float("inf")
                for j in range(n):
                    if j == i:
                        continue
                    for k in range(j+1, n):
                        if k == i:
                            continue
                        a = _area(trial[i], trial[j], trial[k])
                        if a < best_val:
                            break
                        if a < local_min:
                            local_min = a
                    else:
                        continue
                    break
                else:
                    if local_min > best_val:
                        best_val = local_min
                        best_pts = trial.copy()
                        improved = True
                        pts = trial.copy()
        if not improved:
            break
    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    pts = _hex_grid_points(11)
    pts = _optimize_points(pts)
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

