    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _min_triangle_area_fast(pts: np.ndarray, idx: int = None) -> float:
    n = len(pts)
    best = float('inf')

    if idx is None:
        candidates = range(n)
    else:
        candidates = [idx]

    for i in candidates:
        for j in range(n):
            if j == i:
                continue
            for k in range(j+1, n):
                if k == i:
                    continue
                a = abs((pts[j][0] - pts[i][0])*(pts[k][1] - pts[i][1]) - 
                    (pts[j][1] - pts[i][1])*(pts[k][0] - pts[i][0])) * 0.5
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

def _optimize_points(pts: np.ndarray, max_iter: int = 1000) -> np.ndarray:
    n = len(pts)
    current_min = _min_triangle_area_fast(pts)
    step = 0.01

    for _ in range(max_iter):
        improved = False
        for i in range(n):
            original = pts[i].copy()
            for _ in range(10):
                delta = np.random.uniform(-step, step, 2)
                pts[i] = _project_to_simplex(original + delta)
                new_min = _min_triangle_area_fast(pts, i)
                if new_min > current_min:
                    current_min = new_min
                    improved = True
                    break
                else:
                    pts[i] = original
        if not improved:
            step *= 0.5
            if step < 1e-6:
                break
    return pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    # Initial random points
    pts = np.array([_random_point() for _ in range(11)])

    # Optimization phase
    pts = _optimize_points(pts)

    # Convert to list of tuples
    return [(float(x), float(y)) for x, y in pts]

