import math
import random
import numpy as np
from typing import List, Tuple
from scipy.spatial import Delaunay

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5 / TRIANGLE_AREA

def _min_triangle_area(pts: np.ndarray) -> float:
    tri = Delaunay(pts)
    min_area = float('inf')
    for simplex in tri.simplices:
        a = _area(pts[simplex[0]], pts[simplex[1]], pts[simplex[2]])
        if a < min_area:
            min_area = a
            if min_area == 0:
                return 0
    return min_area

def _is_inside_triangle(p: np.ndarray) -> bool:
    x, y = p
    if x < 0 or x > 1 or y < 0 or y > SQRT3/2:
        return False
    if y > SQRT3 * x or y > SQRT3 * (1 - x):
        return False
    return True

def _random_point_inside() -> np.ndarray:
    while True:
        x = random.uniform(0, 1)
        y = random.uniform(0, SQRT3/2)
        if _is_inside_triangle(np.array([x, y])):
            return np.array([x, y])

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    x, y = p
    x = max(0.0, min(1.0, x))
    y = max(0.0, min(SQRT3/2, y))

    if y > SQRT3 * x:
        y = SQRT3 * x
    if y > SQRT3 * (1 - x):
        y = SQRT3 * (1 - x)

    return np.array([x, y])

def _get_initial_points(n: int) -> List[np.ndarray]:
    if n == 11:
        return [
            np.array([0.0, 0.0]),
            np.array([1.0, 0.0]),
            np.array([0.5, SQRT3/2]),
            np.array([0.25, SQRT3/4]),
            np.array([0.75, SQRT3/4]),
            np.array([0.125, SQRT3/8]),
            np.array([0.375, SQRT3/8]),
            np.array([0.625, SQRT3/8]),
            np.array([0.875, SQRT3/8]),
            np.array([0.0625, SQRT3/16]),
            np.array([0.9375, SQRT3/16])
        ]
    return [_random_point_inside() for _ in range(n)]

def _optimize_points(points: np.ndarray) -> np.ndarray:
    n = len(points)
    best_points = points.copy()
    best_score = _min_triangle_area(best_points)
    no_improve = 0

    for t in range(1000):
        if no_improve > 50:
            break

        step = 0.05 * (1 - t/1000)
        idx = random.randrange(n)
        new_points = best_points.copy()
        new_points[idx] += np.random.uniform(-step, step, 2)
        new_points[idx] = _project_to_triangle(new_points[idx])

        new_score = _min_triangle_area(new_points)

        if new_score > best_score:
            best_score = new_score
            best_points = new_points.copy()
            no_improve = 0
        else:
            no_improve += 1

    return best_points

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    initial_points = _get_initial_points(11)
    optimized_points = _optimize_points(np.array(initial_points))

    return [(float(x), float(y)) for x, y in optimized_points]

