def _min_triangle_area(pts):
    min_area = float('inf')
    n = len(pts)
    # Check only nearby points to reduce complexity
    for i in range(n):
        for j in range(i+1, min(i+6, n)):
            for k in range(j+1, min(j+6, n)):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

def _hex_grid_points(n):
    k = int(math.sqrt(n)) + 1
    points = []
    for i in range(k):
        for j in range(k - i):
            x = (i + 0.5 * (j % 2)) / k
            y = (j * SQRT3 / 2) / k
            if y <= SQRT3/2 * (1 - x):
                points.append((x, y))
    return points[:n]

def _optimize_local(pts, iterations=1000):
    best_pts = pts.copy()
    best_area = _min_triangle_area(pts)
    n = len(pts)

    for _ in range(iterations):
        idx = random.randint(0, n-1)
        new_pt = (
            max(0, min(1, pts[idx][0] + random.uniform(-0.01, 0.01))),
            max(0, min(SQRT3/2, pts[idx][1] + random.uniform(-0.01, 0.01)))
        )
        # Ensure point stays in triangle
        if new_pt[1] > SQRT3 * (1 - new_pt[0]) or new_pt[1] > SQRT3 * new_pt[0]:
            continue

        new_pts = pts.copy()
        new_pts[idx] = new_pt
        new_area = _min_triangle_area(new_pts)

        if new_area > best_area:
            best_area = new_area
            best_pts = new_pts.copy()
            pts = new_pts

    return best_pts

def find_points(seed=None):
    if seed is not None:
        random.seed(seed)

    # Start with known good configuration
    pts = _hex_grid_points(11)
    if len(pts) < 11:
        pts += [(random.random(), random.random() * SQRT3/2) for _ in range(11 - len(pts))]

    # Optimize locally
    pts = _optimize_local(pts, 5000)

    # Final small adjustments
    for _ in range(1000):
        idx = random.randint(0, 10)
        new_pt = (
            max(0, min(1, pts[idx][0] + random.uniform(-0.001, 0.001))),
            max(0, min(SQRT3/2, pts[idx][1] + random.uniform(-0.001, 0.001)))
        )
        if new_pt[1] > SQRT3 * (1 - new_pt[0]) or new_pt[1] > SQRT3 * new_pt[0]:
            continue
        new_pts = pts.copy()
        new_pts[idx] = new_pt
        if _min_triangle_area(new_pts) >= _min_triangle_area(pts):
            pts = new_pts

    return [(round(x, 8), round(y, 8)) for x, y in pts]

import math
import random
import itertools
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    min_area = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area < 1e-8:
                        return min_area
    return min_area

def _is_in_triangle(p: np.ndarray) -> bool:
    x, y = p
    if x < 0 or x > 1 or y < 0 or y > SQRT3/2:
        return False
    if y > SQRT3 * x or y > SQRT3 * (1 - x):
        return False
    return True

def _generate_hexagonal_grid(n: int) -> np.ndarray:
    pts = []
    layers = math.ceil(math.sqrt(n / 3)) + 1
    for i in range(-layers, layers+1):
        for j in range(-layers, layers+1):
            x = 0.5 + 0.5 * i + 0.5 * j
            y = SQRT3/2 * j
            if _is_in_triangle([x, y]):
                pts.append([x, y])
    return np.array(pts[:n])

def _optimize_points(pts: np.ndarray, iterations: int = 500) -> np.ndarray:
    best_pts = pts.copy()
    best_score = _min_triangle_area(best_pts)
    current_pts = pts.copy()
    temp = 0.1
    cooling_rate = 0.99

    for _ in range(iterations):
        temp *= cooling_rate
        trial_pts = current_pts.copy()

        for i in range(len(trial_pts)):
            perturbation = np.random.normal(0, temp/10, 2)
            trial_pts[i] += perturbation
            x, y = trial_pts[i]
            if not _is_in_triangle(trial_pts[i]):
                trial_pts[i] = np.clip(trial_pts[i], [0, 0], [1, SQRT3/2])
                if y > SQRT3 * x or y > SQRT3 * (1 - x):
                    trial_pts[i] = current_pts[i]

        current_score = _min_triangle_area(trial_pts)
        if current_score > best_score or (current_score > 0 and 
            math.exp((current_score - best_score)/temp) > random.random()):
            best_score = current_score
            best_pts = trial_pts.copy()
            current_pts = trial_pts.copy()
        else:
            current_pts = best_pts.copy()

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    # Start with hexagonal grid
    pts = _generate_hexagonal_grid(11)
    if len(pts) < 11:
        remaining = 11 - len(pts)
        for _ in range(remaining):
            while True:
                x = random.uniform(0, 1)
                y = random.uniform(0, SQRT3/2)
                if _is_in_triangle([x, y]):
                    pts = np.vstack([pts, [x, y]])
                    break

    # Optimize
    pts = _optimize_points(pts, iterations=1000)

    # Ensure all points are unique
    unique_pts = []
    seen = set()
    for p in pts:
        p_tuple = (round(p[0], 6), round(p[1], 6))
        if p_tuple not in seen:
            seen.add(p_tuple)
            unique_pts.append(p)
        if len(unique_pts) == 11:
            break

    # If we lost points due to uniqueness check, add random ones
    while len(unique_pts) < 11:
        x = random.uniform(0, 1)
        y = random.uniform(0, SQRT3/2)
        if _is_in_triangle([x, y]):
            p_tuple = (round(x, 6), round(y, 6))
            if p_tuple not in seen:
                seen.add(p_tuple)
                unique_pts.append([x, y])

    return [(float(x), float(y)) for x, y in unique_pts]

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _point_in_triangle(p: np.ndarray) -> bool:
    x, y = p
    return (y >= 0 and y <= SQRT3/2 and 
            x >= y/SQRT3 and x <= 1 - y/SQRT3)

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            v1 = pts[j] - pts[i]
            for k in range(j+1, n):
                v2 = pts[k] - pts[i]
                area = abs(v1[0]*v2[1] - v1[1]*v2[0]) * 0.5
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0
    return min_area

def _grid_points(n: int) -> np.ndarray:
    points = []
    layers = 4
    for layer in range(1, layers+1):
        y = (layer * SQRT3) / (2 * layers)
        x_start = 0.5 - (layer * 0.5) / layers
        step = 1.0 / layers
        for i in range(layer + 1):
            x = x_start + i * step
            points.append(np.array([x, y]))

    while len(points) < n:
        points.append(_random_point())
    return np.array(points[:n])

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _optimize_local(pts: np.ndarray, steps: int = 100) -> np.ndarray:
    current = pts.copy()
    best = current.copy()
    best_val = _min_triangle_area(best)

    for _ in range(steps):
        improved = False
        for i in range(len(current)):
            for dx in [-0.01, 0, 0.01]:
                for dy in [-0.01, 0, 0.01]:
                    if dx == 0 and dy == 0:
                        continue
                    trial = current.copy()
                    trial[i] += np.array([dx, dy])
                    if not _point_in_triangle(trial[i]):
                        continue
                    val = _min_triangle_area(trial)
                    if val > best_val:
                        best_val = val
                        best = trial.copy()
                        improved = True
        if not improved:
            break
        current = best.copy()
    return best

def _anneal(n_pts: int = 11, iters: int = 2000, seed: int = 0) -> np.ndarray:
    random.seed(seed)
    pts = _grid_points(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        T = max(0.01, 0.2 * (1 - t/iters)**2)
        idx = random.randrange(n_pts)
        trial = pts.copy()
        step = 0.02 * (1 - t/iters)
        trial[idx] += np.random.uniform(-step, step, 2)

        if not _point_in_triangle(trial[idx]):
            trial[idx] = _random_point()

        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or random.random() < math.exp(delta / (T + 1e-8)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

    best_pts = _optimize_local(best_pts)
    return best_pts

def find_points(seed: int = 0) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=2000, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

