    return min_area

def _hex_grid_points(n: int) -> np.ndarray:
    pts = []
    layers = int(math.sqrt(n)) + 1
    for i in range(layers):
        for j in range(layers - i):
            x = (i + 0.5 * j) / layers
            y = (j * SQRT3 / 2) / layers
            pts.append((x, y))
    return np.array(pts[:n])

def _optimize_points(pts: np.ndarray, max_iter: int = 2000) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _fast_min_area(best_pts)
    n = len(pts)

    for iter in range(max_iter):
        step = 0.05 * (1 - iter/max_iter)**3
        improved = False

        for i in range(n):
            trial = best_pts.copy()
            trial[i] += random.uniform(-step, step), random.uniform(-step, step)
            trial[i] = _project_to_simplex(trial[i])
            area = _fast_min_area(trial)

            if area > best_area:
                best_area = area
                best_pts = trial.copy()
                improved = True

        if not improved and iter > max_iter//2:
            break

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    if seed is not None:
