    # Start with hexagonal grid
    pts = _hex_grid_points(11)

    # Add some randomness if needed
    while len(pts) < 11:
        pts = np.vstack([pts, [_random_point()]])

    # Optimize
    pts = _optimize_points(pts, max_iter=1500)

    return [(float(x), float(y)) for x, y in pts]

