import math
import random
import numpy as np
from itertools import combinations
from scipy.spatial import KDTree

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / 2.0

def _min_triangle_area_fast(pts, kdtree=None):
    if kdtree is None:
        kdtree = KDTree(pts)
    min_area = float('inf')
    for i in range(len(pts)):
        neighbors = kdtree.query_ball_point(pts[i], 0.3)
        if len(neighbors) < 2:
            continue
        for j in neighbors:
            if j <= i:
                continue
            for k in neighbors:
                if k <= j:
                    continue
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area < 1e-8:
                        return min_area
    return min_area

def _is_in_triangle(p):
    x, y = p
    if x < 0 or x > 1 or y < 0 or y > SQRT3/2:
        return False
    if y > SQRT3 * x:
        return False
    if y > SQRT3 * (1 - x):
        return False
    return True

def _generate_initial_points(n):
    points = []
    # Generate points in concentric hexagons
    layers = 4
    for layer in range(1, layers+1):
        t = layer / layers
        # Points along edges
        for i in range(layer):
            # Bottom edge
            points.append([i/layer, 0])
            # Left edge
            points.append([0.5 - i/(2*layer), i*SQRT3/(2*layer)])
            # Right edge
            points.append([0.5 + i/(2*layer), i*SQRT3/(2*layer)])

    # Add center point
    points.append([0.5, SQRT3/6])

    # Filter and select points
    valid_points = [p for p in points if _is_in_triangle(p)]
    if len(valid_points) >= n:
        return np.array(valid_points[:n])

    # Fill remaining points with quasi-random sequence
    phi = (1 + math.sqrt(5))/2
    i = len(valid_points)
    while len(valid_points) < n:
        x = (0.5 + i*phi) % 1
        y = (0.5 + i*phi*phi) % (SQRT3/2)
        if _is_in_triangle((x, y)):
            valid_points.append([x, y])
        i += 1

    return np.array(valid_points[:n])

def _optimize_points(points, iterations):
    best_points = points.copy()
    kdtree = KDTree(best_points)
    best_score = _min_triangle_area_fast(best_points, kdtree)

    for i in range(iterations):
        new_points = best_points.copy()
        idx = random.randint(0, len(points)-1)

        # Adaptive step size
        step = 0.05 * (1 - i/iterations)**0.7

        # Gradient-like move - try pushing away from nearest neighbors
        if random.random() < 0.7:
            neighbors = kdtree.query(best_points[idx], k=4)[1][1:]
            repulsion = np.zeros(2)
            for n_idx in neighbors:
                diff = best_points[idx] - best_points[n_idx]
                dist = np.linalg.norm(diff)
                if dist > 1e-6:
                    repulsion += diff / (dist**2)
            if np.linalg.norm(repulsion) > 1e-6:
                repulsion = repulsion / np.linalg.norm(repulsion)
                new_points[idx] += step * repulsion * random.uniform(0.5, 1.5)
        else:
            new_points[idx] += np.random.uniform(-step, step, 2)

        if not _is_in_triangle(new_points[idx]):
            continue

        new_kdtree = KDTree(new_points)
        new_score = _min_triangle_area_fast(new_points, new_kdtree)

        if new_score > best_score:
            best_score = new_score
            best_points = new_points.copy()
            kdtree = new_kdtree

    return best_points

def find_points(seed=None):
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    points = _generate_initial_points(11)
    points = _optimize_points(points, 5000)

    return [(float(p[0]), float(p[1])) for p in points]

