import math
import random
import itertools
from typing import List, Tuple
import numpy as np

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    best = float("inf")
    n = len(pts)
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best < 1e-8:
                        return 0
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    w = 1.0 - u - v
    if u >= 0 and v >= 0 and w >= 0:
        return p
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        s = u + v
        u /= s
        v /= s
    return (1 - u - v) * _A + u * _B + v * _C

def _uniform_configuration(n_pts: int = 11) -> np.ndarray:
    pts = []
    for _ in range(n_pts):
        pts.append(_random_point())
    return np.array(pts)

def _differential_evolution(n_pts: int = 11,
                          max_iter: int = 500,
                          F: float = 0.5,
                          CR: float = 0.7,
                          seed: int | None = 0) -> np.ndarray:
    random.seed(seed)
    population = [_uniform_configuration(n_pts) for _ in range(20)]
    best_pts = max(population, key=lambda x: _min_triangle_area(x))
    best_val = _min_triangle_area(best_pts)

    for _ in range(max_iter):
        for i in range(len(population)):
            a, b, c = random.sample(range(len(population)), 3)
            mutant = population[a] + F * (population[b] - population[c])
            for j in range(n_pts):
                if random.random() < CR:
                    mutant[j] = _project_to_simplex(mutant[j])
            trial_val = _min_triangle_area(mutant)
            if trial_val > _min_triangle_area(population[i]):
                population[i] = mutant
                if trial_val > best_val:
                    best_val = trial_val
                    best_pts = mutant.copy()
    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _differential_evolution(n_pts=11, seed=seed)
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

import math
import random
import numpy as np
from typing import List, Tuple
from scipy.spatial import Delaunay

SQRT3 = math.sqrt(3.0)

def _hexagonal_grid(n: int) -> List[np.ndarray]:
    k = math.ceil(math.sqrt(n / (SQRT3/2)))
    pts = []
    for i in range(k):
        for j in range(k):
            x = (i + 0.5 * (j % 2)) / k
            y = (SQRT3/2) * j / k
            if x <= 1 and y <= SQRT3/2:
                pts.append(np.array([x, y]))
    return pts[:n] if len(pts) >= n else pts + [np.array([random.random(), random.random() * SQRT3/2]) for _ in range(n - len(pts))]

def _is_inside(p: np.ndarray) -> bool:
    x, y = p
    return y >= 0 and y <= SQRT3/2 and x >= 0 and x <= 1 and y <= SQRT3 * x and y <= SQRT3 * (1 - x)

def _project(p: np.ndarray) -> np.ndarray:
    x, y = p
    if not _is_inside(p):
        x = max(0, min(1, x))
        y = max(0, min(SQRT3/2, y))
        if y > SQRT3 * x or y > SQRT3 * (1 - x):
            y = min(SQRT3 * x, SQRT3 * (1 - x))
    return np.array([x, y])

def _min_area_fast(pts: np.ndarray) -> float:
    min_area = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a, b, c = pts[i], pts[j], pts[k]
                area = abs((b[0]-a[0])*(c[1]-a[1]) - (b[1]-a[1])*(c[0]-a[0])) / 2
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0.0
    return min_area

def _optimize(pts: np.ndarray, steps: int = 1000) -> np.ndarray:
    current_pts = pts.copy()
    current_area = _min_area_fast(current_pts)

    for step in range(steps):
        temp = 1.0 - step / steps
        for i in range(len(current_pts)):
            best_move = None
            best_area = current_area

            for _ in range(5):
                angle = random.uniform(0, 2*math.pi)
                distance = temp * 0.1
                dx, dy = math.cos(angle) * distance, math.sin(angle) * distance
                new_pt = _project(current_pts[i] + np.array([dx, dy]))

                trial_pts = current_pts.copy()
                trial_pts[i] = new_pt
                trial_area = _min_area_fast(trial_pts)

                if trial_area > best_area:
                    best_area = trial_area
                    best_move = new_pt

            if best_move is not None:
                current_pts[i] = best_move
                current_area = best_area

    return current_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    initial_pts = _hexagonal_grid(11)
    optimized_pts = _optimize(np.array(initial_pts), 500)
    return [(float(x), float(y)) for x, y in optimized_pts]

