    return np.array(points[:n])

def _is_inside_triangle(x: float, y: float) -> bool:
    return y > 0 and y < SQRT3/2 and x > 0 and x < 1 and (1 - x) * SQRT3 > y

def _project_to_triangle(x: float, y: float) -> Tuple[float, float]:
    x = max(0.001, min(0.999, x))
    y = max(0.001, min(SQRT3/2 - 0.001, y))
    if (1 - x) * SQRT3 <= y:
        y = (1 - x) * SQRT3 * 0.999
    return x, y

def _optimize_points(pts: np.ndarray, max_iter: int = 200) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area_fast(best_pts)
    n = len(pts)

    for _ in range(max_iter):
        improved = False
        for i in range(n):
            for dx, dy in [(0.002, 0), (-0.002, 0), (0, 0.002), (0, -0.002)]:
                trial = best_pts.copy()
                trial[i] += np.array([dx, dy])
                x, y = trial[i]
                x, y = _project_to_triangle(x, y)
                trial[i] = np.array([x, y])

                area = _min_triangle_area_fast(trial)
                if area > best_area:
                    best_area = area
                    best_pts = trial.copy()
                    improved = True
        if not improved:
            break
    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    pts = _hex_grid_points(11)

    for i in range(len(pts)):
        x, y = pts[i]
        x += np.random.uniform(-0.001, 0.001)
        y += np.random.uniform(-0.001, 0.001)
        x, y = _project_to_triangle(x, y)
        pts[i] = np.array([x, y])

    pts = _optimize_points(pts)

    return [(float(x), float(y)) for x, y in pts]

from __future__ import annotations
import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    w = 1.0 - u - v
    if u >= 0 and v >= 0 and w >= 0:
        return p
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        s = u + v
        u /= s
        v /= s
    return (1 - u - v) * _A + u * _B + v * _C

def _min_triangle_area_fast(pts: np.ndarray) -> float:
    n = len(pts)
    best = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            p1 = pts[j] - pts[i]
            for k in range(j+1, n):
                p2 = pts[k] - pts[i]
                area = abs(p1[0]*p2[1] - p1[1]*p2[0]) * 0.5
                if area < best:
                    best = area
                    if best < 1e-8:
                        return 0
    return best

def _hexagonal_initialization(n: int) -> np.ndarray:
    pts = []
    layers = math.ceil((math.sqrt(8*n/3 + 1) - 1)/2)
    for layer in range(layers):
        count = layer + 1
        for i in range(count):
            u = (i + 0.5 * (layer % 2)) / (2*layers)
            v = (layer + 0.5) / (2*layers)
            if u + v <= 1.0:
                pts.append((1 - u - v) * _A + u * _B + v * _C)
                if len(pts) == n:
                    return np.array(pts)
    while len(pts) < n:
        pts.append(_random_point())
    return np.array(pts)

def _optimize(pts: np.ndarray, steps: int = 300) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area_fast(best_pts)
    step_size = 0.1

    for _ in range(steps):
        improved = False
        for i in range(len(pts)):
            for _ in range(10):
                trial = best_pts.copy()
                trial[i] += np.random.normal(0, step_size, 2)
                trial[i] = _project_to_simplex(trial[i])
                trial_val = _min_triangle_area_fast(trial)
                if trial_val > best_val + 1e-8:
                    best_val = trial_val
                    best_pts = trial.copy()
                    improved = True
                    break
        if not improved:
            step_size *= 0.7
    return best_pts

def _refine_smallest(pts: np.ndarray, steps: int = 50) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area_fast(best_pts)
    step_size = 0.02

    for _ in range(steps):
        trial = best_pts.copy()
        for i in range(len(pts)):
            trial[i] += np.random.normal(0, step_size, 2)
            trial[i] = _project_to_simplex(trial[i])
        trial_val = _min_triangle_area_fast(trial)
        if trial_val > best_val + 1e-8:
            best_val = trial_val
            best_pts = trial.copy()
        else:
            step_size *= 0.9
    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)
    pts = _hexagonal_initialization(11)
    pts = _optimize(pts)
    pts = _refine_smallest(pts)
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

from __future__ import annotations

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / (2 * TRIANGLE_AREA)

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n-2):
        for j in range(i+1, n-1):
            p0 = pts[j] - pts[i]
            for k in range(j+1, n):
                p1 = pts[k] - pts[i]
                area = abs(p0[0]*p1[1] - p0[1]*p1[0]) / (2 * TRIANGLE_AREA)
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0
    return min_area

def _random_point_in_triangle() -> np.ndarray:
    r1 = random.random()
    r2 = random.random()
    if r1 + r2 > 1:
        r1 = 1 - r1
        r2 = 1 - r2
    x = r1 * 1.0 + r2 * 0.5
    y = r2 * SQRT3 / 2.0
    return np.array([x, y])

def _initialize_points(n_pts: int) -> np.ndarray:
    # Improved initialization with hexagonal pattern
    pts = []
    layers = 3
    for layer in range(layers):
        radius = 0.3 + 0.3 * layer / (layers-1)
        points_in_layer = max(3, round(6 * layer / layers))
        for i in range(points_in_layer):
            angle = 2 * math.pi * i / points_in_layer
            x = 0.5 + radius * math.cos(angle)
            y = SQRT3/3 + radius * SQRT3/3 * math.sin(angle)
            pts.append(np.array([x, y]))
    while len(pts) < n_pts:
        pts.append(_random_point_in_triangle())
    return np.array(pts[:n_pts])

def _is_in_triangle(p: np.ndarray) -> bool:
    x, y = p
    if y < 0 or y > SQRT3/2:
        return False
    if x < 0 or x > 1:
        return False
    if y > SQRT3 * x or y > SQRT3 * (1 - x):
        return False
    return True

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    x, y = p
    if _is_in_triangle(p):
        return p

    edge1 = lambda x: SQRT3 * x
    edge2 = lambda x: SQRT3 * (1 - x)

    if y < 0:
        x = max(0.01, min(0.99, x))
        return np.array([x, 0.01])

    d1 = abs(y - edge1(x))
    d2 = abs(y - edge2(x))

    if d1 < d2:
        y_proj = edge1(x)
        return np.array([max(0.01, min(0.99, x)), max(0.01, min(y_proj, SQRT3/2 - 0.01))])
    else:
        y_proj = edge2(x)
        return np.array([max(0.01, min(0.99, x)), max(0.01, min(y_proj, SQRT3/2 - 0.01))])

def _anneal(n_pts: int = 11,
            iters: int = 50000,
            start_temp: float = 0.2,
            end_temp: float = 1e-10,
            step_size: float = 0.05,
            seed: int | None = None) -> np.ndarray:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _initialize_points(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    accept_count = 0

    for t in range(iters):
        T = start_temp * (end_temp / start_temp) ** (t / iters)
        current_step = step_size * (1 - 0.9 * t/iters)

        trial = pts.copy()
        if random.random() < 0.1:  # Multi-point move
            for _ in range(1 + int(random.random() * 3)):
                idx = random.randrange(n_pts)
                delta = np.random.normal(0, current_step/2, size=2)
                trial[idx] += delta
                trial[idx] = _project_to_triangle(trial[idx])
        else:  # Single-point move
            idx = random.randrange(n_pts)
            if t % 200 == 0:
                trial[idx] = _random_point_in_triangle()
            else:
                delta = np.random.normal(0, current_step, size=2)
                trial[idx] += delta
                trial[idx] = _project_to_triangle(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta_val = trial_val - best_val

        if delta_val > 0 or (T > 0 and math.exp(delta_val / T) > random.random()):
            pts = trial
            accept_count += 1
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

        # Adaptive step size
        if t % 100 == 0 and t > 0:
            accept_rate = accept_count / 100
            if accept_rate < 0.2:
                step_size *= 0.9
            elif accept_rate > 0.5:
                step_size *= 1.1
            accept_count = 0

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

