import math
import random
import itertools
from typing import List, Tuple
import numpy as np

SQRT3 = math.sqrt(3.0)
TRI_AREA = SQRT3 / 4.0  # Area of unit equilateral triangle

def _area(p, q, r) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / (2 * TRI_AREA)

def _min_triangle_area(pts: np.ndarray) -> float:
    min_area = float('inf')
    n = len(pts)
    for i in range(n-2):
        for j in range(i+1, n-1):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

def _is_inside_triangle(pt: np.ndarray) -> bool:
    x, y = pt
    if x < 0 or x > 1 or y < 0 or y > SQRT3/2:
        return False
    if y > SQRT3 * x or y > SQRT3 * (1 - x):
        return False
    return True

def _random_point() -> np.ndarray:
    while True:
        x = random.uniform(0.01, 0.99)
        y_max = min(SQRT3 * x, SQRT3 * (1 - x))
        y = random.uniform(0.01, y_max - 0.01)
        pt = np.array([x, y])
        if _is_inside_triangle(pt):
            return pt

def _initial_configuration() -> np.ndarray:
    pts = []
    # Add symmetric points
    pts.append(np.array([0.0, 0.0]))
    pts.append(np.array([1.0, 0.0]))
    pts.append(np.array([0.5, SQRT3/2]))

    # Hexagonal lattice points
    for i in range(1, 4):
        for j in range(i+1):
            x = 0.5 - i/8 + j/4
            y = SQRT3 * (i/8)
            if x > 0 and x < 1 and y > 0 and y < SQRT3/2:
                pts.append(np.array([x, y]))

    # Fill remaining points randomly
    while len(pts) < 11:
        pt = _random_point()
        too_close = False
        for p in pts:
            if np.linalg.norm(p - pt) < 0.05:
                too_close = True
                break
        if not too_close:
            pts.append(pt)

    return np.array(pts[:11])

def _perturb_point(pt: np.ndarray, step_size: float) -> np.ndarray:
    while True:
        new_pt = pt + np.random.uniform(-step_size, step_size, 2)
        if _is_inside_triangle(new_pt):
            return new_pt

def _optimize(pts: np.ndarray, iterations: int = 5000) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)
    current_pts = pts.copy()

    for i in range(iterations):
        step_size = 0.1 * (1 - i/iterations)
        temp = 0.1 * (1 - i/iterations)

        # Select random point to move
        idx = random.randint(0, len(current_pts)-1)
        original_pt = current_pts[idx].copy()

        # Generate new candidate
        candidate_pt = _perturb_point(original_pt, step_size)
        current_pts[idx] = candidate_pt

        # Evaluate
        current_area = _min_triangle_area(current_pts)
        delta = current_area - best_area

        # Acceptance criterion
        if delta > 0 or (temp > 0 and random.random() < math.exp(delta/temp)):
            if current_area > best_area:
                best_area = current_area
                best_pts = current_pts.copy()
        else:
            current_pts[idx] = original_pt

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _initial_configuration()
    pts = _optimize(pts, iterations=10000)

    # Final local optimization
    for _ in range(1000):
        improved = False
        for i in range(len(pts)):
            original = pts[i].copy()
            best_local = original.copy()
            best_local_area = _min_triangle_area(pts)

            for _ in range(10):
                candidate = _perturb_point(original, 0.01)
                pts[i] = candidate
                current_area = _min_triangle_area(pts)
                if current_area > best_local_area:
                    best_local_area = current_area
                    best_local = candidate.copy()
                    improved = True

            pts[i] = best_local

        if not improved:
            break

    return [(float(x), float(y)) for x, y in pts]

from __future__ import annotations

import math
import random
import itertools
from typing import List, Tuple, Optional
import numpy as np

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0
EPSILON = 1e-10

def _is_inside_triangle(pt: np.ndarray) -> bool:
    x, y = pt
    return (y >= -EPSILON and x >= -EPSILON and 
            (x + y/SQRT3) <= 1 + EPSILON and 
            (x - y/SQRT3) <= EPSILON and 
            y <= (SQRT3/2 + EPSILON))

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5 / TRIANGLE_AREA

class MinAreaTracker:
    def __init__(self, pts: np.ndarray):
        self.pts = pts.copy()
        self.n = len(pts)
        self.triplets = list(itertools.combinations(range(self.n), 3))
        self.point_to_triplets = [[] for _ in range(self.n)]
        for idx_triplet, triplet in enumerate(self.triplets):
            for i in triplet:
                self.point_to_triplets[i].append(idx_triplet)
        self.areas_arr = np.zeros(len(self.triplets))
        for idx_triplet, (i, j, k) in enumerate(self.triplets):
            self.areas_arr[idx_triplet] = _area(pts[i], pts[j], pts[k])
        self.min_area = np.min(self.areas_arr)

    def update_point(self, idx: int, new_pos: np.ndarray) -> bool:
        if not _is_inside_triangle(new_pos):
            return False
        self.pts[idx] = new_pos
        for idx_triplet in self.point_to_triplets[idx]:
            i, j, k = self.triplets[idx_triplet]
            self.areas_arr[idx_triplet] = _area(self.pts[i], self.pts[j], self.pts[k])
        self.min_area = np.min(self.areas_arr)
        return True

    def get_min_area(self) -> float:
        return self.min_area

def _random_barycentric(rng: np.random.Generator) -> Tuple[float, float, float]:
    u, v = rng.random(2)
    if u + v > 1:
        u, v = 1 - u, 1 - v
    return (1 - u - v, u, v)

def _barycentric_to_cartesian(bary: Tuple[float, float, float]) -> np.ndarray:
    a, b, c = bary
    return np.array([0.5 * (b - a) + c * 0.5, c * SQRT3 / 2])

def _initial_configuration(n_pts: int = 11, rng: np.random.Generator = None) -> np.ndarray:
    if rng is None:
        rng = np.random.default_rng()

    pts = []
    # Hexagonal lattice points
    k = math.ceil(math.sqrt(2 * n_pts / (SQRT3/2)))
    offset = 1/(2*k)
    for i in range(k):
        for j in range(k):
            if len(pts) >= n_pts:
                break
            x = (i + 0.5 * (j % 2)) / k + offset
            y = (j * SQRT3 / 2) / k + offset
            pt = np.array([x, y])
            if _is_inside_triangle(pt):
                pts.append(pt)

    # Fill remaining points with random positions
    while len(pts) < n_pts:
        bary = _random_barycentric(rng)
        pt = _barycentric_to_cartesian(bary)
        if _is_inside_triangle(pt):
            pts.append(pt)

    return np.array(pts[:n_pts])

def _optimize(n_pts: int = 11, iters: int = 10000, seed: int | None = None) -> np.ndarray:
    rng = np.random.default_rng(seed)
    pts = _initial_configuration(n_pts, rng)
    tracker = MinAreaTracker(pts)
    best_pts = pts.copy()
    best_val = tracker.get_min_area()

    for t in range(iters):
        T = max(0.01 * (1 - t/iters), 1e-6)
        step_size = 0.02 * (1 - t/iters) + 0.001

        idx = rng.integers(0, n_pts)
        old_pos = pts[idx].copy()

        # Move in barycentric coordinates
        bary = _random_barycentric(rng)
        new_pos = _barycentric_to_cartesian(bary)

        if not tracker.update_point(idx, new_pos):
            continue

        trial_val = tracker.get_min_area()
        delta = trial_val - best_val

        if delta > 0 or rng.random() < math.exp(delta / T):
            pts = tracker.pts.copy()
            if trial_val > best_val:
                best_val = trial_val
                best_pts = pts.copy()
        else:
            tracker.update_point(idx, old_pos)

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    pts = _optimize(n_pts=11, iters=10000, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _is_inside_triangle(x: float, y: float) -> bool:
    return (0 <= x <= 1 and 0 <= y <= SQRT3/2 and 
            y <= SQRT3*(1 - abs(2*x - 1)))

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    best = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

def _hexagonal_grid(n: int) -> np.ndarray:
    pts = []
    size = int(math.ceil(math.sqrt(n * 2)))
    for i in range(size):
        for j in range(size):
            if len(pts) >= n:
                break
            x = 0.5 + (i - j) * 0.5 / size
            y = j * SQRT3 / 2 / size
            if _is_inside_triangle(x, y):
                pts.append([x, y])
    while len(pts) < n:
        x = random.uniform(0, 1)
        y = random.uniform(0, SQRT3/2)
        if _is_inside_triangle(x, y):
            pts.append([x, y])
    return np.array(pts)

def _optimize_points(pts: np.ndarray, iterations: int = 2000) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)
    n = len(pts)

    for _ in range(iterations):
        new_pts = best_pts.copy()
        idx = random.randint(0, n-1)
        step = 0.05 * (1 - _/iterations)

        # Generate new candidate point with boundary checks
        for _ in range(10):  # Try up to 10 times to find valid point
            new_pt = best_pts[idx] + np.random.uniform(-step, step, 2)
            x, y = new_pt
            if _is_inside_triangle(x, y):
                new_pts[idx] = new_pt
                break

        new_area = _min_triangle_area(new_pts)
        if new_area > best_area:
            best_area = new_area
            best_pts = new_pts.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _hexagonal_grid(11)
    pts = _optimize_points(pts, 2000)

    return [(float(x), float(y)) for x, y in pts]

