    u, v = random.random(), random.random()
    if u + v > 1.0:
        u, v = 1-u, 1-v
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex_fast(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv[0], uv[1]
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _initial_points(n_pts: int = 11) -> np.ndarray:
    pts = []
    size = int(math.ceil(math.sqrt(n_pts * 2 / SQRT3)))
    for i in range(size):
        for j in range(size):
            if len(pts) >= n_pts:
                break
            x = (i + 0.5 * (j % 2)) / size
            y = (j * SQRT3 / 2) / size
            if x + y/SQRT3 <= 1.0 and y <= SQRT3/2:
                pts.append(np.array([x, y]))
    while len(pts) < n_pts:
        pts.append(_random_point_fast())
    return np.array(pts[:n_pts])

def _anneal_fast(n_pts: int = 11, iters: int = 5000, seed: int | None = 0) -> np.ndarray:
    rng = random.Random(seed)
    pts = _initial_points(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area_fast(best_pts)

    for t in range(iters):
        T = 0.2 * (1e-5 / 0.2) ** ((t / max(iters-1, 1))**0.7)
        idx = rng.randrange(n_pts)
        trial = pts.copy()
        trial[idx] += rng.uniform(-0.03, 0.03), rng.uniform(-0.03, 0.03)
        trial[idx] = _project_to_simplex_fast(trial[idx])

        trial_val = _min_triangle_area_fast(trial)
        if trial_val > best_val or rng.random() < math.exp((trial_val - best_val)/max(T, 1e-12)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = pts.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    start_time = time.time()
    pts = _anneal_fast(n_pts=11, iters=5000, seed=seed)

    if time.time() - start_time < 25:
        try:
            from scipy.optimize import minimize
            n_pts = len(pts)
            x0 = pts.ravel()

            def f(x: np.ndarray) -> float:
                P = x.reshape((-1, 2))
                return -_min_triangle_area_fast(P)

            res = minimize(
                f,
                x0,
                method="Nelder-Mead",
                options=dict(maxiter=200)
            )

            if res.success:
                pts = res.x.reshape((n_pts, 2))
                for i in range(n_pts):
                    pts[i] = _project_to_simplex_fast(pts[i])

            if time.time() - start_time < 28:
                x0 = pts.ravel()
                res = minimize(
                    f,
                    x0,
                    method="Powell",
                    options=dict(maxiter=100)
                )
                if res.success:
                    pts = res.x.reshape((n_pts, 2))
                    for i in range(n_pts):
                        pts[i] = _project_to_simplex_fast(pts[i])
        except:
            pass

    return [(float(x), float(y)) for x, y in pts]

from __future__ import annotations

import math
import random
import itertools
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0
comb = list(itertools.combinations(range(11), 3))

def _area(p, q, r) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / (2 * TRIANGLE_AREA)

def _min_triangle_area(pts: np.ndarray) -> float:
    min_area = float('inf')
    for i, j, k in comb:
        a = _area(pts[i], pts[j], pts[k])
        if a < min_area:
            min_area = a
            if min_area == 0:
                return 0
    return min_area

def _is_in_triangle(p: np.ndarray) -> bool:
    x, y = p
    if x < 0 or x > 1 or y < 0 or y > SQRT3/2:
        return False
    if y > SQRT3 * x or y > SQRT3 * (1 - x):
        return False
    return True

def _generate_point() -> np.ndarray:
    while True:
        x = random.uniform(0, 1)
        y_max = min(SQRT3 * x, SQRT3 * (1 - x))
        y = random.uniform(0, y_max)
        p = np.array([x, y])
        if _is_in_triangle(p):
            return p

def _hexagonal_grid() -> np.ndarray:
    pts = []
    layers = 4
    for i in range(layers):
        for j in range(layers - i):
            u = (i + 0.5 * (j % 2)) / layers
            v = (j + 0.5 * (i % 2)) / layers
            if u + v <= 1.0:
                x = 0.5 * (1 - u - v) + u * 1.0 + v * 0.5
                y = v * SQRT3 / 2.0
                pts.append([x, y])
    while len(pts) < 11:
        pts.append(_generate_point())
    return np.array(pts[:11])

def _optimize(pts: np.ndarray, iterations: int = 2000) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)
    n = len(pts)
    step = 0.05

    for _ in range(iterations):
        idx = random.randint(0, n-1)
        new_pts = best_pts.copy()
        dx = random.uniform(-step, step)
        dy = random.uniform(-step, step)
        new_pt = np.array([best_pts[idx][0] + dx, best_pts[idx][1] + dy])

        if _is_in_triangle(new_pt):
            new_pts[idx] = new_pt
            new_area = _min_triangle_area(new_pts)
            if new_area > best_area:
                best_area = new_area
                best_pts = new_pts.copy()

        if _ % 100 == 0:
            step *= 0.99

    return best_pts

def _refine(pts: np.ndarray, iterations: int = 1000) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)
    n = len(pts)

    for _ in range(iterations):
        temp = 1.0 - (_ / iterations)
        step = 0.01 * temp

        idx = random.randint(0, n-1)
        new_pts = best_pts.copy()
        angle = random.uniform(0, 2*math.pi)
        dx = step * math.cos(angle)
        dy = step * math.sin(angle)
        new_pt = np.array([best_pts[idx][0] + dx, best_pts[idx][1] + dy])

        if _is_in_triangle(new_pt):
            new_pts[idx] = new_pt
            new_area = _min_triangle_area(new_pts)
            if new_area > best_area or (temp > 0 and random.random() < math.exp((new_area - best_area)/temp)):
                best_area = new_area
                best_pts = new_pts.copy()

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    best_pts = None
    best_area = 0.0

    for _ in range(5):
        if random.random() < 0.7:
            pts = _hexagonal_grid()
        else:
            pts = np.array([_generate_point() for _ in range(11)])

        pts = _optimize(pts, 1500)
        pts = _refine(pts, 800)

        current_area = _min_triangle_area(pts)
        if current_area > best_area:
            best_area = current_area
            best_pts = pts.copy()

    return [(float(x), float(y)) for x, y in best_pts]

