import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    best = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

def _hex_grid(n: int) -> np.ndarray:
    pts = []
    layers = math.ceil(math.sqrt(n / 3)) + 1
    for i in range(-layers, layers+1):
        for j in range(-layers, layers+1):
            x = 0.5 + 0.5 * i + 0.25 * j
            y = SQRT3/4 * j
            pts.append([x, y])
    pts = np.array(pts)
    inside = []
    for p in pts:
        try:
            u, v = np.linalg.solve(np.column_stack((_B-_A, _C-_A)), p-_A)[0]
            if u >= -1e-8 and v >= -1e-8 and (1-u-v) >= -1e-8:
                inside.append(p)
        except:
            continue
    if len(inside) < n:
        inside = []
        while len(inside) < n:
            x = random.uniform(0, 1)
            y = random.uniform(0, SQRT3/2)
            if y <= SQRT3 * x and y <= SQRT3 * (1 - x):
                inside.append([x, y])
    return np.array(inside[:n])

def _differential_evolution(pop_size: int, n_pts: int, max_iter: int) -> np.ndarray:
    F = 0.8
    CR = 0.9
    bounds = np.array([[0, 1], [0, SQRT3/2]])

    def eval_fn(x):
        return -_min_triangle_area(x)

    pop = [_hex_grid(n_pts) for _ in range(pop_size)]
    best_sol = pop[0].copy()
    best_val = eval_fn(best_sol)

    for _ in range(max_iter):
        for i in range(pop_size):
            idxs = [idx for idx in range(pop_size) if idx != i]
            a, b, c = pop[np.random.choice(idxs, 3, replace=False)]
            mutant = a + F * (b - c)

            cross_points = np.random.rand(n_pts, 2) < CR
            trial = np.where(cross_points, mutant, pop[i])

            trial = np.clip(trial, bounds[:, 0], bounds[:, 1])

            trial_val = eval_fn(trial)
            if trial_val < best_val:
                best_val = trial_val
                best_sol = trial.copy()
            if trial_val < eval_fn(pop[i]):
                pop[i] = trial

    return best_sol

def _refine(pts: np.ndarray, steps: int) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    n_pts = len(pts)

    for step in range(steps):
        step_size = 0.01 * (1 - step/steps)
        for idx in range(n_pts):
            for _ in range(10):
                trial = best_pts.copy()
                trial[idx] += np.random.uniform(-step_size, step_size, 2)
                try:
                    u, v = np.linalg.solve(np.column_stack((_B-_A, _C-_A)), trial[idx]-_A)[0]
                    if u < -1e-8 or v < -1e-8 or (1-u-v) < -1e-8:
                        continue
                except:
                    continue
                trial_val = _min_triangle_area(trial)
                if trial_val > best_val:
                    best_val = trial_val
                    best_pts = trial.copy()
    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    pts = _differential_evolution(pop_size=20, n_pts=11, max_iter=50)
    pts = _refine(pts, steps=200)

    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

