SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5 / TRIANGLE_AREA

def _min_triangle_area(pts: np.ndarray) -> float:
    min_area = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

def _is_inside_triangle(p: np.ndarray) -> bool:
    x, y = p
    if x < 0 or x > 1 or y < 0 or y > SQRT3/2:
        return False
    if y > SQRT3 * x or y > SQRT3 * (1 - x):
        return False
    return True

def _random_point_inside() -> np.ndarray:
    while True:
        x = random.uniform(0, 1)
        y = random.uniform(0, SQRT3/2)
        if _is_inside_triangle(np.array([x, y])):
            return np.array([x, y])

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    x, y = p
    x = max(0.0, min(1.0, x))
    y = max(0.0, min(SQRT3/2, y))

    if y > SQRT3 * x:
        y = SQRT3 * x
    if y > SQRT3 * (1 - x):
        y = SQRT3 * (1 - x)

    return np.array([x, y])

def _hexagonal_grid(n: int) -> List[np.ndarray]:
    points = []
    size = math.ceil(math.sqrt(n * 2 / SQRT3))
    for i in range(size):
        for j in range(size):
            x = (i + 0.5 * (j % 2)) / size
            y = (j * SQRT3 / 2) / size
            if _is_inside_triangle(np.array([x, y])):
                points.append(np.array([x, y]))
                if len(points) == n:
                    return points
    while len(points) < n:
        points.append(_random_point_inside())
    return points[:n]

def _optimize_points(points: np.ndarray, iterations: int = 1000) -> np.ndarray:
    n = len(points)
    best_points = points.copy()
    best_score = _min_triangle_area(best_points)
    no_improvement = 0

    for t in range(iterations):
        temp = 0.1 * (1e-8 / 0.1) ** (t / (iterations - 1))
        step = 0.05 * (1 - t/iterations)

        for _ in range(3):
            idx = random.randrange(n)
            new_points = points.copy()
            new_points[idx] += np.random.uniform(-step, step, 2)
            new_points[idx] = _project_to_triangle(new_points[idx])

            new_score = _min_triangle_area(new_points)
            delta = new_score - best_score

            if delta > 0 or random.random() < math.exp(delta / max(temp, 1e-12)):
                points = new_points
                if new_score > best_score:
                    best_score = new_score
                    best_points = new_points.copy()
                    no_improvement = 0
                else:
                    no_improvement += 1

        if no_improvement > 50:
            break

    return best_points

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    initial_points = _hexagonal_grid(11)
    optimized_points = _optimize_points(np.array(initial_points), 1000)

    return [(float(x), float(y)) for x, y in optimized_points]

