import numpy as np

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    min_area = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _initialize_points(n: int) -> np.ndarray:
    pts = []
    for i in range(n):
        u = (i + 0.5) / n
        for j in range(n):
            v = (j + 0.5) / n
            if u + v <= 1.0:
                pts.append((1 - u - v) * _A + u * _B + v * _C)
                if len(pts) == n:
                    return np.array(pts)
    return np.array([_A + (_B - _A) * np.random.random() + (_C - _A) * np.random.random() for _ in range(n)])

def _optimize_points(pts: np.ndarray, max_iter: int = 1000) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    n = len(pts)
    step_size = 0.05

    for _ in range(max_iter):
        for i in range(n):
            trial = pts.copy()
            trial[i] += np.random.uniform(-step_size, step_size, size=2)
            trial[i] = _project_to_simplex(trial[i])
            trial_val = _min_triangle_area(trial)

            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()
                pts = trial.copy()

        step_size *= 0.99

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    if seed is not None:
        np.random.seed(seed)
    pts = _initialize_points(11)
    pts = _optimize_points(pts, 2000)
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

from __future__ import annotations

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    best = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _is_inside(p: np.ndarray) -> bool:
    u = p[0]
    v = p[1] * 2 / SQRT3
    return u >= 0 and v >= 0 and u + v <= 1

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        total = u + v
        u /= total
        v /= total
    return (1 - u - v) * _A + u * _B + v * _C

def _initial_configuration(n_pts: int = 11) -> np.ndarray:
    pts = []
    # Hexagonal lattice pattern
    layers = 4
    for layer in range(layers):
        for i in range(layer + 1):
            u = (i + 0.5) / layers
            v = (layer - i + 0.5) / layers
            pts.append((1 - u - v) * _A + u * _B + v * _C)
    while len(pts) < n_pts:
        pts.append(_random_point())
    return np.array(pts[:n_pts])

def _differential_evolution(n_pts: int = 11,
                          max_iter: int = 300,
                          F: float = 0.7,
                          CR: float = 0.9,
                          seed: int | None = None) -> np.ndarray:
    if seed is not None:
        random.seed(seed)
    population = [_initial_configuration(n_pts) for _ in range(15)]
    best_pts = max(population, key=lambda x: _min_triangle_area(x))
    best_val = _min_triangle_area(best_pts)
    no_improve = 0

    for _ in range(max_iter):
        for i in range(len(population)):
            a, b, c = random.sample(range(len(population)), 3)
            mutant = population[a].copy()
            for j in range(n_pts):
                if random.random() < CR:
                    mutant[j] = _project_to_simplex(population[a][j] + 
                               F * (population[b][j] - population[c][j]))
            trial_val = _min_triangle_area(mutant)
            if trial_val > _min_triangle_area(population[i]):
                population[i] = mutant
                if trial_val > best_val:
                    best_val = trial_val
                    best_pts = mutant.copy()
                    no_improve = 0
                else:
                    no_improve += 1
        if no_improve > 30:
            break
    return best_pts

def _local_search(pts: np.ndarray, steps: int = 300) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    n_pts = len(pts)
    for step_num in range(steps):
        trial = best_pts.copy()
        idx = random.randrange(n_pts)
        step = 0.02 * (1 - step_num/steps)**3
        trial[idx] = _project_to_simplex(trial[idx] + 
                       np.random.uniform(-step, step, 2))
        trial_val = _min_triangle_area(trial)
        if trial_val > best_val:
            best_val = trial_val
            best_pts = trial.copy()
    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    pts = _differential_evolution(n_pts=11, max_iter=300, seed=seed)
    pts = _local_search(pts, steps=300)
    return [(float(x), float(y)) for x, y in pts]

from __future__ import annotations

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    u, v = random.random(), random.random()
    if u + v > 1.0:
        u, v = 1 - u, 1 - v
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = 1 - u, 1 - v
    return (1 - u - v) * _A + u * _B + v * _C

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')

    for i in range(n):
        for j in range(i+1, min(i+20, n)):
            for k in range(j+1, min(j+20, n)):
                p, q, r = pts[i], pts[j], pts[k]
                area = abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0.0
    return min_area

def _get_smallest_triangles(pts: np.ndarray, k: int = 8) -> List[int]:
    n = len(pts)
    areas = []

    for i in range(n):
        for j in range(i+1, min(i+20, n)):
            for k in range(j+1, min(j+20, n)):
                p, q, r = pts[i], pts[j], pts[k]
                area = abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5
                areas.append((area, i, j, k))

    areas.sort()
    involved = set()
    for _, i, j, k in areas[:k]:
        involved.update([i, j, k])
    return list(involved)

def _anneal(n_pts: int = 11,
            iters: int = 30000,
            start_temp: float = 0.5,
            end_temp: float = 1e-12,
            seed: int | None = 0) -> np.ndarray:

    random.seed(seed)
    # Improved initial placement
    pts = []
    for i in range(n_pts):
        if i == 0:
            pts.append(np.array([0.5, SQRT3/6]))
        elif i == 1:
            pts.append(np.array([0.25, SQRT3/12]))
        elif i == 2:
            pts.append(np.array([0.75, SQRT3/12]))
        else:
            pts.append(_random_point())
    pts = np.array(pts)

    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        T = start_temp * math.exp(math.log(end_temp/start_temp) * (t/iters)**1.2)

        step_size = 0.04 * math.exp(-4.0 * t/iters) + 0.002

        if t % 10 == 0:
            critical_points = _get_smallest_triangles(pts)
        else:
            critical_points = list(range(n_pts))

        idx = random.choice(critical_points)
        trial = pts.copy()
        trial[idx] += random.uniform(-step_size, step_size), random.uniform(-step_size, step_size)
        trial[idx] = _project_to_simplex(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or random.random() < math.exp(delta / max(T, 1e-12)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=30000, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

from __future__ import annotations

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TOL = 1e-8

def _is_inside_triangle(p: np.ndarray) -> bool:
    x, y = p
    if y < 0 or y > SQRT3/2:
        return False
    if x < 0 or x > 1:
        return False
    if y > SQRT3 * x or y > SQRT3 * (1 - x):
        return False
    return True

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    x, y = p
    if _is_inside_triangle(p):
        return p

    # Project to closest point on triangle boundary
    if y < 0:
        return np.array([max(0.0, min(1.0, x)), 0.0])

    if y > SQRT3/2:
        return np.array([0.5, SQRT3/2])

    if x < 0:
        if y <= SQRT3/2:
            return np.array([0.0, max(0.0, min(SQRT3/2, y))])

    if x > 1:
        if y <= SQRT3/2:
            return np.array([1.0, max(0.0, min(SQRT3/2, y))])

    # Project to one of the sides
    d1 = abs(SQRT3 * x - y) / 2.0
    d2 = abs(SQRT3 * (1 - x) - y) / 2.0
    d3 = abs(y) / 2.0

    if d1 <= d2 and d1 <= d3:
        # Project to left side
        new_y = SQRT3 * x
        return np.array([x, new_y])
    elif d2 <= d3:
        # Project to right side
        new_y = SQRT3 * (1 - x)
        return np.array([x, new_y])
    else:
        # Project to bottom
        return np.array([x, 0.0])

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')

    for i in range(n):
        for j in range(i+1, n):
            p1 = pts[i]
            p2 = pts[j]
            dx12 = p2[0] - p1[0]
            dy12 = p2[1] - p1[1]

            for k in range(j+1, n):
                p3 = pts[k]
                area = abs(dx12 * (p3[1] - p1[1]) - dy12 * (p3[0] - p1[0])) * 0.5
                if area < min_area:
                    min_area = area
                    if min_area < TOL:
                        return 0.0
    return min_area

def _generate_initial_points(n: int) -> np.ndarray:
    k = int(math.ceil(math.sqrt(n * 4 / SQRT3)))
    points = []

    for i in range(k+1):
        y = i * SQRT3 / (2 * k)
        x_start = y / SQRT3
        x_end = 1 - x_start
        step = (x_end - x_start) / (k+1)

        for j in range(k+1):
            x = x_start + j * step
            if len(points) < n:
                points.append(np.array([x, y]))
            else:
                break

    return np.array(points[:n])

def _optimize_points(points: np.ndarray, iterations: int = 10000) -> np.ndarray:
    n = len(points)
    best_points = points.copy()
    best_area = _min_triangle_area(best_points)

    for t in range(iterations):
        temp = 0.1 * (1 - t/iterations)
        step = 0.05 * (1 - t/iterations) + 0.01

        new_points = best_points.copy()
        for _ in range(3):
            idx = random.randint(0, n-1)
            dx = random.uniform(-step, step)
            dy = random.uniform(-step, step)
            new_points[idx] += np.array([dx, dy])
            new_points[idx] = _project_to_triangle(new_points[idx])

        new_area = _min_triangle_area(new_points)

        if new_area > best_area or (temp > 0 and random.random() < math.exp((new_area - best_area)/temp)):
            best_points = new_points.copy()
            best_area = new_area

    return best_points

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    points = _generate_initial_points(11)
    points = _optimize_points(points, 15000)

    return [(float(x), float(y)) for x, y in points]

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def point_in_triangle(p):
    x, y = p
    if y < 0 or y > SQRT3/2:
        return False
    if x < 0 or x > 1:
        return False
    if y > SQRT3 * x or y > SQRT3 * (1 - x):
        return False
    return True

def random_point_in_triangle():
    while True:
        x = random.random()
        y = random.random() * SQRT3/2
        if point_in_triangle((x, y)):
            return np.array([x, y])

def triangle_area(a, b, c):
    return abs((b[0]-a[0])*(c[1]-a[1]) - (b[1]-a[1])*(c[0]-a[0])) / 2

def min_triangle_area(pts):
    n = len(pts)
    min_area = float('inf')
    for i in range(n-2):
        for j in range(i+1, n-1):
            for k in range(j+1, n):
                area = triangle_area(pts[i], pts[j], pts[k])
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0.0
    return min_area

def optimize_points(pts, max_iter=5000):
    best_pts = pts.copy()
    best_area = min_triangle_area(pts)
    n = len(pts)

    for t in range(max_iter):
        temp = 1.0 - t/max_iter
        step = 0.1 * temp

        idx = random.randrange(n)
        new_pts = pts.copy()
        new_pts[idx] += np.random.uniform(-step, step, 2)

        if not point_in_triangle(new_pts[idx]):
            new_pts[idx] = random_point_in_triangle()

        new_area = min_triangle_area(new_pts)

        if new_area > best_area or (temp > 0 and random.random() < math.exp((new_area - best_area)/(0.001 + 0.1*temp))):
            best_area = new_area
            best_pts = new_pts.copy()
            pts = new_pts.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    pts = [random_point_in_triangle() for _ in range(11)]
    pts = optimize_points(pts)
    return [(float(x), float(y)) for x, y in pts]

import math
import random
import numpy as np
from itertools import combinations
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRI_AREA = 0.5 * SQRT3 / 2.0

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5 / TRI_AREA

def _min_triangle_area(pts):
    min_area = float('inf')
    n = len(pts)
    for i in range(n-2):
        for j in range(i+1, n-1):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

def _is_in_triangle(p):
    x, y = p
    return (x >= 0) and (y >= 0) and (x + y/SQRT3 <= 1.0) and (x - y/SQRT3 <= 0.0) and (y <= SQRT3/2)

def _project_to_triangle(p):
    x, y = p
    # Ensure positive coordinates first
    x = max(0.0, min(1.0, x))
    y = max(0.0, min(SQRT3/2, y))
    # Project to left boundary
    if x - y/SQRT3 < 0:
        x = y/SQRT3
    # Project to right boundary
    if x + y/SQRT3 > 1:
        x = 1 - y/SQRT3
    return np.array([x, y])

def _initialize_points():
    # Hexagonal lattice with center point
    points = []
    layers = 3
    for i in range(layers + 1):
        for j in range(layers + 1 - i):
            x = (i + 0.5 * j) / (2*layers)
            y = (SQRT3/2) * j / (2*layers)
            points.append([0.25 + x, 0.25 + y])
            if i > 0 and j > 0:
                points.append([0.25 + x - 0.25, 0.25 + y - 0.25])
    # Add center point
    points.append([0.5, SQRT3/4])
    # Select 11 unique points closest to center
    center = np.array([0.5, SQRT3/4])
    unique_points = []
    seen = set()
    for p in sorted(points, key=lambda p: np.linalg.norm(np.array(p)-center)):
        tp = tuple(p)
        if tp not in seen:
            seen.add(tp)
            unique_points.append(p)
            if len(unique_points) >= 11:
                break
    return np.array(unique_points[:11])

def _get_worst_triangle_indices(pts, k=1):
    min_area = float('inf')
    worst_indices = None
    n = len(pts)
    for i in range(n-2):
        for j in range(i+1, n-1):
            for m in range(j+1, n):
                a = _area(pts[i], pts[j], pts[m])
                if a < min_area:
                    min_area = a
                    worst_indices = (i, j, m)
                    if min_area == 0:
                        return [worst_indices]
    return [worst_indices] if worst_indices else []

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    pts = _initialize_points()
    best_pts = pts.copy()
    best_area = _min_triangle_area(pts)

    # Simulated annealing phase
    for t in range(2000):
        T = max(0.001, 0.1 * (0.001/0.1) ** (t/1999))
        step = 0.03 * (1 - t/2000)

        # Perturb points in worst triangles
        worst_tris = _get_worst_triangle_indices(pts)
        if not worst_tris:
            continue
        idx = random.choice(worst_tris[0])

        new_pts = pts.copy()
        perturbation = np.random.uniform(-step, step, size=2)
        new_pts[idx] += perturbation
        new_pts[idx] = _project_to_triangle(new_pts[idx])

        if not _is_in_triangle(new_pts[idx]):
            new_pts[idx] = _project_to_triangle(new_pts[idx])

        new_area = _min_triangle_area(new_pts)
        if new_area > best_area or (T > 0 and random.random() < math.exp((new_area - best_area)/T)):
            pts = new_pts
            if new_area > best_area:
                best_area = new_area
                best_pts = new_pts.copy()

    # Local optimization phase
    for _ in range(300):
        worst_tris = _get_worst_triangle_indices(best_pts)
        if not worst_tris:
            break
        i, j, k = worst_tris[0]
        centroid = (best_pts[i] + best_pts[j] + best_pts[k]) / 3
        for idx in [i, j, k]:
            new_pts = best_pts.copy()
            new_pts[idx] = 0.9 * new_pts[idx] + 0.1 * centroid
            new_pts[idx] = _project_to_triangle(new_pts[idx])
            new_area = _min_triangle_area(new_pts)
            if new_area > best_area:
                best_area = new_area
                best_pts = new_pts.copy()

    return [(float(x), float(y)) for x, y in best_pts]

from __future__ import annotations
import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _is_in_triangle(p: np.ndarray) -> bool:
    v0 = _C - _A
    v1 = _B - _A
    v2 = p - _A
    dot00 = np.dot(v0, v0)
    dot01 = np.dot(v0, v1)
    dot02 = np.dot(v0, v2)
    dot11 = np.dot(v1, v1)
    dot12 = np.dot(v1, v2)
    inv_denom = 1.0 / (dot00 * dot11 - dot01 * dot01)
    u = (dot11 * dot02 - dot01 * dot12) * inv_denom
    v = (dot00 * dot12 - dot01 * dot02) * inv_denom
    return (u >= -1e-8) and (v >= -1e-8) and (u + v <= 1.0 + 1e-8)

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _min_triangle_area_fast(pts: np.ndarray) -> float:
    n = len(pts)
    best = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            p1 = pts[j] - pts[i]
            for k in range(j+1, n):
                p2 = pts[k] - pts[i]
                area = abs(p1[0]*p2[1] - p1[1]*p2[0]) * 0.5
                if area < best:
                    best = area
                    if best < 1e-8:
                        return 0
    return best

def _hexagonal_initialization(n: int) -> np.ndarray:
    pts = []
    layers = math.ceil((math.sqrt(8*n/3 + 1) - 1)/2)
    for layer in range(layers):
        count = layer + 1
        for i in range(count):
            u = (i + 0.5 * (layer % 2)) / (2*layers)
            v = (layer + 0.5) / (2*layers)
            if u + v <= 1.0:
                pts.append((1 - u - v) * _A + u * _B + v * _C)
                if len(pts) == n:
                    return np.array(pts)
    while len(pts) < n:
        pts.append(_random_point())
    return np.array(pts)

def _optimize(pts: np.ndarray, steps: int = 200) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area_fast(best_pts)
    step_size = 0.1

    for _ in range(steps):
        improved = False
        for i in range(len(pts)):
            for _ in range(5):
                trial = best_pts.copy()
                trial[i] += np.random.normal(0, step_size, 2)
                trial[i] = _project_to_simplex(trial[i])
                if not _is_in_triangle(trial[i]):
                    continue
                trial_val = _min_triangle_area_fast(trial)
                if trial_val > best_val + 1e-8:
                    best_val = trial_val
                    best_pts = trial.copy()
                    improved = True
                    break
        if not improved:
            step_size *= 0.7
    return best_pts

def _refine_smallest(pts: np.ndarray, steps: int = 50) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area_fast(best_pts)
    step_size = 0.02

    for _ in range(steps):
        trial = best_pts.copy()
        for i in range(len(pts)):
            trial[i] += np.random.normal(0, step_size, 2)
            trial[i] = _project_to_simplex(trial[i])
            if not _is_in_triangle(trial[i]):
                trial[i] = best_pts[i]
        trial_val = _min_triangle_area_fast(trial)
        if trial_val > best_val + 1e-8:
            best_val = trial_val
            best_pts = trial.copy()
        else:
            step_size *= 0.9
    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)
    pts = _hexagonal_initialization(11)
    pts = _optimize(pts)
    pts = _refine_smallest(pts)
    for p in pts:
        if not _is_in_triangle(p):
            p = _project_to_simplex(p)
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

