import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRI_AREA = SQRT3 / 4.0

def _random_point() -> np.ndarray:
    while True:
        x, y = random.random(), random.random() * SQRT3 / 2
        if y <= SQRT3 * x and y <= SQRT3 * (1 - x):
            return np.array([x, y])

def _is_inside(p: np.ndarray) -> bool:
    x, y = p
    return y >= 0 and y <= SQRT3/2 and y <= SQRT3 * x and y <= SQRT3 * (1 - x)

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    x, y = p
    if y < 0:
        y = 0
    if y > SQRT3/2:
        y = SQRT3/2

    if y > SQRT3 * x:
        x = y / SQRT3
    if y > SQRT3 * (1 - x):
        x = 1 - y / SQRT3

    return np.array([x, y])

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')

    for i in range(n):
        for j in range(i+1, n):
            x1, y1 = pts[i]
            x2, y2 = pts[j]
            a = x2 - x1
            b = y2 - y1
            for k in range(j+1, n):
                x3, y3 = pts[k]
                area = abs(a * (y3 - y1) - b * (x3 - x1)) / 2.0
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0.0
    return min_area / TRI_AREA

def _initialize_hexagonal(n: int) -> np.ndarray:
    k = math.ceil(math.sqrt(n / (SQRT3/2)))
    pts = []
    for i in range(k):
        for j in range(k):
            x = (0.5 + j) / k
            y = (0.5 + i * SQRT3/2) / k
            if y <= SQRT3 * (1 - x) and y <= SQRT3 * x:
                pts.append([x, y])
            if len(pts) >= n:
                break
        if len(pts) >= n:
            break

    while len(pts) < n:
        pts.append(_random_point())

    return np.array(pts[:n])

def _optimize_points(pts: np.ndarray, iterations: int) -> np.ndarray:
    n = len(pts)
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)
    current_pts = pts.copy()
    current_area = best_area

    temp = 0.1
    cooling_rate = math.exp(math.log(1e-6 / temp) / iterations)

    for _ in range(iterations):
        idx = random.randrange(n)
        angle = random.uniform(0, 2*math.pi)
        step = 0.05 * (1 + random.random())

        new_pts = current_pts.copy()
        new_pts[idx] += step * math.cos(angle), step * math.sin(angle)
        new_pts[idx] = _project_to_triangle(new_pts[idx])

        new_area = _min_triangle_area(new_pts)
        delta = new_area - current_area

        if delta > 0 or random.random() < math.exp(delta / temp):
            current_pts = new_pts
            current_area = new_area
            if new_area > best_area:
                best_pts = new_pts.copy()
                best_area = new_area

        temp *= cooling_rate

        if _ % 1000 == 0:
            for i in range(n):
                if not _is_inside(current_pts[i]):
                    current_pts[i] = _project_to_triangle(current_pts[i])

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _initialize_hexagonal(11)
    pts = _optimize_points(pts, 30000)

    for p in pts:
        if not _is_inside(p):
            p = _project_to_triangle(p)

    return [(float(x), float(y)) for x, y in pts]

