import math
import random
import numpy as np
from typing import List, Tuple
from scipy.spatial import Voronoi

SQRT3 = math.sqrt(3.0)
TRI_AREA = SQRT3 / 4.0

def _is_inside(p: np.ndarray) -> bool:
    x, y = p
    if y < 0 or y > SQRT3/2:
        return False
    if x < 0 or x > 1:
        return False
    if y > SQRT3 * x or y > SQRT3 * (1 - x):
        return False
    return True

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n-2):
        p0 = pts[i]
        for j in range(i+1, n-1):
            p1 = pts[j]
            dx1 = p1[0] - p0[0]
            dy1 = p1[1] - p0[1]
            for k in range(j+1, n):
                dx2 = pts[k][0] - p0[0]
                dy2 = pts[k][1] - p0[1]
                area = abs(dx1*dy2 - dx2*dy1) * 0.5
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0
    return min_area

def _generate_initial_config(n: int) -> np.ndarray:
    if n != 11:
        return _generate_hex_grid(n)

    # Specialized initial configuration for n=11
    pts = np.array([
        [0.5, SQRT3/6],  # Center
        [0.25, SQRT3/12], [0.75, SQRT3/12],  # Inner ring
        [0.5, SQRT3/3],  # Top middle
        [0.125, SQRT3/4], [0.875, SQRT3/4],  # Top sides
        [0.25, 0], [0.75, 0],  # Bottom
        [0.0, 0.0], [1.0, 0.0], [0.5, SQRT3/2]  # Corners
    ])

    # Random perturbation to break symmetry
    pts += np.random.uniform(-0.05, 0.05, (11, 2))
    pts = np.clip(pts, [0, 0], [1, SQRT3/2])
    return np.array([p for p in pts if _is_inside(p)])

def _voronoi_relaxation(pts: np.ndarray, steps: int) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)

    for _ in range(steps):
        try:
            vor = Voronoi(best_pts)
            new_pts = []
            for i in range(len(best_pts)):
                region = vor.regions[vor.point_region[i]]
                if -1 in region or len(region) == 0:
                    new_pts.append(best_pts[i])
                else:
                    vertices = np.array([vor.vertices[v] for v in region])
                    centroid = np.mean(vertices, axis=0)
                    if _is_inside(centroid):
                        new_pts.append(centroid)
                    else:
                        new_pts.append(best_pts[i])

            new_pts = np.array(new_pts)
            new_area = _min_triangle_area(new_pts)
            if new_area > best_area:
                best_area = new_area
                best_pts = new_pts
        except:
            pass

    return best_pts

def _gradient_refinement(pts: np.ndarray, steps: int) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)
    n = len(pts)

    for step in range(steps):
        step_size = 0.02 * (1 - step/steps)

        # Find the smallest triangle
        min_area = float('inf')
        min_indices = (0, 1, 2)
        for i in range(n-2):
            for j in range(i+1, n-1):
                for k in range(j+1, n):
                    area = _min_triangle_area(best_pts[[i,j,k]])
                    if area < min_area:
                        min_area = area
                        min_indices = (i, j, k)

        # Perturb points in the smallest triangle
        for idx in min_indices:
            for _ in range(3):
                trial = best_pts.copy()
                delta = np.random.uniform(-step_size, step_size, 2)
                trial[idx] += delta

                if _is_inside(trial[idx]):
                    trial_area = _min_triangle_area(trial)
                    if trial_area > best_area:
                        best_area = trial_area
                        best_pts = trial.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    initial_pts = _generate_initial_config(11)
    voronoi_pts = _voronoi_relaxation(initial_pts, 50)
    refined_pts = _gradient_refinement(voronoi_pts, 100)

    return [(float(x), float(y)) for x, y in refined_pts]

