    return min_area

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _hexagonal_points(n: int) -> np.ndarray:
    pts = []
    layers = math.ceil((math.sqrt(4*n/SQRT3 + 1) - 1)/2)
    for i in range(layers):
        for j in range(layers):
            x = 0.5 + (j - i) * 0.5
            y = i * SQRT3 / 2
            if x >= 0 and x <= 1 and y >= 0 and y <= SQRT3/2:
                pts.append([x, y])
    if len(pts) < n:
        pts.extend([_random_point() for _ in range(n - len(pts))])
    return np.array(pts[:n])

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _optimize(pts: np.ndarray, max_iters: int = 3000) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area_fast(best_pts)
    n = len(pts)
    no_improve = 0

    for t in range(max_iters):
