import math
import random
import itertools
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p, q, r) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5 / TRIANGLE_AREA

def _min_triangle_area(pts: np.ndarray) -> float:
    min_area = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

def _is_inside_triangle(p: np.ndarray) -> bool:
    x, y = p
    if x < 0 or x > 1 or y < 0:
        return False
    if y > SQRT3 * min(x, 1 - x):
        return False
    return True

def _hexagonal_grid(n: int) -> np.ndarray:
    pts = []
    layers = math.ceil((3 * n / (4 * math.pi)) ** 0.5)

    for layer in range(layers + 1):
        r = layer / (layers * 2)
        h = r * SQRT3
        count = max(1, 2 * layer)

        for i in range(count):
            angle = 2 * math.pi * i / count
            x = 0.5 + r * math.cos(angle)
            y = h + r * math.sin(angle)

            if _is_inside_triangle([x, y]):
                pts.append([x, y])
                if len(pts) == n:
                    return np.array(pts)

    return np.array(pts[:n])

def _optimize_sa(pts: np.ndarray, iterations: int) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)
    current_pts = pts.copy()
    current_area = best_area

    for i in range(iterations):
        T = 1.0 - i/iterations
        idx = random.randrange(len(pts))

        new_pts = current_pts.copy()
        dx = random.uniform(-0.01*T, 0.01*T)
        dy = random.uniform(-0.01*T, 0.01*T)
        new_pts[idx] += [dx, dy]

        if not _is_inside_triangle(new_pts[idx]):
            continue

        new_area = _min_triangle_area(new_pts)

        if new_area > current_area or random.random() < math.exp((new_area - current_area)/T):
            current_pts = new_pts
            current_area = new_area

            if current_area > best_area:
                best_area = current_area
                best_pts = current_pts.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    pts = _hexagonal_grid(11)
    pts = _optimize_sa(pts, 5000)

    return [(float(x), float(y)) for x, y in pts]

