        tree = KDTree(current_pts)
        for i in range(len(trial_pts)):
            neighbors = tree.query(current_pts[i], k=7)[1][1:]
            min_local = min(_area(current_pts[i], current_pts[j], current_pts[k]) 
                          for j, k in combinations(neighbors, 2))

            if min_local < best_score * 1.5:
                perturbation = np.random.normal(0, temp/10, 2)
                trial_pts[i] += perturbation

                if not _is_in_triangle(trial_pts[i]):
                    trial_pts[i] = np.clip(trial_pts[i], [0, 0], [1, SQRT3/2])
                    if (trial_pts[i][1] > SQRT3 * trial_pts[i][0] or 
                        trial_pts[i][1] > SQRT3 * (1 - trial_pts[i][0])):
                        trial_pts[i] = current_pts[i]

        current_score = _min_triangle_area(trial_pts)
        if current_score > best_score or (current_score > 0 and 
            math.exp((current_score - best_score)/temp) > random.random()):
            best_score = current_score
            best_pts = trial_pts.copy()
            current_pts = trial_pts.copy()

    # Gradient-based local optimization
    for _ in range(50):
        for i in range(len(best_pts)):
            original = best_pts[i].copy()
            for dim in [0, 1]:
                for delta in [0.01, -0.01]:
                    best_pts[i][dim] += delta
                    if not _is_in_triangle(best_pts[i]):
                        best_pts[i][dim] -= delta
                        continue
                    new_score = _min_triangle_area(best_pts)
                    if new_score > best_score:
                        best_score = new_score
                    else:
                        best_pts[i][dim] -= delta

    return best_pts

def find_points(seed=None):
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _generate_initial_points(11)
    pts = _optimize_points(pts, iterations=500)

    return [(float(p[0]), float(p[1])) for p in pts]

from __future__ import annotations
import math
import random
import numpy as np
from itertools import combinations

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _min_triangle_area(pts: np.ndarray) -> float:
    min_area = float('inf')
    for trio in combinations(pts, 3):
        a, b, c = trio
        area = abs((b[0]-a[0])*(c[1]-a[1]) - (b[1]-a[1])*(c[0]-a[0])) / 2.0
        if area < min_area:
            min_area = area
            if min_area == 0:
                return 0
    return min_area / TRIANGLE_AREA

def _random_point() -> np.ndarray:
    while True:
        x, y = random.random(), random.random() * SQRT3 / 2
        if y <= SQRT3 * x and y <= SQRT3 * (1 - x):
            return np.array([x, y])

def _hex_grid(n: int) -> np.ndarray:
    k = math.ceil(math.sqrt(n * 2 / SQRT3))
    pts = []
    for i in range(k):
        for j in range(k):
            x = (j + 0.5 * (i % 2)) / k
            y = SQRT3 * i / (2 * k)
            if y <= SQRT3 * x and y <= SQRT3 * (1 - x):
                pts.append([x, y])
    return np.array(random.sample(pts, min(n, len(pts))) if len(pts) > n else pts + [_random_point() for _ in range(n - len(pts))])

def _perturb_point(p: np.ndarray, scale: float) -> np.ndarray:
    while True:
        dx, dy = random.uniform(-scale, scale), random.uniform(-scale, scale)
        new_p = p + np.array([dx, dy])
        x, y = new_p
        if y >= 0 and y <= SQRT3 * x and y <= SQRT3 * (1 - x):
            return new_p

def _optimize(pts: np.ndarray, iterations: int) -> tuple[np.ndarray, float]:
    best_pts = pts.copy()
    best_score = _min_triangle_area(pts)
    current_pts = pts.copy()
    current_score = best_score

    for i in range(iterations):
        T = 0.1 * (1 - i/iterations)**2
        scale = 0.05 * (1 - i/iterations) + 0.005

        idx = random.randrange(len(pts))
        new_pts = current_pts.copy()
        new_pts[idx] = _perturb_point(current_pts[idx], scale)

        new_score = _min_triangle_area(new_pts)
        delta = new_score - current_score

        if delta > 0 or (T > 0 and random.random() < math.exp(delta / T)):
            current_pts, current_score = new_pts, new_score
            if new_score > best_score:
                best_pts, best_score = new_pts.copy(), new_score

        if i % 100 == 0 and i > 0:
            current_pts = best_pts.copy()
            current_score = best_score

    return best_pts, best_score

def find_points(seed: int | None = 0) -> list[tuple[float, float]]:
    random.seed(seed)
    pts = _hex_grid(11)
    best_pts, _ = _optimize(pts, 3000)
    return [(float(x), float(y)) for x, y in best_pts]

from __future__ import annotations

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray, cutoff: float = 0) -> float:
    n = len(pts)
    best = float('inf')
    for i in range(n-2):
        p = pts[i]
        for j in range(i+1, n-1):
            q = pts[j]
            pq = q - p
            for k in range(j+1, n):
                a = abs(np.cross(pq, pts[k] - p)) * 0.5
                if a <= cutoff:
                    return a
                if a < best:
                    best = a
    return best

def _random_barycentric() -> Tuple[float, float, float]:
    u, v = random.random(), random.random()
    if u + v > 1.0:
        u, v = 1 - u, 1 - v
    return (1 - u - v, u, v)

def _barycentric_to_cartesian(b: Tuple[float, float, float]) -> np.ndarray:
    return np.array([0.5 * b[1] + 0.5 * b[2], SQRT3 / 2 * b[2]])

def _initial_hexagonal_configuration(n_pts: int = 11) -> np.ndarray:
    pts = []
    layers = 4
    for i in range(layers):
        for j in range(i+1):
            u = (j + 0.5) / layers
            v = (i - j + 0.5) / layers
            if u + v <= 1.0:
                pts.append(_barycentric_to_cartesian((1-u-v, u, v)))
    while len(pts) < n_pts:
        b = _random_barycentric()
        pts.append(_barycentric_to_cartesian(b))
    return np.array(pts[:n_pts])

def _optimize(n_pts: int = 11, iters: int = 10000, seed: int | None = None) -> np.ndarray:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _initial_hexagonal_configuration(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        T = max(0.1 * (1 - t/iters), 1e-6)
        idx = random.randrange(n_pts)
        trial = pts.copy()

        step = 0.05 * (1 - t/iters)
        if t % 100 == 0 and random.random() < 0.2:
            step *= 2

        # Move in barycentric coordinates to stay inside triangle
        b = np.random.uniform(-step, step, size=2)
        new_b = np.clip(trial[idx][:2] + b, 0.01, 0.99)
        if new_b[0] + new_b[1] > 0.99:
            new_b = new_b / (new_b[0] + new_b[1]) * 0.99
        trial[idx] = np.array([new_b[0], new_b[1]])

        trial_val = _min_triangle_area(trial, best_val)
        if trial_val > best_val or random.random() < math.exp((trial_val - best_val)/T):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

    # Convert back to Cartesian coordinates
    cartesian_pts = []
    for p in best_pts:
        u, v = p[0], p[1]
        if u + v > 1.0:
            u, v = u/(u+v), v/(u+v)
        cartesian_pts.append(_barycentric_to_cartesian((1-u-v, u, v)))
    return np.array(cartesian_pts)

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    pts = _optimize(n_pts=11, iters=10000, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                area = _area(pts[i], pts[j], pts[k])
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0
    return min_area

def _hexagonal_lattice(n: int) -> np.ndarray:
    k = math.ceil(math.sqrt(2 * n / SQRT3))
    scale = 1.0 / (k + 1)
    pts = []
    for i in range(k):
        for j in range(k):
            x = (i + 0.5 * (j % 2)) * scale
            y = j * SQRT3 * 0.5 * scale
            if y <= SQRT3 * min(x, 1 - x):
                pts.append([x, y])
                if len(pts) == n:
                    return np.array(pts)
    while len(pts) < n:
        x = random.uniform(0, 1)
        y_max = SQRT3 * min(x, 1 - x)
        y = random.uniform(0, y_max)
        pts.append([x, y])
    return np.array(pts)

def _optimize_simulated_annealing(pts: np.ndarray, iterations: int = 5000) -> np.ndarray:
    current_pts = pts.copy()
    current_area = _min_triangle_area(current_pts)
    best_pts = current_pts.copy()
    best_area = current_area
    n = len(pts)

    for step in range(iterations):
        temp = 1.0 - step / iterations
        new_pts = current_pts.copy()

        # Focus perturbation on points involved in smallest triangles
        idx = random.randint(0, n-1)
        perturbation = np.random.normal(0, 0.05 * temp, 2)
        new_pts[idx] += perturbation

        # Ensure point stays inside triangle
        x, y = new_pts[idx]
        y_max = SQRT3 * min(x, 1 - x)
        if not (0 <= x <= 1 and 0 <= y <= y_max):
            new_pts[idx] = current_pts[idx]

        new_area = _min_triangle_area(new_pts)

        # Simulated annealing acceptance
        if new_area > current_area or (temp > 0 and random.random() < math.exp((new_area - current_area) / (0.01 + 0.1 * temp)))):
            current_pts = new_pts.copy()
            current_area = new_area
            if new_area > best_area:
                best_pts = new_pts.copy()
                best_area = new_area

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _hexagonal_lattice(11)
    pts = _optimize_simulated_annealing(pts, 5000)

    return [(float(x), float(y)) for x, y in pts]

import math
import random
import numpy as np
from itertools import combinations
from scipy.spatial import KDTree

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / 2.0

def _min_triangle_area_fast(pts, kdtree=None):
    if kdtree is None:
        kdtree = KDTree(pts)
    min_area = float('inf')
    for i in range(len(pts)):
        neighbors = kdtree.query_ball_point(pts[i], 0.3)
        if len(neighbors) < 2:
            continue
        for j in neighbors:
            if j <= i:
                continue
            for k in neighbors:
                if k <= j:
                    continue
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area < 1e-8:
                        return min_area
    return min_area

def _is_in_triangle(p):
    x, y = p
    if x < 0 or x > 1 or y < 0 or y > SQRT3/2:
        return False
    if y > SQRT3 * x:
        return False
    if y > SQRT3 * (1 - x):
        return False
    return True

def _generate_initial_points(n):
    points = []
    # Generate points in a hexagonal grid pattern
    layers = 3
    points.append([0.5, SQRT3/6])  # Center point

    for layer in range(1, layers+1):
        radius = layer/(layers+1)
        # Points on concentric circles
        for angle in np.linspace(0, 2*np.pi, 6*layer, endpoint=False):
            x = 0.5 + radius * np.cos(angle)
            y = SQRT3/6 + radius * np.sin(angle)
            if _is_in_triangle((x, y)):
                points.append([x, y])

    # Add points along edges if needed
    edge_points = [
        [0.0, 0.0], [1.0, 0.0], [0.5, SQRT3/2],
        [0.25, SQRT3/4], [0.75, SQRT3/4]
    for p in edge_points:
        if len(points) < n and p not in points:
            points.append(p)

    # Fill remaining with quasi-random points
    phi = (1 + math.sqrt(5))/2
    i = len(points)
    while len(points) < n:
        x = (0.5 + i*phi) % 1
        y = (0.5 + i*phi*phi) % (SQRT3/2)
        p = [x, y]
        if _is_in_triangle(p) and not any(np.allclose(p, pt) for pt in points):
            points.append(p)
        i += 1

    return np.array(points[:n])

def _optimize_points(points, iterations):
    best_points = points.copy()
    kdtree = KDTree(best_points)
    best_score = _min_triangle_area_fast(best_points, kdtree)

    for i in range(iterations):
        new_points = best_points.copy()
        idx = random.randint(0, len(points)-1)

        step = 0.03 * (1 - i/iterations)**0.5

        # Calculate repulsion from nearest 5 points
        neighbors = kdtree.query(best_points[idx], k=6)[1][1:]
        repulsion = np.zeros(2)
        for n_idx in neighbors:
            diff = best_points[idx] - best_points[n_idx]
            dist = np.linalg.norm(diff)
            if dist > 1e-6:
                repulsion += diff / (dist**3)  # Stronger repulsion for closer points

        if np.linalg.norm(repulsion) > 1e-6:
            repulsion = repulsion / np.linalg.norm(repulsion)
            new_points[idx] += step * repulsion * random.uniform(0.8, 1.2)
        else:
            new_points[idx] += np.random.uniform(-step, step, 2)

        if not _is_in_triangle(new_points[idx]):
            continue

        new_kdtree = KDTree(new_points)
        new_score = _min_triangle_area_fast(new_points, new_kdtree)

        if new_score > best_score or (new_score == best_score and random.random() < 0.1):
            best_score = new_score
            best_points = new_points.copy()
            kdtree = new_kdtree

    return best_points

def find_points(seed=None):
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    points = _generate_initial_points(11)
    points = _optimize_points(points, 3000)

    return [(float(p[0]), float(p[1])) for p in points]

