import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
EPSILON = 1e-8

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    best = float("inf")
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best < EPSILON:
                        return 0
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _is_inside(p: np.ndarray) -> bool:
    v0 = _C - _A
    v1 = _B - _A
    v2 = p - _A
    dot00 = np.dot(v0, v0)
    dot01 = np.dot(v0, v1)
    dot02 = np.dot(v0, v2)
    dot11 = np.dot(v1, v1)
    dot12 = np.dot(v1, v2)
    inv_denom = 1.0 / (dot00 * dot11 - dot01 * dot01)
    u = (dot11 * dot02 - dot01 * dot12) * inv_denom
    v = (dot00 * dot12 - dot01 * dot02) * inv_denom
    return (u >= -EPSILON) and (v >= -EPSILON) and (u + v <= 1.0 + EPSILON)

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _initialize_points(n_pts: int) -> np.ndarray:
    pts = []
    # Hexagonal pattern initialization
    layers = 3
    for layer in range(layers):
        radius = 0.3 + 0.25 * layer / (layers-1)
        for i in range(6):
            angle = math.pi/3 * i
            x = 0.5 + radius * math.cos(angle)
            y = SQRT3/3 + radius * math.sin(angle)
            if _is_inside(np.array([x, y])):
                pts.append(np.array([x, y]))
                if len(pts) == n_pts:
                    return np.array(pts)
    # Fill remaining points if needed
    while len(pts) < n_pts:
        pts.append(_random_point())
    return np.array(pts)

def _anneal(n_pts: int = 11,
            iters: int = 20000,
            start_temp: float = 0.2,
            end_temp: float = 1e-8,
            step_size: float = 0.05,
            seed: int | None = None) -> np.ndarray:
    rng = random.Random(seed)
    pts = _initialize_points(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    no_improve = 0
    adaptive_step = step_size

    for t in range(iters):
        if no_improve > 500:
            break
        T = start_temp * math.exp(-6.0 * t / iters)
        current_step = adaptive_step * (1 - 0.95 * t/iters)

        trial = pts.copy()
        if t % 150 == 0:
            for _ in range(2):
                idx = rng.randrange(n_pts)
                trial[idx] = _random_point()
        else:
            for _ in range(1 + (t % 4 == 0)):
                idx = rng.randrange(n_pts)
                if t > iters * 0.8 and rng.random() < 0.3:
                    # Small jitter in final stages
                    trial[idx] += rng.uniform(-current_step*0.1, current_step*0.1), rng.uniform(-current_step*0.1, current_step*0.1)
                else:
                    trial[idx] += rng.uniform(-current_step, current_step), rng.uniform(-current_step, current_step)
                if not _is_inside(trial[idx]):
                    trial[idx] = _project_to_simplex(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or rng.random() < math.exp(delta / max(T, 1e-12)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()
                no_improve = 0
                adaptive_step = min(0.15, adaptive_step * 1.2)
            else:
                no_improve += 1
                adaptive_step = max(0.005, adaptive_step * 0.9)

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=20000, seed=seed)
    pts = [_project_to_simplex(p) if not _is_inside(p) else p for p in pts]
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _initial_hexagonal_configuration(n: int) -> np.ndarray:
    pts = []
    k = math.ceil(math.sqrt(n / (0.5 * SQRT3)))
    for i in range(k):
        for j in range(k):
            x = (i + 0.5 * (j % 2)) / (k - 1)
            y = (j * SQRT3 / 2) / (k - 1)
            if x <= 1.0 and y <= SQRT3/2 and (1-x)*SQRT3/2 >= y:
                pts.append([x, y])
    while len(pts) < n:
        u, v = random.random(), random.random()
        if u + v > 1.0:
            u, v = 1 - u, 1 - v
        pts.append([u, v * SQRT3])
    return np.array(pts[:n])

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    x, y = p
    if y < 0:
        y = 0
    if y > SQRT3/2:
        y = SQRT3/2
    if x < 0:
        x = 0
    if x > 1:
        x = 1
    if y > (1-x)*SQRT3:
        x = 1 - y/(SQRT3/2)
        y = (1-x)*SQRT3
    return np.array([x, y])

def _min_triangle_area_fast(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n):
        for j in range(i+1, min(i+10, n)):
            p1 = pts[i]
            p2 = pts[j]
            dx1 = p2[0] - p1[0]
            dy1 = p2[1] - p1[1]
            for k in range(j+1, min(j+10, n)):
                p3 = pts[k]
                dx2 = p3[0] - p1[0]
                dy2 = p3[1] - p1[1]
                area = abs(dx1*dy2 - dx2*dy1) / 2
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0.0
    return min_area

def _optimize_step_fast(pts: np.ndarray, idx: int, step: float) -> np.ndarray:
    original = pts[idx].copy()
    best_area = _min_triangle_area_fast(pts)

    for _ in range(5):
        trial = pts.copy()
        trial[idx] = original + np.random.uniform(-step, step, 2)
        trial[idx] = _project_to_triangle(trial[idx])
        trial_area = _min_triangle_area_fast(trial)

        if trial_area > best_area:
            best_area = trial_area
            pts = trial

    return pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    if seed is not None:
        np.random.seed(seed)
        random.seed(seed)

    pts = _initial_hexagonal_configuration(11)
    best_pts = pts.copy()
    best_area = _min_triangle_area_fast(pts)

    step = 0.05
    no_improvement = 0

    for _ in range(1000):
        if no_improvement > 50:
            step *= 0.8
            no_improvement = 0
            if step < 0.001:
                break

        idx = np.random.randint(11)
        pts = _optimize_step_fast(pts, idx, step)
        current_area = _min_triangle_area_fast(pts)

        if current_area > best_area:
            best_area = current_area
            best_pts = pts.copy()
            no_improvement = 0
        else:
            no_improvement += 1

    return [(float(x), float(y)) for x, y in best_pts]

import math
import random
import numpy as np
from scipy.spatial import KDTree
from itertools import combinations

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / 2.0

def _min_triangle_area(pts, kdtree=None, k=10):
    min_area = float('inf')
    n = len(pts)
    k = min(k, n-1)

    if kdtree is None:
        kdtree = KDTree(pts)

    for i, p in enumerate(pts):
        dists, indices = kdtree.query(p, k=k+1)
        neighbors = [pts[j] for j in indices if j != i]

        for q, r in combinations(neighbors, 2):
            a = _area(p, q, r)
            if a < min_area:
                min_area = a
                if min_area == 0:
                    return 0
    return min_area

def _generate_initial_points(n):
    pts = []
    layers = math.ceil(math.sqrt(n * 4 / (3 * SQRT3))) + 3

    for i in range(layers):
        y = (i + 0.5) * (SQRT3/2) / layers
        for j in range(layers):
            x = (j + 0.5) / layers
            if y <= x * SQRT3 and y <= (1 - x) * SQRT3:
                pts.append([x, y])

    if len(pts) < n:
        hex_pts = []
        size = math.ceil(math.sqrt(n/6))
        for i in range(size):
            for j in range(size):
                x = (i + 0.5 * (j % 2)) / size
                y = (j * SQRT3/2) / size
                if y <= x * SQRT3 and y <= (1 - x) * SQRT3:
                    hex_pts.append([x, y])
        pts.extend(hex_pts)

    pts = pts[:n]
    while len(pts) < n:
        x = random.uniform(0, 1)
        y = random.uniform(0, SQRT3/2)
        if y <= x * SQRT3 and y <= (1 - x) * SQRT3:
            pts.append([x, y])

    return pts

def _project_to_triangle(p):
    x, y = p
    if y < 0: y = 0
    if y > SQRT3/2: y = SQRT3/2
    x = max(0, min(1, x))
    if y > x * SQRT3:
        y = x * SQRT3
    if y > (1 - x) * SQRT3:
        y = (1 - x) * SQRT3
    return [x, y]

def _optimize_points(pts, iterations=800):
    best_pts = np.array(pts)
    best_area = _min_triangle_area(best_pts)
    kdtree = KDTree(best_pts)

    for step in range(iterations):
        temp = 1.0 - step/iterations
        step_size = 0.15 * temp
        k = max(8, int(15 * temp))

        for i in range(len(best_pts)):
            for _ in range(4):
                trial = best_pts.copy()
                perturbation = np.random.normal(0, step_size, 2)
                trial[i] = _project_to_triangle(trial[i] + perturbation)

                trial_area = _min_triangle_area(trial, kdtree, k)
                if trial_area > best_area:
                    best_area = trial_area
                    best_pts = trial
                    kdtree = KDTree(best_pts)
                    break

        if step % 50 == 0:
            full_area = _min_triangle_area(best_pts)
            if full_area > best_area:
                best_area = full_area

    return best_pts

def find_points(seed=None):
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _generate_initial_points(11)
    pts = _optimize_points(pts, 800)

    return [(float(x), float(y)) for x, y in pts]

