import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    best = float("inf")
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

def _random_barycentric() -> Tuple[float, float, float]:
    u = random.random()
    v = random.random()
    if u + v > 1:
        u, v = 1 - u, 1 - v
    return (1 - u - v, u, v)

def _barycentric_to_cartesian(b: Tuple[float, float, float]) -> np.ndarray:
    a1, a2, a3 = b
    x = a2 + a3 * 0.5
    y = a3 * SQRT3 / 2
    return np.array([x, y])

def _cartesian_to_barycentric(p: np.ndarray) -> Tuple[float, float, float]:
    x, y = p
    a3 = y * 2 / SQRT3
    a2 = x - a3 * 0.5
    a1 = 1 - a2 - a3
    return (a1, a2, a3)

def _valid_barycentric(b: Tuple[float, float, float]) -> bool:
    a1, a2, a3 = b
    return a1 >= 0 and a2 >= 0 and a3 >= 0 and abs(a1 + a2 + a3 - 1) < 1e-8

def _hexagonal_configuration(n_pts: int = 11) -> np.ndarray:
    pts_bary = [
        (1/3, 1/3, 1/3),
        (0.2, 0.4, 0.4), (0.4, 0.2, 0.4), (0.4, 0.4, 0.2),
        (0.6, 0.2, 0.2), (0.2, 0.6, 0.2), (0.2, 0.2, 0.6),
        (0.5, 0.25, 0.25), (0.25, 0.5, 0.25), (0.25, 0.25, 0.5),
        (0.1, 0.45, 0.45), (0.45, 0.1, 0.45), (0.45, 0.45, 0.1)
    ]
    pts = [_barycentric_to_cartesian(b) for b in pts_bary[:n_pts]]
    return np.array(pts)

def _optimize(pts: np.ndarray, steps: int, step_size: float) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    n_pts = len(pts)

    for step in range(steps):
        trial = best_pts.copy()
        idx = random.randrange(n_pts)

        if random.random() < 0.1:
            b = _random_barycentric()
            trial[idx] = _barycentric_to_cartesian(b)
        else:
            current_b = _cartesian_to_barycentric(trial[idx])
            delta = random.uniform(-step_size, step_size)
            new_b = (
                max(0, min(1, current_b[0] + random.uniform(-step_size, step_size))),
                max(0, min(1, current_b[1] + random.uniform(-step_size, step_size))),
                max(0, min(1, current_b[2] + random.uniform(-step_size, step_size)))
            )
            s = sum(new_b)
            new_b = (new_b[0]/s, new_b[1]/s, new_b[2]/s)
            if _valid_barycentric(new_b):
                trial[idx] = _barycentric_to_cartesian(new_b)

        trial_val = _min_triangle_area(trial)

        if trial_val > best_val:
            best_val = trial_val
            best_pts = trial.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    pts = _hexagonal_configuration(11)

    pts = _optimize(pts, steps=2000, step_size=0.1)
    pts = _optimize(pts, steps=2000, step_size=0.05)
    pts = _optimize(pts, steps=2000, step_size=0.02)
    pts = _optimize(pts, steps=2000, step_size=0.01)

    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

import math
import random
import numpy as np
from itertools import combinations

SQRT3 = math.sqrt(3.0)

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / 2.0

def _min_triangle_area(pts):
    min_area = float('inf')
    for trio in combinations(pts, 3):
        area = _area(*trio)
        if area < min_area:
            min_area = area
            if min_area == 0:
                return 0
    return min_area

def _random_point_in_triangle():
    r1, r2 = random.random(), random.random()
    if r1 + r2 > 1:
        r1, r2 = 1 - r1, 1 - r2
    x = r1 * 1.0 + r2 * 0.5
    y = r2 * SQRT3 / 2.0
    return (x, y)

def _initial_configuration():
    layers = 4
    points = []
    for i in range(layers + 1):
        for j in range(layers + 1 - i):
            x = (i + 0.5 * j) / layers
            y = j * SQRT3 / (2 * layers)
            points.append((x, y))
    return random.sample(points, 11)

def _optimize(pts, iterations, temp):
    best_pts = [np.array(p) for p in pts]
    best_area = _min_triangle_area(best_pts)

    for _ in range(iterations):
        new_pts = [p.copy() for p in best_pts]
        idx = random.randrange(11)

        if random.random() < 0.3:
            new_pts[idx] = np.array(_random_point_in_triangle())
        else:
            delta = np.random.normal(0, temp, 2)
            new_pts[idx] += delta
            x, y = new_pts[idx]
            if y < 0 or y > SQRT3/2 or x < max(0, y/SQRT3 - 0.5) or x < max(0, -y/SQRT3 + 0.5) or x > min(1, 0.5 + y/SQRT3) or x > min(1, 1.5 - y/SQRT3):
                new_pts[idx] -= delta

        new_area = _min_triangle_area(new_pts)
        if new_area > best_area or (temp > 0 and random.random() < math.exp((new_area - best_area)/temp)):
            best_area = new_area
            best_pts = new_pts

    return best_pts

def find_points(seed: int | None = 0) -> list[tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    pts = _initial_configuration()
    pts = _optimize(pts, 5000, 0.05)
    pts = _optimize(pts, 5000, 0.02)
    pts = _optimize(pts, 5000, 0.01)
    pts = _optimize(pts, 5000, 0.005)

    return [(round(x, 8), round(y, 8)) for x, y in pts]

