import math
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _hex_grid_points(n: int) -> List[np.ndarray]:
    points = []
    size = int(math.ceil(math.sqrt(n * 2 / SQRT3)))
    for j in range(size):
        for i in range(size):
            if len(points) >= n:
                break
            x = (i + 0.5 * (j % 2)) / (size - 1)
            y = SQRT3 * j / (2 * (size - 1))
            if (1 - x) * SQRT3 >= y:
                points.append(np.array([x, y]))
    return points[:n]

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _optimize(n_pts: int = 11, max_iter: int = 10000, seed: int | None = None) -> np.ndarray:
    rng = np.random.RandomState(seed)
    pts = np.array(_hex_grid_points(n_pts))
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(max_iter):
        idx = rng.randint(0, n_pts)
        trial = pts.copy()
        step = 0.1 * (1 - t/max_iter)

        if t % 10 == 0:
            trial[idx] = _project_to_simplex(rng.uniform(0, 1, size=2))
        else:
            trial[idx] = _project_to_simplex(trial[idx] + rng.uniform(-step, step, size=2))

        trial_val = _min_triangle_area(trial)
        if trial_val > best_val:
            best_val = trial_val
            best_pts = trial.copy()
            pts = trial.copy()
        elif rng.random() < 0.1:
            pts = trial.copy()

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    pts = _optimize(n_pts=11, max_iter=5000, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

