import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _area_vectorized(pts: np.ndarray) -> np.ndarray:
    n = len(pts)
    areas = np.zeros(n * (n-1) * (n-2) // 6)
    idx = 0
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                areas[idx] = abs(np.cross(pts[j]-pts[i], pts[k]-pts[i])) * 0.5
                idx += 1
    return areas

def _min_triangle_area(pts: np.ndarray) -> float:
    return np.min(_area_vectorized(pts))

def _hex_grid_point(i: int, j: int, n: int) -> np.ndarray:
    x = (i + 0.5 * (j % 2)) / n
    y = j * SQRT3 / (2 * n)
    return np.array([x, y])

def _initial_configuration() -> np.ndarray:
    pts = []
    n = 4
    for i in range(n):
        for j in range(n):
            if (i/n + j*SQRT3/(2*n)) <= 1.0 and (0.5 - i/n + j*SQRT3/(2*n)) <= 1.0:
                pts.append(_hex_grid_point(i, j, n))
    while len(pts) < 11:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            pts.append((1-u-v)*_A + u*_B + v*_C)
    return np.array(pts[:11])

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    u = np.clip(p[0], 0, 1)
    v = np.clip(p[1], 0, SQRT3/2)
    if u + v/SQRT3 > 1.0:
        u = 1.0 - v/SQRT3
    elif v > (1.0 - u)*SQRT3:
        v = (1.0 - u)*SQRT3
    return np.array([u, v])

def _optimize(pts: np.ndarray, steps: int = 5000) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)

    for step in range(steps):
        temp = 1.0 - step/steps
        idx = random.randint(0, 10)
        trial = best_pts.copy()
        delta = 0.05 * temp
        trial[idx] += np.random.uniform(-delta, delta, 2)
        trial[idx] = _project_to_simplex(trial[idx])
        trial_area = _min_triangle_area(trial)

        if trial_area > best_area or (temp > 0 and random.random() < temp):
            best_pts = trial.copy()
            best_area = trial_area

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)
    pts = _initial_configuration()
    pts = _optimize(pts)
    return [(float(x), float(y)) for x, y in pts]

