import random
import numpy as np
from itertools import combinations
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRI_AREA = 0.5 * SQRT3 / 2.0

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5 / TRI_AREA

def _min_triangle_area(pts):
    min_area = float('inf')
    n = len(pts)
    for i in range(n-2):
        for j in range(i+1, n-1):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area < 0.001:  # Early exit
                        return min_area
    return min_area

def _is_in_triangle(p):
    x, y = p
    return (x >= 0) and (y >= 0) and (x + y/SQRT3 <= 1.0) and (x - y/SQRT3 <= 0.0) and (y <= SQRT3/2)

def _project_to_triangle(p):
    x, y = p
    x = max(0.0, min(1.0, x))
    y = max(0.0, min(SQRT3/2, y))
    if x - y/SQRT3 < 0:
        x = y/SQRT3
    if x + y/SQRT3 > 1:
        x = 1 - y/SQRT3
    return np.array([x, y])

def _initialize_points():
    points = []
    # Optimized hexagonal pattern for 11 points
    layers = 2
    for i in range(-layers, layers+1):
        for j in range(-layers, layers+1):
            if abs(i + j) <= layers:
                x = 0.5 + (i + 0.5 * j) * 0.2
                y = SQRT3/4 + (SQRT3/2) * j * 0.2
                points.append([x, y])
    # Select 11 unique points closest to center
    center = np.array([0.5, SQRT3/4])
    unique_points = []
    seen = set()
    for p in sorted(points, key=lambda p: np.linalg.norm(np.array(p)-center)):
        tp = tuple(round(x,6) for x in p)
        if tp not in seen:
            seen.add(tp)
            unique_points.append(p)
            if len(unique_points) >= 11:
                break
    return np.array(unique_points[:11])

def _get_worst_triangle_indices(pts):
    min_area = float('inf')
    worst_indices = None
    n = len(pts)
    for i in range(n-2):
        for j in range(i+1, n-1):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    worst_indices = (i, j, k)
    return worst_indices

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    pts = _initialize_points()
    best_pts = pts.copy()
    best_area = _min_triangle_area(pts)

    # Enhanced simulated annealing
    for t in range(3000):
        T = max(0.001, 0.1 * math.exp(-5 * t/3000))
        step = 0.05 * math.exp(-3 * t/3000)

        worst_indices = _get_worst_triangle_indices(pts)
        if not worst_indices:
            continue

        idx = random.choice(worst_indices)
        new_pts = pts.copy()
        perturbation = np.random.normal(0, step, size=2)
        new_pts[idx] += perturbation
        new_pts[idx] = _project_to_triangle(new_pts[idx])

        new_area = _min_triangle_area(new_pts)
        if new_area > best_area or (T > 0 and random.random() < math.exp(10*(new_area - best_area)/T)):
            pts = new_pts
            if new_area > best_area:
                best_area = new_area
                best_pts = new_pts.copy()

    # Enhanced local optimization
    for _ in range(500):
        worst_indices = _get_worst_triangle_indices(best_pts)
        if not worst_indices:
            break
        i, j, k = worst_indices
        centroid = (best_pts[i] + best_pts[j] + best_pts[k]) / 3
        for idx in [i, j, k]:
            for ratio in [0.8, 0.9, 0.95]:
                new_pts = best_pts.copy()
                new_pts[idx] = ratio * new_pts[idx] + (1-ratio) * centroid
                new_pts[idx] = _project_to_triangle(new_pts[idx])
                new_area = _min_triangle_area(new_pts)
                if new_area > best_area:
                    best_area = new_area
                    best_pts = new_pts.copy()
                    break

    return [(float(x), float(y)) for x, y in best_pts]

