    if x < 0 or x > 1:
        return False
    return y <= SQRT3 * (1 - abs(2*x - 1))

def _hexagonal_grid(n: int) -> np.ndarray:
    pts = []
    size = int(math.ceil(math.sqrt(n * 2)))  # Adjusted multiplier to get more points
    for i in range(size):
        for j in range(size):
            if len(pts) >= n:
                break
            x = 0.5 + (i - j) * 0.5 / size
            y = j * SQRT3 / 2 / size
            if _is_in_triangle(x, y):
                pts.append([x, y])
    # Ensure we have exactly n points inside the triangle
    while len(pts) < n:
        x = random.uniform(0, 1)
        y_max = SQRT3 * (1 - abs(2*x - 1))
        y = random.uniform(0, y_max)
        if _is_in_triangle(x, y):
            pts.append([x, y])
    return np.array(pts)

def _optimize_points(pts: np.ndarray, iterations: int = 2000) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)
    n = len(pts)

    for _ in range(iterations):
        new_pts = best_pts.copy()
        idx = random.randint(0, n-1)
        step = 0.05 * (1 - _/iterations)
        new_pts[idx] += np.random.uniform(-step, step, 2)

        x, y = new_pts[idx]
        if not _is_in_triangle(x, y):
            continue

        new_area = _min_triangle_area(new_pts)
        if new_area > best_area:
            best_area = new_area
            best_pts = new_pts.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _hexagonal_grid(11)
    # Verify all points are inside the triangle before optimization
    for x, y in pts:
        if not _is_in_triangle(x, y):
            y_max = SQRT3 * (1 - abs(2*x - 1))
            y = random.uniform(0, y_max)
            while not _is_in_triangle(x, y):
                y = random.uniform(0, y_max)
    pts = _optimize_points(pts, 2000)

    return [(float(x), float(y)) for x, y in pts]

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRI_AREA = SQRT3 / 4.0
TARGET_AREA = 0.0365 * TRI_AREA

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                area = _area(pts[i], pts[j], pts[k])
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0
    return min_area

def _is_inside(p: np.ndarray) -> bool:
    x, y = p
    if y < 0 or y > SQRT3/2:
        return False
    if x < 0 or x > 1:
        return False
    if y > SQRT3 * x or y > SQRT3 * (1 - x):
        return False
    return True

def _generate_initial_points(n: int) -> np.ndarray:
    pts = []
    while len(pts) < n:
        x = random.uniform(0, 1)
        y = random.uniform(0, SQRT3/2)
        if _is_inside(np.array([x, y])):
            pts.append([x, y])
    return np.array(pts)

def _simulated_annealing(n_pts: int, initial_temp: float, cooling_rate: float, steps: int) -> np.ndarray:
    current_solution = _generate_initial_points(n_pts)
    current_energy = -_min_triangle_area(current_solution)
    best_solution = current_solution.copy()
    best_energy = current_energy

    temp = initial_temp

    for step in range(steps):
        if -best_energy >= TARGET_AREA:
            break

        temp *= cooling_rate
        new_solution = current_solution.copy()

        idx = random.randint(0, n_pts-1)
        new_point = new_solution[idx] + np.random.uniform(-0.02, 0.02, 2)
        if _is_inside(new_point):
            new_solution[idx] = new_point

        new_energy = -_min_triangle_area(new_solution)

        if new_energy < current_energy or random.random() < math.exp((current_energy - new_energy)/temp):
            current_solution = new_solution
            current_energy = new_energy

            if new_energy < best_energy:
                best_solution = new_solution.copy()
                best_energy = new_energy

    return best_solution

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    pts = _simulated_annealing(n_pts=11, initial_temp=10.0, cooling_rate=0.999, steps=5000)

    return [(float(x), float(y)) for x, y in pts]

from __future__ import annotations
import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])
TRI_AREA = SQRT3 / 4.0

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n-2):
        for j in range(i+1, n-1):
            p0 = pts[i]
            p1 = pts[j]
            dx1 = p1[0] - p0[0]
            dy1 = p1[1] - p0[1]
            for k in range(j+1, n):
                dx2 = pts[k][0] - p0[0]
                dy2 = pts[k][1] - p0[1]
                area = abs(dx1*dy2 - dx2*dy1) * 0.5
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0
    return min_area

def _is_inside(p: np.ndarray) -> bool:
    try:
        u, v = np.linalg.solve(np.column_stack((_B-_A, _C-_A)), p-_A)
    except:
        return False
    return u >= -1e-8 and v >= -1e-8 and (1-u-v) >= -1e-8

def _generate_hex_grid(n: int) -> np.ndarray:
    k = math.ceil(math.sqrt(n / 3)) + 2
    x = np.linspace(0, 1, 2*k+1)
    y = np.linspace(0, SQRT3/2, k+1)
    xx, yy = np.meshgrid(x, y)
    pts = np.column_stack((xx.ravel(), yy.ravel()))
    mask = np.array([_is_inside(p) for p in pts])
    inside = pts[mask]
    if len(inside) < n:
        return _generate_hex_grid(n)
    return inside[np.random.choice(len(inside), n, replace=False)]

def _differential_evolution(n_pts: int, max_iter: int) -> np.ndarray:
    pop_size = 30
    F = 0.7
    CR = 0.9

    def eval_fn(x):
        pts = x.reshape(-1, 2)
        if not all(_is_inside(p) for p in pts):
            return float('inf')
        return -_min_triangle_area(pts)

    pop = []
    for _ in range(pop_size):
        pts = _generate_hex_grid(n_pts)
        pop.append(pts.flatten())
    pop = np.array(pop)

    best_idx = np.argmin([eval_fn(ind) for ind in pop])
    best_sol = pop[best_idx]
    best_val = eval_fn(best_sol)

    for _ in range(max_iter):
        for i in range(pop_size):
            idxs = [idx for idx in range(pop_size) if idx != i]
            a, b, c = pop[np.random.choice(idxs, 3, replace=False)]
            mutant = a + F * (b - c)

            cross_points = np.random.rand(n_pts*2) < CR
            trial = np.where(cross_points, mutant, pop[i])

            for j in range(n_pts):
                x, y = trial[j*2], trial[j*2+1]
                if not _is_inside(np.array([x, y])):
                    x = np.clip(x, 0, 1)
                    y = np.clip(y, 0, SQRT3/2)
                    trial[j*2], trial[j*2+1] = x, y

            trial_val = eval_fn(trial)
            if trial_val < best_val:
                best_val = trial_val
                best_sol = trial.copy()
            if trial_val < eval_fn(pop[i]):
                pop[i] = trial

    return best_sol.reshape(-1, 2)

def _refine(pts: np.ndarray, steps: int) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    n_pts = len(pts)

    for step in range(steps):
        step_size = 0.02 * (1 - step/steps)**2
        for idx in range(n_pts):
            for _ in range(5):
                trial = best_pts.copy()
                delta = np.random.uniform(-step_size, step_size, 2)
                trial[idx] += delta
                if _is_inside(trial[idx]):
                    trial_val = _min_triangle_area(trial)
                    if trial_val > best_val:
                        best_val = trial_val
                        best_pts = trial.copy()

    # Final push-apart step
    for _ in range(20):
        min_area = float('inf')
        worst_triplet = None
        for i in range(n_pts-2):
            for j in range(i+1, n_pts-1):
                for k in range(j+1, n_pts):
                    area = _area(best_pts[i], best_pts[j], best_pts[k])
                    if area < min_area:
                        min_area = area
                        worst_triplet = (i, j, k)

        if worst_triplet:
            i, j, k = worst_triplet
            center = (best_pts[i] + best_pts[j] + best_pts[k]) / 3
            for idx in worst_triplet:
                direction = best_pts[idx] - center
                direction /= np.linalg.norm(direction) + 1e-8
                new_pos = best_pts[idx] + 0.01 * direction
                if _is_inside(new_pos):
                    best_pts[idx] = new_pos

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    pts = _differential_evolution(n_pts=11, max_iter=50)
    pts = _refine(pts, steps=150)

    return [(float(x), float(y)) for x, y in pts]

