import math
import random
import itertools
from typing import List, Tuple, Optional
import numpy as np

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0
EPSILON = 1e-8
MARGIN = 1e-4

def _is_inside_triangle(pt: np.ndarray) -> bool:
    x, y = pt
    return (y >= MARGIN and 
            x >= MARGIN and 
            (x + y/SQRT3) <= 1.0 - MARGIN and 
            (x - y/SQRT3) <= 0.0 + MARGIN)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5 / TRIANGLE_AREA

class MinAreaTracker:
    def __init__(self, pts: np.ndarray):
        self.pts = pts.copy()
        self.n = len(pts)
        self.triplets = list(itertools.combinations(range(self.n), 3))
        self.point_to_triplets = [[] for _ in range(self.n)]
        for idx_triplet, triplet in enumerate(self.triplets):
            for i in triplet:
                self.point_to_triplets[i].append(idx_triplet)
        self.areas_arr = np.zeros(len(self.triplets))
        for idx_triplet, (i, j, k) in enumerate(self.triplets):
            self.areas_arr[idx_triplet] = _area(pts[i], pts[j], pts[k])
        self.min_area = np.min(self.areas_arr)

    def update_point(self, idx: int, new_pos: np.ndarray) -> bool:
        if not _is_inside_triangle(new_pos):
            return False
        self.pts[idx] = new_pos
        for idx_triplet in self.point_to_triplets[idx]:
            i, j, k = self.triplets[idx_triplet]
            self.areas_arr[idx_triplet] = _area(self.pts[i], self.pts[j], self.pts[k])
        self.min_area = np.min(self.areas_arr)
        return True

    def get_min_area(self) -> float:
        return self.min_area

def _random_barycentric(rng: np.random.Generator) -> Tuple[float, float, float]:
    while True:
        u, v = rng.random(2)
        if u + v <= 1.0:
            return (1 - u - v, u, v)

def _barycentric_to_cartesian(bary: Tuple[float, float, float]) -> np.ndarray:
    a, b, c = bary
    return np.array([0.5 * (b - a) + c * 0.5, c * SQRT3 / 2])

def _initial_configuration(n_pts: int = 11, rng: np.random.Generator = None) -> np.ndarray:
    if rng is None:
        rng = np.random.default_rng()

    pts = []
    # Hexagonal lattice with margin
    k = math.ceil(math.sqrt(2 * n_pts / (SQRT3/2)))
    offset = 1/(2*k)
    margin = 0.5/k
    for i in range(k):
        for j in range(k):
            if len(pts) >= n_pts:
                break
            x = (i + 0.5 * (j % 2)) / k + offset
            y = (j * SQRT3 / 2) / k + offset
            x = np.clip(x, margin, 1 - margin)
            y = np.clip(y, margin, SQRT3/2 - margin)
            pt = np.array([x, y])
            if _is_inside_triangle(pt):
                pts.append(pt)

    # Fill remaining points with random positions
    while len(pts) < n_pts:
        bary = _random_barycentric(rng)
        pt = _barycentric_to_cartesian(bary)
        if _is_inside_triangle(pt):
            pts.append(pt)

    return np.array(pts[:n_pts])

def _optimize(n_pts: int = 11, iters: int = 10000, seed: int | None = None) -> np.ndarray:
    rng = np.random.default_rng(seed)
    pts = _initial_configuration(n_pts, rng)
    tracker = MinAreaTracker(pts)
    best_pts = pts.copy()
    best_val = tracker.get_min_area()

    for t in range(iters):
        T = max(0.01 * (1 - t/iters), 1e-6)
        step_size = 0.02 * (1 - t/iters) + 0.001

        idx = rng.integers(0, n_pts)
        old_pos = pts[idx].copy()

        # Move in barycentric coordinates
        bary = _random_barycentric(rng)
        new_pos = _barycentric_to_cartesian(bary)

        if not tracker.update_point(idx, new_pos):
            continue

        trial_val = tracker.get_min_area()
        delta = trial_val - best_val

        if delta > 0 or rng.random() < math.exp(delta / T):
            pts = tracker.pts.copy()
            if trial_val > best_val:
                best_val = trial_val
                best_pts = pts.copy()
        else:
            tracker.update_point(idx, old_pos)

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    pts = _optimize(n_pts=11, iters=10000, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

import math
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _min_triangle_area_vectorized(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')

    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                vec1 = pts[j] - pts[i]
                vec2 = pts[k] - pts[i]
                area = abs(vec1[0]*vec2[1] - vec1[1]*vec2[0]) * 0.5
                if area < min_area:
                    min_area = area
                    if min_area < 1e-6:
                        return min_area
    return min_area

def _generate_initial_points(n: int) -> np.ndarray:
    # Generate hexagonal lattice points within the equilateral triangle
    points = []
    size = int(math.ceil(math.sqrt(n * 2 / SQRT3)))

    for i in range(size):
        for j in range(size):
            if i + j >= size:
                continue
            x = 0.5 * (i + 2*j) / size
            y = SQRT3 * i / (2 * size)
            points.append([x, y])

    # If we generated more points than needed, select the most spread ones
    if len(points) > n:
        selected = []
        remaining = points.copy()
        selected.append(remaining.pop(np.argmax([p[0]**2 + p[1]**2 for p in remaining])))

        while len(selected) < n:
            max_dist = -1
            best_idx = -1
            for i, p in enumerate(remaining):
                min_dist = min(np.linalg.norm(p - s) for s in selected)
                if min_dist > max_dist:
                    max_dist = min_dist
                    best_idx = i
            selected.append(remaining.pop(best_idx))
        points = selected

    return np.array(points[:n])

def _differential_evolution(n_pts: int = 11, max_iter: int = 500, F: float = 0.8, CR: float = 0.9) -> np.ndarray:
    pop_size = 30
    population = [_generate_initial_points(n_pts) for _ in range(pop_size)]
    fitness = [_min_triangle_area_vectorized(ind) for ind in population]

    best_idx = np.argmax(fitness)
    best_individual = population[best_idx].copy()
    best_fitness = fitness[best_idx]

    for _ in range(max_iter):
        for i in range(pop_size):
            # Mutation
            idxs = [idx for idx in range(pop_size) if idx != i]
            a, b, c = population[np.random.choice(idxs, 3, replace=False)]
            mutant = a + F * (b - c)

            # Project back to triangle
            for j in range(n_pts):
                x, y = mutant[j]
                if y < 0 or y > SQRT3/2 or x < 0 or x > 1 or (y > SQRT3 * x) or (y > SQRT3 * (1 - x)):
                    # Project to nearest point inside triangle
                    if y < 0:
                        y = 0
                    if y > SQRT3/2:
                        y = SQRT3/2
                    if x < 0:
                        x = 0
                    if x > 1:
                        x = 1
                    if y > SQRT3 * x:
                        y = SQRT3 * x
                    if y > SQRT3 * (1 - x):
                        y = SQRT3 * (1 - x)
                    mutant[j] = [x, y]

            # Crossover
            trial = population[i].copy()
            for j in range(n_pts):
                if np.random.rand() < CR:
                    trial[j] = mutant[j]

            # Selection
            trial_fitness = _min_triangle_area_vectorized(trial)
            if trial_fitness > fitness[i]:
                population[i] = trial
                fitness[i] = trial_fitness

                if trial_fitness > best_fitness:
                    best_fitness = trial_fitness
                    best_individual = trial.copy()

    return best_individual

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    np.random.seed(seed)
    pts = _differential_evolution(n_pts=11, max_iter=500)
    return [(float(x), float(y)) for x, y in pts]

from __future__ import annotations

import math
import random
import itertools
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_HEIGHT = SQRT3 / 2.0
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p, q, r) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5 / TRIANGLE_AREA

def _is_inside(x, y):
    return y >= 0 and y <= SQRT3 * min(x, 1-x)

class UpdatableMinTriangleArea:
    def __init__(self, pts):
        self.pts = np.array(pts)
        self.n = len(pts)
        self.min_area = float('inf')
        self.min_triangles = []
        self._compute_all_areas()

    def _compute_all_areas(self):
        self.min_area = float('inf')
        self.min_triangles = []
        for i in range(self.n):
            for j in range(i+1, self.n):
                for k in range(j+1, self.n):
                    a = _area(self.pts[i], self.pts[j], self.pts[k])
                    if a < self.min_area:
                        self.min_area = a
                        self.min_triangles = [(i,j,k)]
                    elif a == self.min_area:
                        self.min_triangles.append((i,j,k))

    def update_point(self, index, new_pt):
        old_pt = self.pts[index].copy()
        self.pts[index] = new_pt

        affected = set()
        for tri in self.min_triangles:
            affected.update(tri)

        for i in range(self.n):
            if i == index:
                continue
            for j in range(i+1, self.n):
                if j == index:
                    continue
                if i in affected or j in affected:
                    a = _area(self.pts[i], self.pts[j], self.pts[index])
                    if a < self.min_area:
                        self.min_area = a
                        self.min_triangles = [(i,j,index)]
                    elif a == self.min_area:
                        self.min_triangles.append((i,j,index))

        if len(self.min_triangles) > 10:
            self._compute_all_areas()

    def get_min_area(self):
        return self.min_area

def _initial_configuration() -> np.ndarray:
    pts = []
    pts.append((0.0, 0.0))
    pts.append((1.0, 0.0))
    pts.append((0.5, TRIANGLE_HEIGHT))

    # Hexagonal grid points
    for i in range(1, 4):
        y = i * TRIANGLE_HEIGHT / 4
        for j in range(i+1):
            x = (0.5 - i/8) + j * (1.0/(4 if i==3 else i))
            if _is_inside(x, y):
                pts.append((x, y))

    # Fill remaining points with center-biased random
    while len(pts) < 11:
        x = np.random.normal(0.5, 0.15)
        y = np.random.uniform(0, TRIANGLE_HEIGHT)
        if _is_inside(x, y) and all(math.hypot(x-p[0], y-p[1]) > 0.1 for p in pts):
            pts.append((x, y))

    return np.array(pts[:11])

def _optimize_points(pts: np.ndarray, steps: int) -> np.ndarray:
    n = len(pts)
    area_computer = UpdatableMinTriangleArea(pts)
    best_pts = pts.copy()
    best_val = area_computer.get_min_area()

    for step in range(steps):
        temp = max(0.01, 1.0 - step / steps)
        step_size = 0.02 * temp

        critical = set()
        for tri in area_computer.min_triangles:
            critical.update(tri)

        for i in critical:
            angle = random.uniform(0, 2*math.pi)
            dx = step_size * math.cos(angle)
            dy = step_size * math.sin(angle)
            trial_pt = best_pts[i] + np.array([dx, dy])
            x, y = trial_pt

            if not _is_inside(x, y):
                continue

            backup_pt = best_pts[i].copy()
            area_computer.update_point(i, trial_pt)
            new_val = area_computer.get_min_area()

            if new_val > best_val or (random.random() < math.exp((new_val - best_val) / temp)):
                best_val = new_val
                best_pts[i] = trial_pt
            else:
                area_computer.update_point(i, backup_pt)

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    pts = _initial_configuration()
    pts = _optimize_points(pts, 5000)

    return [(float(x), float(y)) for x, y in pts]

