def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n-2):
        for j in range(i+1, n-1):
            p1 = pts[j] - pts[i]
            for k in range(j+1, n):
                area = abs(np.cross(p1, pts[k] - pts[i])) * 0.5
                if area < min_area:
                    min_area = area
                    if min_area < 1e-8:
                        return 0.0
    return min_area

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        total = u + v
        u /= total
        v /= total
    return (1 - u - v) * _A + u * _B + v * _C

def _hexagonal_configuration(n_pts: int = 11) -> np.ndarray:
    pts = []
    layers = math.ceil((n_pts / 3)**0.5) + 1
    for i in range(layers):
        for j in range(layers):
            if len(pts) >= n_pts:
                break
            x = 0.1 + 0.8 * i / max(1, layers - 1)
            y = 0.1 + 0.8 * j / max(1, layers - 1)
            pts.append((x, y * SQRT3/2))
    while len(pts) < n_pts:
        pts.append(_random_point())
    return np.array(pts)

def _anneal(n_pts: int = 11, seed: int | None = None) -> np.ndarray:
    if seed is not None:
        random.seed(seed)
    pts = _hexagonal_configuration(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(3000):
        T = 0.1 * (0.99 ** t)
        step = 0.1 * (1 - t/3000) + 0.005
        trial = pts.copy()

        # Perturb multiple points
        for _ in range(1 + int(t/1000)):
            idx = random.randrange(n_pts)
            trial[idx] += random.uniform(-step, step), random.uniform(-step, step)
            trial[idx] = _project_to_simplex(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or random.random() < math.exp(delta / max(T, 1e-12)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()
                if best_val > 0.035:
                    break

    return best_pts

def _local_search(pts: np.ndarray, steps: int = 1000) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    n = len(pts)

    for step_num in range(steps):
        trial = best_pts.copy()
        step = 0.03 * (1 - step_num/steps)

        # Perturb 2 points at once
        for _ in range(2):
            idx = random.randrange(n)
            trial[idx] += random.uniform(-step, step), random.uniform(-step, step)
            trial[idx] = _project_to_simplex(trial[idx])

        trial_val = _min_triangle_area(trial)
        if trial_val > best_val:
            best_val = trial_val
            best_pts = trial.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    best_val = 0.0
    best_pts = _hexagonal_configuration(11)
    for _ in range(3):
        pts = _anneal(11, seed)
        pts = _local_search(pts, 1000)
        val = _min_triangle_area(pts)
        if val > best_val:
            best_val = val
            best_pts = pts
        if best_val > 0.036:
            break
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in best_pts]

