SQRT3 = math.sqrt(3.0)
INV_SQRT3 = 1.0 / SQRT3

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _hexagonal_grid(n: int) -> np.ndarray:
    size = math.ceil(math.sqrt(n * 2 / SQRT3)) + 1
    pts = []
    for j in range(size):
        for i in range(size):
            x = (i + 0.5 * (j % 2)) / size
            y = j * SQRT3 * 0.5 / size
            if x <= 1.0 and y <= SQRT3/2 and (1-x)*SQRT3 >= y:
                pts.append([x, y])
            if len(pts) >= n:
                return np.array(pts)
    return np.array(pts[:n])

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = max(0.0, min(1.0, uv[0])), max(0.0, min(1.0, uv[1]))
    if u + v > 1.0:
        u, v = 1 - u, 1 - v
    return (1 - u - v) * _A + u * _B + v * _C

def _min_triangle_area_fast(pts: np.ndarray) -> float:
    tree = KDTree(pts)
    min_area = float('inf')
    for i in range(len(pts)):
        dists, idxs = tree.query(pts[i], k=6)
        for j in idxs[1:]:
            if j <= i:
                continue
            for k in idxs[1:]:
                if k <= j:
                    continue
                vec1 = pts[j] - pts[i]
                vec2 = pts[k] - pts[i]
                cross = abs(vec1[0]*vec2[1] - vec1[1]*vec2[0])
                if cross < min_area:
                    min_area = cross
                    if min_area == 0:
                        return 0.0
    return min_area * 0.5

def _optimize_points(pts: np.ndarray, iters: int = 200) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area_fast(pts)
    for _ in range(iters):
        for i in range(len(pts)):
            for angle in np.linspace(0, 2*np.pi, 8, endpoint=False):
                dx, dy = 0.01*math.cos(angle), 0.01*math.sin(angle)
                trial = best_pts.copy()
                trial[i] += (dx, dy)
                trial[i] = _project_to_simplex(trial[i])
                val = _min_triangle_area_fast(trial)
                if val > best_val:
                    best_val = val
                    best_pts = trial.copy()
    return best_pts

def _anneal(n_pts: int = 11) -> np.ndarray:
    best_pts = _hexagonal_grid(n_pts)
    best_val = _min_triangle_area_fast(best_pts)
    pts = best_pts.copy()

    for _ in range(3000):
        idx = random.randrange(n_pts)
        trial = pts.copy()
        trial[idx] += random.uniform(-0.03, 0.03), random.uniform(-0.03, 0.03)
        trial[idx] = _project_to_simplex(trial[idx])
        trial_val = _min_triangle_area_fast(trial)

        if trial_val > best_val:
            best_val = trial_val
            best_pts = trial.copy()
        pts = trial

    return _optimize_points(best_pts)

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)
    pts = _anneal(n_pts=11)
    return [(float(x), float(y)) for x, y in pts]

