import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
HEIGHT = SQRT3 / 2.0

def _random_point() -> np.ndarray:
    while True:
        x = random.random()
        y = random.uniform(0, HEIGHT)
        if y <= SQRT3 * min(x, 1 - x):
            return np.array([x, y])

def _is_inside(p: np.ndarray) -> bool:
    x, y = p
    return (y >= 0 and y <= SQRT3 * min(x, 1 - x) and x >= 0 and x <= 1)

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    x, y = p
    x = max(0.0, min(1.0, x))
    max_y = SQRT3 * min(x, 1 - x)
    y = max(0.0, min(max_y, y))
    return np.array([x, y])

def _triangle_area(a: np.ndarray, b: np.ndarray, c: np.ndarray) -> float:
    return abs((b[0]-a[0])*(c[1]-a[1]) - (b[1]-a[1])*(c[0]-a[0])) / 2.0

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    if n < 3:
        return 0.0
    min_area = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                area = _triangle_area(pts[i], pts[j], pts[k])
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0.0
    return min_area

def _optimize_points(n_pts: int = 11, max_iter: int = 5000, seed: int | None = None) -> np.ndarray:
    if seed is not None:
        random.seed(seed)

    # Initialize with grid-like pattern
    best_pts = []
    grid_size = math.ceil(math.sqrt(n_pts))
    for i in range(n_pts):
        x = (i % grid_size + 0.5) / grid_size
        y = (i // grid_size + 0.5) / grid_size * HEIGHT
        best_pts.append(_project_to_triangle(np.array([x, y])))
    best_pts = np.array(best_pts)
    best_area = _min_triangle_area(best_pts)

    # Add some random perturbations to initial points
    for _ in range(100):
        pts = best_pts.copy()
        for i in range(n_pts):
            if random.random() < 0.3:
                pts[i] = _random_point()
        area = _min_triangle_area(pts)
        if area > best_area:
            best_area = area
            best_pts = pts.copy()

    # Simulated annealing with adaptive step size
    current_pts = best_pts.copy()
    current_area = best_area
    step_size = 0.1

    for iter in range(max_iter):
        T = 1.0 - (iter / max_iter)

        # Adaptive step size
        if iter % 100 == 0:
            step_size = max(0.01, min(0.2, step_size * (0.9 + random.random()*0.2)))

        # Perturb one point
        idx = random.randrange(n_pts)
        new_pts = current_pts.copy()
        angle = random.uniform(0, 2*math.pi)
        distance = random.uniform(0, step_size)
        dx = distance * math.cos(angle)
        dy = distance * math.sin(angle)
        new_pts[idx] = _project_to_triangle(new_pts[idx] + np.array([dx, dy]))

        new_area = _min_triangle_area(new_pts)
        delta = new_area - current_area

        if delta > 0 or (T > 0 and random.random() < math.exp(delta / (T + 1e-12)))):
            current_pts = new_pts
            current_area = new_area
            if new_area > best_area:
                best_area = new_area
                best_pts = new_pts.copy()

    # Final local optimization
    for _ in range(200):
        improved = False
        for idx in range(n_pts):
            for angle in np.linspace(0, 2*math.pi, 8, endpoint=False):
                for distance in [0.01, 0.005, 0.002]:
                    new_pts = best_pts.copy()
                    dx = distance * math.cos(angle)
                    dy = distance * math.sin(angle)
                    new_pts[idx] = _project_to_triangle(new_pts[idx] + np.array([dx, dy]))
                    new_area = _min_triangle_area(new_pts)
                    if new_area > best_area:
                        best_area = new_area
                        best_pts = new_pts.copy()
                        improved = True
        if not improved:
            break

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    pts = _optimize_points(n_pts=11, seed=seed)
    return [(float(p[0]), float(p[1])) for p in pts]

