def _min_triangle_area(pts):
    min_area = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, min(i+5, n)):
            for k in range(j+1, min(j+5, n)):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area < 1e-8:
                        return min_area
    return min_area

def _is_in_triangle(p):
    x, y = p
    if x < 0 or x > 1 or y < 0 or y > SQRT3/2:
        return False
    if y > SQRT3 * x:
        return False
    if y > SQRT3 * (1 - x):
        return False
    return True

def _generate_initial_points(n):
    base_points = [
        [0.1, 0.05], [0.9, 0.05],
        [0.2, 0.15], [0.8, 0.15],
        [0.3, 0.3], [0.7, 0.3],
        [0.4, 0.45], [0.6, 0.45],
        [0.5, 0.6],
        [0.2, 0.4], [0.8, 0.4]  # Moved these slightly lower
    ]
    points = []
    for p in base_points[:n]:
        for _ in range(10):  # Try multiple times to get valid point
            x = p[0] + random.uniform(-0.01, 0.01)
            y = p[1] + random.uniform(-0.01, 0.01)
            if _is_in_triangle((x, y)):
                points.append([x, y])
                break
        else:
            points.append(p.copy())  # Fallback to base point if needed
    return np.array(points)

def _optimize_points(points, iterations):
    best_points = points.copy()
    best_score = _min_triangle_area(best_points)

    for i in range(iterations):
        new_points = best_points.copy()
        idx = i % len(points)

        step = max(0.005, 0.02 * (1 - i/iterations))

        for _ in range(5):  # Try more perturbation attempts
            temp_points = new_points.copy()
            delta = np.random.uniform(-step, step, 2)
            temp_points[idx] += delta

            if _is_in_triangle(temp_points[idx]):
                temp_score = _min_triangle_area(temp_points)
                if temp_score > best_score:
                    best_score = temp_score
                    new_points = temp_points.copy()
                    break

    return best_points

def find_points(seed=None):
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    points = _generate_initial_points(11)
    points = _optimize_points(points, 3000)  # Slightly fewer iterations for safety

    # Final validation pass
    valid_points = []
    for p in points:
        if _is_in_triangle(p):
            valid_points.append(p)
        else:
