            if y > SQRT3 * x:
                y = SQRT3 * x
            if y > SQRT3 * (1 - x):
                y = SQRT3 * (1 - x)
            valid_points.append([x, y])

    return [(float(p[0]), float(p[1])) for p in valid_points]

