import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5 / TRIANGLE_AREA

def _min_triangle_area(pts: np.ndarray) -> float:
    min_area = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _is_inside_triangle(p: np.ndarray) -> bool:
    v0 = _C - _A
    v1 = _B - _A
    v2 = p - _A

    dot00 = np.dot(v0, v0)
    dot01 = np.dot(v0, v1)
    dot02 = np.dot(v0, v2)
    dot11 = np.dot(v1, v1)
    dot12 = np.dot(v1, v2)

    inv_denom = 1 / (dot00 * dot11 - dot01 * dot01)
    u = (dot11 * dot02 - dot01 * dot12) * inv_denom
    v = (dot00 * dot12 - dot01 * dot02) * inv_denom

    return (u >= 0) and (v >= 0) and (u + v <= 1)

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _initial_configuration(n_pts: int = 11) -> np.ndarray:
    pts = []
    for i in range(n_pts):
        pts.append(_random_point())
    return np.array(pts)

def _optimize_points(pts: np.ndarray, iterations: int = 1000) -> np.ndarray:
    n = len(pts)
    best_pts = pts.copy()
    best_score = _min_triangle_area(best_pts)

    for _ in range(iterations):
        for i in range(n):
            current_pt = pts[i].copy()
            best_local_pt = current_pt.copy()
            best_local_score = best_score

            for _ in range(10):
                offset = np.random.normal(0, 0.01, 2)
                trial_pt = current_pt + offset

                if not _is_inside_triangle(trial_pt):
                    continue

                trial_pts = pts.copy()
                trial_pts[i] = trial_pt
                trial_score = _min_triangle_area(trial_pts)

                if trial_score > best_local_score:
                    best_local_score = trial_score
                    best_local_pt = trial_pt.copy()

            if best_local_score > best_score:
                pts[i] = best_local_pt
                best_score = best_local_score
                best_pts = pts.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _initial_configuration(11)
    pts = _optimize_points(pts, 500)

    return [(float(x), float(y)) for x, y in pts]

