from __future__ import annotations

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5 / TRIANGLE_AREA

def _min_triangle_area(pts: np.ndarray) -> float:
    best = float("inf")
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best < 1e-8:
                        return 0
    return best

def _is_inside_triangle(p: np.ndarray) -> bool:
    x, y = p
    if x < 0 or x > 1 or y < 0 or y > SQRT3/2:
        return False
    if y > SQRT3 * x or y > SQRT3 * (1 - x):
        return False
    return True

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    x, y = p
    if _is_inside_triangle(p):
        return p

    # Project to closest edge
    x = max(0.0, min(1.0, x))
    y = max(0.0, min(SQRT3/2, y))

    # Project to diagonal edges
    if y > SQRT3 * x:
        y = SQRT3 * x
    if y > SQRT3 * (1 - x):
        y = SQRT3 * (1 - x)

    return np.array([x, y])

def _hexagonal_configuration(n_pts: int = 11) -> np.ndarray:
    pts = []
    center = np.array([0.5, SQRT3/6])
    radius = 0.45
    layers = 3

    for layer in range(layers):
        r = radius * (layer + 1) / layers
        points_in_layer = 4 if layer > 0 else 3
        for i in range(points_in_layer):
            angle = 2 * math.pi * i / points_in_layer
            x = center[0] + r * math.cos(angle)
            y = center[1] + r * math.sin(angle)
            pt = np.array([x, y])
            pt = _project_to_triangle(pt)
            pts.append(pt)

    while len(pts) < n_pts:
        x = random.uniform(0.1, 0.9)
        y_max = min(SQRT3 * x, SQRT3 * (1 - x))
        y = random.uniform(0.1, y_max - 0.1)
        pts.append(np.array([x, y]))

    return np.array(pts[:n_pts])

def _optimized_search(n_pts: int = 11, iters: int = 5000) -> np.ndarray:
    pts = _hexagonal_configuration(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        step_size = 0.1 * (1 - t/iters) + 0.01
        idx = random.randrange(n_pts)
        trial = pts.copy()
        trial[idx] += random.uniform(-step_size, step_size), random.uniform(-step_size, step_size)
        trial[idx] = _project_to_triangle(trial[idx])

        trial_val = _min_triangle_area(trial)

        if trial_val > best_val:
            best_val = trial_val
            best_pts = trial.copy()
            pts = trial.copy()
        elif random.random() < 0.1:
            pts = trial.copy()

    return best_pts

def _targeted_perturb(pts: np.ndarray, steps: int = 200) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    n = len(pts)

    for _ in range(steps):
        trial = best_pts.copy()
        areas = []
        for i in range(n):
            for j in range(i+1, n):
                for k in range(j+1, n):
                    a = _area(trial[i], trial[j], trial[k])
                    areas.append((a, i, j, k))

        areas.sort()
        worst_triangles = areas[:3]
        affected_points = set()
        for a, i, j, k in worst_triangles:
            affected_points.update([i, j, k])

        step = 0.02
        for idx in affected_points:
            trial[idx] += random.uniform(-step, step), random.uniform(-step, step)
            trial[idx] = _project_to_triangle(trial[idx])

        trial_val = _min_triangle_area(trial)
        if trial_val > best_val:
            best_val = trial_val
            best_pts = trial.copy()

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
    pts = _optimized_search(n_pts=11)
    pts = _targeted_perturb(pts)
    return [(float(x), float(y)) for x, y in pts]

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area_fast(pts: np.ndarray) -> float:
    min_area = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    u, v = random.random(), random.random()
    if u + v > 1.0:
        u, v = 1 - u, 1 - v
    return (1 - u - v) * _A + u * _B + v * _C

def _hexagonal_points(n: int) -> List[np.ndarray]:
    k = int(math.sqrt(n * 2 / SQRT3)) + 1
    points = []
    for i in range(k):
        for j in range(k):
            if i + j > k:
                continue
            x = (i + 0.5 * (j % 2)) / k
            y = (j * SQRT3 / 2) / k
            if y > SQRT3 * (1 - x) or y > SQRT3 * x:
                continue
            points.append(np.array([x, y]))
            if len(points) >= n:
                return points
    return points

def _optimize_points(pts: np.ndarray, max_iter: int = 2000) -> np.ndarray:
    n = len(pts)
    best_pts = pts.copy()
    best_area = _min_triangle_area_fast(best_pts)

    for iter in range(max_iter):
        step = 0.01 * (1 - iter/max_iter)  # Adaptive step size
        improved = False
        for i in range(n):
            # Check 8 directions instead of 4
            for dx, dy in [(step,0), (-step,0), (0,step), (0,-step),
                          (step,step), (-step,-step), (step,-step), (-step,step)]:
                new_pts = best_pts.copy()
                new_pts[i] += np.array([dx, dy])
                # Ensure point stays in triangle
                x, y = new_pts[i]
                if y < 0 or y > SQRT3/2 or x < 0 or x > 1 or y > SQRT3*(1 - abs(2*x - 1)):
                    continue

                area = _min_triangle_area_fast(new_pts)
                if area > best_area:
                    best_area = area
                    best_pts = new_pts.copy()
                    improved = True
        if not improved and step < 0.001:
            break
    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)

    # Start with hexagonal points
    pts = np.array(_hexagonal_points(11))

    # Try multiple random configurations
    for _ in range(20):
        candidate = np.array([_random_point() for _ in range(11)])
        candidate_area = _min_triangle_area_fast(candidate)
        if candidate_area > _min_triangle_area_fast(pts):
            pts = candidate

    # Local optimization
    pts = _optimize_points(pts)

    # Final refinement with smaller steps
    pts = _optimize_points(pts, max_iter=1000)

    return [(float(x), float(y)) for x, y in pts]

