import math
import random
import itertools
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    min_area = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0.0
    return min_area

def _random_point() -> np.ndarray:
    u, v = np.random.random(2)
    if u + v > 1.0:
        u, v = 1-u, 1-v
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _initialize_points(n: int) -> np.ndarray:
    pts = []
    # Hexagonal grid initialization
    k = int(np.ceil(np.sqrt(n * 2 / SQRT3)))
    for i in range(k):
        for j in range(k):
            if len(pts) >= n:
                break
            x = (i + 0.5 * (j % 2)) / k
            y = (j * SQRT3 / 2) / k
            if x <= 1.0 and y <= SQRT3/2 and (SQRT3 * x + y) <= SQRT3:
                pts.append(np.array([x, y]))
    while len(pts) < n:
        pts.append(_random_point())
    return np.array(pts)

def _local_optimize(pts: np.ndarray, steps: int = 100) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    n = len(pts)

    for _ in range(steps):
        improved = False
        for i in range(n):
            for dx, dy in [(0.01,0), (-0.01,0), (0,0.01), (0,-0.01)]:
                trial = best_pts.copy()
                trial[i] += np.array([dx, dy])
                trial[i] = _project_to_simplex(trial[i])
                trial_val = _min_triangle_area(trial)
                if trial_val > best_val:
                    best_val = trial_val
                    best_pts = trial.copy()
                    improved = True
        if not improved:
            break
    return best_pts

def _anneal(n_pts: int = 11, iters: int = 3000) -> np.ndarray:
    pts = _initialize_points(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        T = 0.1 * (1e-6 / 0.1) ** (t / max(iters-1, 1))
        idx = np.random.randint(n_pts)
        trial = pts.copy()
        trial[idx] += np.random.normal(0, 0.015, size=2)
        trial[idx] = _project_to_simplex(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or np.random.random() < math.exp(delta / max(T, 1e-12)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

    return _local_optimize(best_pts)

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    if seed is not None:
        np.random.seed(seed)
    pts = _anneal(n_pts=11)
    return [(float(x), float(y)) for x, y in pts]

from __future__ import annotations
import math
import random
import numpy as np
from itertools import combinations
from scipy.optimize import minimize

SQRT3 = math.sqrt(3.0)

def _area_triples_fast(pts: np.ndarray) -> np.ndarray:
    n = len(pts)
    areas = np.zeros(n*(n-1)*(n-2)//6)
    idx = 0
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                v1 = pts[j] - pts[i]
                v2 = pts[k] - pts[i]
                areas[idx] = abs(v1[0]*v2[1] - v1[1]*v2[0]) * 0.5
                idx += 1
    return areas

def _min_triangle_area(pts: np.ndarray) -> float:
    areas = _area_triples_fast(pts)
    min_area = np.min(areas)
    return min_area if min_area > 1e-8 else 0.0

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    u, v = random.random(), random.random()
    if u + v > 1.0:
        u, v = 1 - u, 1 - v
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv[0], uv[1]
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = 1 - v, 1 - u
    return (1 - u - v) * _A + u * _B + v * _C

def _initial_configuration(n_pts: int = 11) -> np.ndarray:
    pts = []
    for _ in range(n_pts):
        pts.append(_random_point())
    return np.array(pts)

def _hexagonal_grid(n_pts: int = 11) -> np.ndarray:
    pts = []
    layers = int((n_pts / 3) ** 0.5) + 1
    for i in range(layers):
        for j in range(layers):
            if len(pts) >= n_pts:
                break
            u = (i + 0.5 * (j % 2)) / layers
            v = (j * SQRT3 / 2) / layers
            if u + v > 1.0:
                u, v = 1 - v, 1 - u
            pts.append((1 - u - v) * _A + u * _B + v * _C)
    while len(pts) < n_pts:
        pts.append(_random_point())
    return np.array(pts[:n_pts])

def _local_optimize_nelder_mead(pts: np.ndarray) -> np.ndarray:
    def objective(x):
        x_reshaped = x.reshape(-1, 2)
        return -_min_triangle_area(x_reshaped)

    x0 = pts.flatten()
    res = minimize(objective, x0, method='Nelder-Mead', options={'maxiter': 100})
    optimized_pts = res.x.reshape(-1, 2)
    return optimized_pts

def _differential_evolution(n_pts: int = 11, max_iter: int = 200, seed: int | None = 0) -> np.ndarray:
    random.seed(seed)
    population_size = 20
    population = [_hexagonal_grid(n_pts) for _ in range(population_size)]
    fitness = [_min_triangle_area(p) for p in population]
    best_idx = np.argmax(fitness)
    best_pts = population[best_idx].copy()
    best_val = fitness[best_idx]
    no_improve = 0

    for _ in range(max_iter):
        if no_improve >= 20:
            break
        for i in range(population_size):
            a, b, c = random.sample(range(population_size), 3)
            mutant = population[a] + 0.8 * (population[b] - population[c])
            mutant = np.array([_project_to_simplex(p) for p in mutant])
            trial_val = _min_triangle_area(mutant)

            if trial_val > best_val:
                best_val = trial_val
                best_pts = mutant.copy()
                population[i] = mutant.copy()
                no_improve = 0
            elif trial_val > fitness[i]:
                population[i] = mutant.copy()
                fitness[i] = trial_val
        no_improve += 1
    return _local_optimize_nelder_mead(best_pts)

def find_points(seed: int | None = 0) -> list[tuple[float, float]]:
    pts = _differential_evolution(n_pts=11, max_iter=200, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

