import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    u, v = random.random(), random.random()
    if u + v > 1.0:
        u, v = 1 - u, 1 - v
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = 1 - u, 1 - v
    return (1 - u - v) * _A + u * _B + v * _C

def _triangle_area(a: np.ndarray, b: np.ndarray, c: np.ndarray) -> float:
    return 0.5 * abs((b[0]-a[0])*(c[1]-a[1]) - (b[1]-a[1])*(c[0]-a[0]))

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    if n < 3:
        return 0.0

    min_area = float('inf')

    # Check all triangles periodically, but for speed use nearest neighbors most of the time
    for i in range(n):
        for j in range(i+1, min(i+6, n)):  # Limit neighbor range
            for k in range(j+1, min(j+6, n)):
                area = _triangle_area(pts[i], pts[j], pts[k])
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0.0
    return min_area

def _full_min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                area = _triangle_area(pts[i], pts[j], pts[k])
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0.0
    return min_area

def _anneal(n_pts: int = 11,
            iters: int = 15000,
            start_temp: float = 0.1,
            end_temp: float = 1e-10,
            seed: int | None = 0) -> np.ndarray:

    random.seed(seed)
    best_pts = np.array([_random_point() for _ in range(n_pts)])
    best_val = _min_triangle_area(best_pts)

    for restart in range(3):
        pts = np.array([_random_point() for _ in range(n_pts)])
        current_val = _min_triangle_area(pts)
        step_size = 0.02

        for t in range(iters):
            T = start_temp * (end_temp / start_temp) ** (t / iters)

            if t > 0 and t % 500 == 0:
                current_val = _full_min_triangle_area(pts)
                if current_val > best_val:
                    best_val = current_val
                    best_pts = pts.copy()

            idx = random.randrange(n_pts)
            trial = pts.copy()
            trial[idx] += random.uniform(-step_size, step_size), random.uniform(-step_size, step_size)
            trial[idx] = _project_to_simplex(trial[idx])

            trial_val = _min_triangle_area(trial)
            delta = trial_val - current_val

            if delta > 0 or random.random() < math.exp(delta / max(T, 1e-12)):
                pts = trial
                current_val = trial_val
                if trial_val > best_val:
                    best_val = trial_val
                    best_pts = trial.copy()

        # Gradient-based local search
        for _ in range(500):
            improved = False
            for idx in range(n_pts):
                for angle in np.linspace(0, 2*np.pi, 8):
                    dx, dy = 0.01*math.cos(angle), 0.01*math.sin(angle)
                    trial = best_pts.copy()
                    trial[idx] += dx, dy
                    trial[idx] = _project_to_simplex(trial[idx])
                    trial_val = _min_triangle_area(trial)
                    if trial_val > best_val:
                        best_val = trial_val
                        best_pts = trial.copy()
                        improved = True
            if not improved:
                break

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=20000, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

