import math
import random
import time
import numpy as np
from scipy.optimize import differential_evolution, minimize

SQRT3 = math.sqrt(3.0)
_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])
_TRIANGLE_AREA = SQRT3 / 4.0

def _is_inside_triangle(p: np.ndarray) -> bool:
    v0 = _C - _A
    v1 = _B - _A
    v2 = p - _A
    dot00 = np.dot(v0, v0)
    dot01 = np.dot(v0, v1)
    dot02 = np.dot(v0, v2)
    dot11 = np.dot(v1, v1)
    dot12 = np.dot(v1, v2)
    inv_denom = 1.0 / (dot00 * dot11 - dot01 * dot01)
    u = (dot11 * dot02 - dot01 * dot12) * inv_denom
    v = (dot00 * dot12 - dot01 * dot02) * inv_denom
    return (u >= 0) and (v >= 0) and (u + v <= 1)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5 / _TRIANGLE_AREA

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n-2):
        for j in range(i+1, n-1):
            p = pts[i]
            q = pts[j]
            for k in range(j+1, n):
                r = pts[k]
                a = abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / (2 * _TRIANGLE_AREA)
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

def _random_point_inside() -> np.ndarray:
    while True:
        x = random.uniform(0, 1)
        y = random.uniform(0, SQRT3/2)
        if y <= SQRT3 * min(x, 1 - x):
            return np.array([x, y])

def _initial_configuration(n_pts: int = 11) -> np.ndarray:
    pts = []
    # Improved initial configuration
    for i in range(3):
        for j in range(3):
            if i + j <= 3:
                x = 0.1 + 0.3 * i - 0.15 * j
                y = 0.15 * SQRT3 * j
                pts.append(np.array([x, y]))
    while len(pts) < n_pts:
        pts.append(_random_point_inside())
    return np.array(pts[:n_pts])

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    x, y = p
    if y < 0:
        y = 0
    if y > SQRT3/2:
        y = SQRT3/2
    if x < 0:
        x = 0
    if x > 1:
        x = 1
    if y > SQRT3 * x:
        y = SQRT3 * x
    if y > SQRT3 * (1 - x):
        y = SQRT3 * (1 - x)
    return np.array([x, y])

def find_points(seed: int | None = None) -> list[tuple[float, float]]:
    start_time = time.time()
    n_pts = 11

    # First phase: global optimization
    bounds = [(0, 1), (0, SQRT3/2)] * n_pts
    def objective(x):
        pts = x.reshape((-1, 2))
        for i in range(n_pts):
            pts[i] = _project_to_triangle(pts[i])
        return -_min_triangle_area(pts)

    result = differential_evolution(
        objective,
        bounds,
        strategy='best1bin',
        maxiter=100,
        popsize=15,
        tol=1e-6,
        seed=seed,
        polish=False
    )

    pts = result.x.reshape((-1, 2))
    for i in range(n_pts):
        pts[i] = _project_to_triangle(pts[i])

    # Second phase: local optimization if time permits
    if time.time() - start_time < 20:
        def local_objective(x):
            pts = x.reshape((-1, 2))
            for i in range(n_pts):
                pts[i] = _project_to_triangle(pts[i])
            return -_min_triangle_area(pts)

        res = minimize(
            local_objective,
            pts.ravel(),
            method='Nelder-Mead',
            options={'maxiter': 500}
        )
        if res.success:
            pts = res.x.reshape((-1, 2))
            for i in range(n_pts):
                pts[i] = _project_to_triangle(pts[i])

    return [(float(x), float(y)) for x, y in pts]

import math
import random
import numpy as np
