import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    best = float("inf")
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

def _random_barycentric() -> Tuple[float, float, float]:
    while True:
        u = random.random()
        v = random.random()
        if u + v <= 1:
            return (1 - u - v, u, v)

def _barycentric_to_cartesian(b: Tuple[float, float, float]) -> np.ndarray:
    a1, a2, a3 = b
    x = a2 + a3 * 0.5
    y = a3 * SQRT3 / 2
    return np.array([x, y])

def _cartesian_to_barycentric(p: np.ndarray) -> Tuple[float, float, float]:
    x, y = p
    a3 = y * 2 / SQRT3
    a2 = x - a3 * 0.5
    a1 = 1 - a2 - a3
    return (a1, a2, a3)

def _valid_barycentric(b: Tuple[float, float, float]) -> bool:
    a1, a2, a3 = b
    return a1 >= 0 and a2 >= 0 and a3 >= 0 and abs(a1 + a2 + a3 - 1) < 1e-8

def _initial_configuration(n_pts: int = 11) -> np.ndarray:
    pts = []
    while len(pts) < n_pts:
        b = _random_barycentric()
        p = _barycentric_to_cartesian(b)
        pts.append(p)
    return np.array(pts)

def _optimize(pts: np.ndarray, steps: int, step_size: float) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    n_pts = len(pts)

    for step in range(steps):
        trial = best_pts.copy()
        idx = random.randrange(n_pts)

        current_b = _cartesian_to_barycentric(trial[idx])
        new_b = (
            max(0.01, min(0.99, current_b[0] + random.uniform(-step_size, step_size))),
            max(0.01, min(0.99, current_b[1] + random.uniform(-step_size, step_size))),
            max(0.01, min(0.99, current_b[2] + random.uniform(-step_size, step_size)))
        )
        s = sum(new_b)
        new_b = (new_b[0]/s, new_b[1]/s, new_b[2]/s)
        if _valid_barycentric(new_b):
            trial[idx] = _barycentric_to_cartesian(new_b)

        trial_val = _min_triangle_area(trial)

        if trial_val > best_val:
            best_val = trial_val
            best_pts = trial.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    pts = _initial_configuration(11)

    pts = _optimize(pts, steps=3000, step_size=0.1)
    pts = _optimize(pts, steps=3000, step_size=0.05)
    pts = _optimize(pts, steps=3000, step_size=0.02)
    pts = _optimize(pts, steps=3000, step_size=0.01)
    pts = _optimize(pts, steps=3000, step_size=0.005)

    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

