import math
import random
import numpy as np
from scipy.spatial import KDTree
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])
TRI_AREA = SQRT3 / 4.0

def _random_point() -> np.ndarray:
    u, v = random.random(), random.random()
    if u + v > 1.0:
        u, v = 1 - u, 1 - v
    return (1 - u - v) * _A + u * _B + v * _C

def _min_triangle_area(pts: np.ndarray) -> float:
    tree = KDTree(pts)
    min_area = float('inf')
    n = len(pts)

    for i in range(n):
        neighbors = tree.query(pts[i], min(7, n))[1][1:]  # Get closest 6 neighbors
        for j in neighbors:
            if j <= i:
                continue
            for k in neighbors:
                if k <= j:
                    continue
                area = 0.5 * abs((pts[j,0]-pts[i,0])*(pts[k,1]-pts[i,1]) - (pts[k,0]-pts[i,0])*(pts[j,1]-pts[i,1]))
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0
    return min_area / TRI_AREA

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    if u >= 0 and v >= 0 and (u + v) <= 1:
        return p
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _initialize_points(n: int = 11) -> np.ndarray:
    # Start with hexagonal grid pattern
    pts = []
    grid_size = int(math.ceil(math.sqrt(n / 0.866)))  # 0.866 = sin(60°)

    for i in range(grid_size):
        for j in range(grid_size):
            x = (i + 0.5 * (j % 2)) / grid_size
            y = j * SQRT3 / (2 * grid_size)
            if x <= 1.0 and y <= SQRT3/2 and (1-x)*SQRT3/2 >= y:
                pts.append([x, y])

    if len(pts) < n:
        pts.extend([_random_point() for _ in range(n - len(pts))])
    else:
        pts = random.sample(pts, n)

    return np.array(pts)

def _optimize_points(pts: np.ndarray, max_iter: int = 1000) -> np.ndarray:
    n = len(pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    step_size = 0.05

    for _ in range(max_iter):
        improved = False
        for i in range(n):
            original = pts[i].copy()
            for _ in range(5):
                angle = random.uniform(0, 2*math.pi)
                direction = np.array([math.cos(angle), math.sin(angle)])
                trial = pts.copy()
                trial[i] = original + step_size * direction
                trial[i] = _project_to_simplex(trial[i])

                # Check minimum distance
                min_dist = min(np.linalg.norm(trial[i] - trial[j]) for j in range(n) if j != i)
                if min_dist < 0.1:
                    continue

                trial_val = _min_triangle_area(trial)
                if trial_val > best_val:
                    pts = trial
                    best_val = trial_val
                    best_pts = trial.copy()
                    improved = True
                    break

        if not improved:
            step_size *= 0.8
            if step_size < 1e-4:
                break

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _initialize_points(11)
    pts = _optimize_points(pts, 1500)
    return [(float(x), float(y)) for x, y in pts]

