import time
import numpy as np
from scipy.optimize import minimize

SQRT3 = math.sqrt(3.0)
_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])
_TRIANGLE_AREA = SQRT3 / 4.0

def _is_inside_triangle(p: np.ndarray) -> bool:
    v0 = _C - _A
    v1 = _B - _A
    v2 = p - _A
    dot00 = np.dot(v0, v0)
    dot01 = np.dot(v0, v1)
    dot02 = np.dot(v0, v2)
    dot11 = np.dot(v1, v1)
    dot12 = np.dot(v1, v2)
    inv_denom = 1.0 / (dot00 * dot11 - dot01 * dot01)
    u = (dot11 * dot02 - dot01 * dot12) * inv_denom
    v = (dot00 * dot12 - dot01 * dot02) * inv_denom
    return (u >= 0) and (v >= 0) and (u + v <= 1)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5 / _TRIANGLE_AREA

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n-2):
        for j in range(i+1, n-1):
            p = pts[i]
            q = pts[j]
            for k in range(j+1, n):
                r = pts[k]
                a = abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / (2 * _TRIANGLE_AREA)
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

def _random_point_inside() -> np.ndarray:
    while True:
        x = random.uniform(0, 1)
        y = random.uniform(0, SQRT3/2)
        if y <= SQRT3 * min(x, 1 - x):
            return np.array([x, y])

def _initial_configuration(n_pts: int = 11) -> np.ndarray:
    pts = []
    # Improved hexagonal pattern with center point
    for i in range(3):
        for j in range(3):
            if i + j <= 3:
                x = 0.15 + 0.25 * i - 0.125 * j
                y = 0.125 * SQRT3 * j
                pts.append(np.array([x, y]))
    pts.append(np.array([0.5, SQRT3/6]))  # Center point
    while len(pts) < n_pts:
        pts.append(_random_point_inside())
    return np.array(pts[:n_pts])

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    x, y = p
    if y < 0:
        y = 0
    if y > SQRT3/2:
        y = SQRT3/2
    if x < 0:
        x = 0
    if x > 1:
        x = 1
    if y > SQRT3 * x:
        y = SQRT3 * x
    if y > SQRT3 * (1 - x):
        y = SQRT3 * (1 - x)
    return np.array([x, y])

def _anneal(n_pts: int = 11, iters: int = 5000, seed: int | None = None) -> np.ndarray:
    rng = random.Random(seed)
    pts = _initial_configuration(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        T = 0.2 * (1e-5 / 0.2) ** (t / (iters - 1))
        idx = rng.randrange(n_pts)
        trial = pts.copy()
        step = 0.08 * (1 - t/iters)**2
        trial[idx] += rng.uniform(-step, step), rng.uniform(-step, step)
        trial[idx] = _project_to_triangle(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or rng.random() < math.exp(delta / max(T, 1e-12)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

        if t % 200 == 0 and t > 0:
            for _ in range(5):
                idx = rng.randrange(n_pts)
                trial = best_pts.copy()
                trial[idx] += rng.uniform(-0.03, 0.03), rng.uniform(-0.03, 0.03)
                trial[idx] = _project_to_triangle(trial[idx])
                trial_val = _min_triangle_area(trial)
                if trial_val > best_val:
                    best_val = trial_val
                    best_pts = trial.copy()

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    start_time = time.time()
    pts = _anneal(n_pts=11, iters=5000, seed=seed)

    if time.time() - start_time < 25:
        n_pts = len(pts)
        x0 = pts.ravel()
        def f(x: np.ndarray) -> float:
            P = x.reshape((-1, 2))
            return -_min_triangle_area(P)
        res = minimize(f, x0, method="Nelder-Mead", options=dict(maxiter=500))
        if res is not None and res.success:
            pts = res.x.reshape((n_pts, 2))
            for i in range(n_pts):
                pts[i] = _project_to_triangle(pts[i])
        if time.time() - start_time < 25:
            res = minimize(f, pts.ravel(), method="Powell", options=dict(maxiter=200))
            if res is not None and res.success:
                pts = res.x.reshape((n_pts, 2))
                for i in range(n_pts):
                    pts[i] = _project_to_triangle(pts[i])

    return [(float(x), float(y)) for x, y in pts]

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area_exact(pts: np.ndarray) -> float:
    min_area = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0.0
    return min_area

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    u, v = random.random(), random.random()
    if u + v > 1.0:
        u, v = 1 - u, 1 - v
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _initial_configuration() -> np.ndarray:
    pts = []
    # Generate points within the triangle using barycentric coordinates
    for _ in range(10):
        pts.append(_random_point())
    # Add center point
    pts.append(np.array([0.5, SQRT3/6]))
    return np.array(pts[:11])

def _optimize_step(pts: np.ndarray, step_size: float) -> np.ndarray:
    n = len(pts)
    best_pts = pts.copy()
    best_min = _min_triangle_area_exact(best_pts)

    for i in range(n):
        for _ in range(4):
            direction = np.random.normal(size=2)
            direction /= np.linalg.norm(direction)
            trial = pts.copy()
            trial[i] = _project_to_triangle(trial[i] + step_size * direction)
            trial_min = _min_triangle_area_exact(trial)

            if trial_min > best_min:
                best_min = trial_min
                best_pts = trial.copy()

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)

    pts = _initial_configuration()
    current_min = _min_triangle_area_exact(pts)

    for step_size in [0.05, 0.02, 0.01, 0.005]:
        for _ in range(30):
            new_pts = _optimize_step(pts, step_size)
            new_min = _min_triangle_area_exact(new_pts)
            if new_min > current_min:
                pts = new_pts
                current_min = new_min

    final_min = _min_triangle_area_exact(pts) / TRIANGLE_AREA
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

import math
import random
import numpy as np
from itertools import combinations
from functools import lru_cache

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / 2.0

def _min_triangle_area(pts):
    min_area = float('inf')
    for i in range(len(pts)):
        for j in range(i+1, len(pts)):
            for k in range(j+1, len(pts)):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area < 1e-8:
                        return min_area
    return min_area

def _is_in_triangle(p):
    x, y = p
    if x < 0 or x > 1 or y < 0 or y > SQRT3/2:
        return False
    if y > SQRT3 * x:
        return False
    if y > SQRT3 * (1 - x):
        return False
    return True

def _generate_hexagonal_points(n):
    points = []
    layers = 3
    for i in range(layers):
        for j in range(layers - i):
            x = 0.1 + 0.4 * i + 0.2 * j
            y = SQRT3 * 0.2 * i
            if _is_in_triangle((x, y)):
                points.append([x, y])
            x_mirror = 1.0 - x
            if _is_in_triangle((x_mirror, y)) and i > 0:
                points.append([x_mirror, y])

    # Add center points
    center_points = [
        [0.5, 0.3],
        [0.3, 0.15],
        [0.7, 0.15],
        [0.4, 0.45],
        [0.6, 0.45],
        [0.5, 0.6]
    ]
    for p in center_points:
        if _is_in_triangle(p):
            points.append(p)

    # Add boundary points if needed
    boundary_points = [
        [0.05, 0.05],
        [0.95, 0.05],
        [0.5, 0.85]
    ]
    for p in boundary_points:
        if len(points) < n and _is_in_triangle(p):
            points.append(p)

    while len(points) < n:
        x = random.uniform(0.1, 0.9)
        y = random.uniform(0.05, 0.8)
        if _is_in_triangle((x, y)):
            points.append([x, y])

    return np.array(points[:n])

def _compute_gradient(points, idx):
    eps = 1e-6
    original_area = _min_triangle_area(points)
    grad = np.zeros(2)

    for dim in range(2):
        points[idx, dim] += eps
        new_area = _min_triangle_area(points)
        grad[dim] = (new_area - original_area) / eps
        points[idx, dim] -= eps

    return grad

def _optimize_sa(points, iterations):
    best_points = points.copy()
    best_score = _min_triangle_area(best_points)
    current_points = points.copy()
    current_score = best_score

    temp = 0.1
    cooling_rate = 0.999

    for i in range(iterations):
        new_points = current_points.copy()
        idx = np.random.randint(len(points))
        step = 0.02 * (1 - i/iterations)

        perturbation = np.random.uniform(-step, step, 2)
        new_points[idx] += perturbation

        if not _is_in_triangle(new_points[idx]):
            new_points[idx] -= perturbation
            continue

        new_score = _min_triangle_area(new_points)

        if new_score > current_score or np.random.rand() < math.exp((new_score - current_score)/temp):
            current_score = new_score
            current_points = new_points.copy()

            if current_score > best_score:
                best_score = current_score
                best_points = current_points.copy()

        temp *= cooling_rate

    return best_points

def _optimize_gradient(points, iterations):
    best_points = points.copy()
    best_score = _min_triangle_area(best_points)

    for i in range(iterations):
        new_points = best_points.copy()
        step = 0.01 * (1 - i/iterations)

        for idx in range(len(points)):
            grad = _compute_gradient(new_points, idx)
            new_points[idx] += step * grad

            if not _is_in_triangle(new_points[idx]):
                new_points[idx] -= step * grad

        new_score = _min_triangle_area(new_points)

        if new_score > best_score:
            best_score = new_score
            best_points = new_points.copy()

    return best_points

def find_points(seed=None):
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    points = _generate_hexagonal_points(11)
    points = _optimize_sa(points, 2000)
    points = _optimize_gradient(points, 1000)

    return [(float(p[0]), float(p[1])) for p in points]

import math
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = np.abs(np.cross(pts[j]-pts[i], pts[k]-pts[i])) * 0.5
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

def _hex_grid(n: int) -> np.ndarray:
    if n == 1:
        return np.array([[0.5, SQRT3/6]])

    layers = math.ceil((math.sqrt(4*(n-1)/3 + 1) - 1)/2
    pts = []
    for layer in range(int(layers)+1):
        for i in range(layer+1):
            j = layer - i
            x = (i + 0.5*j)/layers
            y = j*SQRT3/2/layers
            pts.append([x, y])
    pts = np.array(pts[:n])
    return (1 - pts[:,0] - pts[:,1]/SQRT3*2)[:,None] * _A + pts[:,0][:,None] * _B + (pts[:,1]/SQRT3*2)[:,None] * _C

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = np.clip(uv, 0, 1)
    if u + v > 1:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _diff_evolution(n_pts: int = 11, max_iter: int = 500, seed: int = None) -> np.ndarray:
    np.random.seed(seed)
    pop_size = 20
    F = 0.8
    CR = 0.9

    # Initialize population with hex grid plus perturbations
    pop = []
    for _ in range(pop_size):
        pts = _hex_grid(n_pts)
        pts += np.random.uniform(-0.05, 0.05, (n_pts, 2))
        for i in range(n_pts):
            pts[i] = _project_to_triangle(pts[i])
        pop.append(pts)

    fitness = [_min_triangle_area(p) for p in pop]
    best_idx = np.argmax(fitness)
    best_pts = pop[best_idx].copy()
    best_val = fitness[best_idx]

    for _ in range(max_iter):
        for i in range(pop_size):
            # Mutation
            idxs = [idx for idx in range(pop_size) if idx != i]
            a, b, c = pop[np.random.choice(idxs, 3, replace=False)]
            mutant = a + F * (b - c)

            # Crossover
            trial = pop[i].copy()
            for j in range(n_pts):
                if np.random.rand() < CR:
                    trial[j] = mutant[j]
                    trial[j] = _project_to_triangle(trial[j])

            # Selection
            trial_val = _min_triangle_area(trial)
            if trial_val > fitness[i]:
                pop[i] = trial
                fitness[i] = trial_val
                if trial_val > best_val:
                    best_val = trial_val
                    best_pts = trial.copy()

        # Periodic perturbation
        if _ % 50 == 0:
            for i in range(pop_size):
                if i != best_idx:
                    pop[i] = best_pts.copy()
                    pop[i] += np.random.uniform(-0.02, 0.02, (n_pts, 2))
                    for j in range(n_pts):
                        pop[i][j] = _project_to_triangle(pop[i][j])
                    fitness[i] = _min_triangle_area(pop[i])

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    pts = _diff_evolution(n_pts=11, max_iter=500, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

from __future__ import annotations

import math
import random
import numpy as np

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    best = float("inf")
    n = len(pts)
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _is_in_triangle(p: np.ndarray) -> bool:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    return u >= 0 and v >= 0 and (u + v) <= 1.0

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        total = u + v
        u /= total
        v /= total
    return (1 - u - v) * _A + u * _B + v * _C

def _initial_configuration(n_pts: int = 11) -> np.ndarray:
    pts = []
    layers = 4
    for layer in range(layers):
        for i in range(layer + 1):
            u = (i + 0.5 * (layer % 2)) / (layers - 0.5)
            v = (layer - i + 0.5 * (layer % 2)) / (2 * layers)
            pts.append((1 - u - v) * _A + u * _B + v * _C)
    while len(pts) < n_pts:
        pts.append(_random_point())
    return np.array(pts[:n_pts])

def _differential_evolution(n_pts: int = 11,
                          max_iter: int = 800,
                          F: float = 0.7,
                          CR: float = 0.8,
                          seed: int | None = 0) -> np.ndarray:
    random.seed(seed)
    population = [_initial_configuration(n_pts) for _ in range(8)]
    best_pts = max(population, key=lambda x: _min_triangle_area(x))
    best_val = _min_triangle_area(best_pts)

    for _ in range(max_iter):
        for i in range(len(population)):
            a, b, c = random.sample(range(len(population)), 3)
            mutant = population[a].copy()
            for j in range(n_pts):
                if random.random() < CR:
                    mutant[j] = population[a][j] + F * (population[b][j] - population[c][j])
                    mutant[j] = _project_to_simplex(mutant[j])
            if all(_is_in_triangle(p) for p in mutant):
                trial_val = _min_triangle_area(mutant)
                if trial_val > _min_triangle_area(population[i]):
                    population[i] = mutant
                    if trial_val > best_val:
                        best_val = trial_val
                        best_pts = mutant.copy()
    return best_pts

def _local_search(pts: np.ndarray, steps: int = 150) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    n_pts = len(pts)
    for step_num in range(steps):
        trial = best_pts.copy()
        idx = random.randrange(n_pts)
        step = 0.01 * (1 - step_num/steps)
        trial[idx] += random.uniform(-step, step), random.uniform(-step, step)
        trial[idx] = _project_to_simplex(trial[idx])
        if _is_in_triangle(trial[idx]):
            trial_val = _min_triangle_area(trial)
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()
    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _differential_evolution(n_pts=11, max_iter=800, seed=seed)
    pts = _local_search(pts, steps=150)
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

import math
import random
import numpy as np
from scipy.spatial import Delaunay
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    tri = Delaunay(pts)
    simplices = tri.simplices
    best = float("inf")
    for simplex in simplices:
        a = _area(pts[simplex[0]], pts[simplex[1]], pts[simplex[2]])
        if a < best:
            best = a
    return best

def _is_inside_triangle(p: np.ndarray) -> bool:
    x, y = p
    if y < 0 or y > SQRT3/2:
        return False
    if x < 0 or x > 1:
        return False
    if y > SQRT3 * x:
        return False
    if y > SQRT3 * (1 - x):
        return False
    return True

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    x, y = p
    if _is_inside_triangle(p):
        return p

    # Project to closest edge
    # Edge 1: y = 0
    d1 = y
    # Edge 2: y = sqrt(3)*x
    d2 = abs(SQRT3 * x - y) / 2
    # Edge 3: y = sqrt(3)*(1-x)
    d3 = abs(SQRT3 * (1 - x) - y) / 2

    min_dist = min(d1, d2, d3)
    if min_dist == d1:
        return np.array([max(0, min(1, x)), 0.0])
    elif min_dist == d2:
        x_proj = (x + SQRT3 * y) / 4
        y_proj = SQRT3 * x_proj
        return np.array([x_proj, y_proj])
    else:
        x_proj = (4 - x + SQRT3 * y) / 4
        y_proj = SQRT3 * (1 - x_proj)
        return np.array([x_proj, y_proj])

def _generate_initial_points(n: int) -> np.ndarray:
    pts = []
    layers = int(math.sqrt(n)) + 2
    for layer in range(layers):
        for i in range(layer + 1):
            x = 0.5 * i / layers
            y = (layer - i) * SQRT3 / (2 * layers)
            pts.append([x + y / SQRT3, y])
    pts = np.array(pts)
    inside_mask = np.array([_is_inside_triangle(p) for p in pts])
    pts = pts[inside_mask]
    if len(pts) > n:
        pts = pts[:n]
    else:
        while len(pts) < n:
            new_pt = np.random.uniform(0, 1, 2)
            if _is_inside_triangle(new_pt):
                pts = np.vstack([pts, new_pt])
    return pts

def _optimize(n_pts: int = 11, max_iter: int = 5000, seed: int | None = None) -> np.ndarray:
    if seed is not None:
        np.random.seed(seed)
        random.seed(seed)

    pts = _generate_initial_points(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    temp = 0.1
    cooling_rate = 0.999

    for t in range(max_iter):
        temp *= cooling_rate
        idx = random.randint(0, n_pts - 1)
        trial = pts.copy()
        step = temp * 0.1
        trial[idx] += np.random.uniform(-step, step, 2)
        trial[idx] = _project_to_triangle(trial[idx])

        trial_val = _min_triangle_area(trial)

        if trial_val > best_val or (temp > 0 and random.random() < math.exp((trial_val - best_val)/temp)):
            best_val = trial_val
            best_pts = trial.copy()
            pts = trial

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    pts = _optimize(n_pts=11, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

import math
import random
import numpy as np
from itertools import combinations

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / 2.0

def _min_triangle_area(pts):
    min_area = float('inf')
    for trio in combinations(pts, 3):
        a = _area(*trio)
        if a < min_area:
            min_area = a
            if min_area < 1e-8:
                return min_area
    return min_area

def _is_in_triangle(p):
    x, y = p
    if x < 0 or x > 1 or y < 0 or y > SQRT3/2:
        return False
    if y > SQRT3 * x:
        return False
    if y > SQRT3 * (1 - x):
        return False
    return True

def _generate_initial_points(n):
    # Improved initial configuration with better spacing
    points = []
    # Add vertices first
    points.extend([[0.0, 0.0], [1.0, 0.0], [0.5, SQRT3/2]])

    # Add points along edges
    edge_pts = 3
    for i in range(1, edge_pts):
        t = i / edge_pts
        points.append([t, 0])
        points.append([0.5 + t/2, t * SQRT3/2])
        points.append([0.5 - t/2, t * SQRT3/2])

    # Add interior points in a hexagonal pattern
    interior_pts = n - len(points)
    size = int(np.ceil(np.sqrt(interior_pts * 2)))
    for i in range(size):
        for j in range(size):
            if len(points) >= n:
                break
            x = 0.2 + 0.6 * i/(size-1)
            y = (SQRT3/2 * 0.6) * j/(size-1)
            if j % 2 == 1:
                x += 0.3/(size-1)
            if _is_in_triangle((x, y)):
                points.append([x, y])

    # Fill remaining points with better distribution
    while len(points) < n:
        x = random.uniform(0.1, 0.9)
        y = random.uniform(0.1, 0.8 * SQRT3/2)
        if _is_in_triangle((x, y)):
            points.append([x, y])
    return np.array(points)

def _optimize_points(points, iterations):
    best_points = points.copy()
    best_score = _min_triangle_area(best_points)

    for i in range(iterations):
        new_points = best_points.copy()

        # Adaptive step size based on iteration and local density
        step = 0.02 * (1 - i/iterations)**0.5

        # Focus on worst points first
        if i % 3 == 0:
            # Find point involved in smallest triangle
            min_area = float('inf')
            worst_idx = 0
            for idx in range(len(points)):
                for trio in combinations([i for i in range(len(points)) if i != idx], 2):
                    a = _area(points[idx], points[trio[0]], points[trio[1]])
                    if a < min_area:
                        min_area = a
                        worst_idx = idx

            # Perturb worst point more aggressively
            new_points[worst_idx] += np.random.uniform(-step*2, step*2, 2)
            if not _is_in_triangle(new_points[worst_idx]):
                new_points[worst_idx] = best_points[worst_idx].copy()
        else:
            # Normal perturbation
            idx = i % len(points)
            new_points[idx] += np.random.uniform(-step, step, 2)
            if not _is_in_triangle(new_points[idx]):
                new_points[idx] = best_points[idx].copy()

        new_score = _min_triangle_area(new_points)

        if new_score > best_score:
            best_score = new_score
            best_points = new_points.copy()

    return best_points

def find_points(seed=None):
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    points = _generate_initial_points(11)
    points = _optimize_points(points, 5000)

    return [(float(p[0]), float(p[1])) for p in points]

