import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])
TRI_AREA = 0.5 * 1 * (SQRT3 / 2)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

def _generate_initial_points(n: int) -> np.ndarray:
    pts = []
    grid_size = math.ceil(math.sqrt(n * 2 / SQRT3))
    for i in range(grid_size):
        for j in range(grid_size):
            x = (i + 0.5 * (j % 2)) / grid_size
            y = (j * SQRT3 / 2) / grid_size
            if y <= SQRT3 * x and y <= SQRT3 * (1 - x):
                pts.append([x, y])
    if len(pts) < n:
        while len(pts) < n:
            x = random.uniform(0, 1)
            y = random.uniform(0, SQRT3/2)
            if y <= SQRT3 * x and y <= SQRT3 * (1 - x):
                pts.append([x, y])
    return np.array(pts[:n])

def _differential_evolution(n_pts: int, max_iter: int) -> np.ndarray:
    pop_size = 15
    F = 0.7
    CR = 0.9

    def evaluate(x):
        return _min_triangle_area(x.reshape(-1, 2))

    pop = [_generate_initial_points(n_pts).flatten() for _ in range(pop_size)]
    pop = np.array(pop)
    fitness = np.array([evaluate(ind) for ind in pop])
    best_idx = np.argmax(fitness)
    best = pop[best_idx].copy()
    best_fitness = fitness[best_idx]

    for _ in range(max_iter):
        for i in range(pop_size):
            idxs = [idx for idx in range(pop_size) if idx != i]
            a, b, c = pop[np.random.choice(idxs, 3, replace=False)]
            mutant = a + F * (b - c)

            cross_points = np.random.rand(len(mutant)) < CR
            trial = np.where(cross_points, mutant, pop[i])

            trial_reshaped = trial.reshape(-1, 2)
            for p in trial_reshaped:
                u, v = np.linalg.solve(np.column_stack((_B-_A, _C-_A)), p-_A)[0]
