                    p[0] = np.clip(p[0], 0, 1)
                    p[1] = np.clip(p[1], 0, SQRT3/2)

            trial_fitness = evaluate(trial)
            if trial_fitness > fitness[i]:
                pop[i] = trial
                fitness[i] = trial_fitness
                if trial_fitness > best_fitness:
                    best_fitness = trial_fitness
                    best = trial.copy()
    return best.reshape(-1, 2)

def _local_search(pts: np.ndarray, steps: int) -> np.ndarray:
    current = pts.copy()
    current_fitness = _min_triangle_area(current)

    for step in range(steps):
        step_size = 0.02 * (1 - step/steps)
        improved = False

        for i in range(len(current)):
            for _ in range(5):
                trial = current.copy()
                delta = np.random.uniform(-step_size, step_size, 2)
                trial[i] += delta

                u, v = np.linalg.solve(np.column_stack((_B-_A, _C-_A)), trial[i]-_A)[0]
                if u < -1e-8 or v < -1e-8 or (1-u-v) < -1e-8:
                    continue

                trial_fitness = _min_triangle_area(trial)
                if trial_fitness > current_fitness:
                    current = trial
                    current_fitness = trial_fitness
                    improved = True
                    break

            if improved:
                break
    return current

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    pts = _differential_evolution(11, 30)
    pts = _local_search(pts, 100)

    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

