import math
import random
import itertools
from typing import List, Tuple
import time
import numpy as np
from scipy.optimize import differential_evolution, minimize

SQRT3 = math.sqrt(3.0)
_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])
_TRIANGLE_AREA = SQRT3 / 4.0

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5 / _TRIANGLE_AREA

def _min_triangle_area(pts: np.ndarray) -> float:
    min_area = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _hexagonal_grid(n: int) -> np.ndarray:
    pts = []
    k = int(math.sqrt(n)) + 1
    for i in range(k):
        for j in range(k):
            if len(pts) >= n:
                break
            x = (i + 0.5 * (j % 2)) / k
            y = (j * SQRT3 / 2) / k
            if x + y / SQRT3 <= 1.0 and y <= SQRT3 / 2:
                pts.append([x, y])
    return np.array(pts[:n])

def _optimize(pts: np.ndarray, time_limit: float) -> np.ndarray:
    start_time = time.time()
    n_pts = len(pts)
    x0 = pts.ravel()

    def f(x: np.ndarray) -> float:
        P = x.reshape((-1, 2))
        return -_min_triangle_area(P)

    bounds = [(0.0, 1.0) if i % 2 == 0 else (0.0, SQRT3 / 2) for i in range(2 * n_pts)]
    res = differential_evolution(f, bounds, maxiter=100, popsize=15, tol=1e-6,
                               updating='deferred', workers=1,
                               polish=False, disp=False)
    if res.success:
        pts = res.x.reshape((n_pts, 2))

    if time.time() - start_time < time_limit - 5:
        res = minimize(f, pts.ravel(), method='L-BFGS-B', bounds=bounds,
                       options=dict(maxiter=100))
        if res.success:
            pts = res.x.reshape((n_pts, 2))

    for i in range(n_pts):
        pts[i] = _project_to_simplex(pts[i])

    return pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    np.random.seed(seed)
    random.seed(seed)
    start_time = time.time()

    pts = _hexagonal_grid(11)
    pts = _optimize(pts, 25)

    return [(float(x), float(y)) for x, y in pts]

