import math
import random
import numpy as np
from typing import List, Tuple
from scipy.optimize import differential_evolution, minimize
from scipy.spatial import Delaunay

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    u, v = random.random(), random.random()
    if u + v > 1.0:
        u, v = 1 - u, 1 - v
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = 1 - v, 1 - u
    return (1 - u - v) * _A + u * _B + v * _C

def _min_triangle_area_fast(pts: np.ndarray) -> float:
    tri = Delaunay(pts)
    min_area = float('inf')

    for simplex in tri.simplices:
        p, q, r = pts[simplex]
        area = abs(np.cross(q - p, r - p)) * 0.5
        if area < min_area:
            min_area = area
            if min_area == 0:
                return 0

    if min_area == float('inf'):
        n = len(pts)
        for i in range(n):
            for j in range(i+1, n):
                for k in range(j+1, n):
                    area = abs(np.cross(pts[j] - pts[i], pts[k] - pts[i])) * 0.5
                    if area < min_area:
                        min_area = area
                        if min_area == 0:
                            return 0
    return min_area

def _hexagonal_init(n: int = 11) -> np.ndarray:
    pts = []
    layers = math.ceil(math.sqrt(n / 3)) + 1
    for i in range(-layers, layers + 1):
        for j in range(-layers, layers + 1):
            x = 0.5 + 0.5 * i + 0.25 * j
            y = SQRT3 * 0.25 * j
            pts.append([x, y])

    pts = np.array(pts)
    inside = []
    for p in pts:
        M = np.column_stack((_B - _A, _C - _A))
        uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
        u, v = uv
        if u >= 0 and v >= 0 and u + v <= 1:
            inside.append(p)

    inside = np.array(inside)
    if len(inside) >= n:
        indices = np.random.choice(len(inside), n, replace=False)
        return inside[indices]
    else:
        return np.array([_random_point() for _ in range(n)])

def optimize_points(pts: np.ndarray, maxiter: int = 1000) -> np.ndarray:
    bounds = [(0, 1), (0, SQRT3/2)] * len(pts)

    def objective(x):
        P = x.reshape((-1, 2))
        for i in range(len(P)):
            P[i] = _project_to_simplex(P[i])
        return -_min_triangle_area_fast(P)

    result = differential_evolution(
        objective,
        bounds,
        strategy='best1bin',
        maxiter=maxiter,
        popsize=15,
        mutation=(0.5, 1.0),
        recombination=0.7,
        tol=1e-6,
        polish=False
    )

    optimized = result.x.reshape((-1, 2))
    for i in range(len(optimized)):
        optimized[i] = _project_to_simplex(optimized[i])

    result_local = minimize(
        objective,
        optimized.ravel(),
        method='L-BFGS-B',
        bounds=bounds,
        options={'maxiter': 500, 'ftol': 1e-8}
    )

    if result_local.success:
        optimized = result_local.x.reshape((-1, 2))
        for i in range(len(optimized)):
            optimized[i] = _project_to_simplex(optimized[i])

    return optimized

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _hexagonal_init(11)
    optimized = optimize_points(pts, maxiter=100)
    return [(float(x), float(y)) for x, y in optimized]

