def _hexagonal_grid(n: int) -> np.ndarray:
    pts = []
    size = int(math.ceil(math.sqrt(n)))
    for i in range(size):
        for j in range(size):
            if len(pts) >= n:
                break
            x = 0.5 + (i - j) * 0.5 / size
            y = j * SQRT3 / 2 / size
            if 0 <= x <= 1 and 0 <= y <= SQRT3/2 and y <= SQRT3*(1 - abs(2*x - 1)) + 1e-10:
                pts.append([x, y])
    while len(pts) < n:
        x = random.uniform(0, 1)
        y_max = SQRT3*(1 - abs(2*x - 1))
        y = random.uniform(0, y_max)
        pts.append([x, y])
    return np.array(pts)

def _optimize_points(pts: np.ndarray, iterations: int = 2000) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)
    n = len(pts)

    for _ in range(iterations):
        new_pts = best_pts.copy()
        idx = random.randint(0, n-1)
        step = 0.05 * (1 - _/iterations)
        new_pts[idx] += np.random.uniform(-step, step, 2)

        x, y = new_pts[idx]
        y_max = SQRT3*(1 - abs(2*x - 1)) + 1e-10
        if not (0 <= x <= 1 and 0 <= y <= y_max):
            continue

        new_area = _min_triangle_area(new_pts)
        if new_area > best_area:
            best_area = new_area
            best_pts = new_pts.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _hexagonal_grid(11)
    pts = _optimize_points(pts, 2000)

    # Strict final boundary check and correction
    for p in pts:
        x, y = p
        y_max = SQRT3*(1 - abs(2*x - 1))
        if y > y_max:
            p[1] = y_max - 1e-10
        if x < 0:
            p[0] = 1e-10
        elif x > 1:
            p[0] = 1 - 1e-10
        if y < 0:
            p[1] = 1e-10

    return [(float(x), float(y)) for x, y in pts]

from __future__ import annotations

import math
import random
import itertools
from typing import List, Tuple, Optional
import numpy as np

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _is_inside_triangle(pt: np.ndarray) -> bool:
    x, y = pt
    return (y > 0 and x > 0 and (x + y/SQRT3) < 1 and 
            (x - y/SQRT3) < 0 and y < SQRT3/2)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5 / TRIANGLE_AREA

class MinAreaTracker:
    def __init__(self, pts: np.ndarray):
        self.pts = pts.copy()
        self.n = len(pts)
        self.triplets = list(itertools.combinations(range(self.n), 3))
        self.point_to_triplets = [[] for _ in range(self.n)]
        for idx_triplet, triplet in enumerate(self.triplets):
            for i in triplet:
                self.point_to_triplets[i].append(idx_triplet)
        self.areas_arr = np.zeros(len(self.triplets))
        for idx_triplet, (i, j, k) in enumerate(self.triplets):
            self.areas_arr[idx_triplet] = _area(pts[i], pts[j], pts[k])
        self.min_area = np.min(self.areas_arr)

    def update_point(self, idx: int, new_pos: np.ndarray) -> bool:
        if not _is_inside_triangle(new_pos):
            return False
        self.pts[idx] = new_pos
        for idx_triplet in self.point_to_triplets[idx]:
            i, j, k = self.triplets[idx_triplet]
            self.areas_arr[idx_triplet] = _area(self.pts[i], self.pts[j], self.pts[k])
        self.min_area = np.min(self.areas_arr)
        return True

    def get_min_area(self) -> float:
        return self.min_area

def _random_barycentric(rng: np.random.Generator) -> Tuple[float, float, float]:
    u, v = rng.random(2)
    if u + v > 1:
        u, v = 1 - u, 1 - v
    return (1 - u - v, u, v)

def _barycentric_to_cartesian(bary: Tuple[float, float, float]) -> np.ndarray:
    a, b, c = bary
    return np.array([0.5 * (b - a) + c * 0.5, c * SQRT3 / 2])

def _initial_configuration(n_pts: int = 11, rng: np.random.Generator = None) -> np.ndarray:
    if rng is None:
        rng = np.random.default_rng()

    pts = []
    # Start with barycentric random points to ensure they're inside
    while len(pts) < n_pts:
        bary = _random_barycentric(rng)
        pt = _barycentric_to_cartesian(bary)
        if _is_inside_triangle(pt):
            pts.append(pt)

    return np.array(pts[:n_pts])

def _optimize(n_pts: int = 11, iters: int = 10000, seed: int | None = None) -> np.ndarray:
    rng = np.random.default_rng(seed)
    pts = _initial_configuration(n_pts, rng)
    tracker = MinAreaTracker(pts)
    best_pts = pts.copy()
    best_val = tracker.get_min_area()

    for t in range(iters):
        T = max(0.01 * (1 - t/iters), 1e-6)
        step_size = 0.02 * (1 - t/iters) + 0.001

        idx = rng.integers(0, n_pts)
        old_pos = pts[idx].copy()

        # Move in barycentric coordinates
        bary = _random_barycentric(rng)
        new_pos = _barycentric_to_cartesian(bary)

        if not tracker.update_point(idx, new_pos):
            continue

        trial_val = tracker.get_min_area()
        delta = trial_val - best_val

        if delta > 0 or rng.random() < math.exp(delta / T):
            pts = tracker.pts.copy()
            if trial_val > best_val:
                best_val = trial_val
                best_pts = pts.copy()
        else:
            tracker.update_point(idx, old_pos)

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    pts = _optimize(n_pts=11, iters=10000, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

from __future__ import annotations

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / (2 * TRIANGLE_AREA)

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n-2):
        for j in range(i+1, n-1):
            p0 = pts[j] - pts[i]
            for k in range(j+1, n):
                p1 = pts[k] - pts[i]
                area = abs(p0[0]*p1[1] - p0[1]*p1[0]) / (2 * TRIANGLE_AREA)
                if area < min_area:
                    min_area = area
                    if min_area < 1e-8:  # Early termination for degenerate cases
                        return 0
    return min_area

def _random_point_in_triangle() -> np.ndarray:
    while True:
        r1 = random.random()
        r2 = random.random()
        if r1 + r2 <= 1:
            break
    x = r1 * 1.0 + r2 * 0.5
    y = r2 * SQRT3 / 2.0
    return np.array([x, y])

def _initialize_points(n_pts: int) -> np.ndarray:
    pts = []
    for _ in range(n_pts):
        pts.append(_random_point_in_triangle())
    return np.array(pts)

def _is_in_triangle(p: np.ndarray) -> bool:
    x, y = p
    if y < 0 or y > SQRT3/2:
        return False
    if x < 0 or x > 1:
        return False
    if y > SQRT3 * x or y > SQRT3 * (1 - x):
        return False
    return True

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    x, y = p
    if _is_in_triangle(p):
        return p

    if y < 0:
        x = max(0, min(1, x))
        return np.array([x, 0])

    if y > SQRT3 * x:
        if x < 0:
            return np.array([0, 0])
        x_proj = y / SQRT3
        return np.array([x_proj, y])

    if y > SQRT3 * (1 - x):
        if x > 1:
            return np.array([1, 0])
        x_proj = 1 - y / SQRT3
        return np.array([x_proj, y])

    d0 = x**2 + y**2
    d1 = (x-1)**2 + y**2
    d2 = (x-0.5)**2 + (y-SQRT3/2)**2

    if d0 <= d1 and d0 <= d2:
        return np.array([0, 0])
    elif d1 <= d0 and d1 <= d2:
        return np.array([1, 0])
    else:
        return np.array([0.5, SQRT3/2])

def _anneal(n_pts: int = 11,
            iters: int = 50000,
            start_temp: float = 0.5,
            end_temp: float = 1e-8,
            step_size: float = 0.1,
            seed: int | None = None) -> np.ndarray:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _initialize_points(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        T = start_temp * (1 - (t/iters)**2)  # Quadratic cooling
        current_step = step_size * (1 - (t/iters)**0.5)  # Slower step reduction

        trial = pts.copy()
        if random.random() < 0.1:  # 10% chance for multi-point perturbation
            for _ in range(1 + int(3*random.random())):
                idx = random.randrange(n_pts)
                delta = np.random.normal(0, current_step, size=2)
                trial[idx] = _project_to_triangle(trial[idx] + delta)
        else:
            idx = random.randrange(n_pts)
            if random.random() < 0.05:  # 5% chance for large jump
                trial[idx] = _random_point_in_triangle()
            else:
                delta = np.random.normal(0, current_step, size=2)
                trial[idx] = _project_to_triangle(trial[idx] + delta)

        trial_val = _min_triangle_area(trial)
        delta_val = trial_val - best_val

        if delta_val > 0 or math.exp(delta_val / max(T, 1e-12)) > random.random():
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

