import math
import random
import numpy as np
from typing import List, Tuple
from scipy.spatial import KDTree

SQRT3 = math.sqrt(3.0)

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    u, v = random.random(), random.random()
    if u + v > 1.0:
        u, v = 1 - u, 1 - v
    return (1 - u - v) * _A + u * _B + v * _C

def _hexagonal_lattice(n: int) -> np.ndarray:
    k = int(math.sqrt(2 * n)) + 1
    pts = []
    for i in range(k):
        for j in range(k):
            x = (i + 0.5 * (j % 2)) / (k - 1)
            y = (SQRT3 / 2 * j) / (k - 1)
            if (1 - x - y / SQRT3) >= 0 and x >= 0 and y >= 0:
                pts.append(np.array([x, y]))
    if len(pts) < n:
        pts.extend([_random_point() for _ in range(n - len(pts))])
    return np.array(pts[:n])

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = 1 - u, 1 - v
    return (1 - u - v) * _A + u * _B + v * _C

def _min_triangle_area(pts: np.ndarray) -> float:
    tree = KDTree(pts)
    min_area = float('inf')
    for i in range(len(pts)):
        neighbors = tree.query_ball_point(pts[i], 0.25)
        for j in neighbors:
            if j <= i:
                continue
            for k in neighbors:
                if k <= j:
                    continue
                a = pts[j] - pts[i]
                b = pts[k] - pts[i]
                cross = abs(a[0]*b[1] - a[1]*b[0])
                if cross < min_area:
                    min_area = cross
                    if min_area == 0:
                        return 0.0
    return min_area * 0.5

def _optimize(n_pts: int = 11, iters: int = 10000, seed: int | None = None) -> np.ndarray:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    best_pts = _hexagonal_lattice(n_pts)
    best_val = _min_triangle_area(best_pts)

    for restart in range(3):
        pts = _hexagonal_lattice(n_pts)
        current_val = _min_triangle_area(pts)
        step_size = 0.1

        for t in range(iters):
            T = max(1e-12, 0.5 * (1 - t / iters) ** 1.5)

            if t > 0 and t % 200 == 0:
                step_size = max(0.005, min(0.15, step_size * (0.9 + random.random() * 0.2)))

            idx = random.randrange(n_pts)
            trial = pts.copy()
            trial[idx] += np.random.normal(0, step_size, 2)
            trial[idx] = _project_to_simplex(trial[idx])

            trial_val = _min_triangle_area(trial)
            delta = trial_val - current_val

            if delta > 0 or random.random() < math.exp(delta / T):
                pts = trial
                current_val = trial_val
                if trial_val > best_val:
                    best_val = trial_val
                    best_pts = trial.copy()

        # Gradient-based local search
        local_step = 0.01
        for _ in range(100):
            improved = False
            for idx in range(n_pts):
                for angle in np.linspace(0, 2*np.pi, 12):
                    dx, dy = local_step * math.cos(angle), local_step * math.sin(angle)
                    trial = best_pts.copy()
                    trial[idx] += dx, dy
                    trial[idx] = _project_to_simplex(trial[idx])
                    trial_val = _min_triangle_area(trial)
                    if trial_val > best_val:
                        best_val = trial_val
                        best_pts = trial.copy()
                        improved = True
            if not improved:
                break

        # Perturbation phase
        if restart < 2:
            perturbation = best_pts.copy()
            for idx in range(n_pts):
                perturbation[idx] += np.random.uniform(-0.05, 0.05, 2)
                perturbation[idx] = _project_to_simplex(perturbation[idx])
            perturbation_val = _min_triangle_area(perturbation)
            if perturbation_val > best_val * 0.9:
                best_pts = perturbation
                best_val = perturbation_val

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    pts = _optimize(n_pts=11, iters=8000, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

