import math
import random
import itertools
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p1, p2, p3) -> float:
    return abs((p2[0]-p1[0])*(p3[1]-p1[1]) - (p2[1]-p1[1])*(p3[0]-p1[0])) / (2 * TRIANGLE_AREA)

def _min_triangle_area(pts: np.ndarray) -> float:
    min_area = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

def _is_inside_triangle(p: np.ndarray) -> bool:
    x, y = p
    if y < 0 or y > SQRT3/2:
        return False
    if x < 0 or x > 1:
        return False
    if y > SQRT3 * x:
        return False
    if y > SQRT3 * (1 - x):
        return False
    return True

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    x, y = p
    # Project to the triangle boundaries
    if y < 0:
        y = 0
    if y > SQRT3/2:
        y = SQRT3/2
    if x < 0:
        x = 0
    if x > 1:
        x = 1
    # Check the diagonal boundaries
    if y > SQRT3 * x:
        y = SQRT3 * x
    if y > SQRT3 * (1 - x):
        y = SQRT3 * (1 - x)
    return np.array([x, y])

def _hexagonal_grid(n_pts: int = 11) -> np.ndarray:
    pts = []
    layers = 5
    for layer in range(layers):
        for i in range(layer + 1):
            u = i / layers
            v = (layer - i) / layers
            x = 0.5 * (1 + u - v)
            y = SQRT3/2 * v
            pts.append([x, y])
    return np.array(pts[:n_pts])

def _optimize_configuration(pts: np.ndarray, iterations: int = 3000) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)
    n = len(pts)
    step_size = 0.05

    for _ in range(iterations):
        trial = best_pts.copy()
        for i in range(n):
            if random.random() < 0.5:
                dx = random.uniform(-step_size, step_size)
                dy = random.uniform(-step_size, step_size)
                trial[i] += [dx, dy]
                trial[i] = _project_to_triangle(trial[i])

        current_area = _min_triangle_area(trial)
        if current_area > best_area:
            best_area = current_area
            best_pts = trial.copy()

        step_size *= 0.999

    return best_pts

def _refine_configuration(pts: np.ndarray, iterations: int = 2000) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)
    n = len(pts)

    for _ in range(iterations):
        trial = best_pts.copy()
        for i in range(n):
            dx = random.uniform(-0.01, 0.01)
            dy = random.uniform(-0.01, 0.01)
            trial[i] += [dx, dy]
            trial[i] = _project_to_triangle(trial[i])

        current_area = _min_triangle_area(trial)
        if current_area > best_area:
            best_area = current_area
            best_pts = trial.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    best_pts = None
    best_area = 0.0

    for _ in range(5):
        if best_area < 0.03 or random.random() < 0.5:
            pts = _hexagonal_grid(11)
        else:
            pts = np.array([[random.uniform(0,1), random.uniform(0,SQRT3/2)] for _ in range(11)])
            for i in range(11):
                pts[i] = _project_to_triangle(pts[i])

        pts = _optimize_configuration(pts, 3000)
        pts = _refine_configuration(pts, 2000)

        current_area = _min_triangle_area(pts)
        if current_area > best_area:
            best_area = current_area
            best_pts = pts.copy()

    return [(float(x), float(y)) for x, y in best_pts]

import math
import random
import numpy as np
from itertools import combinations

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / 2.0

def _min_triangle_area(pts):
    min_area = float('inf')
    for trio in combinations(pts, 3):
        a = _area(*trio)
        if a < min_area:
            min_area = a
            if min_area < 1e-8:
                return min_area
    return min_area

def _is_in_triangle(p, margin=0.001):
    x, y = p
    if x < margin or x > 1-margin or y < margin or y > (SQRT3/2)-margin:
        return False
    if y > SQRT3 * x - margin:
        return False
    if y > SQRT3 * (1 - x) - margin:
        return False
    return True

def _generate_initial_points(n):
    points = []
    points.extend([[0.0, 0.0], [1.0, 0.0], [0.5, SQRT3/2]])

    edge_pts = 2
    for i in range(1, edge_pts+1):
        t = i / (edge_pts+1)
        points.append([t, 0])
        points.append([0.5 + t/2 - 0.05, t * SQRT3/2 - 0.02])
        points.append([0.5 - t/2 + 0.05, t * SQRT3/2 - 0.02])

    interior_pts = n - len(points)
    size = int(np.ceil(np.sqrt(interior_pts * 2)))
    for i in range(size):
        for j in range(size):
            if len(points) >= n:
                break
            x = 0.2 + 0.6 * i/(size-1)
            y = (SQRT3/2 * 0.6) * j/(size-1)
            if j % 2 == 1:
                x += 0.3/(size-1)
            if _is_in_triangle((x, y)):
                points.append([x, y])

    while len(points) < n:
        x = random.uniform(0.15, 0.85)
        y = random.uniform(0.15, 0.7 * SQRT3/2)
        if _is_in_triangle((x, y)):
            points.append([x, y])
    return np.array(points)

def _optimize_points(points, iterations):
    best_points = points.copy()
    best_score = _min_triangle_area(best_points)

    for i in range(iterations):
        new_points = best_points.copy()
        step = 0.01 * (1 - i/iterations)**0.5

        if i % 3 == 0:
            min_area = float('inf')
            worst_idx = 0
            for idx in range(len(points)):
                for trio in combinations([i for i in range(len(points)) if i != idx], 2):
                    a = _area(points[idx], points[trio[0]], points[trio[1]])
                    if a < min_area:
                        min_area = a
                        worst_idx = idx

            for _ in range(10):
                trial_point = best_points[worst_idx].copy() + np.random.uniform(-step*1.5, step*1.5, 2)
                if _is_in_triangle(trial_point):
                    new_points[worst_idx] = trial_point
                    break
        else:
            idx = i % len(points)
            for _ in range(5):
                trial_point = best_points[idx].copy() + np.random.uniform(-step, step, 2)
                if _is_in_triangle(trial_point):
                    new_points[idx] = trial_point
                    break

        new_score = _min_triangle_area(new_points)
        if new_score > best_score:
            best_score = new_score
            best_points = new_points.copy()

    return best_points

def find_points(seed=None):
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    points = _generate_initial_points(11)
    points = _optimize_points(points, 3000)

    return [(float(p[0]), float(p[1])) for p in points]

