import math
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
MARGIN = 1e-8

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area_fast(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

def _generate_hexagonal_grid(n: int) -> np.ndarray:
    pts = []
    layers = math.ceil(math.sqrt(n)) + 2

    for i in range(-layers, layers+1):
        for j in range(-layers, layers+1):
            x = 0.5 + 0.5 * i + 0.5 * j
            y = SQRT3/2 * j
            if (0 <= x <= 1) and (0 <= y <= SQRT3/2) and (y <= SQRT3 * (1 - x)):
                pts.append([x, y])

    pts = np.array(pts)
    if len(pts) < n:
        return _generate_hexagonal_grid(n)

    indices = np.random.choice(len(pts), n, replace=False)
    return pts[indices]

def _optimize_points(pts: np.ndarray, max_iter: int = 200) -> np.ndarray:
    n = len(pts)
    best_pts = pts.copy()
    best_area = _min_triangle_area_fast(pts)

    for _ in range(max_iter):
        improved = False
        for i in range(n):
            grad = np.zeros(2)
            for j in range(n):
                if j == i:
                    continue
                for k in range(j+1, n):
                    if k == i:
                        continue
                    a = _area(pts[i], pts[j], pts[k])
                    if abs(a - best_area) < 1e-8:
                        vec1 = pts[j] - pts[i]
                        vec2 = pts[k] - pts[i]
                        normal = np.array([-vec1[1]-vec2[1], vec1[0]+vec2[0]])
                        grad += normal / (np.linalg.norm(normal) + 1e-8)

            if np.linalg.norm(grad) > 1e-8:
                new_pt = pts[i] + 0.01 * grad / np.linalg.norm(grad)
                new_pt = np.clip(new_pt, [MARGIN, MARGIN], [1-MARGIN, SQRT3/2-MARGIN])
                if (new_pt[1] > SQRT3 * (1 - new_pt[0])):
                    new_pt = np.array([0.5, SQRT3/4])

                temp_pts = pts.copy()
                temp_pts[i] = new_pt
                new_area = _min_triangle_area_fast(temp_pts)
                if new_area > best_area:
                    pts[i] = new_pt
                    best_area = new_area
                    best_pts = pts.copy()
                    improved = True

        if not improved:
            break

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    np.random.seed(seed)
    pts = _generate_hexagonal_grid(11)
    pts = _optimize_points(pts)
    return [(float(x), float(y)) for x, y in pts]

