import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    u, v = random.random(), random.random()
    if u + v > 1.0:
        u, v = 1 - u, 1 - v
    return (1 - u - v) * _A + u * _B + v * _C

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')

    for i in range(n):
        for j in range(i+1, n):
            vec1 = pts[j] - pts[i]
            for k in range(j+1, n):
                vec2 = pts[k] - pts[i]
                area = abs(vec1[0]*vec2[1] - vec1[1]*vec2[0]) * 0.5
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0.0
    return min_area

def _is_in_triangle(pt: np.ndarray) -> bool:
    x, y = pt
    if x < 0 or x > 1 or y < 0 or y > SQRT3/2:
        return False
    if y > SQRT3 * x or y > SQRT3 * (1 - x):
        return False
    return True

def _differential_evolution(n_pts: int = 11,
                          max_iter: int = 1000,
                          pop_size: int = 60,
                          F: float = 0.7,
                          CR: float = 0.8,
                          seed: int | None = 0) -> np.ndarray:

    random.seed(seed)
    np.random.seed(seed)

    def generate_individual():
        return np.array([_random_point() for _ in range(n_pts)])

    population = [generate_individual() for _ in range(pop_size)]
    fitness = [_min_triangle_area(ind) for ind in population]
    best_idx = np.argmax(fitness)
    best_individual = population[best_idx].copy()
    best_fitness = fitness[best_idx]
    no_improve = 0

    for _ in range(max_iter):
        for i in range(pop_size):
            target = population[i]
            a, b, c = random.sample(range(pop_size), 3)
            while a == i or b == i or c == i:
                a, b, c = random.sample(range(pop_size), 3)

            mutant = population[a] + F * (population[b] - population[c])

            trial = target.copy()
            for j in range(n_pts):
                if random.random() < CR:
                    trial[j] = mutant[j]
                    if not _is_in_triangle(trial[j]):
                        trial[j] = _random_point()

            if random.random() < 0.3:
                j = random.randint(0, n_pts-1)
                u, v = random.random()*0.1, random.random()*0.1
                if u + v > 0.1:
                    u, v = 0.1 - u, 0.1 - v
                new_pt = (1 - u - v) * trial[j] + u * _B + v * _C
                if _is_in_triangle(new_pt):
                    trial[j] = new_pt
                else:
                    trial[j] = _random_point()

            trial_fitness = _min_triangle_area(trial)
            if trial_fitness > fitness[i]:
                population[i] = trial
                fitness[i] = trial_fitness
                if trial_fitness > best_fitness:
                    best_fitness = trial_fitness
                    best_individual = trial.copy()
                    no_improve = 0
                else:
                    no_improve += 1

        if best_fitness == 0 or no_improve > 50:
            break

    for _ in range(100):
        trial = best_individual.copy()
        for j in range(n_pts):
            if random.random() < 0.3:
                u, v = random.random()*0.05, random.random()*0.05
                if u + v > 0.05:
                    u, v = 0.05 - u, 0.05 - v
                new_pt = (1 - u - v) * trial[j] + u * _B + v * _C
                if _is_in_triangle(new_pt):
                    trial[j] = new_pt

        trial_fitness = _min_triangle_area(trial)
        if trial_fitness > best_fitness:
            best_fitness = trial_fitness
            best_individual = trial.copy()

    return best_individual

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _differential_evolution(n_pts=11, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

import math
import random
import numpy as np
from itertools import combinations
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRI_AREA = 0.5 * SQRT3 / 2.0

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5 / TRI_AREA

def _min_triangle_area(pts):
    min_area = float('inf')
    n = len(pts)
    for i in range(n-2):
        for j in range(i+1, n-1):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

def _is_in_triangle(p):
    x, y = p
    return (y >= 0) and (x + y/SQRT3 >= 0) and (x - y/SQRT3 <= 0) and (x + y/SQRT3 <= 1)

def _project_to_triangle(p):
    x, y = p
    # Project to bottom boundary
    if y < 0:
        y = 0
    # Project to left boundary
    if x - y/SQRT3 > 0:
        x = y/SQRT3
    # Project to right boundary
    if x + y/SQRT3 > 1:
        x = 1 - y/SQRT3
    return np.array([x, max(0, y)])

def _initialize_points(n):
    # Hexagonal lattice pattern
    points = []
    layers = 3
    for i in range(-layers, layers+1):
        for j in range(-layers, layers+1):
            x = 0.5 + i*0.15 + j*0.075
            y = SQRT3/2 * 0.15 * j
            if _is_in_triangle((x, y)):
                points.append([x, y])

    # Add center point
    points.append([0.5, SQRT3/4])

    # If we have too many points, take the ones closest to center
    if len(points) > n:
        center = np.array([0.5, SQRT3/4])
        points = sorted(points, key=lambda p: np.linalg.norm(np.array(p)-center))[:n]
    # If we need more points, add random ones
    while len(points) < n:
        x = random.uniform(0, 1)
        y = random.uniform(0, SQRT3/2)
        if _is_in_triangle((x, y)):
            points.append([x, y])
    return np.array(points)

def _get_worst_triangle_indices(pts):
    min_area = float('inf')
    worst_indices = None
    n = len(pts)
    for i in range(n-2):
        for j in range(i+1, n-1):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    worst_indices = (i, j, k)
                    if min_area == 0:
                        return worst_indices
    return worst_indices

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    pts = _initialize_points(11)
    best_pts = pts.copy()
    best_area = _min_triangle_area(pts)

    # Optimization loop
    for t in range(1000):
        step = 0.05 * (1 - t/1000)

        # Find worst triangle and perturb its points
        worst_tri = _get_worst_triangle_indices(pts)
        if not worst_tri:
            continue

        i, j, k = worst_tri
        centroid = (pts[i] + pts[j] + pts[k]) / 3

        for idx in [i, j, k]:
            new_pts = pts.copy()
            # Move toward centroid with some randomness
            direction = centroid - pts[idx]
            perturbation = direction * step + np.random.uniform(-step/2, step/2, size=2)
            new_pts[idx] += perturbation
            new_pts[idx] = _project_to_triangle(new_pts[idx])

            if not _is_in_triangle(new_pts[idx]):
                continue

            new_area = _min_triangle_area(new_pts)
            if new_area > best_area:
                best_area = new_area
                best_pts = new_pts.copy()
                pts = new_pts

    return [(float(x), float(y)) for x, y in best_pts]

