import math
import random
import numpy as np
from typing import List, Tuple
from scipy.spatial import Voronoi

SQRT3 = math.sqrt(3.0)

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    u, v = random.random(), random.random()
    if u + v > 1.0:
        u, v = 1 - u, 1 - v
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = 1 - u, 1 - v
    return (1 - u - v) * _A + u * _B + v * _C

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                p, q, r = pts[i], pts[j], pts[k]
                area = abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5
                if area < min_area:
                    min_area = area
                    if min_area < 1e-8:
                        return 0.0
    return min_area

def _initialize_points(n_pts: int) -> np.ndarray:
    # Hexagonal lattice initialization
    pts = []
    k = int(math.sqrt(n_pts)) + 1
    for i in range(k):
        for j in range(k):
            x = 0.5 * j / k
            y = (i + 0.5 * (j % 2)) * SQRT3 / (2 * k)
            if x + y / SQRT3 <= 1.0 and y <= SQRT3 / 2:
                pts.append([x, y])
    if len(pts) < n_pts:
        pts.extend([_random_point() for _ in range(n_pts - len(pts))])
    return np.array(pts[:n_pts])

def _gradient_step(pts: np.ndarray, step_size: float) -> np.ndarray:
    n = len(pts)
    grad = np.zeros_like(pts)
    min_area = _min_triangle_area(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                p, q, r = pts[i], pts[j], pts[k]
                area = abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5
                if abs(area - min_area) < 1e-8:
                    # Approximate gradient contribution
                    grad[i] += (q - p) + (r - p)
                    grad[j] += (p - q) + (r - q)
                    grad[k] += (p - r) + (q - r)
    grad /= np.linalg.norm(grad, axis=1, keepdims=True) + 1e-8
    return pts + step_size * grad

def _voronoi_relaxation(pts: np.ndarray) -> np.ndarray:
    vor = Voronoi(pts)
    new_pts = []
    for i in range(len(pts)):
        region = vor.regions[vor.point_region[i]]
        if -1 not in region and len(region) > 0:
            vertices = np.array([vor.vertices[j] for j in region])
            centroid = np.mean(vertices, axis=0)
            new_pts.append(centroid)
        else:
            new_pts.append(pts[i])
    return np.array(new_pts)

def _optimize(n_pts: int = 11, iters: int = 10000, seed: int | None = 0) -> np.ndarray:
    random.seed(seed)
    pts = _initialize_points(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    step_size = 0.02

    for t in range(iters):
        if t % 10 == 0:
            pts = _voronoi_relaxation(pts)
            current_val = _min_triangle_area(pts)
            if current_val > best_val:
                best_val = current_val
                best_pts = pts.copy()

        pts = _gradient_step(pts, step_size)
        for i in range(n_pts):
            pts[i] = _project_to_simplex(pts[i])

        current_val = _min_triangle_area(pts)
        if current_val > best_val:
            best_val = current_val
            best_pts = pts.copy()

        step_size *= 0.99

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _optimize(n_pts=11, iters=5000, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

