    best = float("inf")
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best < 1e-6:
                        return best
    return best

def _random_point() -> np.ndarray:
    u, v = random.random(), random.random()
    if u + v > 1.0:
        u, v = 1-u, 1-v
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _initial_configuration(n_pts: int) -> np.ndarray:
    pts = []
    layers = int(math.sqrt(n_pts * 2)) + 1
    for i in range(layers):
        for j in range(layers - i):
            u = (i + 0.5) / layers
            v = (j + 0.5) / layers
            if len(pts) < n_pts:
                pts.append((1 - u - v) * _A + u * _B + v * _C)
    while len(pts) < n_pts:
        pts.append(_random_point())
    return np.array(pts)

def _anneal(n_pts: int = 11, iters: int = 2000, restarts: int = 5, seed: int = 0) -> np.ndarray:
    rng = random.Random(seed)
    best_pts = _initial_configuration(n_pts)
    best_val = _min_triangle_area(best_pts)

    for _ in range(restarts):
        pts = _initial_configuration(n_pts)
        current_val = _min_triangle_area(pts)

        for t in range(iters):
            T = max(0.01, 0.1 * (1 - t/iters))
            step_size = 0.05 * T

            idx = rng.randrange(n_pts)
            trial = pts.copy()
            trial[idx] += rng.uniform(-step_size, step_size), rng.uniform(-step_size, step_size)
            trial[idx] = _project_to_simplex(trial[idx])

            trial_val = _min_triangle_area(trial)
            delta = trial_val - current_val

            if delta > 0 or rng.random() < math.exp(delta / max(T, 1e-12)):
                pts = trial
                current_val = trial_val

                if current_val > best_val:
                    best_val = current_val
                    best_pts = pts.copy()

    return best_pts

def _local_polish(pts: np.ndarray) -> np.ndarray:
    if minimize is None or len(pts) == 0:
        return pts
    n_pts = len(pts)
    x0 = pts.ravel()

    def f(x: np.ndarray) -> float:
        P = x.reshape((-1, 2))
        return -_min_triangle_area(P)

    res = minimize(f, x0, method='Nelder-Mead', options={'maxiter': 500})
    if res.success:
        out = res.x.reshape((n_pts, 2))
        for i in range(n_pts):
            out[i] = _project_to_simplex(out[i])
        return out
    return pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=2000, restarts=5, seed=seed)
    pts = _local_polish(pts)
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _is_inside_triangle(x: float, y: float) -> bool:
    return y >= 0 and y <= SQRT3/2 and x >= 0 and x <= 1 and y <= (1-x)*SQRT3

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    x, y = p
    margin = 0.001
    if not _is_inside_triangle(x, y):
        # Project to nearest edge
        if y < 0:
            y = margin
        elif y > (1-x)*SQRT3:
            y = (1-x)*SQRT3 - margin
        elif x < 0:
            x = margin
            y = min(y, (1-x)*SQRT3 - margin)
        elif x > 1:
            x = 1 - margin
            y = min(y, (1-x)*SQRT3 - margin)
        elif y > SQRT3/2:
            y = SQRT3/2 - margin
    return np.array([max(margin, min(x, 1-margin)), max(margin, min(y, (1-max(margin, min(x, 1-margin)))*SQRT3 - margin)])

def _initial_hexagonal_configuration(n: int) -> np.ndarray:
    pts = []
    k = math.ceil(math.sqrt(2*n/SQRT3))
    for i in range(k):
        for j in range(k):
            x = (i + 0.5 * (j % 2)) / k
            y = (j * SQRT3 / 2) / k
            if _is_inside_triangle(x, y):
                x, y = _project_to_triangle([x, y])
                pts.append([x, y])
    while len(pts) < n:
        u, v = random.random(), random.random()
        if u + v > 1.0:
            u, v = 1 - u, 1 - v
        x = u
        y = v * SQRT3
        x, y = _project_to_triangle([x, y])
        pts.append([x, y])
    return np.array(pts[:n])

def _min_triangle_area_fast(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n):
        for j in range(i+1, min(i+10, n)):
            p1 = pts[i]
            p2 = pts[j]
            dx1 = p2[0] - p1[0]
            dy1 = p2[1] - p1[1]
            for k in range(j+1, min(j+10, n)):
                p3 = pts[k]
                dx2 = p3[0] - p1[0]
                dy2 = p3[1] - p1[1]
                area = abs(dx1*dy2 - dx2*dy1) / 2
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0.0
    return min_area

def _optimize_step_fast(pts: np.ndarray, idx: int, step: float) -> np.ndarray:
    original = pts[idx].copy()
    best_area = _min_triangle_area_fast(pts)

    for _ in range(5):
        trial = pts.copy()
        trial[idx] = original + np.random.uniform(-step, step, 2)
        trial[idx] = _project_to_triangle(trial[idx])
        trial_area = _min_triangle_area_fast(trial)

        if trial_area > best_area:
            best_area = trial_area
            pts = trial

    return pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    if seed is not None:
        np.random.seed(seed)
        random.seed(seed)

    pts = _initial_hexagonal_configuration(11)
    best_pts = pts.copy()
    best_area = _min_triangle_area_fast(pts)

    step = 0.05
    no_improvement = 0

    for _ in range(1000):
        if no_improvement > 50:
            step *= 0.8
            no_improvement = 0
            if step < 0.001:
                break

        idx = np.random.randint(11)
        pts = _optimize_step_fast(pts, idx, step)
        current_area = _min_triangle_area_fast(pts)

        if current_area > best_area:
            best_area = current_area
            best_pts = pts.copy()
            no_improvement = 0
        else:
            no_improvement += 1

    return [(float(x), float(y)) for x, y in best_pts]

