                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

def _is_inside(x: float, y: float) -> bool:
    return (y <= SQRT3 * min(x, 1 - x)) and (y >= 0) and (x >= 0) and (x <= 1)

def _generate_initial_points(n: int) -> np.ndarray:
    pts = []
    layers = 4
    for i in range(layers):
        for j in range(layers - i):
            x = (i + 2*j) / (2*layers - 2)
            y = i * SQRT3 / (2*layers - 2)
            if _is_inside(x, y):
                pts.append([x, y])

    while len(pts) < n:
        x = random.uniform(0.001, 0.999)
        y_max = SQRT3 * min(x, 1 - x)
        y = random.uniform(0.001, y_max)
        pts.append([x, y])

    return np.array(pts[:n])

def _optimize_points(pts: np.ndarray, iterations: int = 1000) -> np.ndarray:
