            candidate = best_pts[idx] + np.random.uniform(-step, step, 2)
            x, y = candidate
            if _is_inside(x, y):
                temp_pts[idx] = candidate
                new_area = _min_triangle_area(temp_pts)
                if new_area > best_area:
                    best_area = new_area
                    best_pts = temp_pts.copy()
                break

