from typing import List, Tuple
import numpy as np

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    best = float("inf")
    n = len(pts)
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    w = 1.0 - u - v
    if u >= 0 and v >= 0 and w >= 0:
        return p
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        s = u + v
        u /= s
        v /= s
    return (1 - u - v) * _A + u * _B + v * _C

def _initial_configuration(n_pts: int = 11) -> np.ndarray:
    pts = []
    for i in range(n_pts):
        u = (i % 4) / 4.0 + random.uniform(-0.05, 0.05)
        v = (i // 4) / 4.0 + random.uniform(-0.05, 0.05)
        if u + v <= 1.0:
            pts.append((1 - u - v) * _A + u * _B + v * _C)
    while len(pts) < n_pts:
        pts.append(_random_point())
    return np.array(pts[:n_pts])

def _differential_evolution(n_pts: int = 11, max_iter: int = 500, seed: int | None = 0) -> np.ndarray:
    random.seed(seed)
    population = [_initial_configuration(n_pts) for _ in range(5)]
    best_pts = population[0].copy()
    best_val = _min_triangle_area(best_pts)

    for _ in range(max_iter):
        for i in range(len(population)):
            a, b, c = random.sample(range(len(population)), 3)
            mutant = population[a] + 0.8 * (population[b] - population[c])
            for j in range(n_pts):
                mutant[j] = _project_to_simplex(mutant[j])
            trial_val = _min_triangle_area(mutant)
            if trial_val > best_val:
                best_val = trial_val
                best_pts = mutant.copy()
                population[i] = mutant.copy()
            elif trial_val > _min_triangle_area(population[i]):
                population[i] = mutant.copy()
    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _differential_evolution(n_pts=11, max_iter=500, seed=seed)
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    min_area = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area < 1e-8:
                        return min_area
    return min_area

def _is_in_triangle(p: np.ndarray) -> bool:
    x, y = p
    if x < 0 or x > 1 or y < 0 or y > SQRT3/2:
        return False
    if y > SQRT3 * x or y > SQRT3 * (1 - x):
        return False
    return True

def _generate_initial_points(n: int) -> np.ndarray:
    pts = []
    # Add some grid points
    for i in np.linspace(0.1, 0.9, 4):
        for j in np.linspace(0.1, SQRT3/2-0.1, 4):
            if _is_in_triangle([i, j]):
                pts.append([i, j])

    # Add some edge points
    edge_pts = [[0.0, 0.0], [1.0, 0.0], [0.5, SQRT3/2],
                [0.25, SQRT3/4], [0.75, SQRT3/4]]
    for p in edge_pts:
        if _is_in_triangle(p):
            pts.append(p)

    # Fill remaining with random points
    while len(pts) < n:
        x = random.uniform(0, 1)
        y = random.uniform(0, SQRT3/2)
        if _is_in_triangle([x, y]):
            pts.append([x, y])

    return np.array(pts[:n])

def _optimize_points(pts: np.ndarray, iterations: int = 3000) -> np.ndarray:
    best_pts = pts.copy()
    best_score = _min_triangle_area(best_pts)
    current_pts = pts.copy()
    temp = 0.2
    cooling_rate = 0.995

    for _ in range(iterations):
        temp *= cooling_rate
        trial_pts = current_pts.copy()

        for i in range(len(trial_pts)):
            perturbation = np.random.normal(0, temp/5, 2)
            trial_pts[i] += perturbation
            if not _is_in_triangle(trial_pts[i]):
                trial_pts[i] = np.clip(trial_pts[i], [0, 0], [1, SQRT3/2])
                x, y = trial_pts[i]
                if y > SQRT3 * x or y > SQRT3 * (1 - x):
                    trial_pts[i] = current_pts[i]

        current_score = _min_triangle_area(trial_pts)
        if current_score > best_score or (current_score > 0 and 
            math.exp((current_score - best_score)/temp) > random.random()):
            best_score = current_score
            best_pts = trial_pts.copy()
            current_pts = trial_pts.copy()
        else:
            current_pts = best_pts.copy()

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _generate_initial_points(11)
    pts = _optimize_points(pts, iterations=3000)

    # Ensure all points are unique
    unique_pts = []
    seen = set()
    for p in pts:
        p_tuple = (round(p[0], 6), round(p[1], 6))
        if p_tuple not in seen:
            seen.add(p_tuple)
            unique_pts.append(p)
        if len(unique_pts) == 11:
            break

    while len(unique_pts) < 11:
        x = random.uniform(0, 1)
        y = random.uniform(0, SQRT3/2)
        if _is_in_triangle([x, y]):
            p_tuple = (round(x, 6), round(y, 6))
            if p_tuple not in seen:
                seen.add(p_tuple)
                unique_pts.append([x, y])

    return [(float(x), float(y)) for x, y in unique_pts]

