import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
INV_SQRT3 = 1.0 / SQRT3

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    best = float('inf')
    for i in range(n):
        for j in range(i+1, min(i+8, n)):
            for k in range(j+1, min(j+8, n)):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    u, v = random.random(), random.random()
    if u + v > 1.0:
        u, v = 1 - u, 1 - v
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    x, y = p
    if y < 0:
        y = 0
        x = max(0.0, min(1.0, x))
    if x < 0:
        x = 0
        y = max(0.0, min(SQRT3, y))
    if x + y * INV_SQRT3 > 1.0:
        scale = 1.0 / (x + y * INV_SQRT3)
        x *= scale
        y *= scale
    return np.array([x, y])

def _initial_configuration(n_pts: int = 11) -> np.ndarray:
    pts = []
    # Hexagonal grid with center point
    pts.append(np.array([0.5, SQRT3/6]))
    layers = 2
    for layer in range(1, layers + 1):
        radius = layer / (layers + 1)
        for i in range(6 * layer):
            angle = 2 * math.pi * i / (6 * layer)
            x = 0.5 + radius * math.cos(angle) * 0.8
            y = SQRT3/6 + radius * math.sin(angle) * 0.8
            pts.append(np.array([x, y]))
    while len(pts) < n_pts:
        pts.append(_random_point())
    return np.array(pts[:n_pts])

def _local_search(pts: np.ndarray, steps: int = 200) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    n_pts = len(pts)
    step_sizes = [0.05, 0.02, 0.01]

    for step_size in step_sizes:
        improved = True
        for _ in range(steps):
            if not improved:
                break
            improved = False
            for idx in range(n_pts):
                for _ in range(4):
                    trial = best_pts.copy()
                    trial[idx] += random.uniform(-step_size, step_size), random.uniform(-step_size, step_size)
                    trial[idx] = _project_to_simplex(trial[idx])
                    trial_val = _min_triangle_area(trial)
                    if trial_val > best_val:
                        best_val = trial_val
                        best_pts = trial.copy()
                        improved = True
    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    pts = _initial_configuration(11)
    pts = _local_search(pts, steps=150)
    return [(float(x), float(y)) for x, y in pts]

