import numpy as np
from itertools import combinations

SQRT3 = math.sqrt(3.0)
TRI_AREA = SQRT3 / 4.0

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / 2.0

def _min_triangle_area(pts):
    min_area = float('inf')
    for trio in combinations(pts, 3):
        area = _area(*trio)
        if area < min_area:
            min_area = area
            if min_area == 0:
                return 0
    return min_area / TRI_AREA

def _is_in_triangle(pt):
    x, y = pt
    return y >= 0 and y <= SQRT3 * min(x, 1-x)

def _random_point():
    while True:
        x, y = random.random(), random.random()
        if _is_in_triangle((x, y)):
            return np.array([x, y])

def _hexagonal_grid(n):
    k = math.ceil(math.sqrt(n / (2/SQRT3)))
    pts = []
    for i in range(k):
        for j in range(k):
            x = (i + 0.5*(j%2)) / (k-0.5)
            y = (j * SQRT3/2) / (k-0.5)
            if _is_in_triangle((x, y)):
                pts.append([x, y])
                if len(pts) == n:
                    return pts
    while len(pts) < n:
        pts.append(_random_point())
    return pts[:n]

def _simulated_annealing(pts, iterations=10000, temp=1.0, cooling_rate=0.999, scale=0.1):
    current = np.array(pts)
    current_energy = -_min_triangle_area(current)
    best = current.copy()
    best_energy = current_energy

    for _ in range(iterations):
        temp *= cooling_rate
        idx = random.randrange(len(current))
        new_pt = current[idx] + np.random.normal(0, scale * temp, 2)

        if not _is_in_triangle(new_pt):
            continue

        trial = current.copy()
        trial[idx] = new_pt
        trial_energy = -_min_triangle_area(trial)

        if trial_energy < best_energy:
            best = trial.copy()
            best_energy = trial_energy

        if trial_energy < current_energy or math.exp((current_energy - trial_energy)/temp) > random.random():
            current = trial.copy()
            current_energy = trial_energy

    return best

def find_points(seed=None):
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _hexagonal_grid(11)
    pts = _simulated_annealing(pts, 10000, 1.0, 0.999, 0.1)
    pts = _simulated_annealing(pts, 5000, 0.5, 0.999, 0.05)

    best_pts = pts.copy()
    best_score = _min_triangle_area(best_pts)

    for _ in range(1000):
        idx = random.randrange(len(pts))
        new_pt = pts[idx] + np.random.normal(0, 0.005, 2)

        if not _is_in_triangle(new_pt):
            continue

        trial = pts.copy()
        trial[idx] = new_pt
        trial_score = _min_triangle_area(trial)

        if trial_score > best_score:
            best_pts = trial.copy()
            best_score = trial_score

    return [(float(x), float(y)) for x, y in best_pts]

import math
import random
import numpy as np
from itertools import combinations

SQRT3 = math.sqrt(3.0)
TRI_AREA = 0.5 * SQRT3 / 2.0

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5 / TRI_AREA

def _min_triangle_area(pts):
    min_area = float('inf')
    n = len(pts)
    for i in range(n-2):
        for j in range(i+1, n-1):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

def _is_in_triangle(p):
    x, y = p
    return (y >= 0) and (x + y/SQRT3 >= 0) and (x - y/SQRT3 <= 0) and (x + y/SQRT3 <= 1)

def _project_to_triangle(p):
    x, y = p
    y = max(0, min(y, SQRT3/2))
    x = max(-y/SQRT3, min(x, y/SQRT3))
    if x + y/SQRT3 > 1:
        x = 1 - y/SQRT3
    return np.array([x, y])

def _initialize_points(n):
    points = []
    # Hexagonal grid initialization
    layers = 3
    for i in range(layers + 1):
        for j in range(layers + 1 - i):
            x = (i + 0.5 * j) / layers
            y = (SQRT3/2) * j / layers
            points.append([x, y])
    # Add center point
    points.append([0.5, SQRT3/4])
    # Select top n points by distance to center
    center = np.array([0.5, SQRT3/4])
    points = sorted(points, key=lambda p: np.linalg.norm(np.array(p)-center))[:n]
    return np.array(points)

def _get_worst_triangle_indices(pts, k=1):
    min_area = float('inf')
    worst_indices = None
    n = len(pts)
    for i in range(n-2):
        for j in range(i+1, n-1):
            for m in range(j+1, n):
                a = _area(pts[i], pts[j], pts[m])
                if a < min_area:
                    min_area = a
                    worst_indices = (i, j, m)
                    if min_area == 0:
                        return [worst_indices]
    return [worst_indices] if worst_indices else []

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    pts = _initialize_points(11)
    best_pts = pts.copy()
    best_area = _min_triangle_area(pts)

    # Simulated annealing phase
    for t in range(2000):
        T = max(0.001, 0.1 * (0.001/0.1) ** (t/1999))
        step = 0.03 * (1 - t/2000)

        # Perturb points in worst triangles
        worst_tris = _get_worst_triangle_indices(pts)
        if not worst_tris:
            continue
        idx = random.choice(worst_tris[0])

        new_pts = pts.copy()
        perturbation = np.random.uniform(-step, step, size=2)
        new_pts[idx] += perturbation
        new_pts[idx] = _project_to_triangle(new_pts[idx])

        new_area = _min_triangle_area(new_pts)
        if new_area > best_area or (T > 0 and random.random() < math.exp((new_area - best_area)/T)):
            pts = new_pts
            if new_area > best_area:
                best_area = new_area
                best_pts = new_pts.copy()

    # Local optimization phase
    for _ in range(300):
        worst_tris = _get_worst_triangle_indices(best_pts)
        if not worst_tris:
            break
        i, j, k = worst_tris[0]
        centroid = (best_pts[i] + best_pts[j] + best_pts[k]) / 3
        for idx in [i, j, k]:
            new_pts = best_pts.copy()
            new_pts[idx] = 0.9 * new_pts[idx] + 0.1 * centroid
            new_pts[idx] = _project_to_triangle(new_pts[idx])
            new_area = _min_triangle_area(new_pts)
            if new_area > best_area:
                best_area = new_area
                best_pts = new_pts.copy()

    return [(float(x), float(y)) for x, y in best_pts]

from __future__ import annotations

import math
import random
import itertools
from typing import List, Tuple
import numpy as np

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    best = float("inf")
    n = len(pts)
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    w = 1.0 - u - v
    if u >= 0 and v >= 0 and w >= 0:
        return p
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        s = u + v
        u /= s
        v /= s
    return (1 - u - v) * _A + u * _B + v * _C

def _initial_configuration(n_pts: int = 11) -> np.ndarray:
    pts = []
    for i in range(n_pts):
        u = (i % 4) / 4.0 + random.uniform(-0.05, 0.05)
        v = (i // 4) / 4.0 + random.uniform(-0.05, 0.05)
        if u + v <= 1.0:
            pts.append((1 - u - v) * _A + u * _B + v * _C)
    while len(pts) < n_pts:
        pts.append(_random_point())
    return np.array(pts[:n_pts])

def _differential_evolution(n_pts: int = 11, max_iter: int = 500, seed: int | None = 0) -> np.ndarray:
    random.seed(seed)
    population = [_initial_configuration(n_pts) for _ in range(8)]
    best_pts = population[0].copy()
    best_val = _min_triangle_area(best_pts)

    for _ in range(max_iter):
        for i in range(len(population)):
            a, b, c = random.sample(range(len(population)), 3)
            mutant = population[a] + 0.9 * (population[b] - population[c])
            for j in range(n_pts):
                mutant[j] = _project_to_simplex(mutant[j])
            if random.random() < 0.1:
                mutant += np.random.normal(0, 0.01, size=mutant.shape)
                for j in range(n_pts):
                    mutant[j] = _project_to_simplex(mutant[j])
            trial_val = _min_triangle_area(mutant)
            if trial_val > best_val:
                best_val = trial_val
                best_pts = mutant.copy()
                population[i] = mutant.copy()
            elif trial_val > _min_triangle_area(population[i]):
                population[i] = mutant.copy()
    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _differential_evolution(n_pts=11, max_iter=500, seed=seed)
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4

def _is_in_triangle(x: float, y: float) -> bool:
    return (y >= 0) and (y <= SQRT3*(1 - abs(2*x - 1)))

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / (2 * TRIANGLE_AREA)

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n-2):
        for j in range(i+1, n-1):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

def _initialize_hexagonal(n: int) -> np.ndarray:
    pts = []
    layers = int(math.ceil(math.sqrt(n / 3))) + 1

    for layer in range(layers):
        for i in range(layer + 1):
            j = layer - i
            x = 0.5 + (i - j) * 0.5 / (layers - 1)
            y = j * SQRT3 / 2 / (layers - 1)
            if _is_in_triangle(x, y):
                pts.append([x, y])

    if len(pts) > n:
        pts = random.sample(pts, n)
    elif len(pts) < n:
        while len(pts) < n:
            x = random.uniform(0, 1)
            y_max = SQRT3 * (1 - abs(2*x - 1))
            y = random.uniform(0, y_max)
            pts.append([x, y])

    return np.array(pts)

def _optimize_points(pts: np.ndarray, iterations: int = 500) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)
    n = len(pts)

    for step in range(iterations):
        temp = 1.0 - step / iterations
        step_size = 0.1 * temp

        for idx in range(n):
            current_pt = best_pts[idx]
            best_move = None
            best_move_area = best_area

            for _ in range(20):
                angle = random.uniform(0, 2*math.pi)
                dx = step_size * math.cos(angle)
                dy = step_size * math.sin(angle)
                new_x = current_pt[0] + dx
                new_y = current_pt[1] + dy

                if _is_in_triangle(new_x, new_y):
                    new_pts = best_pts.copy()
                    new_pts[idx] = [new_x, new_y]
                    new_area = _min_triangle_area(new_pts)
                    if new_area > best_move_area:
                        best_move_area = new_area
                        best_move = [new_x, new_y]

            if best_move is not None:
                best_pts[idx] = best_move
                best_area = best_move_area

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _initialize_hexagonal(11)
    pts = _optimize_points(pts, 500)

    # Final verification and boundary clamping
    for i in range(len(pts)):
        x, y = pts[i]
        if not _is_in_triangle(x, y):
            y_max = SQRT3 * (1 - abs(2*x - 1))
            y = min(max(y, 0), y_max)
            pts[i] = [x, y]

    return [(float(x), float(y)) for x, y in pts]

