import math
import random
import numpy as np
from itertools import combinations

SQRT3 = math.sqrt(3.0)
_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _fast_min_area(pts: np.ndarray) -> float:
    min_area = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                area = abs((pts[j,0]-pts[i,0])*(pts[k,1]-pts[i,1]) - (pts[j,1]-pts[i,1])*(pts[k,0]-pts[i,0]))/2
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0
    return min_area

def _irregular_grid_points(n: int) -> np.ndarray:
    pts = []
    base_points = int(math.sqrt(n)) + 2
    for i in range(base_points):
        for j in range(base_points):
            x = (i + 0.5 * j + random.uniform(-0.1, 0.1)) / (base_points - 0.5)
            y = (j * SQRT3 / 2 + random.uniform(-0.05, 0.05)) / (base_points - 0.5)
            if x >= 0 and y >= 0 and (1 - x - y/SQRT3*2) >= 0:
                pts.append((x, y))
            if len(pts) >= n:
                return np.array(pts)
    return np.array(pts[:n])

def _optimize_points(pts: np.ndarray, max_iter: int = 2500) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _fast_min_area(best_pts)
    n = len(pts)

    for iter in range(max_iter):
        step = 0.1 * (1 - (iter/max_iter)**2)

        for i in range(n):
            trial = best_pts.copy()
            trial[i] += random.uniform(-step, step), random.uniform(-step, step)
            trial[i] = _project_to_simplex(trial[i])
            area = _fast_min_area(trial)

            if area > best_area:
                best_area = area
                best_pts = trial.copy()

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)

    # Start with irregular grid
    pts = _irregular_grid_points(11)

    # Fill remaining points randomly if needed
    while len(pts) < 11:
        pts = np.vstack([pts, [_random_point()]])

    # Optimize
    pts = _optimize_points(pts, max_iter=2500)

    return [(float(x), float(y)) for x, y in pts]

from __future__ import annotations

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    u, v = random.random(), random.random()
    if u + v > 1.0:
        u, v = 1 - u, 1 - v
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = 1 - u, 1 - v
    return (1 - u - v) * _A + u * _B + v * _C

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')

    for i in range(n):
        for j in range(i+1, min(i+15, n)):
            for k in range(j+1, min(j+15, n)):
                p, q, r = pts[i], pts[j], pts[k]
                area = abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0.0
    return min_area

def _get_smallest_triangles(pts: np.ndarray, k: int = 12) -> List[int]:
    n = len(pts)
    areas = []

    for i in range(n):
        for j in range(i+1, min(i+15, n)):
            for k in range(j+1, min(j+15, n)):
                p, q, r = pts[i], pts[j], pts[k]
                area = abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5
                areas.append((area, i, j, k))

    areas.sort()
    involved = set()
    for _, i, j, k in areas[:k]:
        involved.update([i, j, k])
    return list(involved)

def _anneal(n_pts: int = 11,
            iters: int = 40000,
            start_temp: float = 0.6,
            end_temp: float = 1e-14,
            seed: int | None = 0) -> np.ndarray:

    random.seed(seed)
    pts = []
    # Better initial placement using hexagonal pattern
    for i in range(n_pts):
        if i == 0:
            pts.append(np.array([0.5, SQRT3/3]))
        elif i == 1:
            pts.append(np.array([0.25, SQRT3/12]))
        elif i == 2:
            pts.append(np.array([0.75, SQRT3/12]))
        elif i == 3:
            pts.append(np.array([0.125, SQRT3/4]))
        elif i == 4:
            pts.append(np.array([0.875, SQRT3/4]))
        else:
            pts.append(_random_point())
    pts = np.array(pts)

    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        T = start_temp * math.exp(math.log(end_temp/start_temp) * (t/iters)**0.8)

        step_size = 0.05 * math.exp(-3.0 * t/iters) + 0.001

        if t % 8 == 0:
            critical_points = _get_smallest_triangles(pts)
        else:
            critical_points = list(range(n_pts))

        idx = random.choice(critical_points)
        trial = pts.copy()
        trial[idx] += random.uniform(-step_size, step_size), random.uniform(-step_size, step_size)
        trial[idx] = _project_to_simplex(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or random.random() < math.exp(delta / max(T, 1e-14)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=40000, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

