import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / (2 * TRIANGLE_AREA)

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n-2):
        for j in range(i+1, n-1):
            p0 = pts[j] - pts[i]
            for k in range(j+1, n):
                p1 = pts[k] - pts[i]
                area = abs(p0[0]*p1[1] - p0[1]*p1[0]) / (2 * TRIANGLE_AREA)
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0
    return min_area

def _random_point_in_triangle() -> np.ndarray:
    while True:
        r1 = random.random()
        r2 = random.random()
        if r1 + r2 <= 1:
            x = r1 * 1.0 + r2 * 0.5
            y = r2 * SQRT3 / 2.0
            return np.array([x, y])

def _initialize_points(n_pts: int) -> np.ndarray:
    pts = []
    for i in range(n_pts):
        r = math.sqrt(random.random()) * 0.9
        angle = 2 * math.pi * i / n_pts
        x = 0.5 + r * 0.5 * math.cos(angle)
        y = SQRT3/3 + r * SQRT3/3 * math.sin(angle)
        pts.append(np.array([x, y]))
    return np.array(pts)

def _is_in_triangle(p: np.ndarray) -> bool:
    x, y = p
    if y < 0 or y > SQRT3/2:
        return False
    if x < 0 or x > 1:
        return False
    if y > SQRT3 * x or y > SQRT3 * (1 - x):
        return False
    return True

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    x, y = p
    if _is_in_triangle(p):
        return p

    # Project to bottom edge
    if y <= 0:
        x_proj = max(0.0, min(1.0, x))
        return np.array([x_proj, 0.0])

    # Project to left edge
    y_left = SQRT3 * x
    # Project to right edge
    y_right = SQRT3 * (1 - x)

    # Find closest edge
    d_left = abs(y - y_left)
    d_right = abs(y - y_right)

    if d_left < d_right:
        # Project to left edge
        if y_left <= 0:
            return np.array([0.0, 0.0])
        y_proj = min(y_left, SQRT3/2)
        return np.array([x, y_proj])
    else:
        # Project to right edge
        if y_right <= 0:
            return np.array([1.0, 0.0])
        y_proj = min(y_right, SQRT3/2)
        return np.array([x, y_proj])

def _anneal(n_pts: int = 11,
            iters: int = 50000,
            start_temp: float = 0.1,
            end_temp: float = 1e-8,
            step_size: float = 0.05,
            seed: int | None = None) -> np.ndarray:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _initialize_points(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        T = start_temp * (end_temp / start_temp) ** (t / iters)
        current_step = step_size * (1 - t/iters)

        idx = random.randrange(n_pts)
        trial = pts.copy()

        if t % 100 == 0:
            trial[idx] = _random_point_in_triangle()
        else:
            delta = np.random.uniform(-current_step, current_step, size=2)
            trial[idx] += delta
            trial[idx] = _project_to_triangle(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta_val = trial_val - best_val

        if delta_val > 0 or math.exp(delta_val / max(T, 1e-12)) > random.random():
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

from __future__ import annotations

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _random_point() -> np.ndarray:
    u, v = random.random(), random.random()
    if u + v > 1.0:
        u, v = 1 - u, 1 - v
    return np.array([(1 - u - v) * 0 + u * 1 + v * 0.5,
                    (1 - u - v) * 0 + u * 0 + v * (SQRT3 / 2)])

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    x, y = p
    v0 = np.array([1, 0])
    v1 = np.array([0.5, SQRT3/2])

    denom = v0[0]*v1[1] - v1[0]*v0[1]
    u = (x*v1[1] - y*v1[0]) / denom
    v = (y*v0[0] - x*v0[1]) / denom

    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = 1 - u, 1 - v
    return np.array([u + 0.5*v, v * SQRT3/2])

def _min_triangle_area_fast(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')

    for i in range(n):
        for j in range(i+1, min(i+8, n)):
            for k in range(j+1, min(j+8, n)):
                p1, p2, p3 = pts[i], pts[j], pts[k]
                area = 0.5 * abs((p2[0]-p1[0])*(p3[1]-p1[1]) - (p2[1]-p1[1])*(p3[0]-p1[0]))
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0.0
    return min_area

def _grid_init(n: int) -> np.ndarray:
    k = math.ceil(math.sqrt(n * 2))
    points = []
    for i in range(k):
        for j in range(k-i):
            u = (i + 0.5) / k
            v = (j + 0.5) / k
            if u + v <= 1.0:
                points.append([u + 0.5*v, v * SQRT3/2])
                if len(points) == n:
                    return np.array(points)
    return np.array(points + [_random_point() for _ in range(n - len(points))])

def _optimize(pts: np.ndarray, steps: int = 5000) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area_fast(pts)
    step_size = 0.05

    for step in range(steps):
        temp = 1.0 - step/steps
        step_size = 0.05 * temp

        idx = random.randrange(len(pts))
        new_pts = pts.copy()
        new_pts[idx] += np.random.uniform(-step_size, step_size, 2)
        new_pts[idx] = _project_to_simplex(new_pts[idx])

        new_area = _min_triangle_area_fast(new_pts)
        if new_area > best_area or (temp > 0 and random.random() < temp):
            pts = new_pts
            if new_area > best_area:
                best_area = new_area
                best_pts = new_pts.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    pts = _grid_init(11)
    pts = _optimize(pts, 5000)
    return [(float(x), float(y)) for x, y in pts]

import math
import random
import numpy as np
from itertools import combinations

SQRT3 = math.sqrt(3.0)
TRI_AREA = SQRT3 / 4.0

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / 2.0

def _min_triangle_area(pts):
    min_area = float('inf')
    for trio in combinations(pts, 3):
        area = _area(*trio)
        if area < min_area:
            min_area = area
            if min_area == 0:
                return 0
    return min_area / TRI_AREA

def _is_in_triangle(pt):
    x, y = pt
    return y >= 0 and y <= SQRT3 * min(x, 1-x)

def _random_point():
    while True:
        x, y = random.random(), random.random()
        if _is_in_triangle((x, y)):
            return np.array([x, y])

def _initial_placement(n):
    pts = []
    for i in range(n):
        while True:
            x = 0.2 + 0.6 * i/(n-1) if n > 1 else 0.5
            y = SQRT3 * x * (1 - x)
            x += random.uniform(-0.1, 0.1)
            y *= random.uniform(0.8, 1.2)
            if _is_in_triangle((x, y)):
                pts.append([x, y])
                break
    return pts

def _simulated_annealing(pts, iterations, initial_temp, cooling_rate, scale):
    current = np.array(pts)
    current_energy = -_min_triangle_area(current)
    best = current.copy()
    best_energy = current_energy

    for i in range(iterations):
        temp = initial_temp * (cooling_rate ** i)
        idx = random.randrange(len(current))
        new_pt = current[idx] + np.random.normal(0, scale * temp, 2)

        if not _is_in_triangle(new_pt):
            continue

        trial = current.copy()
        trial[idx] = new_pt
        trial_energy = -_min_triangle_area(trial)

        if trial_energy < best_energy:
            best = trial.copy()
            best_energy = trial_energy

        if trial_energy < current_energy or math.exp((current_energy - trial_energy)/temp) > random.random():
            current = trial.copy()
            current_energy = trial_energy

    return best

def find_points(seed=None):
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _initial_placement(11)
    pts = _simulated_annealing(pts, 15000, 1.0, 0.9995, 0.15)
    pts = _simulated_annealing(pts, 10000, 0.3, 0.999, 0.05)

    best_pts = pts.copy()
    best_score = _min_triangle_area(best_pts)

    for _ in range(3000):
        idx = random.randrange(len(pts))
        new_pt = pts[idx] + np.random.normal(0, 0.01, 2)

        if not _is_in_triangle(new_pt):
            continue

        trial = pts.copy()
        trial[idx] = new_pt
        trial_score = _min_triangle_area(trial)

        if trial_score > best_score:
            best_pts = trial.copy()
            best_score = trial_score
            pts = trial.copy()

    return [(float(x), float(y)) for x, y in best_pts]

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5 / TRIANGLE_AREA

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    while True:
        u, v = np.random.random(2)
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _hex_grid_points(n: int) -> np.ndarray:
    pts = []
    k = 5  # Increased to generate more points
    count = 0
    for i in range(k):
        for j in range(k - i):
            if count >= n:
                break
            x = i/k + j/(2*k)
            y = j * SQRT3/(2*k)
            pts.append([x, y])
            count += 1
    return np.array(pts[:n])

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    w = 1.0 - u - v
    if u >= 0 and v >= 0 and w >= 0:
        return p
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _optimize(pts: np.ndarray, n_iters: int = 800) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    step = 0.002

    for _ in range(n_iters):
        improved = False
        for idx in range(len(pts)):
            for dx, dy in [(step,0), (-step,0), (0,step), (0,-step), 
                          (step,step), (-step,-step), (step,-step), (-step,step)]:
                trial = best_pts.copy()
                trial[idx] += np.array([dx, dy])
                trial[idx] = _project_to_simplex(trial[idx])
                trial_val = _min_triangle_area(trial)
                if trial_val > best_val:
                    best_val = trial_val
                    best_pts = trial.copy()
                    improved = True
        if not improved:
            step *= 0.9
    return best_pts

def _anneal(n_pts: int = 11, iters: int = 2000, seed: int | None = None) -> np.ndarray:
    if seed is not None:
        np.random.seed(seed)

    pts = _hex_grid_points(n_pts)
    if len(pts) < n_pts:
        while len(pts) < n_pts:
            pts = np.vstack([pts, _random_point()])

    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    temp = 0.15
    cooling_rate = 0.998

    for t in range(iters):
        temp *= cooling_rate

        idx = np.random.randint(n_pts)
        trial = pts.copy()
        perturbation = np.random.uniform(-0.02, 0.02, size=2)
        trial[idx] += perturbation
        trial[idx] = _project_to_simplex(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or np.random.random() < math.exp(delta / max(temp, 1e-12)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

    return _optimize(best_pts, n_iters=400)

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=2000, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

from __future__ import annotations
import math
import random
import numpy as np
from typing import List, Tuple
from scipy.spatial import cKDTree, Voronoi

SQRT3 = math.sqrt(3.0)
_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])
TRI_AREA = SQRT3 / 4.0

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5

def _min_triangle_area_fast(pts: np.ndarray) -> float:
    tree = cKDTree(pts)
    min_area = float('inf')
    for i in range(len(pts)):
        dists, idxs = tree.query(pts[i], k=7)
        for j in range(1, 6):
            for k in range(j+1, 7):
                area = _area(pts[i], pts[idxs[j]], pts[idxs[k]]])
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0
    return min_area

def _is_inside(p: np.ndarray) -> bool:
    try:
        u, v = np.linalg.solve(np.column_stack((_B-_A, _C-_A)), p-_A)
    except:
        return False
    return u >= -1e-8 and v >= -1e-8 and (1-u-v) >= -1e-8

def _generate_hexagonal_points(n: int) -> np.ndarray:
    k = int(math.sqrt(n)) + 1
    pts = []
    for i in range(k):
        for j in range(k):
            x = (i + 0.5 * (j % 2)) / k
            y = (j * SQRT3 / 2) / k
            if _is_inside(np.array([x, y])):
                pts.append([x, y])
                if len(pts) == n:
                    return np.array(pts)
    return np.array(pts)

def _voronoi_refine(pts: np.ndarray, steps: int) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area_fast(best_pts)

    for _ in range(steps):
        vor = Voronoi(best_pts)
        new_pts = []
        for i, point in enumerate(best_pts):
            region = vor.regions[vor.point_region[i]]
            if -1 not in region and len(region) > 0:
                vertices = np.array([vor.vertices[r] for r in region])
                centroid = np.mean(vertices, axis=0)
                if _is_inside(centroid):
                    new_pts.append(centroid)
                else:
                    new_pts.append(point)
            else:
                new_pts.append(point)

        new_pts = np.array(new_pts)
        new_val = _min_triangle_area_fast(new_pts)
        if new_val > best_val:
            best_val = new_val
            best_pts = new_pts

    return best_pts

def _cma_es_optimize(n_pts: int, max_iter: int) -> np.ndarray:
    from cmaes import CMA
    bounds = np.array([[0, 1], [0, SQRT3/2]])

    def objective(x):
        pts = x.reshape(n_pts, 2)
        for p in pts:
            if not _is_inside(p):
                return float('inf')
        return -_min_triangle_area_fast(pts)

    initial_pts = _generate_hexagonal_points(n_pts)
    if len(initial_pts) < n_pts:
        initial_pts = np.vstack([initial_pts, np.random.uniform(0, 1, (n_pts - len(initial_pts), 2))])
        initial_pts[:, 1] *= SQRT3/2

    x0 = initial_pts.flatten()
    sigma0 = 0.2
    optimizer = CMA(mean=x0, sigma=sigma0, bounds=bounds, population_size=16)

    for _ in range(max_iter):
        solutions = []
        for _ in range(optimizer.population_size):
            x = optimizer.ask()
            value = objective(x)
            solutions.append((x, value))
        optimizer.tell(solutions)

    best_x = optimizer.best.x
    return best_x.reshape(n_pts, 2)

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    pts = _cma_es_optimize(n_pts=11, max_iter=30)
    pts = _voronoi_refine(pts, steps=20)

    return [(float(x), float(y)) for x, y in pts]

