import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    min_area = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, min(i+8, n)):
            for k in range(j+1, min(j+8, n)):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    if u >= 0 and v >= 0 and (u + v) <= 1.0:
        return p
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _hexagonal_grid(n_pts: int = 11) -> np.ndarray:
    pts = []
    layers = math.ceil(math.sqrt(n_pts * 2 / SQRT3))
    for i in range(layers):
        for j in range(layers):
            x = (j + 0.5 * (i % 2)) / (layers - 0.5)
            y = (i * SQRT3/2) / (layers - 0.5)
            if x + y/SQRT3 <= 1.0 and x - y/SQRT3 <= 0.0 and y <= SQRT3/2:
                pts.append(np.array([x, y]))
            if len(pts) >= n_pts:
                break
        if len(pts) >= n_pts:
            break
    while len(pts) < n_pts:
        pts.append(_random_point())
    return np.array(pts[:n_pts])

def _anneal(n_pts: int = 11,
            iters: int = 5000,
            start_temp: float = 0.2,
            end_temp: float = 1e-8,
            seed: int | None = 0) -> np.ndarray:
    rng = np.random.RandomState(seed)
    pts = _hexagonal_grid(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    no_improve = 0

    for t in range(iters):
        T = start_temp * math.exp(math.log(end_temp/start_temp) * t/iters)
        current_step = 0.05 * (1 - t/iters) + 0.005

        if no_improve > 100 and T < 0.01:
            break

        idx = rng.randint(n_pts)
        trial = pts.copy()
        trial[idx] += rng.uniform(-current_step, current_step, size=2)
        trial[idx] = _project_to_simplex(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or rng.random() < math.exp(delta / max(T, 1e-12)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = pts.copy()
                no_improve = 0
            else:
                no_improve += 1

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=5000, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

import math
import random
import numpy as np
from itertools import combinations

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / 2.0

def _min_triangle_area(pts):
    min_area = float('inf')
    for trio in combinations(pts, 3):
        a = _area(*trio)
        if a < min_area:
            min_area = a
            if min_area < 1e-8:
                return min_area
    return min_area

def _is_in_triangle(p):
    x, y = p
    if x < 0 or x > 1 or y < 0 or y > SQRT3/2:
        return False
    if y > SQRT3 * x:
        return False
    if y > SQRT3 * (1 - x):
        return False
    return True

def _generate_initial_points(n):
    points = []
    # Hexagonal pattern
    for i in range(n):
        x = 0.5 + 0.4 * math.cos(2 * math.pi * i / n)
        y = SQRT3/4 + 0.4 * math.sin(2 * math.pi * i / n)
        if _is_in_triangle((x, y)):
            points.append([x, y])
    # Grid pattern for remaining points
    grid_size = int(math.ceil(math.sqrt(n - len(points))))
    for i in range(grid_size):
        for j in range(grid_size):
            if len(points) >= n:
                break
            x = (i + 0.5) / grid_size
            y = (j + 0.5) / grid_size * SQRT3/2
            if _is_in_triangle((x, y)):
                points.append([x, y])
    # Random points if still needed
    while len(points) < n:
        x = random.uniform(0, 1)
        y = random.uniform(0, SQRT3/2)
        if _is_in_triangle((x, y)):
            points.append([x, y])
    return np.array(points)

def _optimize_points(points, max_iterations):
    best_points = points.copy()
    best_score = _min_triangle_area(best_points)
    step = 0.02
    no_improve = 0

    for i in range(max_iterations):
        if no_improve > 50:
            step *= 0.5
            no_improve = 0
            if step < 1e-6:
                break

        new_points = best_points.copy()
        for idx in range(len(points)):
            # Gradient-based perturbation
            delta = np.random.uniform(-step, step, 2)
            new_points[idx] += delta
            if not _is_in_triangle(new_points[idx]):
                new_points[idx] -= delta
                continue

            new_score = _min_triangle_area(new_points)
            if new_score > best_score:
                best_score = new_score
                best_points = new_points.copy()
                no_improve = 0
            else:
                new_points[idx] -= delta
                no_improve += 1

    return best_points

def find_points(seed=None):
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    points = _generate_initial_points(11)
    points = _optimize_points(points, 2000)

    return [(float(p[0]), float(p[1])) for p in points]

from __future__ import annotations

import math
import random
import numpy as np

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area_fast(pts: np.ndarray, cutoff: float = 0) -> float:
    n = len(pts)
    best = float('inf')
    for i in range(n-2):
        p = pts[i]
        for j in range(i+1, n-1):
            q = pts[j]
            pq = q - p
            for k in range(j+1, n):
                a = abs(np.cross(pq, pts[k] - p)) * 0.5
                if a <= cutoff:
                    return a
                if a < best:
                    best = a
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            return (1 - u - v) * _A + u * _B + v * _C

def _is_in_triangle(p: np.ndarray) -> bool:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    return u >= -1e-8 and v >= -1e-8 and (u + v) <= 1.0 + 1e-8

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        total = u + v
        u /= total
        v /= total
    return (1 - u - v) * _A + u * _B + v * _C

def _initial_configuration(n_pts: int = 11) -> np.ndarray:
    pts = []
    layers = 4
    for i in range(layers):
        for j in range(i+1):
            u = (j + 0.5 * (i % 1)) / (layers-1)
            v = (i - j + 0.5 * (i % 1)) / (layers-1)
            if u + v <= 1.0:
                pts.append((1 - u - v) * _A + u * _B + v * _C)
    while len(pts) < n_pts:
        pts.append(_random_point())
    return np.array(pts[:n_pts])

def _optimize(n_pts: int = 11, iters: int = 8000, seed: int | None = 0) -> np.ndarray:
    rng = random.Random(seed)
    pts = _initial_configuration(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area_fast(best_pts)

    for t in range(iters):
        T = max(0.05 * (1 - (t/iters)**0.8), 1e-6)
        idx = rng.randrange(n_pts)
        trial = pts.copy()

        step = 0.04 * (1 - (t/iters)**0.3)
        if t % 100 == 0 and rng.random() < 0.1:
            step *= 3

        trial[idx] += rng.uniform(-step, step), rng.uniform(-step, step)
        trial[idx] = _project_to_simplex(trial[idx])

        if not _is_in_triangle(trial[idx]):
            continue

        trial_val = _min_triangle_area_fast(trial, best_val)
        if trial_val <= best_val and rng.random() >= math.exp((trial_val - best_val)/T):
            continue

        pts = trial
        if trial_val > best_val:
            best_val = trial_val
            best_pts = trial.copy()

    # Final validation and projection
    for i in range(len(best_pts)):
        best_pts[i] = _project_to_simplex(best_pts[i])
        assert _is_in_triangle(best_pts[i]), f"Point {best_pts[i]} is outside triangle"

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _optimize(n_pts=11, iters=8000, seed=seed)
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

import math
import random
import numpy as np
from itertools import combinations
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRI_AREA = 0.5 * SQRT3 / 2.0

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5 / TRI_AREA

def _min_triangle_area(pts):
    min_area = float('inf')
    n = len(pts)
    for i in range(n-2):
        for j in range(i+1, n-1):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

def _is_in_triangle(p):
    x, y = p
    return (x >= 0) and (y >= 0) and (x + y/SQRT3 <= 1.0) and (x - y/SQRT3 <= 0.0) and (y <= SQRT3/2)

def _project_to_triangle(p):
    x, y = p
    # Ensure positive coordinates first
    x = max(0.0, x)
    y = max(0.0, y)
    # Project to y boundary
    y = min(y, SQRT3/2 - 1e-10)
    # Project to left boundary
    if x - y/SQRT3 > 0:
        x = y/SQRT3 + 1e-10
    # Project to right boundary
    if x + y/SQRT3 > 1:
        x = 1 - y/SQRT3 - 1e-10
    return np.array([x, y])

def _initialize_points(n):
    points = []
    # Use hexagonal lattice pattern
    layers = 4
    for i in range(layers + 1):
        for j in range(layers + 1 - i):
            x = (i + 0.5 * j) / layers
            y = (SQRT3/2) * j / layers
            points.append([x, y])
    # Ensure we have at least n points
    while len(points) < n:
        x = random.uniform(0.01, 0.99)
        y = random.uniform(0.01, SQRT3/2 - 0.01)
        if _is_in_triangle((x, y)):
            points.append([x, y])
    # Select n points closest to center
    center = np.array([0.5, SQRT3/4])
    points = sorted(points, key=lambda p: np.linalg.norm(np.array(p)-center))[:n]
    return np.array(points)

def _get_worst_triangle_indices(pts, k=1):
    min_area = float('inf')
    worst_indices = None
    n = len(pts)
    for i in range(n-2):
        for j in range(i+1, n-1):
            for m in range(j+1, n):
                a = _area(pts[i], pts[j], pts[m])
                if a < min_area:
                    min_area = a
                    worst_indices = (i, j, m)
                    if min_area == 0:
                        return [worst_indices]
    return [worst_indices] if worst_indices else []

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    pts = _initialize_points(11)
    best_pts = pts.copy()
    best_area = _min_triangle_area(pts)

    # Simulated annealing phase
    for t in range(2000):
        T = max(0.001, 0.1 * (0.001/0.1) ** (t/1999))
        step = 0.03 * (1 - t/2000)

        # Perturb points in worst triangles
        worst_tris = _get_worst_triangle_indices(pts)
        if not worst_tris:
            continue
        idx = random.choice(worst_tris[0])

        new_pts = pts.copy()
        perturbation = np.random.uniform(-step, step, size=2)
        new_pts[idx] += perturbation
        new_pts[idx] = _project_to_triangle(new_pts[idx])

        new_area = _min_triangle_area(new_pts)
        if new_area > best_area or (T > 0 and random.random() < math.exp((new_area - best_area)/T)):
            pts = new_pts
            if new_area > best_area:
                best_area = new_area
                best_pts = new_pts.copy()

    # Local optimization phase
    for _ in range(300):
        worst_tris = _get_worst_triangle_indices(best_pts)
        if not worst_tris:
            break
        i, j, k = worst_tris[0]
        centroid = (best_pts[i] + best_pts[j] + best_pts[k]) / 3
        for idx in [i, j, k]:
            new_pts = best_pts.copy()
            new_pts[idx] = 0.9 * new_pts[idx] + 0.1 * centroid
            new_pts[idx] = _project_to_triangle(new_pts[idx])
            new_area = _min_triangle_area(new_pts)
            if new_area > best_area:
                best_area = new_area
                best_pts = new_pts.copy()

    return [(float(x), float(y)) for x, y in best_pts]

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4

def _point_in_triangle(x: float, y: float) -> bool:
    if y < 0 or y > SQRT3/2:
        return False
    if x < 0 or x > 1:
        return False
    return y <= SQRT3 * (1 - abs(2*x - 1))

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n-2):
        for j in range(i+1, n-1):
            p = pts[i]
            q = pts[j]
            dx1 = q[0] - p[0]
            dy1 = q[1] - p[1]
            for k in range(j+1, n):
                r = pts[k]
                area = abs(dx1 * (r[1] - p[1]) - (r[0] - p[0]) * dy1) * 0.5
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0
    return min_area

def _generate_initial_points(n: int) -> np.ndarray:
    pts = []
    layers = 4
    for layer in range(1, layers+1):
        for i in range(layer):
            x = 0.5 + (i - layer/2 + 0.5) / (2*layers)
            y = (layer - 1) * SQRT3 / (2*layers)
            if _point_in_triangle(x, y):
                pts.append([x, y])

    while len(pts) < n:
        x = random.uniform(0.01, 0.99)
        y = random.uniform(0.01, SQRT3/2 - 0.01)
        if _point_in_triangle(x, y):
            pts.append([x, y])

    return np.array(pts[:n])

def _optimize_points(pts: np.ndarray, iterations: int = 5000) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)
    n = len(pts)
    temp = 0.1

    for iter in range(iterations):
        temp = 0.1 * (1 - iter/iterations)
        new_pts = best_pts.copy()

        for _ in range(5):
            idx = random.randint(0, n-1)
            step = temp * random.random()
            angle = random.uniform(0, 2*math.pi)
            dx = step * math.cos(angle)
            dy = step * math.sin(angle)

            x = new_pts[idx][0] + dx
            y = new_pts[idx][1] + dy

            if _point_in_triangle(x, y):
                new_pts[idx] = [x, y]

        new_area = _min_triangle_area(new_pts)
        if new_area > best_area or (random.random() < math.exp((new_area - best_area)/temp) and new_area > 0):
            best_area = new_area
            best_pts = new_pts.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _generate_initial_points(11)
    pts = _optimize_points(pts, 5000)

    return [(float(x), float(y)) for x, y in pts]

import math
import random
import numpy as np

SQRT3 = math.sqrt(3)
TRIANGLE_HEIGHT = SQRT3 / 2
TRIANGLE_AREA = SQRT3 / 4

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / 2.0

def _min_triangle_area(pts):
    n = len(pts)
    min_area = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

def _min_area_with_point(pts, idx):
    min_area = float('inf')
    for j in range(len(pts)):
        if j == idx:
            continue
        for k in range(j+1, len(pts)):
            if k == idx:
                continue
            a = _area(pts[idx], pts[j], pts[k])
            if a < min_area:
                min_area = a
    return min_area

def _project_to_triangle(p):
    x, y = p
    # Project y into [0, TRIANGLE_HEIGHT]
    y = max(0.0, min(TRIANGLE_HEIGHT, y))
    # Project x into [0, 1]
    x = max(0.0, min(1.0, x))
    # Adjust for triangle sides
    if y > x * SQRT3:
        y = x * SQRT3
    if y > (1 - x) * SQRT3:
        y = (1 - x) * SQRT3
    return (x, y)

def _generate_hexagonal_points(n, jitter=0.001):
    layers = math.ceil(math.sqrt(2 * n / SQRT3)) + 2
    points = []

    for i in range(layers):
        y = (i + 0.5) * TRIANGLE_HEIGHT / layers
        x_offset = 0.5 if i % 2 == 1 else 0.0
        num_in_row = layers - i // 2

        for j in range(num_in_row):
            x = x_offset + j
            x = (x + 0.25) / layers
            if jitter > 0:
                x += random.uniform(-jitter, jitter)
                y += random.uniform(-jitter, jitter)
            pt = _project_to_triangle((x, y))
            points.append(pt)

    while len(points) < n:
        x = random.uniform(0, 1)
        y = random.uniform(0, TRIANGLE_HEIGHT)
        pt = _project_to_triangle((x, y))
        points.append(pt)

    return points[:n]

def _optimize_points(pts, iterations=800, anneal=True):
    n = len(pts)
    current_pts = np.array(pts, dtype=np.float64)
    current_area = _min_triangle_area(current_pts)
    best_pts = current_pts.copy()
    best_area = current_area

    # Precompute all triangles not involving each point
    base_min_areas = [float('inf')] * n
    for i in range(n):
        for j in range(n):
            if j == i:
                continue
            for k in range(j+1, n):
                if k == i:
                    continue
                a = _area(current_pts[j], current_pts[k], current_pts[i])
                if a < base_min_areas[i]:
                    base_min_areas[i] = a

    for step in range(iterations):
        T = 1.0 - step / iterations
        step_size = 0.05 * T + 0.005

        improved = False
        for i in range(n):
            orig_point = current_pts[i].copy()
            best_move = None
            best_move_area = current_area

            for attempt in range(5):
                trial_pts = current_pts.copy()
                perturbation = np.random.normal(0, step_size, 2)
                new_point = _project_to_triangle(orig_point + perturbation)
                trial_pts[i] = new_point

                # Compute new min area for triangles involving this point
                new_area_i = _min_area_with_point(trial_pts, i)
                new_area = min(base_min_areas[i], new_area_i)

                if new_area > best_move_area or (anneal and random.random() < math.exp((new_area - best_move_area)/(0.01 + 0.1*T))):
                    best_move = new_point
                    best_move_area = new_area

            if best_move is not None:
                current_pts[i] = best_point
                new_area_i = _min_area_with_point(current_pts, i)
                current_area = min(base_min_areas[i], new_area_i)
                base_min_areas[i] = new_area_i

                if current_area > best_area:
                    best_area = current_area
                    best_pts = current_pts.copy()
                    improved = True

        # Periodically rescale coordinates to combat drift
        if step % 50 == 0:
            centroid = np.mean(current_pts, axis=0)
            current_pts -= centroid
            current_pts *= 0.99
            current_pts += centroid
            for i in range(n):
                current_pts[i] = _project_to_triangle(current_pts[i])
            current_area = _min_triangle_area(current_pts)
            if current_area > best_area:
                best_area = current_area
                best_pts = current_pts.copy()

    return best_pts

def find_points(seed=None):
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    # Generate initial points with hexagonal pattern and slight jitter
    pts = _generate_hexagonal_points(11, jitter=0.01)

    # Run optimization with simulated annealing
    pts = _optimize_points(pts, iterations=1200, anneal=True)

    return [(float(x), float(y)) for x, y in pts]

