import math
import random
import numpy as np

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area < 1e-8:
                        return 0
    return min_area

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _hex_grid_point(i: int, j: int, k: int) -> np.ndarray:
    x = (i + 0.5 * (j % 2)) / k
    y = (j * SQRT3 / 2) / k
    return np.array([x, y])

def _initial_points(n: int) -> np.ndarray:
    k = int(math.sqrt(n * 4 / SQRT3)) + 2
    pts = []
    for i in range(k):
        for j in range(k):
            p = _hex_grid_point(i, j, k)
            if (p[0] >= 0 and p[1] >= 0 and 
                p[0] + p[1]/SQRT3 <= 1.0 and 
                p[0] - p[1]/SQRT3 <= 1.0 and 
                p[1] <= SQRT3/2):
                pts.append(p)
    if len(pts) > n:
        pts = sorted(pts, key=lambda p: (p[0], p[1]))[:n]
    elif len(pts) < n:
        pts.extend([_hex_grid_point(random.randint(0,k), random.randint(0,k), k) 
                   for _ in range(n - len(pts))])
    return np.array(pts[:n])

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv[0], uv[1]
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _anneal(n_pts: int = 11, iters: int = 10000, seed: int | None = 0) -> np.ndarray:
    random.seed(seed)
    pts = _initial_points(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        T = max(0.001, 0.2 * (1 - t/iters)**3)
        idx = random.randrange(n_pts)
        trial = pts.copy()
        step = 0.1 * (1 - t/iters)**1.5
        trial[idx] += np.random.normal(0, step, 2)
        trial[idx] = _project_to_simplex(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or (T > 0 and random.random() < math.exp(delta / T)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

        if t % 500 == 0 and t > 0:
            pts = best_pts.copy()
            for _ in range(5):
                idx = random.randrange(n_pts)
                pts[idx] += np.random.normal(0, 0.02, 2)
                pts[idx] = _project_to_simplex(pts[idx])

    return best_pts

def find_points(seed: int | None = 0) -> list[tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=15000, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

import math
import random
import numpy as np
from itertools import combinations

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / 2.0

def _min_triangle_area(pts):
    min_area = float('inf')
    for trio in combinations(pts, 3):
        a = _area(*trio)
        if a < min_area:
            min_area = a
            if min_area < 1e-8:
                return min_area
    return min_area

def _is_in_triangle(p):
    x, y = p
    if x < 0 or x > 1 or y < 0 or y > SQRT3/2:
        return False
    if y > SQRT3 * x:
        return False
    if y > SQRT3 * (1 - x):
        return False
    return True

def _generate_initial_points(n):
    points = []
    # Generate hexagonal grid points first
    grid_size = 0.2
    for i in range(4):
        for j in range(4):
            if i + j <= 3 and len(points) < n:
                x = 0.1 + i * grid_size + j * grid_size/2
                y = SQRT3/2 * 0.1 + j * grid_size * SQRT3/2
                if _is_in_triangle((x, y)):
                    points.append([x, y])

    # Fill remaining points with random placement
    while len(points) < n:
        x = random.uniform(0.1, 0.9)
        y = random.uniform(0.1, 0.8 * SQRT3/2)
        if _is_in_triangle((x, y)) and all(math.hypot(x-p[0], y-p[1]) > 0.1 for p in points):
            points.append([x, y])

    return np.array(points[:n])  # Ensure exactly n points

def _optimize_points(points, iterations):
    best_points = points.copy()
    best_score = _min_triangle_area(best_points)

    for i in range(iterations):
        new_points = best_points.copy()

        if i % 50 == 0:
            areas = []
            for j in range(len(points)):
                min_local = float('inf')
                for k, l in combinations([x for x in range(len(points)) if x != j], 2):
                    a = _area(points[j], points[k], points[l])
                    if a < min_local:
                        min_local = a
                areas.append(min_local)
            idx = np.argmin(areas)
            new_points[idx] = np.random.uniform(0, 1, 2)
            if not _is_in_triangle(new_points[idx]):
                continue

        idx = random.randint(0, len(points)-1)
        step = 0.05 * (1 - (i/iterations)**2)
        new_points[idx] += np.random.uniform(-step, step, 2)

        if not _is_in_triangle(new_points[idx]):
            x, y = new_points[idx]
            x = max(0.01, min(0.99, x))
            y = max(0.01, min(SQRT3/2 - 0.01, y))
            if y > SQRT3 * x:
                y = SQRT3 * x - 0.01
            if y > SQRT3 * (1 - x):
                y = SQRT3 * (1 - x) - 0.01
            new_points[idx] = [x, y]

        new_score = _min_triangle_area(new_points)

        if new_score > best_score:
            best_score = new_score
            best_points = new_points.copy()

    return best_points

def find_points(seed=None):
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    points = _generate_initial_points(11)
    points = _optimize_points(points, 5000)

    return [(float(p[0]), float(p[1])) for p in points]

