import math
import random
import numpy as np
from scipy.spatial import Delaunay
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p1, p2, p3) -> float:
    return abs((p2[0]-p1[0])*(p3[1]-p1[1]) - (p2[1]-p1[1])*(p3[0]-p1[0])) / (2 * TRIANGLE_AREA)

def _min_triangle_area(pts: np.ndarray) -> float:
    tri = Delaunay(pts)
    min_area = float('inf')
    for simplex in tri.simplices:
        a = _area(pts[simplex[0]], pts[simplex[1]], pts[simplex[2]])
        if a < min_area:
            min_area = a
            if min_area == 0:
                return 0
    return min_area

def _is_inside_triangle(p: np.ndarray) -> bool:
    x, y = p
    if y < 0 or y > SQRT3/2:
        return False
    if x < 0 or x > 1:
        return False
    if y > SQRT3 * x:
        return False
    if y > SQRT3 * (1 - x):
        return False
    return True

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    x, y = p
    if y < 0:
        y = 0
    if y > SQRT3/2:
        y = SQRT3/2
    if x < 0:
        x = 0
    if x > 1:
        x = 1
    if y > SQRT3 * x:
        y = SQRT3 * x
    if y > SQRT3 * (1 - x):
        y = SQRT3 * (1 - x)
    return np.array([x, y])

def _poisson_disk_sampling(n_pts: int = 11, radius: float = 0.2) -> np.ndarray:
    pts = []
    active = []

    def is_valid(p):
        if not _is_inside_triangle(p):
            return False
        for pt in pts:
            if np.linalg.norm(p - pt) < radius:
                return False
        return True

    first = np.array([0.5, SQRT3/4])
    pts.append(first)
    active.append(first)

    while len(pts) < n_pts and len(active) > 0:
        idx = random.randint(0, len(active)-1)
        p = active[idx]
        found = False

        for _ in range(30):
            angle = random.uniform(0, 2*math.pi)
            dist = random.uniform(radius, 2*radius)
            new_p = p + dist * np.array([math.cos(angle), math.sin(angle)])

            if is_valid(new_p):
                pts.append(new_p)
                active.append(new_p)
                found = True
                break

        if not found:
            active.pop(idx)

    while len(pts) < n_pts:
        x = random.uniform(0, 1)
        y = random.uniform(0, SQRT3/2)
        p = np.array([x, y])
        if _is_inside_triangle(p):
            pts.append(p)

    return np.array(pts[:n_pts])

def _optimize_simulated_annealing(pts: np.ndarray, iterations: int = 5000) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)
    current_pts = best_pts.copy()
    current_area = best_area
    n = len(pts)

    temp = 1.0
    cooling_rate = 0.9995

    for iter in range(iterations):
        temp *= cooling_rate
        step_size = 0.05 * temp

        trial = current_pts.copy()
        for i in range(n):
            dx = random.uniform(-step_size, step_size)
            dy = random.uniform(-step_size, step_size)
            trial[i] += [dx, dy]
            trial[i] = _project_to_triangle(trial[i])

        trial_area = _min_triangle_area(trial)

        if trial_area > current_area or random.random() < math.exp((trial_area - current_area)/temp):
            current_area = trial_area
            current_pts = trial.copy()

            if current_area > best_area:
                best_area = current_area
                best_pts = current_pts.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    best_pts = None
    best_area = 0.0

    for _ in range(3):
        pts = _poisson_disk_sampling(11)
        pts = _optimize_simulated_annealing(pts, 5000)

        current_area = _min_triangle_area(pts)
        if current_area > best_area:
            best_area = current_area
            best_pts = pts.copy()

    return [(float(x), float(y)) for x, y in best_pts]

from __future__ import annotations

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / (2 * TRIANGLE_AREA)

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                area = _area(pts[i], pts[j], pts[k])
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0
    return min_area

def _hexagonal_grid(n: int) -> np.ndarray:
    pts = []
    layers = math.ceil(math.sqrt(n / 3)) + 1
    for i in range(-layers, layers+1):
        for j in range(-layers, layers+1):
            x = 0.5 + (i + 0.5*j) * 0.08
            y = SQRT3/3 + j * SQRT3/2 * 0.08
            pts.append([x, y])
    pts = np.array(pts)
    inside = np.array([_is_in_triangle(p) for p in pts])
    pts = pts[inside]
    if len(pts) > n:
        pts = pts[:n]
    while len(pts) < n:
        pts = np.vstack([pts, _random_point_in_triangle()])
    return pts

def _random_point_in_triangle() -> np.ndarray:
    r1 = random.random()
    r2 = random.random()
    if r1 + r2 > 1:
        r1 = 1 - r1
        r2 = 1 - r2
    x = r1 * 1.0 + r2 * 0.5
    y = r2 * SQRT3 / 2.0
    return np.array([x, y])

def _is_in_triangle(p: np.ndarray) -> bool:
    x, y = p
    if y < 0 or y > SQRT3/2:
        return False
    if x < 0 or x > 1:
        return False
    if y > SQRT3 * x or y > SQRT3 * (1 - x):
        return False
    return True

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    x, y = p
    if _is_in_triangle(p):
        return p

    # Bottom edge
    if y <= 0:
        x = max(0.0, min(1.0, x))
        return np.array([x, 0.0])

    # Left edge
    left_y = SQRT3 * x
    # Right edge
    right_y = SQRT3 * (1 - x)

    # Above both edges
    if y > left_y and y > right_y:
        return np.array([0.5, SQRT3/2])

    # Closest edge
    d_left = abs(y - left_y)
    d_right = abs(y - right_y)

    if d_left < d_right:
        new_x = max(0.0, min(0.5, x))
        new_y = SQRT3 * new_x
        return np.array([new_x, new_y])
    else:
        new_x = min(1.0, max(0.5, x))
        new_y = SQRT3 * (1 - new_x)
        return np.array([new_x, new_y])

def _find_smallest_triangle_indices(pts: np.ndarray) -> Tuple[int, int, int]:
    n = len(pts)
    min_area = float('inf')
    best = (0, 1, 2)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                area = _area(pts[i], pts[j], pts[k])
                if area < min_area:
                    min_area = area
                    best = (i, j, k)
                    if min_area == 0:
                        return best
    return best

def _optimize_points(pts: np.ndarray, steps: int = 1000) -> np.ndarray:
    for _ in range(steps):
        i, j, k = _find_smallest_triangle_indices(pts)
        centroid = (pts[i] + pts[j] + pts[k]) / 3
        for idx in [i, j, k]:
            direction = centroid - pts[idx]
            step_size = 0.05 * (1 - _/steps)
            pts[idx] += direction * step_size
            pts[idx] = _project_to_triangle(pts[idx])
    return pts

def _anneal(n_pts: int = 11, iters: int = 5000, seed: int | None = None) -> np.ndarray:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _hexagonal_grid(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        T = max(0.1 * (1 - t/iters), 1e-8)

        if t % 100 == 0:
            pts = _optimize_points(pts.copy(), 100)

        idx = random.randrange(n_pts)
        trial = pts.copy()

        if t % 50 == 0:
            trial[idx] = _random_point_in_triangle()
        else:
            delta = np.random.normal(0, 0.05 * T, size=2)
            trial[idx] += delta
            trial[idx] = _project_to_triangle(trial[idx])

        trial_val = _min_triangle_area(trial)
        if trial_val > best_val or (T > 0 and random.random() < math.exp((trial_val - best_val)/T)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

import math
import random
import itertools
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / 2.0

def _min_triangle_area(pts):
    n = len(pts)
    if n < 3: return 0.0
    min_area = float('inf')
    for i in range(n-2):
        for j in range(i+1, n-1):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0.0
    return min_area

def _barycentric_to_cartesian(u, v):
    w = 1.0 - u - v
    x = w * 0.0 + u * 1.0 + v * 0.5
    y = w * 0.0 + u * 0.0 + v * SQRT3/2
    return (x, y)

def _generate_hexagonal_grid(n):
    pts = []
    layers = int(math.sqrt(n)) + 2
    for i in range(layers):
        for j in range(layers - i):
            u = (i + 0.5 * j) / (layers)
            v = (j * SQRT3 / 2) / (layers)
            if u + v <= 1.0:
                pts.append(_barycentric_to_cartesian(u, v))

    while len(pts) < n:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            pts.append(_barycentric_to_cartesian(u, v))

    return pts[:n]

def _project_to_triangle(x, y):
    v0 = (0.5, SQRT3/2)
    v1 = (1.0, 0.0)
    v2 = (0.0, 0.0)

    def sign(a, b, c):
        return (a[0]-c[0])*(b[1]-c[1])-(a[1]-c[1])*(b[0]-c[0])

    d1 = sign((x,y), v0, v1)
    d2 = sign((x,y), v1, v2)
    d3 = sign((x,y), v2, v0)

    has_neg = (d1 < 0) or (d2 < 0) or (d3 < 0)
    has_pos = (d1 > 0) or (d2 > 0) or (d3 > 0)

    if not (has_neg and has_pos):
        return (x, y)

    def closest_point_on_segment(a, b, p):
        ab = (b[0]-a[0], b[1]-a[1])
        ap = (p[0]-a[0], p[1]-a[1])
        t = max(0, min(1, (ap[0]*ab[0] + ap[1]*ab[1])/(ab[0]**2 + ab[1]**2)))
        return (a[0] + t*ab[0], a[1] + t*ab[1])

    candidates = [
        closest_point_on_segment(v0, v1, (x,y)),
        closest_point_on_segment(v1, v2, (x,y)),
        closest_point_on_segment(v2, v0, (x,y))
    ]

    return min(candidates, key=lambda p: (p[0]-x)**2 + (p[1]-y)**2)

def _optimize_configuration(pts, max_iter=1000):
    best_pts = [p[:] for p in pts]
    best_area = _min_triangle_area(best_pts)
    n = len(pts)

    for iter in range(max_iter):
        T = max(0.01, 0.1 * (1 - iter/max_iter))
        step = max(0.001, 0.05 * (1 - iter/max_iter))

        idx = random.randint(0, n-1)
        new_pts = [p[:] for p in best_pts]
        dx, dy = random.uniform(-step, step), random.uniform(-step, step)
        new_pts[idx] = (new_pts[idx][0] + dx, new_pts[idx][1] + dy)
        new_pts[idx] = _project_to_triangle(*new_pts[idx])

        new_area = _min_triangle_area(new_pts)
        delta = new_area - best_area

        if delta > 0 or (T > 0 and random.random() < math.exp(delta/T)):
            best_pts = new_pts
            best_area = new_area

    return best_pts

def find_points(seed=None):
    if seed is not None:
        random.seed(seed)

    pts = _generate_hexagonal_grid(11)
    pts = _optimize_configuration(pts)

    return [(round(x, 8), round(y, 8)) for x, y in pts]

