import random
import itertools
import numpy as np
from scipy.optimize import differential_evolution

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / 2.0

def _min_triangle_area(pts):
    min_area = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0.0
    return min_area

def _barycentric_to_cartesian(u, v):
    w = 1.0 - u - v
    x = w * 0.0 + u * 1.0 + v * 0.5
    y = w * 0.0 + u * 0.0 + v * (SQRT3/2.0)
    return (x, y)

def _objective_function(params):
    pts = []
    for i in range(11):
        u = params[2*i]
        v = params[2*i+1]
        if u < 0 or v < 0 or u + v > 1.0:
            return 0.0
        pts.append(_barycentric_to_cartesian(u, v))
    return -_min_triangle_area(pts)

def find_points(seed=None):
    bounds = [(0.0, 1.0)] * 22
    for i in range(22):
        if i % 2 == 1:
            bounds[i] = (0.0, 1.0 - 1e-8)

    def constraint(params):
        for i in range(11):
            u = params[2*i]
            v = params[2*i+1]
            if u + v > 1.0:
                return -1.0
        return 1.0

    constraints = {'type': 'ineq', 'fun': constraint}

    result = differential_evolution(
        _objective_function,
        bounds,
        strategy='best1bin',
        maxiter=100,
        popsize=15,
        mutation=(0.5, 1.0),
        recombination=0.7,
        seed=seed,
        constraints=constraints,
        tol=1e-8,
        polish=False
    )

    pts = []
    for i in range(11):
        u = result.x[2*i]
        v = result.x[2*i+1]
        pts.append(_barycentric_to_cartesian(u, v))

    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
MARGIN = 0.001

def _is_inside_triangle(x: float, y: float) -> bool:
    return (MARGIN <= x <= 1-MARGIN and MARGIN <= y <= SQRT3/2-MARGIN and 
            y <= SQRT3*(1 - abs(2*x - 1)) - MARGIN)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    best = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

def _hexagonal_grid(n: int) -> np.ndarray:
    pts = []
    size = int(math.ceil(math.sqrt(n * 2)))
    for i in range(size):
        for j in range(size):
            if len(pts) >= n:
                break
            x = 0.5 + (i - j) * 0.5 / (size + 1)
            y = (j + 0.5 * (i % 2)) * SQRT3 / 2 / (size + 1)
            if _is_inside_triangle(x, y):
                pts.append([x, y])
    while len(pts) < n:
        x = random.uniform(MARGIN, 1-MARGIN)
        y = random.uniform(MARGIN, SQRT3/2-MARGIN)
        if y <= SQRT3*(1 - abs(2*x - 1)) - MARGIN:
            pts.append([x, y])
    return np.array(pts[:n])

def _optimize_points(pts: np.ndarray, iterations: int = 2000) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)
    n = len(pts)

    for _ in range(iterations):
        new_pts = best_pts.copy()
        idx = random.randint(0, n-1)
        step = 0.05 * (1 - _/iterations)
        new_pts[idx] += np.random.uniform(-step, step, 2)

        x, y = new_pts[idx]
        if not _is_inside_triangle(x, y):
            continue

        new_area = _min_triangle_area(new_pts)
        if new_area > best_area:
            best_area = new_area
            best_pts = new_pts.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _hexagonal_grid(11)
    pts = _optimize_points(pts, 2000)

    return [(float(x), float(y)) for x, y in pts[:11]]

