_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _hex_grid_points(n: int) -> np.ndarray:
    pts = []
    k = int(math.sqrt(n)) + 1
    for i in range(k):
        for j in range(k):
            if i + j > k:
                continue
            u = (i + 0.5 * (j % 2)) / k
            v = j * SQRT3 / (2 * k)
            if u + v/SQRT3 <= 1.0 and v <= SQRT3/2:
                pts.append((1-u-v/SQRT3)*_A + u*_B + (v/(SQRT3/2))*_C)
                if len(pts) == n:
                    return np.array(pts)
    return np.array(pts[:n])

