    random.seed(seed)
    np.random.seed(seed)
    pts = _initialize_points(11)
    pts = _optimize_points(pts, 2000)
    return [(float(x), float(y)) for x, y in pts]

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area_fast(pts: np.ndarray) -> float:
    min_area = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            if min_area == 0:
                return 0
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    u, v = random.random(), random.random()
    if u + v > 1.0:
        u, v = 1 - u, 1 - v
    return (1 - u - v) * _A + u * _B + v * _C

def _hexagonal_points(n: int) -> List[np.ndarray]:
    k = int(math.sqrt(n * 2 / SQRT3)) + 1
    points = []
    for i in range(k):
        for j in range(k):
            if i + j > k:
                continue
            x = (i + 0.5 * (j % 2)) / k
            y = (j * SQRT3 / 2) / k
            if y > SQRT3 * (1 - x) or y > SQRT3 * x:
                continue
            points.append(np.array([x, y]))
            if len(points) >= n:
                return points
    return points

def _optimize_points(pts: np.ndarray, max_iter: int = 500) -> np.ndarray:
    n = len(pts)
    best_pts = pts.copy()
    best_area = _min_triangle_area_fast(best_pts)

    for iter in range(max_iter):
        step = 0.01 * (1 - iter/max_iter)
        improved = False
        for i in range(n):
            for dx, dy in [(step,0), (-step,0), (0,step), (0,-step)]:
                new_pts = best_pts.copy()
                new_pts[i] += np.array([dx, dy])
                x, y = new_pts[i]
                if y < 0 or y > SQRT3/2 or x < 0 or x > 1 or y > SQRT3*(1 - abs(2*x - 1)):
                    continue

                area = _min_triangle_area_fast(new_pts)
                if area > best_area:
                    best_area = area
                    best_pts = new_pts.copy()
                    improved = True
        if not improved and step < 0.001:
            break
    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)

    # Start with hexagonal points
    pts = np.array(_hexagonal_points(11))

    # Try fewer random configurations
    for _ in range(5):
        candidate = np.array([_random_point() for _ in range(11)])
        candidate_area = _min_triangle_area_fast(candidate)
        if candidate_area > _min_triangle_area_fast(pts):
            pts = candidate

    # Single optimization pass with fewer iterations
    pts = _optimize_points(pts, max_iter=300)

    return [(float(x), float(y)) for x, y in pts]

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
AREA_TRIANGLE = SQRT3 / 4.0

def _area_fast(pts: np.ndarray, indices: Tuple[int, int, int]) -> float:
    p, q, r = pts[indices[0]], pts[indices[1]], pts[indices[2]]
    return abs((q[0] - p[0])*(r[1] - p[1]) - (q[1] - p[1])*(r[0] - p[0])) * 0.5

def _min_triangle_area_fast(pts: np.ndarray) -> float:
    n = len(pts)
    if n < 3: return 0.0
    best = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area_fast(pts, (i,j,k))
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

def _barycentric_to_cartesian(u: float, v: float) -> Tuple[float, float]:
    x = u + 0.5 * v
    y = SQRT3/2 * v
    return (x, y)

def _cartesian_to_barycentric(x: float, y: float) -> Tuple[float, float]:
    v = 2 * y / SQRT3
    u = x - 0.5 * v
    return (u, v)

def _is_in_triangle(u: float, v: float) -> bool:
    return u >= 0 and v >= 0 and (1 - u - v) >= 0

def _initial_configuration() -> np.ndarray:
    points = []
    # Add points in a grid pattern with barycentric coordinates
    for u in np.linspace(0.1, 0.9, 4):
        for v in np.linspace(0.1, 0.9 - u, 4):
            if _is_in_triangle(u, v):
                x, y = _barycentric_to_cartesian(u, v)
                points.append((x, y))
                if len(points) >= 11:
                    return np.array(points)
    # If not enough points, add some on the boundary
    for t in np.linspace(0.1, 0.9, 11 - len(points)):
        u = t
        v = 1 - t
        x, y = _barycentric_to_cartesian(u, v)
        points.append((x, y))
    return np.array(points[:11])

def _optimize_sa_fast(pts: np.ndarray, iterations: int, temp: float) -> np.ndarray:
    current = pts.copy()
    current_val = _min_triangle_area_fast(current)
    best = current.copy()
    best_val = current_val

    for step in range(iterations):
        temp = temp * 0.9995

        candidate = current.copy()
        idx = random.randrange(len(pts))

        # Work in barycentric coordinates
        x, y = candidate[idx]
        u, v = _cartesian_to_barycentric(x, y)

        # Generate new point strictly inside triangle
        while True:
            du = random.uniform(-0.05, 0.05)
            dv = random.uniform(-0.05, 0.05)
            new_u = u + du
            new_v = v + dv
            if _is_in_triangle(new_u, new_v):
                break

        new_x, new_y = _barycentric_to_cartesian(new_u, new_v)
        candidate[idx] = (new_x, new_y)

        candidate_val = _min_triangle_area_fast(candidate)

        if candidate_val > current_val or random.random() < math.exp((candidate_val - current_val)/temp):
            current = candidate
            current_val = candidate_val
            if current_val > best_val:
                best = current.copy()
                best_val = current_val

    return best

def _validate_points(pts: List[Tuple[float, float]]) -> bool:
    for x, y in pts:
        u, v = _cartesian_to_barycentric(x, y)
        if not _is_in_triangle(u, v):
            return False
    return True

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    # Generate multiple candidates and pick the best
    best_pts = None
    best_val = 0.0

    for _ in range(3):
        pts = _initial_configuration()
        pts = _optimize_sa_fast(pts, 5000, 0.1)
        pts = _optimize_sa_fast(pts, 3000, 0.01)
        val = _min_triangle_area_fast(pts)
        if val > best_val and _validate_points(pts):
            best_pts = pts
            best_val = val

    if best_pts is None:
        best_pts = _initial_configuration()

    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in best_pts]

