def _min_triangle_area(pts: np.ndarray) -> float:
    best = float("inf")
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _hex_grid_points(n: int) -> np.ndarray:
    pts = []
    k = int(math.sqrt(n)) + 1
    for i in range(k):
        for j in range(k):
            if i + j > k:
                continue
            u = (i + 0.5 * (j % 2)) / k
            v = j * SQRT3 / (2 * k)
            if u + v/SQRT3 <= 1.0 and v <= SQRT3/2:
                pts.append((1-u-v/SQRT3)*_A + u*_B + (v/(SQRT3/2))*_C)
                if len(pts) == n:
                    return np.array(pts)
    return np.array(pts[:n])

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    w = 1.0 - u - v
    if u >= 0 and v >= 0 and w >= 0:
        return p
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        s = u + v
        u /= s
        v /= s
    return (1 - u - v) * _A + u * _B + v * _C

def _anneal(n_pts: int = 11,
            iters: int = 8000,
            start_temp: float = 0.5,
            end_temp: float = 1e-8,
            seed: int | None = 0) -> np.ndarray:
    rng = random.Random(seed)
    pts = _hex_grid_points(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        T = start_temp * (end_temp / start_temp) ** (t / (iters - 1))
        trial = pts.copy()

        step_size = 0.02 * (1 - t/iters) + 0.005
        n_changes = 1 if t > iters//2 else 3

        for _ in range(n_changes):
            idx = rng.randrange(n_pts)
            if t % 100 == 0:
                trial[idx] = _hex_grid_points(1)[0]
            else:
                dx = rng.uniform(-step_size, step_size)
                dy = rng.uniform(-step_size, step_size)
                trial[idx] += np.array([dx, dy])
                trial[idx] = _project_to_simplex(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or rng.random() < math.exp(delta / max(T, 1e-12)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=10000, seed=seed)
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _area(p1, p2, p3):
    return abs((p2[0]-p1[0])*(p3[1]-p1[1]) - (p2[1]-p1[1])*(p3[0]-p1[0])) / (2 * TRIANGLE_AREA)

def _min_triangle_area(pts):
    n = len(pts)
    min_area = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0.0
    return min_area

def _random_point():
    while True:
        x = random.random()
        y = random.random() * SQRT3/2
        if y <= SQRT3 * x and y <= SQRT3 * (1 - x):
            return np.array([x, y])

def _hexagonal_grid(n):
    k = math.ceil(math.sqrt(n / (SQRT3/2)))
    points = []
    for i in range(k):
        for j in range(k):
            x = (i + 0.5 * (j % 2)) / k
            y = (j * SQRT3 / 2) / k
            if y <= SQRT3 * x and y <= SQRT3 * (1 - x):
                points.append([x, y])
                if len(points) == n:
                    return points
    return points[:n]

def _optimize_point(pts, idx, step_size):
    best_pt = pts[idx].copy()
    best_area = _min_triangle_area(pts)

    for _ in range(10):
        direction = np.random.normal(0, 1, 2)
        direction /= np.linalg.norm(direction)
        new_pt = best_pt + step_size * direction

        # Ensure point stays in triangle
        if not (new_pt[1] <= SQRT3 * new_pt[0] and new_pt[1] <= SQRT3 * (1 - new_pt[0])):
            continue

        new_pts = pts.copy()
        new_pts[idx] = new_pt
        new_area = _min_triangle_area(new_pts)

        if new_area > best_area:
            best_pt = new_pt
            best_area = new_area

    return best_pt

def find_points(seed=None):
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    # Initialize with hexagonal grid plus small random perturbations
    pts = np.array(_hexagonal_grid(11))
    pts += np.random.uniform(-0.02, 0.02, (11, 2))

    # Project points back to triangle
    for i in range(len(pts)):
        x, y = pts[i]
        if y > SQRT3 * x or y > SQRT3 * (1 - x):
            pts[i] = _random_point()

    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)

    step_size = 0.02
    temperature = 0.1

    for iteration in range(2000):
        if iteration % 100 == 0:
            step_size *= 0.9
            temperature *= 0.9

        # Choose worst point to optimize
        current_area = _min_triangle_area(pts)
        if iteration % 10 == 0:
            idx = random.randrange(len(pts))
        else:
            # Find point involved in smallest triangles
            min_areas = []
            for i in range(len(pts)):
                min_a = float('inf')
                for j in range(len(pts)):
                    for k in range(j+1, len(pts)):
                        if i != j and i != k:
                            a = _area(pts[i], pts[j], pts[k])
                            if a < min_a:
                                min_a = a
                min_areas.append(min_a)
            idx = np.argmin(min_areas)

        new_pt = _optimize_point(pts, idx, step_size)
        new_pts = pts.copy()
        new_pts[idx] = new_pt
        new_area = _min_triangle_area(new_pts)

        # Simulated annealing acceptance
        if new_area > current_area or random.random() < math.exp((new_area - current_area)/temperature):
            pts = new_pts
            if new_area > best_area:
                best_pts = new_pts.copy()
                best_area = new_area

    return [(float(x), float(y)) for x, y in best_pts]

