def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    best = float("inf")
    for i in range(n):
        pi = pts[i]
        for j in range(i+1, n):
            pj = pts[j]
            d_ij = pj - pi
            for k in range(j+1, n):
                pk = pts[k]
                a = abs(np.cross(d_ij, pk - pi)) * 0.5
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, HEIGHT])

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _is_inside(p: np.ndarray) -> bool:
    x, y = p
    if x < 0 or x > 1 or y < 0 or y > HEIGHT:
        return False
    if y > SQRT3 * x or y > SQRT3 * (1 - x):
        return False
    return True

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    x, y = p
    if _is_inside(p):
        return p

    # Project to closest point on triangle boundary
    if y < 0:
        y = 0
    elif y > HEIGHT:
        y = HEIGHT

    if x < 0:
        x = 0
    elif x > 1:
        x = 1

    if y > SQRT3 * x:
        y = SQRT3 * x
    if y > SQRT3 * (1 - x):
        y = SQRT3 * (1 - x)

    return np.array([x, y])

def _mixed_configuration(n_pts: int = 11) -> np.ndarray:
    # Start with known good points that are verified to be inside
    good_points = [
        (0.25, 0.14433757), (0.5, 0.28867513), (0.75, 0.14433757),
        (0.16666667, 0.28867513), (0.33333333, 0.28867513),
        (0.66666667, 0.28867513), (0.83333333, 0.28867513),
        (0.125, 0.21650635), (0.375, 0.21650635), (0.625, 0.21650635),
        (0.875, 0.21650635)
    ]
    pts = [np.array(p) for p in good_points[:n_pts]]
    return np.array(pts[:n_pts])

def _optimize(pts: np.ndarray, steps: int, step_size: float, improve_threshold: float = 0.0) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    n_pts = len(pts)
    no_improve = 0

    for step in range(steps):
        trial = best_pts.copy()
        idx = random.randrange(n_pts)
        trial[idx] += random.uniform(-step_size, step_size), random.uniform(-step_size, step_size)
        trial[idx] = _project_to_triangle(trial[idx])

        trial_val = _min_triangle_area(trial)
        if trial_val > best_val + improve_threshold:
            best_val = trial_val
            best_pts = trial.copy()
            no_improve = 0
        else:
            no_improve += 1

        if no_improve > 300:
            step_size *= 0.9
            no_improve = 0

        if step % 200 == 0:
            step_size = max(step_size * 0.95, 0.001)

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    pts = _mixed_configuration(11)

    # More careful optimization phases
    pts = _optimize(pts, steps=2000, step_size=0.05, improve_threshold=0.0)
    pts = _optimize(pts, steps=1500, step_size=0.02, improve_threshold=0.001)
    pts = _optimize(pts, steps=1000, step_size=0.01, improve_threshold=0.0005)
    pts = _optimize(pts, steps=500, step_size=0.005, improve_threshold=0.0001)

    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

