    if x < -EPS or x > 1+EPS or y < -EPS:
        return False
    if y > (SQRT3 * 0.5) + EPS:
        return False
    if y > SQRT3 * x + EPS:
        return False
    if y > SQRT3 * (1 - x) + EPS:
        return False
    return True

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    x, y = p
    if _is_in_triangle(p):
        return p

    x = max(0.0, min(1.0, x))
    y = max(0.0, min(SQRT3 * 0.5, y))

    if y > SQRT3 * x:
        y = SQRT3 * x
    if y > SQRT3 * (1 - x):
        y = SQRT3 * (1 - x)

    return np.array([x, y])

def _generate_initial_points(n_pts: int = 11) -> np.ndarray:
    pts = []
    for _ in range(n_pts):
        while True:
            pt = _random_point()
            valid = True
            for existing in pts:
                if np.linalg.norm(pt - existing) < 0.1:
                    valid = False
                    break
            if valid:
                pts.append(pt)
                break
    return np.array(pts)

def _anneal(n_pts: int = 11,
            iters: int = 15000,
            start_temp: float = 0.1,
            end_temp: float = 1e-8,
            seed: int | None = None) -> np.ndarray:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _generate_initial_points(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        T = start_temp * (end_temp / start_temp) ** (t / max(iters-1, 1))
        step_size = 0.1 * (1 - t/iters) + 0.001
        idx = random.randrange(n_pts)
        trial = pts.copy()
        trial[idx] += np.random.uniform(-step_size, step_size, size=2)
        trial[idx] = _project_to_triangle(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or random.random() < math.exp(delta / max(T, 1e-12)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

    return best_pts

def _local_search(pts: np.ndarray, steps: int = 2000) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    n_pts = len(pts)

    for step_idx in range(steps):
        trial = best_pts.copy()
        idx = random.randrange(n_pts)
        step = 0.02 * (1 - step_idx/steps)
        trial[idx] += np.random.uniform(-step, step, size=2)
        trial[idx] = _project_to_triangle(trial[idx])
        trial_val = _min_triangle_area(trial)
        if trial_val > best_val:
            best_val = trial_val
            best_pts = trial.copy()

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=15000, seed=seed)
    pts = _local_search(pts, steps=2000)
    return [(float(x), float(y)) for x, y in pts]

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    best = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

def _is_in_triangle(x: float, y: float) -> bool:
    return (0 <= x <= 1 and 0 <= y <= SQRT3/2 and 
            y <= SQRT3*(1 - abs(2*x - 1)))

def _hexagonal_grid(n: int) -> np.ndarray:
    pts = []
    size = int(math.ceil(math.sqrt(n)))
    for i in range(size):
        for j in range(size):
            if len(pts) >= n:
                break
            x = 0.5 + (i - j) * 0.5 / size
            y = j * SQRT3 / 2 / size
            if _is_in_triangle(x, y):
                pts.append([x, y])
    while len(pts) < n:
        x = random.uniform(0, 1)
        y = random.uniform(0, SQRT3/2)
        if _is_in_triangle(x, y):
            pts.append([x, y])
    return np.array(pts)

def _optimize_points(pts: np.ndarray, iterations: int = 2000) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)
    n = len(pts)

    for _ in range(iterations):
        new_pts = best_pts.copy()
        idx = random.randint(0, n-1)
        step = 0.05 * (1 - _/iterations)
        new_pts[idx] += np.random.uniform(-step, step, 2)

        x, y = new_pts[idx]
        if not _is_in_triangle(x, y):
            continue

        new_area = _min_triangle_area(new_pts)
        if new_area > best_area:
            best_area = new_area
            best_pts = new_pts.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _hexagonal_grid(11)
    pts = _optimize_points(pts, 2000)

    return [(float(x), float(y)) for x, y in pts]

import math
import random
import numpy as np
from itertools import combinations
from scipy.spatial import KDTree

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / 2.0

def _min_triangle_area(pts, kdtree=None):
    if kdtree is None:
        kdtree = KDTree(pts)
    min_area = float('inf')
    n = len(pts)

    for i in range(n):
        neighbors = kdtree.query_ball_point(pts[i], 0.3)
        if len(neighbors) < 2:
            continue
        for j, k in combinations(neighbors, 2):
            if j <= i or k <= j:
                continue
            a = _area(pts[i], pts[j], pts[k])
            if a < min_area:
                min_area = a
                if min_area < 1e-8:
                    return min_area
    return min_area

def _is_in_triangle(p):
    x, y = p
    if x < 0 or x > 1 or y < 0 or y > SQRT3/2:
        return False
    if y > SQRT3 * x:
        return False
    if y > SQRT3 * (1 - x):
        return False
    return True

def _generate_hexagonal_points(n):
    points = []
    layers = int(math.sqrt(n)) + 1

    for layer in range(layers):
        radius = 0.5 * layer / layers
        if layer == 0:
            points.append([0.5, SQRT3/6])
            if len(points) >= n:
                break
            continue

        points_per_side = 6 * layer
        for i in range(points_per_side):
            angle = 2 * math.pi * i / points_per_side
            x = 0.5 + radius * math.cos(angle)
            y = SQRT3/6 + radius * math.sin(angle)
            if _is_in_triangle((x, y)):
                points.append([x, y])
                if len(points) >= n:
                    break
        if len(points) >= n:
            break

    while len(points) < n:
        x = random.uniform(0, 1)
        y = random.uniform(0, SQRT3/2)
        if _is_in_triangle((x, y)) and not any(math.hypot(x-p[0], y-p[1]) < 0.05 for p in points):
            points.append([x, y])

    return np.array(points[:n])

def _optimize_simulated_annealing(points, iterations):
    current_points = points.copy()
    kdtree = KDTree(current_points)
    current_score = _min_triangle_area(current_points, kdtree)

    best_points = current_points.copy()
    best_score = current_score

    temperature = 0.1
    cooling_rate = 0.9995

    for i in range(iterations):
        temp_points = current_points.copy()
        idx = random.randint(0, len(points)-1)

        step = 0.05 * (1 - i/iterations) * temperature

        perturbation = np.random.uniform(-step, step, 2)
        new_point = temp_points[idx] + perturbation

        if not _is_in_triangle(new_point):
            continue

        temp_points[idx] = new_point
        new_kdtree = KDTree(temp_points)
        new_score = _min_triangle_area(temp_points, new_kdtree)

        if new_score > current_score or random.random() < math.exp((new_score - current_score)/temperature):
            current_points = temp_points
            current_score = new_score
            kdtree = new_kdtree

            if new_score > best_score:
                best_points = current_points.copy()
                best_score = new_score

        temperature *= cooling_rate

    return best_points

def find_points(seed=None):
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    points = _generate_hexagonal_points(11)
    points = _optimize_simulated_annealing(points, 5000)

    return [(float(p[0]), float(p[1])) for p in points]

from __future__ import annotations
import math
import random
import numpy as np
try:
    from scipy.optimize import minimize
except ImportError:
    minimize = None

SQRT3 = math.sqrt(3.0)
_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    best = float("inf")
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best < 1e-6:
                        return best
    return best

def _random_point() -> np.ndarray:
    u, v = random.random(), random.random()
    if u + v > 1.0:
        u, v = 1-u, 1-v
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _initial_configuration(n_pts: int) -> np.ndarray:
    pts = []
    layers = int(math.sqrt(n_pts)) + 2
    for i in range(layers):
        for j in range(layers - i):
            u = (i + 0.5) / layers
            v = (j + 0.5) / layers
            if len(pts) < n_pts:
                pts.append((1 - u - v) * _A + u * _B + v * _C)
    while len(pts) < n_pts:
        pts.append(_random_point())
    return np.array(pts)

def _anneal(n_pts: int = 11, iters: int = 2000, restarts: int = 5, seed: int = 0) -> np.ndarray:
    rng = random.Random(seed)
    best_pts = _initial_configuration(n_pts)
    best_val = _min_triangle_area(best_pts)

    for _ in range(restarts):
        pts = _initial_configuration(n_pts)
        current_val = _min_triangle_area(pts)

        for t in range(iters):
            T = max(0.01, 0.1 * (1 - t/iters))
            step_size = 0.05 * T

            idx = rng.randrange(n_pts)
            trial = pts.copy()
            trial[idx] += rng.uniform(-step_size, step_size), rng.uniform(-step_size, step_size)
            trial[idx] = _project_to_simplex(trial[idx])

            trial_val = _min_triangle_area(trial)
            delta = trial_val - current_val

            if delta > 0 or rng.random() < math.exp(delta / max(T, 1e-12)):
                pts = trial
                current_val = trial_val

                if current_val > best_val:
                    best_val = current_val
                    best_pts = pts.copy()

    return best_pts

def _local_polish(pts: np.ndarray) -> np.ndarray:
    if minimize is None or len(pts) == 0:
        return pts
    n_pts = len(pts)
    x0 = pts.ravel()

    def f(x: np.ndarray) -> float:
        P = x.reshape((-1, 2))
        return -_min_triangle_area(P)

    res = minimize(f, x0, method='Nelder-Mead', options={'maxiter': 500})
    if res.success:
        out = res.x.reshape((n_pts, 2))
        for i in range(n_pts):
            out[i] = _project_to_simplex(out[i])
        return out
    return pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=2000, restarts=5, seed=seed)
    pts = _local_polish(pts)
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
AREA_TRIANGLE = SQRT3 / 4.0

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    if n < 3: return 0.0
    best = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

def _barycentric_to_cartesian(u: float, v: float) -> Tuple[float, float]:
    w = 1.0 - u - v
    x = 0.0 * w + 1.0 * u + 0.5 * v
    y = 0.0 * w + 0.0 * u + (SQRT3/2) * v
    return (x, y)

def _cartesian_to_barycentric(x: float, y: float) -> Tuple[float, float]:
    v = 2 * y / SQRT3
    u = x - 0.5 * v
    return (u, v)

def _is_in_triangle(u: float, v: float) -> bool:
    return u > 0 and v > 0 and (1 - u - v) > 0

def _hexagonal_grid(n: int) -> np.ndarray:
    points = []
    layers = math.ceil((math.sqrt(8*n/3 + 1) - 1)/2)
    scale = 1.0 / (2 * layers)

    for i in range(layers):
        for j in range(layers - i):
            u = (i + 0.5 * j + 0.5) * scale
            v = (j * SQRT3/2 + SQRT3/4) * scale
            if _is_in_triangle(u, v):
                points.append(_barycentric_to_cartesian(u, v))

    while len(points) < n:
        u = random.uniform(0.01, 0.99)
        v = random.uniform(0.01, 0.99)
        if _is_in_triangle(u, v):
            points.append(_barycentric_to_cartesian(u, v))

    return np.array(points[:n])

def _optimize_sa(pts: np.ndarray, iterations: int, temp: float) -> np.ndarray:
    current = pts.copy()
    current_val = _min_triangle_area(current)
    best = current.copy()
    best_val = current_val

    bary = np.array([_cartesian_to_barycentric(x, y) for x, y in current])

    for i in range(iterations):
        temp = temp * 0.9995

        candidate = current.copy()
        candidate_bary = bary.copy()
        idx = random.randrange(len(pts))

        step = 0.02 * temp
        while True:
            du = random.uniform(-step, step)
            dv = random.uniform(-step, step)
            new_u = bary[idx][0] + du
            new_v = bary[idx][1] + dv

            if _is_in_triangle(new_u, new_v):
                candidate_bary[idx] = (new_u, new_v)
                new_x, new_y = _barycentric_to_cartesian(new_u, new_v)
                candidate[idx] = (new_x, new_y)
                break

        candidate_val = _min_triangle_area(candidate)

        if candidate_val > current_val:
            accept_prob = 1.0
        else:
            delta = candidate_val - current_val
            accept_prob = math.exp(10 * delta / temp)

        if random.random() < accept_prob:
            current = candidate
            current_val = candidate_val
            bary = candidate_bary

            if current_val > best_val:
                best = current.copy()
                best_val = current_val

    return best

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    pts = _hexagonal_grid(11)
    pts = _optimize_sa(pts, 10000, 0.5)

    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

from __future__ import annotations

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area_fast(pts: np.ndarray, cutoff: float = 0) -> float:
    n = len(pts)
    best = float('inf')
    for i in range(n-2):
        for j in range(i+1, n-1):
            p = pts[i]
            q = pts[j]
            for k in range(j+1, n):
                a = abs(np.cross(q - p, pts[k] - p)) * 0.5
                if a <= cutoff:
                    return a
                if a < best:
                    best = a
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _is_in_triangle(p: np.ndarray) -> bool:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    return u >= -1e-8 and v >= -1e-8 and (u + v) <= 1.0 + 1e-8

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        total = u + v
        u /= total
        v /= total
    return (1 - u - v) * _A + u * _B + v * _C

def _initial_configuration(n_pts: int = 11) -> np.ndarray:
    pts = []
    layers = 3
    for i in range(layers):
        for j in range(layers - i):
            u = (i + 0.5 * (j % 2)) / (layers - 0.5)
            v = j / (layers - 0.5)
            if u + v <= 1.0:
                pts.append((1 - u - v) * _A + u * _B + v * _C)
    pts.append((1 - 1/3 - 1/3) * _A + 1/3 * _B + 1/3 * _C)
    while len(pts) < n_pts:
        pts.append(_random_point())
    return np.array(pts[:n_pts])

def _optimize(n_pts: int = 11, iters: int = 8000, seed: int | None = 0) -> np.ndarray:
    rng = random.Random(seed)
    pts = _initial_configuration(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area_fast(best_pts)

    for t in range(iters):
        T = max(0.1 * (1 - (t/iters)**0.7), 1e-6)
        idx = rng.randrange(n_pts)
        trial = pts.copy()
        step = 0.03 * (1 - (t/iters)**0.5)
        trial[idx] += rng.uniform(-step, step), rng.uniform(-step, step)
        trial[idx] = _project_to_simplex(trial[idx])

        if not _is_in_triangle(trial[idx]):
            continue

        trial_val = _min_triangle_area_fast(trial, best_val)
        if trial_val <= best_val and rng.random() >= math.exp((trial_val - best_val)/T):
            continue

        pts = trial
        if trial_val > best_val:
            best_val = trial_val
            best_pts = trial.copy()

    # Final validation and correction
    for i in range(len(best_pts)):
        if not _is_in_triangle(best_pts[i]):
            best_pts[i] = _project_to_simplex(best_pts[i])

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _optimize(n_pts=11, iters=8000, seed=seed)
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

from __future__ import annotations

import math
import random
import numpy as np
from typing import List, Tuple
from scipy.spatial import Delaunay

SQRT3 = math.sqrt(3.0)

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    u, v = random.random(), random.random()
    if u + v > 1.0:
        u, v = 1 - u, 1 - v
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = 1 - u, 1 - v
    return (1 - u - v) * _A + u * _B + v * _C

def _min_triangle_area(pts: np.ndarray) -> float:
    tri = Delaunay(pts)
    min_area = float('inf')
    for simplex in tri.simplices:
        a, b, c = pts[simplex]
        area = 0.5 * abs((b[0]-a[0])*(c[1]-a[1]) - (b[1]-a[1])*(c[0]-a[0]))
        if area < min_area:
            min_area = area
            if min_area == 0:
                return 0.0
    return min_area

def _optimize_points(pts: np.ndarray, iterations: int = 2000) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)
    step_size = 0.05

    for iter in range(iterations):
        improved = False
        angular_steps = max(8, min(24, int(24 * step_size / 0.05)))

        for i in range(len(pts)):
            for angle in np.linspace(0, 2*np.pi, angular_steps, endpoint=False):
                dx, dy = step_size * math.cos(angle), step_size * math.sin(angle)
                trial = best_pts.copy()
                trial[i] += np.array([dx, dy])
                trial[i] = _project_to_simplex(trial[i])

                # Only compute area if point moved significantly
                if np.linalg.norm(trial[i] - best_pts[i]) > step_size * 0.1:
                    trial_area = _min_triangle_area(trial)
                    if trial_area > best_area:
                        best_area = trial_area
                        best_pts = trial.copy()
                        improved = True

        if not improved:
            step_size *= 0.7
            if step_size < 0.0001:
                break

        # Adaptive random perturbation
        if random.random() < 0.1 + 0.1 * (iter / iterations):
            perturbation_size = step_size * (0.3 + 0.7 * (iter / iterations))
            best_pts = best_pts + np.random.normal(0, perturbation_size, best_pts.shape)
            for i in range(len(best_pts)):
                best_pts[i] = _project_to_simplex(best_pts[i])
            current_area = _min_triangle_area(best_pts)
            if current_area > best_area:
                best_area = current_area

    return best_pts

def _initialize_points(n: int) -> np.ndarray:
    # Try hexagonal grid first
    pts = []
    grid_size = int(math.ceil(math.sqrt(n)))
    for i in range(grid_size):
        for j in range(grid_size):
            if len(pts) >= n:
                break
            x = (i + 0.5 * (j % 2)) / grid_size
            y = (j * SQRT3 / 2) / grid_size
            p = np.array([x, y])
            if x + y/SQRT3 <= 1 and (1-x) + y/SQRT3 <= 1:
                pts.append(p)

    # Fill remaining points randomly if needed
    while len(pts) < n:
        p = _random_point()
        valid = True
        for q in pts:
            if np.linalg.norm(p - q) < 0.15:
                valid = False
                break
        if valid:
            pts.append(p)
    return np.array(pts)

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)
    pts = _initialize_points(11)
    pts = _optimize_points(pts, 2500)  # Slightly more iterations
    return [(float(x), float(y)) for x, y in pts]

