SQRT3 = math.sqrt(3.0)
INV_SQRT3 = 1.0 / SQRT3

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5

def _min_triangle_area(pts):
    n = len(pts)
    min_area = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                area = _area(pts[i], pts[j], pts[k])
                if area < min_area:
                    min_area = area
                    if min_area < 1e-8:
                        return 0
    return min_area

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _hexagonal_points(n):
    pts = []
    layers = math.ceil(math.sqrt(n / 3)) + 1
    for i in range(-layers, layers+1):
        for j in range(max(-layers, -i-layers), min(layers, -i+layers)+1):
            x = 0.5 + 0.5 * i + 0.5 * j
            y = INV_SQRT3 * 0.5 * j
            pts.append((x, y))
    pts = [p for p in pts if (0 <= p[0] <= 1 and 0 <= p[1] <= SQRT3/2 and 
           p[1] <= SQRT3 * (1 - abs(2*p[0]-1)))]
    return pts[:n]

def _project_to_simplex(p):
    u = p[0]
    v = p[1] * 2 / SQRT3
    if u + v <= 1 and u >= 0 and v >= 0:
        return p
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (u, v * SQRT3 / 2)

def _anneal(n_pts=11, iters=5000, seed=None):
    random.seed(seed)
    if n_pts == 11:
        pts = np.array(_hexagonal_points(n_pts))
    else:
        pts = np.array([_random_point() for _ in range(n_pts)])
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        T = max(0.01, 0.1 * math.exp(-5.0 * t/iters))
