import math
import random
import itertools
from typing import List, Tuple
import numpy as np

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0
EPS = 1e-10

def _area(p, q, r) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5 / TRIANGLE_AREA

def _min_triangle_area(pts: np.ndarray) -> float:
    best = float("inf")
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best < EPS:
                        return 0.0
    return best

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    x = u + v * 0.5
    y = v * SQRT3 * 0.5
    return np.array([x, y])

def _is_in_triangle(p: np.ndarray) -> bool:
    x, y = p
    if x < -EPS or x > 1+EPS or y < -EPS:
        return False
    if y > (SQRT3 * 0.5) + EPS:
        return False
    if y > SQRT3 * x + EPS:
        return False
    if y > SQRT3 * (1 - x) + EPS:
        return False
    return True

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    x, y = p
    if _is_in_triangle(p):
        return p

    x = max(0.0, min(1.0, x))
    y = max(0.0, min(SQRT3 * 0.5, y))

    if y > SQRT3 * x:
        y = SQRT3 * x
    if y > SQRT3 * (1 - x):
        y = SQRT3 * (1 - x)

    return np.array([x, y])

def _generate_initial_points(n_pts: int = 11) -> np.ndarray:
    # Hexagonal grid initialization
    pts = []
    grid_size = int(math.ceil(math.sqrt(n_pts * 2 / SQRT3)))
    for i in range(grid_size):
        for j in range(grid_size):
            if len(pts) >= n_pts:
                break
            x = (i + 0.5 * (j % 2)) / (grid_size - 0.5)
            y = j * SQRT3 * 0.5 / (grid_size - 0.5)
            if _is_in_triangle(np.array([x, y])):
                pts.append(np.array([x, y]))

    # Fill remaining points randomly if needed
    while len(pts) < n_pts:
        pts.append(_random_point())

    return np.array(pts[:n_pts])

def _anneal(n_pts: int = 11,
            iters: int = 20000,
            start_temp: float = 0.15,
            end_temp: float = 1e-10,
            seed: int | None = None) -> np.ndarray:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _generate_initial_points(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        T = start_temp * (end_temp / start_temp) ** (t / max(iters-1, 1))
        step_size = 0.15 * (1 - t/iters) + 0.005
        idx = random.randrange(n_pts)
        trial = pts.copy()
        trial[idx] += np.random.normal(0, step_size, size=2)
        trial[idx] = _project_to_triangle(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or random.random() < math.exp(delta / max(T, 1e-12)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

    return best_pts

def _local_search(pts: np.ndarray, steps: int = 3000) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    n_pts = len(pts)

    for step_idx in range(steps):
        trial = best_pts.copy()
        idx = random.randrange(n_pts)
        step = 0.03 * (1 - step_idx/steps) + 0.001
        trial[idx] += np.random.normal(0, step, size=2)
        trial[idx] = _project_to_triangle(trial[idx])
        trial_val = _min_triangle_area(trial)
        if trial_val > best_val:
            best_val = trial_val
            best_pts = trial.copy()

    return best_pts

def _optimize_smallest(pts: np.ndarray, steps: int = 1000) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    n = len(pts)

    for _ in range(steps):
        # Find the smallest triangle
        min_area = float('inf')
        min_indices = (0, 1, 2)
        for i in range(n):
            for j in range(i+1, n):
                for k in range(j+1, n):
                    a = _area(pts[i], pts[j], pts[k])
                    if a < min_area:
                        min_area = a
                        min_indices = (i, j, k)

        # Try to improve this triangle
        for idx in min_indices:
            trial = best_pts.copy()
            step = 0.01
            trial[idx] += np.random.uniform(-step, step, size=2)
            trial[idx] = _project_to_triangle(trial[idx])
            trial_val = _min_triangle_area(trial)
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=20000, seed=seed)
    pts = _local_search(pts, steps=3000)
    pts = _optimize_smallest(pts, steps=1000)
    return [(float(x), float(y)) for x, y in pts]

