import math
import random
import numpy as np
from scipy.optimize import minimize
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0.0
    return min_area

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _initial_grid(n: int) -> np.ndarray:
    k = math.ceil(math.sqrt(n * 2))
    pts = []
    for i in range(k):
        for j in range(k - i):
            u = (i + 0.5) / k
            v = (j + 0.5) / k
            if u + v <= 1.0:
                pts.append((1 - u - v) * _A + u * _B + v * _C)
    while len(pts) < n:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            pts.append((1 - u - v) * _A + u * _B + v * _C)
    return np.array(pts[:n])

def _optimize_points(pts: np.ndarray, max_iter: int = 1000) -> np.ndarray:
    n = len(pts)

    def objective(x):
        pts = x.reshape(-1, 2)
        return -_min_triangle_area(pts)

    bounds = [(0, 1), (0, SQRT3/2)] * n
    x0 = pts.flatten()

    res = minimize(objective, x0, method='L-BFGS-B', bounds=bounds, 
                  options={'maxiter': max_iter, 'ftol': 1e-8})

    return res.x.reshape(-1, 2)

def _perturb_points(pts: np.ndarray, scale: float = 0.05) -> np.ndarray:
    new_pts = pts.copy()
    for i in range(len(new_pts)):
        perturbation = np.random.uniform(-scale, scale, size=2)
        new_pts[i] = _project_to_simplex(new_pts[i] + perturbation)
    return new_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    best_pts = _initial_grid(11)
    best_score = _min_triangle_area(best_pts)

    for _ in range(5):
        pts = _optimize_points(best_pts.copy())
        score = _min_triangle_area(pts)

        if score > best_score:
            best_score = score
            best_pts = pts.copy()

        pts = _perturb_points(best_pts, scale=0.02)
        score = _min_triangle_area(pts)

        if score > best_score:
            best_score = score
            best_pts = pts.copy()

    return [(float(x), float(y)) for x, y in best_pts]

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _is_inside_triangle(x: float, y: float) -> bool:
    return (0 <= x <= 1 and 0 <= y <= SQRT3/2 and 
            y <= SQRT3*(1 - abs(2*x - 1)))

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    best = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

def _hexagonal_grid(n: int) -> np.ndarray:
    pts = []
    size = int(math.ceil(math.sqrt(n * 2)))
    scale = 0.9  # Reduce scale to keep points safely inside
    for i in range(size):
        for j in range(size):
            if len(pts) >= n:
                break
            x = 0.5 + (i - j) * 0.5 / size * scale
            y = j * SQRT3 / 2 / size * scale
            if _is_inside_triangle(x, y):
                pts.append([x, y])
    while len(pts) < n:
        x = random.uniform(0.1, 0.9)
        y = random.uniform(0.1, 0.8 * SQRT3/2)
        if _is_inside_triangle(x, y):
            pts.append([x, y])
    return np.array(pts)

def _optimize_points(pts: np.ndarray, iterations: int = 1500) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)
    n = len(pts)

    for _ in range(iterations):
        new_pts = best_pts.copy()
        idx = random.randint(0, n-1)
        step = 0.03 * (1 - _/iterations)

        # Try new position multiple times until valid
        for _ in range(5):
            delta = np.random.uniform(-step, step, 2)
            new_x, new_y = best_pts[idx] + delta
            if _is_inside_triangle(new_x, new_y):
                new_pts[idx] = [new_x, new_y]
                break

        new_area = _min_triangle_area(new_pts)
        if new_area > best_area:
            best_area = new_area
            best_pts = new_pts.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _hexagonal_grid(11)
    pts = _optimize_points(pts, 1500)

    return [(float(x), float(y)) for x, y in pts]

