import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TOL = 1e-8

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area_fast(pts: np.ndarray) -> float:
    min_area = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

def _is_inside_triangle(x: float, y: float) -> bool:
    return (x >= TOL and x <= 1 - TOL and 
            y >= TOL and y <= SQRT3/2 - TOL and 
            y <= SQRT3 * x - TOL and 
            y <= SQRT3 * (1 - x) - TOL)

def _project_to_triangle(x: float, y: float) -> Tuple[float, float]:
    x = max(TOL, min(1 - TOL, x))
    y = max(TOL, min(SQRT3/2 - TOL, y, SQRT3 * x - TOL, SQRT3 * (1 - x) - TOL))
    return x, y

def _hex_grid_points(n: int) -> np.ndarray:
    points = []
    size = math.ceil(math.sqrt(n * 2 / SQRT3))
    for i in range(size):
        for j in range(size):
            x = (i + 0.5 * (j % 2)) / size
            y = j * SQRT3 / (2 * size)
            if _is_inside_triangle(x, y):
                points.append([x, y])
                if len(points) == n:
                    return np.array(points)
    return np.array(points[:n])

def _optimize_points(pts: np.ndarray, max_iter: int = 300) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area_fast(best_pts)
    n = len(pts)

    for _ in range(max_iter):
        improved = False
        for i in range(n):
            for dx, dy in [(0.002, 0), (-0.002, 0), (0, 0.002), (0, -0.002),
                          (0.0015, 0.0015), (-0.0015, 0.0015),
                          (0.0015, -0.0015), (-0.0015, -0.0015)]:
                trial = best_pts.copy()
                trial[i] += np.array([dx, dy])
                x, y = trial[i]
                x, y = _project_to_triangle(x, y)
                trial[i] = np.array([x, y])

                area = _min_triangle_area_fast(trial)
                if area > best_area + 1e-8:
                    best_area = area
                    best_pts = trial.copy()
                    improved = True
        if not improved:
            break
    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    pts = _hex_grid_points(11)

    for i in range(len(pts)):
        x, y = pts[i]
        x += np.random.uniform(-0.002, 0.002)
        y += np.random.uniform(-0.002, 0.002)
        x, y = _project_to_triangle(x, y)
        pts[i] = np.array([x, y])

    pts = _optimize_points(pts)

    return [(float(x), float(y)) for x, y in pts]

