import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    best = float("inf")
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

def _random_barycentric() -> Tuple[float, float, float]:
    while True:
        u = random.random()
        v = random.random()
        if u + v <= 1:
            return (1 - u - v, u, v)

def _barycentric_to_cartesian(b: Tuple[float, float, float]) -> np.ndarray:
    a1, a2, a3 = b
    x = a2 + a3 * 0.5
    y = a3 * SQRT3 / 2
    return np.array([x, y])

def _cartesian_to_barycentric(p: np.ndarray) -> Tuple[float, float, float]:
    x, y = p
    a3 = y * 2 / SQRT3
    a2 = x - a3 * 0.5
    a1 = 1 - a2 - a3
    return (a1, a2, a3)

def _valid_barycentric(b: Tuple[float, float, float]) -> bool:
    a1, a2, a3 = b
    return a1 >= 0 and a2 >= 0 and a3 >= 0 and abs(a1 + a2 + a3 - 1) < 1e-8

def _initial_configuration(n_pts: int = 11) -> np.ndarray:
    pts = []
    while len(pts) < n_pts:
        b = _random_barycentric()
        p = _barycentric_to_cartesian(b)
        pts.append(p)
    return np.array(pts)

def _optimize(pts: np.ndarray, steps: int, step_size: float) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    n_pts = len(pts)

    for step in range(steps):
        trial = best_pts.copy()
        idx = random.randrange(n_pts)

        current_b = _cartesian_to_barycentric(trial[idx])
        new_b = (
            max(0.01, min(0.99, current_b[0] + random.uniform(-step_size, step_size))),
            max(0.01, min(0.99, current_b[1] + random.uniform(-step_size, step_size))),
            max(0.01, min(0.99, current_b[2] + random.uniform(-step_size, step_size)))
        )
        s = sum(new_b)
        new_b = (new_b[0]/s, new_b[1]/s, new_b[2]/s)
        if _valid_barycentric(new_b):
            trial[idx] = _barycentric_to_cartesian(new_b)

        trial_val = _min_triangle_area(trial)

        if trial_val > best_val:
            best_val = trial_val
            best_pts = trial.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    pts = _initial_configuration(11)

    pts = _optimize(pts, steps=1000, step_size=0.1)
    pts = _optimize(pts, steps=1000, step_size=0.05)
    pts = _optimize(pts, steps=1000, step_size=0.02)

    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

import math
import random
import numpy as np
from itertools import combinations
from scipy.spatial import KDTree

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / 2

def _min_triangle_area(pts):
    tree = KDTree(pts)
    min_area = float('inf')
    n = len(pts)

    for i in range(n):
        neighbors = tree.query(pts[i], k=7)[1][1:]  # Get 6 nearest neighbors
        for j, k in combinations(neighbors, 2):
            a = _area(pts[i], pts[j], pts[k])
            if a < min_area:
                min_area = a
                if min_area < 1e-8:
                    return min_area
    return min_area

def _is_in_triangle(p):
    x, y = p
    if x < 0 or x > 1 or y < 0 or y > SQRT3/2:
        return False
    if y > SQRT3 * x or y > SQRT3 * (1 - x):
        return False
    return True

def _generate_initial_points(n):
    # Generate points in a hexagonal pattern within the triangle
    pts = []
    layers = 3
    for i in range(layers):
        for j in range(layers - i):
            x = 0.1 + 0.4 * i / (layers - 1)
            y = (j + 0.5*(i % 2)) * 0.8 * SQRT3 / (2*layers - 1)
            if _is_in_triangle([x, y]):
                pts.append([x, y])

    # Add symmetric points
    sym_pts = []
    for p in pts:
        x, y = p
        sym_x = 1 - x
        if _is_in_triangle([sym_x, y]):
            sym_pts.append([sym_x, y])
    pts += sym_pts

    # Add center points
    center = [0.5, SQRT3/6]
    if _is_in_triangle(center):
        pts.append(center)

    # Fill remaining points with repulsive sampling
    while len(pts) < n:
        best_p = None
        best_dist = 0
        for _ in range(50):
            x = random.uniform(0.1, 0.9)
            y = random.uniform(0.05, 0.8*SQRT3/2)
            p = np.array([x, y])
            if _is_in_triangle(p):
                min_dist = min(np.linalg.norm(p - q) for q in pts) if pts else float('inf')
                if min_dist > best_dist:
                    best_dist = min_dist
                    best_p = p
        if best_p is not None:
            pts.append(best_p)

    return np.array(pts[:n])

def _optimize_points(pts, iterations=500):
    best_pts = pts.copy()
    best_score = _min_triangle_area(best_pts)
    current_pts = pts.copy()
    temp = 0.2
    cooling_rate = 0.99

    for _ in range(iterations):
        temp *= cooling_rate
        trial_pts = current_pts.copy()

        for i in range(len(trial_pts)):
            # Only perturb points that might improve the score
            if random.random() < 0.7:
                perturbation = np.random.normal(0, temp/10, 2)
                trial_pts[i] += perturbation

                # Ensure point stays within triangle
                x, y = trial_pts[i]
                x = np.clip(x, 0.01, 0.99)
                y = np.clip(y, 0.01, SQRT3/2 - 0.01)
                if y > SQRT3 * x or y > SQRT3 * (1 - x):
                    trial_pts[i] = current_pts[i]

        current_score = _min_triangle_area(trial_pts)
        if current_score > best_score or (current_score > 0 and 
            math.exp((current_score - best_score)/temp) > random.random()):
            best_score = current_score
            best_pts = trial_pts.copy()
            current_pts = trial_pts.copy()

    # Local optimization with boundary checks
    for _ in range(50):
        for i in range(len(best_pts)):
            original = best_pts[i].copy()
            for dim in [0, 1]:
                for delta in [0.005, -0.005]:
                    best_pts[i][dim] += delta
                    if not _is_in_triangle(best_pts[i]):
                        best_pts[i][dim] -= delta
                        continue
                    new_score = _min_triangle_area(best_pts)
                    if new_score > best_score:
                        best_score = new_score
                    else:
                        best_pts[i][dim] -= delta

    return best_pts

def find_points(seed=None):
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _generate_initial_points(11)
    pts = _optimize_points(pts, iterations=500)

    return [(float(p[0]), float(p[1])) for p in pts]

from __future__ import annotations

import math
import itertools
from typing import List, Tuple
import numpy as np

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _is_inside_triangle(pt: np.ndarray) -> bool:
    x, y = pt
    if y < 0 or x < 0 or y > SQRT3/2:
        return False
    if x + y/SQRT3 > 1 + 1e-8:
        return False
    if x - y/SQRT3 > 1e-8:
        return False
    return True

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5 / TRIANGLE_AREA

class MinAreaTracker:
    def __init__(self, pts: np.ndarray):
        self.pts = pts.copy()
        self.n = len(pts)
        self.triplets = np.array(list(itertools.combinations(range(self.n), 3)))
        self.point_to_triplets = [[] for _ in range(self.n)]
        for idx_triplet, triplet in enumerate(self.triplets):
            for i in triplet:
                self.point_to_triplets[i].append(idx_triplet)
        self.areas_arr = np.zeros(len(self.triplets))
        for idx_triplet, (i, j, k) in enumerate(self.triplets):
            self.areas_arr[idx_triplet] = _area(pts[i], pts[j], pts[k])
        self.min_area = np.min(self.areas_arr)

    def update_point(self, idx: int, new_pos: np.ndarray) -> bool:
        if not _is_inside_triangle(new_pos):
            return False
        self.pts[idx] = new_pos
        for idx_triplet in self.point_to_triplets[idx]:
            i, j, k = self.triplets[idx_triplet]
            self.areas_arr[idx_triplet] = _area(self.pts[i], self.pts[j], self.pts[k])
        new_min = np.min(self.areas_arr)
        if new_min < self.min_area:
            self.min_area = new_min
        return True

    def get_min_area(self) -> float:
        return self.min_area

def _hexagonal_grid_points(n: int) -> List[np.ndarray]:
    k = math.ceil(math.sqrt(2*n))
    points = []
    for j in range(k):
        for i in range(k):
            x = (i + 0.5 * (j % 2)) / (k - 1)
            y = (j * SQRT3 / 2) / (k - 1)
            if _is_inside_triangle(np.array([x, y])):
                points.append(np.array([x, y]))
                if len(points) >= n:
                    return points
    return points

def _optimize(n_pts: int = 11, iters: int = 10000, seed: int | None = None) -> np.ndarray:
    rng = np.random.default_rng(seed)
    pts = np.array(_hexagonal_grid_points(n_pts))
    tracker = MinAreaTracker(pts)
    best_pts = pts.copy()
    best_val = tracker.get_min_area()

    for t in range(iters):
        T = max(0.1 * (1 - t/iters), 1e-4)
        step_size = 0.05 * (1 - t/iters) + 0.001

        idx = rng.integers(0, n_pts)
        old_pos = pts[idx].copy()

        angle = rng.uniform(0, 2*math.pi)
        dx = step_size * math.cos(angle)
        dy = step_size * math.sin(angle)
        new_pos = np.array([old_pos[0] + dx, old_pos[1] + dy])

        if not tracker.update_point(idx, new_pos):
            continue

        current_val = tracker.get_min_area()
        delta = current_val - best_val

        if delta > 0 or (T > 0 and rng.random() < math.exp(delta / T)):
