SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    best = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

def _hexagonal_grid(n: int) -> np.ndarray:
    pts = []
    size = int(math.ceil(math.sqrt(n)))
    for i in range(size):
        for j in range(size):
            if len(pts) >= n:
                break
            x = 0.5 + (i - j) * 0.5 / size
            y = j * SQRT3 / 2 / size
            # More careful boundary checking
            y_bound = SQRT3 * (1 - abs(2*x - 1))
            if 0 <= x <= 1 and 0 <= y <= y_bound:
                pts.append([x, y])
    while len(pts) < n:
        x = random.uniform(0, 1)
        y_max = SQRT3 * (1 - abs(2*x - 1))
        y = random.uniform(0, y_max)
        pts.append([x, y])
    return np.array(pts)

def _optimize_points(pts: np.ndarray, iterations: int = 2000) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)
    n = len(pts)

    for _ in range(iterations):
        new_pts = best_pts.copy()
        idx = random.randint(0, n-1)
        step = 0.05 * (1 - _/iterations)
        new_pts[idx] += np.random.uniform(-step, step, 2)

        x, y = new_pts[idx]
        y_max = SQRT3 * (1 - abs(2*x - 1))
        if not (0 <= x <= 1 and 0 <= y <= y_max):
            continue

        new_area = _min_triangle_area(new_pts)
        if new_area > best_area:
            best_area = new_area
            best_pts = new_pts.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _hexagonal_grid(11)
    pts = _optimize_points(pts, 2000)

    # Final boundary check
    for x, y in pts:
        y_bound = SQRT3 * (1 - abs(2*x - 1))
        if not (0 <= x <= 1 and 0 <= y <= y_bound):
            # If any point is outside, generate a new random point inside
            x_new = random.uniform(0, 1)
            y_max = SQRT3 * (1 - abs(2*x_new - 1))
            y_new = random.uniform(0, y_max)
            pts[np.where((pts == [x, y]).all(axis=1))] = [x_new, y_new]

    return [(float(x), float(y)) for x, y in pts]

