    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _initial_configuration(n_pts: int = 11) -> np.ndarray:
    pts = []
    # More dense hexagonal grid
    layers = 4
    for layer in range(1, layers+1):
        radius = 0.05 + 0.45 * layer / layers
        points_in_layer = 6 * layer
        for i in range(points_in_layer):
            angle = 2 * math.pi * i / points_in_layer
            x = 0.5 + radius * math.cos(angle)
            y = SQRT3/4 + radius * math.sin(angle)
            pts.append(np.array([x, y]))
    # Fill remaining points
    while len(pts) < n_pts:
        pts.append(_random_point())
    return np.array(pts[:n_pts])

def _get_worst_point(pts: np.ndarray) -> int:
    n = len(pts)
    min_areas = np.zeros(n)
    for i in range(n):
        min_a = float('inf')
        for j in range(max(0, i-10), min(n, i+10)):
            if j == i: continue
            for k in range(j+1, min(n, j+10)):
                if k == i: continue
                a = _area(pts[i], pts[j], pts[k])
                if a < min_a:
                    min_a = a
        min_areas[i] = min_a
    return np.argmin(min_areas)

