import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    best = float("inf")
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _hex_grid_points(n: int) -> np.ndarray:
    pts = []
    k = int(math.sqrt(2*n)) + 2
    for i in range(k):
        for j in range(k):
            if i + j > k:
                continue
            u = (i + 0.5 * (j % 2)) / k
            v = j * SQRT3 / (2 * k)
            if u + v/SQRT3 <= 1.0 and v <= SQRT3/2:
                pts.append((1-u-v/SQRT3)*_A + u*_B + (v/(SQRT3/2))*_C)
                if len(pts) == n:
                    return np.array(pts)
    return np.array(pts[:n])

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    w = 1.0 - u - v
    if u >= 0 and v >= 0 and w >= 0:
        return p
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        s = u + v
        u /= s
        v /= s
    return (1 - u - v) * _A + u * _B + v * _C

def _anneal(n_pts: int = 11,
            iters: int = 15000,
            start_temp: float = 0.5,
            end_temp: float = 1e-10,
            seed: int | None = 0) -> np.ndarray:
    rng = random.Random(seed)
    pts = _hex_grid_points(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    accept_count = 0

    for t in range(iters):
        T = start_temp * math.exp(-5.0 * t / iters)
        trial = pts.copy()

        if t % 100 == 0:
            step_size = 0.1
        else:
            step_size = 0.02 * (1 - t/iters) + 0.002

        n_changes = 1 + int(3 * (1 - t/iters))

        for _ in range(n_changes):
            idx = rng.randrange(n_pts)
            if t % 200 == 0:
                trial[idx] = _hex_grid_points(1)[0]
            else:
                dx = rng.uniform(-step_size, step_size)
                dy = rng.uniform(-step_size, step_size)
                trial[idx] += np.array([dx, dy])
                trial[idx] = _project_to_simplex(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or rng.random() < math.exp(delta / max(T, 1e-12)):
            pts = trial
            accept_count += 1
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

        if t > 0 and t % 500 == 0:
            accept_rate = accept_count / 500
            if accept_rate < 0.2:
                start_temp *= 1.2
            elif accept_rate > 0.5:
                start_temp *= 0.8
            accept_count = 0

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=15000, seed=seed)
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

from __future__ import annotations

import math
import random
import itertools
from typing import List, Tuple
import numpy as np

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    min_area = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _hex_grid_points(n: int) -> List[np.ndarray]:
    pts = []
    k = int(math.sqrt(n)) + 2  # Increased to ensure enough points
    for i in range(k):
        for j in range(k):
            u = (i + 0.5 * (j % 2)) / k
            v = (j * SQRT3 / 2) / k
            if u + v/SQRT3 <= 1.0:
                pts.append((1 - u - v/SQRT3) * _A + u * _B + v/SQRT3 * _C)
                if len(pts) >= n:
                    return pts[:n]
    # If still not enough points, fill with random ones
    while len(pts) < n:
        pts.append(_random_point())
    return pts[:n]

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    w = 1.0 - u - v
    if u >= 0 and v >= 0 and w >= 0:
        return p
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _local_optimize(pts: np.ndarray, max_iter: int = 100) -> np.ndarray:
    n = len(pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for step in np.linspace(0.02, 0.001, max_iter//2):
        improved = False
        for i in range(n):
            for dx in np.linspace(-step, step, 3):
                for dy in np.linspace(-step, step, 3):
                    trial = best_pts.copy()
                    trial[i] += np.array([dx, dy])
                    trial[i] = _project_to_simplex(trial[i])
                    val = _min_triangle_area(trial)
                    if val > best_val:
                        best_val = val
                        best_pts = trial.copy()
                        improved = True
        if not improved and step > 0.005:
            for i in range(n):
                trial = best_pts.copy()
                trial[i] += np.random.uniform(-0.05, 0.05, 2)
                trial[i] = _project_to_simplex(trial[i])
                val = _min_triangle_area(trial)
                if val > best_val:
                    best_val = val
                    best_pts = trial.copy()
                    improved = True
    return best_pts

def _anneal(n_pts: int = 11,
            iters: int = 5000,
            start_temp: float = 0.1,
            end_temp: float = 1e-8,
            step_size: float = 0.03,
            seed: int | None = 0) -> np.ndarray:
    rng = np.random.RandomState(seed)
    pts = np.array(_hex_grid_points(n_pts))
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        T = start_temp * (end_temp / start_temp) ** (t / max(iters-1, 1))
        idx = rng.randint(n_pts)
        trial = pts.copy()
        trial[idx] += rng.uniform(-step_size, step_size, size=2)
        trial[idx] = _project_to_simplex(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or rng.random() < math.exp(delta / max(T, 1e-12)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = pts.copy()

    return _local_optimize(best_pts)

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=5000, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5 / TRIANGLE_AREA

def _min_triangle_area(pts: np.ndarray) -> float:
    min_area = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    x = 1.0 - u - v
    y = u
    z = v
    return np.array([0.5 * (y + z), SQRT3 / 2 * z])

def _is_in_triangle(p: np.ndarray) -> bool:
    x, y = p
    if x < 0 or x > 1 or y < 0 or y > SQRT3/2:
        return False
    if y > SQRT3 * x or y > SQRT3 * (1 - x):
        return False
    return True

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    x, y = p
    x = max(0.0, min(1.0, x))
    y = max(0.0, min(SQRT3/2, y))

    if y > SQRT3 * x:
        y = SQRT3 * x
    if y > SQRT3 * (1 - x):
        y = SQRT3 * (1 - x)
    return np.array([x, y])

def _optimize_points(pts: np.ndarray, steps: int = 2000) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    temp = 0.1
    cooling_rate = 0.9995

    for step in range(steps):
        current_temp = temp * cooling_rate**step

        # Occasionally do a multi-point perturbation
        if random.random() < 0.1:
            idxs = random.sample(range(len(pts)), min(3, len(pts)))
        else:
            idxs = [random.randrange(len(pts))]

        trial = best_pts.copy()
        for idx in idxs:
            step_size = 0.01 * (1 - step/steps)  # Decreasing step size
            trial[idx] += np.random.uniform(-step_size, step_size, size=2)
            trial[idx] = _project_to_triangle(trial[idx])

            if not _is_in_triangle(trial[idx]):
                continue

        trial_val = _min_triangle_area(trial)

        # Simulated annealing acceptance
        if trial_val > best_val or (current_temp > 0 and 
                                  random.random() < math.exp((trial_val - best_val)/current_temp)):
            best_val = trial_val
            best_pts = trial.copy()

        # Occasionally kick the configuration
        if step > 0 and step % 500 == 0 and best_val < 0.01:
            kick_idx = random.randrange(len(pts))
            best_pts[kick_idx] = _random_point()

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    # Initial random points
    pts = np.array([_random_point() for _ in range(11)])

    # Optimization phases with different parameters
    for phase in range(3):
        pts = _optimize_points(pts, steps=1500)

    return [(float(x), float(y)) for x, y in pts]

