import math
import random
import numpy as np

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    best = float("inf")
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _initial_configuration() -> np.ndarray:
    pts = []
    while len(pts) < 11:
        p = _random_point()
        valid = True
        for q in pts:
            if np.linalg.norm(p - q) < 0.1:
                valid = False
                break
        if valid:
            pts.append(p)
    return np.array(pts)

def _optimize(pts: np.ndarray, steps: int = 5000) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    n = len(pts)

    for step in range(steps):
        current_step_size = 0.1 * (1 - step/steps)**2

        # Occasionally make a large jump
        if step % 100 == 0 and step > 0:
            i = random.randint(0, n-1)
            trial = best_pts.copy()
            trial[i] = _random_point()
        else:
            i = random.randint(0, n-1)
            trial = best_pts.copy()
            trial[i] += np.random.normal(0, current_step_size, size=2)
            trial[i] = _project_to_simplex(trial[i])

        trial_val = _min_triangle_area(trial)
        if trial_val > best_val:
            best_val = trial_val
            best_pts = trial.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    np.random.seed(seed)
    random.seed(seed)

    best_pts = _initial_configuration()
    best_pts = _optimize(best_pts, 5000)

