import math
import random
import numpy as np
from itertools import combinations

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / 2.0

def _min_triangle_area(pts):
    min_area = float('inf')
    for trio in combinations(pts, 3):
        a = _area(*trio)
        if a < min_area:
            min_area = a
            if min_area < 1e-8:
                return min_area
    return min_area

def _is_in_triangle(p):
    x, y = p
    if x < 0 or x > 1 or y < 0 or y > SQRT3/2:
        return False
    if y > SQRT3 * x:
        return False
    if y > SQRT3 * (1 - x):
        return False
    return True

def _generate_initial_points(n):
    # Optimized initial configuration for n=11
    base_points = [
        (0.1, 0.05), (0.9, 0.05),
        (0.2, 0.2), (0.8, 0.2),
        (0.3, 0.35), (0.7, 0.35),
        (0.4, 0.5), (0.6, 0.5),
        (0.5, 0.65),
        (0.15, 0.1), (0.85, 0.1)
    ]
    points = []
    for p in base_points:
        x, y = p
        x += random.uniform(-0.02, 0.02)
        y += random.uniform(-0.02, 0.02)
        if _is_in_triangle((x, y)):
            points.append([x, y])

    while len(points) < n:
        x = random.uniform(0.1, 0.9)
        y = random.uniform(0.05, 0.7)
        if _is_in_triangle((x, y)):
            points.append([x, y])
    return np.array(points)

def _optimize_points(points, iterations):
    best_points = points.copy()
    best_score = _min_triangle_area(best_points)
    n = len(points)

    for i in range(iterations):
        new_points = best_points.copy()

        # Cooling schedule
        cooling = 1.0 - (i/iterations)**0.7
        step = 0.02 * cooling

        # Identify worst triangles
        worst_indices = set()
        min_areas = []
        for trio in combinations(range(n), 3):
            a = _area(new_points[trio[0]], new_points[trio[1]], new_points[trio[2]])
            min_areas.append((a, trio))

        min_areas.sort()
        for _, trio in min_areas[:5]:
            worst_indices.update(trio)

        # Update worst points with repulsion
        for idx in worst_indices:
            # Repulsion from nearest neighbors
            repulsion = np.zeros(2)
            for j in range(n):
                if j == idx:
                    continue
                diff = new_points[idx] - new_points[j]
                dist = np.linalg.norm(diff)
                if dist < 0.2:
                    repulsion += diff / (dist**2 + 1e-6)

            new_pos = new_points[idx] + step * np.random.uniform(-1, 1, 2) + 0.01 * repulsion
            if _is_in_triangle(new_pos):
                new_points[idx] = new_pos

        new_score = _min_triangle_area(new_points)

        if new_score > best_score:
            best_score = new_score
            best_points = new_points.copy()

    return best_points

def find_points(seed=None):
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    points = _generate_initial_points(11)
    points = _optimize_points(points, 4000)

    return [(float(p[0]), float(p[1])) for p in points]

import math
import random
import numpy as np
from itertools import combinations
from scipy.spatial import KDTree

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / 2

def _min_triangle_area(pts):
    tree = KDTree(pts)
    min_area = float('inf')
    n = len(pts)

    for i in range(n):
        neighbors = tree.query(pts[i], k=7)[1][1:]  # Get 6 nearest neighbors
        for j, k in combinations(neighbors, 2):
            a = _area(pts[i], pts[j], pts[k])
            if a < min_area:
                min_area = a
                if min_area < 1e-8:
                    return min_area
    return min_area

def _is_in_triangle(p):
    x, y = p
    if x < 0 or x > 1 or y < 0 or y > SQRT3/2:
        return False
    if y > SQRT3 * x or y > SQRT3 * (1 - x):
        return False
    return True

def _generate_initial_points(n):
    # Generate points in a hexagonal pattern with tighter bounds
    pts = []
    layers = 3
    for i in range(layers):
        for j in range(layers - i):
            x = 0.15 + 0.35 * i / (layers - 1)
            y = (j + 0.5*(i % 2)) * 0.7 * SQRT3 / (2*layers - 1)
            if _is_in_triangle([x, y]):
                pts.append([x, y])

    # Add symmetric points with boundary check
    sym_pts = []
    for p in pts:
        x, y = p
        sym_x = 1 - x
        if _is_in_triangle([sym_x, y]):
            sym_pts.append([sym_x, y])
    pts += sym_pts

    # Add center points
    center = [0.5, SQRT3/6]
    if _is_in_triangle(center):
        pts.append(center)

    # Fill remaining points with repulsive sampling and strict bounds
    while len(pts) < n:
        best_p = None
        best_dist = 0
        for _ in range(50):
            x = random.uniform(0.1, 0.9)
            y = random.uniform(0.05, 0.8*SQRT3/2)
            p = np.array([x, y])
            if _is_in_triangle(p):
                min_dist = min(np.linalg.norm(p - q) for q in pts) if pts else float('inf')
                if min_dist > best_dist:
                    best_dist = min_dist
                    best_p = p
        if best_p is not None and _is_in_triangle(best_p):
            pts.append(best_p)
        else:
            # Fallback to random point inside triangle
            while True:
                x = random.uniform(0.05, 0.95)
                y = random.uniform(0.01, 0.85*SQRT3/2)
                if _is_in_triangle([x, y]):
                    pts.append([x, y])
                    break

    return np.array(pts[:n])

def _optimize_points(pts, iterations=500):
    best_pts = pts.copy()
    best_score = _min_triangle_area(best_pts)
    current_pts = pts.copy()
    temp = 0.2
    cooling_rate = 0.99

    for _ in range(iterations):
        temp *= cooling_rate
        trial_pts = current_pts.copy()

        for i in range(len(trial_pts)):
            if random.random() < 0.7:
                perturbation = np.random.normal(0, temp/10, 2)
                trial_pts[i] += perturbation

                # Strict boundary enforcement
                x, y = trial_pts[i]
                x = np.clip(x, 0.02, 0.98)
                y = np.clip(y, 0.02, SQRT3/2 - 0.02)
                if not _is_in_triangle(trial_pts[i]):
                    trial_pts[i] = current_pts[i]

        current_score = _min_triangle_area(trial_pts)
        if current_score > best_score or (current_score > 0 and 
            math.exp((current_score - best_score)/temp) > random.random()):
            best_score = current_score
            best_pts = trial_pts.copy()
            current_pts = trial_pts.copy()

    # Local optimization with strict boundary checks
    for _ in range(50):
        for i in range(len(best_pts)):
            original = best_pts[i].copy()
            for dim in [0, 1]:
                for delta in [0.005, -0.005]:
                    best_pts[i][dim] += delta
                    if not _is_in_triangle(best_pts[i]):
                        best_pts[i][dim] -= delta
                        continue
                    new_score = _min_triangle_area(best_pts)
                    if new_score > best_score:
                        best_score = new_score
                    else:
                        best_pts[i][dim] -= delta

    return best_pts

def find_points(seed=None):
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _generate_initial_points(11)
    pts = _optimize_points(pts, iterations=500)

