import math
import random
import numpy as np

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    sample_size = min(200, n*(n-1)*(n-2)//6)
    for _ in range(sample_size):
        i, j, k = random.sample(range(n), 3)
        a = _area(pts[i], pts[j], pts[k])
        if a < min_area:
            min_area = a
            if min_area < 1e-8:
                return 0
    return min_area

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _is_inside(p: np.ndarray) -> bool:
    x, y = p
    return (x >= 0 and y >= 0 and 
            x + y/SQRT3 <= 1.0 and 
            x - y/SQRT3 <= 1.0 and 
            y <= SQRT3/2)

def _hex_grid_point(i: int, j: int, k: int) -> np.ndarray:
    x = (i + 0.5 * (j % 2)) / k
    y = (j * SQRT3 / 2) / k
    return np.array([x, y])

def _initial_points(n: int) -> np.ndarray:
    k = int(math.sqrt(n * 2.5)) + 1
    pts = []
    for i in range(k):
        for j in range(k):
            p = _hex_grid_point(i, j, k)
            if _is_inside(p):
                pts.append(p)
    if len(pts) < n:
        while len(pts) < n:
            x = random.random()
            y = random.random() * SQRT3 / 2
            if _is_inside(np.array([x, y])):
                pts.append(np.array([x, y]))
    return np.array(pts[:n])

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv[0], uv[1]
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _anneal(n_pts: int = 11, iters: int = 5000, seed: int | None = 0) -> np.ndarray:
    random.seed(seed)
    pts = _initial_points(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        T = max(0.001, 0.1 * (1 - t/iters)**2)
        idx = random.randrange(n_pts)
        trial = pts.copy()
        step = 0.05 * (1 - t/iters)
        trial[idx] += np.random.normal(0, step, 2)
        trial[idx] = _project_to_simplex(trial[idx])

        if not _is_inside(trial[idx]):
            trial[idx] = _project_to_simplex(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or (T > 0 and random.random() < math.exp(delta / T)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

        if t % 500 == 0:
            pts = best_pts.copy()

    return best_pts

def find_points(seed: int | None = 0) -> list[tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=5000, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

