import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    best = float("inf")
    n = len(pts)
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u / (u + v), v / (u + v)
    return (1 - u - v) * _A + u * _B + v * _C

def _improved_configuration() -> np.ndarray:
    pts = []
    # 3-layer hexagonal pattern
    layers = 3
    for layer in range(layers):
        for i in range(layer + 1):
            u = (i + 0.5) / (layers + 1)
            v = (layer - i + 0.5) / (layers + 1)
            pts.append((1 - u - v) * _A + u * _B + v * _C)
    # Add center point
    pts.append((1 - 1/3 - 1/3) * _A + (1/3) * _B + (1/3) * _C)
    return np.array(pts[:11])

def _optimize(pts: np.ndarray, steps: int = 3000) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    n_pts = len(pts)
    step_size = 0.02

    for step in range(steps):
        trial = best_pts.copy()

        # Every 100 steps, do a larger perturbation
        if step % 100 == 0:
            for i in range(n_pts):
                trial[i] += random.uniform(-0.05, 0.05), random.uniform(-0.05, 0.05)
                trial[i] = _project_to_simplex(trial[i])
        else:
            # Directed move towards largest adjacent triangles
            idx = random.randrange(n_pts)
            dir_x, dir_y = 0.0, 0.0
            for j in range(n_pts):
                if j == idx:
                    continue
                for k in range(j+1, n_pts):
                    if k == idx:
                        continue
                    a = _area(trial[idx], trial[j], trial[k])
                    if a < best_val * 1.5:
                        vec = (trial[j] + trial[k]) / 2 - trial[idx]
                        dir_x += vec[0] * (best_val / (a + 1e-9))
                        dir_y += vec[1] * (best_val / (a + 1e-9))

            norm = math.sqrt(dir_x**2 + dir_y**2)
            if norm > 0:
                dir_x, dir_y = dir_x/norm, dir_y/norm
                trial[idx] += dir_x * step_size, dir_y * step_size
            else:
                trial[idx] += random.uniform(-step_size, step_size), random.uniform(-step_size, step_size)
            trial[idx] = _project_to_simplex(trial[idx])

        trial_val = _min_triangle_area(trial)
        if trial_val > best_val:
            best_val = trial_val
            best_pts = trial.copy()
            step_size = min(0.1, step_size * 1.2)
        else:
            step_size = max(0.001, step_size * 0.9)

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)
    pts = _improved_configuration()
    pts = _optimize(pts)
    return [(float(x), float(y)) for x, y in pts]

import math
import random
import numpy as np
from itertools import combinations
from scipy.spatial import KDTree

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / 2.0

def _min_triangle_area(pts):
    tree = KDTree(pts)
    min_area = float('inf')
    n = len(pts)

    for i in range(n):
        neighbors = tree.query(pts[i], k=6)[1][1:]  # Get 5 nearest neighbors (excluding self)
        for j in neighbors:
            for k in neighbors:
                if j >= k:
                    continue
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area < 1e-8:
                        return min_area
    return min_area

def _is_in_triangle(p):
    x, y = p
    if x < 0 or x > 1 or y < 0 or y > SQRT3/2:
        return False
    if y > SQRT3 * x:
        return False
    if y > SQRT3 * (1 - x):
        return False
    return True

def _project_to_triangle(p):
    x, y = p
    x = max(0, min(1, x))
    y = max(0, min(SQRT3/2, y))

    if y > SQRT3 * x:
        y = SQRT3 * x
    if y > SQRT3 * (1 - x):
        y = SQRT3 * (1 - x)
    return np.array([x, y])

def _generate_initial_points(n):
    points = []
    layers = 4
    for i in range(layers):
        y = (i + 0.5) * (SQRT3/2) / layers
        x_start = 0.5 - y/SQRT3
        x_end = 0.5 + y/SQRT3
        num_points = max(3, int((x_end - x_start) * (n / (layers * 0.5))))
        for j in range(num_points):
            x = x_start + (x_end - x_start) * (j + 0.5) / num_points
            points.append([x, y])

    while len(points) < n:
        x = random.uniform(0.1, 0.9)
        y = random.uniform(0.05, 0.7)
        if _is_in_triangle((x, y)):
            points.append([x, y])

    return np.array(points[:n])

def _optimize_points(points, iterations):
    best_points = points.copy()
    best_score = _min_triangle_area(best_points)
    n = len(points)

    for i in range(iterations):
        new_points = best_points.copy()
        cooling = 1.0 - (i/iterations)**0.7
        step = 0.02 * cooling

        tree = KDTree(new_points)
        min_areas = []
        for idx in range(n):
            neighbors = tree.query(new_points[idx], k=6)[1][1:]
            for j in neighbors:
                for k in neighbors:
                    if j >= k:
                        continue
                    a = _area(new_points[idx], new_points[j], new_points[k])
                    min_areas.append((a, idx, j, k))

        min_areas.sort()
        worst_indices = set()
        for a, idx, j, k in min_areas[:20]:
            worst_indices.add(idx)
            worst_indices.add(j)
            worst_indices.add(k)

        for idx in worst_indices:
            gradient = np.zeros(2)
            count = 0
            for j in range(n):
                if j == idx:
                    continue
                for k in range(j+1, n):
                    if k == idx:
                        continue
                    a = _area(new_points[idx], new_points[j], new_points[k])
                    if a < 2 * best_score:
                        # Compute gradient of area with respect to point idx
                        p, q, r = new_points[idx], new_points[j], new_points[k]
                        sign = 1 if (q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0]) > 0 else -1
                        dx = sign * (q[1] - r[1]) / 2.0
                        dy = sign * (r[0] - q[0]) / 2.0
                        gradient += np.array([dx, dy]) / max(a, 1e-6)
                        count += 1

            if count > 0:
                gradient /= count
                new_pos = new_points[idx] + step * (np.random.uniform(-1, 1, 2) + 0.05 * gradient
                new_pos = _project_to_triangle(new_pos)
                new_points[idx] = new_pos

        new_score = _min_triangle_area(new_points)
        if new_score > best_score:
            best_score = new_score
            best_points = new_points.copy()

    return best_points

def find_points(seed=None):
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    points = _generate_initial_points(11)
    points = _optimize_points(points, 2000)

    return [(float(p[0]), float(p[1])) for p in points]

