import math
import random
import numpy as np
from collections import defaultdict

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area_fast(pts: np.ndarray, threshold=0) -> float:
    n = len(pts)
    best = float('inf')
    spatial_grid = defaultdict(list)
    grid_size = 0.1

    for i, p in enumerate(pts):
        x, y = p
        grid_x, grid_y = int(x/grid_size), int(y/grid_size)
        spatial_grid[(grid_x, grid_y)].append(i)

    for (gx, gy), indices in spatial_grid.items():
        for i in indices:
            for j in range(i+1, n):
                if j in indices or (abs(pts[j][0]/grid_size - gx) <= 1 and abs(pts[j][1]/grid_size - gy) <= 1):
                    for k in range(j+1, n):
                        if k in indices or (abs(pts[k][0]/grid_size - gx) <= 1 and abs(pts[k][1]/grid_size - gy) <= 1):
                            a = _area(pts[i], pts[j], pts[k])
                            if a < best:
                                best = a
                                if best <= threshold:
                                    return best
    return best

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = 1 - v, 1 - u
    return (1 - u - v) * _A + u * _B + v * _C

def _initial_configuration(n_pts: int) -> np.ndarray:
    if n_pts == 11:
        return np.array([
            [0.0, 0.0], [1.0, 0.0], [0.5, SQRT3/2],
            [0.25, SQRT3/4], [0.75, SQRT3/4],
            [0.125, SQRT3/8], [0.375, SQRT3/8],
            [0.625, SQRT3/8], [0.875, SQRT3/8],
            [0.0625, SQRT3/16], [0.9375, SQRT3/16]
        ])
    pts = []
    for i in range(n_pts):
        x = (i * 0.381966) % 1.0
        y = (i * 0.618034) % (SQRT3/2)
        pts.append([x, y])
    return np.array(pts)

def _optimize(pts: np.ndarray, iterations: int) -> np.ndarray:
    n = len(pts)
    best_pts = pts.copy()
    best_area = _min_triangle_area_fast(best_pts)

    for it in range(iterations):
        current_min = _min_triangle_area_fast(pts)
        candidates = []

        for i in range(n):
            for _ in range(3):
                step = 0.01 * (1 - it/iterations)**2
                dx, dy = random.uniform(-step, step), random.uniform(-step, step)
                new_pt = _project_to_simplex(pts[i] + [dx, dy])
                trial = pts.copy()
                trial[i] = new_pt
                trial_area = _min_triangle_area_fast(trial, current_min)
                if trial_area > current_min:
                    candidates.append((trial, trial_area))

        if candidates:
            candidates.sort(key=lambda x: -x[1])
            pts = candidates[0][0]
            if candidates[0][1] > best_area:
                best_area = candidates[0][1]
                best_pts = pts.copy()
        else:
            for i in range(n):
                pts[i] += np.random.normal(0, 0.001, 2)
                pts[i] = _project_to_simplex(pts[i])

    return best_pts

def _gradient_optimize(pts: np.ndarray, steps: int) -> np.ndarray:
    n = len(pts)
    best_pts = pts.copy()
    best_area = _min_triangle_area_fast(best_pts)

    for _ in range(steps):
        grad = np.zeros_like(pts)
        min_triangles = []

        for i in range(n):
            for j in range(i+1, n):
                for k in range(j+1, n):
                    a = _area(pts[i], pts[j], pts[k])
                    if abs(a - best_area) < 1e-8:
                        min_triangles.append((i,j,k))

        for i,j,k in min_triangles:
            p, q, r = pts[i], pts[j], pts[k]
            normal = np.array([q[1]-r[1], r[0]-q[0]])
            grad[i] += normal
            normal = np.array([r[1]-p[1], p[0]-r[0]])
            grad[j] += normal
            normal = np.array([p[1]-q[1], q[0]-p[0]])
            grad[k] += normal

        for i in range(n):
            if np.linalg.norm(grad[i]) > 0:
                grad[i] = grad[i] / np.linalg.norm(grad[i])

        step_size = 0.001
        improved = False
        for factor in [1.0, 0.5, 0.1, 0.01]:
            trial = pts + step_size * factor * grad
            for i in range(n):
                trial[i] = _project_to_simplex(trial[i])
            trial_area = _min_triangle_area_fast(trial)
            if trial_area > best_area:
                best_area = trial_area
                best_pts = trial.copy()
                pts = trial.copy()
                improved = True
                break

        if not improved:
            break

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    pts = _initial_configuration(11)
    pts = _optimize(pts, 2000)
    pts = _gradient_optimize(pts, 100)

    min_area = _min_triangle_area_fast(pts)
    for _ in range(3):
        if min_area < 0.01:
            pts = _optimize(pts, 500)
            min_area = _min_triangle_area_fast(pts)

    return [(float(x), float(y)) for x, y in pts]

