        y = (layer * SQRT3) / (2 * (layers - 1))
        x_start = 0.5 - (layer * 0.5) / (layers - 1)
        x_step = 1.0 / (layers - 1)
        for i in range(layer + 1):
            x = x_start + i * x_step
            points.append(np.array([x, y]))
    # Add additional points if needed
    while len(points) < n_pts:
        points.append(_random_point())
    return np.array(points[:n_pts])

def _anneal(n_pts: int = 11, iters: int = 5000, seed: int | None = 0) -> np.ndarray:
    rng = random.Random(seed)
    pts = _initial_configuration(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        T = 0.1 * (1 - t/iters)**2
        idx = rng.randrange(n_pts)
        trial = pts.copy()
        step_size = 0.05 * (1 - t/iters)**2
        trial[idx] += rng.uniform(-step_size, step_size), rng.uniform(-step_size, step_size)
        trial[idx] = _project_to_simplex(trial[idx])

        trial_val = _min_triangle_area(trial)
        if trial_val > best_val or rng.random() < math.exp((trial_val - best_val)/max(T, 1e-12)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

    # Local optimization
    for _ in range(1000):
        improved = False
        for idx in range(n_pts):
            for dx in [-0.001, 0, 0.001]:
                for dy in [-0.001, 0, 0.001]:
                    if dx == 0 and dy == 0:
                        continue
                    trial = best_pts.copy()
                    trial[idx] += dx, dy
                    trial[idx] = _project_to_simplex(trial[idx])
                    trial_val = _min_triangle_area(trial)
                    if trial_val > best_val:
                        best_val = trial_val
                        best_pts = trial.copy()
                        improved = True
        if not improved:
            break

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=5000, seed=seed)
    return [(float(f"{x:.6f}"), float(f"{y:.6f}")) for x, y in pts]

from __future__ import annotations

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
INV_SQRT3 = 1.0 / SQRT3

def _hex_grid_init(n: int) -> np.ndarray:
    # Generate hexagonal grid points within the equilateral triangle
    k = math.ceil(math.sqrt(n * 2 * INV_SQRT3))
    points = []
    for i in range(k):
        y = (i + 0.5) * SQRT3 / (2 * k)
        x_start = 0.5 * (1 - (2*i+1)/k)
        x_end = 0.5 * (1 + (2*i+1)/k)
        x_step = 1.0 / k
        for j in range(k):
            x = x_start + j * x_step
            if x <= x_end and (1 - x - y * 2 * INV_SQRT3) >= 0:
                points.append([x, y])
                if len(points) == n:
                    return np.array(points)
    return np.array(points + [_random_point() for _ in range(n - len(points))])

def _random_point() -> np.ndarray:
    u, v = random.random(), random.random()
    if u + v > 1.0:
        u, v = 1 - u, 1 - v
    return np.array([u + 0.5*v, v * SQRT3/2])

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    x, y = p
    # Barycentric coordinates
    v = y * 2 * INV_SQRT3
    u = x - 0.5 * v

    # Project to simplex
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = 1 - u, 1 - v

    return np.array([u + 0.5*v, v * SQRT3/2])

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')

    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                p1, p2, p3 = pts[i], pts[j], pts[k]
                area = 0.5 * abs((p2[0]-p1[0])*(p3[1]-p1[1]) - (p2[1]-p1[1])*(p3[0]-p1[0]))
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0.0
    return min_area

def _optimize_lloyd(pts: np.ndarray, iterations: int = 100) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area(pts)

    for _ in range(iterations):
        new_pts = pts.copy()

        # Compute repulsion forces
        for i in range(len(pts)):
            force = np.zeros(2)
            for j in range(len(pts)):
                if i == j:
                    continue
                diff = pts[i] - pts[j]
                dist = np.linalg.norm(diff)
                if dist > 0:
                    force += diff / (dist**3)  # Inverse square law repulsion

            # Apply force with adaptive step size
            step_size = 0.1 * best_area
            new_pts[i] = pts[i] + step_size * force
            new_pts[i] = _project_to_triangle(new_pts[i])

        new_area = _min_triangle_area(new_pts)
        if new_area > best_area:
            best_area = new_area
            best_pts = new_pts.copy()
            pts = new_pts.copy()
        else:
            # Small random perturbation to escape local optima
            for i in range(len(pts)):
                if random.random() < 0.1:
                    pts[i] += np.random.normal(0, best_area/10, 2)
                    pts[i] = _project_to_triangle(pts[i])

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    pts = _hex_grid_init(11)
    pts = _optimize_lloyd(pts, 100)
    return [(float(x), float(y)) for x, y in pts]

