import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
EPSILON = 1e-8

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    best = float('inf')
    for i in range(n-2):
        for j in range(i+1, n-1):
            v1 = pts[j] - pts[i]
            for k in range(j+1, n):
                area = abs(np.cross(v1, pts[k] - pts[i])) * 0.5
                if area < best:
                    best = area
                    if best < EPSILON:
                        return 0
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _hex_grid_point(i: int, n: int) -> np.ndarray:
    k = math.ceil((math.sqrt(8*n + 1) - 1)/2)
    row = i // k
    col = i % k
    x = 0.5 * col / (k-1) if row % 2 else col / (k-1)
    y = row * SQRT3 / (2*(k-1))
    if x > 0.5 + y/SQRT3 or x < 0.5 - y/SQRT3 or y > SQRT3/2:
        return _random_point()
    return np.array([x, y])

def _random_point() -> np.ndarray:
    u, v = random.random(), random.random()
    if u + v > 1.0:
        u, v = 1-u, 1-v
    return (1 - u - v) * _A + u * _B + v * _C

def _initialize_points(n_pts: int) -> np.ndarray:
    pts = []
    for i in range(n_pts):
        if i < 9:
            pts.append(_hex_grid_point(i, n_pts))
        else:
            pts.append(_random_point())
    return np.array(pts)

def _optimize_locally(pts: np.ndarray, best_val: float, steps: int = 100) -> Tuple[np.ndarray, float]:
    n = len(pts)
    step_size = 0.02
    for _ in range(steps):
        improved = False
        for i in range(n):
            for _ in range(5):
                trial = pts.copy()
                trial[i] += np.random.uniform(-step_size, step_size, 2)
                u, v = np.random.random(), np.random.random()
                if u + v > 1.0:
                    u, v = 1-u, 1-v
                trial[i] = (1 - u - v) * _A + u * _B + v * _C
                trial_val = _min_triangle_area(trial)
                if trial_val > best_val:
                    pts = trial
                    best_val = trial_val
                    improved = True
                    break
        if not improved:
            step_size *= 0.8
    return pts, best_val

def _anneal(n_pts: int = 11,
            iters: int = 3000,
            start_temp: float = 0.2,
            end_temp: float = 1e-8,
            step_size: float = 0.1,
            seed: int | None = None) -> np.ndarray:
    rng = random.Random(seed)
    pts = _initialize_points(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        T = start_temp * math.exp(-8.0 * t / iters)
        current_step = step_size * (1 - 0.95 * t/iters)

        trial = pts.copy()
        idx = rng.randrange(n_pts)
        trial[idx] += rng.uniform(-current_step, current_step), rng.uniform(-current_step, current_step)

        u, v = rng.random(), rng.random()
        if u + v > 1.0:
            u, v = 1-u, 1-v
        trial[idx] = (1 - u - v) * _A + u * _B + v * _C

        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or rng.random() < math.exp(delta / max(T, 1e-12)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

    best_pts, best_val = _optimize_locally(best_pts, best_val)
    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=3000, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

from __future__ import annotations

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    u, v = random.random(), random.random()
    if u + v > 1.0:
        u, v = 1 - u, 1 - v
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = 1 - u, 1 - v
    return (1 - u - v) * _A + u * _B + v * _C

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')

    for i in range(n):
        for j in range(i+1, min(i+15, n)):
            for k in range(j+1, min(j+15, n)):
                area = 0.5 * abs((pts[j,0]-pts[i,0])*(pts[k,1]-pts[i,1]) - (pts[k,0]-pts[i,0])*(pts[j,1]-pts[i,1]))
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0.0
    return min_area

def _get_small_triangle_indices(pts: np.ndarray, threshold: float) -> List[int]:
    n = len(pts)
    small_indices = set()
    for i in range(n):
        for j in range(i+1, min(i+15, n)):
            for k in range(j+1, min(j+15, n)):
                area = 0.5 * abs((pts[j,0]-pts[i,0])*(pts[k,1]-pts[i,1]) - (pts[k,0]-pts[i,0])*(pts[j,1]-pts[i,1]))
                if area < threshold * 1.5:
                    small_indices.update([i, j, k])
    return list(small_indices)

def _anneal(n_pts: int = 11,
            iters: int = 25000,
            start_temp: float = 0.2,
            end_temp: float = 1e-8,
            seed: int | None = 0) -> np.ndarray:

    random.seed(seed)
    best_pts = np.array([_random_point() for _ in range(n_pts)])
    best_val = _min_triangle_area(best_pts)

    for restart in range(3):
        pts = best_pts.copy()
        current_val = best_val
        step_size = 0.02
        accept_count = 0

        for t in range(iters):
            T = start_temp * (end_temp / start_temp) ** ((t / iters) ** 1.8)

            if t > 0 and t % 100 == 0:
                accept_rate = accept_count / 100
                if accept_rate > 0.6:
                    step_size *= 1.3
                elif accept_rate < 0.2:
                    step_size *= 0.7
                step_size = max(0.001, min(0.15, step_size))
                accept_count = 0

            if t % 500 == 0:
                small_indices = _get_small_triangle_indices(pts, current_val)
                if not small_indices:
                    small_indices = list(range(n_pts))
                idx = random.choice(small_indices)
            else:
                idx = random.randrange(n_pts)

            trial = pts.copy()
            angle = random.uniform(0, 2*math.pi)
            step = random.uniform(0, step_size)
            dx, dy = step*math.cos(angle), step*math.sin(angle)
            trial[idx] += dx, dy
            trial[idx] = _project_to_simplex(trial[idx])

            trial_val = _min_triangle_area(trial)
            delta = trial_val - current_val

            if delta > 0 or random.random() < math.exp(delta / max(T, 1e-12)):
                pts = trial
                current_val = trial_val
                accept_count += 1
                if trial_val > best_val:
                    best_val = trial_val
                    best_pts = trial.copy()

    # Enhanced local search
    for _ in range(400):
        improved = False
        small_indices = _get_small_triangle_indices(best_pts, best_val)
        if not small_indices:
            small_indices = list(range(n_pts))
        for idx in random.sample(small_indices, len(small_indices)):
            for angle in np.linspace(0, 2*np.pi, 20):
                dx, dy = 0.004*math.cos(angle), 0.004*math.sin(angle)
                trial = best_pts.copy()
                trial[idx] += dx, dy
                trial[idx] = _project_to_simplex(trial[idx])
                trial_val = _min_triangle_area(trial)
                if trial_val > best_val:
                    best_val = trial_val
                    best_pts = trial.copy()
                    improved = True
        if not improved:
            break

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=25000, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

from __future__ import annotations

import math
import random
import itertools
from typing import List, Tuple
import numpy as np

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _is_inside_triangle(pt: np.ndarray) -> bool:
    x, y = pt
    if y < 0 or x < 0 or y > SQRT3/2:
        return False
    if x + y/SQRT3 > 1 + 1e-8:
        return False
    if x - y/SQRT3 > 1e-8:
        return False
    return True

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5 / TRIANGLE_AREA

class MinAreaTracker:
    def __init__(self, pts: np.ndarray):
        self.pts = pts.copy()
        self.n = len(pts)
        self.min_area = float('inf')
        self.min_triplet = None
        self._update_min_area()

    def _update_min_area(self):
        self.min_area = float('inf')
        for i in range(self.n):
            for j in range(i+1, self.n):
                for k in range(j+1, self.n):
                    a = _area(self.pts[i], self.pts[j], self.pts[k])
                    if a < self.min_area:
                        self.min_area = a
                        self.min_triplet = (i, j, k)

    def update_point(self, idx: int, new_pos: np.ndarray) -> bool:
        if not _is_inside_triangle(new_pos):
            return False
        old_pos = self.pts[idx].copy()
        self.pts[idx] = new_pos

        # Only recompute affected triangles
        affected = []
        for i in range(self.n):
            for j in range(i+1, self.n):
                if i == idx or j == idx:
                    affected.append((i, j))

        new_min = float('inf')
        for i, j in affected:
            for k in range(self.n):
                if k != i and k != j:
                    a = _area(self.pts[i], self.pts[j], self.pts[k])
                    if a < new_min:
                        new_min = a

        if new_min < self.min_area:
            self.min_area = new_min
            return True
        return True

    def get_min_area(self) -> float:
        return self.min_area

def _hexagonal_grid_points(n: int) -> List[np.ndarray]:
    k = math.ceil(math.sqrt(n / (SQRT3/4)))
    points = []
    for i in range(k):
        for j in range(k):
            x = (i + 0.5 * (j % 2)) / (k - 1)
            y = (j * SQRT3 / 2) / (k - 1)
            if _is_inside_triangle(np.array([x, y])):
                points.append(np.array([x, y]))
                if len(points) >= n:
                    return points
    return points

def _optimize(n_pts: int = 11, max_time: float = 28.0, seed: int | None = None) -> np.ndarray:
    import time
    start_time = time.time()

    rng = np.random.default_rng(seed)
    pts = np.array(_hexagonal_grid_points(n_pts))
    while len(pts) < n_pts:
        new_pt = np.array([rng.uniform(0, 1), rng.uniform(0, SQRT3/2)])
        if _is_inside_triangle(new_pt):
            pts = np.vstack([pts, new_pt])

    tracker = MinAreaTracker(pts)
    best_pts = pts.copy()
    best_val = tracker.get_min_area()

    no_improve = 0
    step_size = 0.1

    while time.time() - start_time < max_time and no_improve < 1000:
        idx = rng.integers(0, n_pts)
        old_pos = pts[idx].copy()

        angle = rng.uniform(0, 2*math.pi)
        dx = step_size * math.cos(angle)
        dy = step_size * math.sin(angle)
        new_pos = np.array([old_pos[0] + dx, old_pos[1] + dy])

        if not tracker.update_point(idx, new_pos):
            continue

        current_val = tracker.get_min_area()

        if current_val > best_val:
            best_val = current_val
            best_pts = tracker.pts.copy()
            no_improve = 0
            step_size = min(0.1, step_size * 1.1)
        else:
            tracker.update_point(idx, old_pos)
            no_improve += 1
            step_size = max(0.001, step_size * 0.9)

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    pts = _optimize(n_pts=11, max_time=28.0, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

