import math
import random
import numpy as np

SQRT3 = math.sqrt(3.0)
INV_SQRT3 = 1.0 / SQRT3

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    # Precompute all pairwise vectors
    vecs = np.array([(pts[i], pts[j]) 
                    for i in range(n) 
                    for j in range(i+1, n)])
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    u, v = random.random(), random.random()
    if u + v > 1.0:
        u, v = 1 - u, 1 - v
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv[0], uv[1]
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _initial_points(n: int) -> np.ndarray:
    if n < 7:
        return np.array([_random_point() for _ in range(n)])

    # Hexagonal grid initialization
    k = int(math.sqrt(2*n)) + 2
    pts = []
    for i in range(k):
        y = SQRT3 * i / (2*(k-1))
        for j in range(k - i):
            x = 0.5 * j / (k-1) + (0.5*i/(k-1) if i % 2 else 0)
            pts.append(np.array([x + random.uniform(-0.01,0.01), 
                               y + random.uniform(-0.01,0.01)]))
    if len(pts) < n:
        pts.extend([_random_point() for _ in range(n - len(pts))])
    selected = pts[:n] if len(pts) <= n else random.sample(pts, n)
    return np.array(selected)

def _anneal(n_pts: int = 11, iters: int = 5000, seed: int | None = 0) -> np.ndarray:
    random.seed(seed)
    pts = _initial_points(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        T = max(0.01, 0.3 * (1 - (t/iters)**1.5))  # Slower cooling
        idx = random.randrange(n_pts)
        trial = pts.copy()
        step = 0.03 * (1 - (t/iters)**0.7)  # More gradual step reduction
        trial[idx] += random.uniform(-step, step), random.uniform(-step, step)
        trial[idx] = _project_to_simplex(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or random.random() < math.exp(delta / max(T, 1e-12)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

        # Early exit if no improvement for a while
        if t > 1000 and best_val == 0:
            break

    return best_pts

def find_points(seed: int | None = 0) -> list[tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=5000, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

import math
import random
import itertools
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p, q, r) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5 / TRIANGLE_AREA

def _min_triangle_area(pts: np.ndarray) -> float:
    triangles = list(itertools.combinations(pts, 3))
    return min(_area(p, q, r) for p, q, r in triangles)

def _is_inside_triangle(pt: np.ndarray) -> bool:
    x, y = pt
    if x < 0 or x > 1 or y < 0 or y > SQRT3/2:
        return False
    if y > SQRT3 * x:
        return False
    if y > SQRT3 * (1 - x):
        return False
    return True

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    x = u + v * 0.5
    y = v * SQRT3 / 2
    return np.array([x, y])

def _hexagonal_grid_points(n: int) -> List[np.ndarray]:
    points = []
    layers = math.ceil(math.sqrt(n))
    for i in range(layers):
        for j in range(layers - i):
            x = (i + 0.5 * j) / layers
            y = j * SQRT3 / (2 * layers)
            if _is_inside_triangle([x, y]):
                points.append(np.array([x, y]))
                if len(points) >= n:
                    return points
    return points

def _initial_configuration(n_pts: int = 11) -> np.ndarray:
    pts = _hexagonal_grid_points(n_pts)
    while len(pts) < n_pts:
        pt = _random_point()
        pts.append(pt)
    return np.array(pts[:n_pts])

def _optimize_points(pts: np.ndarray, iterations: int = 50000) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)
    n = len(pts)

    for i in range(iterations):
        temp = 0.1 * (1 - i/iterations)
        step = 0.02 * (1 - i/iterations)

        idx = random.randint(0, n-1)
        trial = best_pts.copy()
        trial[idx] += np.random.uniform(-step, step, 2)

        if not _is_inside_triangle(trial[idx]):
            continue

        trial_area = _min_triangle_area(trial)

        if trial_area > best_area or random.random() < math.exp((trial_area - best_area)/temp):
            best_pts = trial.copy()
            best_area = trial_area

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _initial_configuration(11)
    pts = _optimize_points(pts, 50000)

    # Final verification
    for pt in pts:
        if not _is_inside_triangle(pt):
            pt[:] = _random_point()

    return [(float(x), float(y)) for x, y in pts]

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
EPSILON = 1e-8

def _is_inside_triangle(p: np.ndarray) -> bool:
    x, y = p
    if x < 0 or x > 1 or y < 0 or y > SQRT3/2:
        return False
    if y > -SQRT3 * x + SQRT3 + EPSILON or y > SQRT3 * x + EPSILON:
        return False
    return True

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v > 1.0:
            u, v = 1 - u, 1 - v
        p = np.array([(1 - u - v) * 0 + u * 1 + v * 0.5,
                     (1 - u - v) * 0 + u * 0 + v * SQRT3/2])
        if _is_inside_triangle(p):
            return p

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    x, y = p
    x = max(0, min(1, x))
    y = max(0, min(SQRT3/2, y))
    if y > -SQRT3 * x + SQRT3:
        y = -SQRT3 * x + SQRT3 - EPSILON
    if y > SQRT3 * x:
        y = SQRT3 * x - EPSILON
    return np.array([x, y])

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                x1, y1 = pts[i]
                x2, y2 = pts[j]
                x3, y3 = pts[k]
                area = abs((x2-x1)*(y3-y1) - (x3-x1)*(y2-y1)) / 2
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0.0
    return min_area

def _initialize_hexagonal(n: int) -> np.ndarray:
    pts = []
    layers = math.ceil(math.sqrt(n / 3))
    for i in range(-layers, layers+1):
        for j in range(-layers, layers+1):
            x = 0.5 + 0.5 * i + 0.25 * j
            y = SQRT3/4 * j
            p = np.array([x, y])
            if _is_inside_triangle(p):
                pts.append(p)
    pts = np.array(pts)
    if len(pts) > n:
        pts = pts[np.random.choice(len(pts), n, replace=False)]
    return pts

def _optimize_points(pts: np.ndarray, iterations: int = 1000) -> np.ndarray:
    n = len(pts)
    best_pts = pts.copy()
    best_area = _min_triangle_area(pts)

    for _ in range(iterations):
        vecs = pts[:, np.newaxis] - pts
        dists = np.linalg.norm(vecs, axis=2)
        np.fill_diagonal(dists, np.inf)

        forces = np.zeros_like(pts)
        for i in range(n):
            for j in range(n):
                if i != j and dists[i,j] < 0.15:
                    direction = vecs[i,j] / (dists[i,j]**2 + 1e-8)
                    forces[i] += direction * 0.01

        temp = 1.0 - (_ / iterations)
        new_pts = pts + forces * temp * 0.1

        for i in range(n):
            new_pts[i] = _project_to_triangle(new_pts[i])

        new_area = _min_triangle_area(new_pts)
        if new_area > best_area:
            best_area = new_area
            best_pts = new_pts.copy()
            pts = new_pts.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    pts = _initialize_hexagonal(11)
    if len(pts) < 11:
        extra = 11 - len(pts)
        pts = np.vstack([pts, np.array([_random_point() for _ in range(extra)])])

    pts = _optimize_points(pts, iterations=1500)

    best_area = _min_triangle_area(pts)
    for _ in range(300):
        idx = random.randint(0, 10)
        new_pt = pts.copy()
        angle = random.uniform(0, 2*math.pi)
        r = random.uniform(0, 0.005)
        new_pt[idx] += r * math.cos(angle), r * math.sin(angle)
        new_pt[idx] = _project_to_triangle(new_pt[idx])
        new_area = _min_triangle_area(new_pt)
        if new_area > best_area:
            best_area = new_area
            pts = new_pt.copy()

    return [(float(x), float(y)) for x, y in pts]

