import math
import random
import numpy as np
from scipy.spatial import Delaunay
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p1, p2, p3) -> float:
    return abs((p2[0]-p1[0])*(p3[1]-p1[1]) - (p2[1]-p1[1])*(p3[0]-p1[0])) / (2 * TRIANGLE_AREA)

def _min_triangle_area(pts: np.ndarray) -> float:
    tri = Delaunay(pts)
    min_area = float('inf')
    for simplex in tri.simplices:
        a = _area(pts[simplex[0]], pts[simplex[1]], pts[simplex[2]])
        if a < min_area:
            min_area = a
            if min_area == 0:
                return 0
    return min_area

def _is_inside_triangle(p: np.ndarray) -> bool:
    x, y = p
    if y < 0 or y > SQRT3/2:
        return False
    if x < 0 or x > 1:
        return False
    if y > SQRT3 * x:
        return False
    if y > SQRT3 * (1 - x):
        return False
    return True

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    x, y = p
    if y < 0:
        y = 0
    if y > SQRT3/2:
        y = SQRT3/2
    if x < 0:
        x = 0
    if x > 1:
        x = 1
    if y > SQRT3 * x:
        y = SQRT3 * x
    if y > SQRT3 * (1 - x):
        y = SQRT3 * (1 - x)
    return np.array([x, y])

def _generate_hexagonal_points(n: int = 11) -> np.ndarray:
    pts = []
    layers = 3
    radius = 0.2

    center = np.array([0.5, SQRT3/4])
    pts.append(center)

    for layer in range(1, layers):
        for i in range(6):
            angle = math.pi/3 * i
            for j in range(layer):
                offset = radius * layer * np.array([math.cos(angle), math.sin(angle)])
                pt = center + offset
                if _is_inside_triangle(pt):
                    pts.append(pt)
                    if len(pts) == n:
                        return np.array(pts)

    while len(pts) < n:
        x = random.uniform(0, 1)
        y = random.uniform(0, SQRT3/2)
        p = np.array([x, y])
        if _is_inside_triangle(p):
            pts.append(p)

    return np.array(pts[:n])

def _optimize_simulated_annealing(pts: np.ndarray, iterations: int = 8000) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)
    current_pts = best_pts.copy()
    current_area = best_area
    n = len(pts)

    temp = 1.0
    cooling_rate = 0.9999

    for iter in range(iterations):
        temp *= cooling_rate
        step_size = 0.05 * temp

        trial = current_pts.copy()
        for i in range(n):
            dx = random.uniform(-step_size, step_size)
            dy = random.uniform(-step_size, step_size)
            trial[i] += [dx, dy]
            trial[i] = _project_to_triangle(trial[i])

        trial_area = _min_triangle_area(trial)

        if trial_area > current_area or random.random() < math.exp((trial_area - current_area)/temp):
            current_area = trial_area
            current_pts = trial.copy()

            if current_area > best_area:
                best_area = current_area
                best_pts = current_pts.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    best_pts = None
    best_area = 0.0

    for _ in range(5):
        pts = _generate_hexagonal_points(11)
        pts = _optimize_simulated_annealing(pts, 8000)

        current_area = _min_triangle_area(pts)
        if current_area > best_area:
            best_area = current_area
            best_pts = pts.copy()

    return [(float(x), float(y)) for x, y in best_pts]

