import math
import random
import itertools
from typing import List, Tuple
import numpy as np

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    best = float("inf")
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    w = 1.0 - u - v
    if u >= 0 and v >= 0 and w >= 0:
        return p
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        s = u + v
        u /= s
        v /= s
    return (1 - u - v) * _A + u * _B + v * _C

def _optimal_lattice_configuration(n_pts: int = 11) -> np.ndarray:
    layers = math.ceil(math.sqrt(n_pts * 2 / SQRT3)) + 1
    pts = []
    for i in range(layers):
        for j in range(layers - i):
            u = (i + 0.5 * j + 0.5) / (layers + 1)
            v = (j * SQRT3 / 2 + 0.5) / (layers + 1)
            if u + v <= 1.0:
                pts.append((1 - u - v) * _A + u * _B + v * _C)
    while len(pts) < n_pts:
        pts.append(_random_point())
    return np.array(pts[:n_pts])

def _gradient_optimize(pts: np.ndarray, steps: int, initial_step: float) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    n_pts = len(pts)
    step = initial_step
    no_improve = 0

    for _ in range(steps):
        improved = False
        for idx in np.random.permutation(n_pts):
            for _ in range(5):
                delta = np.random.normal(0, step, 2)
                trial = best_pts.copy()
                trial[idx] += delta
                trial[idx] = _project_to_simplex(trial[idx])
                trial_val = _min_triangle_area(trial)
                if trial_val > best_val and trial_val > 0:
                    best_val = trial_val
                    best_pts = trial.copy()
                    improved = True
                    break

        if improved:
            no_improve = 0
            step = min(initial_step, step * 1.05)
        else:
            no_improve += 1
            step *= 0.8
            if no_improve > 10:
                break

    return best_pts

def _remove_colinear(pts: np.ndarray) -> np.ndarray:
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                if _area(pts[i], pts[j], pts[k]) == 0:
                    pts[k] = _random_point()
    return pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    pts = _optimal_lattice_configuration(11)
    pts = _remove_colinear(pts)

    pts = _gradient_optimize(pts, steps=300, initial_step=0.05)
    pts = _remove_colinear(pts)
    pts = _gradient_optimize(pts, steps=500, initial_step=0.02)
    pts = _remove_colinear(pts)
    pts = _gradient_optimize(pts, steps=1000, initial_step=0.01)
    pts = _remove_colinear(pts)
    pts = _gradient_optimize(pts, steps=1500, initial_step=0.005)
    pts = _remove_colinear(pts)

    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

