def _is_inside(p: np.ndarray) -> bool:
    try:
        u, v = np.linalg.solve(np.column_stack((_B-_A, _C-_A)), p-_A)
    except:
        return False
    return u >= -1e-8 and v >= -1e-8 and (1-u-v) >= -1e-8

def _generate_initial_points(n: int) -> np.ndarray:
    pts = []
    # Add symmetric points first
    if n >= 3:
        pts.extend([_A, _B, _C])
    if n >= 6:
        pts.extend([(_A+_B)/2, (_A+_C)/2, (_B+_C)/2])

    while len(pts) < n:
        x = random.uniform(0, 1)
        y_max = SQRT3 * min(x, 1-x)
        y = random.uniform(0, y_max)
        p = np.array([x, y])
        if _is_inside(p):
            pts.append(p)
    return np.array(pts)

def _differential_evolution(n_pts: int, max_iter: int) -> np.ndarray:
    pop_size = 20
    F = 0.7
    CR = 0.8

    pop = [_generate_initial_points(n_pts).flatten() for _ in range(pop_size)]
    best_sol = pop[0]
    best_val = -_min_triangle_area(best_sol.reshape(n_pts, 2))

    for _ in range(max_iter):
        for i in range(pop_size):
            idxs = [idx for idx in range(pop_size) if idx != i]
            a, b, c = [pop[idx] for idx in np.random.choice(idxs, 3, replace=False)]
            mutant = a + F * (b - c)

            cross_points = np.random.rand(n_pts*2) < CR
            trial = np.where(cross_points, mutant, pop[i])

            trial_pts = trial.reshape(n_pts, 2)
            for j in range(n_pts):
                if not _is_inside(trial_pts[j]):
                    trial_pts[j] = np.clip(trial_pts[j], [0, 0], [1, SQRT3/2])
                    u, v = np.linalg.solve(np.column_stack((_B-_A, _C-_A)), trial_pts[j]-_A)
                    u = max(0, min(1, u))
                    v = max(0, min(1, v))
                    if u + v > 1:
                        u, v = u/(u+v), v/(u+v)
                    trial_pts[j] = _A + u*(_B-_A) + v*(_C-_A)

            trial_val = -_min_triangle_area(trial_pts)
            if trial_val < best_val:
                best_val = trial_val
                best_sol = trial.copy()
            if trial_val < -_min_triangle_area(pop[i].reshape(n_pts, 2)):
                pop[i] = trial

    return best_sol.reshape(n_pts, 2)

def _find_critical_points(pts: np.ndarray) -> set:
    n = len(pts)
    min_area = _min_triangle_area(pts)
    critical = set()

    for i in range(n-2):
        for j in range(i+1, n-1):
            for k in range(j+1, n):
                area = _area(pts[i], pts[j], pts[k])
                if abs(area - min_area) < 1e-8:
                    critical.update([i, j, k])
    return critical

def _refine(pts: np.ndarray, steps: int) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for step in range(steps):
        step_size = 0.01 * (1 - step/steps)
        critical = _find_critical_points(best_pts)

        for idx in critical:
            for _ in range(10):
                trial = best_pts.copy()
                delta = np.random.uniform(-step_size, step_size, 2)
                trial[idx] += delta
                if _is_inside(trial[idx]):
                    trial_val = _min_triangle_area(trial)
                    if trial_val > best_val:
                        best_val = trial_val
                        best_pts = trial.copy()
                else:
                    trial[idx] = np.clip(trial[idx], [0, 0], [1, SQRT3/2])
                    u, v = np.linalg.solve(np.column_stack((_B-_A, _C-_A)), trial[idx]-_A)
                    u = max(0, min(1, u))
                    v = max(0, min(1, v))
                    if u + v > 1:
                        u, v = u/(u+v), v/(u+v)
                    trial[idx] = _A + u*(_B-_A) + v*(_C-_A)
                    trial_val = _min_triangle_area(trial)
                    if trial_val > best_val:
                        best_val = trial_val
                        best_pts = trial.copy()
    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    pts = _differential_evolution(n_pts=11, max_iter=25)
    pts = _refine(pts, steps=60)

    return [(float(x), float(y)) for x, y in pts]

from __future__ import annotations

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / (2 * TRIANGLE_AREA)

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    vectors = pts - pts[:, np.newaxis]
    for i in range(n):
        for j in range(i+1, n):
            p0 = vectors[i,j]
            for k in range(j+1, n):
                p1 = vectors[i,k]
                area = abs(p0[0]*p1[1] - p0[1]*p1[0]) / (2 * TRIANGLE_AREA)
                if area < min_area:
                    min_area = area
                    if min_area < 0.001:
                        return min_area
    return min_area

def _random_point_in_triangle() -> np.ndarray:
    r1 = random.random()
    r2 = random.random()
    if r1 + r2 > 1:
        r1 = 1 - r1
        r2 = 1 - r2
    x = r1 * 1.0 + r2 * 0.5
    y = r2 * SQRT3 / 2.0
    return np.array([x, y])

def _initialize_points(n_pts: int) -> np.ndarray:
    # Optimized initial configuration for 11 points
    pts = []
    layers = 4
    for i in range(layers):
        for j in range(layers):
            if i + j > layers-1:
                continue
            x = (i + j/2) / (layers-0.8)
            y = j * SQRT3 / (2*layers-1.6)
            pts.append(np.array([x, y]))

    # Mirror points
    mirror = [np.array([1-x, y]) for x,y in pts]
    pts.extend(mirror)

    # Add center point
    if len(pts) < n_pts:
        pts.append(np.array([0.5, SQRT3/4]))

    # Fill remaining with optimized random points
    while len(pts) < n_pts:
        new_pt = _random_point_in_triangle()
        min_dist = min(np.linalg.norm(new_pt - p) for p in pts) if pts else float('inf')
        if min_dist > 0.12 or len(pts) >= n_pts-2:
            pts.append(new_pt)

    return np.array(pts[:n_pts])

def _is_in_triangle(p: np.ndarray) -> bool:
    x, y = p
    if y < 0 or y > SQRT3/2:
        return False
    if x < 0 or x > 1:
        return False
    if y > SQRT3 * x or y > SQRT3 * (1 - x):
        return False
    return True

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    x, y = p
    if _is_in_triangle(p):
        return p

    edge1 = lambda x: SQRT3 * x
    edge2 = lambda x: SQRT3 * (1 - x)

    if y < 0:
        x = max(0.01, min(0.99, x))
        return np.array([x, 0.01])

    d1 = abs(y - edge1(x))
    d2 = abs(y - edge2(x))

    if d1 < d2:
        y_proj = edge1(x)
        return np.array([max(0.01, min(0.99, x)), max(0.01, min(y_proj, SQRT3/2 - 0.01))])
    else:
        y_proj = edge2(x)
        return np.array([max(0.01, min(0.99, x)), max(0.01, min(y_proj, SQRT3/2 - 0.01))])

def _anneal(n_pts: int = 11,
            max_iters: int = 120000,
            start_temp: float = 0.3,
            end_temp: float = 1e-12,
            seed: int | None = None) -> np.ndarray:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _initialize_points(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    no_improve = 0

    for t in range(max_iters):
        T = start_temp * (1 - t/max_iters)**3  # More aggressive cooling

        idx = random.randrange(n_pts)
        trial = pts.copy()

        if t % 500 == 0 or best_val < 0.01 or no_improve > 800:
            trial[idx] = _random_point_in_triangle()
        else:
            step_size = 0.08 * (1 - t/max_iters)**2 + 0.02
            delta = np.random.normal(0, step_size, size=2)
            trial[idx] += delta
            trial[idx] = _project_to_triangle(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta_val = trial_val - best_val

        if delta_val > 0 or (T > 1e-12 and math.exp(delta_val / T) > random.random()):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()
                no_improve = 0
            else:
                no_improve += 1
        else:
            no_improve += 1

        if no_improve > 1500 and t > 30000:
            break

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

