import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5 / TRIANGLE_AREA

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    if n < 3: return 0.0
    best = float('inf')

    # Use spatial partitioning to reduce checks
    for i in range(n):
        for j in range(i+1, min(i+10, n)):
            for k in range(j+1, min(j+10, n)):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0.0
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _hexagonal_grid(n: int) -> np.ndarray:
    pts = []
    layers = math.ceil(math.sqrt(n / 3)) + 1
    for i in range(-layers, layers+1):
        for j in range(-layers, layers+1):
            x = 0.5 + 0.5 * i + 0.5 * j
            y = SQRT3/2 * j
            if x >= 0 and y >= 0 and (1 - x - y/SQRT3*2) >= 0:
                pts.append(np.array([x, y]))
    return np.array(pts[:n]) if len(pts) >= n else np.concatenate(
        [np.array(pts), _random_points(n - len(pts))])

def _random_points(n: int) -> np.ndarray:
    pts = []
    for _ in range(n):
        u, v = random.random(), random.random()
        if u + v > 1.0:
            u, v = 1 - u, 1 - v
        pts.append((1 - u - v) * _A + u * _B + v * _C)
    return np.array(pts)

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = max(0.0, uv[0]), max(0.0, uv[1])
    u, v = min(1.0, u), min(1.0 - u, v)
    return (1 - u - v) * _A + u * _B + v * _C

def _optimize(pts: np.ndarray, max_iter: int = 5000) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    n = len(pts)

    for iter in range(max_iter):
        T = max(0.01, 0.2 * (1 - iter/max_iter))
        step = 0.05 * (1 - iter/max_iter) + 0.005

        for _ in range(5):
            idx = random.randint(0, n-1)
            direction = np.random.normal(0, 1, 2)
            direction /= np.linalg.norm(direction)

            trial = best_pts.copy()
            trial[idx] += step * direction
            trial[idx] = _project_to_triangle(trial[idx])
            trial_val = _min_triangle_area(trial)

            if trial_val > best_val or (random.random() < math.exp((trial_val - best_val)/T)):
                best_pts = trial.copy()
                best_val = trial_val

        # Periodic perturbation
        if iter % 100 == 0 and iter > 0:
            for idx in random.sample(range(n), min(3, n)):
                best_pts[idx] = _project_to_triangle(best_pts[idx] + np.random.normal(0, 0.02, 2))

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    # Start with hexagonal grid
    pts = _hexagonal_grid(11)

    # Optimize with simulated annealing + local search
    pts = _optimize(pts, max_iter=5000)

    # Final local refinement
    best_val = _min_triangle_area(pts)
    for _ in range(100):
        for i in range(11):
            for dx, dy in [(0.01,0), (-0.01,0), (0,0.01), (0,-0.01)]:
                trial = pts.copy()
                trial[i] += dx, dy
                trial[i] = _project_to_triangle(trial[i])
                trial_val = _min_triangle_area(trial)
                if trial_val > best_val:
                    pts = trial.copy()
                    best_val = trial_val

    return [(float(x), float(y)) for x, y in pts]

