import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    best = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

def _hex_grid(n: int) -> np.ndarray:
    max_retries = 3
    layers = math.ceil(math.sqrt(n * 2)) + 2

    for _ in range(max_retries):
        pts = []
        for i in range(-layers, layers+1):
            for j in range(-layers, layers+1):
                x = 0.5 + 0.5 * i + 0.25 * j
                y = SQRT3/4 * j
                pts.append([x, y])
        pts = np.array(pts)
        inside = []
        for p in pts:
            try:
                uv = np.linalg.solve(np.column_stack((_B-_A, _C-_A)), p-_A)
                u = uv[0] if isinstance(uv, np.ndarray) else uv
                v = uv[1] if isinstance(uv, np.ndarray) else 0
                if u >= 0 and v >= 0 and (1-u-v) >= 0:
                    inside.append(p)
            except:
                continue
        if len(inside) >= n:
            if len(inside) == 0:
                break
            indices = np.random.choice(len(inside), min(n, len(inside)), replace=False)
            return np.array(inside)[indices]
        layers += 1

    # Fallback to random points if hex grid fails
    pts = []
    while len(pts) < n:
        x, y = np.random.uniform(0, 1, 2)
        uv = np.linalg.solve(np.column_stack((_B-_A, _C-_A)), np.array([x,y])-_A)
        u = uv[0] if isinstance(uv, np.ndarray) else uv
        v = uv[1] if isinstance(uv, np.ndarray) else 0
        if u >= 0 and v >= 0 and (1-u-v) >= 0:
            pts.append([x, y])
    return np.array(pts)

def _differential_evolution(pop_size: int, n_pts: int, max_iter: int) -> np.ndarray:
    F = 0.8
    CR = 0.9

    def eval_fn(x):
        pts = x.reshape(n_pts, 2)
        return -_min_triangle_area(pts)

    pop = []
    for _ in range(pop_size):
        pts = _hex_grid(n_pts)
        pop.append(pts.flatten())

    best_sol = pop[0].copy()
    best_val = eval_fn(best_sol)

    for _ in range(max_iter):
        for i in range(pop_size):
            idxs = [idx for idx in range(pop_size) if idx != i]
            if len(idxs) < 3:
                continue
            a, b, c = pop[np.random.choice(idxs, 3, replace=False)]
            mutant = a + F * (b - c)

            trial = np.zeros_like(pop[i])
            cross_points = np.random.rand(n_pts*2) < CR
            trial[cross_points] = mutant[cross_points]
            trial[~cross_points] = pop[i][~cross_points]

            for j in range(n_pts):
                x, y = trial[j*2], trial[j*2+1]
                uv = np.linalg.solve(np.column_stack((_B-_A, _C-_A)), np.array([x,y])-_A)
                u = uv[0] if isinstance(uv, np.ndarray) else uv
                v = uv[1] if isinstance(uv, np.ndarray) else 0
                if u < 0 or v < 0 or (1-u-v) < 0:
                    trial[j*2:j*2+2] = pop[i][j*2:j*2+2]

            trial_val = eval_fn(trial)
            if trial_val < best_val:
                best_val = trial_val
                best_sol = trial.copy()
            if trial_val < eval_fn(pop[i]):
                pop[i] = trial

    return best_sol.reshape(n_pts, 2)

def _refine(pts: np.ndarray, steps: int) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    n_pts = len(pts)

    for step in range(steps):
        step_size = 0.01 * (1 - step/steps)
        for idx in range(n_pts):
            for _ in range(5):
                trial = best_pts.copy()
                trial[idx] += np.random.uniform(-step_size, step_size, 2)
                try:
                    uv = np.linalg.solve(np.column_stack((_B-_A, _C-_A)), trial[idx]-_A)
                    u = uv[0] if isinstance(uv, np.ndarray) else uv
                    v = uv[1] if isinstance(uv, np.ndarray) else 0
                    if u < 0 or v < 0 or (1-u-v) < 0:
                        continue
                except:
                    continue
                trial_val = _min_triangle_area(trial)
                if trial_val > best_val:
                    best_val = trial_val
                    best_pts = trial.copy()
    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    pts = _differential_evolution(pop_size=15, n_pts=11, max_iter=30)
    pts = _refine(pts, steps=300)

    return [(float(x), float(y)) for x, y in pts]

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    best = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

def _hexagonal_grid(n: int) -> np.ndarray:
    pts = []
    size = int(math.ceil(math.sqrt(n * 1.5)))
    margin = 0.05
    for i in range(size):
        for j in range(size):
            if len(pts) >= n:
                break
            x = 0.5 + (i - j) * (0.5 - margin) / size
            y = j * (SQRT3/2 - margin) / size + margin
            y_max = SQRT3*(1 - abs(2*x - 1))
            if y <= y_max - 1e-8:
                pts.append([x, y])
    while len(pts) < n:
        x = random.uniform(margin, 1 - margin)
        y_max = SQRT3*(1 - abs(2*x - 1)) - margin
        y = random.uniform(margin, y_max)
        pts.append([x, y])
    return np.array(pts)

def _optimize_points(pts: np.ndarray, iterations: int = 2000) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)
    n = len(pts)

    for _ in range(iterations):
        new_pts = best_pts.copy()
        idx = random.randint(0, n-1)
        step = 0.05 * (1 - _/iterations)
        new_pts[idx] += np.random.uniform(-step, step, 2)

        x, y = new_pts[idx]
        y_max = SQRT3*(1 - abs(2*x - 1))
        if not (0 <= x <= 1 and 0 <= y <= y_max - 1e-8):
            continue

        new_area = _min_triangle_area(new_pts)
        if new_area > best_area:
            best_area = new_area
            best_pts = new_pts.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _hexagonal_grid(11)
    pts = _optimize_points(pts, 2000)

    # Final boundary check and repair
    for p in pts:
        x, y = p
        y_max = SQRT3*(1 - abs(2*x - 1))
        if not (0 <= x <= 1 and 0 <= y <= y_max - 1e-8):
            x = min(max(x, 0), 1)
            y_max = SQRT3*(1 - abs(2*x - 1))
            p[0] = x
            p[1] = min(max(y, 0), y_max - 1e-8)

    return [(float(x), float(y)) for x, y in pts]

