import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    best = float("inf")
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

def _random_barycentric() -> Tuple[float, float, float]:
    while True:
        u = random.random()
        v = random.random()
        if u + v <= 1:
            return (1 - u - v, u, v)

def _barycentric_to_cartesian(b: Tuple[float, float, float]) -> np.ndarray:
    a1, a2, a3 = b
    x = a2 + a3 * 0.5
    y = a3 * SQRT3 / 2
    return np.array([x, y])

def _cartesian_to_barycentric(p: np.ndarray) -> Tuple[float, float, float]:
    x, y = p
    a3 = y * 2 / SQRT3
    a2 = x - a3 * 0.5
    a1 = 1 - a2 - a3
    return (a1, a2, a3)

def _valid_barycentric(b: Tuple[float, float, float]) -> bool:
    a1, a2, a3 = b
    return a1 >= 0 and a2 >= 0 and a3 >= 0 and abs(a1 + a2 + a3 - 1) < 1e-8

def _initial_configuration(n_pts: int = 11) -> np.ndarray:
    pts = []
    # Start with hexagonal pattern
    for i in range(4):
        for j in range(4):
            if i + j < 4 and len(pts) < n_pts:
                x = 0.2 + 0.2 * j + 0.1 * i
                y = 0.1 + i * 0.2 * SQRT3/2
                pts.append(np.array([x, y]))

    # Fill remaining points randomly if needed
    while len(pts) < n_pts:
        b = _random_barycentric()
        p = _barycentric_to_cartesian(b)
        pts.append(p)
    return np.array(pts)

def _optimize(pts: np.ndarray, steps: int, step_size: float) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    n_pts = len(pts)

    for step in range(steps):
        trial = best_pts.copy()
        # Move multiple points (3) in each step
        for _ in range(3):
            idx = random.randrange(n_pts)
            current_b = _cartesian_to_barycentric(trial[idx])
            new_b = (
                max(0.01, min(0.99, current_b[0] + random.uniform(-step_size, step_size))),
                max(0.01, min(0.99, current_b[1] + random.uniform(-step_size, step_size))),
                max(0.01, min(0.99, current_b[2] + random.uniform(-step_size, step_size)))
            )
            s = sum(new_b)
            new_b = (new_b[0]/s, new_b[1]/s, new_b[2]/s)
            if _valid_barycentric(new_b):
                trial[idx] = _barycentric_to_cartesian(new_b)

        trial_val = _min_triangle_area(trial)

        if trial_val > best_val:
            best_val = trial_val
            best_pts = trial.copy()
            # Adaptive step size increase when improving
            step_size = min(0.2, step_size * 1.1)
        else:
            # Adaptive step size decrease when not improving
            step_size = max(0.01, step_size * 0.95)

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    pts = _initial_configuration(11)

    pts = _optimize(pts, steps=800, step_size=0.1)
    pts = _optimize(pts, steps=800, step_size=0.05)
    pts = _optimize(pts, steps=800, step_size=0.02)

    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

from __future__ import annotations
import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])
TRI_AREA = SQRT3 / 4.0

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n-2):
        p0 = pts[i]
        for j in range(i+1, n-1):
            p1 = pts[j]
            dx1 = p1[0] - p0[0]
            dy1 = p1[1] - p0[1]
            for k in range(j+1, n):
                dx2 = pts[k][0] - p0[0]
                dy2 = pts[k][1] - p0[1]
                area = abs(dx1*dy2 - dx2*dy1) * 0.5
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0
    return min_area

def _is_inside(p: np.ndarray) -> bool:
    try:
        u, v = np.linalg.solve(np.column_stack((_B-_A, _C-_A)), p-_A)
    except:
        return False
    return u >= -1e-8 and v >= -1e-8 and (1-u-v) >= -1e-8

def _generate_initial_points(n: int) -> np.ndarray:
    pts = []
    while len(pts) < n:
        x = random.uniform(0, 1)
        y_max = SQRT3 * min(x, 1-x)
        y = random.uniform(0, y_max)
        p = np.array([x, y])
        if _is_inside(p):
            pts.append(p)
    return np.array(pts)

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    u, v = np.linalg.solve(np.column_stack((_B-_A, _C-_A)), p-_A)
    u = max(0, min(1, u))
    v = max(0, min(1, v))
    if u + v > 1:
        u, v = u/(u+v), v/(u+v)
    return _A + u*(_B-_A) + v*(_C-_A)

def _differential_evolution(n_pts: int, max_iter: int) -> np.ndarray:
    pop_size = 15
    F = 0.7
    CR = 0.85

    pop = [_generate_initial_points(n_pts).flatten() for _ in range(pop_size)]
    best_sol = pop[0]
    best_val = -_min_triangle_area(best_sol.reshape(n_pts, 2))

    for _ in range(max_iter):
        for i in range(pop_size):
            idxs = [idx for idx in range(pop_size) if idx != i]
            a, b, c = [pop[idx] for idx in np.random.choice(idxs, 3, replace=False)]
            mutant = a + F * (b - c)

            cross_points = np.random.rand(n_pts*2) < CR
            trial = np.where(cross_points, mutant, pop[i])

            trial_pts = trial.reshape(n_pts, 2)
            for j in range(n_pts):
                if not _is_inside(trial_pts[j]):
                    trial_pts[j] = _project_to_triangle(trial_pts[j])

            trial_val = -_min_triangle_area(trial_pts)
            if trial_val < best_val:
                best_val = trial_val
                best_sol = trial.copy()
            if trial_val < -_min_triangle_area(pop[i].reshape(n_pts, 2)):
                pop[i] = trial

    return best_sol.reshape(n_pts, 2)

def _refine(pts: np.ndarray, steps: int) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    n_pts = len(pts)

    for step in range(steps):
        step_size = 0.01 * (1 - step/steps)
        for idx in range(n_pts):
            for _ in range(5):
                trial = best_pts.copy()
                delta = np.random.uniform(-step_size, step_size, 2)
                trial[idx] += delta
                if not _is_inside(trial[idx]):
                    trial[idx] = _project_to_triangle(trial[idx])
                trial_val = _min_triangle_area(trial)
                if trial_val > best_val:
                    best_val = trial_val
                    best_pts = trial.copy()
    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    pts = _differential_evolution(n_pts=11, max_iter=30)
    pts = _refine(pts, steps=100)

    return [(float(x), float(y)) for x, y in pts]

