import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRI_AREA = SQRT3 / 4.0

def _is_inside(p: np.ndarray) -> bool:
    x, y = p
    if x < 0 or x > 1 or y < 0 or y > SQRT3/2:
        return False
    if y > SQRT3 * x or y > SQRT3 * (1 - x):
        return False
    return True

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    cross = (q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])
    return abs(cross) / (2 * TRI_AREA)

def _min_triangle_area(pts: np.ndarray) -> float:
    min_area = float('inf')
    n = len(pts)
    for i in range(n-2):
        p = pts[i]
        for j in range(i+1, n-1):
            q = pts[j]
            dx1 = q[0] - p[0]
            dy1 = q[1] - p[1]
            for k in range(j+1, n):
                r = pts[k]
                area = abs(dx1*(r[1]-p[1]) - dy1*(r[0]-p[0])) / (2 * TRI_AREA)
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0
    return min_area

def _hexagonal_grid(n: int) -> np.ndarray:
    pts = []
    layers = 4
    for layer in range(layers):
        y = (layer + 0.5) * SQRT3 / (2 * layers)
        count = layer + 1
        offset = (1 - (count-1)/layers) / 2
        for i in range(count):
            x = offset + i * (1.0/layers)
            pts.append(np.array([x, y]))

    while len(pts) < n:
        x = random.uniform(0, 1)
        y = random.uniform(0, SQRT3/2)
        if _is_inside(np.array([x, y])):
            pts.append(np.array([x, y]))

    return np.array(pts[:n])

def _optimize(pts: np.ndarray, iterations: int) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)
    n = len(pts)

    for t in range(iterations):
        temp = max(0.01, 0.1 * (1 - t/iterations))
        step = max(0.001, 0.1 * (1 - t/iterations))

        idx = random.randrange(n)
        trial = pts.copy()
        trial[idx] += np.random.uniform(-step, step, 2)

        # Ensure point stays inside triangle
        if not _is_inside(trial[idx]):
            trial[idx] = np.clip(trial[idx], [0, 0], [1, SQRT3/2])
            if not _is_inside(trial[idx]):
                continue

        trial_area = _min_triangle_area(trial)

        if trial_area > best_area or (temp > 0 and random.random() < math.exp((trial_area - best_area)/temp)):
            pts = trial
            if trial_area > best_area:
                best_area = trial_area
                best_pts = trial.copy()

    return best_pts

def _local_refine(pts: np.ndarray, steps: int) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)
    n = len(pts)

    for _ in range(steps):
        improved = False
        for idx in range(n):
            for dx in [-0.001, 0, 0.001]:
                for dy in [-0.001, 0, 0.001]:
                    if dx == 0 and dy == 0:
                        continue
                    trial = best_pts.copy()
                    trial[idx] += np.array([dx, dy])
                    if not _is_inside(trial[idx]):
                        continue
                    trial_area = _min_triangle_area(trial)
                    if trial_area > best_area:
                        best_area = trial_area
                        best_pts = trial.copy()
                        improved = True
        if not improved:
            break
    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    pts = _hexagonal_grid(11)
    pts = _optimize(pts, 3000)
    pts = _optimize(pts, 2000)
    pts = _local_refine(pts, 100)

    return [(float(x), float(y)) for x, y in pts]

