import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / (2 * TRIANGLE_AREA)

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                area = _area(pts[i], pts[j], pts[k])
                if area < min_area:
                    min_area = area
                    if min_area < 0.001:
                        return min_area
    return min_area

def _random_point_in_triangle() -> np.ndarray:
    r1 = random.random()
    r2 = random.random()
    if r1 + r2 > 1:
        r1 = 1 - r1
        r2 = 1 - r2
    x = r1 * 1.0 + r2 * 0.5
    y = r2 * SQRT3 / 2.0
    return np.array([x, y])

def _initialize_points(n_pts: int) -> np.ndarray:
    # Hexagonal grid initialization
    pts = []
    layers = 3
    for i in range(-layers, layers+1):
        for j in range(-layers, layers+1):
            x = 0.5 + i*0.15 + j*0.075
            y = 0.433 + j*0.13
            if _is_in_triangle(np.array([x, y])):
                pts.append(np.array([x, y]))

    # Add center points
    pts.append(np.array([0.5, SQRT3/4]))
    pts.append(np.array([0.25, SQRT3/8]))
    pts.append(np.array([0.75, SQRT3/8]))

    # Fill remaining with optimized random points
    while len(pts) < n_pts:
        new_pt = _random_point_in_triangle()
        min_dist = min(np.linalg.norm(new_pt - p) for p in pts) if pts else float('inf')
        if min_dist > 0.15:
            pts.append(new_pt)

    return np.array(pts[:n_pts])

def _is_in_triangle(p: np.ndarray) -> bool:
    x, y = p
    if y < 0 or y > SQRT3/2:
        return False
    if x < 0 or x > 1:
        return False
    if y > SQRT3 * x or y > SQRT3 * (1 - x):
        return False
    return True

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    x, y = p
    if _is_in_triangle(p):
        return p

    edge1 = lambda x: SQRT3 * x
    edge2 = lambda x: SQRT3 * (1 - x)

    if y < 0:
        x = max(0.01, min(0.99, x))
        return np.array([x, 0.01])

    d1 = abs(y - edge1(x))
    d2 = abs(y - edge2(x))

    if d1 < d2:
        y_proj = edge1(x)
        return np.array([max(0.01, min(0.99, x)), max(0.01, min(y_proj, SQRT3/2 - 0.01))])
    else:
        y_proj = edge2(x)
        return np.array([max(0.01, min(0.99, x)), max(0.01, min(y_proj, SQRT3/2 - 0.01))])

def _anneal(n_pts: int = 11,
            max_iters: int = 150000,
            start_temp: float = 0.4,
            end_temp: float = 1e-12,
            seed: int | None = None) -> np.ndarray:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _initialize_points(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    no_improve = 0
    step_size = 0.1

    for t in range(max_iters):
        T = start_temp * (1 - t/max_iters)**4

        idx = random.randrange(n_pts)
        trial = pts.copy()

        if t % 1000 == 0 or best_val < 0.01 or no_improve > 1000:
            trial[idx] = _random_point_in_triangle()
            step_size = 0.1
        else:
            delta = np.random.normal(0, step_size, size=2)
            trial[idx] += delta
            trial[idx] = _project_to_triangle(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta_val = trial_val - best_val

        if delta_val > 0 or (T > 1e-12 and math.exp(delta_val / T) > random.random()):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()
                no_improve = 0
                step_size *= 1.1
            else:
                no_improve += 1
                step_size *= 0.99
        else:
            no_improve += 1
            step_size *= 0.99

        if no_improve > 2000 and t > 50000:
            break

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

