def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / 2

def _min_triangle_area(pts):
    tree = KDTree(pts)
    min_area = float('inf')
    n = len(pts)

    for i in range(n):
        neighbors = tree.query(pts[i], k=min(7, n))[1][1:]  # Dynamic k based on n
        for j, k in combinations(neighbors, 2):
            a = _area(pts[i], pts[j], pts[k])
            if a < min_area:
                min_area = a
                if min_area < 1e-8:
                    return min_area
    return min_area

def _is_in_triangle(p):
    x, y = p
    if x < 0 or x > 1 or y < 0 or y > SQRT3/2:
        return False
    if y > SQRT3 * x or y > SQRT3 * (1 - x):
        return False
    return True

def _generate_initial_points(n):
    # Optimized hexagonal pattern for 11 points
    pts = []
    layers = 3
    offsets = [0.15, 0.35, 0.55]

    for i in range(layers):
        for j in range(layers - i):
            x = offsets[i]
            y = (j + 0.5*(i % 2)) * 0.3 * SQRT3
            if _is_in_triangle([x, y]):
                pts.append([x, y])

    # Add symmetric points
    sym_pts = []
    for p in pts:
        x, y = p
        sym_x = 1 - x
        if _is_in_triangle([sym_x, y]):
            sym_pts.append([sym_x, y])
    pts += sym_pts

    # Add center points
    center = [0.5, SQRT3/4]
    if _is_in_triangle(center):
        pts.append(center)

    # Repulsive sampling with better bounds
    while len(pts) < n:
        best_p = None
        best_dist = 0
        for _ in range(20):
            x = random.uniform(0.05, 0.95)
            y = random.uniform(0.01, 0.9*SQRT3/2)
            p = np.array([x, y])
            if _is_in_triangle(p):
                if len(pts) > 0:
                    dists = np.linalg.norm(pts - p, axis=1)
                    min_dist = np.min(dists)
                else:
                    min_dist = float('inf')
                if min_dist > best_dist:
                    best_dist = min_dist
                    best_p = p
