    cooling_rate = 0.985

    for iter in range(iterations):
        temp *= cooling_rate
        trial_pts = current_pts.copy()

        # Adaptive perturbation based on iteration
        for i in range(len(trial_pts)):
            if random.random() < 0.8:
                scale = temp * (0.1 + 0.9*(iter/iterations))
                perturbation = np.random.normal(0, scale/8, 2)
