def _hex_grid_points(n):
    points = []
    k = math.ceil(math.sqrt(n / (SQRT3/2)))
    for i in range(k):
        for j in range(k):
            x = (i + 0.5 * (j % 2)) / k
            y = (j * SQRT3 / 2) / k
            if x + y/SQRT3 <= 1.0 and y <= SQRT3/2:
                points.append((x, y))
    return points[:n]

def _project_to_triangle(p):
    x, y = p
    if y < 0: y = 0
    if y > SQRT3/2: y = SQRT3/2
    if x < 0: x = 0
    if x > 1: x = 1
    if y > SQRT3 * (1 - x): 
        y = SQRT3 * (1 - x)
    return (x, y)

def _optimize_points(points, iterations=10000):
    best_points = np.array(points)
    best_score = _min_triangle_area(best_points)

    for _ in range(iterations):
        temp_points = best_points.copy()

        for i in range(len(temp_points)):
            grad = np.zeros(2)
            for j,k in itertools.combinations([x for x in range(11) if x != i], 2):
                p1, p2, p3 = temp_points[i], temp_points[j], temp_points[k]
