                    dx = (p2[1] - p3[1]) / (2 * area + 1e-8)
                    dy = (p3[0] - p2[0]) / (2 * area + 1e-8)
                    grad += np.array([dx, dy])

            step_size = 0.01 * (1 - _/iterations)
            temp_points[i] += grad * step_size
            temp_points[i] = _project_to_triangle(temp_points[i])

        current_score = _min_triangle_area(temp_points)
        if current_score > best_score:
