import math
import random
import numpy as np
from itertools import combinations

SQRT3 = math.sqrt(3.0)
TRI_AREA = SQRT3 / 4.0

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / 2.0

def _min_triangle_area(pts):
    min_area = float('inf')
    for trio in combinations(pts, 3):
        area = _area(*trio)
        if area < min_area:
            min_area = area
            if min_area == 0:
                return 0
    return min_area / TRI_AREA

def _is_in_triangle(pt):
    x, y = pt
    return y >= 0 and y <= SQRT3 * min(x, 1-x)

def _random_point():
    while True:
        x, y = random.random(), random.random()
        if _is_in_triangle((x, y)):
            return np.array([x, y])

def _hexagonal_grid_with_offset(n):
    k = math.ceil(math.sqrt(n / (2/SQRT3)))
    pts = []
    offset = random.random() * 0.1
    for i in range(k):
        for j in range(k):
            x = (i + 0.5*(j%2) + offset) / (k-0.5)
            y = (j * SQRT3/2 + offset) / (k-0.5)
            if _is_in_triangle((x, y)):
                pts.append([x, y])
                if len(pts) == n:
                    return pts
    while len(pts) < n:
        pts.append(_random_point())
    return pts[:n]

def _simulated_annealing(pts, iterations=10000):
    current = np.array(pts)
    current_energy = -_min_triangle_area(current)
    best = current.copy()
    best_energy = current_energy

    temp = 1.0
    cooling_rate = 0.9997

    for _ in range(iterations):
        temp *= cooling_rate
        idx = random.randrange(len(current))
        step_size = 0.02 * temp
        new_pt = current[idx] + np.random.normal(0, step_size, 2)

        if not _is_in_triangle(new_pt):
            continue

        trial = current.copy()
        trial[idx] = new_pt
        trial_energy = -_min_triangle_area(trial)

        if trial_energy < best_energy:
            best = trial.copy()
            best_energy = trial_energy

        if trial_energy < current_energy or math.exp((current_energy - trial_energy)/temp) > random.random():
            current = trial.copy()
            current_energy = trial_energy

    return best

def _local_search(pts, iterations=2000):
    best_pts = np.array(pts)
    best_score = _min_triangle_area(best_pts)

    for i in range(iterations):
        step_size = 0.02 * (1 - i/iterations)
        idx = random.randrange(len(pts))
        new_pt = best_pts[idx] + np.random.normal(0, step_size, 2)

        if not _is_in_triangle(new_pt):
            continue

        trial = best_pts.copy()
        trial[idx] = new_pt
        trial_score = _min_triangle_area(trial)

        if trial_score > best_score:
            best_pts = trial.copy()
            best_score = trial_score

    return best_pts

def find_points(seed=None):
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _hexagonal_grid_with_offset(11)
    pts = _simulated_annealing(pts, 8000)
    pts = _local_search(pts, 3000)

    return [(float(x), float(y)) for x, y in pts]

