import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(points: np.ndarray, i: int, j: int, k: int) -> float:
    p, q, r = points[i], points[j], points[k]
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / (2 * TRIANGLE_AREA)

def _min_triangle_area(points: np.ndarray) -> float:
    n = len(points)
    min_area = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            if min_area == 0:
                return 0
            for k in range(j+1, n):
                area = _area(points, i, j, k)
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0
    return min_area

def _initial_configuration(n: int = 11) -> np.ndarray:
    points = []
    grid_size = int(math.ceil(math.sqrt(n * 3.0)))

    for j in range(grid_size):
        y = (j * SQRT3 / 2) / grid_size
        row_points = grid_size if j % 2 == 0 else grid_size - 1
        for i in range(row_points):
            x = (i + 0.5 * (j % 2)) / grid_size
            if y <= SQRT3 / 2 - x * SQRT3 and y <= x * SQRT3:
                points.append([x, y])
            if len(points) >= n:
                break
        if len(points) >= n:
            break

    while len(points) < n:
        x = random.uniform(0.2, 0.8)
        y = random.uniform(0.1, 0.6)
        if y <= SQRT3 / 2 - x * SQRT3 and y <= x * SQRT3:
            points.append([x, y])

    return np.array(points)

def _optimize_points(points: np.ndarray, iterations: int = 10000) -> np.ndarray:
    best_points = points.copy()
    best_area = _min_triangle_area(points)
    current_points = points.copy()
    current_area = best_area

    temp = 1.0
    cooling_rate = 0.9995
    no_improve = 0

    for step in range(iterations):
        temp *= cooling_rate

        idx = random.randint(0, len(points)-1)
        old_point = current_points[idx].copy()

        step_size = 0.1 * temp + 0.01
        if random.random() < 0.1 and temp > 0.2:
            step_size *= 4

        while True:
            angle = random.uniform(0, 2*math.pi)
            dx = math.cos(angle) * step_size
            dy = math.sin(angle) * step_size
            new_x = old_point[0] + dx
            new_y = old_point[1] + dy

            if (new_y >= 0 and new_y <= SQRT3 / 2 and 
                new_y <= SQRT3 * new_x and 
                new_y <= SQRT3 * (1 - new_x)):
                break

        current_points[idx] = [new_x, new_y]
        new_area = _min_triangle_area(current_points)

        accept = False
        if new_area > current_area:
            accept = True
        elif temp > 0.001 and random.random() < math.exp(10*(new_area - current_area)/temp):
            accept = True

        if accept:
            current_area = new_area
            if new_area > best_area:
                best_area = new_area
                best_points = current_points.copy()
                no_improve = 0
            else:
                no_improve += 1
        else:
            current_points[idx] = old_point
            no_improve += 1

        if no_improve > 300 and temp < 0.05:
            break

    return best_points

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    initial_points = _initial_configuration(11)
    optimized_points = _optimize_points(initial_points, 10000)
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in optimized_points]

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
AREA_TRIANGLE = SQRT3 / 4.0

def _area_fast(pts: np.ndarray, indices: Tuple[int, int, int]) -> float:
    p, q, r = pts[indices[0]], pts[indices[1]], pts[indices[2]]
    return abs((q[0] - p[0])*(r[1] - p[1]) - (q[1] - p[1])*(r[0] - p[0])) * 0.5

def _min_triangle_area_fast(pts: np.ndarray) -> float:
    n = len(pts)
    if n < 3: return 0.0
    best = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area_fast(pts, (i,j,k))
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

def _barycentric_to_cartesian(u: float, v: float) -> Tuple[float, float]:
    x = u + 0.5 * v
    y = SQRT3/2 * v
    return (x, y)

def _cartesian_to_barycentric(x: float, y: float) -> Tuple[float, float]:
    v = 2 * y / SQRT3
    u = x - 0.5 * v
    return (u, v)

def _is_in_triangle(u: float, v: float) -> bool:
    return u >= 0 and v >= 0 and (1 - u - v) >= 0

def _initial_configuration() -> np.ndarray:
    points = []
    # Hexagonal pattern with barycentric coordinates
    for u in np.linspace(0.1, 0.9, 3):
        for v in np.linspace(0.1, 0.9 - u, 3):
            if _is_in_triangle(u, v):
                x, y = _barycentric_to_cartesian(u, v)
                points.append((x, y))
    # Add points near the center
    for _ in range(11 - len(points)):
        u = random.uniform(0.3, 0.7)
        v = random.uniform(0.1, 0.7 - u*0.5)
        x, y = _barycentric_to_cartesian(u, v)
        points.append((x, y))
    return np.array(points[:11])

def _optimize_sa_fast(pts: np.ndarray, iterations: int, temp: float) -> np.ndarray:
    current = pts.copy()
    current_val = _min_triangle_area_fast(current)
    best = current.copy()
    best_val = current_val

    for step in range(iterations):
        temp = temp * 0.999

        candidate = current.copy()
        idx = random.randrange(len(pts))

        x, y = candidate[idx]
        u, v = _cartesian_to_barycentric(x, y)

        # Adaptive step size based on temperature
        step_size = 0.1 * temp
        while True:
            du = random.uniform(-step_size, step_size)
            dv = random.uniform(-step_size, step_size)
            new_u = u + du
            new_v = v + dv
            if _is_in_triangle(new_u, new_v):
                break

        new_x, new_y = _barycentric_to_cartesian(new_u, new_v)
        candidate[idx] = (new_x, new_y)

        candidate_val = _min_triangle_area_fast(candidate)

        if candidate_val > current_val or random.random() < math.exp(10*(candidate_val - current_val)/temp):
            current = candidate
            current_val = candidate_val
            if current_val > best_val:
                best = current.copy()
                best_val = current_val

    return best

def _validate_points(pts: List[Tuple[float, float]]) -> bool:
    for x, y in pts:
        u, v = _cartesian_to_barycentric(x, y)
        if not _is_in_triangle(u, v):
            return False
    return True

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    best_pts = None
    best_val = 0.0

    for _ in range(5):
        pts = _initial_configuration()
        pts = _optimize_sa_fast(pts, 8000, 0.2)
        pts = _optimize_sa_fast(pts, 4000, 0.02)
        val = _min_triangle_area_fast(pts)
        if val > best_val and _validate_points(pts):
            best_pts = pts
            best_val = val

    if best_pts is None:
        best_pts = _initial_configuration()

    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in best_pts]

