            j = layer - i
            x = x_offset + base_scale * (0.5 + (i - j) * 0.5)
            y = y_offset + base_scale * (i + j) * SQRT3 / 6
            if y <= SQRT3 / 2 - x * SQRT3 and y <= x * SQRT3:
                points.append([x, y])
                if len(points) >= n:
