        for i in range(len(points)):
            local_min = float('inf')
            for j in range(max(0,i-4), min(len(points),i+5)):
                if j == i:
                    continue
                for k in range(max(0,j-4), min(len(points),j+5)):
                    if k == i or k == j:
                        continue
                    area = _area(current_points, i, j, k)
                    if area < local_min:
                        local_min = area
                        if local_min < 0.001:
                            break
                if local_min < 0.001:
                    break
            if local_min < min_local_area:
                min_local_area = local_min
                worst_idx = i

        old_point = current_points[worst_idx].copy()

        # Generate new candidate with directional bias
        for _ in range(3):
            angle = random.uniform(0, 2*math.pi)
            dist = random.uniform(0, step_size)
            dx = dist * math.cos(angle)
            dy = dist * math.sin(angle)

            new_x = old_point[0] + dx
            new_y = old_point[1] + dy

            # Check bounds and triangle constraints
            if (0 <= new_x <= 1 and 0 <= new_y <= SQRT3/2 and
                new_y <= SQRT3 * new_x and new_y <= SQRT3 * (1 - new_x)):
                current_points[worst_idx] = [new_x, new_y]
                new_area = _min_triangle_area(current_points)

                if new_area > best_area or (temp > 0.01 and random.random() < math.exp(10*(new_area - best_area)/temp)):
                    if new_area > best_area:
                        best_area = new_area
                        best_points = current_points.copy()
                    break
                else:
                    current_points[worst_idx] = old_point

    return best_points

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    initial_points = _hexagonal_configuration(11)
    optimized_points = _optimize_points(initial_points, 4000)
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in optimized_points]

from __future__ import annotations
import math
import random
import itertools
from typing import List, Tuple
import numpy as np

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _is_inside_triangle(pt: np.ndarray) -> bool:
    x, y = pt
    if y < 0 or x < 0 or y > SQRT3/2:
        return False
    if x + y/SQRT3 > 1 + 1e-8:
        return False
    if x - y/SQRT3 > 1e-8:
        return False
    return True

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5 / TRIANGLE_AREA

class MinAreaTracker:
    def __init__(self, pts: np.ndarray):
        self.pts = pts.copy()
        self.n = len(pts)
        self.min_area = float('inf')
        self.update_all_areas()

    def update_all_areas(self):
        self.min_area = float('inf')
        for i, j, k in itertools.combinations(range(self.n), 3):
            area = _area(self.pts[i], self.pts[j], self.pts[k])
            if area < self.min_area:
                self.min_area = area

    def update_point(self, idx: int, new_pos: np.ndarray) -> bool:
        if not _is_inside_triangle(new_pos):
            return False
        old_pos = self.pts[idx].copy()
        self.pts[idx] = new_pos
        self.update_all_areas()
        return True

    def get_min_area(self) -> float:
        return self.min_area

def _random_point_inside_triangle(rng: np.random.Generator) -> np.ndarray:
    while True:
        x = rng.uniform(0, 1)
        y = rng.uniform(0, SQRT3/2)
        if _is_inside_triangle(np.array([x, y])):
            return np.array([x, y])

def _hexagonal_grid_points(n: int) -> List[np.ndarray]:
    k = math.ceil(math.sqrt(n / (SQRT3/4)))
    points = []
    for i in range(k):
        for j in range(k):
            x = (i + 0.5 * (j % 2)) / (k - 1)
            y = (j * SQRT3 / 2) / (k - 1)
            if _is_inside_triangle(np.array([x, y])):
                points.append(np.array([x, y]))
                if len(points) >= n:
                    return points
    return points

def _initial_configuration(n_pts: int = 11, rng: np.random.Generator = None) -> np.ndarray:
    if rng is None:
        rng = np.random.default_rng()

    pts = _hexagonal_grid_points(n_pts)
    while len(pts) < n_pts:
        pts.append(_random_point_inside_triangle(rng))
    return np.array(pts[:n_pts])

def _optimize(n_pts: int = 11, iters: int = 10000, seed: int | None = None) -> np.ndarray:
    rng = np.random.default_rng(seed)
    pts = _initial_configuration(n_pts, rng)
    tracker = MinAreaTracker(pts)
    best_pts = pts.copy()
    best_val = tracker.get_min_area()

    for t in range(iters):
        T = max(0.1 * (1 - t/iters), 1e-4)
        step_size = 0.05 * (1 - t/iters) + 0.001

        idx = rng.integers(0, n_pts)
        old_pos = pts[idx].copy()

        angle = rng.uniform(0, 2*math.pi)
        dx = step_size * math.cos(angle)
        dy = step_size * math.sin(angle)
        new_pos = np.array([old_pos[0] + dx, old_pos[1] + dy])

        if not tracker.update_point(idx, new_pos):
            continue

        current_val = tracker.get_min_area()
        delta = current_val - best_val

        if delta > 0 or (T > 0 and rng.random() < math.exp(delta / T)):
            pts = tracker.pts.copy()
            if current_val > best_val:
                best_val = current_val
                best_pts = pts.copy()
        else:
            tracker.update_point(idx, old_pos)

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    pts = _optimize(n_pts=11, iters=10000, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

from __future__ import annotations

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    best = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0001, min(0.9999, u))
    v = max(0.0001, min(0.9999, v))
    if u + v > 0.9999:
        total = u + v
        u = 0.9999 * u / total
        v = 0.9999 * v / total
    return (1 - u - v) * _A + u * _B + v * _C

def _initial_configuration(n_pts: int = 11) -> np.ndarray:
    pts = []
    layers = 4
    for layer in range(layers):
        for i in range(layer + 1):
            u = (i + 0.5 * (layer % 2)) / (layers - 0.5)
            v = (layer - i + 0.5 * (layer % 2)) / (2 * layers)
            pts.append((1 - u - v) * _A + u * _B + v * _C)
    while len(pts) < n_pts:
        pts.append(_random_point())
    return np.array(pts[:n_pts])

def _differential_evolution(n_pts: int = 11,
                          max_iter: int = 500,
                          F: float = 0.8,
                          CR: float = 0.9,
                          seed: int | None = 0) -> np.ndarray:
    random.seed(seed)
    population = [_initial_configuration(n_pts) for _ in range(10)]
    best_pts = max(population, key=lambda x: _min_triangle_area(x))
    best_val = _min_triangle_area(best_pts)
    no_improve = 0

    for _ in range(max_iter):
        for i in range(len(population)):
            a, b, c = random.sample(range(len(population)), 3)
            mutant = population[a].copy()
            for j in range(n_pts):
                if random.random() < CR:
                    mutant[j] = _project_to_simplex(population[a][j] + 
                               F * (population[b][j] - population[c][j]))
            trial_val = _min_triangle_area(mutant)
            if trial_val > _min_triangle_area(population[i]):
                population[i] = mutant
                if trial_val > best_val:
                    best_val = trial_val
                    best_pts = mutant.copy()
                    no_improve = 0
                else:
                    no_improve += 1
        if no_improve > 30:
            break
    return best_pts

def _local_search(pts: np.ndarray, steps: int = 200) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    n_pts = len(pts)
    for step_num in range(steps):
        trial = best_pts.copy()
        idx = random.randrange(n_pts)
        step = 0.02 * (1 - step_num/steps)**2
        trial[idx] = _project_to_simplex(trial[idx] + 
                       np.random.uniform(-step, step, 2))
        trial_val = _min_triangle_area(trial)
        if trial_val > best_val:
            best_val = trial_val
            best_pts = trial.copy()
    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _differential_evolution(n_pts=11, max_iter=500, seed=seed)
    pts = _local_search(pts, steps=200)
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

import math
import random
import numpy as np
from itertools import combinations

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / 2.0

def _min_triangle_area(pts):
    min_area = float('inf')
    for trio in combinations(pts, 3):
        a = _area(*trio)
        if a < min_area:
            min_area = a
            if min_area < 1e-8:
                return min_area
    return min_area

def _is_in_triangle(p, margin=0.01):
    x, y = p
    if x < margin or x > 1-margin or y < margin or y > (SQRT3/2)-margin:
        return False
    if y > SQRT3 * x + margin:
        return False
    if y > SQRT3 * (1 - x) + margin:
        return False
    return True

def _generate_initial_points(n):
    points = []
    points.extend([[0.0, 0.0], [1.0, 0.0], [0.5, SQRT3/2]])

    edge_pts = 2
    for i in range(1, edge_pts+1):
        t = i / (edge_pts+1)
        points.append([t, 0])
        points.append([0.5 + t/2 - 0.05, t * SQRT3/2 * 0.95])
        points.append([0.5 - t/2 + 0.05, t * SQRT3/2 * 0.95])

    interior_pts = n - len(points)
    size = int(np.ceil(np.sqrt(interior_pts * 2)))
    for i in range(size):
        for j in range(size):
            if len(points) >= n:
                break
            x = 0.2 + 0.6 * i/(size-1)
            y = (SQRT3/2 * 0.6) * j/(size-1)
            if j % 2 == 1:
                x += 0.3/(size-1)
            if _is_in_triangle((x, y)):
                points.append([x, y])

    while len(points) < n:
        x = random.uniform(0.15, 0.85)
        y = random.uniform(0.15, 0.7 * SQRT3/2)
        if _is_in_triangle((x, y)):
            points.append([x, y])
    return np.array(points)

def _optimize_points(points, iterations):
    best_points = points.copy()
    best_score = _min_triangle_area(best_points)

    for i in range(iterations):
        new_points = best_points.copy()
        step = 0.01 * (1 - i/iterations)**0.5

        if i % 3 == 0:
            min_area = float('inf')
            worst_idx = 0
            for idx in range(len(points)):
                for trio in combinations([i for i in range(len(points)) if i != idx], 2):
                    a = _area(points[idx], points[trio[0]], points[trio[1]])
                    if a < min_area:
                        min_area = a
                        worst_idx = idx

            for _ in range(10):
                trial_point = best_points[worst_idx].copy() + np.random.uniform(-step*1.5, step*1.5, 2)
                if _is_in_triangle(trial_point):
                    new_points[worst_idx] = trial_point
                    break
        else:
            idx = i % len(points)
            for _ in range(5):
                trial_point = best_points[idx].copy() + np.random.uniform(-step, step, 2)
                if _is_in_triangle(trial_point):
                    new_points[idx] = trial_point
                    break

        new_score = _min_triangle_area(new_points)
        if new_score > best_score:
            best_score = new_score
            best_points = new_points.copy()

    return best_points

def find_points(seed=None):
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    points = _generate_initial_points(11)
    points = _optimize_points(points, 3000)

    return [(float(p[0]), float(p[1])) for p in points]

