import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    if u >= 0 and v >= 0 and (1 - u - v) >= 0:
        return p
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _triangle_area(a: np.ndarray, b: np.ndarray, c: np.ndarray) -> float:
    return abs((b[0]-a[0])*(c[1]-a[1]) - (b[1]-a[1])*(c[0]-a[0])) / 2.0

def _min_triangle_area(points: np.ndarray) -> float:
    min_area = float('inf')
    n = len(points)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                area = _triangle_area(points[i], points[j], points[k])
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0
    return min_area

def _optimize(n_pts: int = 11, iterations: int = 1000, seed: int | None = None) -> np.ndarray:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    points = np.array([_random_point() for _ in range(n_pts)])
    best_points = points.copy()
    best_min_area = _min_triangle_area(points)

    for _ in range(iterations):
        temp = max(0.01, 1.0 - (_ / iterations))
        idx = random.randint(0, n_pts-1)
        perturbation = np.random.normal(0, 0.05 * temp, 2)
        new_point = _project_to_simplex(points[idx] + perturbation)

        old_point = points[idx]
        points[idx] = new_point

        current_min_area = _min_triangle_area(points)
        if current_min_area > best_min_area or (
            current_min_area == best_min_area and random.random() < temp
        ):
            best_min_area = current_min_area
            best_points = points.copy()
        else:
            points[idx] = old_point

    return best_points

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    points = _optimize(n_pts=11, iterations=5000, seed=seed)
    return [(float(p[0]), float(p[1])) for p in points]

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TOLERANCE = 1e-8

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    best = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

def _is_inside(x: float, y: float) -> bool:
    if x < 0 or x > 1 or y < 0:
        return False
    y_bound = SQRT3 * (1 - abs(2*x - 1))
    return y <= y_bound + TOLERANCE

def _hexagonal_grid(n: int) -> np.ndarray:
    pts = []
    size = int(math.ceil(math.sqrt(n * 1.1)))  # Slightly larger grid
    margin = 0.02  # Keep points away from boundary

    for i in range(size):
        for j in range(size):
            if len(pts) >= n:
                break
            x = 0.5 + (i - j) * (0.5 - margin) / size
            y = margin + j * (SQRT3/2 - 2*margin) / size
            if _is_inside(x, y):
                pts.append([x, y])

    while len(pts) < n:
        x = random.uniform(margin, 1 - margin)
        y_max = SQRT3 * (1 - abs(2*x - 1)) - margin
        y = random.uniform(margin, y_max)
        pts.append([x, y])

    return np.array(pts)

def _optimize_points(pts: np.ndarray, iterations: int = 2000) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)
    n = len(pts)

    for iter in range(iterations):
        new_pts = best_pts.copy()
        idx = random.randint(0, n-1)
        step = 0.05 * (1 - iter/iterations)
        new_pts[idx] += np.random.uniform(-step, step, 2)

        x, y = new_pts[idx]
        if not _is_inside(x, y):
            continue

        new_area = _min_triangle_area(new_pts)
        if new_area > best_area:
            best_area = new_area
            best_pts = new_pts.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _hexagonal_grid(11)
    pts = _optimize_points(pts, 2000)

    # Final strict boundary check and correction
    for i in range(len(pts)):
        x, y = pts[i]
        if not _is_inside(x, y):
            x_new = random.uniform(0.02, 0.98)
            y_max = SQRT3 * (1 - abs(2*x_new - 1)) - 0.02
            y_new = random.uniform(0.02, y_max)
            pts[i] = [x_new, y_new]

    return [(float(x), float(y)) for x, y in pts]

