import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _area_vectorized(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            p = pts[j] - pts[i]
            for k in range(j+1, n):
                q = pts[k] - pts[i]
                area = abs(p[0]*q[1] - p[1]*q[0]) * 0.5
                if area < min_area:
                    min_area = area
                    if min_area < 1e-6:
                        return 0.0
    return min_area

def _hexagonal_lattice(n: int) -> np.ndarray:
    pts = []
    size = int(math.ceil(math.sqrt(n)))
    for i in range(size):
        for j in range(size):
            if len(pts) >= n:
                break
            x = (i + 0.5 * (j % 2)) / size
            y = (j * SQRT3 / 2) / size
            if x <= 1.0 and y <= SQRT3/2 and (1 - x) * SQRT3 >= y:
                pts.append(np.array([x, y]))
    return np.array(pts[:n])

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _local_optimize(pts: np.ndarray, steps: int = 50, step_size: float = 0.01) -> np.ndarray:
    n = len(pts)
    best_pts = pts.copy()
    best_val = _area_vectorized(best_pts)

    for _ in range(steps):
        improved = False
        for i in range(n):
            for dx, dy in [(step_size, 0), (-step_size, 0), (0, step_size), (0, -step_size),
                          (step_size, step_size), (-step_size, -step_size),
                          (step_size, -step_size), (-step_size, step_size)]:
                trial = best_pts.copy()
                trial[i] += np.array([dx, dy])
                trial[i] = _project_to_simplex(trial[i])
                trial_val = _area_vectorized(trial)
                if trial_val > best_val:
                    best_val = trial_val
                    best_pts = trial.copy()
                    improved = True
        if not improved:
            step_size *= 0.5
            if step_size < 1e-4:
                break
    return best_pts

def _anneal(n_pts: int = 11,
            iters: int = 50_000,
            start_temp: float = 0.2,
            end_temp: float = 1e-7,
            step_size: float = 0.05,
            seed: int | None = None) -> np.ndarray:
    if seed is not None:
        np.random.seed(seed)

    pts = _hexagonal_lattice(n_pts)
    best_pts = pts.copy()
    best_val = _area_vectorized(best_pts)

    for t in range(iters):
        T = start_temp * (end_temp / start_temp) ** (t / max(1, iters-1))

        idx = np.random.choice(n_pts, size=min(3, n_pts), replace=False)
        trial = pts.copy()
        for i in idx:
            perturbation = np.random.normal(0, step_size, size=2)
            trial[i] += perturbation
            trial[i] = _project_to_simplex(trial[i])

        trial_val = _area_vectorized(trial)
        delta = trial_val - best_val

        if delta > 0 or np.random.random() < math.exp(delta / max(T, 1e-12)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()
                step_size = max(0.01, step_size * 1.01)
            else:
                step_size = max(0.001, step_size * 0.99)

    return _local_optimize(best_pts, step_size=0.01)

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=50_000, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

import math
import random
import numpy as np
from scipy.spatial import KDTree
from itertools import combinations

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / 2.0

def _min_triangle_area(pts):
    min_area = float('inf')
    kdtree = KDTree(pts)

    for i, p in enumerate(pts):
        # Query for k+2 points to ensure we get enough neighbors after excluding self
        dists, indices = kdtree.query(p, k=16)
        neighbors = [pts[j] for j in indices if j != i]

        for q, r in combinations(neighbors[:15], 2):
            a = _area(p, q, r)
            if a < min_area:
                min_area = a
                if min_area == 0:
                    return 0
    return min_area

def _generate_hexagonal_points(n):
    pts = []
    layers = math.ceil(math.sqrt(n * 4 / (3 * SQRT3))) + 2

    for i in range(layers):
        y = (i + 0.5) * (SQRT3/2) / layers
        row_width = layers - abs(i - (layers-1)/2)
        for j in range(row_width):
            x = (j + 0.5 + (layers - row_width)/2) / layers
            if y <= x * SQRT3 and y <= (1 - x) * SQRT3:
                pts.append([x, y])

    while len(pts) < n:
        x = random.uniform(0, 1)
        y = random.uniform(0, SQRT3/2)
        if y <= x * SQRT3 and y <= (1 - x) * SQRT3:
            pts.append([x, y])

    return pts[:n]

def _project_to_triangle(p):
    x, y = p
    if y < 0: y = 0
    if y > SQRT3/2: y = SQRT3/2
    x = max(0, min(1, x))
    if y > x * SQRT3:
        y = x * SQRT3
    if y > (1 - x) * SQRT3:
        y = (1 - x) * SQRT3
    return [x, y]

def _optimize_points(pts, iterations=500):
    best_pts = np.array(pts)
    best_area = _min_triangle_area(best_pts)

    for step in range(iterations):
        temp = 1.0 - step/iterations
        step_size = 0.05 * temp

        for i in range(len(best_pts)):
            for _ in range(3):
                trial = best_pts.copy()
                perturbation = np.random.normal(0, step_size, 2)
                trial[i] = _project_to_triangle(trial[i] + perturbation)

                trial_area = _min_triangle_area(trial)
                if trial_area > best_area:
                    best_area = trial_area
                    best_pts = trial
                    break

    return best_pts

def find_points(seed=None):
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _generate_hexagonal_points(11)
    pts = _optimize_points(pts, 1000)

    return [(float(x), float(y)) for x, y in pts]

