import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    best = float("inf")
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = 1 - v, 1 - u
    return (1 - u - v) * _A + u * _B + v * _C

def _symmetric_configuration(n: int) -> np.ndarray:
    pts = []
    layers = int(math.sqrt(2*n)) + 1
    for i in range(layers):
        for j in range(i+1):
            if len(pts) >= n:
                break
            x = 0.5 + (j - i/2) * (1.0/(layers-1))
            y = i * (SQRT3/2) * (1.0/(layers-1))
            if 0 <= x <= 1 and 0 <= y <= SQRT3/2:
                pts.append(np.array([x, y]))
    return np.array(pts[:n])

def _differential_evolution(n_pts: int = 11, max_iter: int = 500, pop_size: int = 20, seed: int | None = 0) -> np.ndarray:
    random.seed(seed)
    np.random.seed(seed)

    def init_population():
        pop = []
        for _ in range(pop_size):
            if random.random() < 0.7:
                ind = _symmetric_configuration(n_pts)
            else:
                ind = np.random.rand(n_pts, 2)
                for p in ind:
                    p[1] *= SQRT3/2
                    if p[0] + p[1]/SQRT3 > 1.0:
                        p[0] = 1.0 - p[1]/SQRT3
            pop.append(ind)
        return pop

    population = init_population()
    fitness = [_min_triangle_area(ind) for ind in population]
    best_idx = np.argmax(fitness)
    best_individual = population[best_idx].copy()
    best_fitness = fitness[best_idx]

    F = 0.8
    Cr = 0.9

    for _ in range(max_iter):
        for i in range(pop_size):
            idxs = [idx for idx in range(pop_size) if idx != i]
            a, b, c = population[np.random.choice(idxs, 3, replace=False)]
            mutant = a + F * (b - c)

            trial = population[i].copy()
            for j in range(n_pts):
                if random.random() < Cr:
                    trial[j] = mutant[j]
                    trial[j] = _project_to_simplex(trial[j])

            trial_fitness = _min_triangle_area(trial)
            if trial_fitness > fitness[i]:
                population[i] = trial
                fitness[i] = trial_fitness
                if trial_fitness > best_fitness:
                    best_fitness = trial_fitness
                    best_individual = trial.copy()

    return best_individual

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _differential_evolution(n_pts=11, max_iter=500, pop_size=20, seed=seed)
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

