import math
import random
import numpy as np
from scipy.spatial import KDTree
from scipy.optimize import differential_evolution

SQRT3 = math.sqrt(3.0)

def _random_point() -> np.ndarray:
    u, v = random.random(), random.random()
    if u + v > 1.0:
        u, v = 1 - u, 1 - v
    return np.array([(1 - u - v) * 0 + u * 1 + v * 0.5,
                     (1 - u - v) * 0 + u * 0 + v * (SQRT3/2)])

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    u = p[0] - 0.5 * p[1] / (SQRT3/2)
    v = p[1] / (SQRT3/2)
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = 1 - u, 1 - v
    return np.array([u + 0.5*v, v*SQRT3/2])

def _min_triangle_area(pts: np.ndarray) -> float:
    min_area = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = pts[j] - pts[i]
                b = pts[k] - pts[i]
                cross = abs(a[0]*b[1] - a[1]*b[0])
                area = cross * 0.5
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0.0
    return min_area

def _hexagonal_lattice(n: int) -> np.ndarray:
    pts = []
    size = int(math.ceil(math.sqrt(n / (0.5 * SQRT3))))
    for i in range(size):
        for j in range(size):
            x = (i + 0.5 * (j % 2)) / size
            y = (j * SQRT3 / 2) / size
            if x <= 1 and y <= SQRT3/2 and (1-x)*SQRT3 >= y:
                pts.append([x, y])
                if len(pts) == n:
                    return np.array(pts)
    return np.array(pts[:n])

def _optimize_points(initial_pts: np.ndarray) -> np.ndarray:
    bounds = [(0, 1), (0, SQRT3/2)] * 11

    def objective(x):
        pts = x.reshape(-1, 2)
        for pt in pts:
            if not (pt[0] <= 1 and pt[1] <= SQRT3/2 and (1-pt[0])*SQRT3 >= pt[1]):
                return 0.0
        return -_min_triangle_area(pts)

    res = differential_evolution(
        objective,
        bounds,
        strategy='best1bin',
        maxiter=100,
        popsize=15,
        mutation=(0.5, 1),
        recombination=0.7,
        init='latinhypercube',
        polish=False,
        updating='immediate',
        disp=False,
        seed=0,
        workers=1
    )
    return res.x.reshape(-1, 2)

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    initial_pts = _hexagonal_lattice(11)
    optimized_pts = _optimize_points(initial_pts)
    return [(float(x), float(y)) for x, y in optimized_pts]

