    while len(pts) < n:
        pts = []
        for i in range(-layers, layers+1):
            for j in range(max(-layers, -i-layers), min(layers, -i+layers)+1):
                x = 0.5 + 0.5 * i + 0.5 * j
                y = INV_SQRT3 * 0.5 * j
                pts.append((x, y))
        pts = [p for p in pts if (0 <= p[0] <= 1 and 0 <= p[1] <= SQRT3/2 and 
               p[1] <= SQRT3 * (1 - abs(2*p[0]-1)))]
        layers += 1
    return pts[:n]

def _project_to_simplex(p):
    u = p[0]
    v = p[1] * 2 / SQRT3
    if u + v <= 1 and u >= 0 and v >= 0:
        return p
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (u, v * SQRT3 / 2)

def _random_point():
    u, v = random.random(), random.random()
    if u + v > 1:
        u, v = 1-u, 1-v
    return (u, v * SQRT3 / 2)

def _anneal(n_pts=11, iters=5000, seed=None):
    random.seed(seed)
    pts = np.array(_hexagonal_points(n_pts))
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        T = max(0.01, 0.1 * math.exp(-5.0 * t/iters))
        idx = random.randrange(n_pts)
        trial = pts.copy()
        step = 0.05 * math.exp(-3.0 * t/iters)
        trial[idx] += random.uniform(-step, step), random.uniform(-step, step)
        trial[idx] = _project_to_simplex(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or random.random() < math.exp(delta / max(T, 1e-12)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

    return best_pts

def find_points(seed=None):
    pts = _anneal(n_pts=11, iters=12000, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

from __future__ import annotations

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
HEX_GRID_SCALE = 0.12

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> Tuple[float, List[Tuple[int,int,int]]]:
    n = len(pts)
    min_area = float('inf')
    min_triangles = []

    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    min_triangles = [(i,j,k)]
                elif a == min_area:
                    min_triangles.append((i,j,k))

    return min_area, min_triangles

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _hex_grid_point(i: int, n: int) -> np.ndarray:
    row = int(math.sqrt(i))
    col = i - row*row
    x = (col + 0.5 * (row % 2)) * HEX_GRID_SCALE
    y = row * HEX_GRID_SCALE * SQRT3 * 0.5
    u = x
    v = y * 2/SQRT3
    if u + v > 1.0:
        return _random_point()
    return (1 - u - v) * _A + u * _B + v * _C

def _is_inside(p: np.ndarray) -> bool:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    return u >= 0 and v >= 0 and (u + v) <= 1.0

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    projected = (1 - u - v) * _A + u * _B + v * _C
    if not _is_inside(projected):
        return _random_point()
    return projected

def _initial_configuration(n_pts: int = 11) -> np.ndarray:
    pts = []
    for i in range(n_pts):
        if i < 6:
            pts.append(_hex_grid_point(i, n_pts))
        else:
            pts.append(_random_point())
    return np.array(pts)

def _anneal(n_pts: int = 11, iters: int = 5000, seed: int | None = 0) -> np.ndarray:
    rng = random.Random(seed)
    pts = _initial_configuration(n_pts)
    best_pts = pts.copy()
    best_val, _ = _min_triangle_area(best_pts)

    for t in range(iters):
        T = max(0.1 * (1 - t/iters)**2, 1e-8)
        step_size = 0.05 * (1 - t/iters)**0.5 + 0.001

        min_area, min_triangles = _min_triangle_area(pts)
        involved_indices = set()
        for tri in min_triangles:
            involved_indices.update(tri)

        trial = pts.copy()
        for idx in involved_indices:
            perturbation = rng.uniform(-step_size, step_size, size=2)
            trial[idx] += perturbation
            trial[idx] = _project_to_simplex(trial[idx])

        trial_val, _ = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or rng.random() < math.exp(delta / max(T, 1e-12)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=5000, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

from __future__ import annotations

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    best = float("inf")
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best < 1e-8:
                        return 0
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    w = 1.0 - u - v
    if u >= 0 and v >= 0 and w >= 0:
        return p
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        s = u + v
        u /= s
        v /= s
    return (1 - u - v) * _A + u * _B + v * _C

def _mixed_configuration(n_pts: int = 11) -> np.ndarray:
    pts = []
    # Add hexagonal points
    layers = math.ceil((math.sqrt(8*n_pts/3 + 1) - 1)/2)
    for layer in range(layers):
        count = layer + 1
        for i in range(count):
            u = (i + 0.5) / (layers)
            v = (layer - i + 0.5) / (layers)
            if len(pts) < n_pts:
                pts.append((1 - u - v) * _A + u * _B + v * _C)
    # Add random points to fill
    while len(pts) < n_pts:
        pts.append(_random_point())
    return np.array(pts[:n_pts])

def _optimized_anneal(n_pts: int = 11,
                     iters: int = 10000,
                     start_temp: float = 0.1,
                     end_temp: float = 1e-10,
                     seed: int | None = 0) -> np.ndarray:
    rng = random.Random(seed)
    pts = _mixed_configuration(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        T = start_temp * (end_temp / start_temp) ** (t / (iters - 1))
        step_size = 0.15 * (1 - (t/iters)**0.3) + 0.005

        # Focus perturbation on worst points
        if t % 10 == 0 and best_val > 1e-6:
            areas = []
            for i in range(n_pts):
                min_a = float('inf')
                for j in range(n_pts):
                    if j == i: continue
                    for k in range(j+1, n_pts):
                        if k == i: continue
                        a = _area(pts[i], pts[j], pts[k])
                        if a < min_a:
                            min_a = a
                areas.append(min_a)
            idx = np.argmin(areas)
        else:
            idx = rng.randrange(n_pts)

        trial = pts.copy()
        trial[idx] += rng.uniform(-step_size, step_size), rng.uniform(-step_size, step_size)
        trial[idx] = _project_to_simplex(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or rng.random() < math.exp(delta / max(T, 1e-12)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()
                if best_val > 0.03:
                    return best_pts

    return best_pts

def _targeted_perturb(pts: np.ndarray, steps: int = 1000) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    n_pts = len(pts)

    for step_num in range(steps):
        trial = best_pts.copy()
        # Focus on points forming smallest triangles
        areas = []
        for i in range(n_pts):
            min_a = float('inf')
            for j in range(n_pts):
                if j == i: continue
                for k in range(j+1, n_pts):
                    if k == i: continue
                    a = _area(best_pts[i], best_pts[j], best_pts[k])
                    if a < min_a:
                        min_a = a
            areas.append(min_a)
        idx = np.argsort(areas)[:3]

        step = 0.03 * (1 - (step_num/steps)**0.2)
        for i in idx:
            trial[i] += random.uniform(-step, step), random.uniform(-step, step)
            trial[i] = _project_to_simplex(trial[i])

        trial_val = _min_triangle_area(trial)
        if trial_val > best_val:
            best_val = trial_val
            best_pts = trial.copy()
            if best_val > 0.03:
                break

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _optimized_anneal(n_pts=11, iters=10000, seed=seed)
    pts = _targeted_perturb(pts, steps=1000)
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

