import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _is_inside_triangle(p: np.ndarray) -> bool:
    x, y = p
    if y < 0 or y > SQRT3/2:
        return False
    if x < 0 or x > 1:
        return False
    if y > SQRT3 * x or y > SQRT3 * (1 - x):
        return False
    return True

def _random_point() -> np.ndarray:
    while True:
        x = random.random()
        y = random.random() * SQRT3/2
        if _is_inside_triangle(np.array([x, y])):
            return np.array([x, y])

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    x, y = p
    if y < 0:
        y = 0
    elif y > SQRT3/2:
        y = SQRT3/2

    if x < 0:
        x = 0
    elif x > 1:
        x = 1

    if y > SQRT3 * x:
        y = SQRT3 * x
    elif y > SQRT3 * (1 - x):
        y = SQRT3 * (1 - x)

    return np.array([x, y])

def _min_triangle_area_fast(pts: np.ndarray, cache=None) -> float:
    n = len(pts)
    min_area = float('inf')

    for i in range(n):
        for j in range(i+1, n):
            p1 = pts[i]
            p2 = pts[j]
            dx12 = p2[0] - p1[0]
            dy12 = p2[1] - p1[1]
            for k in range(j+1, n):
                p3 = pts[k]
                area = abs(dx12 * (p3[1] - p1[1]) - (p3[0] - p1[0]) * dy12)
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0.0
    return min_area / (2.0 * TRIANGLE_AREA)

def _initialize_points(n: int) -> np.ndarray:
    pts = []
    layers = math.ceil(math.sqrt(2 * n / SQRT3))

    for i in range(layers):
        y = (i + 0.5) * SQRT3 / (2 * layers)
        x_start = 0.5 - y / SQRT3
        x_end = 0.5 + y / SQRT3
        points_in_layer = max(1, round(n * (x_end - x_start)))
        for j in range(points_in_layer):
            x = x_start + (j + 0.5) * (x_end - x_start) / points_in_layer
            pts.append([x, y])
            if len(pts) == n:
                return np.array(pts)

    while len(pts) < n:
        pts.append(_random_point())
    return np.array(pts)

def _optimize_points(pts: np.ndarray, iterations: int = 8000) -> np.ndarray:
    n = len(pts)
    best_pts = pts.copy()
    best_score = _min_triangle_area_fast(best_pts)

    for iter in range(iterations):
        temp = max(0.01, 0.2 * (1 - iter/iterations))
        step = max(0.001, 0.1 * (1 - iter/iterations))

        trial_pts = best_pts.copy()
        for i in np.random.permutation(n):
            angle = random.uniform(0, 2*math.pi)
            dx = step * math.cos(angle)
            dy = step * math.sin(angle)
            trial_pts[i] += np.array([dx, dy])
            trial_pts[i] = _project_to_triangle(trial_pts[i])

        trial_score = _min_triangle_area_fast(trial_pts)

        if trial_score > best_score or random.random() < math.exp(10*(trial_score - best_score)/temp):
            best_score = trial_score
            best_pts = trial_pts.copy()

    for refine_iter in range(500):
        improved = False
        for i in np.random.permutation(n):
            for angle in np.linspace(0, 2*math.pi, 24, endpoint=False):
                step = 0.005 * (1 - refine_iter/500)
                dx = step * math.cos(angle)
                dy = step * math.sin(angle)
                trial_pts = best_pts.copy()
                trial_pts[i] += np.array([dx, dy])
                trial_pts[i] = _project_to_triangle(trial_pts[i])
                trial_score = _min_triangle_area_fast(trial_pts)
                if trial_score > best_score:
                    best_score = trial_score
                    best_pts = trial_pts.copy()
                    improved = True
        if not improved:
            break

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _initialize_points(11)
    pts = _optimize_points(pts, 12000)

    return [(float(p[0]), float(p[1])) for p in pts]

