import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TOL = 1e-8

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / 2.0

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n):
        for j in range(i+1, min(i+7, n)):
            for k in range(j+1, min(j+7, n)):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area < 0.01:
                        return min_area
    return min_area

def _is_inside(p: np.ndarray) -> bool:
    x, y = p
    if x < 0 or x > 1 or y < 0 or y > SQRT3/2:
        return False
    if y > SQRT3 * x or y > SQRT3 * (1 - x):
        return False
    return True

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    x, y = p
    if _is_inside(p):
        return p

    # Project to closest edge
    if y <= 0:
        return np.array([max(0.0, min(1.0, x)), 0.0])

    left_edge_y = SQRT3 * x
    right_edge_y = SQRT3 * (1 - x)

    if y >= left_edge_y and y >= right_edge_y:
        return np.array([0.5, SQRT3/2])
    elif y >= left_edge_y:
        dist_left = abs(y - left_edge_y) / math.hypot(1, SQRT3)
        return np.array([x - dist_left * 0.5, y - dist_left * SQRT3/2])
    elif y >= right_edge_y:
        dist_right = abs(y - right_edge_y) / math.hypot(1, SQRT3)
        return np.array([x + dist_right * 0.5, y - dist_right * SQRT3/2])
    else:
        return np.array([max(0.0, min(1.0, x)), max(0.0, min(SQRT3/2, y))])

def _hex_grid(n: int) -> np.ndarray:
    layers = int(math.sqrt(n)) + 1
    pts = []
    for layer in range(layers):
        for i in range(layer + 1):
            u = i / (layer + TOL)
            v = layer / (layers + TOL)
            if u + v > 1.0:
                u, v = 1 - v, 1 - u
            x = (1 - u - v) * 0 + u * 1 + v * 0.5
            y = (1 - u - v) * 0 + u * 0 + v * SQRT3/2
            pts.append([x, y])
    return np.array(pts[:n])

def _optimize(pts: np.ndarray, steps: int = 1000) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)

    for step in range(steps):
        temp = 1.0 - step / steps
        for i in range(len(pts)):
            trial = best_pts.copy()
            delta = 0.01 * temp
            trial[i] += np.random.uniform(-delta, delta, 2)
            trial[i] = _project_to_triangle(trial[i])

            # Ensure we stay inside
            while not _is_inside(trial[i]):
                trial[i] = best_pts[i] + 0.5 * (trial[i] - best_pts[i])
                trial[i] = _project_to_triangle(trial[i])

            new_area = _min_triangle_area(trial)
            if new_area > best_area or (temp > 0 and np.random.random() < math.exp((new_area - best_area)/temp)):
                best_area = new_area
                best_pts = trial.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    np.random.seed(seed)
    pts = _hex_grid(11)
    pts = _optimize(pts, 1500)

    # Final check and adjustment
    for i in range(len(pts)):
        if not _is_inside(pts[i]):
            pts[i] = _project_to_triangle(pts[i])

    return [(float(x), float(y)) for x, y in pts]

