                    if best_val > 0.01:
                        polished = _local_polish(best_pts)
                        polished_val = _min_triangle_area(polished)
                        if polished_val > best_val:
                            best_pts = polished
                            best_val = polished_val

    return best_pts

def _local_polish(pts: np.ndarray) -> np.ndarray:
    if minimize is None or len(pts) == 0:
        return pts
    n_pts = len(pts)
    x0 = pts.ravel()

    def f(x: np.ndarray) -> float:
        P = x.reshape((-1, 2))
        return -_min_triangle_area(P)

    res = minimize(f, x0, method='Nelder-Mead', options={'maxiter': 1000})
    if res.success:
        out = res.x.reshape((n_pts, 2))
        for i in range(n_pts):
            out[i] = _project_to_simplex(out[i])
        return out
    return pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=3000, restarts=3, seed=seed)
    pts = _local_polish(pts)
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

import math
import random
import numpy as np
from typing import List, Tuple
import time
from itertools import combinations
from concurrent.futures import ProcessPoolExecutor, as_completed

SQRT3 = math.sqrt(3.0)
_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _area_fast(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5

def _min_triangle_area_fast(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for trio in combinations(pts, 3):
        area = _area_fast(trio[0], trio[1], trio[2])
        if area < min_area:
            min_area = area
            if min_area == 0:
                return 0
    return min_area

def _random_point_fast() -> np.ndarray:
    u, v = random.random(), random.random()
    if u + v > 1.0:
        u, v = 1-u, 1-v
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex_fast(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv[0], uv[1]
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _hexagonal_grid_points(n_pts: int = 11) -> np.ndarray:
    pts = []
    layers = int(math.ceil(math.sqrt(n_pts / 3))) + 1
    for i in range(-layers, layers+1):
        for j in range(-layers, layers+1):
            x = 0.5 + 0.5 * (i + j/2)
            y = SQRT3/2 * j
            if x + y/SQRT3 <= 1.0 and y <= SQRT3/2 and x >= 0 and y >= 0:
                pts.append(np.array([x, y]))
    if len(pts) < n_pts:
        pts.extend([_random_point_fast() for _ in range(n_pts - len(pts))])
    return np.array(pts[:n_pts])

def _optimize_single_run(seed: int, n_pts: int = 11) -> Tuple[np.ndarray, float]:
    random.seed(seed)
    pts = _hexagonal_grid_points(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area_fast(best_pts)

    for t in range(1000):
        T = max(0.1 * (1 - t/1000)**3, 1e-6)
        idx = random.randrange(n_pts)
        trial = pts.copy()
        step = 0.05 * (1 - t/1000)
        trial[idx] += random.uniform(-step, step), random.uniform(-step, step)
        trial[idx] = _project_to_simplex_fast(trial[idx])

        trial_val = _min_triangle_area_fast(trial)
        if trial_val > best_val or random.random() < math.exp((trial_val - best_val)/T):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = pts.copy()

    try:
        from scipy.optimize import minimize
        x0 = best_pts.ravel()
        def f(x: np.ndarray) -> float:
            P = x.reshape((-1, 2))
            return -_min_triangle_area_fast(P)
        res = minimize(f, x0, method='Nelder-Mead', options={'maxiter': 200})
        if res.success:
            optimized = res.x.reshape((n_pts, 2))
            for i in range(n_pts):
                optimized[i] = _project_to_simplex_fast(optimized[i])
            optimized_val = _min_triangle_area_fast(optimized)
            if optimized_val > best_val:
                best_pts, best_val = optimized, optimized_val
    except:
        pass

    return best_pts, best_val

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    start_time = time.time()
    best_val = -1
    best_pts = None

    with ProcessPoolExecutor() as executor:
        futures = [executor.submit(_optimize_single_run, seed + i) for i in range(4)]
        for future in as_completed(futures):
            pts, val = future.result()
            if val > best_val:
                best_val = val
                best_pts = pts

    return [(float(x), float(y)) for x, y in best_pts]

from __future__ import annotations
import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    best = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

def _hex_grid(n: int) -> np.ndarray:
    max_retries = 3
    layers = math.ceil(math.sqrt(n * 2)) + 2

    for _ in range(max_retries):
        pts = []
        for i in range(-layers, layers+1):
            for j in range(-layers, layers+1):
                x = 0.5 + 0.5 * i + 0.25 * j
                y = SQRT3/4 * j
                pts.append([x, y])
        pts = np.array(pts)
        inside = []
        for p in pts:
            try:
                uv = np.linalg.solve(np.column_stack((_B-_A, _C-_A)), p-_A)
                if len(uv) == 2:
                    u, v = uv[0], uv[1]
                    if u >= 0 and v >= 0 and (1-u-v) >= 0:
                        inside.append(p)
            except:
                continue
        if len(inside) >= n:
            if len(inside) == 0:
                break
            indices = np.random.choice(len(inside), min(n, len(inside)), replace=False)
            return np.array(inside)[indices]
        layers += 1

    # Fallback to random points if hex grid fails
    pts = []
    while len(pts) < n:
        x, y = np.random.uniform(0, 1, 2)
        uv = np.linalg.solve(np.column_stack((_B-_A, _C-_A)), np.array([x,y])-_A)
        if len(uv) == 2:
            u, v = uv[0], uv[1]
            if u >= 0 and v >= 0 and (1-u-v) >= 0:
                pts.append([x, y])
    return np.array(pts)

def _differential_evolution(pop_size: int, n_pts: int, max_iter: int) -> np.ndarray:
    F = 0.7
    CR = 0.8

    def eval_fn(x):
        pts = x.reshape(n_pts, 2)
        return -_min_triangle_area(pts)

    pop = []
    for _ in range(pop_size):
        pts = _hex_grid(n_pts)
        pop.append(pts.flatten())

    best_sol = pop[0].copy()
    best_val = eval_fn(best_sol)

    for _ in range(max_iter):
        for i in range(pop_size):
            idxs = [idx for idx in range(pop_size) if idx != i]
            if len(idxs) < 3:
                continue
            a, b, c = pop[np.random.choice(idxs, 3, replace=False)]
            mutant = a + F * (b - c)

            trial = np.zeros_like(pop[i])
            cross_points = np.random.rand(n_pts*2) < CR
            trial[cross_points] = mutant[cross_points]
            trial[~cross_points] = pop[i][~cross_points]

            for j in range(n_pts):
                x, y = trial[j*2], trial[j*2+1]
                uv = np.linalg.solve(np.column_stack((_B-_A, _C-_A)), np.array([x,y])-_A)
                if len(uv) == 2:
                    u, v = uv[0], uv[1]
                    if u < 0 or v < 0 or (1-u-v) < 0:
                        trial[j*2:j*2+2] = pop[i][j*2:j*2+2]

            trial_val = eval_fn(trial)
            if trial_val < best_val:
                best_val = trial_val
                best_sol = trial.copy()
            if trial_val < eval_fn(pop[i]):
                pop[i] = trial

    return best_sol.reshape(n_pts, 2)

def _refine(pts: np.ndarray, steps: int) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    n_pts = len(pts)

    for step in range(steps):
        step_size = 0.02 * (1 - step/steps)
        for idx in range(n_pts):
            for _ in range(3):
                trial = best_pts.copy()
                trial[idx] += np.random.uniform(-step_size, step_size, 2)
                uv = np.linalg.solve(np.column_stack((_B-_A, _C-_A)), trial[idx]-_A)
                if len(uv) == 2:
                    u, v = uv[0], uv[1]
                    if u >= 0 and v >= 0 and (1-u-v) >= 0:
                        trial_val = _min_triangle_area(trial)
                        if trial_val > best_val:
                            best_val = trial_val
                            best_pts = trial.copy()
    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    pts = _differential_evolution(pop_size=12, n_pts=11, max_iter=40)
    pts = _refine(pts, steps=200)

    return [(float(x), float(y)) for x, y in pts]

from __future__ import annotations

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(points: np.ndarray, i: int, j: int, k: int) -> float:
    p, q, r = points[i], points[j], points[k]
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / (2 * TRIANGLE_AREA)

def _min_triangle_area(points: np.ndarray) -> float:
    n = len(points)
    min_area = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                area = _area(points, i, j, k)
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0
    return min_area

def _initial_configuration(n: int = 11) -> np.ndarray:
    points = []
    # Optimized hexagonal grid for n=11
    grid_size = 4
    offsets = [0.2, 0.4, 0.6, 0.8]

    for j in range(grid_size):
        y = offsets[j] * SQRT3 / 2
        for i in range(grid_size):
            x = offsets[i] + (0.25 if j % 2 else 0)
            if y <= SQRT3 / 2 - x * SQRT3 and y <= x * SQRT3:
                points.append([x, y])
            if len(points) >= n:
                break
        if len(points) >= n:
            break

    while len(points) < n:
        x = random.uniform(0.2, 0.8)
        y = random.uniform(0.1, 0.6)
        if y <= SQRT3 / 2 - x * SQRT3 and y <= x * SQRT3:
            points.append([x, y])

    return np.array(points)

def _optimize_points(points: np.ndarray, iterations: int = 10000) -> np.ndarray:
    best_points = points.copy()
    best_area = _min_triangle_area(points)
    current_points = points.copy()
    current_area = best_area

    temp = 1.0
    cooling_rate = 0.9995
    no_improve = 0

    for step in range(iterations):
        temp *= cooling_rate

        idx = random.randint(0, len(points)-1)
        old_point = current_points[idx].copy()

        step_size = 0.1 * temp + 0.01
        if random.random() < 0.1:
            step_size *= 2

        while True:
            angle = random.uniform(0, 2*math.pi)
            dx = math.cos(angle) * step_size
            dy = math.sin(angle) * step_size
            new_x = old_point[0] + dx
            new_y = old_point[1] + dy

            if (new_y >= 0 and new_y <= SQRT3 / 2 and 
                new_y <= SQRT3 * new_x and 
                new_y <= SQRT3 * (1 - new_x)):
                break

        current_points[idx] = [new_x, new_y]
        new_area = _min_triangle_area(current_points)

        accept_prob = math.exp((new_area - current_area)/max(temp, 0.0001))
        if new_area > current_area or random.random() < accept_prob:
            current_area = new_area
            if new_area > best_area:
                best_area = new_area
                best_points = current_points.copy()
                no_improve = 0
            else:
                no_improve += 1
        else:
            current_points[idx] = old_point
            no_improve += 1

        if no_improve > 300 and temp < 0.05:
            break

    return best_points

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    initial_points = _initial_configuration(11)
    optimized_points = _optimize_points(initial_points, 10000)
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in optimized_points]

