import math
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    min_area = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _differential_evolution(n_pts: int = 11, max_iter: int = 1000, pop_size: int = 50, 
                          F: float = 0.8, CR: float = 0.9, seed: int | None = None) -> np.ndarray:
    if seed is not None:
        np.random.seed(seed)

    def generate_individual():
        pts = np.zeros((n_pts, 2))
        for i in range(n_pts):
            u, v = np.random.random(2)
            if u + v > 1.0:
                u, v = 1 - u, 1 - v
            pts[i] = (1 - u - v) * _A + u * _B + v * _C
        return pts

    population = [generate_individual() for _ in range(pop_size)]
    fitness = [_min_triangle_area(ind) for ind in population]
    best_idx = np.argmax(fitness)
    best_individual = population[best_idx].copy()
    best_fitness = fitness[best_idx]

    for _ in range(max_iter):
        for i in range(pop_size):
            idxs = [idx for idx in range(pop_size) if idx != i]
            a, b, c = population[np.random.choice(idxs, 3, replace=False)]
            mutant = a + F * (b - c)
            for j in range(n_pts):
                mutant[j] = _project_to_simplex(mutant[j])

            trial = np.zeros((n_pts, 2))
            for j in range(n_pts):
                if np.random.random() < CR:
                    trial[j] = mutant[j]
                else:
                    trial[j] = population[i][j]

            trial_fitness = _min_triangle_area(trial)
            if trial_fitness > fitness[i]:
                population[i] = trial
                fitness[i] = trial_fitness
                if trial_fitness > best_fitness:
                    best_fitness = trial_fitness
                    best_individual = trial.copy()

    return best_individual

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _differential_evolution(n_pts=11, max_iter=1000, pop_size=50, seed=seed)
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

import math
import random
import itertools
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
AREA_TOTAL = SQRT3 / 4.0

def _area(p: Tuple[float, float], q: Tuple[float, float], r: Tuple[float, float]) -> float:
    return abs((q[0] - p[0]) * (r[1] - p[1]) - (q[1] - p[1]) * (r[0] - p[0])) / (2 * AREA_TOTAL)

class MinTriangleArea:
    __slots__ = ('pts', 'n', 'triangles', 'areas', 'point_to_triangles', 'current_min')

    def __init__(self, pts: List[Tuple[float, float]]):
        self.pts = pts
        self.n = len(pts)
        self.triangles = list(itertools.combinations(range(self.n), 3))
        self.areas = [0.0] * len(self.triangles)
        self.point_to_triangles = [[] for _ in range(self.n)]
        for idx, (i, j, k) in enumerate(self.triangles):
            self.point_to_triangles[i].append(idx)
            self.point_to_triangles[j].append(idx)
            self.point_to_triangles[k].append(idx)
        self._update_all_areas()
        self.current_min = min(self.areas)

    def _update_all_areas(self):
        for idx, (i, j, k) in enumerate(self.triangles):
            self.areas[idx] = _area(self.pts[i], self.pts[j], self.pts[k])

    def update_point(self, i: int, new_pt: Tuple[float, float]]:
        self.pts[i] = new_pt
        for idx in self.point_to_triangles[i]:
            i0, j0, k0 = self.triangles[idx]
            self.areas[idx] = _area(self.pts[i0], self.pts[j0], self.pts[k0])
        self.current_min = min(self.areas)

    def get_min_area(self) -> float:
        return self.current_min

def _barycentric_to_cartesian(u: float, v: float) -> Tuple[float, float]:
    w = 1 - u - v
    x = w * 0.0 + u * 1.0 + v * 0.5
    y = w * 0.0 + u * 0.0 + v * (SQRT3 / 2)
    return (x, y)

def _is_in_triangle(p: Tuple[float, float]) -> bool:
    x, y = p
    v = 2 * y / SQRT3
    u = x - 0.5 * v
    return u >= 0 and v >= 0 and (1 - u - v) >= 0

def _generate_initial_points(n: int) -> List[Tuple[float, float]]:
    points = []
    grid_size = math.ceil(math.sqrt(n * 2))

    for i in range(grid_size):
        for j in range(grid_size - i):
            u = (i + 0.5) / grid_size
            v = (j + 0.5) / grid_size
            points.append(_barycentric_to_cartesian(u, v))
            if len(points) >= n:
                return points[:n]

    while len(points) < n:
        u = random.random()
        v = random.random() * (1 - u)
        points.append(_barycentric_to_cartesian(u, v))

    return points[:n]

def _perturb_point(p: Tuple[float, float], scale: float) -> Tuple[float, float]:
    while True:
        dx = random.uniform(-scale, scale)
        dy = random.uniform(-scale, scale)
        new_p = (p[0] + dx, p[1] + dy)
        if _is_in_triangle(new_p):
            return new_p

def _optimize_points(points: List[Tuple[float, float]], iterations: int) -> List[Tuple[float, float]]:
    min_area = MinTriangleArea(points)
    best_points = points.copy()
    best_min = min_area.get_min_area()

    for i in range(iterations):
        temp = 0.1 * (1 - i/iterations)
        scale = 0.05 * (1 - i/iterations) + 0.001

        for j in range(len(points)):
            original_point = points[j]
            new_point = _perturb_point(original_point, scale)

            min_area.update_point(j, new_point)
            current_min = min_area.get_min_area()

            if current_min > best_min:
                best_min = current_min
                best_points = points.copy()
            elif random.random() < math.exp((current_min - best_min)/temp):
                pass
            else:
                min_area.update_point(j, original_point)

    return best_points

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)

    best_points = []
    best_score = 0.0

    for _ in range(5):
        points = _generate_initial_points(11)
        points = _optimize_points(points, 2000)

        current_min_area = MinTriangleArea(points).get_min_area()
        if current_min_area > best_score:
            best_score = current_min_area
            best_points = points

    return [(round(x, 8), round(y, 8)) for x, y in best_points]

from __future__ import annotations

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / (2 * TRIANGLE_AREA)

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n-2):
        for j in range(i+1, n-1):
            p0 = pts[j] - pts[i]
            for k in range(j+1, n):
                p1 = pts[k] - pts[i]
                area = abs(p0[0]*p1[1] - p0[1]*p1[0]) / (2 * TRIANGLE_AREA)
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0
    return min_area

def _random_point_in_triangle() -> np.ndarray:
    r1 = random.random()
    r2 = random.random()
    if r1 + r2 > 1:
        r1 = 1 - r1
        r2 = 1 - r2
    x = r1 * 1.0 + r2 * 0.5
    y = r2 * SQRT3 / 2.0
    return np.array([x, y])

def _initialize_points(n_pts: int) -> np.ndarray:
    # Hexagonal grid initialization
    pts = []
    layers = math.ceil(math.sqrt(n_pts / 3))
    spacing = 0.8 / (2 * layers)

    for i in range(-layers, layers + 1):
        for j in range(-layers, layers + 1):
            x = 0.5 + i * spacing + (j % 2) * spacing / 2
            y = SQRT3 / 3 + j * spacing * SQRT3 / 2
            if _is_in_triangle(np.array([x, y])):
                pts.append(np.array([x, y]))
                if len(pts) == n_pts:
                    return np.array(pts)

    # Fill remaining points if needed
    while len(pts) < n_pts:
        pts.append(_random_point_in_triangle())
    return np.array(pts)

def _is_in_triangle(p: np.ndarray) -> bool:
    x, y = p
    if y < 0 or y > SQRT3/2:
        return False
    if x < 0 or x > 1:
        return False
    if y > SQRT3 * x or y > SQRT3 * (1 - x):
        return False
    return True

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    x, y = p
    if _is_in_triangle(p):
        return p

    # Project to closest point inside triangle
    edge1 = lambda x: SQRT3 * x
    edge2 = lambda x: SQRT3 * (1 - x)

    # Project to bottom edge
    if y < 0:
        x = max(0.01, min(0.99, x))
        return np.array([x, 0.01])

    # Project to left edge
    d1 = abs(y - edge1(x))
    # Project to right edge
    d2 = abs(y - edge2(x))

    if d1 < d2:
        y_proj = edge1(x)
        if y_proj < 0:
            return np.array([0.01, 0.01])
        return np.array([max(0.01, min(0.99, x)), max(0.01, min(y_proj, SQRT3/2 - 0.01))])
    else:
        y_proj = edge2(x)
        if y_proj < 0:
            return np.array([0.99, 0.01])
        return np.array([max(0.01, min(0.99, x)), max(0.01, min(y_proj, SQRT3/2 - 0.01))])

def _anneal(n_pts: int = 11,
            iters: int = 50000,
            start_temp: float = 0.2,
            end_temp: float = 1e-10,
            step_size: float = 0.05,
            seed: int | None = None) -> np.ndarray:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _initialize_points(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        T = start_temp * (end_temp / start_temp) ** (t / iters)
        current_step = step_size * (1 - 0.9 * t/iters)

        idx = random.randrange(n_pts)
        trial = pts.copy()

        if t % 200 == 0:
            # Occasional large jump
            trial[idx] = _random_point_in_triangle()
        else:
            # Biased random walk
            delta = np.random.normal(0, current_step, size=2)
            trial[idx] += delta
            trial[idx] = _project_to_triangle(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta_val = trial_val - best_val

        if delta_val > 0 or math.exp(delta_val / max(T, 1e-12)) > random.random():
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _point_in_triangle(p: np.ndarray) -> bool:
    x, y = p
    return (y >= 0 and y <= SQRT3/2 and 
            x >= y/SQRT3 and x <= 1 - y/SQRT3)

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n):
        for j in range(i+1, min(i+8, n)):
            v1 = pts[j] - pts[i]
            for k in range(j+1, min(j+8, n)):
                v2 = pts[k] - pts[i]
                area = abs(v1[0]*v2[1] - v1[1]*v2[0]) * 0.5
                if area < min_area:
                    min_area = area
                    if min_area < 0.001:  # Early termination
                        return 0
    return min_area

def _grid_points(n: int) -> np.ndarray:
    points = []
    layers = 8  # Increased to 8 layers
    for layer in range(1, layers+1):
        y = (layer * SQRT3) / (2 * layers)
        x_start = 0.5 - (layer * 0.5) / layers
        step = 1.0 / layers
        for i in range(layer + 1):
            x = x_start + i * step
            points.append(np.array([x, y]))

    # Add center points between grid points
    for i in range(len(points)-1):
        for j in range(i+1, min(i+4, len(points))):
            mid = (points[i] + points[j]) * 0.5
            if _point_in_triangle(mid):
                points.append(mid)

    while len(points) < n:
        points.append(_random_point())
    return np.array(points[:n])

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _optimize_local(pts: np.ndarray, steps: int = 200) -> np.ndarray:
    current = pts.copy()
    best = current.copy()
    best_val = _min_triangle_area(best)

    for step in range(steps):
        step_size = 0.03 * (1 - step/steps)**2
        improved = False
        for i in range(len(current)):
            for dx in [-step_size, 0, step_size]:
                for dy in [-step_size, 0, step_size]:
                    if dx == 0 and dy == 0:
                        continue
                    trial = current.copy()
                    trial[i] += np.array([dx, dy])
                    if not _point_in_triangle(trial[i]):
                        continue
                    val = _min_triangle_area(trial)
                    if val > best_val:
                        best_val = val
                        best = trial.copy()
                        improved = True
        if not improved:
            break
        current = best.copy()
    return best

def _anneal(n_pts: int = 11, iters: int = 4000, seed: int = 0) -> np.ndarray:
    random.seed(seed)
    pts = _grid_points(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        T = max(0.005, 0.15 * (1 - t/iters)**4)
        idx = random.randrange(n_pts)
        trial = pts.copy()
        step = 0.04 * (1 - t/iters)**2
        trial[idx] += np.random.uniform(-step, step, 2)

        if not _point_in_triangle(trial[idx]):
            trial[idx] = _random_point()

        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or random.random() < math.exp(delta / (T + 1e-8)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

    best_pts = _optimize_local(best_pts, steps=200)
    return best_pts

def find_points(seed: int = 0) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=4000, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

