import math
import random
import numpy as np
from scipy.spatial import KDTree

SQRT3 = math.sqrt(3.0)
TRI_AREA = SQRT3 / 4.0

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5

def _min_triangle_area(pts, kdtree=None, neighbor_size=7):
    n = len(pts)
    min_area = float('inf')

    if kdtree is None:
        for i in range(n):
            for j in range(i+1, n):
                for k in range(j+1, n):
                    area = _area(pts[i], pts[j], pts[k])
                    if area < min_area:
                        min_area = area
                        if min_area == 0:
                            return 0
    else:
        for i in range(n):
            _, idxs = kdtree.query(pts[i], neighbor_size)
            for j_idx in range(1, neighbor_size):
                for k_idx in range(j_idx+1, neighbor_size):
                    j = idxs[j_idx]
                    k = idxs[k_idx]
                    if j >= n or k >= n:
                        continue
                    area = _area(pts[i], pts[j], pts[k])
                    if area < min_area:
                        min_area = area
                        if min_area == 0:
                            return 0
    return min_area

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _hex_grid(n):
    k = math.ceil(math.sqrt(n * 2 / SQRT3))
    points = []
    for row in range(k):
        for col in range(k):
            x = (col + 0.5 * (row % 2)) / k
            y = row * SQRT3 / (2 * k)
            if x + y/SQRT3 <= 1.0 and y <= SQRT3/2:
                points.append((1 - x - y/SQRT3) * _A + x * _B + (y/(SQRT3/2)) * _C)
    return points[:n]

def _project_to_simplex(p):
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    w = 1.0 - u - v
    if u >= 0 and v >= 0 and w >= 0:
        return p
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _optimize(pts, iters=2000):
    best_pts = np.array(pts)
    best_val = _min_triangle_area(best_pts)
    current_pts = np.array(pts)
    current_val = best_val
    velocities = np.zeros_like(current_pts)

    for t in range(iters):
        kdtree = KDTree(current_pts)

        if t % 100 == 0:
            step = 0.1 * (1 - t/iters)
            for _ in range(5):
                idx = random.randrange(len(current_pts))
                current_pts[idx] += np.random.uniform(-step, step, 2)
                current_pts[idx] = _project_to_simplex(current_pts[idx])

        gradients = np.zeros_like(current_pts)
        neighbor_size = min(15, len(current_pts))

        for i in range(len(current_pts)):
            _, idxs = kdtree.query(current_pts[i], neighbor_size)
            for j_idx in range(1, neighbor_size):
                for k_idx in range(j_idx+1, neighbor_size):
                    j = idxs[j_idx]
                    k = idxs[k_idx]
                    if j >= len(current_pts) or k >= len(current_pts):
                        continue
                    a = _area(current_pts[i], current_pts[j], current_pts[k])
                    if a < current_val * 2:
                        grad = np.zeros(2)
                        p, q, r = current_pts[i], current_pts[j], current_pts[k]
                        sign = 1 if (q[0]-p[0])*(r[1]-p[1]) > (q[1]-p[1])*(r[0]-p[0]) else -1
                        grad += sign * np.array([q[1]-r[1], r[0]-q[0]])
                        gradients[i] += grad / (a + 1e-8)

        learning_rate = 0.01 * (1 - t/iters)
        velocities = 0.8 * velocities + learning_rate * gradients
        current_pts += velocities
        for i in range(len(current_pts)):
            current_pts[i] = _project_to_simplex(current_pts[i])

        current_val = _min_triangle_area(current_pts, kdtree)
        if current_val > best_val:
            best_val = current_val
            best_pts = current_pts.copy()

    return best_pts

def find_points(seed=None):
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _hex_grid(11)
    pts = _optimize(pts, iters=3000)
    return [(float(x), float(y)) for x, y in pts]

