import math
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / 2.0

def _min_triangle_area(pts: np.ndarray) -> float:
    min_area = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            x1, y1 = pts[i]
            x2, y2 = pts[j]
            dx1 = x2 - x1
            dy1 = y2 - y1
            for k in range(j+1, n):
                x3, y3 = pts[k]
                a = abs(dx1*(y3-y1) - dy1*(x3-x1)) * 0.5
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

def _is_in_triangle(p: np.ndarray) -> bool:
    x, y = p
    if x < 0 or x > 1 or y < 0 or y > SQRT3/2:
        return False
    if y > SQRT3 * x or y > SQRT3 * (1 - x):
        return False
    return True

def _random_point() -> np.ndarray:
    while True:
        x = np.random.random()
        y = np.random.random() * SQRT3 / 2
        if _is_in_triangle(np.array([x, y])):
            return np.array([x, y])

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    x, y = p
    if _is_in_triangle(p):
        return p

    # Project to nearest edge
    if x < 0:
        x = 0
    elif x > 1:
        x = 1

    if y < 0:
        y = 0
    elif y > SQRT3 / 2:
        y = SQRT3 / 2

    # Project to diagonal edges
    if y > SQRT3 * x:
        y = SQRT3 * x
    if y > SQRT3 * (1 - x):
        y = SQRT3 * (1 - x)

    return np.array([x, y])

def _initial_configuration(n: int) -> np.ndarray:
    if n == 11:
        # Start with a known good hexagonal pattern
        pts = []
        for i in range(3):
            for j in range(4 - i):
                x = 0.15 + i * 0.25 + j * 0.5
                y = 0.1 + i * 0.433
                pts.append([x, y])
        return np.array(pts)
    return np.array([_random_point() for _ in range(n)])

def _anneal(n_pts: int = 11,
            iters: int = 10000,
            start_temp: float = 0.1,
            end_temp: float = 1e-8,
            seed: int | None = None) -> np.ndarray:
    if seed is not None:
        np.random.seed(seed)

    pts = _initial_configuration(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        T = start_temp * (end_temp / start_temp) ** (t / iters)
        step_size = 0.05 * (1 - t/iters) + 0.01

        idx = np.random.randint(n_pts)
        trial = pts.copy()
        trial[idx] += np.random.normal(0, step_size, size=2)
        trial[idx] = _project_to_triangle(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta = trial_val - _min_triangle_area(pts)

        if delta > 0 or np.random.random() < math.exp(delta / max(T, 1e-12)):
            pts = trial

        current_val = _min_triangle_area(pts)
        if current_val > best_val:
            best_val = current_val
            best_pts = pts.copy()

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=10000, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

