import math
import random
import numpy as np
from typing import List, Tuple
from scipy.spatial import KDTree

SQRT3 = math.sqrt(3.0)
INV_SQRT3 = 1.0 / SQRT3

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _is_in_triangle(p: np.ndarray) -> bool:
    x, y = p
    return (y >= 0 and y <= SQRT3/2 and 
            x >= 0 and x <= 1 and 
            (1 - x) * SQRT3 >= y)

def _hexagonal_grid(n: int) -> np.ndarray:
    size = math.ceil(math.sqrt(n * 2 / SQRT3))
    pts = []
    for j in range(size):
        for i in range(size + 1):
            x = (i + 0.5 * (j % 2)) / (size + 1)
            y = (j + 0.5) * SQRT3 * 0.5 / (size + 1)
            if _is_in_triangle([x, y]):
                pts.append([x, y])
                if len(pts) == n:
                    return np.array(pts)
    return np.array(pts[:n])

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = 1 - u, 1 - v
    return (1 - u - v) * _A + u * _B + v * _C

def _min_triangle_area_fast(pts: np.ndarray) -> float:
    tree = KDTree(pts)
    min_area = float('inf')

    for i in range(len(pts)):
        neighbors = tree.query(pts[i], k=5)[1][1:]
        for j in neighbors:
            if j <= i:
                continue
            for k in neighbors:
                if k <= j:
                    continue
                vec1 = pts[j] - pts[i]
                vec2 = pts[k] - pts[i]
                cross = abs(vec1[0]*vec2[1] - vec1[1]*vec2[0])
                area = cross * 0.5
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0.0
    return min_area

def _optimize_points(pts: np.ndarray, iters: int = 200) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area_fast(pts)

    for _ in range(iters):
        improved = False
        for i in range(len(pts)):
            for angle in np.linspace(0, 2*np.pi, 8, endpoint=False):
                dx, dy = 0.01*math.cos(angle), 0.01*math.sin(angle)
                trial = best_pts.copy()
                trial[i] += (dx, dy)
                trial[i] = _project_to_simplex(trial[i])
                val = _min_triangle_area_fast(trial)
                if val > best_val:
                    best_val = val
                    best_pts = trial.copy()
                    improved = True
        if not improved:
            break
    return best_pts

def _anneal(n_pts: int = 11, iters: int = 5000) -> np.ndarray:
    best_pts = _hexagonal_grid(n_pts)
    best_val = _min_triangle_area_fast(best_pts)

    for restart in range(3):
        pts = _hexagonal_grid(n_pts)
        current_val = _min_triangle_area_fast(pts)
        step_size = 0.03

        for t in range(iters):
            T = 0.5 * (1e-10 / 0.5) ** ((t / iters) ** 1.5)

            idx = random.randrange(n_pts)
            trial = pts.copy()
            trial[idx] += random.uniform(-step_size, step_size), random.uniform(-step_size, step_size)
            trial[idx] = _project_to_simplex(trial[idx])

            trial_val = _min_triangle_area_fast(trial)
            delta = trial_val - current_val

            if delta > 0 or random.random() < math.exp(delta / max(T, 1e-12)):
                pts = trial
                current_val = trial_val
                if trial_val > best_val:
                    best_val = trial_val
                    best_pts = trial.copy()

    return _optimize_points(best_pts)

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)
    pts = _anneal(n_pts=11)
    return [(float(x), float(y)) for x, y in pts]

import math
import random
import numpy as np
from itertools import combinations

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / 2.0

def _min_triangle_area(pts):
    min_area = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area < 1e-8:
                        return min_area
    return min_area

def _is_in_triangle(p):
    x, y = p
    if x < 0 or x > 1 or y < 0 or y > SQRT3/2:
        return False
    if y > SQRT3 * x:
        return False
    if y > SQRT3 * (1 - x):
        return False
    return True

def _generate_initial_points():
    # Based on known optimal patterns for n=11
    points = [
        [0.0, 0.0],
        [1.0, 0.0],
        [0.5, SQRT3/2],
        [0.25, SQRT3/4],
        [0.75, SQRT3/4],
        [0.125, SQRT3/8],
        [0.375, SQRT3/8],
        [0.625, SQRT3/8],
        [0.875, SQRT3/8],
        [0.0625, SQRT3/16],
        [0.1875, SQRT3/16],
        [0.3125, SQRT3/16],
        [0.4375, SQRT3/16],
        [0.5625, SQRT3/16],
        [0.6875, SQRT3/16],
        [0.8125, SQRT3/16],
        [0.9375, SQRT3/16]
    ]

    # Filter points inside triangle and select 11 best
    valid_points = [p for p in points if _is_in_triangle(p)]
    if len(valid_points) >= 11:
        return np.array(valid_points[:11])

    # Fallback to grid if needed
    grid = []
    for i in range(5):
        for j in range(5-i):
            x = 0.1 + 0.2 * i + 0.1 * j
            y = SQRT3 * 0.1 * i
            if _is_in_triangle((x, y)):
                grid.append([x, y])
            if i > 0 and j > 0:
                x_mirror = 1.0 - x
                if _is_in_triangle((x_mirror, y)):
                    grid.append([x_mirror, y])

    while len(grid) < 11:
        x = random.uniform(0.05, 0.95)
        y = random.uniform(0.01, 0.85)
        if _is_in_triangle((x, y)):
            grid.append([x, y])

    return np.array(grid[:11])

def _optimize_combined(points, iterations):
    best_points = points.copy()
    best_score = _min_triangle_area(best_points)

    current_points = points.copy()
    current_score = best_score

    temp = 0.2
    cooling_rate = 0.9995

    for i in range(iterations):
        # Simulated annealing step
        new_points = current_points.copy()
        idx = random.randint(0, len(points)-1)
        step = 0.03 * (1 - i/iterations)

        perturbation = np.random.uniform(-step, step, 2)
        new_points[idx] += perturbation

        if not _is_in_triangle(new_points[idx]):
            continue

        new_score = _min_triangle_area(new_points)

        if new_score > current_score or random.random() < math.exp((new_score - current_score)/temp):
            current_score = new_score
            current_points = new_points.copy()

            if current_score > best_score:
                best_score = current_score
                best_points = current_points.copy()

        # Local search step
        if i % 10 == 0:
            for j in range(len(points)):
                for dx in [-0.01, 0, 0.01]:
                    for dy in [-0.01, 0, 0.01]:
                        if dx == 0 and dy == 0:
                            continue
                        trial_point = best_points[j] + np.array([dx, dy])
                        if _is_in_triangle(trial_point):
                            trial_points = best_points.copy()
                            trial_points[j] = trial_point
                            trial_score = _min_triangle_area(trial_points)
                            if trial_score > best_score:
                                best_score = trial_score
                                best_points = trial_points.copy()

        temp *= cooling_rate

    return best_points

def find_points(seed=None):
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    points = _generate_initial_points()
    points = _optimize_combined(points, 5000)

    return [(float(p[0]), float(p[1])) for p in points]

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area_fast(pts: np.ndarray) -> float:
    n = len(pts)
    best = float('inf')
    for i in range(n):
        for j in range(i+1, min(i+6, n)):
            for k in range(j+1, min(j+6, n)):
                a = _area(pts[i], pts[j], pts[k])
                if a < best and a > 1e-8:
                    best = a
                    if best < 0.01:
                        return best
    return best

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    if u >= 0 and v >= 0 and (u + v) <= 1:
        return p
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _is_inside_triangle(p: np.ndarray) -> bool:
    x, y = p
    return (y <= SQRT3/2 and (1 - x - y/SQRT3) >= 0 and x >= 0)

def _initialize_hexagonal(n: int = 11) -> np.ndarray:
    pts = []
    layers = 2  # Reduced layers to ensure all points stay inside
    for layer in range(layers + 1):
        for i in range(layer + 1):
            j = layer - i
            x = 0.5 * i + 0.5 * j / 2
            y = SQRT3 * j / 2
            if _is_inside_triangle([x, y]):
                pts.append(np.array([x, y]))

    # Add center points first
    center_pts = [
        (_A + _B + _C) / 3,
        (_A + _B) / 2,
        (_A + _C) / 2,
        (_B + _C) / 2,
        (2*_A + _B + _C) / 4,
        (_A + 2*_B + _C) / 4,
        (_A + _B + 2*_C) / 4
    ]
    for pt in center_pts:
        if len(pts) < n:
            pts.append(pt)

    # Fill remaining with random points inside triangle
    while len(pts) < n:
        u = random.random()
        v = random.random() * (1 - u)
        pts.append((1 - u - v) * _A + u * _B + v * _C)

    return np.array(pts[:n])

def _optimize_points_fast(pts: np.ndarray, max_iter: int = 1000) -> np.ndarray:
    n = len(pts)
    best_pts = pts.copy()
    best_score = _min_triangle_area_fast(best_pts)
    no_improve = 0

    for iter in range(max_iter):
        if no_improve > 50 and iter > max_iter//2:
            break

        step = 0.05 * (1 - iter/max_iter)
        idx = random.randrange(n)

        for _ in range(5):
            trial = best_pts.copy()
            delta = np.random.uniform(-step, step, 2)
            trial[idx] += delta
            trial[idx] = _project_to_simplex(trial[idx])

            current_score = _min_triangle_area_fast(trial)
            if current_score > best_score:
                best_score = current_score
                best_pts = trial.copy()
                no_improve = 0
            else:
                no_improve += 1

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    pts = _initialize_hexagonal(11)
    pts = _optimize_points_fast(pts, 1000)

    # Final validation
    for pt in pts:
        if not _is_inside_triangle(pt):
            pt = _project_to_simplex(pt)

    return [(float(x), float(y)) for x, y in pts]

