import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / 2.0

def _min_triangle_area(pts: np.ndarray) -> Tuple[float, List[Tuple[int,int,int]]]:
    n = len(pts)
    min_area = float('inf')
    min_triangles = []

    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    min_triangles = [(i,j,k)]
                elif a == min_area:
                    min_triangles.append((i,j,k))
                if min_area == 0:
                    return (0, [])
    return (min_area / TRIANGLE_AREA, min_triangles)

def _random_barycentric() -> Tuple[float, float, float]:
    s = random.random()
    t = random.random()
    if s + t > 1:
        s, t = 1 - s, 1 - t
    return (s, t, 1 - s - t)

def _barycentric_to_cartesian(b: Tuple[float, float, float]) -> np.ndarray:
    return np.array([0.5*b[2] + b[1], SQRT3/2 * b[2]])

def _initial_configuration() -> np.ndarray:
    # Start with known good configuration
    pts = [
        [0.5, SQRT3/2],  # Top vertex
        [0.0, 0.0],      # Bottom left
        [1.0, 0.0],      # Bottom right
        [0.25, SQRT3/4], 
        [0.75, SQRT3/4],
        [0.125, SQRT3/8],
        [0.375, SQRT3/8],
        [0.625, SQRT3/8],
        [0.875, SQRT3/8],
        [0.5, SQRT3/6],
        [0.5, SQRT3/3]
    ]
    return np.array(pts)

def _optimize_points(pts: np.ndarray, iterations: int = 10000) -> np.ndarray:
    n = len(pts)
    best_pts = pts.copy()
    best_score, _ = _min_triangle_area(best_pts)

    for iter in range(iterations):
        temp = math.exp(-5.0 * iter/iterations)  # Exponential cooling

        # Get current min triangles to target mutations
        _, min_triangles = _min_triangle_area(best_pts)
        if min_triangles:
            # Pick a random point from smallest triangles
            triangle = random.choice(min_triangles)
            idx = random.choice(triangle)
        else:
            idx = random.randrange(n)

        # Generate new point
        s, t, u = _random_barycentric()
        new_pt = _barycentric_to_cartesian((s, t, u))

        trial = best_pts.copy()
        trial[idx] = new_pt
        trial_score, _ = _min_triangle_area(trial)

        if trial_score > best_score or random.random() < temp:
            best_score = trial_score
            best_pts = trial

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
    pts = _initial_configuration()
    pts = _optimize_points(pts, 20000)
    return [(float(x), float(y)) for x, y in pts]

