        return False
    if x < 0 or x > 1:
        return False
    return y <= SQRT3 * (1 - abs(2*x - 1))

def _hexagonal_grid(n: int) -> np.ndarray:
    pts = []
    size = int(math.ceil(math.sqrt(n * 2.5)))  # Slightly larger grid
    for i in range(size):
        for j in range(size):
            if len(pts) >= n:
                break
            x = 0.5 + (i - j) * 0.5 / size
            y = j * SQRT3 / 2 / size
            if _is_in_triangle(x, y):
                pts.append([x, y])
    # Fill remaining points with random positions inside triangle
    while len(pts) < n:
        x = random.uniform(0, 1)
        y_max = SQRT3 * (1 - abs(2*x - 1))
        y = random.uniform(0, y_max)
        pts.append([x, y])
    return np.array(pts)

