    u, v = random.random(), random.random()
    if u + v > 1.0:
        u, v = 1-u, 1-v
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    x, y = p
    if y > SQRT3 * min(x, 1 - x):
        if x < 0.5:
            y = SQRT3 * x
        else:
            y = SQRT3 * (1 - x)
        return np.array([x, y])
    return p

def _initial_configuration() -> np.ndarray:
    pts = []
    # Hexagonal pattern
    for i in range(6):
        angle = math.pi/3 * i
        pts.append([0.5 + 0.4*math.cos(angle), SQRT3/3 + 0.4*math.sin(angle)])
    # Center points
    pts.append([0.5, SQRT3/6])
    # Edge points
    for i in range(1, 4):
        t = i/4
        pts.append([t, 0])
        pts.append([0.5*(1-t), SQRT3/2*(1-t)])
    return np.array(pts[:11])

def _optimize_step(pts: np.ndarray, step_size: float) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _area_vectorized(best_pts)

    for i in range(len(pts)):
        for _ in range(5):
            trial = pts.copy()
            dx = random.uniform(-step_size, step_size)
            dy = random.uniform(-step_size, step_size)
            trial[i] = _project_to_simplex(trial[i] + [dx, dy])
            area = _area_vectorized(trial)
            if area > best_area:
                best_area = area
                best_pts = trial.copy()
                break

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    pts = _initial_configuration()

    for step in [0.1, 0.05, 0.02, 0.01]:
        for _ in range(50):
            pts = _optimize_step(pts, step)

    min_area = _area_vectorized(pts)
    if min_area > 0.0365 * TRIANGLE_AREA:
        return [(float(x), float(y)) for x, y in pts]

    # Final refinement
    for _ in range(100):
        pts = _optimize_step(pts, 0.005)

    return [(float(x), float(y)) for x, y in pts]

