    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    u, v = random.random(), random.random()
    if u + v > 1.0:
        u, v = 1-u, 1-v
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    if u >= 0 and v >= 0 and (1 - u - v) >= 0:
        return p
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _optimize_local(pts: np.ndarray, steps: int = 30) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    step_size = 0.05

    for _ in range(steps):
        improved = False
        for i in range(len(pts)):
            for _ in range(10):  # Try more directions
                trial = best_pts.copy()
                # Try both random and gradient-based moves
                if random.random() < 0.3:
                    # Gradient-like move: push away from nearest points
                    nearest = np.argsort([np.linalg.norm(trial[i]-p) for p in trial])[1:4]
                    direction = sum(trial[i] - trial[j] for j in nearest)
                    trial[i] += 0.01 * direction / np.linalg.norm(direction)
                else:
                    trial[i] += np.random.uniform(-step_size, step_size, 2)
                trial[i] = _project_to_simplex(trial[i])
                trial_val = _min_triangle_area(trial)
                if trial_val > best_val:
                    best_val = trial_val
                    best_pts = trial.copy()
                    improved = True
        if not improved:
            step_size *= 0.5
        else:
            step_size = min(0.05, step_size * 1.2)
    return best_pts

def _generate_initial_points() -> np.ndarray:
    # More structured initial configuration
    pts = []
    for i in range(3):
        for j in range(4):
            if i + j <= 3:
                u = 0.1 + 0.8 * i / 3
                v = 0.1 + 0.8 * j / 3
                pts.append((1-u-v) * _A + u * _B + v * _C)
    # Add remaining points randomly but well-spread
    while len(pts) < 11:
        p = _random_point()
        min_dist = min(np.linalg.norm(p - q) for q in pts) if pts else float('inf')
