    return np.array(pts)

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    pts = _generate_initial_points()

    # Multi-stage optimization
    for _ in range(3):
        pts = _optimize_local(pts, steps=15)
