import math
import random
import itertools
from typing import List, Tuple
import numpy as np

SQRT3 = math.sqrt(3.0)
TRI_AREA = SQRT3 / 4.0

def _area(p, q, r) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / (2 * TRI_AREA)

def _min_triangle_area(pts: np.ndarray) -> float:
    min_area = float('inf')
    n = len(pts)
    for i in range(n-2):
        for j in range(i+1, n-1):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

def _is_inside_triangle(pt: np.ndarray) -> bool:
    x, y = pt
    if x < 0 or x > 1 or y < 0 or y > SQRT3/2:
        return False
    if y > SQRT3 * x or y > SQRT3 * (1 - x):
        return False
    return True

def _initial_configuration() -> np.ndarray:
    pts = []
    # Hexagonal lattice with center point
    pts.append(np.array([0.5, SQRT3/6]))
    for i in range(1, 4):
        for j in range(i+1):
            x = 0.5 - i/6 + j/3
            y = SQRT3 * (i/6)
            if _is_inside_triangle(np.array([x, y])):
                pts.append(np.array([x, y]))

    # Add symmetric edge points
    if len(pts) < 11:
        pts.extend([np.array([0.0, 0.0]), np.array([1.0, 0.0]), np.array([0.5, SQRT3/2])])

    # Fill remaining points with good spacing
    while len(pts) < 11:
        best_pt = None
        best_min_dist = 0
        for _ in range(10):
            x = random.uniform(0.1, 0.9)
            y_max = min(SQRT3 * x, SQRT3 * (1 - x))
            y = random.uniform(0.1, y_max - 0.1)
            pt = np.array([x, y])
            min_dist = min(np.linalg.norm(p - pt) for p in pts) if pts else float('inf')
            if min_dist > best_min_dist:
                best_min_dist = min_dist
                best_pt = pt
        pts.append(best_pt)

    return np.array(pts[:11])

def _perturb_point(pt: np.ndarray, step_size: float) -> np.ndarray:
    while True:
        new_pt = pt + np.random.uniform(-step_size, step_size, 2)
        if _is_inside_triangle(new_pt):
            return new_pt

def _optimize(pts: np.ndarray, iterations: int = 2000) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)
    current_pts = pts.copy()

    for i in range(iterations):
        step_size = 0.05 * (1 - i/iterations)

        idx = random.randint(0, len(current_pts)-1)
        original_pt = current_pts[idx].copy()
        current_pts[idx] = _perturb_point(original_pt, step_size)

        current_area = _min_triangle_area(current_pts)
        if current_area > best_area:
            best_area = current_area
            best_pts = current_pts.copy()
        else:
            current_pts[idx] = original_pt

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _initial_configuration()
    pts = _optimize(pts, iterations=1500)

    return [(float(x), float(y)) for x, y in pts]

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area / TRIANGLE_AREA

def _random_point() -> np.ndarray:
    while True:
        x = random.uniform(0, 1)
        y = random.uniform(0, SQRT3/2)
        if y <= SQRT3 * min(x, 1-x):
            return np.array([x, y])

def _initial_configuration() -> np.ndarray:
    # Hexagonal lattice with some random perturbation
    points = []
    for i in range(11):
        while True:
            if i < 6:
                x = 0.2 + 0.6 * (i % 6) / 5
                y = SQRT3 * (0.2 + 0.6 * (i // 6) / 1)
            else:
                x = 0.2 + 0.6 * ((i-6) % 5) / 4
                y = SQRT3 * (0.4 + 0.4 * ((i-6) // 5) / 1)

            x += random.uniform(-0.05, 0.05)
            y += random.uniform(-0.05, 0.05)

            if 0 <= x <= 1 and 0 <= y <= SQRT3/2 and y <= SQRT3 * min(x, 1-x):
                points.append(np.array([x, y]))
                break
    return np.array(points)

def _perturb_point(p: np.ndarray, scale: float) -> np.ndarray:
    while True:
        delta = np.random.uniform(-scale, scale, 2)
        new_p = p + delta
        if (0 <= new_p[0] <= 1 and 0 <= new_p[1] <= SQRT3/2 and 
            new_p[1] <= SQRT3 * min(new_p[0], 1-new_p[0])):
            return new_p

def _simulated_annealing(initial_pts: np.ndarray, 
                        max_iter: int = 10000,
                        initial_temp: float = 0.1,
                        final_temp: float = 0.0001) -> np.ndarray:
    current_pts = initial_pts.copy()
    current_min_area = _min_triangle_area(current_pts)
    best_pts = current_pts.copy()
    best_min_area = current_min_area

    temp = initial_temp
    cooling_rate = (final_temp / initial_temp) ** (1.0 / max_iter)

    for i in range(max_iter):
        temp *= cooling_rate
        scale = max(0.1 * (1 - i/max_iter), 0.01)

        # Perturb either one point or all points with small probability
        if random.random() < 0.1:
            trial_pts = np.array([_perturb_point(p, scale*0.1) for p in current_pts])
        else:
            idx = random.randrange(len(current_pts))
            trial_pts = current_pts.copy()
            trial_pts[idx] = _perturb_point(current_pts[idx], scale)

        trial_min_area = _min_triangle_area(trial_pts)

        if trial_min_area > current_min_area or \
           (trial_min_area < current_min_area and 
            random.random() < math.exp((trial_min_area - current_min_area)/temp)):
            current_pts = trial_pts
            current_min_area = trial_min_area
            if trial_min_area > best_min_area:
                best_pts = trial_pts.copy()
                best_min_area = trial_min_area

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)

    # Try multiple restarts
    best_pts = None
    best_area = 0.0

    for _ in range(5):
        initial_pts = _initial_configuration()
        optimized_pts = _simulated_annealing(initial_pts, max_iter=5000)
        current_area = _min_triangle_area(optimized_pts)

        if current_area > best_area:
            best_area = current_area
            best_pts = optimized_pts

    return [(float(x), float(y)) for x, y in best_pts]

