                    if min_area == 0:
                        return 0
    return min_area

def _hexagonal_configuration(n: int = 11) -> np.ndarray:
    points = []
    layers = 4
    count = 0

    for layer in range(layers):
        for i in range(layer + 1):
            j = layer - i
            x = 0.5 + (i - j) * 0.5
            y = (i + j) * SQRT3 / 6
            x = 0.1 + 0.8 * x
            y = 0.1 + 0.8 * y
            if y <= SQRT3 / 2 - x * SQRT3 and y <= x * SQRT3:
                points.append([x, y])
                count += 1
                if count >= n:
                    return np.array(points)

    while len(points) < n:
        x = random.uniform(0.1, 0.9)
        y = random.uniform(0.1, 0.8)
        if y <= SQRT3 / 2 - x * SQRT3 and y <= x * SQRT3:
            points.append([x, y])

    return np.array(points)

def _optimize_points(points: np.ndarray, iterations: int = 5000) -> np.ndarray:
    best_points = points.copy()
    best_area = _min_triangle_area(points)
    current_points = points.copy()

    temp = 1.0
    cooling_rate = 0.9995
    step_size = 0.1

    for iter in range(iterations):
        temp *= cooling_rate

        if iter % 50 == 0:
            current_area = _min_triangle_area(current_points)
            if current_area > best_area:
                best_area = current_area
                best_points = current_points.copy()

        step_size = 0.02 + 0.08 * (1 - iter/iterations)

        idx = random.randint(0, len(points)-1)
        old_point = current_points[idx].copy()

        for _ in range(10):
            angle = random.uniform(0, 2*math.pi)
            dist = random.uniform(0, step_size)
            dx = dist * math.cos(angle)
            dy = dist * math.sin(angle)

            new_x = old_point[0] + dx
            new_y = old_point[1] + dy

            if (new_y >= 0 and new_y <= SQRT3 / 2 and 
                new_y <= SQRT3 * new_x and 
                new_y <= SQRT3 * (1 - new_x)):
                current_points[idx] = [new_x, new_y]
                new_area = _min_triangle_area(current_points)

                if new_area > best_area or random.random() < math.exp((new_area - best_area)/temp):
                    if new_area > best_area:
                        best_area = new_area
                        best_points = current_points.copy()
                    break
                else:
                    current_points[idx] = old_point

        if iter % 200 == 0 and best_area < 0.01:
            current_points = best_points.copy()
            for i in range(len(current_points)):
                if random.random() < 0.3:
                    current_points[i] += np.random.normal(0, 0.01, 2)

    return best_points

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    initial_points = _hexagonal_configuration(11)
    optimized_points = _optimize_points(initial_points, 5000)
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in optimized_points]

import math
import random
import numpy as np
from scipy.spatial import Delaunay

SQRT3 = math.sqrt(3.0)
TRI_AREA = SQRT3 / 4.0

def _is_in_triangle(p):
    x, y = p
    return (y >= 0 and x >= 0 and (x * SQRT3 + y) <= SQRT3 and (x * SQRT3 - y) >= 0)

def _min_triangle_area(pts):
    tri = Delaunay(pts)
    triangles = pts[tri.simplices]
    v1 = triangles[:,1] - triangles[:,0]
    v2 = triangles[:,2] - triangles[:,0]
    areas = np.abs(np.cross(v1, v2)) / 2.0
    return np.min(areas) / TRI_AREA

def _generate_initial_points(n):
    points = []
    k = int(math.sqrt(n)) + 1
    for i in range(k):
        for j in range(k):
            x = (i + 0.5 * j) / (k + 0.5)
            y = (j * SQRT3 / 2) / (k + 0.5)
            if _is_in_triangle((x, y)):
                points.append([x, y])
            if len(points) >= n:
                return np.array(points)
    return np.array(points[:n])

def _optimize(n_pts=11, iterations=5000, initial_temp=0.1, seed=None):
    if seed is not None:
        np.random.seed(seed)
        random.seed(seed)

    pts = _generate_initial_points(n_pts)
    current_min = _min_triangle_area(pts)
    best_pts = pts.copy()
    best_min = current_min

    for i in range(iterations):
        temp = initial_temp * (1 - i/iterations)
        idx = np.random.randint(n_pts)
        step = 0.01 * temp

        new_pts = pts.copy()
        perturbation = np.random.uniform(-step, step, 2)
        new_pt = new_pts[idx] + perturbation

        if _is_in_triangle(new_pt):
            new_pts[idx] = new_pt
            new_min = _min_triangle_area(new_pts)

            if new_min > current_min or np.random.random() < math.exp((new_min - current_min)/temp):
                pts = new_pts
                current_min = new_min
                if current_min > best_min:
                    best_pts = pts.copy()
                    best_min = current_min

    return best_pts

def find_points(seed=None):
    pts = _optimize(n_pts=11, iterations=10000, initial_temp=0.2, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

