import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    best = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _is_inside(p: np.ndarray) -> bool:
    u = p[0]
    v = p[1] * 2 / SQRT3
    return u >= 0 and v >= 0 and u + v <= 1

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        total = u + v
        u /= total
        v /= total
    return (1 - u - v) * _A + u * _B + v * _C

def _initial_configuration(n_pts: int = 11) -> np.ndarray:
    pts = []
    # Hexagonal grid with center point
    for i in range(3):
        for j in range(3):
            if i + j <= 2:
                u = (i + 0.5 * (j % 2)) / 2.5
                v = (j + 0.5 * (i % 2)) / 2.5
                pts.append((1 - u - v) * _A + u * _B + v * _C)
    # Add remaining points randomly
    while len(pts) < n_pts:
        pts.append(_random_point())
    return np.array(pts[:n_pts])

def _differential_evolution(n_pts: int = 11,
                          max_iter: int = 300,
                          F: float = 0.5,
                          CR: float = 0.7,
                          seed: int | None = 0) -> np.ndarray:
    if seed is not None:
        random.seed(seed)
    population = [_initial_configuration(n_pts) for _ in range(8)]
    best_pts = max(population, key=lambda x: _min_triangle_area(x))
    best_val = _min_triangle_area(best_pts)

    for _ in range(max_iter):
        for i in range(len(population)):
            a, b, c = random.sample(range(len(population)), 3)
            mutant = population[a].copy()
            for j in range(n_pts):
                if random.random() < CR:
                    mutant[j] = _project_to_simplex(population[a][j] + 
                               F * (population[b][j] - population[c][j]))
            trial_val = _min_triangle_area(mutant)
            if trial_val > _min_triangle_area(population[i])):
                population[i] = mutant
                if trial_val > best_val:
                    best_val = trial_val
                    best_pts = mutant.copy()
    return best_pts

def _local_search(pts: np.ndarray, steps: int = 300) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    n_pts = len(pts)
    for step_num in range(steps):
        trial = best_pts.copy()
        idx = random.randrange(n_pts)
        step = 0.005 * (1 - step_num/steps)**3
        trial[idx] = _project_to_simplex(trial[idx] + 
                       np.random.uniform(-step, step, 2))
        trial_val = _min_triangle_area(trial)
        if trial_val > best_val:
            best_val = trial_val
            best_pts = trial.copy()
    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _differential_evolution(n_pts=11, max_iter=300, seed=seed)
    pts = _local_search(pts, steps=300)
    return [(float(x), float(y)) for x, y in pts]

