import math
import random
import numpy as np

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area_fast(pts: np.ndarray, cutoff: float = 0) -> float:
    n = len(pts)
    best = float('inf')
    for i in range(n-2):
        for j in range(i+1, n-1):
            p = pts[i]
            q = pts[j]
            for k in range(j+1, n):
                a = abs(np.cross(q - p, pts[k] - p)) * 0.5
                if a <= cutoff:
                    return a
                if a < best:
                    best = a
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            return (1 - u - v) * _A + u * _B + v * _C

def _is_in_triangle(p: np.ndarray) -> bool:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    return u >= 0 and v >= 0 and (u + v) <= 1.0

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        s = u + v
        u /= s
        v /= s
    return (1 - u - v) * _A + u * _B + v * _C

def _initial_configuration(n_pts: int = 11) -> np.ndarray:
    pts = []
    layers = 4
    for i in range(layers):
        for j in range(i+1):
            u = (j + 0.5 * (i % 1)) / (layers-1)
            v = (i - j + 0.5 * (i % 1)) / (layers-1)
            if u + v <= 1.0:
                pts.append((1 - u - v) * _A + u * _B + v * _C)
    while len(pts) < n_pts:
        pts.append(_random_point())
    return np.array(pts[:n_pts])

def _optimize(n_pts: int = 11, iters: int = 15000, seed: int | None = 0) -> np.ndarray:
    rng = random.Random(seed)
    pts = _initial_configuration(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area_fast(best_pts)
    no_improve = 0

    for t in range(iters):
        T = max(0.1 * (1 - (t/iters)**0.5), 1e-6)
        idx = rng.randrange(n_pts)
        trial = pts.copy()
        step = 0.05 * (1 - (t/iters)**0.3)
        trial[idx] += rng.uniform(-step, step), rng.uniform(-step, step)
        trial[idx] = _project_to_simplex(trial[idx])

        if not _is_in_triangle(trial[idx]):
            continue

        trial_val = _min_triangle_area_fast(trial, best_val)
        if trial_val <= best_val and rng.random() >= math.exp((trial_val - best_val)/T):
            no_improve += 1
            if no_improve > 500 and t > 5000:
                break
            continue

        pts = trial
        if trial_val > best_val:
            best_val = trial_val
            best_pts = trial.copy()
            no_improve = 0

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _optimize(n_pts=11, iters=15000, seed=seed)
    # Final validation pass
    for i in range(len(pts)):
        if not _is_in_triangle(pts[i]):
            pts[i] = _project_to_simplex(pts[i])
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area_fast(pts: np.ndarray) -> float:
    min_area = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    u, v = random.random(), random.random()
    if u + v > 1.0:
        u, v = 1 - u, 1 - v
    return (1 - u - v) * _A + u * _B + v * _C

def _hex_grid_points(n: int) -> List[np.ndarray]:
    k = int(math.sqrt(n)) + 1
    points = []
    for i in range(k):
        for j in range(k - i):
            u = i / k
            v = j / k
            points.append((1 - u - v) * _A + u * _B + v * _C)
            if len(points) >= n:
                return points
    return points

def _optimize_points(pts: np.ndarray, max_iter: int = 2000) -> np.ndarray:
    n = len(pts)
    best_pts = pts.copy()
    best_area = _min_triangle_area_fast(best_pts)

    for _ in range(max_iter):
        improved = False
        for i in range(n):
            for dx, dy in [(0.01, 0), (-0.01, 0), (0, 0.01), (0, -0.01),
                          (0.007, 0.007), (-0.007, 0.007), (0.007, -0.007), (-0.007, -0.007)]:
                new_pts = best_pts.copy()
                new_pts[i] += np.array([dx, dy])
                new_pts[i] = np.clip(new_pts[i], [0, 0], [1, SQRT3/2])

                area = _min_triangle_area_fast(new_pts)
                if area > best_area:
                    best_area = area
                    best_pts = new_pts.copy()
                    improved = True
        if not improved:
            break
    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)

    # Start with hexagonal grid points
    pts = np.array(_hex_grid_points(11))

    # Add small random perturbations
    for i in range(len(pts)):
        pts[i] += np.random.uniform(-0.02, 0.02, size=2)
        pts[i] = np.clip(pts[i], [0, 0], [1, SQRT3/2])

    # Local optimization with more iterations
    pts = _optimize_points(pts, max_iter=2000)

    return [(float(x), float(y)) for x, y in pts]

