import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    min_area = float('inf')
    n = len(pts)
    for i in range(n-2):
        for j in range(i+1, n-1):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    w = 1.0 - u - v
    if u >= 0 and v >= 0 and w >= 0:
        return p
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        s = u + v
        u /= s
        v /= s
    return (1 - u - v) * _A + u * _B + v * _C

def _get_worst_points(pts: np.ndarray, k: int = 3) -> List[int]:
    n = len(pts)
    point_scores = np.zeros(n)
    min_area = float('inf')

    for i in range(n-2):
        for j in range(i+1, n-1):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                if a == min_area:
                    point_scores[i] += 1
                    point_scores[j] += 1
                    point_scores[k] += 1

    return np.argsort(point_scores)[-k:].tolist()

def _anneal(n_pts: int = 11,
            iters: int = 2000,
            start_temp: float = 0.1,
            end_temp: float = 1e-7,
            seed: int | None = 0) -> np.ndarray:
    rng = random.Random(seed)
    pts = np.array([_random_point() for _ in range(n_pts)])
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    accept_rate = 0.0
    step_size = 0.02

    for t in range(iters):
        T = start_temp * math.exp(-5.0 * t / iters)

        trial = pts.copy()
        if t % 100 == 99:
            idx = rng.choice(_get_worst_points(pts, k=3))
            trial[idx] = _random_point()
        else:
            if rng.random() < 0.2:
                idx = rng.choice(_get_worst_points(pts, k=3))
            else:
                idx = rng.randrange(n_pts)

            if rng.random() < 0.1:
                trial[idx] += rng.uniform(-step_size*3, step_size*3), rng.uniform(-step_size*3, step_size*3)
            else:
                trial[idx] += rng.uniform(-step_size, step_size), rng.uniform(-step_size, step_size)
            trial[idx] = _project_to_simplex(trial[idx])

        trial_val = _min_triangle_area(trial)
        if trial_val == 0:
            continue

        delta = trial_val - _min_triangle_area(pts)

        if delta > 0 or rng.random() < math.exp(delta / max(T, 1e-12)):
            pts = trial
            accept_rate = 0.9 * accept_rate + 0.1
        else:
            accept_rate = 0.9 * accept_rate

        if accept_rate < 0.2:
            step_size *= 0.9
        elif accept_rate > 0.5:
            step_size *= 1.1

        current_val = _min_triangle_area(pts)
        if current_val > best_val:
            best_val = current_val
            best_pts = pts.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=2000, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4

def _point_in_triangle(x: float, y: float) -> bool:
    if y < 0 or y > SQRT3/2:
        return False
    if x < 0 or x > 1:
        return False
    return y <= SQRT3 * (1 - abs(2*x - 1))

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n-2):
        for j in range(i+1, n-1):
            p = pts[i]
            q = pts[j]
            dx1 = q[0] - p[0]
            dy1 = q[1] - p[1]
            for k in range(j+1, n):
                r = pts[k]
                area = abs(dx1 * (r[1] - p[1]) - (r[0] - p[0]) * dy1) * 0.5
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0
    return min_area

def _generate_initial_points(n: int) -> np.ndarray:
    pts = []
    layers = 5
    for layer in range(1, layers+1):
        for i in range(layer):
            x = 0.5 + (i - layer/2 + 0.5) / (2*layers)
            y = (layer - 1) * SQRT3 / (2*layers)
            if _point_in_triangle(x, y):
                pts.append([x, y])

    while len(pts) < n:
        x = random.uniform(0.01, 0.99)
        y = random.uniform(0.01, SQRT3/2 - 0.01)
        if _point_in_triangle(x, y):
            pts.append([x, y])

    return np.array(pts[:n])

def _optimize_points(pts: np.ndarray, iterations: int = 4000) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)
    n = len(pts)
    temp = 0.1

    for iter in range(iterations):
        temp = 0.1 * (1 - iter/iterations)
        new_pts = best_pts.copy()

        for _ in range(5):
            idx = random.randint(0, n-1)
            step = temp * random.random()
            angle = random.uniform(0, 2*math.pi)
            dx = step * math.cos(angle)
            dy = step * math.sin(angle)

            x = new_pts[idx][0] + dx
            y = new_pts[idx][1] + dy

            if _point_in_triangle(x, y):
                new_pts[idx] = [x, y]
            else:
                continue

        new_area = _min_triangle_area(new_pts)
        if new_area > best_area or (random.random() < math.exp((new_area - best_area)/temp) and new_area > 0):
            best_area = new_area
            best_pts = new_pts.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _generate_initial_points(11)
    pts = _optimize_points(pts, 4000)

    # Final validation
    valid_pts = []
    for x, y in pts:
        if _point_in_triangle(x, y):
            valid_pts.append([x, y])
        else:
            # If point is outside, generate a new random point inside
            while True:
                x = random.uniform(0.01, 0.99)
                y = random.uniform(0.01, SQRT3/2 - 0.01)
                if _point_in_triangle(x, y):
                    valid_pts.append([x, y])
                    break

    return [(float(x), float(y)) for x, y in valid_pts[:11]]

