    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

def _is_in_triangle(x: float, y: float) -> bool:
    if y <= MARGIN or y >= SQRT3/2 - MARGIN:
        return False
    if x <= MARGIN or x >= 1 - MARGIN:
        return False
    if y >= SQRT3 * (1 - x) - MARGIN:
        return False
    return True

def _generate_initial_points(n: int) -> np.ndarray:
    points = []
    while len(points) < n:
        x = random.uniform(MARGIN, 1 - MARGIN)
        y_max = min(SQRT3/2 - MARGIN, SQRT3 * (1 - x) - MARGIN)
        y = random.uniform(MARGIN, y_max)
        points.append([x, y])
    return np.array(points)

def _optimize_points(pts: np.ndarray) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area_fast(best_pts)
    n = len(pts)
    step = 0.01

    for _ in range(200):
        improved = False
        for i in range(n):
            for dx, dy in itertools.product([-step, 0, step], [-step, 0, step]):
                if dx == 0 and dy == 0:
                    continue
                trial = best_pts.copy()
                trial[i] += np.array([dx, dy])
                x, y = trial[i]
                if not _is_in_triangle(x, y):
                    continue

                area = _min_triangle_area_fast(trial)
                if area > best_area:
                    best_area = area
                    best_pts = trial.copy()
                    improved = True
        if not improved:
            step *= 0.8
            if step < 1e-5:
                break
    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    pts = _generate_initial_points(11)
    pts = _optimize_points(pts)

    return [(float(x), float(y)) for x, y in pts]

