import math
import random
import itertools
import numpy as np
from scipy.spatial import KDTree

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p, q, r) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / (2 * TRIANGLE_AREA)

def _min_triangle_area(pts: np.ndarray) -> float:
    tree = KDTree(pts)
    best = float('inf')
    for i in range(len(pts)):
        dists, idxs = tree.query(pts[i], k=7)
        for j, k in itertools.combinations(idxs[1:], 2):
            a = _area(pts[i], pts[j], pts[k])
            if a < best:
                best = a
                if best < 0.01:
                    return best
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _initial_configuration() -> np.ndarray:
    pts = []
    # Hexagonal grid with some perturbations
    n_layers = 3
    for i in range(n_layers):
        for j in range(n_layers):
            if i + j < n_layers:
                x = 0.5 * (i + 0.5 * j) / (n_layers - 1)
                y = SQRT3 * j / (2 * (n_layers - 1))
                pts.append(np.array([x, y]))
                if (i,j) != (0,0):
                    pts.append(np.array([1-x, y]))
                    if j > 0:
                        pts.append(np.array([x + 0.25*j/(n_layers-1), y - 0.1*SQRT3/(n_layers-1)]))
    pts = pts[:11]
    return np.array(pts)

def _genetic_optimize(pop_size=20, generations=50, elite_size=4):
    population = [_initial_configuration() for _ in range(pop_size)]
    fitness = [_min_triangle_area(ind) for ind in population]

    for gen in range(generations):
        elite_indices = np.argsort(fitness)[-elite_size:]
        new_population = [population[i].copy() for i in elite_indices]

        while len(new_population) < pop_size:
            parent1, parent2 = random.sample(elite_indices.tolist(), 2)
            child = population[parent1].copy()
            for i in range(len(child)):
                if random.random() < 0.3:
                    child[i] = population[parent2][i].copy()
                if random.random() < 0.2:
                    child[i] += np.random.normal(0, 0.05, 2)
                    child[i] = _project_to_simplex(child[i])
            new_population.append(child)

        population = new_population
        fitness = [_min_triangle_area(ind) for ind in population]

    best_idx = np.argmax(fitness)
    return population[best_idx]

def _pattern_search(pts: np.ndarray, steps=2000) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    step_size = 0.05

    for _ in range(steps):
        improved = False
        for i in range(len(pts)):
            for direction in [(1,0), (-1,0), (0,1), (0,-1), (1,1), (-1,-1)]:
                trial = best_pts.copy()
                trial[i] += np.array(direction) * step_size
                trial[i] = _project_to_simplex(trial[i])
                trial_val = _min_triangle_area(trial)
                if trial_val > best_val:
                    best_val = trial_val
                    best_pts = trial.copy()
                    improved = True
        if not improved:
            step_size *= 0.7
            if step_size < 1e-6:
                break
    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    pts = _genetic_optimize(pop_size=20, generations=50)
    pts = _pattern_search(pts, steps=2000)

    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

