import math
import random
import numpy as np

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    if n < 3:
        return 0.0
    min_area = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                area = _area(pts[i], pts[j], pts[k])
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0.0
    return min_area

def _is_in_triangle(p: np.ndarray) -> bool:
    v0 = np.array([0.5, SQRT3/2]) - np.array([0.0, 0.0])
    v1 = np.array([1.0, 0.0]) - np.array([0.0, 0.0])
    v2 = p - np.array([0.0, 0.0])

    dot00 = np.dot(v0, v0)
    dot01 = np.dot(v0, v1)
    dot02 = np.dot(v0, v2)
    dot11 = np.dot(v1, v1)
    dot12 = np.dot(v1, v2)

    inv_denom = 1.0 / (dot00 * dot11 - dot01 * dot01)
    u = (dot11 * dot02 - dot01 * dot12) * inv_denom
    v = (dot00 * dot12 - dot01 * dot02) * inv_denom

    return (u >= 0) and (v >= 0) and (u + v <= 1)

def _generate_hexagonal_grid(n: int) -> np.ndarray:
    k = math.ceil(math.sqrt(n * 2 / SQRT3)) + 2
    points = []
    for row in range(k):
        y = SQRT3 * row / (2 * k)
        start = 0.0 if row % 2 else 0.5 / k
        for col in range(k):
            x = start + col / k
            if _is_in_triangle(np.array([x, y])):
                points.append(np.array([x, y]))
            if len(points) >= n:
                return np.array(points[:n])
    return np.array(points[:n])

def _optimize_points(pts: np.ndarray, steps: int = 1000) -> np.ndarray:
    current = pts.copy()
    n = len(current)
    best = current.copy()
    best_area = _min_triangle_area(best)

    for step in range(steps):
        temp = 0.1 * (1 - step/steps)
        changed = False

        for i in range(n):
            for _ in range(5):
                angle = random.uniform(0, 2*math.pi)
                radius = 0.05 * (1 - step/steps)
                dx = radius * math.cos(angle)
                dy = radius * math.sin(angle)
                trial = current.copy()
                trial[i] += np.array([dx, dy])

                if not _is_in_triangle(trial[i]):
                    continue

                trial_area = _min_triangle_area(trial)
                delta = trial_area - best_area

                if delta > 0 or (temp > 0 and random.random() < math.exp(delta/temp)):
                    current = trial
                    if trial_area > best_area:
                        best = trial.copy()
                        best_area = trial_area
                    changed = True
                    break

        if not changed:
            break

    return best

def find_points(seed: int | None = 0) -> list[tuple[float, float]]:
    random.seed(seed)
    pts = _generate_hexagonal_grid(11)
    if len(pts) < 11:
        remaining = 11 - len(pts)
        for _ in range(remaining):
            while True:
                x = random.uniform(0, 1)
                y = random.uniform(0, SQRT3/2)
                if _is_in_triangle(np.array([x, y])):
                    pts = np.append(pts, [[x, y]], axis=0)
                    break

    pts = _optimize_points(pts)
    return [(float(p[0]), float(p[1])) for p in pts]

import math
import random
import numpy as np
from scipy.spatial import KDTree
from itertools import combinations

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / 2.0

def _min_triangle_area(pts, kdtree=None, k=15):
    if kdtree is None:
        kdtree = KDTree(pts)
    min_area = float('inf')

    for i, p in enumerate(pts):
        dists, indices = kdtree.query(p, k=min(k+1, len(pts)))
        neighbors = [pts[j] for j in indices if j != i]

        for q, r in combinations(neighbors[:min(k, len(neighbors))], 2):
            a = _area(p, q, r)
            if a < min_area:
                min_area = a
                if min_area == 0:
                    return 0
    return min_area

def _generate_initial_points(n):
    pts = []
    layers = math.ceil(math.sqrt(n * 4 / (3 * SQRT3))) + 1

    for i in range(layers):
        y = (i + 0.5) * (SQRT3/2) / layers
        for j in range(layers):
            x = (j + 0.5) / layers
            if y <= x * SQRT3 and y <= (1 - x) * SQRT3:
                pts.append([x, y])
                if len(pts) == n:
                    return pts

    while len(pts) < n:
        x = random.uniform(0, 1)
        y = random.uniform(0, SQRT3/2)
        if y <= x * SQRT3 and y <= (1 - x) * SQRT3:
            pts.append([x, y])

    return pts

def _project_to_triangle(p):
    x, y = p
    if y < 0: y = 0
    if y > SQRT3/2: y = SQRT3/2
    x = max(0, min(1, x))
    if y > x * SQRT3:
        y = x * SQRT3
    if y > (1 - x) * SQRT3:
        y = (1 - x) * SQRT3
    return [x, y]

def _optimize_points(pts, iterations=500):
    best_pts = np.array(pts)
    best_area = _min_triangle_area(best_pts)
    kdtree = KDTree(best_pts)

    for step in range(iterations):
        temp = 1.0 - step/iterations
        step_size = 0.05 * temp

        for i in range(len(best_pts)):
            trial = best_pts.copy()
            perturbation = np.random.normal(0, step_size, 2)
            trial[i] = _project_to_triangle(trial[i] + perturbation)

            trial_area = _min_triangle_area(trial, kdtree, k=15)
            if trial_area > best_area:
                best_area = trial_area
                best_pts = trial
                kdtree = KDTree(best_pts)

    return best_pts

def find_points(seed=None):
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _generate_initial_points(11)
    pts = _optimize_points(pts, 500)

    return [(float(x), float(y)) for x, y in pts]

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4

def _is_inside_triangle(x: float, y: float) -> bool:
    return (0 <= x <= 1 and 0 <= y <= SQRT3/2 and 
            y <= SQRT3*(1 - abs(2*x - 1)))

def _vectorized_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            vec_ij = pts[j] - pts[i]
            for k in range(j+1, n):
                vec_ik = pts[k] - pts[i]
                area = abs(vec_ij[0]*vec_ik[1] - vec_ij[1]*vec_ik[0]) / 2
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0
    return min_area

def _generate_initial_points(n: int) -> np.ndarray:
    layers = math.ceil((math.sqrt(8*n/3 + 1) - 1)/2)
    pts = []
    center = np.array([0.5, SQRT3/6])

    for layer in range(layers):
        radius = layer / (2*layers)
        for i in range(6*layer):
            angle = 2*math.pi*i/(6*layer) if layer > 0 else 0
            x = center[0] + radius * math.cos(angle)
            y = center[1] + radius * math.sin(angle)
            if _is_inside_triangle(x, y) and len(pts) < n:
                pts.append([x, y])

    while len(pts) < n:
        x = random.uniform(0.1, 0.9)
        y = random.uniform(0.1, 0.8)
        if _is_inside_triangle(x, y):
            pts.append([x, y])

    return np.array(pts)

def _optimize_points(pts: np.ndarray, iterations: int = 5000) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _vectorized_area(best_pts)
    n = len(pts)

    for it in range(iterations):
        temp = 1.0 - it/iterations
        step = 0.05 * temp

        for _ in range(10):
            new_pts = best_pts.copy()
            idx = random.randint(0, n-1)
            delta = np.random.uniform(-step, step, 2)
            new_pts[idx] += delta

            x, y = new_pts[idx]
            if not _is_inside_triangle(x, y):
                continue

            new_area = _vectorized_area(new_pts)
            if new_area > best_area:
                best_area = new_area
                best_pts = new_pts.copy()
                break

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _generate_initial_points(11)
    pts = _optimize_points(pts, 5000)

    return [(float(x), float(y)) for x, y in pts]

import math
import random
import itertools
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
comb = list(itertools.combinations(range(11), 3))

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5

def _min_triangle_area(pts):
    min_area = float('inf')
    for i,j,k in comb:
        a = _area(pts[i], pts[j], pts[k])
        if a < min_area:
            min_area = a
            if min_area == 0:
                return 0
    return min_area

def _hex_grid_points(n):
    points = []
    k = math.ceil(math.sqrt(n / (SQRT3/2)))
    for i in range(k):
        for j in range(k):
            x = (i + 0.5 * (j % 2)) / k
            y = (j * SQRT3 / 2) / k
            if x + y/SQRT3 <= 1.0 and y <= SQRT3/2:
                points.append((x, y))
    return points[:n]

def _project_to_triangle(p):
    x, y = p
    # First project to bounding box
    x = max(0.0, min(1.0, x))
    y = max(0.0, min(SQRT3/2, y))

    # Then project to triangle edges
    if y > SQRT3 * (1 - x):
        # Project to hypotenuse
        x_new = (SQRT3 - y) / SQRT3
        y_new = y
        if x_new < 0:
            x_new = 0
            y_new = SQRT3
        elif x_new > 1:
            x_new = 1
            y_new = 0
        # Choose closest point on hypotenuse
        if (x - x_new)**2 + (y - y_new)**2 < (x - (1 - y/SQRT3))**2 + (y - 0)**2:
            x, y = x_new, y_new
        else:
            x, y = 1 - y/SQRT3, 0
    return (x, y)

def _optimize_points(points, iterations=8000):
    best_points = np.array(points)
    best_score = _min_triangle_area(best_points)

    for _ in range(iterations):
        temp_points = best_points.copy()

        for i in range(len(temp_points)):
            grad = np.zeros(2)
            for j,k in itertools.combinations([x for x in range(11) if x != i], 2):
                p1, p2, p3 = temp_points[i], temp_points[j], temp_points[k]
                area = _area(p1, p2, p3)
                if area < best_score * 1.5:
                    dx = (p2[1] - p3[1]) / (2 * area + 1e-8)
                    dy = (p3[0] - p2[0]) / (2 * area + 1e-8)
                    grad += np.array([dx, dy])

            step_size = 0.005 * (1 - _/iterations)
            temp_points[i] += grad * step_size
            temp_points[i] = _project_to_triangle(temp_points[i])

        current_score = _min_triangle_area(temp_points)
        if current_score > best_score:
            best_score = current_score
            best_points = temp_points.copy()

        if _ % 200 == 0 and _ > 0:
            temp_points = best_points.copy()
            for i in range(len(temp_points)):
                temp_points[i] += np.random.normal(0, 0.01, 2)
                temp_points[i] = _project_to_triangle(temp_points[i])
            shake_score = _min_triangle_area(temp_points)
            if shake_score > best_score:
                best_score = shake_score
                best_points = temp_points.copy()

    return best_points

def find_points(seed=None):
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    initial_points = _hex_grid_points(11)
    optimized_points = _optimize_points(initial_points, 10000)

    # Final projection to ensure all points are inside
    final_points = [_project_to_triangle(p) for p in optimized_points]
    return [(float(x), float(y)) for x,y in final_points]

