import math
import random
import itertools
from typing import List, Tuple
import numpy as np

SQRT3 = math.sqrt(3.0)
HEIGHT = SQRT3 / 2.0

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    best = float("inf")
    n = len(pts)
    for i in range(n):
        for j in range(i+1, min(i+6, n)):
            for k in range(j+1, min(j+6, n)):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
    return best

def _is_in_triangle(p: np.ndarray) -> bool:
    x, y = p
    if y < 0 or y > HEIGHT:
        return False
    if x < 0 or x > 1:
        return False
    if y > SQRT3 * x or y > SQRT3 * (1 - x):
        return False
    return True

def _generate_point_in_triangle() -> np.ndarray:
    while True:
        x = random.random()
        y = random.uniform(0, HEIGHT)
        if _is_in_triangle(np.array([x, y])):
            return np.array([x, y])

def _initial_configuration(n_pts: int = 11) -> np.ndarray:
    pts = []
    # Hexagonal grid center
    center = np.array([0.5, HEIGHT/3])
    pts.append(center)

    # First ring
    radius = 0.2
    for i in range(6):
        angle = math.pi * 2 * i / 6
        x = center[0] + radius * math.cos(angle)
        y = center[1] + radius * math.sin(angle)
        if _is_in_triangle(np.array([x, y])):
            pts.append(np.array([x, y]))

    # Second ring
    radius = 0.35
    for i in range(6):
        angle = math.pi * 2 * i / 6
        x = center[0] + radius * math.cos(angle)
        y = center[1] + radius * math.sin(angle)
        if _is_in_triangle(np.array([x, y])):
            pts.append(np.array([x, y]))

    # Fill remaining points
    while len(pts) < n_pts:
        pts.append(_generate_point_in_triangle())

    return np.array(pts[:n_pts])

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    x, y = p
    if not _is_in_triangle(p):
        x = max(0.0, min(1.0, x))
        y = max(0.0, min(HEIGHT, y))
        if y > SQRT3 * x:
            y = SQRT3 * x
        if y > SQRT3 * (1 - x):
            y = SQRT3 * (1 - x)
    return np.array([x, y])

def _anneal(n_pts: int = 11,
            iters: int = 10000,
            start_temp: float = 0.1,
            end_temp: float = 1e-6,
            step_size: float = 0.05,
            seed: int | None = None) -> np.ndarray:
    rng = random.Random(seed)
    pts = _initial_configuration(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        T = start_temp * (end_temp / start_temp) ** (t / (iters - 1))
        idx = rng.randrange(n_pts)
        trial = pts.copy()
        step = step_size * (1 - t/iters)
        trial[idx] += rng.uniform(-step, step), rng.uniform(-step, step)
        trial[idx] = _project_to_triangle(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or rng.random() < math.exp(delta / max(T, 1e-12)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=10000, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

