import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / (2 * TRIANGLE_AREA)

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')

    for i in range(n-2):
        p0 = pts[i]
        for j in range(i+1, n-1):
            p1 = pts[j]
            vec1 = p1 - p0
            for k in range(j+1, n):
                vec2 = pts[k] - p0
                area = abs(vec1[0]*vec2[1] - vec1[1]*vec2[0]) / (2 * TRIANGLE_AREA)
                if area < min_area:
                    min_area = area
                    if min_area < 0.001:
                        return min_area
    return min_area

def _random_point_in_triangle() -> np.ndarray:
    r1 = random.random()
    r2 = random.random()
    if r1 + r2 > 1:
        r1 = 1 - r1
        r2 = 1 - r2
    x = r1 * 1.0 + r2 * 0.5
    y = r2 * SQRT3 / 2.0
    return np.array([x, y])

def _initialize_points(n_pts: int) -> np.ndarray:
    pts = []

    # Known good points for n=6
    pts.append(np.array([0.0, 0.0]))
    pts.append(np.array([1.0, 0.0]))
    pts.append(np.array([0.5, SQRT3/2]))
    pts.append(np.array([0.5, 0.0]))
    pts.append(np.array([0.25, SQRT3/4]))
    pts.append(np.array([0.75, SQRT3/4]))

    # Add center and symmetric points
    pts.append(np.array([0.5, SQRT3/6]))
    pts.append(np.array([0.25, SQRT3/12]))
    pts.append(np.array([0.75, SQRT3/12]))

    # Fill remaining with optimized points
    while len(pts) < n_pts:
        new_pt = _random_point_in_triangle()
        min_dist = min(np.linalg.norm(new_pt - pt) for pt in pts)
        if min_dist > 0.18:
            pts.append(new_pt)

    return np.array(pts[:n_pts])

def _is_in_triangle(p: np.ndarray) -> bool:
    x, y = p
    if y < 0 or y > SQRT3/2:
        return False
    if x < 0 or x > 1:
        return False
    if y > SQRT3 * x or y > SQRT3 * (1 - x):
        return False
    return True

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    x, y = p
    if _is_in_triangle(p):
        return p

    edge1 = lambda x: SQRT3 * x
    edge2 = lambda x: SQRT3 * (1 - x)

    if y < 0:
        x = max(0.01, min(0.99, x))
        return np.array([x, 0.01])

    d1 = abs(y - edge1(x))
    d2 = abs(y - edge2(x))

    if d1 < d2:
        y_proj = edge1(x)
        return np.array([max(0.01, min(0.99, x)), max(0.01, min(y_proj, SQRT3/2 - 0.01))])
    else:
        y_proj = edge2(x)
        return np.array([max(0.01, min(0.99, x)), max(0.01, min(y_proj, SQRT3/2 - 0.01))])

def _anneal(n_pts: int = 11,
            iters: int = 40000,
            start_temp: float = 0.5,
            end_temp: float = 1e-12,
            step_size: float = 0.05,
            seed: int | None = None) -> np.ndarray:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _initialize_points(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        T = start_temp * (end_temp / start_temp) ** (t / (iters*0.8))
        current_step = step_size * (1 - t/iters)**2

        idx = random.randrange(n_pts)
        trial = pts.copy()

        if t % 200 == 0 or best_val < 0.01:
            trial[idx] = _random_point_in_triangle()
        else:
            delta = np.random.normal(0, current_step, size=2)
            trial[idx] += delta
            trial[idx] = _project_to_triangle(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta_val = trial_val - best_val

        if delta_val > 0 or (T > 1e-12 and math.exp(delta_val / T) > random.random()):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

    # Focused local optimization
    for _ in range(500):
        improved = False
        for i in range(n_pts):
            for dx, dy in [(0.01,0), (-0.01,0), (0,0.01), (0,-0.01)]:
                trial = best_pts.copy()
                trial[i] += np.array([dx, dy])
                trial[i] = _project_to_triangle(trial[i])
                trial_val = _min_triangle_area(trial)
                if trial_val > best_val:
                    best_val = trial_val
                    best_pts = trial.copy()
                    improved = True
                    break
            if improved:
                break
        if not improved:
            break

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _area(points, triples):
    p = points[triples[:, 0]]
    q = points[triples[:, 1]]
    r = points[triples[:, 2]]
    return np.abs((q[:,0]-p[:,0])*(r[:,1]-p[:,1]) - (q[:,1]-p[:,1])*(r[:,0]-p[:,0])) * 0.5

def _min_triangle_area(pts):
    n = len(pts)
    triples = np.zeros((n*(n-1)*(n-2)//6, 3), dtype=int)
    idx = 0
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                triples[idx] = [i, j, k]
                idx += 1
    return np.min(_area(pts, triples))

def _random_point():
    u, v = random.random(), random.random()
    if u + v > 1.0:
        u, v = 1-u, 1-v
    return (1 - u - v) * _A + u * _B + v * _C

def _hexagonal_points(n):
    points = []
    k = int(math.sqrt(n)) + 1
    i = 0
    while len(points) < n:
        for j in range(k):
            if len(points) >= n:
                break
            x = 0.5 + (i * 0.5) / (k-1)
            y = (j * SQRT3/2) / (k-1)
            if x - y/SQRT3 >= 0 and x + y/SQRT3 <= 1 and y <= SQRT3/2:
                points.append([x, y])
        i += 1
    return np.array(points[:n])

def _project_to_simplex(p):
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv[0], uv[1]
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _optimize_local(pts, steps=100):
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    n = len(pts)

    for _ in range(steps):
        improved = False
        for i in range(n):
            trial = pts.copy()
            trial[i] += random.uniform(-0.01, 0.01), random.uniform(-0.01, 0.01)
            trial[i] = _project_to_simplex(trial[i])
            trial_val = _min_triangle_area(trial)
            if trial_val > best_val:
                pts = trial
                best_val = trial_val
                best_pts = pts.copy()
                improved = True
        if not improved:
            break
    return best_pts

def _anneal(n_pts=11, iters=10_000, start_temp=0.2, end_temp=1e-6, step_size=0.02, seed=None):
    if seed is not None:
        random.seed(seed)
    pts = _hexagonal_points(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        T = start_temp * (end_temp / start_temp) ** (t / max(iters-1, 1))
        idx = random.randrange(n_pts)
        trial = pts.copy()
        trial[idx] += random.uniform(-step_size, step_size), random.uniform(-step_size, step_size)
        trial[idx] = _project_to_simplex(trial[idx])
        trial_val = _min_triangle_area(trial)

        if trial_val > best_val or random.random() < math.exp((trial_val - best_val) / max(T, 1e-12)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = pts.copy()

    return _optimize_local(best_pts, steps=50)

def find_points(seed=None) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=10_000, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

import math
import random
import itertools
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _is_inside_triangle(p: np.ndarray) -> bool:
    x, y = p
    if x < 0 or x > 1 or y < 0 or y > SQRT3/2:
        return False
    if y > SQRT3 * x or y > SQRT3 * (1 - x):
        return False
    return True

def _barycentric_random_point() -> np.ndarray:
    u, v = random.random(), random.random()
    if u + v > 1:
        u, v = 1 - u, 1 - v
    return np.array([0.5 * (1 + u - v), SQRT3/2 * v])

def _area(p1: np.ndarray, p2: np.ndarray, p3: np.ndarray) -> float:
    return abs((p2[0] - p1[0])*(p3[1] - p1[1]) - (p2[1] - p1[1])*(p3[0] - p1[0])) / 2.0

def _min_triangle_area(pts: np.ndarray) -> float:
    min_area = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                area = _area(pts[i], pts[j], pts[k])
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0
    return min_area / TRIANGLE_AREA

def _initial_configuration() -> np.ndarray:
    pts = []
    # Hexagonal grid with more points for better initial coverage
    layers = 5
    for i in range(layers):
        for j in range(layers - i):
            u = (i + 0.5) / layers
            v = (j + 0.5) / layers
            if u + v <= 1.0:
                pts.append([0.5 * (1 + u - v), SQRT3/2 * v])

    # Add some random points if needed
    while len(pts) < 11:
        pt = _barycentric_random_point()
        if not any(np.allclose(pt, x, atol=1e-4) for x in pts):
            pts.append(pt)

    return np.array(pts[:11])

def _optimize_points(pts: np.ndarray, iterations: int = 5000) -> np.ndarray:
    best_pts = pts.copy()
    best_score = _min_triangle_area(best_pts)

    for restart in range(3):  # Multiple restarts
        current_pts = best_pts.copy() if restart > 0 else pts.copy()
        current_score = _min_triangle_area(current_pts)

        for i in range(iterations):
            temp = 0.2 * (1 - i/iterations)**2
            step = 0.1 * (1 - i/iterations)**2

            # Try moving each point in random order
            indices = list(range(11))
            random.shuffle(indices)

            for idx in indices:
                trial_pts = current_pts.copy()
                trial_pts[idx] += np.random.uniform(-step, step, 2)

                if not _is_inside_triangle(trial_pts[idx]):
                    trial_pts[idx] = _barycentric_random_point()

                trial_score = _min_triangle_area(trial_pts)

                if trial_score > current_score or (temp > 0 and 
                   random.random() < math.exp((trial_score - current_score)/temp)):
                    current_pts = trial_pts
                    current_score = trial_score

                    if trial_score > best_score:
                        best_pts = trial_pts.copy()
                        best_score = trial_score

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _initial_configuration()
    pts = _optimize_points(pts)

    return [(float(x), float(y)) for x, y in pts]

