import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    min_area = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, min(i+8, n)):
            for k in range(j+1, min(j+8, n)):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(1e-8, min(1.0-1e-8, u))
    v = max(1e-8, min(1.0-1e-8, v))
    if u + v > 1.0:
        total = u + v
        u = (u / total) * (1.0 - 1e-8)
        v = (v / total) * (1.0 - 1e-8)
    return (1 - u - v) * _A + u * _B + v * _C

def _hexagonal_grid(n_pts: int = 11) -> np.ndarray:
    pts = []
    layers = math.ceil(math.sqrt(n_pts * 2 / SQRT3))
    for i in range(layers):
        for j in range(layers):
            x = (j + 0.5 * (i % 2)) / (layers - 0.5)
            y = (i * SQRT3/2) / (layers - 0.5)
            if x + y/SQRT3 <= 1.0-1e-8 and x - y/SQRT3 >= 1e-8 and y <= SQRT3/2-1e-8:
                pts.append(np.array([x, y]))
            if len(pts) >= n_pts:
                break
        if len(pts) >= n_pts:
            break
    while len(pts) < n_pts:
        pts.append(_random_point())
    return np.array(pts[:n_pts])

def _anneal(n_pts: int = 11,
            iters: int = 5000,
            start_temp: float = 0.1,
            end_temp: float = 1e-8,
            seed: int | None = 0) -> np.ndarray:
    rng = np.random.RandomState(seed)
    pts = _hexagonal_grid(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    no_improve = 0

    for t in range(iters):
        T = start_temp * math.exp(math.log(end_temp/start_temp) * t/iters)
        current_step = 0.05 * (1 - t/iters) + 0.002

        if no_improve > 100 and T < 0.01:
            break

        idx = rng.randint(n_pts)
        trial = pts.copy()
        trial[idx] += rng.uniform(-current_step, current_step, size=2)
        trial[idx] = _project_to_simplex(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or rng.random() < math.exp(delta / max(T, 1e-12)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = pts.copy()
                no_improve = 0
            else:
                no_improve += 1

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=5000, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

from __future__ import annotations
import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n-2):
        p = pts[i]
        for j in range(i+1, n-1):
            q = pts[j]
            dx1 = q[0] - p[0]
            dy1 = q[1] - p[1]
            for k in range(j+1, n):
                r = pts[k]
                area = abs(dx1*(r[1]-p[1]) - dy1*(r[0]-p[0])) * 0.5
                if area < min_area:
                    min_area = area
                    if min_area < 1e-12:
                        return 0.0
    return min_area / TRIANGLE_AREA

def _random_point() -> np.ndarray:
    s, t = sorted([random.random(), random.random()])
    u = 1 - t
    v = t - s
    w = s
    x = 0.5 * v + w
    y = SQRT3 * 0.5 * v
    return np.array([x, y])

def _initial_configuration() -> np.ndarray:
    pts = []
    # Central point
    pts.append(np.array([0.5, SQRT3/6]))

    # Ring of 6 points
    for i in range(6):
        angle = math.pi/3 * i
        r = 0.5
        x = 0.5 + r * math.cos(angle) * 0.5
        y = SQRT3/6 + r * math.sin(angle) * 0.5
        pts.append(np.array([x, y]))

    # Outer ring of 4 points
    for i in range(4):
        angle = math.pi/2 * i + math.pi/4
        r = 0.8
        x = 0.5 + r * math.cos(angle) * 0.5
        y = SQRT3/6 + r * math.sin(angle) * 0.5
        pts.append(np.array([x, y]))

    return np.array(pts[:11])

def _is_in_triangle(x: float, y: float) -> bool:
    v0 = np.array([0.5, SQRT3/2])
    v1 = np.array([0.0, 0.0])
    v2 = np.array([1.0, 0.0])

    def sign(a: np.ndarray, b: np.ndarray, c: np.ndarray) -> float:
        return (a[0] - c[0])*(b[1] - c[1]) - (b[0] - c[0])*(a[1] - c[1])

    d1 = sign(np.array([x, y]), v0, v1)
    d2 = sign(np.array([x, y]), v1, v2)
    d3 = sign(np.array([x, y]), v2, v0)

    has_neg = (d1 < 0) or (d2 < 0) or (d3 < 0)
    has_pos = (d1 > 0) or (d2 > 0) or (d3 > 0)

    return not (has_neg and has_pos)

def _project_to_triangle(x: float, y: float) -> np.ndarray:
    if _is_in_triangle(x, y):
        return np.array([x, y])

    # Project to nearest edge
    if y > SQRT3 * x or y > SQRT3 * (1 - x):
        # Project to top edge
        x_proj = x
        y_proj = min(SQRT3 * x, SQRT3 * (1 - x))
    else:
        # Project to bottom edge
        x_proj = max(0.0, min(1.0, x))
        y_proj = 0.0

    return np.array([x_proj, y_proj])

def _differential_evolution(pop_size: int = 30, max_iter: int = 200, F: float = 0.8, CR: float = 0.9) -> np.ndarray:
    n_pts = 11
    dim = n_pts * 2

    def _to_params(pts: np.ndarray) -> np.ndarray:
        return pts.flatten()

    def _to_points(params: np.ndarray) -> np.ndarray:
        pts = params.reshape((n_pts, 2))
        for i in range(n_pts):
            pts[i] = _project_to_triangle(pts[i][0], pts[i][1])
        return pts

    def _evaluate(params: np.ndarray) -> float:
        pts = _to_points(params)
        return -_min_triangle_area(pts)

    bounds = [(0.0, 1.0) if i % 2 == 0 else (0.0, SQRT3/2) for i in range(dim)]
    pop = np.random.uniform(low=[b[0] for b in bounds], high=[b[1] for b in bounds], size=(pop_size, dim))
    fitness = np.array([_evaluate(ind) for ind in pop])

    best_idx = np.argmin(fitness)
    best_params = pop[best_idx]
    best_fitness = fitness[best_idx]

    for _ in range(max_iter):
        for i in range(pop_size):
            idxs = [idx for idx in range(pop_size) if idx != i]
            a, b, c = pop[np.random.choice(idxs, 3, replace=False)]
            mutant = np.clip(a + F * (b - c), [b[0] for b in bounds], [b[1] for b in bounds])

            cross_points = np.random.rand(dim) < CR
            if not np.any(cross_points):
                cross_points[np.random.randint(0, dim)] = True
            trial = np.where(cross_points, mutant, pop[i])

            trial_fitness = _evaluate(trial)
            if trial_fitness < fitness[i]:
                pop[i] = trial
                fitness[i] = trial_fitness
                if trial_fitness < best_fitness:
                    best_fitness = trial_fitness
                    best_params = trial

    return _to_points(best_params)

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    best_pts = None
    best_score = 0.0

    for _ in range(3):
        pts = _initial_configuration()
        pts = _differential_evolution()
        score = _min_triangle_area(pts)
        if score > best_score:
            best_score = score
            best_pts = pts

    return [(float(x), float(y)) for x, y in best_pts]

from __future__ import annotations
import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    best = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

def _is_inside(p: np.ndarray) -> bool:
    try:
        u, v = np.linalg.solve(np.column_stack((_B-_A, _C-_A)), p-_A)[0]
        return u >= -1e-8 and v >= -1e-8 and (1-u-v) >= -1e-8
    except:
        return False

def _hex_grid(n: int) -> np.ndarray:
    layers = math.ceil(math.sqrt(n / 3)) + 2
    pts = []
    for i in range(-layers, layers+1):
        for j in range(-layers, layers+1):
            x = 0.5 + 0.5 * i + 0.25 * j
            y = SQRT3/4 * j
            pts.append([x, y])
    pts = np.array(pts)
    inside = [p for p in pts if _is_inside(p)]
    if len(inside) < n:
        inside = []
        while len(inside) < n:
            x = random.uniform(0, 1)
            y = random.uniform(0, SQRT3/2)
            if y <= SQRT3 * x and y <= SQRT3 * (1 - x):
                inside.append([x, y])
    return np.array(inside[:n])

def _optimize(pts: np.ndarray, steps: int) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)
    n = len(pts)

    for step in range(steps):
        temp = best_pts.copy()
        for i in range(n):
            for _ in range(5):
                delta = np.random.uniform(-0.01, 0.01, 2)
                candidate = temp.copy()
                candidate[i] += delta
                if not _is_inside(candidate[i]):
                    continue
                current_area = _min_triangle_area(candidate)
                if current_area > best_area:
                    best_area = current_area
                    temp = candidate.copy()
        best_pts = temp.copy()
    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    # Start with hexagonal grid
    pts = _hex_grid(11)

    # Optimize the configuration
    pts = _optimize(pts, 100)

    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

from __future__ import annotations

import math
import random
import itertools
from typing import List, Tuple
import numpy as np

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p, q, r) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / (2 * TRIANGLE_AREA)

comb = list(itertools.combinations(range(11), 3))

def _min_triangle_area(pts: np.ndarray) -> float:
    min_area = float('inf')
    for i, j, k in comb:
        a = _area(pts[i], pts[j], pts[k])
        if a < min_area:
            min_area = a
            if min_area == 0:
                return 0
    return min_area

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    x = (1 - u - v) * _A[0] + u * _B[0] + v * _C[0]
    y = (1 - u - v) * _A[1] + u * _B[1] + v * _C[1]
    return np.array([x, y])

def _is_inside_triangle(pt: np.ndarray) -> bool:
    def sign(a, b, c):
        return (a[0] - c[0])*(b[1] - c[1]) - (b[0] - c[0])*(a[1] - c[1])

    d1 = sign(pt, _A, _B)
    d2 = sign(pt, _B, _C)
    d3 = sign(pt, _C, _A)

    has_neg = (d1 < 0) or (d2 < 0) or (d3 < 0)
    has_pos = (d1 > 0) or (d2 > 0) or (d3 > 0)
    return not (has_neg and has_pos)

def _project_to_triangle(pt: np.ndarray) -> np.ndarray:
    if _is_inside_triangle(pt):
        return pt

    # Find closest point on triangle edges
    edges = [(_A, _B), (_B, _C), (_C, _A)]
    min_dist = float('inf')
    closest = pt

    for p1, p2 in edges:
        l2 = (p1[0]-p2[0])**2 + (p1[1]-p2[1])**2
        if l2 == 0:
            continue
        t = max(0, min(1, ((pt[0]-p1[0])*(p2[0]-p1[0]) + (pt[1]-p1[1])*(p2[1]-p1[1])) / l2))
        proj = np.array([p1[0] + t*(p2[0]-p1[0]), p1[1] + t*(p2[1]-p1[1])])
        dist = np.linalg.norm(pt - proj)
        if dist < min_dist:
            min_dist = dist
            closest = proj

    # Move slightly inside the triangle
    centroid = (_A + _B + _C) / 3.0
    return closest + (centroid - closest) * 0.001

def _initial_configuration(n_pts: int = 11) -> np.ndarray:
    pts = []
    pts.append(_A.copy())
    pts.append(_B.copy())
    pts.append(_C.copy())
    for _ in range(n_pts - 3):
        while True:
            pt = _random_point()
            if all(np.linalg.norm(pt - x) > 0.1 for x in pts):
                pts.append(pt)
                break
    return np.array(pts)

def _optimize(pts: np.ndarray, iterations: int, initial_step: float) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    n_pts = len(pts)

    for i in range(iterations):
        step = initial_step * (1 - i/iterations)**2
        trial = best_pts.copy()
        idx = random.randrange(n_pts)
        trial[idx] += random.uniform(-step, step), random.uniform(-step, step)
        trial[idx] = _project_to_triangle(trial[idx])

        trial_val = _min_triangle_area(trial)
        if trial_val > best_val:
            best_val = trial_val
            best_pts = trial.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    pts = _initial_configuration(11)
    pts = _optimize(pts, 15000, 0.1)
    pts = _optimize(pts, 10000, 0.05)
    pts = _optimize(pts, 5000, 0.02)

    # Final verification
    for pt in pts:
        if not _is_inside_triangle(pt):
            pt = _project_to_triangle(pt)

    return [(float(x), float(y)) for x, y in pts]

from __future__ import annotations

import math
import random
import itertools
from typing import List, Tuple
import numpy as np

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    min_area = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _hex_grid_points(n: int) -> List[np.ndarray]:
    pts = []
    k = int(math.sqrt(n)) + 3
    for i in range(k):
        for j in range(k):
            u = (i + 0.5 * (j % 2)) / k
            v = (j * SQRT3 / 2) / k
            if u + v/SQRT3 <= 1.0:
                pts.append((1 - u - v/SQRT3) * _A + u * _B + v/SQRT3 * _C)
    if len(pts) < n:
        pts.extend([_random_point() for _ in range(n - len(pts))])
    return pts[:n]

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    w = 1.0 - u - v
    if u >= 0 and v >= 0 and w >= 0:
        return p
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _local_optimize(pts: np.ndarray, max_iter: int = 200) -> np.ndarray:
    n = len(pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for step in np.linspace(0.05, 0.001, max_iter):
        improved = False
        for i in range(n):
            for dx in np.linspace(-step, step, 5):
                for dy in np.linspace(-step, step, 5):
                    trial = best_pts.copy()
                    trial[i] += np.array([dx, dy])
                    trial[i] = _project_to_simplex(trial[i])
                    val = _min_triangle_area(trial)
                    if val > best_val:
                        best_val = val
                        best_pts = trial.copy()
                        improved = True
        if not improved and step > 0.01:
            for i in range(n):
                trial = best_pts.copy()
                trial[i] += np.random.uniform(-0.1, 0.1, 2)
                trial[i] = _project_to_simplex(trial[i])
                val = _min_triangle_area(trial)
                if val > best_val:
                    best_val = val
                    best_pts = trial.copy()
    return best_pts

def _anneal(n_pts: int = 11,
            iters: int = 10000,
            start_temp: float = 0.1,
            end_temp: float = 1e-8,
            step_size: float = 0.05,
            seed: int | None = 0) -> np.ndarray:
    rng = np.random.RandomState(seed)
    pts = np.array(_hex_grid_points(n_pts))
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        T = start_temp * (end_temp / start_temp) ** (t / max(iters-1, 1))
        idx = rng.randint(n_pts)
        trial = pts.copy()
        trial[idx] += rng.uniform(-step_size, step_size, size=2)
        trial[idx] = _project_to_simplex(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or rng.random() < math.exp(delta / max(T, 1e-12)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = pts.copy()

        if t % 1000 == 0:
            pts = _local_optimize(pts, max_iter=50)

    return _local_optimize(best_pts, max_iter=300)

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=10000, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

import math
import random
import itertools
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
AREA_TOTAL = SQRT3 / 4.0

def _area(p: Tuple[float, float], q: Tuple[float, float], r: Tuple[float, float]) -> float:
    return abs((q[0] - p[0]) * (r[1] - p[1]) - (q[1] - p[1]) * (r[0] - p[0])) / (2 * AREA_TOTAL)

class MinTriangleArea:
    __slots__ = ('pts', 'n', 'triangles', 'areas', 'point_to_triangles', 'current_min')

    def __init__(self, pts: List[Tuple[float, float]]):
        self.pts = pts
        self.n = len(pts)
        self.triangles = list(itertools.combinations(range(self.n), 3))
        self.areas = [0.0] * len(self.triangles)
        self.point_to_triangles = [[] for _ in range(self.n)]
        for idx, (i, j, k) in enumerate(self.triangles):
            self.point_to_triangles[i].append(idx)
            self.point_to_triangles[j].append(idx)
            self.point_to_triangles[k].append(idx)
        self._update_all_areas()
        self.current_min = min(self.areas)

    def _update_all_areas(self):
        for idx, (i, j, k) in enumerate(self.triangles):
            self.areas[idx] = _area(self.pts[i], self.pts[j], self.pts[k])

    def update_point(self, i: int, new_pt: Tuple[float, float]):
        self.pts[i] = new_pt
        for idx in self.point_to_triangles[i]:
            i0, j0, k0 = self.triangles[idx]
            self.areas[idx] = _area(self.pts[i0], self.pts[j0], self.pts[k0])
        self.current_min = min(self.areas)

    def get_min_area(self) -> float:
        return self.current_min

def _barycentric_to_cartesian(u: float, v: float) -> Tuple[float, float]:
    w = 1 - u - v
    x = w * 0.0 + u * 1.0 + v * 0.5
    y = w * 0.0 + u * 0.0 + v * (SQRT3 / 2)
    return (x, y)

def _is_in_triangle(p: Tuple[float, float]) -> bool:
    x, y = p
    v = 2 * y / SQRT3
    u = x - 0.5 * v
    return u >= 0 and v >= 0 and (1 - u - v) >= 0

def _generate_initial_points(n: int) -> List[Tuple[float, float]]:
    points = []
    k = math.ceil(math.sqrt(4 * n / SQRT3))

    for i in range(k):
        for j in range(k - i):
            u = (i + 0.5 * (j % 2)) / k
            v = (j * SQRT3 / 2) / k
            points.append(_barycentric_to_cartesian(u, v))
            if len(points) >= n:
                return points[:n]

    while len(points) < n:
        u = random.random()
        v = random.random() * (1 - u)
        points.append(_barycentric_to_cartesian(u, v))

    return points[:n]

def _perturb_point(p: Tuple[float, float], scale: float) -> Tuple[float, float]:
    for _ in range(10):
        dx = random.uniform(-scale, scale)
        dy = random.uniform(-scale, scale)
        new_p = (p[0] + dx, p[1] + dy)
        if _is_in_triangle(new_p):
            return new_p
    return p

def _optimize_points(points: List[Tuple[float, float]], iterations: int) -> List[Tuple[float, float]]:
    min_area = MinTriangleArea(points)
    best_points = points.copy()
    best_min = min_area.get_min_area()
    no_improve = 0

    for i in range(iterations):
        temp = max(0.01, 0.1 * (1 - i/iterations))
        scale = max(0.001, 0.05 * (1 - i/iterations))

        improved = False
        for j in range(len(points)):
            original_point = points[j]
            new_point = _perturb_point(original_point, scale)

            min_area.update_point(j, new_point)
            current_min = min_area.get_min_area()

            if current_min > best_min:
                best_min = current_min
                best_points = points.copy()
                improved = True
                no_improve = 0
            elif random.random() < math.exp((current_min - best_min)/temp):
                pass
            else:
                min_area.update_point(j, original_point)

        if not improved:
            no_improve += 1
            if no_improve > 50:
                break

    return best_points

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)

    best_points = []
    best_score = 0.0

    for _ in range(3):
        points = _generate_initial_points(11)
        points = _optimize_points(points, 1000)

        current_min_area = MinTriangleArea(points).get_min_area()
        if current_min_area > best_score:
            best_score = current_min_area
            best_points = points

    return [(round(x, 8), round(y, 8)) for x, y in best_points]

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    best = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

def _is_in_triangle(x: float, y: float) -> bool:
    if y < 0 or y > SQRT3/2:
        return False
    if x < 0 or x > 1:
        return False
    return y <= SQRT3 * (1 - abs(2*x - 1))

def _generate_valid_point() -> Tuple[float, float]:
    while True:
        x = random.uniform(0, 1)
        y_max = SQRT3 * (1 - abs(2*x - 1))
        y = random.uniform(0, y_max)
        if _is_in_triangle(x, y):
            return (x, y)

def _hexagonal_grid(n: int) -> np.ndarray:
    pts = []
    size = int(math.ceil(math.sqrt(n * 2)))
    for i in range(size):
        for j in range(size):
            if len(pts) >= n:
                break
            x = 0.5 + (i - j) * 0.5 / (size-1)
            y = j * SQRT3 / 2 / (size-1)
            if _is_in_triangle(x, y):
                pts.append([x, y])
    while len(pts) < n:
        x, y = _generate_valid_point()
        pts.append([x, y])
    return np.array(pts)

def _optimize_points(pts: np.ndarray, iterations: int = 2000) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)
    n = len(pts)

    for iter in range(iterations):
        new_pts = best_pts.copy()
        idx = random.randint(0, n-1)
        step = 0.1 * (1 - iter/iterations)

        # Generate new point within bounds
        while True:
            new_pt = best_pts[idx] + np.random.uniform(-step, step, 2)
            if _is_in_triangle(new_pt[0], new_pt[1]):
                new_pts[idx] = new_pt
                break

        new_area = _min_triangle_area(new_pts)
        if new_area > best_area:
            best_area = new_area
            best_pts = new_pts.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _hexagonal_grid(11)
    pts = _optimize_points(pts, 2000)

    # Final verification and correction
    for i in range(len(pts)):
        x, y = pts[i]
        if not _is_in_triangle(x, y):
            pts[i] = _generate_valid_point()

    return [(float(x), float(y)) for x, y in pts]

