import math
import random
import numpy as np

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    best = float("inf")
    n = len(pts)
    for i in range(n):
        for j in range(i+1, min(i+5, n)):
            for k in range(j+1, min(j+5, n)):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best < 0.01:
                        return best
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _initial_configuration(n_pts: int = 11) -> np.ndarray:
    pts = []
    # More uniform initial distribution
    for i in range(1, 5):
        for j in range(1, 5):
            if i + j <= 5:
                u = i/5
                v = j/5
                pts.append((1 - u - v) * _A + u * _B + v * _C)
    while len(pts) < n_pts:
        pts.append(_random_point())
    return np.array(pts[:n_pts])

def _anneal(n_pts: int = 11,
            iters: int = 5000,
            start_temp: float = 0.1,
            end_temp: float = 1e-8,
            seed: int | None = 0) -> np.ndarray:
    rng = random.Random(seed)
    pts = _initial_configuration(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        T = start_temp * (end_temp/start_temp) ** (t/iters)
        step_size = 0.08 * (1 - t/iters) + 0.02
        idx = rng.randrange(n_pts)
        trial = pts.copy()
        trial[idx] += rng.uniform(-step_size, step_size), rng.uniform(-step_size, step_size)
        trial[idx] = _project_to_simplex(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or rng.random() < math.exp(delta / max(T, 1e-12)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=5000, seed=seed)
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

import math
import random
import numpy as np
from typing import List, Tuple, Dict
from functools import lru_cache

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

@lru_cache(maxsize=100000)
def _cached_area(p1: Tuple[float, float], p2: Tuple[float, float], p3: Tuple[float, float]) -> float:
    p, q, r = np.array(p1), np.array(p2), np.array(p3)
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: List[Tuple[float, float]]) -> float:
    best = float("inf")
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _cached_area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best < 1e-6:
                        return best
    return best

def _hexagonal_grid(n: int) -> List[Tuple[float, float]]:
    pts = []
    k = math.ceil(math.sqrt(n * 2 / SQRT3))
    for i in range(k):
        for j in range(k):
            x = (i + 0.5 * (j % 2)) / (k - 0.5)
            y = j * SQRT3 / (2 * k)
            if x <= 1.0 and y <= SQRT3/2 and (1 - x) * SQRT3 >= y:
                pts.append((x, y))
    return random.sample(pts, min(n, len(pts)))

def _gradient_step(pts: List[Tuple[float, float]], step_size: float) -> List[Tuple[float, float]]:
    n = len(pts)
    grad = np.zeros((n, 2))
    min_area = float("inf")
    min_triplets = []

    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _cached_area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    min_triplets = [(i, j, k)]
                elif abs(a - min_area) < 1e-6:
                    min_triplets.append((i, j, k))

    for i, j, k in min_triplets:
        p, q, r = np.array(pts[i]), np.array(pts[j]), np.array(pts[k])
        normal = np.array([-(q[1] - p[1]), q[0] - p[0]])
        grad[i] += normal
        grad[j] += normal
        grad[k] += normal

    new_pts = []
    for idx in range(n):
        delta = grad[idx] / np.linalg.norm(grad[idx] + 1e-6) * step_size
        new_p = np.array(pts[idx]) + delta
        new_p = _project_to_simplex(new_p)
        new_pts.append(tuple(new_p))

    return new_pts

def _mutate_population(population: List[List[Tuple[float, float]]], mutation_rate: float) -> List[List[Tuple[float, float]]]:
    new_pop = []
    for ind in population:
        new_ind = []
        for p in ind:
            if random.random() < mutation_rate:
                new_p = np.array(p) + np.random.normal(0, 0.05, 2)
                new_p = _project_to_simplex(new_p)
                new_ind.append(tuple(new_p))
            else:
                new_ind.append(p)
        new_pop.append(new_ind)
    return new_pop

def _crossover(p1: List[Tuple[float, float]], p2: List[Tuple[float, float]]) -> List[Tuple[float, float]]:
    child = []
    for i in range(len(p1)):
        if random.random() < 0.5:
            child.append(p1[i])
        else:
            child.append(p2[i])
    return child

def _optimize_hybrid(initial_pts: List[Tuple[float, float]], time_limit: float) -> List[Tuple[float, float]]:
    start_time = time.time()
    best_pts = initial_pts
    best_val = _min_triangle_area(best_pts)

    # Genetic algorithm parameters
    pop_size = 20
    population = [initial_pts] * pop_size
    mutation_rate = 0.1

    while time.time() - start_time < time_limit * 0.7:
        # Genetic phase
        population = sorted(population, key=lambda x: -_min_triangle_area(x))
        new_pop = population[:pop_size//4]

        for _ in range(pop_size - len(new_pop)):
            p1, p2 = random.choices(population[:pop_size//2], k=2)
            child = _crossover(p1, p2)
            new_pop.append(child)

        population = _mutate_population(new_pop, mutation_rate)

        # Local search phase
        for i in range(len(population)):
            current = population[i]
            improved = _gradient_step(current, 0.01)
            if _min_triangle_area(improved) > _min_triangle_area(current):
                population[i] = improved

        # Update best
        current_best = max(population, key=lambda x: _min_triangle_area(x))
        current_val = _min_triangle_area(current_best)
        if current_val > best_val:
            best_val = current_val
            best_pts = current_best

    # Final gradient refinement
    for _ in range(100):
        improved = _gradient_step(best_pts, 0.001)
        if _min_triangle_area(improved) > best_val:
            best_pts = improved
            best_val = _min_triangle_area(improved)

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    # Generate initial hexagonal configuration
    pts = _hexagonal_grid(11)
    if len(pts) < 11:
        pts += [(random.random(), random.random() * SQRT3 / 2) for _ in range(11 - len(pts))]
        pts = [_project_to_simplex(np.array(p)) for p in pts]
        pts = [tuple(p) for p in pts]

    # Optimize with hybrid approach
    pts = _optimize_hybrid(pts, 25)  # Leave 5s buffer

    return pts

import math
import random
import numpy as np
from itertools import combinations

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p, q, r):
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / 2.0

def _min_triangle_area(pts):
    min_area = float('inf')
    for trio in combinations(pts, 3):
        a = _area(*trio)
        if a < min_area:
            min_area = a
            if min_area < 1e-8:
                return min_area
    return min_area

def _is_in_triangle(p):
    x, y = p
    if x < 0 or x > 1 or y < 0 or y > SQRT3/2:
        return False
    if y > SQRT3 * x:
        return False
    if y > SQRT3 * (1 - x):
        return False
    return True

def _generate_initial_points(n):
    # Optimized initial configuration for n=11
    base_points = [
        [0.0, 0.0], [1.0, 0.0], [0.5, SQRT3/2],  # vertices
        [0.25, SQRT3/4], [0.75, SQRT3/4],  # edge midpoints
        [0.5, 0.0], [0.25, 0.0], [0.75, 0.0],  # base points
        [0.125, SQRT3/8], [0.375, SQRT3/8],  # lower left
        [0.625, SQRT3/8], [0.875, SQRT3/8]   # lower right
    ]

    points = []
    for p in base_points[:n]:
        # Add small random perturbation
        x = p[0] + random.uniform(-0.02, 0.02)
        y = p[1] + random.uniform(-0.02, 0.02)
        if _is_in_triangle((x, y)):
            points.append([x, y])

    # Fill any remaining points if needed
    while len(points) < n:
        x = random.uniform(0.1, 0.9)
        y = random.uniform(0.1, 0.8*SQRT3/2)
        if _is_in_triangle((x, y)):
            points.append([x, y])
    return np.array(points)

def _optimize_points(points, iterations):
    best_points = points.copy()
    best_score = _min_triangle_area(best_points)

    for i in range(iterations):
        new_points = best_points.copy()

        # Non-linear cooling schedule
        progress = i / iterations
        cooling = np.exp(-5 * progress)  # exponential cooling

        # Focus on worst points every 10 iterations
        if i % 10 == 0:
            areas = []
            for j in range(len(points)):
                min_area = float('inf')
                for trio in combinations([p for k,p in enumerate(points) if k != j], 2):
                    a = _area(points[j], trio[0], trio[1])
                    if a < min_area:
                        min_area = a
                areas.append(min_area)
            worst_idx = np.argmin(areas)

            step = 0.03 * cooling
            new_points[worst_idx] += np.random.uniform(-step, step, 2)
            if not _is_in_triangle(new_points[worst_idx]):
                new_points[worst_idx] = best_points[worst_idx].copy()
        else:
            # Regular perturbation
            idx = i % len(points)
            step = 0.02 * cooling
            new_points[idx] += np.random.uniform(-step, step, 2)
            if not _is_in_triangle(new_points[idx]):
                new_points[idx] = best_points[idx].copy()

        new_score = _min_triangle_area(new_points)

        if new_score > best_score:
            best_score = new_score
            best_points = new_points.copy()

    return best_points

def find_points(seed=None):
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    points = _generate_initial_points(11)
    points = _optimize_points(points, 4000)

    return [(float(p[0]), float(p[1])) for p in points]

