    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            if min_area == 0:
                return 0
            p1 = pts[i]
            p2 = pts[j]
            for k in range(j+1, n):
                a = abs((p2[0]-p1[0])*(pts[k][1]-p1[1]) - (p2[1]-p1[1])*(pts[k][0]-p1[0])) * 0.5
                if a < min_area:
                    min_area = a
                    if min_area == 0:
