def _hexagonal_points(n: int) -> List[np.ndarray]:
    k = int(math.sqrt(n * 2 / SQRT3)) + 1
    points = []
    for i in range(k):
        for j in range(k):
            if i + j > k:
                continue
            x = (i + 0.5 * (j % 2)) / k
            y = (j * SQRT3 / 2) / k
            if y > SQRT3 * (1 - x) or y > SQRT3 * x:
                continue
            points.append(np.array([x, y]))
            if len(points) >= n:
                return points
    return points

def _optimize_points(pts: np.ndarray, max_iter: int = 500) -> np.ndarray:
    n = len(pts)
    best_pts = pts.copy()
    best_area = _min_triangle_area_fast(best_pts)

    for iter in range(max_iter):
        step = 0.01 * (1 - iter/max_iter)
        improved = False
        for i in range(n):
            for dx, dy in [(step,0), (-step,0), (0,step), (0,-step)]:
                new_pts = best_pts.copy()
                new_pts[i] += np.array([dx, dy])
                x, y = new_pts[i]
                if y < 0 or y > SQRT3/2 or x < 0 or x > 1 or y > SQRT3*(1 - abs(2*x - 1)):
                    continue

                area = _min_triangle_area_fast(new_pts)
                if area > best_area:
                    best_area = area
                    best_pts = new_pts.copy()
                    improved = True
        if not improved and step < 0.001:
            break
    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)

    pts = np.array(_hexagonal_points(11))

    for _ in range(10):
        candidate = np.array([_random_point() for _ in range(11)])
        candidate_area = _min_triangle_area_fast(candidate)
        if candidate_area > _min_triangle_area_fast(pts):
            pts = candidate

    pts = _optimize_points(pts)

    return [(float(x), float(y)) for x, y in pts]

from __future__ import annotations

import math
import random
import itertools
from typing import List, Tuple
import time
import numpy as np
try:
    from scipy.optimize import minimize, differential_evolution
    from scipy.spatial import KDTree
except ImportError:
    minimize = None
    differential_evolution = None

SQRT3 = math.sqrt(3.0)
start_time = time.time()

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area_fast(pts: np.ndarray) -> float:
    tree = KDTree(pts)
    best = float('inf')
    n = len(pts)
    for i in range(n):
        neighbors = tree.query_ball_point(pts[i], 0.2)
        for j in neighbors:
            if j <= i:
                continue
            for k in neighbors:
                if k <= j:
                    continue
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _structured_points(n: int) -> np.ndarray:
    pts = []
    layers = int(math.sqrt(n)) + 1
    for i in range(layers):
        for j in range(layers - i):
            u = i / layers
            v = j / layers
            if u + v <= 1.0:
                pts.append((1 - u - v) * _A + u * _B + v * _C)
    if len(pts) < n:
        pts.extend([_project_to_simplex(_A + (random.random(), random.random() * SQRT3)) for _ in range(n - len(pts))])
    return np.array(pts[:n])

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    w = 1.0 - u - v
    if u >= 0 and v >= 0 and w >= 0:
        return p
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _optimize_global(n_pts: int) -> np.ndarray:
    if differential_evolution is None or time.time() - start_time > 20:
        return _structured_points(n_pts)

    bounds = [(0, 1), (0, SQRT3/2)] * n_pts

    def f(x: np.ndarray) -> float:
        P = x.reshape((-1, 2))
        if not np.all(np.isfinite(P)):
            return float('inf')
        return -_min_triangle_area_fast(P)

    result = differential_evolution(
        f,
        bounds,
        strategy='best1bin',
        maxiter=100,
        popsize=15,
        tol=1e-6,
        polish=False,
        seed=0
    )

    if result.success and np.all(np.isfinite(result.x)):
        pts = result.x.reshape((n_pts, 2))
        for i in range(n_pts):
            pts[i] = _project_to_simplex(pts[i])
        return pts
    return _structured_points(n_pts)

def _local_polish(pts: np.ndarray) -> np.ndarray:
    if minimize is None or time.time() - start_time > 28:
        return pts
    n_pts = len(pts)
    x0 = pts.ravel()

    def f(x: np.ndarray) -> float:
        P = x.reshape((-1, 2))
        if not np.all(np.isfinite(P)):
            return float('inf')
        return -_min_triangle_area_fast(P)

    bounds = [(0, 1), (0, SQRT3/2)] * n_pts
    res = minimize(
        f,
        x0,
        method="L-BFGS-B",
        bounds=bounds,
        options=dict(maxiter=500)
    )

    if res is not None and res.success and np.all(np.isfinite(res.x)):
        out = res.x.reshape((n_pts, 2))
        for i in range(n_pts):
            out[i] = _project_to_simplex(out[i])
        return out
    return pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)
    pts = _optimize_global(11)
    pts = _local_polish(pts)
    if time.time() - start_time < 28:
        pts = _local_polish(pts)
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

