import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    u, v = random.random(), random.random()
    if u + v > 1.0:
        u, v = 1 - u, 1 - v
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = 1 - u, 1 - v
    return (1 - u - v) * _A + u * _B + v * _C

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')

    for i in range(n):
        for j in range(i+1, min(i+20, n)):
            for k in range(j+1, min(j+20, n)):
                p, q, r = pts[i], pts[j], pts[k]
                area = abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0.0
    return min_area

def _get_smallest_triangles(pts: np.ndarray, k: int = 15) -> List[int]:
    n = len(pts)
    areas = []

    for i in range(n):
        for j in range(i+1, min(i+20, n)):
            for k in range(j+1, min(j+20, n)):
                p, q, r = pts[i], pts[j], pts[k]
                area = abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5
                areas.append((area, i, j, k))

    areas.sort()
    involved = set()
    for _, i, j, k in areas[:k]:
        involved.update([i, j, k])
    return list(involved)

def _anneal(n_pts: int = 11,
            iters: int = 50000,
            start_temp: float = 0.8,
            end_temp: float = 1e-16,
            seed: int | None = 0) -> np.ndarray:

    random.seed(seed)
    pts = []
    # Improved initial placement
    for i in range(n_pts):
        if i == 0:
            pts.append(np.array([0.5, SQRT3/3]))
        elif i == 1:
            pts.append(np.array([0.25, SQRT3/12]))
        elif i == 2:
            pts.append(np.array([0.75, SQRT3/12]))
        elif i == 3:
            pts.append(np.array([0.125, SQRT3/6]))
        elif i == 4:
            pts.append(np.array([0.875, SQRT3/6]))
        elif i == 5:
            pts.append(np.array([0.375, SQRT3/4]))
        elif i == 6:
            pts.append(np.array([0.625, SQRT3/4]))
        else:
            pts.append(_random_point())
    pts = np.array(pts)

    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        T = start_temp * math.exp(math.log(end_temp/start_temp) * (t/iters)**0.7)

        step_size = 0.06 * math.exp(-2.5 * t/iters) + 0.001

        if t % 5 == 0 or best_val < 0.01:
            critical_points = _get_smallest_triangles(pts)
        else:
            critical_points = list(range(n_pts))

        idx = random.choice(critical_points)
        trial = pts.copy()
        trial[idx] += random.uniform(-step_size, step_size), random.uniform(-step_size, step_size)
        trial[idx] = _project_to_simplex(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or random.random() < math.exp(delta / max(T, 1e-16)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=50000, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

