def _get_smallest_triangles(pts: np.ndarray, k: int = 5) -> List[Tuple[int, int, int, float]]:
    n = len(pts)
    heap = []

    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                p, q, r = pts[i], pts[j], pts[k]
                area = abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5
                if len(heap) < k or area < -heap[0][0]:
                    if len(heap) == k:
                        heapq.heappop(heap)
                    heapq.heappush(heap, (-area, i, j, k))

