def _anneal(n_pts: int = 11,
            iters: int = 30000,
            start_temp: float = 0.8,
            end_temp: float = 1e-10,
            seed: int | None = 0) -> np.ndarray:

    random.seed(seed)
    pts = np.array([_random_point() for _ in range(n_pts)])
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    step_size = 0.05
    accept_rate = 0.0

    for t in range(iters):
        T = start_temp * math.exp(-4.0 * t / iters)

        if t % 20 == 0:
            step_size *= 0.8 if accept_rate < 0.4 else 1.1
            step_size = min(0.1, max(0.001, step_size))
            accept_rate = 0.0

        small_triangles = _get_smallest_triangles(pts, k=3)
        if not small_triangles:
            continue

        idx = random.choice(list({t[1] for t in small_triangles} | {t[2] for t in small_triangles} | {t[3] for t in small_triangles}))
        trial = pts.copy()

        if random.random() < 0.15:
            trial[idx] = _random_point()
        else:
            grad = np.zeros(2)
            for area, i, j, k in small_triangles:
                if idx in {i, j, k}:
                    p, q, r = pts[i], pts[j], pts[k]
                    weight = 1.0 / (area**2 + 1e-6)
                    dx = (q[1]-r[1]) * 0.5 * weight
                    dy = (r[0]-q[0]) * 0.5 * weight
                    if idx == i:
                        grad += np.array([dx, dy])
                    elif idx == j:
                        grad += np.array([(r[1]-p[1]) * 0.5 * weight, (p[0]-r[0]) * 0.5 * weight])
                    else:
                        grad += np.array([(p[1]-q[1]) * 0.5 * weight, (q[0]-p[0]) * 0.5 * weight])

            if np.linalg.norm(grad) > 0:
                grad = grad / np.linalg.norm(grad)
                trial[idx] += grad * random.uniform(0, step_size * 1.5)
            else:
                trial[idx] += np.random.uniform(-step_size, step_size, 2)

            trial[idx] = _project_to_simplex(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or random.random() < math.exp(delta / max(T, 1e-12)):
            pts = trial
            accept_rate += 1.0 / 20
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=35000, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

from __future__ import annotations

import math
import random
import itertools
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p, q, r) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5 / TRIANGLE_AREA

class MinTriangleArea:
    def __init__(self, n_points):
        self.comb = list(itertools.combinations(range(n_points), 3))

    def __call__(self, pts: np.ndarray) -> float:
        best = float("inf")
        for tri in self.comb:
            i, j, k = tri
            a = _area(pts[i], pts[j], pts[k])
            if a < best:
                best = a
                if best == 0:
                    return 0
        return best

def _initial_configuration(n: int) -> np.ndarray:
    pts = []
    layers = 3
    for i in range(layers):
        for j in range(layers):
            x = 0.2 + 0.6 * j / (layers - 1)
            y = 0.2 + 0.5 * i / (layers - 1)
            if y <= SQRT3 * x and y <= SQRT3 * (1 - x):
                pts.append([x, y])
    while len(pts) < n:
        x = random.uniform(0.2, 0.8)
        y = random.uniform(0.2, 0.7)
        if y <= SQRT3 * x and y <= SQRT3 * (1 - x):
            pts.append([x, y])
    return np.array(pts[:n])

def _optimize_points(pts: np.ndarray, steps: int, min_area_func) -> np.ndarray:
    best_pts = pts.copy()
    best_val = min_area_func(best_pts)
    n = len(pts)

    for step in range(steps):
        temp = max(0.01, 1.0 - step / steps)
        step_size = 0.02 * temp

        critical = set()
        for tri in min_area_func.comb:
            i, j, k = tri
            if _area(best_pts[i], best_pts[j], best_pts[k]) < best_val * 1.5:
                critical.update([i, j, k])

        for i in critical:
            angle = random.uniform(0, 2*math.pi)
            dx = step_size * math.cos(angle)
            dy = step_size * math.sin(angle)
            trial = best_pts.copy()
            trial[i] += dx, dy

            x, y = trial[i]
            if y < 0 or y > SQRT3 * x or y > SQRT3 * (1 - x):
                continue

            val = min_area_func(trial)
            if val > best_val or random.random() < math.exp(5*(val - best_val)/temp):
                best_val = val
                best_pts = trial.copy()

    return best_pts

def _refine_points(pts: np.ndarray, steps: int, min_area_func) -> np.ndarray:
    best_pts = pts.copy()
    best_val = min_area_func(best_pts)
    n = len(pts)

    for step in range(steps):
        step_size = 0.01 * (1 - step/steps)**2

        critical = set()
        for tri in min_area_func.comb:
            i, j, k = tri
            if _area(best_pts[i], best_pts[j], best_pts[k]) < best_val * 1.2:
                critical.update([i, j, k])

        for i in critical:
            trial = best_pts.copy()
            dx = random.uniform(-step_size, step_size)
            dy = random.uniform(-step_size, step_size)
            trial[i] += dx, dy

            x, y = trial[i]
            if y < 0 or y > SQRT3 * x or y > SQRT3 * (1 - x):
                continue

            val = min_area_func(trial)
            if val > best_val:
                best_val = val
                best_pts = trial.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    min_area_func = MinTriangleArea(11)
    pts = _initial_configuration(11)
    pts = _optimize_points(pts, 5000, min_area_func)
    pts = _refine_points(pts, 5000, min_area_func)

    return [(float(x), float(y)) for x, y in pts]

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4

def _is_in_triangle(x: float, y: float) -> bool:
    return (y >= 0) and (y <= SQRT3 * (1 - abs(2*x - 1)))

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                p1, p2, p3 = pts[i], pts[j], pts[k]
                area = abs((p2[0]-p1[0])*(p3[1]-p1[1]) - (p2[1]-p1[1])*(p3[0]-p1[0])) / (2 * TRIANGLE_AREA)
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0
    return min_area

def _initialize_points(n: int) -> np.ndarray:
    pts = []
    while len(pts) < n:
        x = random.uniform(0, 1)
        y_max = SQRT3 * (1 - abs(2*x - 1))
        y = random.uniform(0, y_max)
        pts.append([x, y])
    return np.array(pts)

def _optimize_points(pts: np.ndarray, iterations: int = 1000) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)
    n = len(pts)

    for _ in range(iterations):
        temp = 1.0 - _ / iterations
        step_size = 0.1 * temp

        for idx in range(n):
            for _ in range(5):  # Try multiple moves per point
                while True:
                    dx = random.uniform(-step_size, step_size)
                    dy = random.uniform(-step_size, step_size)
                    new_x = best_pts[idx][0] + dx
                    new_y = best_pts[idx][1] + dy
                    if _is_in_triangle(new_x, new_y):
                        break

                new_pts = best_pts.copy()
                new_pts[idx] = [new_x, new_y]
                new_area = _min_triangle_area(new_pts)

                if new_area > best_area:
                    best_area = new_area
                    best_pts = new_pts.copy()

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _initialize_points(11)
    pts = _optimize_points(pts, 500)

    # Final verification and adjustment
    for i in range(len(pts)):
        x, y = pts[i]
        if not _is_in_triangle(x, y):
            y = min(y, SQRT3*(1 - abs(2*x - 1)))
            y = max(y, 0)
            pts[i] = [x, y]

    return [(float(x), float(y)) for x, y in pts]

