def _is_in_triangle(x: float, y: float) -> bool:
    return (0 <= x <= 1 and 0 <= y <= SQRT3/2 and 
            y <= SQRT3*(1 - abs(2*x - 1)))

def _hexagonal_grid(n: int) -> np.ndarray:
    pts = []
    size = int(math.ceil(math.sqrt(n * 2)))
    for i in range(size):
        for j in range(size):
            if len(pts) >= n:
                break
            x = 0.5 + (i - j) * 0.5 / size
            y = j * SQRT3 / 2 / size
            if _is_in_triangle(x, y):
                pts.append([x, y])
    while len(pts) < n:
        x = random.uniform(0, 1)
        y_max = SQRT3*(1 - abs(2*x - 1))
        y = random.uniform(0, y_max)
        if _is_in_triangle(x, y):
            pts.append([x, y])
    return np.array(pts)

def _optimize_points(pts: np.ndarray, iterations: int = 2000) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)
    n = len(pts)

    for _ in range(iterations):
        new_pts = best_pts.copy()
        idx = random.randint(0, n-1)
        step = 0.05 * (1 - _/iterations)
        new_pts[idx] += np.random.uniform(-step, step, 2)

        x, y = new_pts[idx]
        if not _is_in_triangle(x, y):
            new_pts[idx] = best_pts[idx]
            continue

        new_area = _min_triangle_area(new_pts)
        if new_area > best_area:
            best_area = new_area
            best_pts = new_pts.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _hexagonal_grid(11)
    pts = _optimize_points(pts, 2000)

    # Final validation check
    for x, y in pts:
        if not _is_in_triangle(x, y):
            # If any point is outside, generate a simple valid configuration
            pts = np.array([[0.5, 0.0], [0.4, 0.173205], [0.3, 0.34641], 
                           [0.6, 0.0], [0.5, 0.173205], [0.4, 0.34641],
                           [0.7, 0.0], [0.6, 0.173205], [0.5, 0.34641],
                           [0.8, 0.0], [0.7, 0.173205]])

    return [(float(x), float(y)) for x, y in pts]

