import math
import random
import itertools
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _is_in_triangle(x: float, y: float) -> bool:
    return (y >= 0 and y <= SQRT3 * x and y <= SQRT3 * (1 - x))

def _area(p, q, r) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5 / TRIANGLE_AREA

class MinTriangleArea:
    def __init__(self, n_points):
        self.comb = list(itertools.combinations(range(n_points), 3))
        self.point_cache = {}

    def __call__(self, pts: np.ndarray) -> float:
        best = float("inf")
        for tri in self.comb:
            i, j, k = tri
            a = _area(pts[i], pts[j], pts[k])
            if a < best:
                best = a
                if best < 0.01:
                    return best
        return best

def _initial_configuration(n: int) -> np.ndarray:
    points = []
    layers = 3
    for i in range(layers):
        for j in range(layers):
            if i + j < layers:
                x = 0.1 + 0.4 * j
                y = 0.1 + 0.4 * i * SQRT3/2
                points.append([x, y])
                if i > 0 and j > 0:
                    points.append([1-x, y])
                    points.append([0.5 + (x-0.5)/2, SQRT3 - y])

    points.extend([[0.1, 0], [0.9, 0], [0.5, SQRT3-0.1]])
    return np.array(points[:n])

def _optimize_points(pts: np.ndarray, steps: int, min_area_func) -> np.ndarray:
    best_pts = pts.copy()
    best_val = min_area_func(best_pts)
    n = len(pts)

    for step in range(steps):
        temp = max(0.001, 1.0 - (step/steps)**0.33)
        step_size = 0.01 * temp

        for i in range(n):
            for _ in range(10):  # Try multiple perturbations
                trial = best_pts.copy()
                dx = random.uniform(-step_size, step_size)
                dy = random.uniform(-step_size, step_size)
                x, y = trial[i][0] + dx, trial[i][1] + dy

                if _is_in_triangle(x, y):
                    trial[i] = x, y
                    val = min_area_func(trial)
                    if val > best_val or (random.random() < math.exp(100*(val - best_val)/temp)):
                        best_val = val
                        best_pts = trial.copy()
                        break

    return best_pts

def _refine_points(pts: np.ndarray, steps: int, min_area_func) -> np.ndarray:
    best_pts = pts.copy()
    best_val = min_area_func(best_pts)
    n = len(pts)

    for step in range(steps):
        step_size = 0.005 * (1 - step/steps)**2

        worst_tris = []
        for tri in min_area_func.comb:
            i, j, k = tri
            a = _area(best_pts[i], best_pts[j], best_pts[k])
            if a < best_val * 1.2:
                worst_tris.append((i, j, k, a))

        if not worst_tris:
            continue

        worst_tris.sort(key=lambda x: x[3])
        critical = set()
        for tri in worst_tris[:10]:
            critical.update(tri[:3])

        for i in critical:
            for _ in range(10):  # Try multiple perturbations
                trial = best_pts.copy()
                dx = random.gauss(0, step_size)
                dy = random.gauss(0, step_size)
                x, y = trial[i][0] + dx, trial[i][1] + dy

                if _is_in_triangle(x, y):
                    trial[i] = x, y
                    val = min_area_func(trial)
                    if val > best_val:
                        best_val = val
                        best_pts = trial.copy()
                        break

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    min_area_func = MinTriangleArea(11)
    pts = _initial_configuration(11)
    pts = _optimize_points(pts, 15000, min_area_func)
    pts = _refine_points(pts, 5000, min_area_func)

    return [(float(x), float(y)) for x, y in pts]

import math
import random
import numpy as np
from itertools import combinations

SQRT3 = math.sqrt(3.0)

def _area(p, q, r):
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts):
    min_area = float('inf')
    for trio in combinations(pts, 3):
        a = _area(*trio)
        if a < min_area:
            min_area = a
            if min_area == 0:
                return 0
    return min_area

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point():
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p):
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv[0], uv[1]
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _hexagonal_grid(n):
    pts = []
    k = int(math.sqrt(n)) + 1
    for i in range(k):
        for j in range(k):
            if len(pts) >= n:
                break
            x = (i + 0.5 * (j % 2)) / (k - 0.5)
            y = (j * SQRT3 / 2) / (k - 0.5)
            if x + y/SQRT3 <= 1.0 and y <= SQRT3/2:
                pts.append(np.array([x, y]))
    return pts[:n]

def _optimize(pts, max_iter=1000, temp=0.1, cooling_rate=0.99):
    best_pts = np.array(pts)
    best_val = _min_triangle_area(best_pts)

    for _ in range(max_iter):
        temp *= cooling_rate
        idx = random.randrange(len(pts))
        step = temp * np.random.uniform(-1, 1, 2)
        new_pts = best_pts.copy()
        new_pts[idx] += step
        new_pts[idx] = _project_to_simplex(new_pts[idx])

        new_val = _min_triangle_area(new_pts)
        if new_val > best_val or random.random() < math.exp((new_val - best_val)/temp):
            best_pts = new_pts.copy()
            best_val = new_val

    return best_pts, best_val

def find_points(seed=None):
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    best_val = 0
    best_pts = []

    for _ in range(5):
        if random.random() < 0.7:
            pts = _hexagonal_grid(11)
        else:
            pts = [_random_point() for _ in range(11)]

        pts, val = _optimize(np.array(pts), max_iter=1000)

        if val > best_val:
            best_val = val
            best_pts = pts

    return [(float(x), float(y)) for x, y in best_pts]

