import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    u, v = random.random(), random.random()
    if u + v > 1.0:
        u, v = 1 - u, 1 - v
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = 1 - u, 1 - v
    return (1 - u - v) * _A + u * _B + v * _C

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    if n < 3:
        return 0.0
    min_area = float('inf')

    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = pts[j] - pts[i]
                b = pts[k] - pts[i]
                cross = abs(a[0]*b[1] - a[1]*b[0])
                if cross < min_area:
                    min_area = cross
                    if min_area == 0:
                        return 0.0
    return min_area * 0.5

def _initialize_points(n_pts: int) -> np.ndarray:
    # Use a hexagonal lattice as initial configuration
    pts = []
    k = int(math.ceil(math.sqrt(n_pts)))
    for i in range(k):
        for j in range(k):
            if len(pts) >= n_pts:
                break
            x = 0.5 * (i + (j % 2) * 0.5) / k
            y = j * SQRT3 / (2 * k)
            if x + y / SQRT3 <= 1.0 and y <= SQRT3 / 2.0:
                pts.append(np.array([x, y]))
    while len(pts) < n_pts:
        pts.append(_random_point())
    return np.array(pts)

def _optimize(pts: np.ndarray, iters: int, step_size: float) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        idx = random.randrange(len(pts))
        trial = pts.copy()
        perturbation = random.uniform(-step_size, step_size), random.uniform(-step_size, step_size)
        trial[idx] += perturbation
        trial[idx] = _project_to_simplex(trial[idx])

        trial_val = _min_triangle_area(trial)
        if trial_val > best_val:
            best_val = trial_val
            best_pts = trial.copy()
            pts = trial.copy()
        else:
            if random.random() < 0.1:
                pts = trial.copy()

    return best_pts

def _local_search(pts: np.ndarray, iters: int, step_size: float) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        improved = False
        for idx in range(len(pts)):
            for angle in np.linspace(0, 2*np.pi, 8):
                dx, dy = step_size * math.cos(angle), step_size * math.sin(angle)
                trial = best_pts.copy()
                trial[idx] += dx, dy
                trial[idx] = _project_to_simplex(trial[idx])
                trial_val = _min_triangle_area(trial)
                if trial_val > best_val:
                    best_val = trial_val
                    best_pts = trial.copy()
                    improved = True
        if not improved:
            break
    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    pts = _initialize_points(11)
    pts = _optimize(pts, 5000, 0.05)
    pts = _local_search(pts, 1000, 0.02)
    pts = _optimize(pts, 5000, 0.02)
    pts = _local_search(pts, 1000, 0.01)
    return [(float(x), float(y)) for x, y in pts]

