import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    best = float("inf")
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = 1 - v, 1 - u
    return (1 - u - v) * _A + u * _B + v * _C

def _initial_configuration(n_pts: int = 11) -> np.ndarray:
    pts = []
    k = int(math.sqrt(n_pts)) + 1
    for i in range(k):
        for j in range(k):
            if len(pts) >= n_pts - 1:
                break
            x = (i + 0.5 * (j % 2)) / (k - 0.5)
            y = (j * SQRT3 / 2) / (k - 0.5)
            if x + y / SQRT3 <= 1.0 and y <= SQRT3 / 2:
                pts.append(np.array([x, y]))
    pts.append(np.array([0.5, SQRT3/4]))
    return np.array(pts[:n_pts])

def _adaptive_anneal(n_pts: int = 11, iters: int = 4000, seed: int | None = 0) -> np.ndarray:
    rng = random.Random(seed)
    pts = _initial_configuration(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        T = 0.2 * (0.001 / 0.2) ** (t / max(iters - 1, 1))
        idx = rng.randrange(n_pts)
        trial = pts.copy()
        step = 0.02 * (1 - t/iters)
        trial[idx] += rng.uniform(-step, step), rng.uniform(-step, step)
        trial[idx] = _project_to_simplex(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or rng.random() < math.exp(delta / max(T, 1e-12)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

        if t % 500 == 0 and t > 0:
            pts = best_pts.copy()
            for i in range(n_pts):
                pts[i] += rng.uniform(-0.01, 0.01), rng.uniform(-0.01, 0.01)
                pts[i] = _project_to_simplex(pts[i])

    return best_pts

def _gradient_perturb(pts: np.ndarray, steps: int = 300) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    n_pts = len(pts)

    for _ in range(steps):
        idx = random.randrange(n_pts)
        trial = best_pts.copy()
        grad = np.zeros(2)

        min_areas = []
        for j in range(n_pts):
            if j == idx:
                continue
            for k in range(j+1, n_pts):
                if k == idx:
                    continue
                p, q, r = best_pts[idx], best_pts[j], best_pts[k]
                area = _area(p, q, r)
                min_areas.append(area)
                if abs(area - best_val) < 1e-6:
                    normal = np.array([q[1] - r[1], r[0] - q[0]])
                    grad += normal / np.linalg.norm(normal)

        if np.linalg.norm(grad) > 0:
            grad = grad / np.linalg.norm(grad)
            trial[idx] += 0.002 * grad
        else:
            trial[idx] += random.uniform(-0.001, 0.001), random.uniform(-0.001, 0.001)

        trial[idx] = _project_to_simplex(trial[idx])
        trial_val = _min_triangle_area(trial)
        if trial_val > best_val:
            best_val = trial_val
            best_pts = trial.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _adaptive_anneal(n_pts=11, iters=4000, seed=seed)
    pts = _gradient_perturb(pts, steps=300)
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4

def _point_in_triangle(x: float, y: float) -> bool:
    if y < 0 or y > SQRT3/2:
        return False
    if x < 0 or x > 1:
        return False
    return y <= SQRT3 * (1 - abs(2*x - 1))

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n-2):
        for j in range(i+1, n-1):
            p = pts[i]
            q = pts[j]
            dx1 = q[0] - p[0]
            dy1 = q[1] - p[1]
            for k in range(j+1, n):
                r = pts[k]
                area = abs(dx1 * (r[1] - p[1]) - (r[0] - p[0]) * dy1) * 0.5
                if area < min_area:
                    min_area = area
                    if min_area == 0:
                        return 0
    return min_area

def _generate_initial_points(n: int) -> np.ndarray:
    pts = []
    layers = 5
    for layer in range(1, layers+1):
        for i in range(layer):
            x = 0.5 + (i - layer/2 + 0.5) / (2*layers)
            y = (layer - 1) * SQRT3 / (2*layers)
            if _point_in_triangle(x, y):
                pts.append([x, y])

    while len(pts) < n:
        x = random.uniform(0.01, 0.99)
        y = random.uniform(0.01, SQRT3/2 - 0.01)
        if _point_in_triangle(x, y):
            pts.append([x, y])

    return np.array(pts[:n])

def _optimize_points(pts: np.ndarray, iterations: int = 4000) -> np.ndarray:
    best_pts = pts.copy()
    best_area = _min_triangle_area(best_pts)
    n = len(pts)
    temp = 0.1

    for iter in range(iterations):
        temp = 0.1 * (1 - iter/iterations)
        new_pts = best_pts.copy()

        for _ in range(5):
            idx = random.randint(0, n-1)
            step = temp * random.random()
            angle = random.uniform(0, 2*math.pi)
            dx = step * math.cos(angle)
            dy = step * math.sin(angle)

            x = new_pts[idx][0] + dx
            y = new_pts[idx][1] + dy

            if _point_in_triangle(x, y):
                new_pts[idx] = [x, y]

        new_area = _min_triangle_area(new_pts)
        if new_area > best_area or (random.random() < math.exp((new_area - best_area)/temp) and new_area > 0):
            best_area = new_area
            best_pts = new_pts.copy()

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _generate_initial_points(11)
    pts = _optimize_points(pts, 4000)

    # Final validation and correction
    valid_pts = []
    for x, y in pts:
        if not _point_in_triangle(x, y):
            # Generate new point inside triangle
            while True:
                x = random.uniform(0.01, 0.99)
                y = random.uniform(0.01, SQRT3/2 - 0.01)
                if _point_in_triangle(x, y):
                    break
        valid_pts.append([x, y])

    return [(float(x), float(y)) for x, y in valid_pts[:11]]

