TRIANGLE_AREA = SQRT3 / 4.0

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5 / TRIANGLE_AREA

def _min_triangle_area(pts: np.ndarray) -> float:
    min_area = float('inf')
    n = len(pts)
    for i in range(n):
        for j in range(i+1, n):
            vec_ij = pts[j] - pts[i]
            for k in range(j+1, n):
                vec_ik = pts[k] - pts[i]
                a = abs(np.cross(vec_ij, vec_ik)) * 0.5 / TRIANGLE_AREA
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0
    return min_area

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _is_in_triangle(p: np.ndarray) -> bool:
    def sign(a: np.ndarray, b: np.ndarray, c: np.ndarray) -> float:
        return (a[0] - c[0])*(b[1] - c[1]) - (b[0] - c[0])*(a[1] - c[1])
    d1 = sign(p, _A, _B)
    d2 = sign(p, _B, _C)
    d3 = sign(p, _C, _A)
    has_neg = (d1 < 0) or (d2 < 0) or (d3 < 0)
    has_pos = (d1 > 0) or (d2 > 0) or (d3 > 0)
    return not (has_neg and has_pos)

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _generate_hexagonal_points(n: int) -> np.ndarray:
    points = [_A, _B, _C]
    layers = 3

    for layer in range(1, layers+1):
        step = 1.0 / (layers + 1)
        for i in range(layer + 1):
            for j in range(layer + 1):
                if i + j > layer:
                    continue
                u = i * step
                v = j * step
                w = 1 - u - v
                if w < 0:
                    continue
                p = u * _A + v * _B + w * _C
                if _is_in_triangle(p) and not any(np.allclose(p, pt) for pt in points):
                    points.append(p)

    while len(points) < n:
        p = np.random.uniform(0, 1, 2)
        if p[1] > SQRT3 * min(p[0], 1 - p[0]):
            continue
        if _is_in_triangle(p) and not any(np.allclose(p, pt) for pt in points):
            points.append(p)

    return np.array(points[:n])

def _optimize_points(points: np.ndarray, iterations: int = 1000) -> np.ndarray:
    best_points = points.copy()
    best_score = _min_triangle_area(best_points)
    n = len(points)

    for iter in range(iterations):
        T = max(0.01, 1.0 - (iter / iterations))
        step = 0.1 * T

        # Global perturbation
        if iter % 10 == 0:
            new_points = points.copy()
            for i in range(n):
                perturbation = np.random.normal(0, step, 2)
                new_points[i] += perturbation
                new_points[i] = _project_to_triangle(new_points[i])

            new_score = _min_triangle_area(new_points)
            if new_score > best_score:
                best_score = new_score
                best_points = new_points.copy()
                points = new_points.copy()

        # Local perturbation
        for i in range(n):
            new_points = points.copy()
            perturbation = np.random.normal(0, step/10, 2)
            new_points[i] += perturbation
            new_points[i] = _project_to_triangle(new_points[i])

            new_score = _min_triangle_area(new_points)
            if new_score > best_score:
                best_score = new_score
                best_points = new_points.copy()
                points = new_points.copy()

    return best_points

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    initial_points = _generate_hexagonal_points(11)
    optimized_points = _optimize_points(initial_points, 2000)
    return [(float(p[0]), float(p[1])) for p in optimized_points]

from __future__ import annotations

import math
import random
import numpy as np
from scipy.optimize import minimize
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < min_area:
                    min_area = a
                    if min_area == 0:
                        return 0.0
    return min_area

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _is_inside_triangle(p: np.ndarray) -> bool:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    return u >= 0 and v >= 0 and (u + v) <= 1.0

def _initial_grid(n: int) -> np.ndarray:
    k = math.ceil(math.sqrt(n * 2))
    pts = []
    for i in range(k):
        for j in range(k - i):
            u = (i + 0.5) / k
            v = (j + 0.5) / k
            if u + v <= 1.0:
                pts.append((1 - u - v) * _A + u * _B + v * _C)
    while len(pts) < n:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            pts.append((1 - u - v) * _A + u * _B + v * _C)
    return np.array(pts[:n])

def _optimize_points(pts: np.ndarray, max_iter: int = 200) -> np.ndarray:
    n = len(pts)

    def objective(x):
        pts = x.reshape(-1, 2)
        return -_min_triangle_area(pts)

    bounds = [(0, 1), (0, SQRT3/2)] * n
    x0 = pts.flatten()

    res = minimize(objective, x0, method='L-BFGS-B', bounds=bounds, 
                  options={'maxiter': max_iter, 'ftol': 1e-8})

    optimized_pts = res.x.reshape(-1, 2)
    return np.array([_project_to_simplex(p) for p in optimized_pts])

def _perturb_points(pts: np.ndarray, scale: float = 0.01) -> np.ndarray:
    new_pts = pts.copy()
    for i in range(len(new_pts)):
        perturbation = np.random.uniform(-scale, scale, size=2)
        new_pts[i] = _project_to_simplex(new_pts[i] + perturbation)
    return new_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    best_pts = _initial_grid(11)
    best_score = _min_triangle_area(best_pts)

    for _ in range(5):
        pts = _optimize_points(best_pts.copy())
        pts = np.array([_project_to_simplex(p) for p in pts])  # Extra projection
        score = _min_triangle_area(pts)

        if score > best_score:
            best_score = score
            best_pts = pts.copy()

        pts = _perturb_points(best_pts, scale=0.005)  # Reduced scale
        score = _min_triangle_area(pts)

        if score > best_score:
            best_score = score
            best_pts = pts.copy()

    # Final validation
    for p in best_pts:
        if not _is_inside_triangle(p):
            p[:] = _project_to_simplex(p)

    return [(float(x), float(y)) for x, y in best_pts]

from __future__ import annotations

import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)
TRIANGLE_AREA = SQRT3 / 4.0

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs((q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])) / (2 * TRIANGLE_AREA)

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    min_area = float('inf')
    for i in range(n-2):
        for j in range(i+1, n-1):
            p0 = pts[j] - pts[i]
            for k in range(j+1, n):
                p1 = pts[k] - pts[i]
                area = abs(p0[0]*p1[1] - p0[1]*p1[0]) / (2 * TRIANGLE_AREA)
                if area < min_area:
                    min_area = area
                    if min_area < 1e-8:
                        return 0
    return min_area

def _random_point_in_triangle() -> np.ndarray:
    while True:
        r1 = random.random()
        r2 = random.random()
        if r1 + r2 <= 1:
            break
    x = r1 * 1.0 + r2 * 0.5
    y = r2 * SQRT3 / 2.0
    return np.array([x, y])

def _initialize_points(n_pts: int) -> np.ndarray:
    pts = []
    for _ in range(n_pts):
        pts.append(_random_point_in_triangle())
    return np.array(pts)

def _is_in_triangle(p: np.ndarray) -> bool:
    x, y = p
    if y < 0 or y > SQRT3/2:
        return False
    if x < 0 or x > 1:
        return False
    if y > SQRT3 * x or y > SQRT3 * (1 - x):
        return False
    return True

def _project_to_triangle(p: np.ndarray) -> np.ndarray:
    x, y = p
    if _is_in_triangle(p):
        return p

    if y < 0:
        x = max(0, min(1, x))
        return np.array([x, 0])

    if y > SQRT3 * x:
        if x < 0:
            return np.array([0, 0])
        x_proj = y / SQRT3
        return np.array([x_proj, y])

    if y > SQRT3 * (1 - x):
        if x > 1:
            return np.array([1, 0])
        x_proj = 1 - y / SQRT3
        return np.array([x_proj, y])

    d0 = x**2 + y**2
    d1 = (x-1)**2 + y**2
    d2 = (x-0.5)**2 + (y-SQRT3/2)**2

    if d0 <= d1 and d0 <= d2:
        return np.array([0, 0])
    elif d1 <= d0 and d1 <= d2:
        return np.array([1, 0])
    else:
        return np.array([0.5, SQRT3/2])

def _anneal(n_pts: int = 11,
            iters: int = 100000,
            start_temp: float = 0.5,
            end_temp: float = 1e-8,
            step_size: float = 0.1,
            seed: int | None = None) -> np.ndarray:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    pts = _initialize_points(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    no_improve = 0

    for t in range(iters):
        T = start_temp * (1 - (t/iters)**1.5)  # Faster initial cooling
        current_step = step_size * (1 - (t/iters)**0.8)  # More gradual step reduction

        trial = pts.copy()
        if t % 1000 == 0:  # Periodic full re-evaluation
            trial = _initialize_points(n_pts)
        elif random.random() < 0.15:  # Higher chance for multi-point perturbation
            for _ in range(1 + int(4*random.random())):
                idx = random.randrange(n_pts)
                delta = np.random.normal(0, current_step, size=2)
                trial[idx] = _project_to_triangle(trial[idx] + delta)
        else:
            idx = random.randrange(n_pts)
            if random.random() < 0.1:  # Higher chance for large jumps
                trial[idx] = _random_point_in_triangle()
            else:
                delta = np.random.normal(0, current_step, size=2)
                trial[idx] = _project_to_triangle(trial[idx] + delta)

        trial_val = _min_triangle_area(trial)
        delta_val = trial_val - best_val

        if delta_val > 0 or math.exp(delta_val / max(T, 1e-12)) > random.random():
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()
                no_improve = 0
            else:
                no_improve += 1

        if no_improve > 5000:  # Early termination
            break

    return best_pts

def find_points(seed: int | None = None) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, seed=seed)
    return [(float(x), float(y)) for x, y in pts]

from __future__ import annotations
import math
import random
import numpy as np
from typing import List, Tuple

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    best = float("inf")
    n = len(pts)
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _barycentric_to_cartesian(u: float, v: float) -> np.ndarray:
    w = 1 - u - v
    return w * _A + u * _B + v * _C

def _cartesian_to_barycentric(p: np.ndarray) -> Tuple[float, float]:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.solve(M, p - _A)
    return uv[0], uv[1]

def _initial_hexagonal_grid(n_pts: int = 11) -> np.ndarray:
    pts = []
    layers = 4
    for layer in range(layers):
        for i in range(layer + 1):
            j = layer - i
            if i <= layer and j <= layer:
                u = (i + 0.5 * (j % 1)) / (layers - 1)
                v = (j * SQRT3 / 2) / (layers - 1)
                if u + v <= 1.0:
                    pts.append(_barycentric_to_cartesian(u, v))

    # If we still need more points, add symmetric ones
    while len(pts) < n_pts:
        u = random.uniform(0.1, 0.9)
        v = random.uniform(0.1, 0.9) * (1 - u)
        pts.append(_barycentric_to_cartesian(u, v))

    return np.array(pts[:n_pts])

def _local_optimization(pts: np.ndarray, steps: int = 200) -> np.ndarray:
    current_pts = pts.copy()
    current_val = _min_triangle_area(current_pts)
    step_size = 0.02

    for _ in range(steps):
        improved = False
        for i in range(len(current_pts)):
            best_delta = None
            best_new_val = current_val

            for _ in range(20):
                delta = np.random.uniform(-step_size, step_size, size=2)
                new_pt = current_pts[i] + delta
                u, v = _cartesian_to_barycentric(new_pt)
                if u >= 0 and v >= 0 and (u + v) <= 1:
                    temp_pts = current_pts.copy()
                    temp_pts[i] = new_pt
                    new_val = _min_triangle_area(temp_pts)
                    if new_val > best_new_val:
                        best_new_val = new_val
                        best_delta = delta

            if best_delta is not None and best_new_val > current_val:
                current_pts[i] += best_delta
                current_val = best_new_val
                improved = True

        if not improved:
            step_size *= 0.9
        else:
            step_size = min(0.05, step_size * 1.1)

    return current_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)

    # Generate initial configuration
    pts = _initial_hexagonal_grid(11)

    # Local optimization
    optimized_pts = _local_optimization(pts)

    # Convert to list of tuples
    return [(float(x), float(y)) for x, y in optimized_pts]
